(263, 0, 0, '이 땅 곳곳에 언데드가 득실거리고 있는데 도대체 스톰윈드 군대는 어디에 있는 것인가?'),
(269, 0, 0, '그늘숲 의회는 조치를 취해야 합니다. 악의 세력이 퍼져 나가고 있습니다.'),
(269, 0, 1, '어둠골의 주민들은 의회가 좀 더 적극적인 조치를 취하기를 바라고 있습니다. 우리를 괴롭히는 이 부정한 침략에 그들이 고통받도록 내버려 둘 순 없습니다.'),
