(270, 0, 0, '스톰윈드에서 뭔가 조치를 취해줘야 하오. 우리의 터전이 언데드의 손아귀에 넘어가고 있소.'),
(271, 0, 0, '스톰윈드의 저 두꺼운 돌 성벽 너머에 있는 귀머거리들은 우리의 뜻을 듣지도 않는군요.'),
