(1268, 0, 0, '흠, 충분히 통할 것 같아요. 자신감을 갖고 좀 더 강하게 밀어붙여 보세요!'),
(1355, 0, 0, '세상에, 미끼가 먹혀들었군요! 그림누르는 정말 대단한 친구라니까. 아, 당신 꼬집힌 게 그다지 많이 아프진 않았으면 좋겠군요... 하지만 일단 가재고기를 맛보게 그럴 가치가 있다는 걸 알게 될 겁니다!'),
