(1402, 0, 3, '이건 모두 바보 같은 오크족 때문입죠. 내 농장을 모두 불태워 버리다니...'),
(1402, 0, 4, '앞 못 보는 이 불쌍한 자에게 동전 몇 닢만 적선해 줍쇼... 제가 눈이 멀지 않았다고요? 전 눈이 멀지 않았어요! 앞을 볼 수 있다고요!! 오, 기적이야!'),
(1402, 0, 5, '가난한 자에게 자비를 베풀어 주세요.'),
