(1416, 0, 0, '날 따라오시오, 성기사 양반. 드워프 스타우트 맥주를 마시듯 빠르게 마갑을 완성해 주겠소. 음... 스타우트 맥주가 갑자기 먹고 싶은데...'),
(1416, 1, 0, '성능에 만족할 것이오. 자, 오시오. 이제 가게로 돌아가서 거래를 마무리합시다!'),
