(1449, 0, 0, '모두 준비해라! 고릴라들이 몰려온다!'),
(1477, 0, 0, '다나스가 스톰윈드의 모든 용병을 모아 전투를 위해 네더가드로 진격해 갔던 때를 기억하나?'),
(1477, 0, 1, '난 대전쟁을 속속들이 다 겪었어. 우리가 다로우미어 호수에서 싸웠을 때가 생각나는군. 질퍽거리는 참호 속에서 밤을 꼬박 새웠었지.'),
(1477, 0, 2, '로데론의 그 여관에서 마시곤 했던 드워프 에일 맥주가 그리워. 자네, 거기서 시작된 우리의 전투를 기억하나?'),
(1477, 0, 3, '우리는 백 명이 안 되고 오크 놈들은 천 명이 넘었지. 우리 중 몇 명만이 그 전투에서 살아 돌아올 수 있었어.'),
(1477, 0, 4, '최고의 순간은 우리 군대가 자기 집 문 앞에까지 진격해 가자 사색이 된 페레놀드의 표정을 보았을 때였지. 정말 대단한 전투였어!'),
(1477, 0, 5, '그 황혼의 망치단 무리와 습지대에서 싸웠었는데... 정말 끔찍한 전투였지.'),
(1477, 0, 6, '아 그래, 이제 생각나는군. 자네 결혼식 날밤 말이지?'),
(1477, 0, 7, '아, 그 글러스트웰트 쌍둥이!'),
(1477, 1, 0, '그날 밤 입은 상처 자국이 아직 남아 있다고.'),
(1477, 1, 1, '그날 밤 두 다리가 모두 부러졌었는데 어떻게 잊을 수 있겠나?'),
(1477, 1, 2, '3주 후에 북녘골의 침대 위에서 깨어났지. 하나도 기억이 나질 않더라고.'),
(1477, 1, 3, '그날 밤에 내 반지를 주워서 자네 담배 주머니 안에 넣지 않았던가?'),
(1477, 1, 4, '내 등에 있는 상처가 아마 평생 그날 밤 일을 기억하게 할 걸세.'),
(1477, 1, 5, '물론 그날 밤은 기억하지. 조금만 왼쪽으로 비켜 맞았어도 자네는 지금쯤 그 엘프 모리스와 함께 뒤틀린 황천에서 술을 마시고 있을 거야. 참, 그리고 그건 내가 가장 좋아하는 셔츠였다고.'),
(1477, 1, 6, '자네가 그 정신 나간 묘기에 도전하다가 내가 복부에 크게 상처 입은 게 그때가 세 번째 아니면 네 번째였지, 아마?'),
(1477, 1, 7, '그래, 그날 밤 내 손을 가지고 사제들에게 돌아갈 수 있도록 해 준 건 고맙게 생각하네.'),
(1477, 2, 0, '헤헤, 소심하긴...'),
(1477, 2, 1, '그때 자넨 어린 여자 아이처럼 비명을 질러댔지. 지금까지 내가 본 것 중 가장 우스운 광경이었어, 하하.'),
(1477, 2, 2, '결국엔 다 잘 됐지.'),
(1477, 2, 3, '전투에서 입은 흉터를 비교하는 짓은 아예 시작도 하지 말자고, 친구.'),
(1477, 2, 4, '내 지금껏 살면서 그렇게 빨리 움직이는 친구는 본 적이 없어.'),
(1477, 2, 5, '자네와 같이 지내다 보면 그 파란만장한 삶에 끊임없이 놀라게 된다니까.'),
(1477, 2, 6, '뭐, 우리가 아직 이렇게 살아 있다는 것만으로도 축배를 들 만한 일이 아닌가?'),
(1477, 2, 7, '자네 삶을 아주 흥미진진하게 만들어 준 내게 항상 감사하라고.'),
(1478, 0, 0, '이봐 리즈, 크리스토프에게 한 잔 더 주게.'),
(1478, 1, 0, '따뜻한 선술집과 차가운 맥주라... 더 바랄 게 없지.'),
(1478, 2, 0, '다나스가 스톰윈드의 모든 용병을 모아 전투를 위해 네더가드로 진격해 갔던 때를 기억하나?'),
