(1478, 4, 6, '뭐, 우리가 아직 이렇게 살아 있다는 것만으로도 축배를 들 만한 일이 아닌가?'),
(1478, 4, 7, '자네 삶을 아주 흥미진진하게 만들어 준 내게 항상 감사하라고.'),
(1493, 0, 0, '크르르... 신선한 고기로군!'),
(1493, 0, 1, '스모츠! 이봐, 스모츠! 나와서 붙어 보자고!'),
(1493, 0, 2, '이 조각상하고만 노는 것도 지겨워졌다고. 나와서 붙어보잔 말이야!'),
(1493, 0, 3, '자네이로 섬으로 나와. 기다리고 있겠다, 스모츠.'),
(1493, 0, 4, '이번에는 네 동료를 죽이지 않겠다고 약속할게. 흐흐! 하지만 내 동생이 먹어 버릴지도 몰라!'),
(1493, 0, 5, '이제 보낼 배가 더는 없는 건가? 너의 그 가상한 용기는 다 어디 간 거야?'),
(1493, 0, 6, '크르르... 신선한 고기로군!'),
(1494, 0, 0, '흐음... 음식 냄새가 나는데!'),
(1497, 0, 0, '부름의 양초는 앞에 있는 상자에 있네, $n.'),
(1543, 0, 0, '지금 %s|1을;를; 포획하십시오!'),
(1544, 0, 0, '지금 %s|1을;를; 포획하십시오!'),
(1568, 0, 0, '어디 보자, 당신에게 딱 맞는 턱을 가진 시체가 여기 어딘가 있었는데...'),
(1568, 1, 0, '이거면 되겠군. 턱을 잃어버리면 다시 돌아오시오.'),
(1569, 0, 0, '아니, 이게 누군가!'),
(1571, 0, 0, '경비병!'),
(1572, 0, 0, '경비병!'),
(1573, 0, 0, '경비병!'),
(1696, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(1716, 0, 0, '스톰윈드 경비병들은 왜 아직 안 온 거지?'),
(1719, 0, 0, '갑자기 사방에서 놈들이 뛰쳐나오다니...'),
(1719, 0, 1, '누군가 놈들의 뒤에서 돕고 있는 게 분명해.'),
(1719, 0, 2, '위에서 아는 날엔 난 죽은 목숨이야.'),
(1754, 0, 0, '명상에 들어갈 시간이군. 방해하지 말도록.'),
(1754, 1, 0, '왔군. 그래, 서부 몰락지대에서 어떤 소식을 가져왔나?'),
(1754, 2, 0, '흠.. 참견하기 좋아하는 쇼가 아닐까 싶군. 내 나름대로 알아보지. 우선 가보게나. 곧 다시 연락하지.'),
(1754, 3, 0, '아, 친절에 감사드리오. 내가 잠시 볼 일을 볼 동안 도서관에서 기다려 주시겠소?'),
(1755, 0, 0, '밴클리프 님께서 계획을 진행 중이라고 알려 오셨습니다. 또 주위를 염탐하는 자가 있다는 소문을 들으셨다고 합니다.'),
(1755, 1, 0, '데피아즈단은 반드시 성공할 것이다! 떠돌이 녀석 따위가 감히 우리를 막으려고 하느냐!'),
(1756, 0, 0, '네, 알겠습니다!'),
(1756, 1, 0, '어서 들어가십시오. 경께서는 도서관에 기다리고 계십니다.'),
(1763, 0, 0, '저 부품들을 배로 옮겨라!'),
(1763, 0, 1, '쉬고 싶은 자가 있나? 아주 안됐군! 어서 일해, 이 멍청이들아!'),
(1776, 0, 0, '예...'),
(1802, 0, 0, '%s|1이;가; 격노합니다!'),
(1853, 0, 0, '수업이 시작됐다!'),
(1854, 0, 0, '환영하오, 친구들!'),
(1854, 1, 0, '맹세코 성스러운 빛에 의해 그대는 이 무덤을 떠나게 될 것이오!'),
(1931, 0, 0, '아아아... 속이... 안 좋아...'),
(1931, 1, 0, '아아아... 내 영혼... 내 살이... 썩어 들어가고 있어...!'),
(1951, 0, 0, '난 나아지고 있네. 포악한 이바르한테 지다니...'),
(1976, 0, 0, '칼날 맛 좀 봐라!'),
(1976, 0, 1, '제발 그 일만은 저지르지 않았다고 말해주세요! 그렇지 않다면 전 당신을 해칠 수밖에 없습니다.'),
(1976, 0, 2, '가만히 있지 말고 가서 놀 거리를 많이 만들어 주도록!'),
(1978, 0, 0, '밖에 있는 저 늑대들을 조심하면서 동료가 있는 곳으로 갑시다.'),
(1978, 1, 0, '조심하시오, $n. 저 늑대들은 나무 사이에 숨기를 좋아하오.'),
(1978, 2, 0, '$n의 공격이오!'),
(1978, 2, 1, '조심하시오! 공격 받고 있소!'),
(1978, 2, 2, '조심하시오! $n|1이;가; 우릴 노리고 있소!'),
(1978, 3, 0, '거의 다 온 것 같소!'),
(1978, 4, 0, '무사히 도착했구려. 고맙소, $n. 당신이 아니었다면 이곳까지 오지 못했을 거요.'),
(1978, 5, 0, '동쪽에 늑대 무리가 출몰하여 말덴의 과수원에 살던 이들이 모두 당했소.'),
(1978, 6, 0, '괜찮다면 퀸이 무사한지 좀 확인해 보고 싶은데...'),
(1978, 7, 0, '반갑네, 퀸. 어떻게 지내는가?'),
(1978, 8, 0, '몸조심하는 게 좋을 걸세, 퀸. 이번엔 운이 좋았던 거야.'),
(1981, 0, 0, '우리는 네놈의 폭발물이 필요하다. 너를 죽이고 감사한 마음으로 가져가 주지.'),
(2044, 0, 0, '지난 일에 집착하지 마라, $c|1이여;여;!'),
(2044, 0, 1, '어떤 $r|1이;가; 이미 지난 일에 간섭하는가? 너도 스탈반의 전설과 함께 잠재워 주마!'),
(2055, 0, 0, '내 보장하오, 감독관이여. 왕립 연금술 학회는 많은 이의 목숨을 앗은 그 비극적인 사태에 대해 진심으로 보상하고 싶어하오.'),
(2055, 1, 0, '문제를 일으킬 생각은 전혀 없소. 단지 평화롭게 연구를 계속하고 싶을 뿐이오.'),
(2057, 0, 0, '도와줘서 고맙네. 사옌이 놈들과 한편일 줄 정말 상상도 하지 못했군. 그런 일에 맞설 준비도 되어 있지 않았었고 말이네.'),
(2057, 1, 0, '잘했네. 배신자에게 복수가 행해져서 정말 기쁘군. 미란이 간 동쪽 길로 계속 가서 발굴조사단장 아이언밴드에게 우리는 준비가 모두 끝났다고 전해 주게. 아마 아이언밴드가 자네에게 부탁할 일도 조금 있을 것이네.'),
(2080, 0, 0, '이제 이 귀한 흙을 내 화단에 넣읍시다.'),
(2080, 1, 0, '다시 한번 고맙소, $n. 이 귀한 흙은 내 연구에 큰 도움이 될 거요.'),
(2080, 2, 0, '%s|1이;가; 황급히 그의 화단으로 갑니다.'),
(2080, 3, 0, '싹이 트고 뿌리를 내려야 할 텐데...'),
(2080, 4, 0, '%s|1이;가; 빛나는 과일에서 씨를 빼냅니다...'),
(2080, 5, 0, '내가 준비한 토양에서 이 씨들이 잘 자라는지 한번 봅시다.'),
(2080, 6, 0, '%s|1이;가; 과일에서 빼낸 씨앗을 심습니다.'),
(2080, 7, 0, '%s|1이;가; 흙을 뚫고 나옵니다!'),
