(2768, 1, 0, '우리가 이곳에 온 첫날 이 동굴을 발견했지요. 마법석의 힘을 유용하게 쓸 수 있을 거예요.'),
(2768, 2, 0, '이제 마법석에서 힘을 끌어내 볼게요. 당신은 저를 보호해 주시면 돼요. 이곳은 저주받은 곳이에요... 정말이라니까요.'),
