(2922, 0, 2, '이곳 황야의 땅은 정말 뜨겁지만 습하지는 않답니다.'),
(2922, 1, 0, '우리는 더 뛰어나고, 더 강하고, 더 빠르게 만들 수 있습니다. 우리에겐 기술과 마법이 있으니까요.'),
(2922, 1, 1, '주인님, 이곳은 위험합니다. 제가 경비를 서겠습니다.'),
(2922, 1, 2, '부르... 찰칵... 윙...'),
(2931, 0, 0, '%s|1이;가; $n의 시체를 다 먹고 나자 훨씬 더 조용해 진 것 같습니다.'),
(2941, 0, 0, '경비병!'),
(2981, 0, 0, '대지모신이시여, 오늘 저희 중 하나가 당신의 품에 듭니다. 그녀는 우나야 호크윈드, 제 어머니이자 우리 모두의 대모님입니다. 부족에서 가장 현명한 분이시지요.'),
(2981, 1, 0, '그녀의 영혼이 순식간에 당신께 닿길. 바람이 그녀를 부드럽게 감싸고, 풀잎이 그녀의 이름을 속삭이길.'),
(2981, 2, 0, '그녀가 저희를 돌보았듯 그녀를 돌봐 주십시오. 저희 또한 안식에 드는 그날까지, 그녀가 안쉬와 무샤의 영원한 빛으로 저희를 기쁘게 바라보게 해 주십시오.'),
(2981, 3, 0, '우리 모두 당신께 났으니, 마땅히 당신께 돌아갈 것입니다.'),
(2986, 0, 0, '또 보자고, 용감한 친구.'),
(2995, 0, 0, '경비병!'),
(3054, 0, 0, '%s|1이;가; 부족의 불 앞에서 우물돌과 대지열매를 결합하면서 주문을 외우기 시작합니다.'),
(3054, 1, 0, '그대가 마실 현자의 물이 준비되었네.'),
(3125, 0, 0, '%s|1이;가; 독침을 쏘려고 합니다! 지금 토템을 설치하십시오!'),
(3142, 0, 0, '어떤 악마의 앞잡이도 우리 땅에 발을 들이도록 허락할 수 없다!'),
(3218, 0, 0, '칼날 맛 좀 봐라!'),
(3218, 0, 1, '제발 그 일만은 저지르지 않았다고 말해주세요! 그렇지 않다면 전 당신을 해칠 수밖에 없습니다.'),
(3218, 0, 2, '가만히 있지 말고 가서 놀 거리를 많이 만들어 주도록!'),
(3274, 0, 0, '베로그를 불러내! 위기에 처했다!'),
(3275, 0, 0, '베로그를 불러내! 위기에 처했다!'),
(3282, 0, 0, '훔쳐 간 벌목기가 저기 있군! 러그위즐이 우리 은신처를 점령하기 전에 막아라!'),
(3287, 0, 0, '$n, 서둘러 가시오. 내 운명이 당신 손에 달려 있소.'),
(3296, 0, 0, '칼날 맛 좀 봐라!'),
(3296, 0, 1, '제발 그 일만은 저지르지 않았다고 말해주세요! 그렇지 않다면 전 당신을 해칠 수밖에 없습니다.'),
(3296, 0, 2, '가만히 있지 말고 가서 놀 거리를 많이 만들어 주도록!'),
(3301, 1, 0, '살아생전에는 나의 검 아키우스가 아주 쓸모 있었지. 하지만 비참했던 삶에서 자유로워진 지금은 아무런 필요가 없네.'),
(3301, 2, 0, '내 딸에 대한 사랑과 추억은 절대 잊을 수 없을 것이야. 이젠 정의의 이름으로 내 죄를 용서 받을 수 있기를 바라네.'),
(3305, 0, 0, '경비병!'),
(3310, 0, 0, '경비병!'),
(3389, 0, 0, '조심하게, $n! 서쪽이야!'),
(3389, 1, 0, '경비병 하나가 쓰러졌다!'),
(3395, 0, 0, '내가 왔다! 침입자들이여, 나의 막사로 와서 죽음을 맞으라!'),
(3397, 0, 0, '베로그를 불러내! 위기에 처했다!'),
(3439, 0, 0, '알았다고, 알았어! 내가 이 대단한 물건의 작동 방법을 곧 알아낼 수 있단 말이야.'),
(3439, 1, 0, '아이고, 내가 뭘 잘못했나?'),
(3439, 2, 0, '좋아, 이제 괜찮아진 것 같군. 날 따라오라고!'),
(3439, 3, 0, '이제 굴착 현장에서 빠져 나온 것 같군, 그렇지? 그런데 대체 이건 어디다 쓰는 건지, 원...'),
(3439, 4, 0, '제발... 말 좀 들어라!'),
(3439, 5, 0, '큰일 날 뻔했군! 자, 계속 가자고. 거의 다 왔어.'),
(3439, 6, 0, '흠... 이 깜빡이는 빨간 불빛은 뭔가 좋지 않은 신호 같은데...'),
(3442, 0, 0, '자, 어디 한번 볼까...'),
(3442, 1, 0, '아, 이런...'),
(3448, 0, 0, '%s|1이;가; 무쇠턱거북의 등껍질을 조사합니다...'),
(3448, 1, 0, '흠...'),
(3448, 2, 0, '이상하군. 정말 이상해...'),
(3448, 3, 0, '흠... $n. 이 등껍질로 많은 걸 알 수 있었지만, 의문점도 더 많이 생긴 것 같소...'),
(3451, 0, 0, '당신이 먼저 톱니항으로 가서 스퍼터밸브에게 내가 벌목기를 망가뜨렸다고 알려야겠소.'),
(3451, 1, 0, '나는 여기 남아 잔해를 지키겠소. 서두르시오! 아무도 이 연기를 눈치채지 못해야 할 텐데...'),
(3465, 0, 0, '내게서 멀리 떨어지지 마시오. 이곳을 뚫고 나가려면 가능한 모든 도움이 필요할 거요. 자, 갑시다!'),
(3465, 1, 0, '드디어 북부감시 요새를 빠져 나왔군! 잠시, 한숨 돌려야겠소...'),
(3465, 2, 0, '이제 좀 낫군. 자, 어서 톱니항으로 돌아갑시다.'),
(3465, 3, 0, '남쪽바다 해적단 놈들이 해안에 진지를 상당하게 구축해 놓은 것 같군. 좀 힘들게 됐구먼...'),
(3465, 4, 0, '도와주시오! $n의 공격을 받고 있소!'),
(3465, 4, 1, '$n|1이;가; 이쪽으로 오고 있소! 복수할 때가 왔군!'),
(3465, 4, 2, '$n|1이;가; 우리에게 다가오고 있소!'),
(3465, 4, 3, '이 $n 놈을 좀 막아주시오!'),
(3465, 5, 0, '톱니항에 거의 다 왔소! 속도를 늦추지 말고 갑시다.'),
(3465, 6, 0, '아, 반가운 톱니항의 바다 냄새!'),
(3465, 7, 0, '브라이트썬 선장님, 여기 있는 $n|1이;가; 절 구해줬습니다. 당신의 용감한 행동에 선장님께서 보상을 해주실 거요.'),
(3502, 0, 0, '칼날 맛 좀 봐라!'),
(3502, 0, 1, '제발 그 일만은 저지르지 않았다고 말해주세요! 그렇지 않다면 전 당신을 해칠 수밖에 없습니다.'),
(3502, 0, 2, '가만히 있지 말고 가서 놀 거리를 많이 만들어 주도록!'),
(3504, 0, 0, '진짜예요, 엄마? 운하에 진짜 악어가 살아요?'),
(3504, 0, 1, '엄마, 나 다리 아파.'),
(3504, 0, 2, '아직 멀었어요?'),
(3504, 1, 0, '마법사의 탑도 보고 싶어요.'),
(3511, 0, 0, '이걸 왜 배워야 하나요?'),
(3512, 0, 0, '선생님, 성기사 분들이 정말로 여기서 훈련을 하나요?'),
(3518, 0, 0, '갓 구운 빵 팔아요!'),
(3518, 0, 1, '신선한 빵 팔아요!'),
(3518, 0, 2, '따뜻하고 건강에 좋은 빵이 있습니다!'),
(3518, 0, 3, '롤빵, 작은 롤빵, 식빵 있어요. 갓 구운 빵입니다!'),
(3568, 1, 0, '%s|1이;가; 감사의 표시로 울어 보인 후 곧장 숲으로 사라집니다.'),
(3569, 0, 0, '죽여라!'),
(3615, 0, 0, '경비병!'),
(3616, 0, 0, '%s|1이;가; 황혼의 마법책에서 얻은 양피지를 살펴봅니다...'),
(3616, 1, 0, '%s|1이;가; 마법에 의해 피해를 입습니다!'),
(3616, 2, 0, '음...'),
(3627, 0, 0, '마법 공부로 지치셨다고요? 그럴 때 고독한 은둔자 선술집에 가서 정신이 맑아지는 음료수 한잔 하시기 바랍니다!'),
(3627, 0, 1, '스톰윈드 최고의 술이 바로 여기 있습니다!'),
(3627, 0, 2, '맥주를 마시러 왔다가 분위기에 취해 머물게 되는 곳!'),
(3627, 0, 3, '스톰윈드에서 유일하게 마법과 영혼이 공존하는 곳, 고독한 은둔자 선술집으로 오십시오!'),
(3627, 0, 4, '고독한 은둔자 선술집에서 공짜 술을 제공합니다!'),
(3627, 0, 5, '기분이 우울하신가요? 그렇다면 고독한 은둔자 선술집으로 오셔서 즐거운 시간을 보내십시오!'),
(3627, 0, 6, '고독한 은둔자 선술집으로 오십시오. 그곳에서는 모두 단골손님으로 대접한답니다!'),
(3644, 0, 0, '아나야? 내가 지금 꿈을 꾸고 있는 건가? 정말 당신이오?'),
(3644, 1, 0, '천 년을 떨어져 지내고 난 후에도 이 정도밖에 허락하지 않다니... 가혹한 운명이 너무나 원망스럽구려.'),
(3644, 2, 0, '날 미워하는 거요, 내 사랑? 그 고통스러운 불행의 속박에서 당신의 영혼을 풀어주기 위해서 다른 이의 손을 빌려 당신을 해칠 수밖에 없었던 나를...'),
(3644, 3, 0, '안 돼! 아나야... 아나야! 나를 떠나지 마시오! 제발...'),
(3644, 4, 0, '어떻게... 나더러 당신 없이 이 세상을 살아가란 말이오, 내 사랑...'),
(3669, 0, 0, '꿈꾸는 자는 절대로 깨울 수 없다!'),
(3670, 0, 0, '온몸을 휘감아 으스러뜨려주마!'),
(3673, 0, 0, '나는 전지전능한 군주 서펜티스다!'),
(3678, 0, 0, '마침내! 나랄렉스께서 깨어나실 수 있다! 용감한 모험가들이여, 와서 나를 도우시오!'),
(3678, 1, 0, '그 분을 깨우는 의식을 시작하기 전에 준비가 필요하오. 당신이 날 지켜 줘야 하오!'),
(3678, 2, 0, '이 동굴은 한때 불모의 땅의 재번영에 대한 약속의 신전이었소. 지금은 악몽의 소굴이지만...'),
(3678, 3, 0, '계속 가야 하오. 악몽에서 나랄렉스 님을 구하려면 해야 할 일이 많소.'),
(3678, 4, 0, '이 화염 마법진 안에서 살해당한 송곳니 드루이드의 영혼을 추방시킬 주문을 걸어야 하오.'),
(3678, 5, 0, '동굴이 정화되었소. 이제 나랄렉스의 안식처로 갑시다!'),
(3678, 6, 0, '이 복도 너머에 나랄렉스께서 발작을 일으키는 고통스러운 잠에 빠져 계시오. 너무 늦기 전에 그 분을 깨우러 갑시다.'),
(3678, 7, 0, '용감한 이들이여, 나랄렉스 님을 구하고 이 재앙을 끝내기 위해 에메랄드의 꿈으로 들어갈 때에 나를 지켜 주시오.'),
(3678, 8, 0, '%s|1이;가; 나랄렉스에게 자각의 의식을 행하기 시작합니다.'),
(3678, 9, 0, '이 $n 놈은 나랄렉스 님의 악몽에서 나온 악마의 앞잡이가 분명하오!'),
(3678, 10, 0, '마침내! 나랄렉스께서 악몽에서 깨어나셨소.'),
(3678, 11, 0, '공격 받고 있소! 이 $n 놈을 막아주시오!'),
(3679, 0, 0, '%s|1이;가; 악몽 속에서 고통으로 몸부림칩니다.'),
(3679, 1, 0, '%s|1이;가; 고통으로 몸부림칩니다. 그의 신도가 꿈속으로 들어간 것 같습니다.'),
(3679, 2, 0, '%s|1이;가; 끔찍한 꿈을 꿉니다. 어둠침침한 물속에서 무언가 꿈틀댑니다.'),
(3679, 3, 0, '마침내 내가 깨어났도다!'),
(3679, 4, 0, '아, 드디어 끔찍한 악몽에서 풀려났구나! 고맙다, 내 충성스러운 신도여, 그리고 너의 용감한 동료에게도 감사를 전한다.'),
(3679, 5, 0, '우리는 어서 가서 다른 신도들과 합류해야 한다. 다시 한번 불모의 땅에 대한 회복을 시도하려면 그 전에 많은 준비가 필요하다. 살펴 가거라, 용맹한 이들이여!'),
(3695, 0, 0, '%s|1이;가; 당신을 향해 으르렁거린 다음 당신의 냄새를 맡습니다.'),
(3727, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(3817, 0, 0, '%s|1이;가; 돌진하여 공격합니다!'),
(3818, 0, 0, '%s|1이;가; 돌진하여 공격합니다!'),
(3838, 0, 0, '경비병!'),
(3840, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(3841, 0, 0, '경비병!'),
(3849, 0, 0, '드디어 이 비참한 감방에서 탈출하는군! 제가 안마당으로 안내해 드리겠습니다.'),
(3849, 1, 0, '당신은 진실로 이 문 너머에 있는 무시무시한 괴물들을 상대할 정도로 용감하신 분입니다.'),
(3849, 2, 0, '다 됐네!'),
(3849, 3, 0, '아루갈을 처치하길 바랍니다. 전 이제 서둘러 하드렉 님께 돌아가 봐야겠습니다.'),
(3849, 4, 0, '누군가가 놈을 처치했군.'),
(3850, 0, 0, '날 따라오십시오. 안마당 문을 열어 드리겠습니다.'),
(3850, 1, 0, '감방문들이 너무 복잡하게 잠겨 있어서 제게는 이 문을 여는 주문밖에 없습니다.'),
(3850, 2, 0, '다 됐습니다! 이제 문이 열렸습니다. 이 너머에 있는 것들을 물리치길 바랍니다. 난 즉시 키린 토로 돌아가 보고해야겠습니다.'),
(3850, 3, 0, '이번만큼은 쓰레기 같은 네놈과 의견이 일치하는구나.'),
(3887, 0, 0, '당장 이 저주받은 곳을 떠나라!'),
(3887, 1, 0, '죽음도 나를 저주에서 해방해 줄 순 없다...'),
(3887, 2, 0, '너의 영혼이 안식을 찾길.'),
(3887, 2, 1, '너의 영혼이 편안히 쉬길.'),
(3899, 0, 0, '수호자의 도움 없이는 자신이 없는 것 같군?'),
(3925, 0, 0, '%s|1이;가; 전투에서 동료가 쓰러진 것을 보고 분노에 휩싸입니다.'),
(3974, 0, 0, '얘들아, 놈들을 처치해라!'),
(3975, 0, 0, '아! 도전을 기다리고 있었다!'),
(3975, 1, 0, '빛의 검을 받아라!'),
(3975, 2, 0, '빛이여, 힘을 주소서!'),
(3975, 3, 0, '하! 고작 이거냐?'),
(3975, 4, 0, '%s|1이;가; 격노합니다!'),
(3976, 0, 0, '이단자들! 성스러운 칼을 받아라!'),
(3976, 2, 0, '명령만 내리십시오!'),
(3981, 0, 0, '결국, 놈이 대가를 치렀군요.'),
(3983, 0, 0, '불어... 순순히 모두 불라고!'),
(3983, 1, 0, '고약한 비밀이로군!'),
(3983, 2, 0, '낱낱이 밝혀내고야 말겠다!'),
(3983, 3, 0, '죄의 대가를 치러라!'),
(4063, 0, 0, '안 돼! 내버려 둬! 방해하지마!'),
(4063, 0, 1, '죽어라! 미즈라엘 구하지 못한다!'),
(4063, 0, 2, '위대하신 분이 너 박살내 버리신다!'),
(4064, 0, 0, '%s|1이;가; 격노합니다!'),
(4065, 0, 0, '검은바위 오크의 힘을 느껴 보아라!'),
(4065, 0, 1, '넌 검은바위 오크의 상대가 안 돼!'),
(4065, 1, 0, '%s|1이;가; 격노합니다!'),
(4267, 0, 0, '경비병!'),
(4275, 0, 0, '감히 아루갈의 후예들을 방해하는 게 누구냐?'),
(4278, 0, 0, '성채에 침입자가 있다! 무장하라!'),
(4278, 1, 0, '우리는 영원히 이곳을 감시할 것이다...'),
(4278, 2, 0, '적의 전력이 약해지고 있다!'),
(4278, 2, 1, '승리에 한 발짝 더 가까워졌군!'),
(4278, 3, 0, '침입자를 물리쳐라!'),
(4295, 0, 0, '도망칠 곳은 없다! 붉은십자군은 타락한 스컬지 녀석들을 모두 없애버릴 것이다.'),
(4303, 0, 0, '%s|1이;가; 격노합니다!'),
(4306, 0, 0, '여기서 나가고 싶으면 어서 자백하시지.'),
(4306, 0, 1, '결국은 죄다 불게 될 텐데... 차라리 지금 털어놓는 게 어때?'),
(4306, 0, 2, '뭐라고? 사실.. 난 자백 따위엔 관심이 없었어. 단지 고문을 즐길 뿐이지, 하하하.'),
(4312, 0, 0, '경비병!'),
(4314, 0, 0, '경비병!'),
(4317, 0, 0, '경비병!'),
(4319, 0, 0, '경비병!'),
(4321, 0, 0, '경비병!'),
(4351, 0, 0, '%s|1이;가; 포획할 수 있을 만큼 약해졌습니다!'),
(4352, 0, 0, '%s|1이;가; 포획할 수 있을 만큼 약해졌습니다!'),
(4407, 0, 0, '경비병!'),
(4420, 0, 0, '아감마간 만세!'),
(4422, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(4462, 0, 0, '검은바위 오크의 힘을 느껴 보아라!'),
(4462, 0, 1, '넌 검은바위 오크의 상대가 안 돼!'),
(4462, 1, 0, '%s|1이;가; 격노합니다!'),
(4463, 0, 0, '검은바위 오크의 힘을 느껴 보아라!'),
(4463, 0, 1, '넌 검은바위 오크의 상대가 안 돼!'),
(4463, 1, 0, '%s|1이;가; 격노합니다!'),
(4464, 0, 0, '%s|1이;가; 격노합니다!'),
(4484, 0, 0, '갑자기 불길한 예감이 드는데... 조심해, 놈들이 왔다!'),
(4484, 1, 0, '자네가 발견한 그 이교도 조직에서 보낸 암살자로군. 다른 놈들이 우리를 발견하기 전에 어서 가세나.'),
(4484, 2, 0, '잠깐! 뭔가 사악한 기운이 느껴지는데... 언데드다!'),
(4484, 3, 0, '오늘 목공 일을 끝내고 오던 놈들이군. 계속 이동하지 않으면 날 노리는 적을 더 많이 만나게 될 거야.'),
(4484, 4, 0, '이런... 또 이 세 놈들이군.'),
(4484, 5, 0, '이번에는 영원히 끝장내 주마!'),
(4484, 6, 0, '수고했네. 여기서부터는 혼자 가더라도 안전할 거야. 잿빛 골짜기의 마에스트라 주둔지로 가서 델그렌과 대화하는 걸 잊지 마시게.'),
(4484, 7, 0, '서둘러 움직여야 하네. 아우버다인은 그리 멀지 않지만 많은 적들이 숲에서 잠복하고 있네.'),
(4500, 0, 0, '조그만 $r|1이;가; 감히 이 대군주 모크모로크와 싸우겠다고? 끝장내 주지! 나 이곳의 왕이다!'),
(4500, 1, 0, '너 박살내 버린다!'),
(4500, 2, 0, '나 무서워! 나 이제 도망갈 거야!'),
(4508, 0, 0, '야호! 마침내 여기서 나가는구먼. 하지만 쉽지는 않을 거야. 경계를 늦추지 말라고.'),
(4508, 1, 0, '저 위에 그 괘씸한 쭈그렁 할멈, 서슬깃 차를가가 살고 있지.'),
(4508, 2, 0, '도와줘! 이 $n|1을;를; 좀 막아 주란 말이야!'),
(4508, 3, 0, '이곳에 청엽수 줄기가 있다고! 말하자면, 찾아주길 얌전히 기다리고 있는 황금 같은 거라고 할 수 있지!'),
(4508, 4, 0, '여기는 곳곳에 위험이 도사리고 있는 곳이지.'),
(4508, 5, 0, '이곳에 어떻게 이런 고약한 짐승들이 사는지 모르겠다니까. 윽! 냄새!'),
(4508, 6, 0, '드디어 이 엄청난 가시덩굴 미로에서 빠져나갈 길을 발견한 것 같군.'),
(4508, 7, 0, '저 고약한 곳에서 빠져 나와서 정말 다행이군. 하지만 이 위의 상황도 별로 나아 보이지는 않는구먼!'),
(4508, 8, 0, '드디어! 이곳에서 나갈 수 있게 되어 정말 기쁘다니까!'),
(4508, 9, 0, '한숨 돌린 후에 톱니항으로 돌아가야겠군. 도와줘서 고맙다고!'),
(4508, 10, 0, '자, 그럼 난 톱니항으로 가겠네. 자네에게 행운이 함께하기를!'),
(4509, 0, 0, '대지를 감싸는 공포 속에서 아메스아란은 분리의 고통을 겪었어. 그 속에선 살아남을 수 있는 희망은 거의 없었지.'),
(4509, 1, 0, '그때 애스리쿠스가 왔어. 그는 우리를 고통에서 구해주겠다고 했지. 그러곤 보호의 마법을 시전했어.'),
(4509, 2, 0, '마법의 진동이 멈추자 그의 숨겨진 목적이 밝혀졌어. 우린 함정에 빠졌고 그는 천천히 우리의 힘을 빼앗아갔어.'),
(4509, 3, 0, '수백 명이 그의 주문에 갇혀 버렸지. 하지만 이제 그의 주문에 속박된 자는 얼마 안 남게 됐지. 그래도 그는 가끔 우리에게 말을 걸곤 했어.'),
(4509, 4, 0, '그는 자신의 힘이 약해질까 봐 걱정했지. 그리고 자신에게 마지막으로 남은 귀중한 영혼의 보석인 우리마저 사라져 최후를 맞이할까 봐 걱정하고 있었어.'),
(4509, 5, 0, '그의 부관인 일크루드 마그스룰은 남아있는 영혼의 보석의 위치를 나타내는 마법책을 지니고 있소.'),
(4520, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(4530, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(4531, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(4532, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(4543, 0, 0, '우리는 복수에 굶주려 있다.'),
(4543, 1, 0, '분노한 망자에게 안식이란 없다.'),
(4543, 2, 0, '영혼... 영혼이 더 필요해!'),
(4551, 0, 0, '경비병!'),
(4607, 0, 0, '윽! 저놈이 뭘 하는 거야. 해충을 내게 보내? 목숨을 부지하고 싶다면 어서 이거 가지고 내 눈앞에서 사라져!'),
(4624, 0, 0, '칼날 맛 좀 봐라!'),
(4624, 0, 1, '제발 그 일만은 저지르지 않았다고 말해주세요! 그렇지 않다면 전 당신을 해칠 수밖에 없습니다.'),
(4624, 0, 2, '가만히 있지 말고 가서 놀 거리를 많이 만들어 주도록!'),
(4670, 0, 0, '%s|1이;가; 격노합니다!'),
(4671, 0, 0, '%s|1이;가; 격노합니다!'),
(4672, 0, 0, '%s|1이;가; 격노합니다!'),
(4673, 0, 0, '%s|1이;가; 격노합니다!'),
(4674, 0, 0, '%s|1이;가; 격노합니다!'),
(4675, 0, 0, '%s|1이;가; 격노합니다!'),
(4721, 0, 0, '밤의 장막 아래에서도 대지모신께서 훤한 대낮과 같이 우리를 지켜 주시기를. 이 불이 우리의 몸과 영혼을 모두 비추며, 항상 우리를 이끌어 주시는 영광스러운 선조를 기억하게 해 주기를...'),
(4832, 0, 0, '누가 감히 내 명상을 방해하는 거냐?'),
(4832, 1, 0, '감히 이곳에 들어오다니! 모두 처치해!'),
(4832, 2, 0, '잘 가라.'),
(4851, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(4854, 0, 0, '나 그림로크는 왕이다!'),
(4854, 2, 0, '죽어! 죽어 버려!'),
(4855, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(4961, 0, 0, '고독한 은둔자 선술집으로 오십시오. 그곳에서는 모두 단골손님으로 대접한답니다!'),
(4961, 1, 0, '좋아, 좋아! 싸움은 이제 그만. 누군가 하나가 다칠 필요는 없지.'),
(4961, 2, 0, '그만하자고, 친구. 물러서라고. 그만하면 충분하지 않나. 나중에 보자고.'),
(4966, 0, 0, '헨델, 이제 자네 문제를 처리해야겠군. 프라우드무어 님께서 탑에서 자네에게 말씀하실 걸세.'),
(4966, 1, 0, '부디... 제발... 프라우드무어 님. 그럴 뜻은 아니었습니다...'),
(4966, 2, 0, '여기 오는 데 너무 오래 걸려서 미안합니다. 프라우드무어 님께서도 함께하셔야 할 것 같아서 말입니다.'),
(4966, 3, 0, '우리는 잠시 머물렀다 다시 탑으로 돌아가야 합니다. 우리와 더 얘기를 나누고 싶다면 그곳으로 오시기 바랍니다.'),
(4966, 4, 0, '%s|1이;가; 심각한 부상으로 추적을 포기합니다.'),
(4979, 0, 0, '오, 고맙소.'),
(4979, 1, 0, '... 탈영병 속옷 반값에 할인합니다? 이 쓰레기는 도대체 뭐요?'),
(4979, 1, 1, '... 헤어젤을 구매하기 위한 기금을 만들자? 필요 없소. 난 내 머리 모양에 만족하오!'),
(4979, 1, 2, '... 탈영병들은 모든 시민이 온종일 곡예를 할 수 있는 테라모어를 원합니다? 이게 대체 무슨 소리요?'),
(4979, 1, 3, '... 닭을 테라모어의 상징으로 지정하자고?! 이 사람들 제정신이 아니군!'),
(4979, 1, 4, '... 탈영병이 된 여러분은 밧줄에 묶여 수영하기나 개 목욕시키기 등의 여러 여가 활동을 즐기실 수 있습니다? 이거 웃기는군!'),
(4979, 2, 0, '이거... 웃자고 하는 소리겠지. 아니오?'),
(4979, 2, 1, '나는 절대 이딴 일에 동참하지 않을 거요. 하지만 이건 가져가겠소. 화장실에서 쓰기 딱 좋은 재질이로군...'),
(4979, 2, 2, '당신들 모두 정신이 어떻게 된 거 아니오? 정말 이렇게 생각한단 말이오?'),
(4980, 0, 0, '워... 원하는 게 뭐야? 그냥 날 내버려둬...'),
(4980, 1, 0, '맹세해. 너에게선 아무것도 훔치지 않았다고! 자, 이걸 가지고 어서 사라져!'),
(4980, 2, 0, '내... 내가 그 여관에서 자잘한 물건을 한두 개 훔쳤던 것도 같지만... 그런데 오우거가 왜 그런 일에 신경 쓰는 거지?'),
(4980, 3, 0, '한 발자국도 더 가까이 오지 마, 이 오우거!'),
(4980, 4, 0, '난 네가 말하는 그 화재에 대해서는 아무것도 모른다고...'),
(4980, 5, 0, '뭐지? 무슨 소리지?'),
(4980, 6, 0, '%s|1이;가; 가슴에 화살이 깊이 박히자 뒤로 비틀거립니다.'),
(4980, 7, 0, '으윽... 할란, 네가 이럴 수가...'),
(4980, 8, 0, '운 좋은 날인 줄 알라고. 좋아, 말해 주지. 그러니 날 제발 좀 내버려둬. 이봐, 내 말이 믿기지 않겠지만, 그건... 으, 젠장, 할란이 쏜 게... 윽...'),
(4983, 0, 0, '저기 있는 저 섬에서 불빛과 인간 그림자를 본 적이 있다. 가서 한번 확인해 보자, $n.'),
(4983, 1, 0, '저건 리테로군. 좋아. 가서 그가 뭐라고 하는지 들어 보자고.'),
(4983, 2, 0, '그늘 쉼터 여관에 대해 알고 있는 걸 모두 말해! 그렇지 않으면 네놈의 정강이를 걷어차겠다.'),
(4983, 3, 0, '이봐, 어서 그 화재에 대해 말하지 않으면...'),
(4983, 4, 0, '젠장! 내 앞에서 죽지 마, 인간!'),
(4983, 5, 0, '괜찮나, 리테?'),
(4983, 6, 0, '숨이 끊어진 것 같다. 이래서는 우리에게 별 도움이 안 되지. 당신은 돌아가서 크로그에게 이 일에 대해 보고하는 게 좋겠다.'),
(4983, 7, 0, '그리고 날 엄호해 줘서 고맙다.'),
(4983, 8, 0, '너 내가 죽인다!'),
(4983, 8, 1, '너 박살내 버린다!'),
(5046, 0, 0, '파발 리테! 마침내 찾아냈군. 이젠 오우거들과 어울리고 있나? 두려워 말라고. 탈영병이나 배반자에게도 자비의 손길을 베풀 순 있으니까.'),
(5046, 1, 0, '할란 병사, 부관 리테에게 자비를 좀 베풀어 주어라!'),
(5046, 2, 0, '이제 나머지 쓰레기들도 다 쓸어버리도록!'),
(5089, 0, 0, '좋아! 좋아! 항복하지... 협조할 테니 무기는 내려놓으라고!'),
(5159, 0, 0, '오셨군요! 맥주를 가지고 도망가셨다고 생각했어요!'),
(5267, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(5355, 0, 2, '살아서 도망치지 못할 것이다!'),
(5355, 0, 3, '넌 너무 많은 걸 알고 있군! 절대 살려둘 수 없다!'),
(5391, 0, 0, '도와 주세요! 제발 저 좀 도와 주십시오!'),
(5391, 1, 0, '어서 여기를 떠납시다.'),
(5391, 2, 0, '조심해요! $n|1이;가; 공격합니다!'),
(5391, 2, 1, '도와주세요! 공격 받고 있어요!'),
(5391, 3, 0, '고맙습니다. 항상 당신을 기억하겠어요. 스토나드 북쪽에 있는 내 야영지에 가면 내 금고가 있을 겁니다.'),
(5391, 4, 0, '%s|1이;가; $n에게 자신의 금고를 열 수 있는 비밀을 속삭입니다.'),
(5391, 5, 0, '%s|1이;가; 늪으로 사라집니다.'),
(5471, 0, 0, '%s|1이;가; 먹을 준비를 다 했습니다.'),
(5471, 1, 0, '미안하다! 안 때릴게!'),
(5471, 2, 0, '야호!'),
(5471, 2, 1, '고맙다, 웃긴 오우거!'),
(5471, 2, 2, '나 잘 모르겠다.'),
(5471, 2, 3, '읽으면 머리 아프다.'),
(5471, 2, 4, '...네가 말한 것 까먹었다.'),
(5471, 2, 5, '알았다. 나 서명한다.'),
