(5475, 0, 0, '%s|1이;가; 먹을 준비를 다 했습니다.'),
(5475, 1, 0, '미안하다! 안 때릴게!'),
(5475, 2, 0, '야호!'),
(5475, 2, 1, '고맙다, 웃긴 오우거!'),
(5475, 2, 2, '나 잘 모르겠다.'),
(5475, 2, 3, '읽으면 머리 아프다.'),
(5475, 2, 4, '...네가 말한 것 까먹었다.'),
(5475, 2, 5, '알았다. 나 서명한다.'),
(5475, 2, 6, '나 아직 배고프다.'),
(5475, 2, 7, '옷도 줘?'),
(5661, 0, 0, '에드워드. 타일러. 첫 번째 시험을 준비하도록.'),
(5661, 1, 0, '리스타, 포로를 소환하도록!'),
(5661, 2, 0, '이번 건 별로 어렵지 않았던 것 같군. 두 번째 시험은 어떻게 해내는지 한번 볼까? 리스타, 리치 왕의 앞잡이들을 데려오게.'),
(5661, 3, 0, '리스타, 언데드 포로들을 불러내라.'),
(5661, 4, 0, '젊은 전사들이여, 마지막 시험을 치를 때가 왔다! 이제 가장 힘든 전투를 준비하도록.'),
(5661, 5, 0, '리스타, 누더기골렘을 데려오너라!'),
(5661, 6, 0, '에드워드, 타일러. 잘했다. 훈련 성과가 꽤 좋군. 얼마 후에 자네들의 기질을 다시 한번 시험해 볼 테니 준비하고 있도록.'),
(5662, 0, 0, '너희 실력이 겨우 그 정도밖에 안 되는 건 아니겠지? 자, 증명해 봐!'),
(5662, 0, 1, '좋아, 말라깽이 친구들. 얼마나 잘 배웠는지 한번 볼까? 내가 멈추라고 할 때까지 계속 공격하도록.'),
(5662, 0, 2, '뭐하고 있는 건가? 그걸 전투라고 할 수 있겠나? 그게 전투면 난 로서다!'),
(5662, 0, 3, '이까짓 나무와 지푸라기로 만든 허수아비는 자비를 베풀지 몰라도 리치 왕은 절대 봐 주지 않는다!'),
(5662, 0, 4, '검은 단순한 도구가 아니야! 검은 네 몸의 일부다. 더 잘할 수 없나!'),
(5662, 0, 5, '그만! 너희 그걸 전투라고 하는 건가? 형편없군! 제대로 한번 싸워 보라고, 아니면 끝장날 줄 알아!'),
(5662, 0, 6, '이것들 봐라. 땅속에 묻히지만 않았지 완전히 죽은 녀석들 같군. 죽을 힘을 다해서 해 보란 말이야!'),
(5662, 0, 7, '너희는 자신을 위해 싸우는 게 아니다! 이제 너희는 여왕님을 위해 싸우는 영예로운 전사다. 그러니 자격을 갖추었다는 것을 증명해 보이도록!'),
(5696, 0, 0, '테레사, 이걸 랭커스터 신부께 전해 줘.'),
(5696, 1, 0, '고맙구나, 착한 것.'),
(5696, 2, 0, '내가 말한 대로 멋지지 않나?'),
(5696, 2, 1, '내 새로운 지배 기술이 성공할 거라고 하지 않았던가?'),
(5696, 2, 2, '내 새 장난감 어떤가?'),
(5696, 2, 3, '내 애완동물 어떤가?'),
(5696, 2, 4, '정말 놀라운 창조물이지 않나?'),
(5696, 3, 0, '약간의 고문, 마법, 그리고 절개 수술의 조합에 의한 대단한 효과지. 물론 그녀는 의식이 없었다네.'),
(5696, 3, 1, '누구나 약점이 있게 마련이지만 찾아낼 수 있느냐의 문제라네.'),
(5696, 3, 2, '일단 그녀의 영혼을 파괴하고 나니 간단하더군.'),
(5696, 3, 3, '나는 제거하거나 자극을 하면 고분고분해지게 되는 뇌의 특정 부분을 발견해 냈다네.'),
(5696, 3, 4, '내가 모든 비밀을 폭로하길 바라는 건 아니겠지?'),
(5696, 3, 5, '작은 의식을 통한 고문의 효과도 아주 오래갈 수 있지.'),
(5709, 0, 0, '악의 세력이 이 세계에 발을 들여놓게 해서는 안 된다! 싸워라, 나의 아이들아!'),
(5710, 0, 0, '보호막이 무너졌다. 일어나라, 아탈라이여! 일어나라!'),
(5710, 1, 0, '나를 따르라!'),
(5710, 2, 0, '학카르 님이 다시 강림하실 것이다!'),
(5710, 3, 0, '학카르 님이 곧 오실 것이다!'),
(5721, 0, 0, '돌아가라! 꿈의 여왕을 깨우지 마라!'),
(5721, 1, 0, '지금 네가 무슨 짓을 저지르고 있는지 알고나 있느냐! 네 운명을 위해서라도 우리가 널 처치해야겠다.'),
(5734, 0, 0, '흠, 이 키버에게 새로운 연구 주제가 필요할 것 같군. 그 바보 애버너시가 계속 이 키버의 주제를 가로챈다면 키버가 그에게 한마디 할 수밖에 없지.'),
(5734, 1, 0, '아, 이게 있었지. 이제 이 약병이 효과가 있는지 시험해 봐야겠어.'),
(5734, 2, 0, '%s|1이;가; 지친 남자의 목 안에 강제로 액체를 부어 넣습니다.'),
(5734, 3, 0, '%s|1이;가; 작은 두꺼비를 찔러 봅니다.'),
(5734, 4, 0, '이건 키버가 원하던 게 아닌데... 뱀뿌리를 너무 많이 넣었나 보군. 두 번째 물약은 키버가 원하는 효과가 있을지 한번 봐야겠어.'),
(5734, 5, 0, '%s|1이;가; 두꺼비에게 이상한 액체를 조금 먹입니다.'),
(5734, 6, 0, '%s|1이;가; 실망한 듯 작은 털북숭이 다람쥐를 찔러 봅니다.'),
(5734, 7, 0, '흠, 뭔가 잘못됐어. 짐승이 너무 작아. 이 키버의 세 번째 시도는 어떨지 한번 볼까?'),
(5734, 8, 0, '%s|1이;가; 다람쥐에게 끈적끈적한 액체를 조금 먹입니다.'),
(5734, 9, 0, '%s|1이;가; 겁먹은 토끼를 찔러 봅니다.'),
(5734, 10, 0, '이 키버를 실망시키는군. 물약의 양을 늘려서 해보면 문제가 해결될지도 모르겠어.'),
(5734, 11, 0, '%s|1이;가; 토끼를 잡고 목으로 액체를 쏟아 붓습니다. 그런 다음 우리 안에 다시 넣습니다.'),
(5734, 12, 0, '이건 뭐야? 이 키버는 양을 원한 적이 없는데? 강한 힘을 가진 무기를 원했건만 고작 이런 양이 되다니. 정말 실망이야.'),
(5734, 13, 0, '%s|1이;가; 털이 난 양을 계속 찔러 봅니다.'),
(5734, 14, 0, '대만족이야.'),
(5840, 0, 0, '차라리... 그냥 죽는 게 낫겠어...'),
(5840, 0, 1, '윽! 뭐가 이렇게 축축해!?'),
(5840, 0, 2, '빛이... 희미하게... 죽는 건가? 아니야, 그냥 잠드는 것뿐이야...'),
(5840, 0, 3, '아니... 어디서 웬 오우거가...'),
(5840, 0, 4, '아니... 웬...'),
(5840, 0, 5, '무슨 엉덩이가... 이렇게 큰 거야...'),
(5840, 0, 6, '왜 하필이면... 구린내 나는 오우거가...'),
(5840, 0, 7, '다리에 감각이 없어...'),
(5955, 0, 0, '목이 말라요.'),
(5955, 0, 1, '토르타가 많이 걱정하겠는걸.'),
(5955, 1, 0, '내 사랑 토르타! 내가 돌아왔소!'),
(5955, 2, 0, '이 세상에서 제일 많이 사랑하는 토르타. 그렇게 오랫동안 떨어져 있다가 이제야 다시 만났구려. 마침내 우리 사랑이 다시 꽃필 수 있게 되었소.'),
(5955, 3, 0, '그래야지, 토르타. 당신이 원하는 거라면 뭐든지...'),
(6015, 0, 0, '얼마나 오래 기다렸는지 알기나 해요? 그리고 저녁거리는 어디 있는 거예요? 그렇게 오랜 시간을 밖에서 보냈으면서 아무것도 안 가져왔단 말이에요?'),
(6015, 1, 0, '말도 안 되는 소린 그만해요. 배고파 죽겠다고요! 얼른 바다에 들어가서 먹을 거나 좀 잡아와요.'),
(6015, 2, 0, '그리고 이번에는 제발 길을 잃지 마세요...'),
(6026, 0, 0, '경비병!'),
(6109, 0, 0, '와라, 조무래기들아! 덤벼라!'),
(6119, 0, 0, '끔직하군! 아, 아니에요. 살짝 손을 보고 정리하면 좀 괜찮아질 것 같기도 하네요.'),
(6172, 0, 0, '그만하자고, 친구. 물러서라고. 그만하면 충분하지 않나. 나중에 보자고.'),
(6177, 0, 0, '%s|1이;가; 소환 마법을 외우기 시작합니다...'),
(6238, 0, 0, '어디 한번 덤벼 보시지, 애송이 전사.'),
(6248, 0, 0, '격투가 시작됐소. $n, 싸울 준비를 하시오!'),
(6248, 1, 0, '거기! 당신 차례요!'),
(6248, 2, 0, '도전자가 쓰러졌소!'),
(6248, 3, 0, '격투가 끝났소!'),
(6487, 0, 0, '누가 감히 신비술을 방해하려 하는가?'),
(6487, 1, 0, '정의의 불꽃을 받아라!'),
(6492, 0, 0, '%s|1이;가; 분노하며 $n|1을;를; 공격합니다!'),
(6492, 1, 0, '%s|1이;가; 허공 속으로 탈출합니다!'),
(6513, 0, 0, '%s|1이;가; 격노합니다!'),
(6523, 0, 0, '절대로 검은무쇠 부족을 이길 순 없다.'),
(6523, 0, 1, '죽을 시간이다, $C 녀석.'),
(6523, 0, 2, '검은무쇠 드워프의 힘을 느껴봐라!'),
(6669, 0, 0, '*일등항해사 망나니탈곡기 출발 대기 중*'),
(6669, 1, 0, '끄아악! 바보 같으니라고! 무슨 짓을 한 거야?! 저 녀석 미쳤군! 해치를 닫아라! 돛대를 올려! 아아아악! 모두 자기 위치로!'),
(6706, 0, 0, '경비병!'),
(6726, 0, 0, '경비병!'),
(6729, 0, 0, '아쿠마이가 죽었다! 이제야 이 끔찍한 곳에서 빠져나갈 수 있겠군.'),
(6729, 1, 0, '내 얘기를 들어보시지 않겠소?'),
(6784, 0, 0, '으으.'),
(6846, 0, 0, '우리 결사단이 벌레 같은 녀석들에게 당할 것 같으냐!'),
(6866, 0, 0, '결사단은 너의 행위를 결코 용서하지 않을 것이다!'),
(6866, 0, 1, '막 갈아 놓은 검을 써 볼 기회가 왔군!'),
(6866, 0, 2, '결사단의 힘을 느껴 보아라!'),
(6927, 0, 0, '결사단은 너의 행위를 결코 용서하지 않을 것이다!'),
(6927, 0, 1, '막 갈아 놓은 검을 써 볼 기회가 왔군!'),
(6927, 0, 2, '결사단의 힘을 느껴 보아라!'),
(6986, 0, 0, '엘프 친구, 도무지 무슨 말을 하는 건지 알 수 없군. 그리고 내 일에 사사건건 참견하는 건 그다지 달갑지 않아!'),
(6986, 1, 0, '울둠에서 나온 유물을 정말이지 실수로 얻은 것 같기는 한데 말이지. 성물회가 이 물건에 관심이 있는 건가?'),
(6986, 2, 0, '알았네, 알았어. 관심이 있는 구매자와 만나게 해줄 수는 있을 거야. 그런데 목소리는 좀 낮추라고! 손님들이 겁에 질린단 말이야.'),
(7025, 0, 0, '아야! 뭐 한 거야?'),
(7025, 0, 1, '이봐! 누가 그 곤봉을 준 거야?'),
(7025, 0, 2, '맹세하는 데 나 아니었어요! 당신이 아무것도 증명할 수 없잖아요!'),
(7025, 0, 3, '잘못했어요! 다시는 안 그럴게요!'),
(7033, 0, 0, '우어어!!! 나 $r 죽일거야!'),
(7033, 0, 1, '너 내가 죽인다!'),
(7033, 0, 2, '너 박살내 버린다!'),
(7034, 0, 0, '우어어!!! 나 $r 죽일거야!'),
(7034, 0, 1, '너 내가 죽인다!'),
(7034, 0, 2, '너 박살내 버린다!'),
(7035, 0, 0, '아야! 뭐 한 거야?'),
(7035, 0, 1, '이봐! 누가 그 곤봉을 준 거야?'),
(7035, 0, 2, '맹세하는 데 나 아니었어요! 당신이 아무것도 증명할 수 없잖아요!'),
(7035, 0, 3, '잘못했어요! 다시는 안 그럴게요!'),
(7157, 0, 0, '%s|1이;가; 격노합니다!'),
(7175, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(7267, 0, 0, '죽어라, 이방인!'),
(7267, 1, 0, '모래의 분노를 느껴 보라!'),
(7267, 2, 0, '이 땅은 우리가 지배한다!'),
(7267, 3, 0, '이 사막은 내 거야!'),
(7271, 0, 0, '어떻게 감히 내 성소에 들어오는 게냐!'),
(7271, 2, 2, '뜨거운 모래 맛을 보고 싶나?'),
(7271, 2, 3, '죽어라!'),
(7274, 0, 0, '처형을 시작하자!'),
(7274, 1, 0, '정의가 실현됐다!'),
