(7357, 3, 0, '처치하라, 형제들이여! 스컬지를 위해!'),
(7358, 0, 0, '절대 살아서 나가지 못하리라!'),
(7358, 1, 0, '오너라! 나의 노예들아.'),
(7358, 2, 0, '어서 나와 주인을 섬겨라!'),
