(7664, 3, 0, '영원한 고통을 맛보게 해주마. 복수는 나의 것이니...'),
(7766, 0, 0, '첩보로봇이 녀석을 나오게 할 테니까 여기서 기다리라고, $n. 단단히 준비하라고! 그들의 대화를 엿들은 후에 공격해야 해!'),
(7766, 1, 0, '그렇지! 바로 그걸 기다리고 있었던 거야! 처치해 버려!'),
(7780, 0, 0, '린지는 자유다!'),
(7780, 1, 0, '여기 도움이 필요하오!'),
(7780, 1, 1, '공격 받고 있소!'),
(7780, 2, 0, '아, 이제 길이 보이는군. 여기서부턴 집으로 가는 길을 알고 있소.'),
(7780, 3, 0, '이제 비밀을 말해 주겠소... 전망대 절벽으로 가시오. 이 린지가 그곳 섬에 뭔가 숨겨 놨소.'),
(7780, 4, 0, '당신이 그걸 찾아서 가지시오! 아무에게도 내가 말해 줬다고 얘기하면 안 된다오!'),
(7784, 0, 0, '비상 동력 가동 완료! 이동식 발동기 초기화 중! 꼬꼬댁!'),
