(7784, 2, 0, '꼬꼬댁! 공간 형태 이상 감지 -- 위험 임박! 꼬꼬댁!'),
(7784, 3, 0, '비행 시스템 가동! 꼬꼬댁! 무법항으로 이동을 위해 로켓 가동 중!'),
(7800, 0, 0, '이놈들! 놈리건은 내 꺼란 말이야!'),
