(8127, 0, 0, '술트라제의 자손들이여, 네 주인을 보호하라. 술리투즈여, 다시 한번 일어나다오!'),
(8127, 1, 0, '점심식사가 도착했단다, 내 귀여운 아이들아. 갈가리 찢어 먹어라!'),
(8127, 2, 0, '일어나라... 네 주인을 지켜라!'),
(8201, 0, 0, '%s|1이;가; 격노합니다!'),
(8256, 0, 0, '불쌍한 도리우스... 망할 검은무쇠 놈들, 내 손에 걸리기만 해봐. 날 좀 도와...'),
(8297, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(8391, 0, 0, '네 할 일은 끝났다. 운명을 맞이할 준비나 해라!'),
(8391, 1, 0, '흑요암이여, 일어나서 너의 주인을 모시거라!'),
(8421, 0, 0, '멍청한 놈들... 동생의 나약한 감정을 이용하면 구조 대원을 보낼 줄 알았지.'),
(8421, 1, 0, '너를 이용해 어리석은 황혼의 망치단 녀석들에게 마지막 선타라 비석을 가지고 오게 하는 건 식은 죽 먹기였어.'),
(8421, 2, 0, '검댕가루 작업현장에서 우연히 선타라 비석을 찾았을 때 라그나로스 님의 힘이 내 온몸과 마음을 휘감았지. 라그나로스께서 내 삶에 의미를 주신 거야.'),
(8421, 3, 0, '흑요암을 만든다는 것은 라그나로스 님의 뜻이었지. 흑요암이 검은바위 첨탑에서 검은바위 오크를 쳐부수면, 우리 동지들은 불타오르는 심연에서 하나가 될 수 있어.'),
(8421, 4, 0, '그리고 마침내 내가 불의 수행사제로 다시 태어났을 때 라그나로스께서 내게 이름을 하사하셨지. 라소릭... 검은 라소릭이라고 말이야.'),
(8421, 5, 0, '%s|1이;가; 내는 웃음소리가 멀어져 갑니다...'),
(8421, 6, 0, '박수! 박수! 아주 재미있는 연극이군. 내가 죽은 줄 알았나?'),
(8479, 0, 0, '참고 기다리시오, $n. 횃불이 거의 완성됐소.'),
(8503, 0, 0, '널 베어 버리겠다!'),
(8516, 0, 0, '자, 방심하지 마시고 가까이 붙어 있으세요. 당장에라도 어둠 속에서 가시멧돼지들이 튀어나올지 모릅니다.'),
(8516, 1, 0, '자, 시작하겠습니다. 진화 의식은 한 5분 정도 걸릴 겁니다. 제가 시작하면 졸개 녀석들이 접근하지 못하게 막아주십시오. 안 그러면 우리 모두 끝장입니다!'),
(8516, 2, 0, '3분 남았소. 마력이 차오르는 게 느껴집니다! 부디 계속해서 녀석들을 막아주십시오!'),
(8516, 3, 0, '2분만 더! 절반은 해냈지만 아직 방심하면 안 되오!'),
(8516, 4, 0, '1분만 더! 이제 곧 의식이 끝날 테니 조금만 더 버텨주십시오!'),
(8516, 5, 0, '다 됐군요, 우리가 해냈습니다! 이 우상의 불은 이제 영원히 타오르지 못할 것입니다! 역시 당신은 내가 기대했던 영웅이시로군요!'),
(8516, 6, 0, '$n, 날 거역한 걸 후회하도록 만들어주마.'),
(8516, 7, 0, '$n|1을;를; 조심하세요!'),
