(9316, 0, 0, '좋아요, 그럼 시작합시다.'),
(9453, 0, 0, '저 코도 정말 예쁘군, 잠시만... 내 안경이 어디 있지? 음... 자네가 날 위해 저 코도를 살펴봐 줘야겠어.'),
