(9543, 0, 0, '싫어! 비키란 말이야! 도와줘!!'),
(9546, 0, 0, '아, 정말 죽은 줄 알았습니다. 음...아직도 어질어질하네...'),
(9546, 1, 0, '이제 혼자서도 요새로 돌아갈 수 있소. 당신이 시간을 벌어 주었으니 여기서 몰래 빠져나갈 수 있을 거요. 뉘신지는 잘 모르겠지만 어쨌든 고맙소이다. 언제나 엘룬의 축복이 함께하기를!'),
(9564, 0, 0, '언더시티행 비행선이 방금 도착했습니다! 티리스팔 숲으로 가실 분은 모두 탑승하세요!'),
