(9623, 4, 0, '나빠, $n. $n, 나빠!'),
(9623, 5, 0, '에이미 집에 왔다! 에이미, 착해! 착해, 에이미. 집, 집, 집이다.'),
(9716, 0, 0, '%s|1이;가; 격노합니다!'),
(9779, 0, 0, '%s|1이;가; 분노에 휩싸입니다!'),
(9816, 0, 0, '%s|1이;가; 힘을 되찾기 시작합니다!'),
(9816, 1, 0, '%s|1이;가; 힘을 거의 다 회복했습니다!'),
(9816, 2, 0, '%s|1이;가; 힘을 완전히 회복해 속박에서 풀려납니다!'),
(9816, 3, 0, '하하하! 날 풀어주다니 정말 고맙군, 멍청한 녀석들. 이제 그 보답을 해야겠군. 네놈의 모든 살덩어리를 남김없이 태워주마!'),
(9999, 0, 0, '이거, 이래서야 얼마나 멀리 갈 수 있을지 모르겠네요... 현기증이 좀 나는데...'),
(9999, 0, 1, '만약 내가 어지러워하면, 마구 때려. 만약 내가 쓰러지면, 수통을 사용하고. 이제 가자고!'),
(9999, 1, 0, '뜨거워... 견딜 수가 없어요...'),
(9999, 1, 1, '혹시... 날 업어 줄 수 없나요?'),
(9999, 1, 2, '으으으으으윽...'),
(9999, 1, 3, '기분이 이상해요...'),
(9999, 2, 0, '여기가... 여기가 어디죠?'),
(9999, 2, 1, '아, 이제 기분이 좀 나아졌네요. 고마워요.'),
(9999, 2, 2, '그래요, 계속 가야죠.'),
(9999, 2, 3, '기분이 어떠냐고요? 상당히 축축한 느낌인데요. 아무튼 고마워요.'),
(9999, 3, 0, '스프래글! 난 내가 돌아오지 못할 줄 알았어!'),
(9999, 4, 0, '으... 어지러워...'),
(9999, 5, 0, '%s|1이;가; 정신을 잃고 땅에 쓰러집니다.'),
(9999, 6, 0, '으... 어지러워...'),
(9999, 7, 0, '으으.'),
(9999, 8, 0, '으으.'),
(10096, 0, 0, '검은무쇠 제국에 반하는 범죄를 저질렀으므로 사형을 선고한다!'),
(10096, 1, 0, '타우릿산의 아드님들께서 너희가 법의 심판장에서 종말을 맞이하는 모습을 지켜볼 것이다!'),
(10096, 2, 0, '분노를 참지 말고 처단하라!'),
(10096, 3, 0, '하하! 그냥 죽일 줄 알았더냐!'),
(10096, 4, 0, '진정한 처형이 너를 기다리고 있도다.'),
(10096, 5, 0, '잘 해치웠다!'),
(10162, 0, 0, '잘 됐군. 내 군단에게 먹일 보잘것없는 벌레들이 제시간에 도착한 것 같구나. 어서 오너라, 나약한 생명체들아!'),
(10162, 1, 0, '피 한 방울도 남김없이 먹어 치워라, 아이들아. 놈들의 영혼을 잡아먹어라!'),
(10162, 2, 0, '어리석은 것들... 부상당한 녀석을 죽여라!'),
(10162, 3, 0, '믿을 수가 없군!'),
(10162, 4, 0, '모두 헛수고일 뿐이야. 아무도 우리를 막진 못한다!'),
(10162, 5, 0, '내가 직접 나서면 너희의 가죽으로 장화를 만들어 버리겠다. 어서 저 녀석들을 없애란 말이야!'),
(10162, 6, 0, '냉기의 숨결을 써, 이 바보 녀석!'),
(10162, 7, 0, '이건 말도 안 돼!!! 렌드, 이 벌레들을 해치우도록 하라.'),
(10162, 8, 0, '대족장이 곧 너희를 처리할 것이니 각오해라!'),
(10162, 9, 0, '내 힘을 맛보라!'),
(10162, 10, 0, '너의 승리는 오래 가지 못한다. 얼라이언스와 호드의 시대도 점차 끝나고 있어! 우리가 다음에 또 만나면 그게 바로 끝이 될 것이다.'),
(10162, 11, 0, '나약한 생명체들이 쓰러졌다! 검은바위 부대의 새로운 시대가 도래하였느니라!'),
(10162, 12, 0, '시간이 너의 적인 이 세계에서 그 시간이 나의 가장 위대한 동료다. 네가 네 맘대로 조종하고 있다고 믿는 인생이란 놀이가 사실은 널 갖고 놀고 있는 것이지. 그러니까 내 말은...'),
(10162, 13, 0, '흐흐흐흐... 게임을 시작하자!'),
(10162, 14, 0, '아! 영웅들... 아주 끈질긴 족속이지. 바로 이곳에서 너희 동료가 내게 도전했다가 그 대가를 치렀다. 이제 녀석은 날 섬기지.'),
(10181, 0, 0, '멍청한 것들! 흑요암이여, 일어나라! 그리고 침입자를 처치하라!'),
(10184, 4, 0, '%s|1이;가; 숨을 깊게 들이쉽니다.'),
(10220, 0, 0, '%s|1이;가; 거칠게 으르렁거리더니 쓰러집니다. 그때 검은바위 첨탑의 전당 안에서 끔찍한 비명이 울려 퍼집니다. 무언가... 몹시 화가 난 것 같습니다.'),
(10262, 0, 0, '보물 숨겨진 장소 비쥬가 알아.'),
(10262, 0, 1, '꽤액!! 콜록... 콜록! 담배를 끊어야겠군!'),
(10262, 0, 2, '보물? 키블러에게 물어봐! 꽤액!'),
(10262, 0, 3, '모두 첨탑으로 가서는 돌아오지 않아... 비쥬처럼!'),
