(11444, 0, 0, '우어어!!! 나 $r 죽일거야!'),
(11444, 0, 1, '너 내가 죽인다!'),
(11444, 0, 2, '너 박살내 버린다!'),
(11444, 1, 0, '%s|1이;가; 격노합니다!'),
(11448, 0, 0, '우어어!!! 나 $r 죽일거야!'),
(11448, 0, 1, '너 내가 죽인다!'),
(11448, 0, 2, '너 박살내 버린다!'),
(11451, 0, 0, '%s|1이;가; 격노합니다!'),
(11469, 0, 0, '%s|1이;가; 격노합니다!'),
(11486, 0, 0, '감히 엘드레탈라스의 신성함을 더럽히는 게 누구냐? 썩 나와라, 겁쟁이들아!'),
(11496, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(11502, 0, 0, '보라! 불의 군주 라그나로스 님을! 태초부터 존재하셨던 분이다. 경배하라! 최후를 맞기 전 그분 앞에 무릎을 꿇어라!'),
(11502, 1, 0, '아직 때가 아닌데 나를 너무 일찍 깨웠도다, 이그젝큐투스, 대체 왜 이런 불경한 짓을 저지른 게냐?'),
(11502, 2, 0, '주인님! 저 필멸의 이단자들이 감히 주인님의 성소에 침입해 비밀을 훔치려 했나이다!'),
(11502, 3, 0, '바보 같은 놈! 이 성스러운 곳에 저 벌레 같은 것들이 날뛰도록 내버려두었더란 말이냐? 날 실망시켰다, 이그젝큐투스! 그 대가를 치러라!'),
(11502, 4, 0, '이제 너희 놈들 차례다! 이 라그나로스의 힘을 찾으러 왔다 했으니 내 몸소 보여주리라!'),
(11502, 5, 0, '나오너라, 나의 부하들아! 주인을 보호해라!'),
(11502, 6, 0, '누구도 살아있는 불꽃을 꺾을 수는 없다! 나타나라! 불의 신하들이여! 나오너라! 증오의 피조물들이여! 네 주인이 부르노라!'),
(11502, 7, 0, '불의 세례를 받아라!'),
(11502, 8, 0, '설퍼론의 유황 맛을 보아라!'),
(11502, 9, 0, '죽어라, 벌레야!'),
(11502, 10, 0, '설퍼론의 유황 맛을 보아라!'),
(11582, 0, 0, '바로 이런 걸 소환해서는 안 되는 거야. 약해빠졌잖아. 철퇴로 한 대만 치면 뼛조각이 날아다닐걸.'),
(11582, 0, 1, '흠, 이런 건 풍경으로나 써야겠군. 이런 것이야말로 전투가 한창일 때 소환하면 절대로 안 되는 것이니까 기록해 놓도록!'),
(11582, 0, 2, '마지막 것보다는 좀 낫군. 다른 것들처럼 골격 구조가 약하긴 하지만! 이런 걸 소환해야 일이 제대로 되는 거야.'),
(11583, 0, 0, '잘했다! 적들의 사기가 떨어지고 있다! 검은바위 첨탑의 군주에게 도전한 대가를 치르게 해주자!'),
(11583, 0, 1, '설퍼론의 유황 맛을 보아라!'),
(11583, 0, 2, '불타라! 활활!'),
(11583, 1, 0, '말도 안 돼! 일어나라! 다시 한 번 너희 주인을 섬겨라!'),
(11583, 2, 0, '바보같은 $n! 이제 나머지도 모두 처치해 주마!'),
(11583, 3, 0, '이럴 수가! 이곳의 주인은 나다! 우리에 비하면 너희는 아무것도 아니다! 아무것도!'),
(11583, 4, 0, '네가 마법사냐? 마법을 가지고 장난칠 상대를 고를 때는 좀 더 신중했어야지...'),
(11583, 5, 0, '전사들이로군, 네가 그보다 더 강하게 내려 칠 수 있다는 걸 알고 있다! 어디 한번 제대로 쳐 보란 말이다!'),
(11583, 6, 0, '드루이드 녀석, 그 바보 같은 변신을 했다고 내가 모를 줄 알았더냐? 받아라!'),
(11583, 7, 0, '사제야, 그렇게 치유를 계속할 테냐?! 그럼 어디 좀 더 재미있게 만들어 줄까!'),
(11583, 8, 0, '성기사여... 네 목숨은 여러 개라고 하던데 어디 한번 보여 다오.'),
(11583, 9, 0, '주술사, 네 놈의 토템이 얼마나 쓸모 있는지 한번 보자!'),
(11583, 10, 0, '흑마법사여, 네가 이해하지도 못하는 마법을 가지고 장난을 쳐서야 쓰나... 바로 이런 꼴이 되어 버렸지 않는가!'),
(11583, 11, 0, '사냥꾼 놈에다 그 장난감 같은 총이라니, 정말 거슬리는구나!'),
(11583, 12, 0, '도적들인가? 숨어 다니지만 말고 나와서 나와 맞서라!'),
(11583, 13, 0, '죽음의 기사여... 당장 이리 와라!'),
(11596, 0, 0, '아, 신비한 코도 소리로군. 난 코도가 땅을 울리는 게 참 좋단 말이야. 날 위해 그 짐승을 살펴봐 주게.'),
(11596, 0, 1, '어이, 저기 코도를 조심하라고! 자네가 코도를 살펴본다면, 자넬 믿어주지!'),
(11596, 0, 2, '저 코도 정말 예쁘군, 잠시만... 내 안경이 어디 있지? 음... 자네가 날 위해 저 코도를 살펴봐 줘야겠어.'),
(11672, 0, 0, '주인이 위험에 처한 것을 본 %s|1이;가; 죽지 않으려고 몸부림칩니다!'),
(11677, 0, 0, '나 여기 있지롱! 얼음이빨 광산은 이 스니블 님의 것이다!'),
(11680, 0, 0, '절대로 검은무쇠 부족을 이길 순 없다.'),
(11680, 0, 1, '죽을 시간이다, $C 녀석.'),
(11680, 0, 2, '검은무쇠 드워프의 힘을 느껴봐라!'),
(11747, 0, 0, '%s|1이;가; 격노합니다!'),
(11830, 0, 0, '네놈을 처치하는 것쯤이야 식은 죽 먹기지.'),
(11830, 0, 1, '트롤의 주술이 가장 강력하다!'),
(11830, 0, 2, '그 두개골로 우리의 제단을 장식하겠다!'),
(11830, 0, 3, '두꺼비가 되고 싶어 제 발로 찾아 왔구나!'),
(11830, 0, 4, '위대한 부두교 마법의 맛을 봐라!'),
(11830, 0, 5, '피에 굶주린 내 도끼를 받아라!'),
(11830, 0, 6, '곧 저승으로 보내주겠다!'),
(11831, 0, 0, '네놈을 처치하는 것쯤이야 식은 죽 먹기지.'),
(11831, 0, 1, '트롤의 주술이 가장 강력하다!'),
(11831, 0, 2, '그 두개골로 우리의 제단을 장식하겠다!'),
(11831, 0, 3, '두꺼비가 되고 싶어 제 발로 찾아 왔구나!'),
(11831, 0, 4, '위대한 부두교 마법의 맛을 봐라!'),
(11831, 0, 5, '피에 굶주린 내 도끼를 받아라!'),
(11831, 0, 6, '곧 저승으로 보내주겠다!'),
(11832, 0, 0, '네가 수집한 조각을 통해 악몽이 시작되는 곳을 찾을 것이다, $n. 그곳에서 꿈속의 갈라진 틈을 통해 에라니쿠스를 끌어낼 생각이다. 우리가 이 세계로 불러내려는 것은 바로 악몽의 화신이니 마음을 굳게 먹어라.'),
(11832, 1, 1, '엘룬아라 호수 위로 틈이 열릴 것이다. 준비하라, $n. 에라니쿠스가 우리 세계로 들어오면 혼돈과 싸움이 끊이지 않을 것이니라.'),
(11832, 2, 2, '그는 말퓨리온 님의 현신을 파괴하고자 수단과 방법을 가리지 않을 것이다. 그것만은 결단코 막아야 한다... 우린 티란데 님께서 도착할 때까지 그 괴물을 붙잡고 시간을 끌어야 한다.'),
(11832, 3, 3, '밤의 안식처를 수호하라, 영웅이여...'),
(11832, 4, 4, '이 악마! 세나리우스의 힘을 보여 주마!'),
(11832, 5, 5, '뛰어야 벼룩인 게 누구더냐? 물론 너는 우리가 말퓨리온 님에 이어 너까지 소환할 거라고는 생각도 못했겠지? 자, 구원받을 시간이다, 에라니쿠스. 너의 광기와 타락을 정화하도록 하마.'),
(11832, 6, 6, '서둘러라, $n! 몸을 숨길 만한 곳을 찾아야 한다!'),
(11832, 7, 7, '부디 우리 백성들을 지켜다오.'),
(11832, 8, 8, '곧 끝날 것이오, 에라니쿠스. 몸조심하시오, 고대의 존재여.'),
(11832, 9, 9, '우리는 밤의 안식처를 떠날 것이다, 영웅이여. 날 찾으려거든 숲으로 오너라.'),
(11832, 10, 10, '$n, 나를 따라오라. 저기서 조금만 돌면 바로 호수니라.'),
(11832, 11, 11, '내 옆에 바짝 붙으라. 아무 일 없도록 내가 지켜주겠다.'),
(11832, 12, 12, '말퓨리온!'),
(11832, 13, 13, '말퓨리온, 온통 악몽만 꾸었어. 도대체 에메랄드의 꿈속에서 무슨 일이 일어나고 있는 거지? 무엇 때문에 그렇게 끔찍한 일이 벌어진 걸까?'),
(11832, 14, 14, '나 역시 많은 것이 느껴져, 말퓨리온. 암울한 시대가 다가오고 있어.'),
(11832, 15, 15, '말퓨리온, 지나치게 앞서 가는군. 현재 아제로스 자손들 사이에서 평화는 거의 찾아볼 수가 없는 지경일세. 그나저나 우리 아버지는 어떤가? 자네 형제는? 뭐 새로운 소식은 없나?'),
(11832, 16, 16, '오랜 친구여, 부디... 잘 가게...'),
(11832, 17, 17, '숲으로 돌아가자.'),
(11840, 0, 0, '%s|1이;가; 격노합니다!'),
(11899, 0, 0, '경비병!'),
(11900, 0, 0, '경비병!'),
(11901, 0, 0, '경비병!'),
(11915, 0, 0, '안 해! 나 호드 안 도와!'),
(11915, 0, 1, '채찍 때문에 나 화나!'),
(11915, 0, 2, '채찍 빼앗아 버릴래!'),
(11915, 0, 3, '너 채찍으로 감아버릴래!'),
(11915, 0, 4, '너 나쁜 $r|1이야;야;!'),
(11915, 0, 5, '나 너무 화나!'),
(11915, 1, 0, '알았어! 알았어! 나 $r|1이;가; 시키는 거 다 할게!'),
(11915, 1, 1, '제발 채찍질 나 하지마! 호드 돕잖아!'),
(11915, 1, 2, '아파! 그만해!'),
(11915, 1, 3, '그만 아플래! 나 너 도울게!'),
