(11946, 0, 0, '스톰파이크 쓰레기들이 감히 나의 요새에 쳐들어와?! 모조리 쳐라!'),
(11946, 1, 0, '감히 서리늑대 사령관을 요새 밖으로 끌어내시겠다? 말도 안 되는 소리!'),
(11946, 2, 0, '스톰파이크 약골들아, 나의 요새로 와서 한 판 붙어보자! 그럴 만한 용기가 있다면!'),
(11946, 3, 0, '너무 추워서 공격도 제대로 못하는군!'),
(11946, 3, 1, '오늘 황천에서 네 선조를 만나게 될 줄 알아라!'),
(11946, 3, 2, '제 발로 알터랙 계곡을 떠나지 않겠다면 우리 서리늑대 부족이 그렇게 해주겠다!'),
(11946, 3, 3, '너희는 절대로 서리늑대 부족을 물리칠 수 없다!'),
(11946, 3, 4, '너희는 막강한 우리 호드에게 상대도 안 돼!'),
(11946, 3, 5, '한 놈도 살려두지 마라!'),
(11947, 0, 0, '죽어라! 이 알터랙 계곡에 너희 종족이 발붙일 자리는 없다!'),
(11947, 1, 0, '내가 그 정도에 속아 넘어갈 것 같으냐, 어리석은 놈들! 내게 맞서고자 한다면 내가 있는 곳에서 내 방식대로 싸워야 할 것이다.'),
(11947, 2, 0, '바로 지금이 공격할 때다! 호드를 위하여!'),
(11948, 0, 0, '스톰파이크의 병사들이여, 그대들의 사령관이 공격받고 있노라! 도움이 필요하다! 어서 와서 이 비열한 서리늑대 개들을 처치하라!'),
(11948, 1, 0, '절대로 날 참호 밖으로 끌어낼 수 없을 것이다, 이 야만인 녀석들!'),
(11948, 1, 1, '어디 한 번 그 얄팍한 전술을 다시 시도해 보시지그래, 얼간이 녀석들! 왜, 이제는 너무 겁이 나나?'),
(11948, 2, 0, '절대로 날 참호 밖으로 끌어낼 수 없을 것이다, 이 야만인 녀석들!'),
(11948, 2, 1, '주먹이 솜방망이로군! 가서 토끼 잡는 연습이나 좀 더 한 다음에 오시오.'),
(11948, 2, 2, '우리는 절대 흔들리지 않을 것이오!'),
(11948, 2, 3, '너희 같은 오합지졸로는 나를 쓰러뜨릴 수 없다!'),
(11948, 2, 4, '우리 얼라이언스가 승리할 거요!'),
(11948, 2, 5, '스톰파이크 부족은 아무에게도 굴복하지 않소. 특히 호드에게는!'),
(11948, 2, 6, '고작 이 정도냐?'),
(11948, 3, 0, '포로는 필요 없다! 우리 땅에서 이교도들을 몰아내라!'),
(11981, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(11982, 0, 0, '%s|1이;가; 살기를 띤 듯한 광란 상태에 빠집니다!'),
(12017, 0, 0, '너희 같은 놈들이 올 곳은 아닌데... 죽음을 자초했구나!'),
(12017, 1, 0, '약삭빠르구나... 하지만 난 쉽게 무너지지 않는다!'),
(12018, 0, 0, '무모한 놈들! 감히 누가 살아있는 불꽃의 후예에게 덤비느냐!'),
(12018, 1, 0, '보호의 룬이 파괴됐다! 형제들이여, 이단자들을 찾아 처치하라!'),
(12018, 2, 0, '재로 돌아가라!'),
(12018, 3, 0, '재로 돌아가라!'),
(12018, 4, 0, '이럴 수가! 그만! 제발 그만! 내가 졌다! 내가 졌어!'),
(12018, 5, 0, '보라! 불의 군주 라그나로스 님을! 태초부터 존재하셨던 분이다. 경배하라! 최후를 맞기 전 그분 앞에 무릎을 꿇어라!'),
(12018, 6, 0, '주인님! 저 필멸의 이단자들이 감히 주인님의 성소에 침입해 비밀을 훔치려 했나이다!'),
(12046, 0, 0, '%s|1이;가; 격노합니다!'),
(12056, 0, 0, '%s|1이;가; 라그나로스를 위한 마지막 임무를 수행합니다...'),
(12116, 26, 0, '안녕히 가십시오.'),
(12121, 0, 0, '%s|1이;가; 격노합니다!'),
(12122, 0, 0, '%s|1이;가; 격노합니다!'),
(12136, 0, 0, '그롬골로 가는 비행선이 방금 도착했습니다! 가시덤불 골짜기로 가시는 분들 모두 타세요!'),
(12152, 20, 0, '그리고 얼마 후 어떤 짐승을 보게 되었다. 깃털은 분명 올빼미의 것이지만, 곰의 힘과 의지가 있었노라.'),
(12379, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(12423, 0, 0, '감사합니다! 감사합니다, 사제님! 이제 성스러운 빛이 함께하니 저 멀록들과 맞설 수 있겠습니다!'),
(12423, 1, 0, '안녕히 가십시오. 성스러운 빛이 항상 함께하시기를.'),
(12423, 2, 0, '아, 사제님. 제때에 와주셨군요. 정말 감사합니다.'),
(12427, 0, 0, '감사합니다! 감사합니다, 사제님! 이제 성스러운 빛이 저와 함께하니 저 웬디고들과 맞설 수 있겠어요!'),
(12427, 1, 0, '안녕히 가십시오. 성스러운 빛이 항상 함께하시기를.'),
(12427, 2, 0, '아, 사제님. 제때에 와주셨군요. 정말 감사합니다.'),
(12428, 0, 0, '고맙네! 고마워, 사제여! 이제 힘이 되돌아왔으니 저 놀 무리를 해치울 수 있겠군!'),
(12428, 1, 0, '잘 가게. 어둠의 가호가 항상 함께하기를!'),
(12428, 2, 0, '아, 사제님. 제때에 와주셨군요. 정말 감사합니다.'),
(12429, 2, 0, '아, 사제님. 제때에 와주셨군요. 정말 감사합니다.'),
(12430, 2, 0, '아, 사제님. 제때에 와주셨군요. 정말 감사합니다.'),
(12435, 0, 0, '대가를 꼭 치르게 해주마!'),
(12435, 1, 0, '바보들아! 이 알들이 얼마나 귀한 것인데!'),
(12435, 2, 0, '더 이상은 안 돼! 죗값은 너희들 머리로 받겠다!'),
(12435, 3, 0, '내가 나락으로 떨어질 때 너희 모두 끌고 가겠다!'),
(12577, 0, 0, '경비병!'),
