(12616, 0, 0, '경비병!'),
(12617, 0, 0, '경비병!'),
(12636, 0, 0, '경비병!'),
(12717, 0, 0, '자네, 준비가 끝난 게 확실한가? 우리를 도와 줄 자네 동료가 모이지 않으면 분명히 패배하게 될 걸세.'),
(12717, 1, 0, '힘든 싸움이 될 걸세, $n. 내 뒤에 바짝 붙어 따라오라고!'),
(12717, 2, 0, '이게 그 화로라네, $n. 꺼 버리게나. 보르샤는 그 누구에게도 찬미를 받을 자격이 없는 괴물에 불과해!'),
(12717, 3, 0, '이제 기다려야 하네. 곧 있으면 보르샤가 낌새를 알아차리고 나타날 테니까...'),
(12717, 4, 0, '경계를 늦추지 말게, $n!'),
(12717, 5, 0, '잠깐 쉴 틈이 생길 것 같군그래. 하지만 난 보르샤와 직접 맞붙기 전까지는 절대로 포기하지 않을 걸세!'),
(12717, 6, 0, '우리가 해냈군!'),
(12717, 7, 0, '내 깊은 감사의 마음을 전하네. 정말 고맙네.'),
(12717, 8, 0, '나는 얼마간 이 지역을 좀 더 정찰하면서 치안안전에 전력을 기울여야겠네.'),
(12717, 9, 0, '자네는 조람가르로 돌아가서 전쟁노래 길잡이에게 우리의 성공을 보고하도록 하게나.'),
(12740, 0, 0, '경비병!'),
(12858, 0, 0, '모두 준비됐나?'),
(12858, 1, 0, '좋아, 가자!'),
(12858, 2, 0, '모두 준비하라. 저기만 돌아가면 은빛날개 전초기지다.'),
(12858, 3, 0, '은빛날개 전초기지는 우리 것이다!'),
(12858, 4, 0, '가서 전초기지를 점령했다고 보고하라. 우리는 여기 남아있겠다.'),
(12918, 0, 0, '썩은나무 일족에게 너 같은 놈은 한낱 날벌레에 불과하다! 죽어라!'),
(12918, 1, 0, '말도 안 돼! 네놈 따위가 썩은나무 일족보다 강하다니! 안 돼!'),
(12920, 0, 0, '살았다! 정말 고맙습니다, 의사 선생님!'),
(12920, 0, 1, '만세! 살았다!'),
(12920, 0, 2, '달콤한 죽음이여... 나를 데려가주오...'),
(12921, 0, 0, '%s|1이;가; 깃발을 공격합니다!'),
(12923, 0, 0, '살았다! 정말 고맙습니다, 의사 선생님!'),
