(12925, 0, 0, '살았다! 정말 고맙습니다, 의사 선생님!'),
(12939, 0, 0, '살았다! 정말 고맙습니다, 의사 선생님!'),
(12939, 0, 1, '만세! 살았다!'),
(12939, 0, 2, '달콤한 죽음이여... 나를 데려가주오...'),
(12997, 0, 0, '상자 안으로! 내 귀여운 것들! 옳지. 하나씩 차례대로 들어가.'),
(13020, 0, 0, '너무 늦었어! 네파리우스의 타락이 뿌리를 내려... 난... 나 자신을 통제할 수가 없어.'),
(13020, 1, 0, '부탁이다. 도망쳐라! 내가 자제력을 완전히 잃기 전에! 내 가슴 속에 검은 불길이 끓고 있다! 내뿜어야만 해!'),
(13020, 2, 0, '불! 파괴! 죽음! 군주의 분노를 두려워하라! 안 돼! 난 싸워야해! 알렉스트라자여, 도와주소서! 난 싸워야해!'),
(13020, 3, 0, '네파리우스가 나를 강하게 만들었다. 내 혈관에는 네파리우스의 증오와 검은바위 부족의 분노가 흐르고 있다!'),
(13020, 4, 0, '용서해라! 나도 죗값을 치르게 될 것이다!'),
(13083, 0, 0, '너희의 모든 노력은 헛수고다. 이미 세계수의 힘을 빨아들이기 시작했으니! 곧 너희 세계의 심장은 더 이상 뛰지 않으리라!'),
(13177, 0, 0, '경비병!'),
(13602, 0, 0, '우워어어어어!'),
(14020, 0, 0, '%s|1이;가; 살기를 띤 듯한 광란 상태에 빠집니다!'),
(14020, 1, 0, '%s|1이;가; 가죽을 빛내며 주춤 물러섭니다.'),
(14224, 0, 0, '알 수 없는 생명체 발견... 분석 중...'),
(14224, 0, 1, '목표물 상실... 델타 형식으로 검색 재시작'),
(14224, 0, 2, '생명체 검색 중... 목표물 찾을 수 없다...'),
(14267, 0, 0, '우어어!!! 나 $r 죽일거야!'),
(14267, 0, 1, '너 내가 죽인다!'),
(14267, 0, 2, '너 박살내 버린다!'),
(14305, 1, 0, '와, 세상에 있는 모든 다이아몬드 중에 제일 크겠는데요!'),
(14305, 2, 0, '게다가 마그니 폐하의 초상화랑 똑같이 생겼어요! 정말 스스로 이렇게 되신 건가요?'),
(14305, 3, 0, '어... 별로 좋은 생각은 아니었네요...'),
(14305, 4, 0, '국왕 폐하를 잃어서 정말 슬프시겠어요, 아저씨. 하지만, 어떻게 보면 그분은 이제 영원히 아저씨 곁에 있는 거라고요!'),
(14305, 5, 0, '우와, 아저씨는 제가 지금까지 본 나이트 엘프랑 정말 다르게 생기셨어요!'),
(14305, 6, 0, '보육원 원장님이 드루이드는 새나 표범, 곰으로 변신할 수 있다고 하셨어요. 하지만 아저씨 모습은 마치 그 동물들을 다 합쳐 놓은 것 같아요!'),
(14305, 7, 0, '아하, 무슨 생각이신지 알겠어요. 드루이드 변신을 전부 합쳐서 초 강력한 변신을 완성하시려는 거죠?!'),
(14305, 8, 0, '제가 에메랄드의 꿈이란 곳을 좋아할 것 같진 않네요. 제가 거북이로 변하거나 하면 어떡해요? 물론 동물이라도 좋으니 날개는 달아 보고 싶지만...'),
(14305, 9, 0, '우와아! 난 새 인간이다!'),
(14321, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(14322, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(14323, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(14325, 0, 0, '나 있는 한 누구도 왕 위협할 순 없다! 우어어! 받아라!'),
(14325, 1, 0, '이 약골들 쓰러뜨리는 걸 도와라!'),
(14325, 2, 0, '%s|1이;가; 공격을 모두 되받아치기 시작합니다!'),
(14326, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(14354, 0, 0, '열쇠를 가지려면 먼저 날 잡아야 할걸!'),
(14354, 1, 0, '따라올 테면 따라와 봐! 뒤도 안 돌아보고 튈 테니까!'),
(14354, 2, 0, '왜 날 해치려 들까? 우린 사이 좋은 친구가 될 수도 있는데 말이야!'),
(14354, 3, 0, '으앙! 이 푸실린을 울리다니!'),
(14354, 4, 0, '내 깜찍한 친구들한테 인사나 하시지!'),
(14368, 0, 0, '이방인이여, 그는 죽었으니 아무 말도 해주지 않으리라 생각하오만...'),
(14368, 1, 0, '나는 개인적으로 토르텔드린 왕자가 하는 일에 관여하지 않았소. 예외적으로 하이 엘프를 자신의 영토에 들인 것은 토르텔드린 왕자였소. 유감스럽게도 나는 토르텔드린 왕자에게 의문을 제기할 입장이 못 되오. 조금이나마 왕자를 두둔하자면, 윈탈루스를 즉시 불태워 죽이지는 않았다는 거지.'),
(14368, 2, 0, '더는 이목을 끌어서는 안 되오. 당신에게 윈탈루스를 찾으라고 지시한 자들에게 돌아가서 아무것도 찾을 수 없었다고 전하시오. 그런 다음 날 다시 찾아오시오. 그 말을 전하는 순간 난 당신이 할 일을 마쳤다는 걸 알 수 있으니까 말이오. 그러면 죽은 윈탈루스의 비밀을 알려주리다.'),
(14435, 0, 0, '나의 엄청난 위력에 정신을 차릴 수 없을 것이다! 하찮은 미물 주제에 감히 내 영역을 침범하려 하다니 정말 가소롭구나!'),
(14444, 1, 0, '와, 진짜 밴시 여왕님이세요? 훨씬 더 키가 크실 줄 알았는데!'),
(14444, 2, 0, '사람들이 그러는데 여왕님이랑 대족장님이랑 싸우셨고, 그래서 여왕님이 호드를 버릴 거래요. 진짜 그러실 건가요?'),
(14444, 3, 0, '그럼 사람들 얘긴 사실이 아니군요? 와, 정말 다행이다! 여왕님 같은 분이랑 적이 되는 건 생각하기도 싫어요, 여군주 실바나스 님.'),
(14444, 4, 0, '이런 식으로 대부족장님을 기리는군요!'),
(14507, 1, 0, '증오의 똬리를 틀 시간이다!'),
(14507, 2, 0, '이제서야... 안식을...!'),
(14509, 0, 0, '시르밸라시여, 분노를 채워 주소서!'),
(14509, 1, 0, '학카르의 구속이 끝났다! 이젠 평안히 잠들리라!'),
(14510, 0, 0, '시르밸라시여, 분노를 채워 주소서!'),
(14627, 0, 0, '내 큰 주먹 맛이 어떠냐!'),
(14688, 0, 0, '내 소개가 그 정도밖에 안 되오, 가이르 부인? 자, 사람들 입에 그렇게 오르내리던 이방인이 대체 누굽니까?'),
(14688, 1, 0, '최대한 짧고 간결하게 이야기 하마. 이리 와서 그냥 죽어라. 네가 한 짓에 대해 내가 해줄 수 있는 건 그것뿐이다. 이 신성한 전투의 장을 더럽힌 대가다.'),
(14688, 2, 0, '리치 왕의 이름을 더럽힌 대가다!'),
(14750, 0, 0, '화염에 완전히 휩싸인 %s|1이;가; 광기 가득한 눈빛을 번득입니다!'),
(14821, 0, 0, '%s|1이;가; 격노합니다!'),
(14822, 0, 0, '내게로 오라! 운명이 준비해둔 미래를 직접 보라!'),
(14822, 0, 1, '와서 나의 예언을 들으라. 불확실한 미래가 수정 거울처럼 분명해지리라.'),
(14822, 0, 2, '두려워 말라! 길을 아는 자, 운명에 맞설 수 있다.'),
(14822, 0, 3, '운명을 놓고 우물쭈물할 시간이 있는가? 그만큼 불확실한 미래가 늘어날 뿐인데...'),
(14823, 0, 0, '어서 오세요! 다크문 축제에 오신 것을 환영합니다! 모험을 원하시나요? 이국적이고 신비한 보물을 찾고 계신가요? 그렇다면 더 이상 찾아다니지 마십시오! 여기가 바로 여러분이 찾던 곳이니까요! 축제의 모든 것을 마음껏 즐기십시오! 이번 주 내내 이곳에서 열리니까 친구들과 주변의 모두에게 꼭 귀띔해 주세요!'),
(14823, 0, 1, '아제로스 최고의 쇼에 오신 것을 환영합니다!$B$B어서 와서 마음껏 즐기시기 바랍니다. 즐길 거리와 볼거리가 가득합니다! 이 신비하고 광활한 세계에서 다크문 축제 유랑단이 발견한 온갖 놀라운 물건들을 구경하세요! 아이들이라면 모두 좋아할 재미있는 물건들을 아낌없이 준비해 놓았습니다!'),
(14823, 0, 2, '왔습니다! 다크문 축제가 왔어요! 그 어느 때보다 더욱 멋진 모습으로! 여러분에게 즐거움을 선사하기 위해 비용 따위는 아끼지 않고 전 세계를 유랑하며 진귀하고 놀라운 물건들을 모아 왔습니다. 오늘은 행운이 가득한 날! 남녀노소 누구나 다크문 축제에서 흥겨운 시간을 보낼 수 있습니다! 다크문 축제 상품권이 있다면 잊지 말고 겔바스 그림게이트를 찾아가세요! 놀라운 상품이 기다리고 있으니까요!'),
(14828, 0, 0, '상품권이 다섯 개 있든 오백 개 있든 아무 상관이 없지, 친구... 꽝은 없으니까!'),
(14828, 0, 1, '신비한 상품들이 모험가들을 기다리고 있다네. 어서 오게, 어서!'),
(14828, 0, 2, '상품! 이리 와서 상품 타 가게! 다크문 축제 상품권을 귀한 물건으로 바꿔 가라고!'),
(14828, 0, 3, '상품권이 있나? 이리 와서 다크문 축제 상품권을 교환하게! 놀랍고 진귀한 상품들이 자네를 기다리고 있다네!'),
(14834, 0, 0, '자만심은 세상의 종말을 불러올 뿐이다. 오너라! 건방진 피조물들이여! 와서 신의 진노에 맞서 보아라!'),
(14834, 1, 0, '도망쳐 봐야 소용없다, 어리석은 생명체여!'),
(14834, 2, 0, '감히 학카리 성지에 발을 들여놓는 게냐? 학카르의 종들이여, 저 이단자들을 처단하라!'),
(14834, 3, 0, '학카르의 종들아, 너희가 섬기는 신의 목소리를 들어라! 이 신성하고 거룩한 사원을 침입자들이 더럽히고 있나니! 피의 제단을 반드시 지켜야 한다. 죽여라! 전부!'),
(14841, 0, 0, '이리 와서 멋지게 한 방 쏴보십시오!'),
(14841, 0, 1, '총을 쏘면 상품을 드립니다! 총 쏴서 상품 가져가고 싶으신 분?'),
(14841, 1, 0, '탕탕탕! 이리 와서 한번 쏴보십시오!'),
(14841, 1, 1, '여러분, 제가 여기서 멋진 걸 나눠드리고 있습니다! 놓치지 마십시오!'),
(14841, 1, 2, '사격을 할 줄 알면 멋진 상품이 생깁니다!'),
(14841, 1, 3, '이리 오셔서 게임을 즐겨보십시오! 너무 간단해서 $c|1이라도;라도; 할 수 있습니다!'),
(14841, 1, 4, '사격 실력을 시험해 보십시오! 사격 실력을 시험해보십시오!'),
(14841, 1, 5, '사격 실력을 시험해보십시오! 상품도 얻을 수 있습니다!'),
(14847, 0, 0, '다크문 카드 한 벌을 다 모으셨다면, 이리 가져오십시오!'),
(14847, 0, 1, '다크문 축제 카드를 가지고 있는 분이라면 저를 찾아 주십시오.'),
(14847, 0, 2, '다크문 축제 카드를 가지고 있습니까? 자세히 알아볼 배짱이 있으면 물어보십시오!'),
