(15214, 28, 0, '얼라이언스가 겨울손아귀 요새를 점령했습니다!'),
(15214, 29, 0, '호드가 겨울손아귀 요새를 방어했습니다!'),
(15214, 30, 0, '호드가 겨울손아귀 요새를 점령했습니다!'),
(15214, 31, 0, '호드가 겨울손아귀 요새를 방어했습니다!'),
(15214, 32, 0, '호드가 겨울손아귀 요새를 점령했습니다!'),
(15214, 33, 0, '북동쪽 경비탑이 파손되었습니다!'),
(15214, 34, 0, '북동쪽 경비탑이 파괴되었습니다!'),
(15214, 35, 0, '남서쪽 경비탑이 파손되었습니다!'),
(15214, 36, 0, '남서쪽 경비탑이 파괴되었습니다!'),
(15214, 37, 0, '1번째 계급 달성: 하사관'),
(15214, 38, 0, '2번째 계급 달성: 부관'),
(15220, 0, 0, '뭐? 이런 하룻강아지 같은 놈이 감히 내게 덤비겠다고? 버릇을 고쳐주마!'),
(15233, 0, 0, '%s|1이;가; 격노합니다!'),
(15252, 0, 0, '%s|1이;가; 격노합니다!'),
(15263, 0, 0, '그토록 죽고 싶은가? 내 친히 그 소망을 이뤄주리라.'),
(15263, 0, 1, '그토록 죽고 싶은가? 내 친히 그 소망을 이뤄주리라.'),
(15263, 0, 2, '그토록 죽고 싶은가? 내 친히 그 소망을 이뤄주리라.'),
(15263, 1, 0, '네 죽음은 모두에게 본보기가 되리라!'),
(15263, 1, 1, '네 죽음은 모두에게 본보기가 되리라!'),
(15263, 1, 2, '네 죽음은 모두에게 본보기가 되리라!'),
(15263, 2, 0, '네 죽음은 모두에게 본보기가 되리라!'),
(15263, 3, 0, '이런다고 피할 수는 없다!'),
(15275, 0, 0, '너무나 큰 아픔을...'),
(15275, 1, 0, '영혼의 향연이 시작되리라...'),
(15275, 2, 0, '베클로어, 죽으면 안 돼!'),
(15276, 0, 0, '고통을 맛보리라...'),
(15276, 1, 0, '오너라, 미천한 족속들이여!'),
(15276, 2, 0, '오, 형제여... 안돼!'),
(15277, 0, 0, '%s|1이;가; 격노합니다!'),
(15299, 0, 0, '%s|1이;가; 느려지기 시작했습니다!'),
(15299, 1, 0, '%s|1이;가; 얼어붙고 있습니다!'),
(15299, 2, 0, '%s|1이;가; 단단하게 얼었습니다!'),
(15299, 3, 0, '%s|1이;가; 분해되기 시작합니다!'),
(15299, 4, 0, '%s|1이;가; 부서질 것 같습니다!'),
(15299, 5, 0, '%s|1이;가; 폭발합니다!'),
(15303, 0, 0, '몸무게가 많이 나간다고 걱정하지 마십시오. 이 대포는 아무리 무거워도 문제없습니다!'),
(15303, 1, 0, '대포 발사! 대포로 발사되고 싶으신 분?'),
(15303, 1, 1, '이리 오시면 날려 보내드리겠습니다!'),
(15303, 1, 2, '다크문 축제 지역의 반대쪽으로 갈 수 있습니다!'),
(15305, 0, 0, '네 놈의 배신은 네 명을 재촉할 뿐이다. 이 세계는 암흑 속에 빠지게 될 것이다!'),
(15307, 0, 0, '심연의 의회를 속이다니 그냥 두지 않겠다! 우리의 분노가 어떤 것인지 느끼게 해 주마!'),
(15339, 0, 0, '피 흘려라!'),
(15339, 0, 1, '피 흘려라!'),
(15339, 0, 2, '피 흘려라!'),
(15339, 1, 0, '피 흘려라!'),
(15339, 1, 1, '피 흘려라!'),
(15339, 1, 2, '피 흘려라!'),
(15339, 2, 0, '사막의 모래여, 일어나 태양을 가려주소서!'),
(15339, 3, 0, '너는 제거됐다.'),
(15339, 4, 0, '내가... 졌다.'),
(15339, 5, 0, '성벽이 무너졌다!'),
(15340, 0, 0, '%s|1이;가; 당신의 공포를 알아챕니다.'),
(15340, 1, 0, '%s|1이;가; 힘을 발산합니다!'),
(15341, 0, 0, '응보의 날이 다가왔다! 암흑이 적들의 마음을 지배하리라!'),
(15341, 1, 0, '더는 돌벽과 성문 뒤에서 기다릴 수 없다! 복수의 기회를 놓칠 수 없다. 우리가 분노를 터뜨리는 날 용족은 두려움에 떨리라.'),
(15341, 2, 0, '적에게 공포와 죽음의 향연을!'),
(15341, 3, 0, '스태그헬름은 흐느끼며 목숨을 구걸하리라. 그 아들놈이 그랬던 것처럼! 천 년의 한을 풀리라! 오늘에서야!'),
(15341, 4, 0, '판드랄! 때가 왔다! 에메랄드의 꿈속에 숨어서 기도나 올려라!'),
(15341, 5, 0, '건방진... 내 친히 너희를 처치해주마!'),
(15341, 6, 0, '공격하라! 놈들에게 혹독한 대가를 치르게 하라!'),
(15341, 7, 0, '짓밟아라! 놈들을 몰아내라!'),
(15341, 8, 0, '주저하지 마라! 놈들을 파괴하라!'),
(15341, 9, 0, '용사들이여, 전투를 멈추지 마라!'),
(15341, 10, 0, '시간 낭비할 가치도 없는 놈들!'),
(15341, 11, 0, '마지막 숨을 쉬어라!'),
(15341, 12, 0, '필멸의 존재여, 쓸데없이 참견한 대가를 치르리라. 주인님께서 거의 깨어나셨다. 완전히 일어나시는 날, 너희 세계는 끝이다.'),
(15367, 0, 0, '새겨둬라! 네가 죽어도 친구들은 금방 널 잊을 것이야!'),
(15369, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(15370, 0, 0, '%s|1이;가; $n|1을;를; 노려봅니다!'),
(15371, 0, 0, '$C|1이여;여;, 냉큼 저리 가세요!'),
(15371, 0, 1, '$n, 좀 성가시군요!'),
(15371, 1, 0, '성질 돋구지 마시오!'),
(15379, 0, 0, '판드랄, 언제나 이 말을 명심해라. 비탄에 빠져 신념이 흔들리지 않도록 해라. 만일 그렇게 된다면 네가 가는 곳마다 어둠이 깔리게 될 것이다, 나이트 엘프여. 그릇된 복수심으로는 결코 죄를 사할 수 없다.'),
(15379, 1, 0, '오늘의 희생을 잊지 마라, 나이트 엘프여. 우리 모두 이 괴물의 손아귀에서 얼마나 많은 고통을 받았는가!'),
(15379, 2, 0, '알렉스트라자시여, 제게 적들을 물리칠 수 있는 의지를 주소서!'),
(15380, 0, 0, '아나크로노스, 이런 식으로 주의를 끌면 자네와 젊은 드루이드가 문을 봉인할 시간을 벌 수 있을 것이네. 속전속결로 끝내야 하네. 자, 그럼 놈들이 혼돈의 마법에 어떻게 대응하는지 볼까?'),
(15380, 1, 0, '저들에게 푸른용군단의 분노를 느끼게 해 주소서! 말리고스시여, 저를 보호해 주소서!'),
(15380, 2, 0, '%s|1이;가; 알았다는 듯 고개를 끄덕입니다.'),
(15381, 0, 0, '서둘러야 하오. 그렇지 않으면 모두 끝장이오!'),
(15381, 1, 0, '지금이오, 스태그헬름! 지금 시작하겠으니 마법을 준비하시오!'),
(15381, 2, 0, '가까이 있으시오...'),
(15381, 3, 0, '아주 잠깐 시간의 흐름이 정지할 것이오! 지금부터 보호막을 소환할 것이니...'),
(15381, 4, 0, '주문을 끝내시오, 스태그헬름! 더 이상 수호의 문장을 유지할 수 없을 것 같소! 힘을 내시오!'),
(15381, 5, 0, '드디어... 끝났군, 대드루이드 스태그헬름이여. 비록 엄청난 희생이 있었지만 우리의 승리요.'),
(15381, 6, 0, '하지만 아직 할 일이 한 가지 남았소...'),
(15381, 7, 0, '스태그헬름, 이곳을 떠나기 전에 마지막으로 그대에게 줄 것이 하나 있소. 만약 그대가 이 저주받은 요새에 다시 들어와야 할 때가 오거든 흐르는 모래의 홀로 신성한 징을 울리시오. 그러면 보호막을 유지하고 있는 마력이 사라지고, 이 세계에 다시 한 번 안퀴라즈의 공포가 찾아올 것이오.'),
(15381, 8, 0, '대드루이드여, 어디로 가는 것이오? 자존심 때문에 우리의 관계를 저버릴 셈이오?'),
(15381, 9, 0, '이제 그대에게 해 줄 말은 다했소, 필멸의 존재여...'),
(15381, 10, 0, '%s|1이;가; 흐르는 모래의 홀을 판드랄 스태그헬름에게 건넵니다.'),
(15381, 11, 0, '%s|1이;가; 실망하여 고개를 가로 젓습니다.'),
(15381, 12, 0, '%s|1이;가; 무릎을 꿇고 부서진 홀 조각들을 줍습니다.'),
(15382, 0, 0, '나의 군대로는 퀴라지의 방어선을 뚫을 수가 없네. 용이여, 그대의 영검한 보호막을 칠 수 있을 만큼 가까이 갈 수가 없네.'),
(15382, 1, 0, '준비됐다, 용이여. 시작하라.'),
(15382, 2, 0, '고대의 존재께서 나의 손을 인도하시니... 잠에서 깨어나라! 깨어나서 이 저주받은 곳을 봉인하라!'),
(15382, 3, 0, '용이여, 나의 백성들에게 이런 참혹함을 보고 겪게 한 후에도 내가 또다시 짐을 떠맡을 것이라고 기대했는가? 물론 그대는 미쳤으니까 그럴 수도 있겠지.'),
(15382, 4, 0, '나는 실리더스나 퀴라지, 특히 빌어먹을 용들과는 더 이상 엮이고 싶지 않다!'),
(15382, 5, 0, '이런 공허한 승리는 내 아들의 영혼에게 안식을 줄 수 없다, 용이여. 나는 내 아들을 되찾을 것이다. 수천 년이 걸린다 할지라도 꼭 되찾고 말 것이다!'),
(15382, 6, 0, '%s|1이;가; 탈진하여 한쪽 무릎을 털썩 꿇습니다.'),
(15382, 7, 0, '%s|1이;가; 보호막으로 흐르는 모래의 홀을 집어던지자 박살 납니다.'),
(15387, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(15420, 0, 0, '좋아. 뭘 보여준다는 건지 확인해 보자고.'),
(15420, 1, 0, '$r, 이건 무슨 수작이지? 경고하는 데 날 건드릴 작정이라면 다시 한번 생각해 보는 게 좋을 거야. 난 그렇게 쉽게 쓰러질 드워프가 아니거든!'),
(15420, 2, 0, '케이다니스 씨, 당신이 지키고 있는 이 비전 성소들은 상당히... 흥미롭소이다. 유용한 정보 감사드리오.'),
(15471, 0, 0, '그들이 오고 있다. 자신의 몸을 지키도록 하라!'),
(15471, 1, 0, '내가 너는 꼭 마지막에 해치우겠다고 말했던 걸 기억하나, 라작스?'),
(15481, 0, 0, '호드가 서부불꽃 공성 작업장을 장악했습니다!'),
(15491, 0, 0, '언젠가는 죽음을 맞이할 가련한 존재여... 네 놈들이 무슨 짓을 저질렀는지 모르는구나! 그분의 의지가 실현될 것이다. 달숲은 파괴될 것이며, 그와 함께 말퓨리온 녀석도 죽음을 맞이할 것이다!'),
(15491, 1, 1, '%s|1이;가; 사악한 웃음을 터뜨립니다.'),
(15491, 2, 2, '레물로스... 넌 네 애비가 아니다, 벌레 같은 놈. 날 자극한다면 이 발톱으로 단숨에 숨통을 끊어 놓아주마. 샨도 스톰레이지를 넘겨라. 그러면 네 부하들과 함께 구차한 목숨을 연명할 수 있을 것이다.'),
(15491, 3, 3, '날 구원하겠다고? 애송이들이 배짱 하나는 두둑하구나. 구원이란 나의 신께서만 베푸실 수 있는 은혜인 것을!'),
(15491, 4, 4, '%s|1이;가; 격분하여 포효합니다.'),
(15491, 5, 5, '악몽의 종들아, 일어서라! 일어서서 너희의 광기로 이 세계를 파괴해라! 살아 있는 모든 생명을 없애라...'),
(15491, 6, 6, '너의 구세주는 어디 있지? 내 공격을 얼마나 버틸 수 있을까?'),
(15491, 7, 7, '레물로스, 이들이 내 앞에서 얼마나 쉽게 목숨을 잃어 가는지 똑똑히 지켜봐라. 아직 기회는 있다, 레물로스. 그 드루이드 녀석만 내게 넘기면, 이 모든 고통이 끝날 것이며 너는 이 학살을 막는 영웅이 될 것이다...'),
(15491, 8, 8, '내 부하들을 해치웠다는 건가? 그럼 어디 날 상대해 봐라, 필멸의 존재여!'),
(15491, 9, 9, '타오르고 있다! 고통... 불타는 고통이...'),
(15491, 10, 10, '왜? 왜 내게 이런 일이 일어나는 것인가... 어디에 있었는가, 티란데? 내가 여신님의 은총을 잃어갈 때 그대는 어디에 있었는가?'),
(15491, 11, 11, '느낄 수 있다... 느껴져... 다시 나를 쓰다듬으시는 엘룬 님의 손길이 느껴지는구나... 엘룬께서 내게 미소를 지으시는구나... 그래... 나는...'),
(15491, 12, 12, '%s|1이;가; 한쪽 무릎을 꿇습니다.'),
(15509, 0, 0, '%s|1이;가; 살기를 띤 듯한 광란 상태에 빠집니다!'),
(15509, 1, 0, '%s|1이;가; 분노에 휩싸여 광폭해집니다!'),
(15516, 0, 0, '성스러운 땅을 더럽힌 죗값을 받게 되리라. 고대의 법률은 거스를 수 없다! 침입자들을 처단하라!'),
(15516, 1, 0, '사형에 처하노라!'),
(15516, 2, 0, '최후의 그날까지!'),
(15537, 0, 0, '%s|1이;가; 격노합니다!'),
(15550, 0, 0, '당연한 결과였다...'),
(15550, 0, 1, '전리품이 하나 더 생겼군!'),
(15550, 1, 0, '나 정도 싸움꾼한테 무기는 장신구에 불과하지!'),
(15550, 2, 0, '아아! 언젠간 나도... 당할 날이 올 줄... 알았다...'),
(15550, 3, 0, '최후의 그날까지!'),
(15550, 3, 1, '최후의 그날까지!'),
(15551, 0, 0, '이것으로 끝이란 말인가?'),
(15551, 0, 1, '앞으로 어떻게 될 것인지...'),
(15608, 0, 0, '때가 왔다, 굴단! 너의 흑마법사들에게 좀 더 노력하라고 해라! 지금부터 어둠의 문이 열리고 너의 호드는 이 썩어빠진 불신의 세상으로 풀려날 것이다!'),
(15608, 1, 0, '때가 왔다, 굴단! 너의 흑마법사들에게 좀 더 노력하라고 해라! 지금부터 어둠의 문이 열리고 너의 호드는 이 썩어빠진 불신의 세상으로 풀려날 것이다!'),
(15608, 2, 0, '용사들이여! 나의 보호막이 약해진다!'),
(15608, 3, 0, '나의 힘을 어둠의 문에 집중해야 돼! 보호막을 지탱할 시간이 없다!'),
(15608, 4, 0, '보호막이 거의 없어졌다! 위험하다. 모든 일이 수포로 돌아갈지도 몰라!'),
(15608, 5, 0, '안 돼! 이런 나약한 무리에게 당하다니!'),
(15608, 6, 0, '용사들이여, 도와줘서 고맙다. 이제 굴단의 호드는 굶주린 메뚜기떼처럼 이 세상을 휩쓸 것이다. 내가 계획한 모든 것들이 마침내 실현될 것이다.'),
(15608, 7, 0, '호드의 용감한 오크들이여! 이 문은 그대들을 새로운 운명으로 안내할 것이다! 사냥감이 가득한 아제로스가 그대들을 기다리고 있도다!'),
(15608, 8, 0, '굴단 님은 진실을 말씀하신다! 우리는 즉시 돌아가서 형제들에게 이 소식을 알려야 한다! 차원문을 통해 돌아가도록!'),
(15623, 0, 0, '우리 일에 참견하는 것도 여기까지다. 필멸의 존재여! 나는 위대한 타락자 잔디비어스 님이시다!'),
(15623, 1, 0, '이 몸이 죽을 운명이라면 내 마지막 숨결과 함께 너도 같이 황천으로 데려가겠다!'),
(15623, 2, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(15625, 0, 0, '오너라, $n. 악몽의 결과가 어떤 것인지 보여 주마...'),
(15625, 1, 0, '악몽을 막을 수는 없다!'),
(15625, 2, 0, '%s|1이;가; $n의 마지막 생명력까지 모조리 짜내어 영혼을 집어삼킵니다.'),
(15628, 0, 0, '아주 오랫동안 나는 자신을 잃어버린 채 살았다... 악몽의 타락이 나를 지배해 왔지... 그리고 지금, 그대... 그대들이... 나를 구했다. 악몽의 손아귀에서 나를 해방시켰구나.'),
(15628, 1, 1, '허나... 말퓨리온, 세나리우스, 이세라... 그들은 아직도 다툼을 계속하고 있다. 그들에겐 내가 필요하니 난 다시 꿈으로 돌아가야 한다.'),
(15628, 2, 2, '티란데여, 나는 그대의 기도를 받을 가치가 없는 자라오. 그대는 진실로 빛의 천사로군. 부디 내가 지하굴로 돌아가서 꿈속으로 되돌아갈 수 있도록 도와주시오. 나 또한 말퓨리온처럼 날 기다리고 있는 사랑하는 이가 있소... 그녀에게 돌아가야 하오... 그녀를 지키러...'),
(15628, 3, 3, '그리고 영웅들이여... 내게 그대들이 찾고 있는 것이 있다. 다시 한번 아제로스에서 악마가 사라지는 모습을 볼 수 있기를... 레물로스, 우리의 용사에게 녹색용군단의 파편을 건네 주도록 하라.'),
(15629, 0, 0, '%s|1이;가; 쓰러진 이들의 고통을 흡수합니다.'),
(15638, 0, 0, '법을 준수하라!'),
(15638, 0, 1, '대중의 신뢰에 보답하라!'),
(15638, 0, 2, '선량한 이들을 보호해야 한다!'),
(15643, 0, 0, '%s|1이;가; 격노합니다!'),
(15644, 0, 0, '고통과... 욕구... 더 먹고 싶다...'),
(15644, 0, 1, '고통을 견딜 수가 없다. 새로운 원천을 찾아야 한다.'),
(15644, 0, 2, '더, 더, 더! 당장 먹을 것이 필요하다.'),
(15645, 0, 0, '고통과... 욕구... 더 먹고 싶다...'),
(15645, 0, 1, '고통을 견딜 수가 없다. 새로운 원천을 찾아야 한다.'),
(15645, 0, 2, '더, 더, 더! 당장 먹을 것이 필요하다.'),
(15648, 0, 0, '%s|1이;가; 폭발하며 비전 잔류물이 쏟아집니다!'),
(15656, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(15657, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(15687, 0, 0, '음, 예상치 못한 손님들이군. 준비를 해야겠어...'),
(15687, 1, 0, '어디까지 했죠? 아, 맞아...'),
(15687, 1, 1, '절 부르셨습니까?'),
(15687, 2, 0, '저녁 만찬에 쓸 재료가 하나 더 늘었군.'),
(15687, 2, 1, '시간... 언제나 시간이 부족해.'),
(15687, 2, 2, '흥분해서 그만 실수를 했네요...'),
(15687, 3, 0, '나는 정말 미련했구나.'),
(15688, 0, 0, '너희의 피로 내 마법진을 칠하리라!'),
(15688, 0, 1, '위대한 분께서 기뻐하실 것이다.'),
(15688, 1, 0, '제 목숨은 당신 것입니다, 위대한 분이시여...'),
(15688, 2, 0, '아, 때맞춰 와줬군. 막 의식을 시작하려던 참이었다!'),
(15688, 3, 0, '위대한 분이시여, 부디 이 보잘것없는 제물을 받아주십시오...'),
(15688, 3, 1, '충성심의 증거로 이 제물을 바칩니다.'),
(15688, 4, 0, '나오너라, 어둠의 피조물들이여! 내 부름에 응답하라!'),
(15688, 4, 1, '내 귀여운 아이들아... 먹이가 아주 많구나!'),
(15690, 0, 0, '여기까지 오다니 정신이 나간 놈들이 분명하구나. 소원이라면 파멸시켜 주마!'),
(15690, 1, 0, '바보 같으니! 시간은 너의 몸을 태우는 불길이 되리라!'),
(15690, 2, 0, '바보 같으니! 시간은 너의 몸을 태우는 불길이 되리라!'),
(15690, 3, 0, '바보 같으니! 시간은 너의 몸을 태우는 불길이 되리라!'),
(15690, 4, 0, '바보 같으니! 시간은 너의 몸을 태우는 불길이 되리라!'),
(15690, 5, 0, '어찌 감히 이렇게 압도적인 힘에 맞서기를 꿈꾸느냐?'),
(15690, 6, 0, '물론 이길 거란 생각은 하지 않았겠지.'),
(15690, 6, 1, '그 탐욕과 우둔함이 너희를 파멸로 이끌었노라.'),
(15690, 6, 2, '너희는 노리개일 뿐이다. 기분 전환거리도 안 되는...'),
(15690, 7, 0, '모든 차원과 실체가 나를 향해 열려 있노라!'),
(15690, 7, 1, '이 말체자르 님은 혼자가 아니시다. 너희는 나의 군대와 맞서야 한다!'),
(15690, 8, 0, '패배를 인정할 수 없다! 나는 에레다르의 공작이다! 나... 나는...'),
(15691, 0, 0, '박물관에는 초대받은 손님만 입장하실 수 있습니다.'),
(15691, 1, 0, '관람 규칙을 엄격히 준수해 주십시오.'),
(15691, 1, 1, '저는 이곳의 안전을 책임지고 있습니다.'),
(15691, 2, 0, '현재 요청하신 내용은 처리가 불가능합니다.'),
(15691, 3, 0, '규칙 위반으로 경보가 발동됐습니다.'),
(15691, 4, 0, '전시물에는 손대지 마십시오.'),
(15691, 4, 1, '당신은 초대받지 못하셨습니다.'),
(15691, 5, 0, '관리인, 작동을 중단합니다...'),
(15727, 0, 0, '%s|1이;가; 약해집니다!'),
(15928, 0, 0, '너무 늦었다! 난... 복종해야 한다!'),
(15928, 1, 0, '죽여주마...'),
(15928, 1, 1, '잡아... 먹어주마...'),
(15928, 1, 2, '박살을 내주겠다!'),
(15928, 2, 0, '잘... 가라!'),
(15928, 3, 0, '자, 고통을 느껴봐라...'),
(15928, 4, 0, '고맙... 구나...'),
(15928, 5, 0, '제... 발!'),
(15928, 5, 1, '그만! 제발 멈춰줘!'),
(15928, 5, 2, '도와줘! 날 구해줘!'),
(15928, 5, 3, '제발... 안 돼!'),
(15929, 0, 0, '스탈라그, 박살낸다!'),
(15929, 1, 0, '스탈라그, 죽인다!'),
(15929, 2, 0, '주인님, 살려주세요!'),
(15930, 0, 0, '너 주인님께 바칠 거야!'),
(15930, 1, 0, '퓨진 주인님 기쁘게 한다.'),
(15930, 2, 0, '이제... 퓨진은... 없다...'),
(15936, 0, 0, '이제 넌 내 것이다.'),
(15936, 0, 1, '네놈이 보인다!'),
(15936, 0, 2, '다음은... 너다.'),
(15936, 1, 0, '눈을 감아라... 잠들거라...'),
(15936, 2, 0, '모든 종족은 멸망할 것이다. 시간문제일 뿐이지!'),
(15936, 2, 1, '보인다. 끝없는 고통이... 보인다. 고통과 분노가... 내게는 모든 것이 보인다.'),
(15936, 2, 2, '곧 세상에 종말이 닥치리라.'),
(15936, 2, 3, '여기가 너희 무덤이 되리라.'),
(15936, 2, 4, '배고픈 벌레들이 너희 살덩이 위에서 잔치를 벌이리라.'),
(15936, 3, 0, '여기가 너희 무덤이 되리라.'),
(15941, 0, 0, '어떻게 된 거지? 아, 또 이럴 순 없어!'),
(15945, 0, 0, '어떻게 이럴 수가! 우린 약속을 하지 않았소?!'),
(15951, 0, 0, '문제가 해결되었군... 이제 그 누구도 나 같은 실수를 반복하지 않을 것이오!'),
(15953, 1, 3, '도망칠 수 있을 때 달리십시오!'),
(15954, 0, 0, '주인님께 영광을!'),
(15954, 0, 1, '너희 생명은 끝이다!'),
(15954, 0, 2, '죽어라, 침입자들아!'),
(15954, 1, 0, '일어나라, 병사들이여! 다시 일어나 싸워라!'),
(15954, 2, 0, '임무를 완료했다!'),
(15954, 2, 1, '이제 숨을 거두어라!'),
(15954, 3, 0, '죽어서도 주인님을... 섬길 것이다!'),
(15956, 0, 0, '어디 맛 좀 볼까...'),
(15956, 0, 1, '나가는 길은 없다.'),
(15956, 0, 2, '그래, 도망쳐! 더 신선한 피가 솟구칠 테니!'),
(15956, 1, 0, '아... 손님 맞이할 시간이군.'),
(15956, 1, 1, '조그만 심장 뛰는 소리가 들린다. 오, 점점 빨리... 곧 멈추게 해주마.'),
(15956, 1, 2, '어디로 갈까? 무얼 할까? 모두 다 부질없는 것! 고통과 죽음만이 기다릴 뿐...'),
(15956, 1, 3, '어느 놈부터 먹어줄까? 참 고르기 어렵군. 다들 맛있을 것 같단 말이야...'),
(15956, 1, 4, '가까이 오라, 한입 거리들아! 군침이 도는구나. 너무 오랫동안 굶주려 있었어...'),
(15956, 2, 0, '쉬이... 이제 다 끝이다.'),
(15978, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(15989, 0, 0, '사피론이 공중으로 떠오릅니다!'),
(15989, 1, 0, '사피론이 다시 공격합니다!'),
(15989, 2, 0, '%s|1이;가; 숨을 깊게 한번 들이마십니다.'),
(15989, 3, 0, '사피론이 다시 공격합니다!'),
(15990, 0, 0, '나의 주군이시여, 당신의 군대는 적을 쓸어버릴 준비가 되었습니다.'),
(15990, 1, 0, '나의 주군이시여, 당신의 군대는 적을 쓸어버릴 준비가 되었습니다.'),
(15990, 2, 0, '그렇습니다, 주인님. 저들의 완전한 파멸이 눈앞에 다가왔습니다... 이건 뭐지?'),
(15990, 3, 0, '그렇습니다, 주인님. 저들의 완전한 파멸이 눈앞에 다가왔습니다... 이건 뭐지?'),
(15990, 4, 0, '명령을 따르겠습니다... 주인님!'),
(15990, 5, 0, '안 돼! 저주가 내릴 것이다, 침입자 녀석! 리치 왕께서 이끄는 군대가 널 추적하리라. 운명의 굴레를 벗어나지는 못할 것이야...'),
(15990, 6, 0, '안 돼! 저주가 내릴 것이다, 침입자 녀석! 리치 왕께서 이끄는 군대가 널 추적하리라. 운명의 굴레를 벗어나지는 못할 것이야...'),
(15990, 6, 1, '어리석은... 너희가 성공했다고 생각하나? 이제 한 발짝 더 다가왔을 뿐이다. 끝없는 심연으로!'),
(15990, 6, 2, '이런 놀음도 이젠 지겹군. 와라, 너희 영혼을 망각의 저편으로 보내 주마!'),
(15990, 6, 3, '어떤 공포가 닥쳐올지 모르는군. 지금까진 아무것도 아니다. 기다리고 있노라. 낙스라마스의 얼어붙은 심장이!'),
(15990, 7, 0, '자비를 구하라!'),
(15990, 7, 1, '마지막 숨이나 쉬어라!'),
(15990, 7, 2, '최후를 맞이하라!'),
(15990, 8, 0, '어둠이 널 기다린다.'),
(15990, 8, 1, '%s|1이;가; 미친 듯이 웃습니다.'),
(15990, 9, 0, '으아아! 아직... 기뻐하긴 이르지... 승리는 잠깐일 뿐! 상상조차 할 수 없는 강력한 존재로 돌아오겠다!'),
(15990, 10, 0, '너의 영혼은 이제 내 것이다!'),
(15990, 10, 1, '빠져나갈 구멍은 없다.'),
(15990, 11, 0, '네놈들 뼛속까지 얼려주마!'),
(15990, 12, 0, '주인님, 도와주소서!'),
(15990, 13, 0, '좋다. 얼어붙은 땅의 전사들이여, 일어나라! 너희에게 싸울 것을 명하노라. 날 위해 죽고, 날 위해 죽여라! 한 놈도 살려두지 마라!'),
(15990, 14, 0, '어둠의 문지기와 하수인, 그리고 병사들이여! 나 켈투자드가 부르니 명을 받들라!'),
(15990, 15, 0, '그따위 하찮은 마법으로는 스컬지에 상대도 되지 않는다는 걸 모르느냐!'),
(15990, 15, 1, '그따위 하찮은 마법으로는 스컬지에 상대도 되지 않는다는 걸 모르느냐!'),
(15990, 15, 2, '그따위 하찮은 마법으로는 스컬지에 상대도 되지 않는다는 걸 모르느냐!'),
(16011, 0, 0, '강령술의 기운이 주위를 둘러싸 모든 치유를 방해합니다!'),
(16011, 1, 0, '기운이 사라지자 다시 치유가 가능합니다!'),
(16011, 2, 0, '오라의 힘이 약해지기 시작합니다!'),
(16028, 0, 0, '패치워크랑 놀아줘!'),
(16028, 0, 1, '켈투자드 님이 패치워크 싸움꾼으로 만들었다.'),
(16028, 1, 0, '또 놀아 줄래?'),
(16028, 2, 0, '나... 어떻게...아아아...'),
(16028, 3, 0, '%s|1이;가; 분노에 휩싸여 광폭해집니다!'),
(16028, 4, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(16042, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(16060, 0, 0, '어리석은 것들, 스스로 죽음을 자초하다니! 감히 넘보지도 못할 힘을 무시하느냐? 그래도 가까스로 이 고딕 님의 영역까지 침범했구나. 자, 이제 출구는 하나뿐이다. 쓸쓸히 황천으로 가는 길이지.'),
(16060, 1, 0, '죽음만이 유일한 탈출구다!'),
(16060, 2, 0, '내가... 죽는구나.'),
(16060, 3, 0, '오랫동안 기다렸다. 이제 영혼 착취자를 만날 차례다.'),
(16063, 0, 0, '도망가라! 더 늦기 전에!'),
(16063, 1, 0, '침입자들이여, 무모한 도전은 당장 멈추고 더 늦기 전에 돌아가라!'),
(16063, 1, 1, '그들이 깨어날 것이다... 그 전에 빨리 도망쳐라.'),
(16063, 1, 2, '이제 그만! 돌아가! 더 늦기 전에!'),
(16063, 2, 0, '난... 난 복종할 수밖에 없어!'),
(16063, 3, 0, '날 용서해줘!'),
(16063, 4, 0, '이것이... 나의 운명...'),
(16064, 0, 0, '덤벼라, 애송이 같은 놈들!'),
(16064, 1, 0, '나가서 싸우자! 적들이 왔다!'),
(16064, 1, 1, '이제 그만 좀 지껄여라! 주둥이 닥치란 말이다!'),
(16064, 1, 2, '약골들을 상대하게 되다니 아주 재밌겠군!'),
(16064, 2, 0, '난 바싹 구운 걸 좋아하지!'),
(16064, 3, 0, '다음에는 엄마라도 데려와라!'),
(16064, 4, 0, '이 무슨 개떡같은 일이!'),
(16065, 3, 0, '다음은 누구냐!'),
(16098, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(16128, 0, 0, '저희가 브란의 전갈을 받고 미리 준비를 시작했습니다.'),
(16128, 1, 0, '달라란의 시민이여! 두 눈을 들어 하늘을 올려다보라!'),
(16128, 2, 0, '오늘 우리는, 바로 우리를 창조한 존재에 맞서 세계의 파괴를 막아냈다!'),
(16128, 3, 0, '용감한 우리 동료가, 티탄 도시 울두아르 깊숙한 곳에서 티탄의 사자인 관찰자 알갈론을 물리쳤다!'),
(16128, 4, 0, '알갈론은 우리 세상의 운명을 결정하러 왔었다.'),
(16128, 5, 0, '그가 찾은 행성에는 티탄의 청사진을 벗어난 종족들이 살고 있었다. 그곳은 티탄의 계획과 다르게 돌아가고 있었다.'),
(16128, 6, 0, '차가운 논리는 이 세상을 보전할 가치가 없다고 판단했다. 그러나 차가운 논리는, 자유 의지의 힘을 간과했다! 이제 우리가 증명해야 한다. 이 세상의 가치를!'),
(16128, 7, 0, '그리고 우리의 삶이... 살 가치가 있음을.'),
(16151, 0, 0, '아주 잘했다, 천둥아!'),
(16151, 1, 0, '비겁하고 치사한 놈들!'),
(16151, 1, 1, '감히 누가 사냥꾼의 애마를 건드리느냐?'),
(16151, 1, 2, '한번 혼쭐이 나야 정신을 차릴 놈들이로구나!'),
(16151, 2, 0, '이랴! 이 오합지졸을 데리고 실컷 놀아보자!'),
(16183, 0, 0, '여기가... 여기가 어디죠?'),
(16189, 0, 0, '경비병!'),
(16192, 0, 0, '경비병!'),
(16206, 0, 0, '고... 고맙습니다. 그냥 죽는 줄로만 알았답니다.'),
(16209, 0, 0, '정말 감사합니다!'),
(16220, 0, 0, '릴라사는 가서 상처를 돌보도록. 무사히 데려다 줘서 정말 고맙네.'),
(16222, 0, 0, '태양와... 아, 실버문에 영광 있으라!'),
(16222, 1, 0, '혈기사여, 우리 목숨은 그대의 것입니다.'),
(16227, 0, 0, '경비병!'),
(16244, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(16263, 0, 0, '왜 지저분하고 냄새 나는 트롤과 우리가 동맹을 맺어야 합니까? 유령이 되었을 때를 제외하고는 트롤들은 절대 선량한 족속이 아닙니다.'),
(16263, 0, 1, '트롤 사냥에 쓸 물건이 필요한 분? 트롤들도 만반의 준비를 다했을 것입니다.'),
(16287, 1, 0, '주제도 모르는 어린애 같으니! 지금 네 앞에 선 분이 누군지 알고나 있는 게냐?'),
(16295, 0, 0, '갑시다.'),
(16329, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(16364, 0, 0, '%s|1이;가; 마지막 힘을 근처의 마법석으로 방출하여 성공적으로 재가동시킵니다.'),
(16406, 0, 0, '이게 대체 무슨 일이랍니까?'),
(16406, 0, 1, '여기는 어디죠? 대체...'),
(16407, 0, 0, '안 돼!'),
(16407, 0, 1, '난 이걸로 끝이란 말인가!'),
(16407, 0, 2, '주인님께서... 화내실 텐데...'),
(16408, 0, 0, '아, 운명이 내게서 등을 돌리다니!'),
(16409, 0, 0, '이건... 말도 안 돼...'),
(16414, 0, 0, '200년 된 퍼플리버보스 포트 포도주였단 말이다!'),
(16414, 0, 1, '너 같은 놈에게는 너무 아까운 물건이다!'),
(16414, 0, 2, '너 때문에 주인님께서 드실 포도주가 모자라겠다!'),
(16414, 1, 0, '잠깐, 기다려! 안 돼!'),
(16447, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(16468, 0, 0, '아, 이제 기억이 돌아오는 것 같소...'),
(16468, 0, 1, '이 극장의 공연이 그리울 거요!'),
(16470, 0, 0, '정말 끝난 건가?'),
(16470, 0, 1, '모든 것이... 돌아오고 있습니다...'),
(16481, 0, 0, '떠날 때가 되었구나...'),
(16481, 0, 1, '마침내... 자유인가.'),
(16482, 0, 0, '떠날 때가 되었구나...'),
(16482, 0, 1, '마침내... 자유인가.'),
(16483, 0, 0, '비행선이 추락하면서 우리는 비상 탈출 장치를 가동했습니다. 그게 제 마지막 기억이죠. 가서 도울 일이 있는지 봐야겠군요. 감사합니다!'),
(16483, 0, 1, '뭐지? 무슨 일이 일어난 거야? 으... 머리가 너무 아파 터질 거 같군요! 추락 지점으로 돌아가는 게 좋겠습니다.'),
(16483, 0, 2, '$C님이 절 구하셨군요! 평생 잊지 못할 신세를 졌습니다. 도움이 필요한 다른 친구는 없는지 찾아봐야겠습니다.'),
(16483, 0, 3, '아, 이런! 여기는 어디인가요? 무슨 일이 벌어진 겁니까? 저기... 비행선의 파편이군요!'),
(16483, 1, 0, '으, 아파...'),
(16483, 1, 1, '너무나 고통스럽습니다. 제발 이 고통을 멈춰주십시오...'),
(16483, 1, 2, '으으으... 너무 아파. 좀 도와주시겠소?'),
(16483, 1, 3, '제가 버텨낼 수 있을지 모르겠습니다. 제발 도와주십시오...'),
(16485, 0, 0, '주인님의 물건을 훔치려는 놈들에게 똑같은 운명이 기다리고 있다.'),
(16485, 0, 1, '너 같은 놈에게는 죽음도 크나큰 자비다.'),
(16485, 1, 0, '이런다고... 바뀌는 것은 없다. 영원한 저주가 널 찾아갈 것이다!'),
(16485, 1, 1, '이래도 소용없다. 다른 누군가 내 자리를 대신할 테니까!'),
(16518, 0, 0, '%s|1이;가; 매우 기뻐하는 것 같습니다.'),
(16518, 0, 1, '%s|1이;가; 어지러워합니다.'),
(16518, 0, 2, '%s|1은;는; 수정의 효과에 개의치 않는 듯합니다.'),
(16518, 0, 3, '%s|1은;는; 방금 벌어진 일이 매우 불쾌하다는 표정입니다.'),
(16518, 0, 4, '%s|1이;가; 어찌할 바를 모르겠다는 표정입니다.'),
(16518, 0, 5, '%s|1이;가; 고맙다는 듯이 고개를 끄덕거립니다.'),
(16521, 0, 0, '고통 없이 보내 주마.'),
(16521, 0, 1, '너희는 이 계곡을 벗어나지 못한다!'),
(16521, 0, 2, '추락에서 살아남아 찾아온 곳이 네 무덤이 될 자리라니. 정말 불쌍하군.'),
(16523, 0, 0, '%s|1이;가; 격노합니다!'),
(16524, 0, 0, '제발 그만! 내 아들... 그 아이는 미쳤어!'),
(16524, 0, 1, '똑같은 고통을 겪진 않겠다.'),
(16524, 0, 2, '너흰 누구냐? 원하는 게 뭐야? 가까이 오지 마!'),
(16524, 1, 0, '너희에게 보여주마! 아무리 지친 개라도 송곳니는 있는 법!'),
(16524, 1, 1, '불타라, 지옥의 악마들아!'),
(16524, 2, 0, '모두 얼려 버리겠다!'),
(16524, 2, 1, '차가운 암흑으로 돌아가라!'),
(16524, 3, 0, '그래, 내 아들은 아주 강하지... 하지만, 내게도 힘은 있다!'),
(16524, 3, 1, '난 어릿광대 따위가 아니다! 나는 니엘라스 아란이다!'),
(16524, 4, 0, '목 좀 축이게 해달라는 이 늙은이의 청을 뿌리칠 텐가? 아... 별로 기대도 안 했어.'),
(16524, 5, 0, '아직 끝나지 않았어! 몇 가지 계략을 준비해 두었지...'),
(16524, 6, 0, '이 악몽을 끝내고 싶구나!'),
(16524, 6, 1, '이제 그만 괴롭혀라!'),
(16524, 7, 0, '충분히 시간을 끌었다... 이제 게임을 끝낼 때가 됐구나!'),
(16524, 8, 0, '마침내 악몽이 끝났다...'),
(16524, 9, 0, '그건 어디서 났지? 그 아이가 보냈나?'),
(16534, 0, 0, '%s|1이;가; 고맙다는 듯이 고개를 끄덕거립니다.'),
(16534, 0, 1, '%s|1이;가; 어찌할 바를 모르겠다는 표정입니다.'),
(16534, 0, 2, '%s|1은;는; 방금 벌어진 일이 매우 불쾌하다는 표정입니다.'),
(16534, 0, 3, '%s|1이;가; 매우 기뻐하는 것 같습니다.'),
(16534, 0, 4, '%s|1은;는; 수정의 효과에 개의치 않는 듯합니다.'),
(16544, 0, 0, '살아서 나갈 수 있을 때 돌아가라.'),
(16544, 1, 0, '당신이 거둘 유일한 성과는 바로 자신의 파멸밖에 없습니다!'),
(16550, 0, 0, '아타말 수정 7개의 힘이로군! 생존자가 더 있다니! 자나, 당신인가? 당신을 다시 보게 되어 정말 반갑군!'),
(16550, 1, 0, '그리고 누가 있소? 의심할 필요도 없이... <통신 장애> ...통신이 가능한가? ...하늘 감시초소에서... <통신 장애>... 의 안부를 전하오.'),
(16550, 2, 0, '그쪽 신호를 들어보니 우리가 당신을... 우리가 추락한 큰 섬의 남동쪽 부분으로... 암멘 여울을 건너... 크쉬쉬쉬크 지지지트... 미안하오. 너무 많은...'),
(16577, 0, 0, '형제자매들이여, 나는 약속의 땅에 다녀왔소. 그곳에서 엄청난 힘을 경험했고 더없는 행복을 느꼈소. 너무나 행복하고 황홀한 나머지 신의 꿈을 발견한 것은 아닌가 하는 생각이 들 정도였다오.'),
(16577, 1, 0, '천국에서는 팔을 뻗어서 황천에서 가져오기만 하면 된다오.'),
(16577, 2, 0, '바람을 마시는 것이오! 대지의 균열에서 순수한 마력이 솟아오를 때 그 신비한 힘의 덩굴이 흑요석 빛깔의 하늘을 비추지. 개울이나 우물에서 물을 마시듯 무릎을 꿇고 틈에서 나오는 마력을 마시면 되오. 가지에 매달린 사과를 따듯 하늘의 덩굴을 잡아당기면 되는 것이지.'),
(16578, 0, 0, '더 말씀해 주세요, 말티크. 그게 무엇이죠? 어떤 느낌인가요?'),
(16578, 1, 0, '하지만, 어떻게요?'),
(16578, 2, 0, '%s|1이;가; 놀라서 입을 벌립니다.'),
(16584, 0, 0, '노움도 너보다는 부지런하게 일한다! 삐삐 머리를 한 어린 여자 노움도 말이다! 빨리... 빨리 움직여라!'),
(16585, 0, 0, '당신 음식이 준비됐으니 와서 가져가시오...'),
(16585, 1, 0, '그리고 당신이 나즈그렐 님께 또다시 불평을 했다는 얘기가 들리면 다음번에는 내가 만든 음식을 먹이겠소이다...'),
(16587, 0, 0, '경비병!'),
(16589, 0, 0, '그래서 우리가 도착했지. 나와 내 부대는 저 아래 뼈로 덮인 길에서 통상적인 정찰 임무를 수행했지. 우리는 먼저 정찰병을 보내서 위험한 일은 없는지 주변을 살폈소이다.'),
(16589, 1, 0, '아니나 다를까 정찰병이 돌아와서 길 아래에 오크가 있다고 보고를 했지. 그들은 아직 우리를 발견하지 못했기 때문에 우리가 가서 안면을 터야겠다고 생각했다오.'),
(16589, 2, 0, '붉은색의 거대한 괴물! 내가 지금껏 봤던 그 어떤 오크보다도 컸소이다. 울퉁불퉁한 근육에 여기로 비집고 나온 이빨하며...'),
(16589, 3, 0, '%s|1이;가; 고개를 끄덕입니다.'),
(16589, 4, 0, '맞소, 타락한 오크들이지...'),
(16589, 5, 0, '나도 모른다오, 친구. 나도 잘 모르겠어...'),
(16589, 6, 0, '하지만, 그게 끝이 아니었소. 우리가 후퇴하기 전에 그 오크 한 패거리가 우리를 발견하고 공격했지.'),
(16589, 7, 0, '그날 내 정예병사들을 여럿 잃었다오...'),
(16590, 0, 0, '위장이 음식을 토해내지 않고 버텨만 주면 되니까, 죄수들에게 주고 남은 음식이라도 주세요. 이... 이 음식을 주다니 정말 모욕적이군요.'),
(16590, 0, 1, '계피를 조금 넣었나요, 아니면 육두구를 넣었나요? 뭐든 간에 한 가지 확실한 것은 쿠키 씨, 당신만큼 당나귀를 제대로 요리하는 자는 아무도 없다는 겁니다.'),
(16590, 1, 0, '어떤 오크를 말씀하시는 겁니까, 경비대장님?'),
(16590, 2, 0, '그럼 그 사람이...'),
(16590, 3, 0, '하지만, 어떻게 그럴 수 있습니까, 경비대장님? 저주가 풀린 줄 알았는데...'),
(16699, 0, 0, '%s|1이;가; 격노합니다!'),
(16769, 0, 0, '시간이 없다는 것을 안 %s|1은;는; 뛰려고도 하지 않습니다.'),
(16769, 1, 0, '캘타스를 위하여!'),
(16769, 1, 1, '살아서 도망치지 못할 것이다!'),
(16769, 1, 2, '저자들이 달아나기 전에 해치워라!'),
(16769, 1, 3, '우선 너의 힘을 뺏은 후 목숨도 취해주마!'),
(16794, 0, 0, '음... 대단해... 정말 강력한 혼합물이로군!'),
(16794, 1, 0, '하지만, 어디서 저자와 같은 적당한 실험 대상을 찾을 수 있겠소?'),
(16794, 2, 0, '자, 이걸 마셔라, 이 푸른 괴물아! 내 말을 듣지 않으면 천천히 아주 고통스러운 죽음을 안겨주겠다!'),
(16794, 3, 0, '흠... 새 실험 대상을 찾아야겠는데...'),
(16795, 0, 0, '불쌍하구려, 포세이큰이여. 당신의 영혼에는 빛이 없소이다.'),
(16802, 0, 0, '당연한 결과다!'),
(16802, 0, 1, '헛된 죽음이로군!'),
(16807, 0, 0, '한꺼번에 덤벼보시겠다? 정말 재미있겠군!'),
(16807, 1, 0, '가져가라. 어차피 쓸모없는 놈이니까!'),
(16807, 1, 1, '그래, 마구 내려쳐라! 그놈은 오우거만큼 머리가 단단하지.'),
(16807, 1, 2, '약골을 상대하는데 시간을 낭비하지 말라고.'),
(16807, 1, 3, '그놈을 원한다고? 좋다, 가져가라!'),
(16807, 2, 0, '구차한 목숨이 또 하나 갔구나. 계속 해봐라!'),
(16807, 2, 1, '아, 시간 낭비가 따로 없군. 다음!'),
(16807, 2, 2, '어쨌거나 처리하려던 놈이었다!'),
(16807, 2, 3, '성가신 일을 대신 해줘서 고맙군. 이제 나도 재미 좀 볼까!'),
(16807, 3, 0, '구차한 목숨을 구걸해 보아라!'),
(16807, 3, 1, '도망쳐라, 겁쟁이들아, 도망쳐!'),
(16807, 3, 2, '너희의 고통은 나의 즐거움이지!'),
(16807, 4, 0, '벌써부터 지겨워지는군.'),
(16807, 4, 1, '제대로 덤벼라! 진짜 싸움이 뭔지 보여줘!'),
(16807, 4, 2, '하인들을 괴롭히는 게 훨씬 더 재밌을 것 같군.'),
(16807, 5, 0, '네가 졌다!'),
(16807, 5, 1, '순순히 죽어라!'),
(16807, 6, 0, '이... 얼마나 수치스러운 일인가!'),
(16808, 0, 0, '우리가 진정한 호드이자 유일한 호드이다!'),
(16808, 0, 1, '네놈을 먼저 손봐주마!'),
(16808, 0, 2, '내 별명이 칼주먹인데는 다 이유가 있다. 너희도 곧 알게 될 것이다.'),
(16808, 1, 0, '진정한 호드를 위하여!'),
(16808, 1, 1, '내가 유일한 대족장이시다!'),
(16808, 2, 0, '진정한 호드가... 승리할 것이다.'),
(16809, 0, 0, '다... 네 잘못이야!'),
(16809, 1, 0, '네가... 정말... 미워.'),
(16809, 2, 0, '진정한 호드가... 승리할 것이다.'),
(16812, 0, 0, '신사 숙녀 여러분, 오늘 저녁 공연에 오신 것을 환영합니다!'),
(16812, 1, 0, '오늘 밤, 충직한 동료의 도움을 받아 고향으로 돌아가기 위해서 필사적으로 노력하는 길 잃은 한 소녀를 통해 인간의 영혼은 그 깊이가 얼마나 되는지 알아보겠습니다!'),
(16812, 2, 0, '불행히도, 심술궂고 사악한 쭈그렁할멈이 이 소녀의 뒤를 쫓고 있습니다!'),
(16812, 3, 0, '과연 소녀는 살아서 집에 돌아갈 수 있을까요? 그 답은 오직 시간만이 알려줄 것입니다. 이제... 연극을 시작하겠습니다!'),
(16812, 4, 0, '신사 숙녀 여러분, 오늘 저녁 공연에 오신 것을 환영합니다!'),
(16812, 5, 0, '오늘 밤, 보이는 것을 그대로 믿지 마십시오... 이제 여러분의 눈앞에 믿지 못할 광경이 펼쳐집니다.'),
(16812, 6, 0, '여기 조용히 손녀를 기다리는 할머니가 계십니다... 백발이 성성한 이 숙녀분을 두려워할 이는 아무도 없겠죠!'),
(16812, 7, 0, '하지만, 제가 여러분의 눈을 속이고 있다면?! 저 아래 뭐가 있는지 직접 확인하십시오! 이제... 연극을 시작하겠습니다!'),
(16812, 8, 0, '신사 숙녀 여러분, 오늘 저녁 공연에 오신 것을 환영합니다!'),
(16812, 9, 0, '오늘 밤... 금지된 사랑의 이야기를 파헤쳐 보겠습니다!'),
(16812, 10, 0, '기억해 두십시오. 두고 보면 아시겠지만 모든 사랑 얘기가 행복하게 끝나는 것은 아닙니다. 때로는 장미 가시처럼 아픈 것이 사랑이지요!'),
(16812, 11, 0, '그래도 제게서 사랑을 뺏어가지는 마세요. 운명이 연인들을 갈라놓을 때 어떤 비극이 기다리고 있을까요?! 이제... 연극을 시작하겠습니다!'),
(16816, 0, 0, '승부사의 전당의 입구에 걸린 저주가 풀리려는 듯, 카라잔의 전당이 심하게 흔들립니다.'),
(16816, 1, 0, '메디브의 메아리!'),
(16822, 0, 0, '경비병!'),
(16846, 0, 0, '%s|1이;가; 격노합니다!'),
(16847, 0, 0, '힘이... 힘이... 돌아오고 있습니다!'),
(16847, 0, 1, '당신이 치료법을 발견했군요! 이제 우린 적을 박살 낼 수 있는 힘을 다시 찾았습니다!'),
(16847, 0, 2, '덕분에 건강을 회복했습니다! 당신에게 빚을 졌군요.'),
(16863, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(16871, 0, 0, '%s|1이;가; 격노합니다!'),
(16876, 0, 0, '%s의 상태가 불안정하게 변하더니 붕괴됩니다!'),
(16878, 0, 0, '%s|1이;가; 격노합니다!'),
(16916, 0, 0, '제발! 마법의 힘이 필요해... 마나 수정이든... 결정이든... 아무거나 상관없어! 너무나 고통스러워!'),
(16924, 0, 0, '불어라! 너희 대장은 어디에 숨었느냐?'),
(16924, 1, 0, '입을 열기 전까지는 계속 굶긴다!'),
(16938, 0, 0, '저를 이 불행의 구렁텅이에서 좀 꺼내 주십시오!'),
(16938, 0, 1, '용서하십시오... 전 선택의 여지가 없습니다.'),
(16943, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(16964, 0, 0, '%s|1이;가; 격노합니다!'),
(16980, 0, 0, '침입자들이 내부 성소로 들어왔다. 서둘러 녹색용을 파멸시켜라! 되살려 낼 때 쓸 뼈와 힘줄만 남겨라!'),
(17000, 0, 0, '바보 같은! 우리 아버지의 존재를 부정하려는 것이냐? 죽을 준비나 해라, 필멸의 존재들이여!'),
(17015, 0, 0, '다른 순례자가 도착했소이다! 빨리 물을 가져오시오. 아니면 그녀가 죽을지도 모르오!'),
(17023, 0, 0, '굴단 님은 진실을 말씀하신다! 우리는 즉시 돌아가서 형제들에게 이 소식을 알려야 한다! 차원문을 통해 돌아가도록!'),
(17058, 0, 0, '멈추지 마라! 요령을 피우다 걸리면 끔찍한 고통을 보여 주마!'),
(17058, 0, 1, '더 빨리 파라, 쓰레기들아! 나로 하여금 고통의 진짜 의미를 가르치게 하지 마라!'),
(17058, 0, 2, '좀 더 빨리 움직여라, 이 하찮은 것들! 주인님께서 찾고 계신 아타말 수정을 찾지 못하면 그분의 분노를 사게 될 것이다.'),
(17058, 1, 0, '감히 주인님의 일을 방해하다니! 그 대가를 치르게 될 것이다, 이 어리석은 녀석!'),
(17058, 1, 1, '침입자들을 해치워라, 더러운 넝마두건 녀석들아! 내 말을 거역한다면 끝없는 고통을 선물해 주마!'),
(17058, 1, 2, '어서 가라, 이 쓸모없는 것들아! 저 바보들에게 우리 주인님이 얼마나 위대한 분인지 보여 주거라!'),
(17058, 1, 3, '도망갈 생각은 꿈에도 하지 마라, 이 뒤틀린 드레나이 쓰레기들아! 침입자들을 해치우지 않으면 지옥보다도 고통스러운 운명을 안겨주겠다!'),
(17073, 0, 0, '<흐느껴 울며> 저는 무덤이 싫습니다. 많은 동료가 죽었습니다. 사랑하는 루하나도...'),
(17073, 0, 1, '내가 죽었어야 하는데!'),
(17073, 0, 2, '평화롭게 잠드시오, 루하나... 내 사랑.'),
(17073, 0, 3, '당신을 절대 잊지 못할 거요, 내 사랑.'),
(17073, 0, 4, '추락 사고가 누구 책임인지 알아낸다면...'),
(17073, 0, 5, '함께 오는 게 아니었는데...'),
(17073, 0, 6, '왜 내게서 루하나를 앗아간 겁니까? 왜?!'),
(17073, 0, 7, '당신이 너무나 보고 싶구려!'),
(17073, 0, 8, '당신은 언제나 여기에, 나와 함께 있을 거요.'),
(17073, 0, 9, '%s|1이;가; 조용히 눈물을 흘립니다.'),
(17073, 0, 10, '%s|1이;가; 완전히 지친 듯 고개를 숙이고 한숨을 쉽니다.'),
(17073, 0, 11, '%s|1이;가; 갑자기 큰 소리로 엉엉 웁니다.'),
(17073, 0, 12, '%s|1이;가; 앞에 있는 묘비를 조용히 바라봅니다.'),
(17077, 0, 0, '%s|1이;가; 마치 무언가를 듣는 것처럼 하늘을 향해 고개를 치켜듭니다.'),
(17077, 1, 0, '%s|1이;가; 산을 넘어 북쪽까지 울리는 긴 소리를 내고는 따라오라는 듯 꼬리를 흔듭니다.'),
(17085, 0, 0, '아브루의 마법이... 아직도 날 조종하고 있다. 너는 나와 싸워야 한다, 필멸의 존재여. 그것만이 마법을 깰 수 있는 유일한 방법이다!'),
(17085, 1, 0, '아브루의 마법이 깨졌구나! 내가 다시 자유를 찾았다!'),
(17086, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17117, 0, 0, '%s|1이;가; 신음합니다.'),
(17156, 0, 0, '%s|1이;가; 격노합니다!'),
(17188, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17215, 0, 0, '흠, 그녀를 치료할 방법이 아직 있을 것이오. 이쪽으로 오시오, $n. 필요한 걸 알려주겠소.'),
(17215, 1, 0, '이거면 될 것이오...'),
(17215, 2, 0, '일어나십시오, 작은 친구. 그만 잠에서 깨십시오... 당신은 이제 안전합니다.'),
(17225, 0, 0, '멀리에서 고대의 존재가 깨어납니다...'),
(17225, 1, 0, '정말 멍청하군! 고통 없이 빨리 끝내주마!'),
(17225, 2, 0, '이 더러운 기생충들, 내가 하늘에서 너희의 씨를 말리리라!'),
(17225, 3, 0, '그만! 내 친히 내려가서 너희를 짓이겨주마!'),
(17225, 3, 1, '하루살이 같은 놈들! 나의 힘을 똑똑히 보여주겠다!'),
(17225, 4, 0, '%s|1이;가; 숨을 깊게 한번 들이마십니다.'),
(17230, 0, 0, '아롱이가 굶주림에 가득 찬 눈으로 비에라 선위스퍼를 쳐다봅니다.'),
(17233, 0, 0, '날 기억하고 여기까지 와주다니 고맙네. 그 상징이 꼭 필요한 건 아니었네만 그걸 되찾아 온 그대의 노력이 이 늙은이의 마음을 감동시키는군.'),
(17233, 1, 0, '부디 일어나게, 내 친구여. 성스러운 빛의 힘을 나타내는 상징으로서 축복받은 마음을 간직하고 있으면, 오랫동안 모습을 감추었던 영웅들이 다시 한번 일어나 모든 이에게 용기를 줄 걸세.'),
(17233, 2, 0, '친구여, 당신 덕분에 이번 일을 할 수 있었소. 고맙소이다. 오늘 일은 절대 잊을 수 없을 것이오! 난 잠시 여기서 우서 경께서 하신 말씀을 마음에 새기겠소. 당신은 서리바람 야영지의 대여사제 맥도널에게 돌아가시오. 그녀는 여기서 일어난 일들에 대해 매우 궁금해할 것이오.'),
(17233, 4, 0, '왜 이러는가? 생전에 내가 자네에게 무슨 잘못이라도 했는가?'),
(17233, 5, 0, '아, 이제 자네가 무슨 생각인지 알겠군. 내 생전의 제자가 이런 일을 하다니... 메라 돈블레이드. 그의 마음이 그토록 사악하게 변했다니 정말 안타깝군그래.'),
(17233, 6, 0, '메라에게 돌아가게. 돌아가서 내가 용서한다고 전해주게나. 그리고 그가 왜 그러는지 이해한다고도 전해 주게.'),
(17233, 7, 0, '내가 바라는 것은 오직 그가 성스러운 빛의 정의를 깨닫고 열정을 다해 한때 아름다웠던 쿠엘탈라스를 재건하는 것뿐이라네.'),
(17238, 0, 0, '적의 공격이오! 조심하시오!'),
(17238, 1, 0, '스컬지가 우리를 공격하는 이유는 분명 빛의 수호자의 징표가 지닌 순수함 때문이오. 당하지 않으려면 조심해서 전진해야 하오!'),
(17238, 2, 0, '이 땅은 반드시 성스러운 빛으로 정화해야겠군! 자, 계속해서 무덤으로 갑시다. 얼마 안 남았소.'),
(17240, 0, 0, '이보라고, 쿠키! 오늘 저녁은 뭔가? 제발 닭고기만은... 이제 질렸으니까!'),
(17240, 1, 0, '오오! 정말인가?'),
(17240, 2, 0, '네 녀석이 정말 밉구나, 쿠키.'),
(17242, 0, 0, '오, 물론입니다! 아름다우신 여사제님, 당신을 위해서라면 무엇이든지 합지요!'),
(17242, 1, 0, '자. 어디 서판을 좀 볼까요?'),
(17242, 2, 0, '%s|1이;가; 드워프어로 중얼거리며 천천히 서판을 읽습니다.'),
(17242, 3, 0, '나가 장군! 오, 이런...'),
(17242, 4, 0, '아름다우신 여사제님, 제가 말씀드릴 내용이 심기를 불편하게 해드릴지도 모르겠군요. 이 서판은 나가의 통신 수단입니다. 나가의 지도자인 장군 스리스티즈가 부하들에게 섬의 나머지 지역을 무력으로 점령하라고 명령한 내용이 담겨 있습니다.'),
(17242, 5, 0, '그리고 나즈자타에서 나가 증원군이 온 것 같군요!'),
(17242, 6, 0, '뭔가 손을 써야 합니다!'),
(17243, 0, 0, '그렇습니다, 주인님. 모든 것이 계획대로 진행되고 있습니다.'),
(17243, 1, 0, '%s|1이;가; 눈높이까지 껍질을 들어올립니다.'),
(17243, 2, 0, '이제 널 베겠다!'),
(17243, 3, 0, '무슨 짓인가? 너 때문에 내 정체가 거의 드러날 뻔했잖아, 멍청한 녀석! 내가 분명 나침반하고 항해 지도를 안전한 곳에 두라고 하지 않았나. 바보도 쉽게 찾을 수 있는 뻥 뚫린 곳 말고!'),
(17243, 4, 0, '주인님께서는 엑소다르의 소재에 관한 정보를 지키려고 엄청난 노력을 하셨다. 너 때문에 내부 첩자가 발각될 뻔했을 뿐만 아니라 우리 계획도 전부 엉망이 될 뻔했다는 걸 아나?'),
(17243, 5, 0, '진정하라고? 캘타스 님께서 그분께 실망을 안겨준 자들에게 어떻게 하시는지 알고나 하는 소린가, 기즐? 영원한 고통과 괴로움에 몸부림치는 거다... 이번 일을 망치면 알아서 해, 멍청한 고블린 녀석.'),
(17243, 6, 0, '우리 핏빛안개 척후병들이 우리 정보원의 위치를 파악했다. 그 멍청이 벨렌은 곧 무방비 상태가 될 것이다. 우리가 습격하기에 충분한 시간이지! 이제, 네놈을 없애 버리기 전에 눈앞에서 사라져라...'),
(17243, 7, 0, '%s|1이;가; 나가 깃발을 집어듭니다.'),
(17246, 0, 0, '어, 함장님. 생각할 시간을 좀... 으음... 결정했습니다.'),
(17246, 1, 0, '육즙이 많은 돼지 갈비와 샌더 선장의 비밀 소스로 양념한 옆구리살을 준비하지요.'),
(17246, 2, 0, '그리고 후식으론 천사들의 날개에 실어 스톰윈드에서 공수해 온 신선한 치즈 케이크가 좋겠군요.'),
(17246, 3, 0, '아니요, 아... 닙니다...'),
(17246, 4, 0, '송구스럽지만... 닭고기입니다...'),
(17259, 0, 0, '이 세계는 우리 것이다!'),
(17259, 0, 1, '우리가 바로 진정한 호드다!'),
(17259, 0, 2, '피는 우리의 힘이다!'),
(17271, 0, 0, '카르가스 만세! 승리를 위해!'),
(17271, 0, 1, '우리가 바로 진정한 호드다!'),
(17271, 0, 2, '피는 우리의 힘이다!'),
(17281, 0, 0, '%s|1이;가; 격노합니다!'),
(17300, 0, 0, '%s|1이;가; 도움을 요청합니다!'),
(17306, 0, 0, '냄새가 나지 않나? 어쩐 일인지 신선한 살덩이들이 우리 요새를 침입했구나. 침입자를 조심하라.'),
(17306, 1, 0, '빨리, 치유해라!'),
(17306, 2, 0, '물러서라, 애송이!'),
(17306, 3, 0, '이것들은 대체 뭐지?'),
(17306, 3, 1, '조금은 아플 거다...'),
(17306, 3, 2, '점점 재미있어지는군...'),
(17306, 4, 0, '작별을 고해라!'),
(17306, 4, 1, '너무 쉽잖아!'),
(17306, 5, 0, '작별을 고해라!'),
(17307, 0, 0, '수많은 시련을 겪어왔겠지. 안타깝군. 결국엔 모두 헛수고니까! 너희는 그분께 무릎을 꿇으리라.'),
(17308, 0, 0, '감히 나에게 맞서려느냐?'),
(17308, 0, 1, '난 절대 패배하지 않는다!'),
(17308, 0, 2, '그 오만함이 죽음으로 이끌 것이다!'),
(17308, 1, 0, '아코르 쉬 카이! 내 강아지들아, 배불리 먹어라.'),
(17308, 2, 0, '아 크리쉬!'),
(17308, 3, 0, '죽어라, 약해빠진 것!'),
(17308, 4, 0, '아직... 끝난 건 아니다.'),
(17308, 5, 0, '내가 승리한다!'),
(17312, 1, 0, '도와주세요!'),
(17318, 0, 0, '무슨 일이라도 있습니까, 불똥 님? 모이라고 하신 이유가 뭡니까?'),
(17318, 1, 0, '진정하십시오, 불똥 님! 모든 것이 제 통제 하에 있습니다. 우리는 그들 몰래 엑소다르에서 채굴을 할 것이고 불똥님과 저는 아주 큰 부자가 될 겁니다.'),
(17318, 2, 0, '네, 알겠습니다. 다시는 이런 일이 없도록 하겠습니다...'),
(17370, 0, 0, '로크나라쉬!'),
(17375, 0, 0, '[펄볼그어] 너울소나무 펄볼그는 당신의 용감한 행동을 잊지 못할 것입니다!'),
(17375, 0, 1, '[펄볼그어] 감사합니다, $n!'),
(17375, 0, 2, '[펄볼그어] 감사합니다. 너울소나무 요새에 남아 있는 이들이 당신을 영웅으로 환영할 겁니다!'),
(17375, 0, 3, '[펄볼그어] 오, 예언이 사실이로군요! 구해주셔서 감사합니다.'),
(17375, 0, 4, '%s|1이;가; 자신을 잡아 온 자들을 향해 으르렁거립니다.'),
(17377, 0, 0, '누가 감히... 이게 무슨 짓이냐? 너희가 모든 것을 망쳐놓았다!'),
(17377, 1, 0, '그를 풀어줘서는 안 돼!'),
(17377, 1, 1, '아무것도 모르는 것들이!'),
(17377, 1, 2, '바보들아, 그가 우리를 모두 죽일 것이다.'),
(17377, 2, 0, '너희들은 죽어 마땅하다.'),
(17377, 2, 1, '친구들도 곧 네 뒤를 따르리라.'),
(17377, 3, 0, '가까이... 더 가까이... 활활 타오르리라!'),
(17377, 4, 0, '요행이 있기만 빌어야 할 거다.'),
(17379, 0, 0, '%s|1이;가; 자기를 따라오라고 합니다.'),
(17379, 1, 0, '%s|1이;가; 쿠우의 토템을 가리킵니다.'),
(17380, 0, 0, '덤벼라, 침입자여.'),
(17381, 0, 0, '나의 실험을 방해하지 마라!'),
(17381, 0, 1, '너희는 좋은 재료가 되겠어...'),
(17381, 0, 2, '증오... 분노... 난 이런 것들을 다루는데 익숙하지.'),
(17381, 1, 0, '너희를 어떻게 변형할 수 있을지 한번 보자!'),
(17381, 1, 1, '저항해봤자 소용없다.'),
(17381, 2, 0, '내게서 떨어져!'),
(17391, 0, 0, '%s|1이;가; 자기를 따라오라고 손짓합니다.'),
(17391, 1, 0, '[펄볼그어] 릭트 킨칙스 아줄 하늘 꼭대기...'),
(17391, 2, 0, '[펄볼그어] 쿠우 시프 플라이... 로스 강을 건너라. 티크티를 찾아라.'),
(17392, 0, 0, '%s|1이;가; 자기를 따라오라고 합니다.'),
(17392, 1, 0, '[펄볼그어] 멀리까지 믹식 탁 너 가라. 강을 키취칼 자세히 보라. 따라오너라. 요르까지 일로그.'),
(17392, 2, 0, '[펄볼그어] 가라... 이틱스킬 강 바닥을 조사해 보라. 남쪽이다!'),
(17410, 0, 0, '[펄볼그] 적이 저지른 이 야만스러운 짓의 증인이 돼라, $n. 그들이 우리의 젊은이들을... 힘없는 자들을... 여기에 이 뾰족가지 일족의 우리에 가둬놨다. 그들을 구하라, 예언의 현신이여!'),
(17414, 0, 0, '%s|1이;가; 근접 폭발 폭탄을 작동시킵니다!'),
(17414, 1, 0, '%s|1이;가; 근접 폭발 폭탄을 작동시킵니다!'),
(17420, 0, 0, '%s|1이;가; 격노합니다!'),
(17455, 0, 0, '전투견을 풀어놓을 때까지 침입자들을 막아라!'),
(17455, 1, 0, '도망가기엔 너무 늦었다. 이제 내 전투견의 분노를 맛보아라!'),
(17491, 0, 0, '가카라 마!'),
(17491, 0, 1, '우리가 바로 진정한 호드다!'),
(17521, 0, 0, '잡아 먹기 좋으라고 그런거지!'),
(17521, 1, 0, '음... 맛있구나.'),
(17521, 2, 0, '도망쳐라, 꼬마야! 달아나라...'),
(17533, 0, 0, '기어코 나를 화나게 하는구나? 그렇다면 받아라, 애송이!'),
(17533, 1, 0, '그대들은 나를 쓰러뜨린 그 일격을 자랑스러워하며... 미소짓는구나.'),
(17533, 2, 0, '그대들은 나를 쓰러뜨린 그 일격을 자랑스러워하며... 미소짓는구나.'),
(17533, 3, 0, '추악한 욕망과 죽음의 모태여, 그대들의 썩어빠진 입을 벌려주마!'),
(17533, 4, 0, '이야말로 나를 위로하는 커다란 즐거움이지!'),
(17534, 1, 0, '당신들은 대체 누구시기에 절 이리도 괴롭히나요?'),
(17536, 0, 0, '나잔이 하늘에서 내려옵니다.'),
(17537, 0, 0, '더 도전할 자가 남아 있느냐?'),
(17537, 1, 0, '너희의 종말이 다가오고 있다.'),
(17537, 1, 1, '미개한 종족아! 나는 높으신 분의 부름을 받는 몸이시다.'),
(17537, 1, 2, '어둠의 군주께서 너희를 비웃고 계시노라.'),
(17537, 2, 0, '끝났다! 해치웠어!'),
(17537, 2, 1, '너희의 시간은 끝났다!'),
(17537, 3, 0, '그분께서 오시면... 너희는 모두 파멸을 맞으리라!'),
(17543, 0, 0, '너희를 어떻게 해주면 좋을까? 아무 생각도 나지 않아!'),
(17543, 1, 0, '날... 빗자루로만은 만들지 말아줘.'),
(17543, 2, 0, '나도 분명 쓸모가 있다고!'),
(17546, 0, 0, '하나도 안 무섭다고! 덤벼! 앞발 두 개를 몽땅 꺼내서 할퀴어주마!'),
(17546, 1, 0, '꼭 이럴 필요는 없었잖아!'),
(17546, 2, 0, '그 누구도 창조자의 비밀을 훔칠 수 없다!'),
(17547, 0, 0, '나도 심장 갖고 싶어. 너희들 것 나한테 주면 안 될까?'),
(17547, 1, 0, '다시 낡은 양철통 신세로구나!'),
(17547, 2, 0, '내 솜씨가 아직 녹슬지 않았네.'),
(17547, 3, 0, '%s|1이;가; 녹슬기 시작합니다!'),
(17554, 0, 0, '경비병!'),
(17555, 0, 0, '경비병!'),
(17591, 0, 0, '네놈의 돈을 뺏을까 목숨을 앗아갈까! 너의 목숨이 더 좋겠구나...'),
(17591, 0, 1, '너의 죽음은 왕께 바치는 좋은 선물이 될 것이다!'),
(17591, 0, 2, '실버문 만세! 선스트라이더 만세!'),
(17621, 0, 0, '%s|1이;가; 격노합니다!'),
(17623, 0, 0, '%s|1이;가; 격노합니다!'),
(17626, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17651, 0, 0, '용이여, 나를 화나게 하는군. 난 아랫마을 주민들처럼 쉽게 겁먹지는 않을 걸세.'),
(17651, 1, 0, '감히 내 집에서 나에게 도전하다니 아무리 용이라지만 오만함이 하늘을 찌르는구나!'),
(17651, 2, 0, '자네가 무슨 말을 하는지 모르겠군, 용이여... 하지만, 나는 이런 무례한 행동에 겁을 먹지는 않을 것이야. 때가 되면 그때 카라잔을 떠날 것일세!'),
(17651, 3, 0, '%s|1이;가; 강력한 마법을 걸어 자신의 정수를 마력으로 바꿉니다.'),
(17651, 4, 0, '내 화를 돋우지 말았어야 했다. 이제 그만 가야한다... 내 힘을 회복해야 해...'),
(17652, 0, 0, '메디브여, 비전에 대한 그대의 연구는 도를 넘어섰도다. 그대의 연구가 그대가 이해할 수 있는 범위를 넘어선 강력한 존재들의 관심을 끌었더군. 그대는 지금 즉시 카라잔을 떠나야 한다!'),
(17652, 1, 0, '어둠의 힘이 그대를 이용하려고 기다리고 있도다, 메디브여! 이곳에 계속 머무를수록 끔찍한 일을 겪게 될 것이다. 시간이 얼마 없으니 서둘러야 한다!'),
(17652, 2, 0, '선택의 여지를 주지 않는구나, 메디브. 충고를 들으려 하지 않는다면 힘으로 막는 수밖에 없도다!'),
(17652, 3, 0, '마법사여, 이... 무슨 짓을 한 것인가? 어떻게 이럴 수가! 내 몸속에서... 불이 타오르다니!'),
(17664, 0, 0, '날 찾은 걸 후회하게 해 주마, 어리석은 놈.'),
(17664, 1, 0, '%s|1이;가; 의식을 잃습니다.'),
(17681, 0, 0, '야호! 고맙습니다!'),
(17682, 0, 0, '구해 주셔서 정말 감사합니다, $n! 우리 아버지께서 기뻐하실 거예요!'),
(17702, 0, 0, '뾰족가지 펄볼그의 분노를 받아라!'),
(17711, 0, 0, '접근 금지. 너희는 제거될 것이다.'),
(17711, 1, 0, '지각 붕괴 실행 중...'),
(17711, 1, 1, '진도 조정 완료. 방출!'),
(17711, 2, 0, '경로 설정 완료.'),
(17711, 2, 1, '전속력 추진.'),
(17711, 3, 0, '위협 수준 초기화.'),
(17711, 3, 1, '지령 완수.'),
(17711, 3, 2, '제거 완료.'),
(17711, 4, 0, '시스템 정지 5초 전, 4... 3...'),
(17723, 0, 0, '%s|1이;가; 격노합니다!'),
(17725, 0, 0, '%s|1이;가; $n|1을;를; 보더니 점점 커집니다!'),
(17725, 1, 0, '%s의 힘이 점점 약해집니다.'),
(17727, 0, 0, '일리단 만세!'),
(17728, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17729, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17730, 0, 0, '%s|1이;가; 대량 치유를 시전합니다!'),
(17732, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17734, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17735, 0, 0, '%s|1이;가; 격노합니다!'),
(17767, 0, 0, '날 꺾었을진 몰라도 이 전쟁은... 어림없다!'),
(17767, 1, 0, '생명체는 다 사라져야 해!'),
(17767, 1, 1, '불타는 군단에 승리를!'),
(17767, 2, 0, '부서지고 썩어가리라!'),
(17767, 2, 1, '먼지에서 왔으니 먼지로 돌아가라!'),
(17767, 3, 0, '죽음의... 한기에 굴복하라.'),
(17767, 3, 1, '무덤 속보다 더 추울 것이다.'),
(17767, 4, 0, '불타는 군단의 마지막 정복 작전이 시작됐다! 다시 한번, 이 세계를 우리 손 안에 거머쥐리라! 아무도 살려두지 않겠다!'),
(17768, 0, 0, '더 도전할 자가 남아 있느냐?'),
(17772, 2, 0, '포기라뇨! 반드시 승리뿐입니다!'),
(17796, 0, 0, '진정한 고통이 뭔지 알려주겠다!'),
(17796, 1, 0, '고통의 세계를 보여주마!'),
(17796, 1, 1, '금속의 뜨거운 맛을 봐라, 더러운 놈들!'),
(17796, 1, 2, '내가 그쪽으로 가마!'),
(17796, 1, 3, '진정한 고통이 뭔지 알려주겠다!'),
(17796, 2, 0, '애송이, 제대로 대접받으니 어때!'),
(17796, 2, 1, '내가 널 차지했다!'),
(17796, 2, 2, '잘 죽었다, 식은 죽 먹기로군.'),
(17796, 3, 0, '엄마야! 무서워라...'),
(17797, 0, 0, '잘 죽었다, 식은 죽 먹기로군.'),
(17798, 0, 0, '내 경비병들을 꺾었다고 아주 기고만장을 하는구나. 우리 계획에 타협이란 없다!'),
(17798, 1, 0, '아직 끝나지 않았다.'),
(17798, 2, 0, '곧 너희들의 시체가 산을 이룰 것이다.'),
(17798, 2, 1, '네 종족은 정말 싫어!'),
(17798, 2, 2, '바안탈소 도레이!'),
(17798, 3, 0, '아무리 발버둥쳐도 소용없다!'),
(17798, 3, 1, '네 종족은 정말 싫어!'),
(17798, 4, 0, '군주님을 위하여!'),
(17805, 0, 0, '%s|1이;가; 격노합니다!'),
(17807, 0, 0, '시험을 시작하겠다! 블러드래스여, 공격하라!'),
(17807, 1, 0, '용사 라이트렌드여, 나를 자랑스럽게 해다오!'),
(17807, 2, 0, '스위프트블레이드, 벼락출세를 노리는 이 친구에게 진짜 혈기사가 싸우는 모습을 보여줘!'),
(17807, 3, 0, '$n에게 고통의 의미를 알려줘라, 선스트라이커!'),
(17807, 4, 0, '잘했네, $n! 두 번째 시험을 통과했어!'),
(17808, 0, 0, '그래도 종말의... 시계는... 돌아간다.'),
(17808, 1, 0, '희망은 사라졌다!'),
(17808, 1, 1, '날 위해 비명을 질러라.'),
(17808, 1, 2, '천천히 죽여줄 시간이 없어 아쉽구나!'),
(17808, 2, 0, '박쥐들이 많이 굶주렸구나.'),
(17808, 2, 1, '역병에 뒤덮이리라!'),
(17808, 3, 0, '영원히 잠재워주마...'),
(17808, 3, 1, '잘 자라.'),
(17808, 4, 0, '하늘에서 불 비가 내릴지어다!'),
(17808, 4, 1, '하늘과 땅이 모두 타오르리라!'),
(17808, 5, 0, '멸망에 처한 세계의 수호자들이여, 구차한 목숨이라도 건지려면 어서 달아나라!'),
(17826, 0, 0, '야수야, 내 명령에 복종하라! 저들을 모조리 죽여라!'),
(17826, 1, 0, '우리는 끝까지 싸울 것이다!'),
(17826, 1, 1, '곧 끝내주마...'),
(17826, 1, 2, '아칼라 페크 엑타!'),
(17826, 2, 0, '크립타!'),
(17826, 2, 1, '네놈도 끝났다.'),
(17826, 3, 0, '다... 끝났다.'),
(17835, 0, 0, '저 마법사는 몰락할 것이다!'),
(17835, 0, 1, '우리는 결코 멈추지 않는다!'),
(17835, 0, 2, '너희의 노력은... 쓸데없는 짓이니라.'),
(17839, 0, 0, '승리 또는 죽음!'),
(17839, 0, 1, '너희에게는 시간이 얼마 없다!'),
(17839, 0, 2, '균열을 보호해야 한다!'),
(17840, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17842, 0, 0, '네놈들의 시대는... 끝났다.'),
(17842, 1, 0, '리쉬, 혹타!'),
(17842, 1, 1, '쓸데없이 저항하지 마라.'),
(17842, 1, 2, '아무도 널 구해주지 못해.'),
(17842, 2, 0, '이것은 시작에 불과하다!'),
(17842, 2, 1, '죽어라! 미천한 벌레 같은 것들!'),
(17842, 3, 0, '희망 따위는 버려라! 오래전 시작한 계획을 마무리하고자 불타는 군단이 돌아왔다. 이번엔 절대 피할 수 없다!'),
(17848, 0, 0, '뭐야! 이봐, 어서 물을 가져와라! 요새 전체로 번지기 전에 불을 꺼야 한다! 빨리, 젠장!'),
(17848, 1, 0, '무슨 일로 왔는지 알고 있다. 그 일에 영원히 마침표를 찍어주지!'),
(17848, 2, 0, '무슨 일로 왔는지 알고 있다. 그 일에 영원히 마침표를 찍어주지!'),
(17848, 2, 1, '더 이상 방해하지 마라!'),
(17848, 3, 0, '피를 볼 시간이군!'),
(17848, 4, 0, '도망가라! 이 겁쟁이들아!'),
(17848, 5, 0, '스랄을... 풀어줘서는... 안 돼.'),
(17852, 0, 0, '누구도 날 쓰러뜨릴 수 없다!'),
(17852, 0, 1, '목숨을 걸 용기가 있다면 덤벼 봐라!'),
(17852, 1, 0, '흔들리지 마라! 놈들을 막아야 한다!'),
(17852, 2, 0, '흔들리지 마라! 놈들을 막아야 한다!'),
(17852, 3, 0, '승리 또는 죽음!'),
(17852, 3, 1, '단 한 치도 허용하지 않겠다!'),
(17852, 4, 0, '이제 끝이다! 후퇴! 우리가 졌다...'),
(17852, 5, 0, '우리가 할 일은 여기까지다. 잘했다 제군들! 이제부터는 다른 용사들에게 맡기겠다.'),
(17852, 6, 0, '단 한 치도 허용하지 않겠다!'),
(17853, 0, 0, '드디어 잡았구나, $n!'),
(17853, 1, 0, '쿠로스 님께 돌아가십시오. 나는 마티스를 핏빛 감시초소로 데려가겠습니다.'),
(17862, 0, 0, '스랄! 네가 탈출할 수 있다고 생각하나? 너와 네 동료들은 블랙무어와 대면해야 할 것이다. 내가 충분히 재미를 본 다음에 말이지.'),
(17862, 1, 0, '넌 노예다! 그것이 너의 영원한 운명이다!'),
(17862, 2, 0, '블랙무어가 대체 너에게 무얼 기대하는지 모르겠군. 돈으로 살 수 있는 한낱 노예 따위에 불과한데 말이야.'),
(17862, 3, 0, '스랄은 절대 자유의 몸이 될 수 없어!'),
(17862, 3, 1, '살아서 여길 나갈 수 있으리라 생각하나?'),
(17862, 4, 0, '경비... 경비병!'),
(17876, 0, 0, '그럼, 어서 갑시다!'),
(17876, 1, 0, '새로운 계획에 따라야 한다면 무기와 갑옷을 갖추는 게 좋겠소이다.'),
(17876, 2, 0, '추적자가 오고 있소.'),
(17876, 3, 0, '다시는 억압받지 않을 것이다!'),
(17876, 4, 0, '좋소. 타렌 제분소는 여기서 서쪽에 있소. 시간이 많지 않소.'),
(17876, 5, 0, '어서 갑시다.'),
(17876, 6, 0, '타레사가 여관에 있는 게 틀림없군. 자, 갑시다.'),
(17876, 7, 0, '타레사! 이 사악한 마력은 대체 뭐요?'),
(17876, 8, 0, '뭐였지?'),
(17876, 9, 0, '안 돼!'),
(17876, 10, 0, '타레사, 잘 있으시오. 당신의 호의는 결코 잊지 않겠소.'),
(17876, 11, 0, '느낌이 좋지 않다...'),
(17876, 11, 1, '끝까지... 싸울 것이다!'),
(17876, 12, 0, '타레사...'),
(17876, 12, 1, '죽기... 좋은 날이군..'),
(17876, 13, 0, '자유를 얻었노라!'),
(17876, 13, 1, '갈 길이 멀다! 어서 길을 비켜라!'),
(17876, 13, 2, '난 더 이상 노예가 아니다!'),
(17876, 13, 3, '블랙무어는 그 대가를 치를 것이다!'),
(17876, 14, 0, '너희가 자초한 일이다!'),
(17876, 14, 1, '이런 결말을 바라진 않았다!'),
(17876, 14, 2, '누가 이런 대접을 바란다고 했나!'),
(17876, 15, 0, '이방인들이여, 당신들에게 너무나도 많은 빚을 졌소.'),
(17876, 15, 1, '고맙소, 이방인들이여. 당신들로 인해 희망의 빛을 보았소.'),
(17876, 15, 2, '이 기회를 헛되이 하지 않겠소. 내 운명을 찾아 나설 것이오.'),
(17877, 0, 0, '프우르 인제 간다, $n. 방주 가지고 돌아온다.'),
(17877, 1, 0, '나가 처치 준비 시간이다.'),
(17877, 2, 0, '우리 간다!'),
(17877, 3, 0, '%s|1이;가; 쉬슬리스의 방주를 가볍게 들어올립니다.'),
(17877, 4, 0, '이런...'),
(17877, 5, 0, '으하, 흐물흐물한 나가들!'),
(17877, 6, 0, '%s|1이;가; 쉬슬리스의 방주를 땅에 내려놓습니다.'),
(17877, 7, 0, '프우르 잘했다!'),
(17878, 0, 0, '네 손에 죽는 것 따위는 두렵지 않다, $r!'),
(17878, 0, 1, '난 아무것도 말하지 않을 거다, 이 돼지 같은 $r 녀석아!'),
(17878, 0, 2, '그녀가 드워프를 네게 돌려주는 일은 없을 거다!'),
(17878, 0, 3, '그 드워프는 우리 손에 들어왔다! 이제 네 동료가 아니야!'),
(17878, 1, 0, '역병숲은 아주 넓지! 네 친구는 그 속으로 사라졌으니, 절대 찾지 못할 거다!'),
(17878, 2, 0, '멍청한 $r 같으니! 드워프를 찾고 있다고? 아나스타리 남작부인이 아주 잘 숨겨두셨다!'),
(17879, 0, 0, '왜 저 마법사를 돕는 거냐? 차원문이 열리지 않아서 전쟁이 일어나지 않으면 얼마나 많은 목숨을 구할 수 있는지 생각해 봐라.'),
(17879, 1, 0, '이 어리석은 임무를 당장 그만두지 않으면 죽음을 면치 못하리라!'),
(17879, 2, 0, '시간의 수호자여, 너무 오래 머물렀다, 사라져라!'),
(17879, 3, 0, '바보 같은 임무라고 했잖나!'),
(17879, 3, 1, '벌써 가는 건가?'),
(17879, 4, 0, '시간은... 우리 편이다.'),
(17880, 0, 0, '왜 고집을 피우는 게냐? 어차피 다 헛된 일... 아직 늦지 않았어! 살 수 있을 때 도망쳐라!'),
(17880, 1, 0, '계속 그렇게 나오겠다는 건가? 분명 경고했다.'),
(17880, 2, 0, '시간의 수호자여, 모래시계의 흐름이 멈추었다!'),
(17880, 3, 0, '기회가 있을 때 이곳을 떠났어야 했다.'),
(17880, 3, 1, '네 운명의 시간이 다했구나.'),
(17880, 4, 0, '나의 죽음으로 달라질 것은... 없다.'),
(17881, 0, 0, '이 쳇바퀴처럼 돌아가는 세상을 영원히 부서뜨릴 때가 왔다! 우린 모래시계의 노예가 아니야! 경고한다. 이 위대한 뜻을 거부하는 자, 첫 번째 희생양이 되리라!'),
(17881, 1, 0, '어떤 운명이 기다리고 있는지 한번 볼까...'),
(17881, 2, 0, '과거의 노예여, 너의 시간이 끝났다.'),
(17881, 3, 0, '우리 앞에 장애물이 하나 줄었구나!'),
(17881, 3, 1, '누구도 우릴 막을 수 없어! 그 누구도!'),
(17881, 4, 0, '우리는 승리한다. 단지 시간문제일 뿐...'),
(17881, 5, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17888, 0, 0, '샤자 키엘!'),
(17888, 0, 1, '네놈은 상대가 안 된다!'),
(17888, 0, 2, '한심하고 성가신 것!'),
(17888, 1, 0, '너에겐 고통스러운 죽음을 선사해주마.'),
(17888, 1, 1, '넌 이제... 벗어날 수 없다.'),
(17888, 2, 0, '살려달라고 울부짖어 봐라! 너의 부질없는 목숨을 거두리라!'),
(17892, 0, 2, '우리에게 실패란 없다!'),
(17893, 0, 0, '이봐요! 여기 이쪽입니다! 네, 여기 이쪽... 이 우리 안에 있습니다!!!'),
(17941, 0, 0, '작업은 계속되어야 한다!'),
(17941, 0, 1, '너희가 자초한 일이야!'),
(17941, 0, 2, '이러면 너희를 죽일 수밖에 없어!'),
(17941, 1, 0, '이럴 수밖에 없었다.'),
(17941, 1, 1, '이곳에 오지 말아야 했어...'),
(17941, 2, 0, '난... 죽어 마땅하다...'),
(17949, 0, 0, '레물로스, 내 오랜 벗이여... 다시 만나 반갑네. 자네에게 어떻게든 그 전갈이 전해질 거라 생각했네.'),
(17949, 1, 0, '친구여, 나는 사태가 악화될까 두렵네. 에메랄드의 꿈속에서 우리는 고대의 악마로 태어난 새로운 적과 싸우고 있네. 이세라의 고귀한용군단은 고대의 속삭임에 희생되었네. 마치 악몽이 차원의 경계를 뚫고 아제로스에서 새로운 숙주를 찾고 있는 것 같네.'),
(17949, 2, 0, '그렇다네, 레물로스. 아제로스의 종족들은 이제 그들과 맞설 준비를 해야 해.'),
(17949, 3, 0, '세나리우스는 내 편이 돼주기로 했네. 아웃랜드로 간 일리단은 거기서 왕좌에 앉아 있네. 그런데 아서스에게 패한 게 원통했기 때문인지 완전히 미쳐버리고 말았어. 광기에 휩싸여 하루에도 천 번 그때 그 사건을 마음속으로 재연하고 있네. 아서스를 무찌르고 승리하는 상상을 하는 거지. 그는 제정신이 아니야. 친구여, 난 머지않아 우리가 시험을 받게 될 날이 오지 않을까 두렵네. 진아즈샤리의 샘에서처럼 잘해낼 수 있을 자신도 없고 말일세.'),
(17949, 4, 0, '레물로스, 나는 다시 빨려들어가고 있네. 티란데... 그녀에게 사랑한다고... 난 잘 있다고 전해 주게. 꼭 그녀에게 돌아가겠다고... 잘 있게.'),
(17955, 0, 0, '%s|1이;가; 버섯을 조금 뜯어서 ''코''에 가져다 대더니 만족스러운 듯 먹습니다!'),
(17955, 1, 0, '%s|1이;가; 나머지 버섯을 모두 뽑아들고는 사라집니다.'),
(17957, 0, 0, '침입자가 죄수를 데리고 달아난다! 놈들을 처치하라!!!'),
(17959, 0, 0, '아직 멀었다! 이렇게 빨리 지치다니!'),
(17959, 0, 1, '일어나라! 이제 일하러 가란 말이다!'),
(17959, 0, 2, '서둘러라! 시간을 지체할수록 너에게 가해지는 고통만 커진다는 것을 모르나!'),
(17959, 1, 0, '뭐야?! 가정교육도 못 받았나?'),
(17959, 1, 1, '다시 일을 시작해라!'),
(17959, 1, 2, '정말 끔찍하다... 너희처럼 게으른 일꾼을 매질하느라 내 팔이 떨어질 지경이야!'),
(17959, 2, 0, '날 도와라, 노예들아!'),
(17962, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(17968, 1, 0, '아무리 저항해도 소용없다!'),
(17968, 2, 0, '온 세상을 불살라 버리겠다!'),
(17968, 2, 1, '마나크 쉬크 스리쉬!'),
(17968, 3, 0, '아 크리쉬!'),
(17968, 3, 1, '물러서라, 버러지들아!'),
(17968, 4, 0, '모든 생명을 삼켜버리겠다.'),
(17968, 4, 1, '네 영혼은 영원히 고통받으리라!'),
(17968, 4, 2, '종말을 선사하러 왔다!'),
(17968, 5, 0, '마침내 끝났도다! 동지들의 죽음을 애도하라! 이루지 못한 꿈을 그리며 슬피 울어라! 하크 민 코레이!'),
(17968, 6, 0, '안돼! 이럴 수는 없어! 안돼!'),
(17968, 7, 0, '이제 넌 내 것이다.'),
(17968, 7, 1, '내 뜻에 굴복하라.'),
(17975, 0, 0, '무슨 짓이냐? 그 종은 아주 연약하단 말이다!'),
(17975, 1, 0, '네 생명 주기는 끝났다.'),
(17975, 1, 1, '벌레 먹이로 주마.'),
(17975, 2, 0, '엔도렐 아누미노르!'),
(17975, 3, 0, '자연의 힘이 내 손안에 있다...'),
(17975, 4, 0, '저 종들을... 지켜야 하는데...'),
(17975, 5, 0, '가시 덩굴... 중얼중얼... 아냐!'),
(17975, 5, 1, '중얼중얼...'),
(17975, 5, 2, '중얼중얼... 화염초 꽃잎... 중얼중얼...'),
(17975, 5, 3, '조합만 제대로 하면...'),
(17977, 0, 0, '감히 누가 소란을 피우느냐?'),
(17977, 1, 0, '죽어라! 아니, 저 잠깐만, 이건... 아니, 아니야... 넌 죽어야 돼!'),
(17977, 1, 1, '내가 무슨 짓을 한 거지? 왜 내가...'),
(17977, 2, 0, '얘들아! 내게로 와라!'),
(17977, 2, 1, '으, 이게 아닌데... 아냐, 싸운다! 어서 도와라!'),
(17977, 3, 0, '정말... 혼란스럽군. 너희는... 어서 떠나라.'),
(17978, 0, 0, '이 무슨 불미스러운 일이냐? 죽여주마!'),
(17978, 1, 0, '보상을 찾는다고? 죽음은 어떤가?'),
(17978, 2, 0, '그러게 내가 뭐라고 그랬나...'),
(17978, 3, 0, '네 목숨은 내 것이다!'),
(17978, 4, 0, '너의 고통은 나의 기쁨이다!'),
(17978, 5, 0, '재로 만들어주마!'),
(17978, 5, 1, '타들어 가는 비명을 질러라!'),
(17978, 6, 0, '멀리는... 못 갈 것이다.'),
(17978, 7, 0, '%s|1이;가; 격노합니다!'),
(17980, 0, 0, '%s|1이;가; 이상한 소리를 냅니다.'),
(17991, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(18062, 0, 0, '%s|1이;가; 격노합니다!'),
(18069, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(18069, 1, 0, '로크다르 정말 멍청했다! 모고르가 저것보단 훨씬 잘 싸울 수 있었는데!'),
(18069, 2, 0, '이번 대전 모고르 전혀 감탄 안 했다! 스크라가스는 공기와 어둠의 존재다! 흐느적대는 오크 어린애 같았다!'),
(18069, 3, 0, '이제 진정한 영웅의 솜씨 맛 봐라! 도망갈 기회를 준다. 널 파괴... 박살... 널 죽이기 전에 도망가는 게 좋을 거다!'),
(18069, 4, 0, '더는 도망칠 기회 없다! 오우거의 빚 갚을 시간이다!'),
(18069, 5, 0, '으아악! 더는 친절한 오우거 없다! 너 감히 날 아프게 했다!!'),
(18069, 6, 0, '이건 뭐지? 불가능하다! 너 지금 모고르와 싸우는 거다! 널 부숴 버리겠다!'),
(18096, 0, 0, '스랄! 밖으로 나와서 네 운명을 받아들여라!'),
(18096, 0, 1, '타레사의 목숨이 위태롭다. 너희는 그녀를 살리고 싶겠지... 분명히 그녀를 구출하고 싶을 거야.'),
(18096, 0, 2, '아, 거기 있구나. 일을 조용히 처리하고 싶었는데 어쩔 수 없이 정면대결을 해야겠군. 스랄, 네 미래는 여기서 끝이다. 그러니까 너와 네 성가신 친구들은 모두 죽어줘야겠다!'),
(18096, 1, 0, '좋아, 네 존재 자체를 지워주마!'),
(18096, 1, 1, '운명을 거부할 수는 없다!'),
(18096, 2, 0, '이 무가치한 것들!'),
(18096, 2, 1, '스랄은 노예로 남을 것이고 타레사는 죽을 것이다. 그리고 넌 실패한 거야.'),
(18096, 3, 0, '그렇게 빠르지는 않군!'),
(18096, 3, 1, '원하는 만큼 발버둥쳐봐라.'),
(18096, 4, 0, '안 돼! 주인님께서... 노하실... 것이다.'),
(18098, 0, 0, '%s|1이;가; 현상 수배 전단에 붙은 정보를 검토합니다.'),
(18103, 0, 0, '실버문의 법을 준수하십시오. 그렇지 않을 경우 그에 상응하는 처벌을 받게 될 것입니다.'),
(18103, 0, 1, '성벽 안에서는 질서를 지키십시오.'),
(18105, 0, 0, '%s|1이;가; 격노합니다!'),
(18117, 0, 0, '%s|1이;가; 격노합니다!'),
(18119, 0, 0, '%s|1이;가; 격노합니다!'),
(18146, 0, 0, '%s|1이;가; 수호병 한 쌍에게 고개를 살짝 숙여 인사합니다.'),
(18146, 1, 0, '%s|1이;가; 수호병들을 보더니 눈썹을 찡그리며 못마땅하다는 표정을 짓습니다.'),
(18146, 2, 0, '%s|1이;가; 수호병들을 차례대로 훑어봅니다.'),
(18146, 3, 0, '%s|1이;가; 거만한 웃음을 지으며 순찰자들의 작은 훈련장을 둘러봅니다.'),
(18202, 0, 0, '어디로 빠져나가려고 하느냐? 놈들을 모두 죽여라!'),
(18206, 0, 0, '언제쯤이면 이 고통이 끝날까?'),
(18206, 0, 1, '도와주십시오! 제발 도와주세요!'),
(18206, 0, 2, '어떻게 이런 곳에 절 남겨둘 수 있단 말입니까?'),
(18209, 0, 0, '조심하시오!'),
(18209, 1, 0, '놈들의 탈출을 막아라! 강한 녀석을 먼저 해치워야 한다!'),
(18209, 2, 0, '녀석들이 더 많이 오고 있소! 조심하시오!'),
(18209, 3, 0, '어디로 빠져나가려고 하느냐? 놈들을 모두 죽여라!'),
(18209, 4, 0, '번개나 먹어라, 추악한 녀석!'),
(18209, 5, 0, '냉기 충격!'),
(18209, 6, 0, '저 위에 텔라아르로 가는 길이 있습니다. 수렁피 일족 녀석들이 추가 병력을 보내서 우리를 추적할 게 뻔하니 갈림길이 나오면 찢어져서 가기로 합시다. 우리 중 한 명은 텔라아르로 돌아가야만 합니다.'),
(18210, 0, 0, '조심하시오!'),
(18210, 1, 0, '녀석들이 더 많이 오고 있소! 조심하시오!'),
(18210, 2, 0, '번개나 먹어라, 추악한 녀석!'),
(18210, 3, 0, '냉기 충격!'),
(18210, 4, 0, '저들이 추적자들을 더 많이 보낼 경우를 대비해서 여기서 헤어지는 게 좋겠소. 우리 중 한 명은 가로쉬에게로 돌아가야 할 테니 말이오. 몸조심하시오, 이방인이여.'),
(18211, 0, 0, '놈들의 탈출을 막아라! 강한 녀석을 먼저 해치워야 한다!'),
(18262, 0, 0, '항복! 제발 죽이지 마십시오!'),
(18292, 0, 0, '나도 저 투사처럼 되고 싶군!'),
(18292, 0, 1, '저 투사가 이길까? 정말 승리할 수 있을까?'),
(18293, 0, 0, '잘 훈련된 강인한 신체의 소유자잖아!'),
(18296, 0, 0, '어떻게 저런 능력을 발휘한다지?'),
(18296, 0, 1, '나도 저 투사처럼 되고 싶군!'),
(18296, 0, 2, '오오! 저 근육 좀 봐!'),
(18311, 0, 0, '%s|1이;가; 격노합니다!'),
(18322, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(18337, 0, 0, '그 문제에 대해서 생각해보겠소. 도움이 필요하면 부르시오.'),
(18341, 0, 0, '네 영혼을 먹어주마.'),
(18341, 0, 1, '생명력이 느껴진다.'),
(18341, 0, 2, '저항하지 마라..'),
(18341, 1, 0, '그래... 나의 힘은 막강하다...'),
(18341, 1, 1, '더... 더 많이 필요하다..'),
(18341, 2, 0, '다시 공허로 돌아가는구나.'),
(18341, 3, 0, '%s|1이;가; 공허 속으로 스며듭니다...'),
(18344, 0, 0, '이게 무슨 일이야? 하, 손님이 찾아오실 줄은 몰랐는데 사과 말씀드리겠소. 보시다시피 우린 지금 무척 바쁘다오. 하지만, 손님 접대는 꼭 친히 이 몸께서 해드리겠소.'),
(18344, 1, 0, '우리 정식으로 소개도 안 한 것 같은데?'),
(18344, 1, 1, '멋진 전투로군, 아주 재미있어.'),
(18344, 1, 2, '즐거운 모험을 기다리고 있었소.'),
(18344, 2, 0, '아주 즐거운 시간이었소.'),
(18344, 2, 1, '잘 가시오.'),
(18344, 3, 0, '당신들에게 보여줄 아주 멋진 선물이 있지.'),
(18344, 4, 0, '작별 인사를 할 시간이군. 잘 있으시오.'),
(18351, 0, 0, '나그란드에서는 사냥감이 오우거 사냥한다!'),
(18351, 0, 1, '소금과 후추로 간을 하면 더 좋은 맛이 나겠군.'),
(18351, 1, 2, '알았다, 알았어! 룸프 항복이다!'),
(18369, 0, 0, '차라리 날 잡아먹으란 말이야! 너희처럼 지독한 냄새를 풍기는 놈들 옆에서 우리에 갇혀 있기는 정말 싫단 말이다, 이 뚱보 녀석들!'),
(18369, 0, 1, '거기 뚱보, 그렇게 뚱뚱한 몸으로 화장실은 어떻게 가지!?'),
(18369, 0, 2, '내가 여기서 나가기만 하면 너희는 다 죽었어!'),
(18369, 0, 3, '거기 얼간이, 먹을 것 좀 줄까!?'),
(18369, 0, 4, '아빠가 보고 싶어, 흑!'),
(18369, 1, 0, '고맙습니다! 아빠가 당신에게 크게 보상할 거예요! 그럼 안녕히!'),
(18371, 0, 0, '%s|1이;가; $n|1을;를; 집중 공격합니다!'),
(18373, 0, 0, '작별 인사를 할 시간이군. 잘 있으시오.'),
(18373, 1, 0, '일어나라, 나의 형제들이여. 일어나 싸워라!'),
(18373, 2, 0, '너의 생명을 내놓아야 할 것이다.'),
(18373, 2, 1, '이제 물러설 곳은 없다.'),
(18373, 2, 2, '참회의 기도나 올려라.'),
(18373, 3, 0, '너희의 마음을 어지럽히리라.'),
(18373, 3, 1, '네 영혼의 어둠을 응시하라.'),
(18373, 4, 0, '여기가 너의 무덤이 될 것이다!'),
(18373, 4, 1, '이제 넌 이곳을 떠돌게 될 것이다. 영원히!'),
(18373, 5, 0, '여기가 내가 속한 곳이다.'),
(18399, 0, 0, '푸른 형제들이 최고의 위치에 올랐다!'),
(18400, 0, 0, '로크다르 $n 부숴버린다!'),
(18401, 0, 0, '가까이... 이리 가까이 오너라... 이 공포의 군주께서 어떤 힘이 있는지 맛보게 해주마!'),
(18402, 0, 0, '이 도전자의 몸뚱어리를 서서히 분해해 놓겠다... 한 조각씩!'),
(18407, 0, 0, '망할 오우거들. 전부 지옥에나 떨어져라. 이 야만족으로부터 우리를 구해줄 자는 없소!? 이번이 벌써 50번째 납치 사건이오.'),
(18407, 0, 1, '그게 우리가 줄 수 있는 최대한의 보상이오. 누군가 이 일을 맡아주면 좋을 텐데...'),
(18428, 0, 0, '오우거들을 처치하자!'),
(18428, 0, 1, '정말 고맙습니다, 영웅이여!'),
(18428, 0, 2, '언젠가 영웅이 나타나 오크에게 예전의 영광을 안겨줄 겁니다.'),
(18428, 0, 3, '정령들이 당신을 보살피길!'),
(18428, 0, 4, '고맙습니다! 당신이 마그하르를 도와준 일을 절대 잊지 않겠습니다.'),
(18445, 0, 0, '고마워요, $n 님! 제 목숨을 구해 주신 게 이걸로 몇 번째죠? 3번이던가요? 제 책에 우리 얘기를 쓰면 정말 재미있겠네요!'),
(18447, 0, 0, '위험은 끝났습니다! $n|1이;가; 우리를 구했습니다!'),
(18471, 0, 0, '피의 투기장으로 들어가게, $n. 곧 대전이 시작될 걸세!'),
(18471, 1, 0, '첫 번째 대전이 시작됩니다! $n|1과;와; 사나운 갈래발굽인 망치발굽의 대결입니다, 여러분!'),
(18471, 2, 0, '$n|1이;가; 망치발굽을 쓰러뜨렸습니다!'),
(18471, 3, 0, '자, 여러분! 전투가 시작될 것입니다! 자비를 모르는 수렁피 쌍둥이들과 $n의 대결입니다!'),
(18471, 4, 0, '믿을 수가 없군요! $n|1이;가; 수렁피 쌍둥이를 이겼습니다!'),
(18471, 5, 0, '여러분, 칼날 산맥에서 들려오는 환호 소리가 파괴의 군주 로크다르를 불러 왔습니다! $n|1이;가; 목숨을 걸고 싸우는 이번 대전을 눈을 크게 뜨고 지켜보십시오.'),
(18471, 6, 0, '$n|1이;가; 대전에서 또 승리를 거뒀습니다!'),
(18471, 7, 0, '오, 알 수 없는 곳에서 온 공허의 군주인 스크라가스가 나타났습니다! 과연 $n|1이;가; 저 보이드의 맹공격에서 살아남을 수 있을까요?'),
(18471, 8, 0, '$n|1이;가; 대전에서 또 승리를 거뒀습니다!'),
(18471, 9, 0, '드디어 모두가 기다리던 순간이 왔습니다! 전쟁망치 용사가 수주일 만에 처음으로 피의 투기장에서 그의 실력을 뽐낼 것입니다! $n|1이;가; 전쟁망치 용사가 싸웠던 다른 상대들처럼 쉽게 무릎을 꿇게 될까요? 숨죽이고 지켜보도록 하지요...'),
(18471, 10, 0, '$n|1이;가; 대전에서 또 승리를 거뒀습니다!'),
(18471, 11, 0, '모고르가 자네에게 도전했네. 자네는 그 도전을 받아들여야만 해! 싸울 준비가 되면 투기장으로 들어가게.'),
(18471, 12, 0, '오!!! 피의 투기장의 역사상 처음으로 모고르가 대전 상대 지목권을 사용했습니다! 전쟁으로 파괴된 이 땅에서 $n|1이;가; 전쟁망치 일족의 영웅 모고르와 처절한 전투를 벌이게 됩니다!'),
(18471, 13, 0, '$n|1이;가; 전쟁망치 일족의 영웅 모고르를 물리치고야 말았군요! $n에게 박수를 보내 주십시오!'),
(18472, 0, 0, '나도... 부하들이 있다!'),
(18472, 1, 0, '흠, 움직일 시간이군!'),
(18472, 1, 1, '귀여운 것들, 그래...'),
(18472, 1, 2, '꼬마들이 무기도 들었네. 그리... 훌륭하진 않군.'),
(18472, 2, 0, '그래, 삶이란 덧없는 것이지...'),
(18472, 2, 1, '음, 자유롭게 해주마!'),
(18472, 3, 0, '음... 생명이 없으면 고통도 없지.'),
(18473, 0, 0, '장신구. 그래, 어여쁜 장신구! 힘, 위대한 힘... 장신구의 힘!'),
(18473, 1, 0, '음, 감히 나에게 도전하는 거냐?!'),
(18473, 1, 1, '이키스가 할퀴어 줄까? 찢어 줄까?!'),
(18473, 1, 2, '너흰 절대 도망 못 간다!'),
(18473, 2, 0, '죽어라! 장신구에 손대지 마!'),
(18473, 2, 1, '으으으음...'),
(18473, 3, 0, '이키스는 까악... 까악.. 죽지 않아.'),
(18473, 4, 0, '%s|1이;가; 비전 에너지를 시전하기 시작합니다...'),
(18554, 0, 0, '어느 녀석이 내 집에 들어와서 나를 위협하는 것이냐!'),
(18554, 1, 0, '주인님, 모든 것이 착착 진행되고 있습니다. 세나리온 수풀에서 소규모 원형을 실험한 결과, 매우 성공적이었습니다. 현재 아래쪽 안마당에서 두 번째 폭탄의 연료를 주입하고 있습니다. 그리고 이곳으로 나머지 부품을 가져올 전령을 투렘으로 보냈습니다.'),
(18554, 2, 0, '이 정도면 만족하십니까?'),
(18554, 3, 0, '절대 실패하지 않을 거라 확신합니다, 주인님. 제가 직접 폭탄 제작을 감독하고 있으며 최종 접근암호도 제가 보관하고 있습니다. 하루 안에 이 근처의 벌레들을 폭탄으로 날려버리겠습니다.'),
(18588, 0, 0, '저는 세 번째 방법을 선택하겠습니다. 죽어라!'),
(18598, 0, 0, '흥, 너무 좋아하지는... 마라.'),
(18598, 0, 1, '언제쯤이면 제대로 된 음식을 다시 먹을 수 있을까?'),
(18667, 0, 0, '저는 세 번째 방법을 선택하겠습니다. 죽어라!'),
(18667, 0, 1, '저는 세 번째 방법을 선택하겠습니다. 죽어라!'),
(18667, 0, 2, '저는 세 번째 방법을 선택하겠습니다. 죽어라!'),
(18667, 1, 0, '후회할 거야!'),
(18667, 1, 1, '재미를 볼 시간이다!'),
(18667, 1, 2, '재미를 볼 시간이다!'),
(18667, 2, 0, '다시는 돌아오지 마라!'),
(18667, 2, 1, '용기는 칭찬해 주지.'),
(18667, 3, 0, '재미를 볼 시간이다!'),
(18667, 4, 0, '흠... 좋지... 않다...'),
(18667, 5, 0, '흠... 좋지... 않다...'),
(18667, 5, 1, '흠... 좋지... 않다...'),
(18667, 5, 2, '흠... 좋지... 않다...'),
(18667, 6, 0, '후회할 거야!'),
(18667, 6, 1, '살육의 시간이다!'),
(18667, 6, 2, '후회할 거야!'),
(18667, 7, 0, '영영 보내버렸다!'),
(18667, 7, 1, '네가 졌다!'),
(18667, 8, 0, '후회할 거야!'),
(18667, 9, 0, '후회할 거야!'),
(18668, 0, 0, '아니, 당신이 틀렸습니다! 배신을 당한 것은 우리 쪽이라고요!'),
(18668, 1, 0, '실버문의 순찰대 사령관은 동맹으로서 의리를 지킬 것입니다!'),
(18668, 2, 0, '진실한 믿음은 곧 피에 있습니다. 우리 종족 외에는 누구도 믿을 수 없어요!'),
(18668, 3, 0, '우리가 배신자라는 말입니까?'),
(18669, 0, 0, '드워프들이 우리의 동맹이었던 적이 있던가?'),
(18669, 1, 0, '하지만, 우리가 마력 없이 어떻게 살아갑니까?'),
(18669, 2, 0, '그런 허튼소리 그만 늘어놓고 숲으로 돌아가시오!'),
(18671, 0, 0, '바보 같으니! 왕자의 부하들은 현재 우리가 동맹을 맺은 바로 그 포세이큰이었고 이제 그 왕자가 우릴 배반했소!'),
(18671, 1, 0, '지금 우리의 땅에 지독한 병이 돌고 있소. 날로 심각해지고 있지! 마력에 대한 욕구가 클수록 우리는 약해질 테고 결국 몰락하고 말 거요. 과거에 그랬던 것처럼!'),
(18671, 2, 0, '하지만, 대가를 치르지 않았소?! 우리는 모두 장님이 되었소. 모두 눈이 멀어 버렸단 말이오!'),
(18671, 3, 0, '절대 그런 것은 아니오! 내 양심을 걸고 말하겠소. 우리 일족의 무절제는 우리 자신과, 그동안 힘들게 쌓아올린 모든 것을 파괴할 거요.'),
(18671, 4, 0, '우리는 파멸의 갈림길에 서 있소. 이 성급한 행동에 대해 다시 생각해 봐야 하오.'),
(18671, 5, 0, '우리에게 여러분의 힘을 실어주시오! 지금이야말로 우리 종족을 구원하기 위해 행동에 나설 때요!'),
(18671, 6, 0, '로르테마르는 우리 말을 경청해야 할 거요! 우리는 절대 조용히 있지 않을 테니까!'),
(18671, 7, 0, '로르테마르는 실버문을 재건하여 우리가 진정 자랑스러워할 만한 도시로 만들었소.');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(18671, 8, 0, '현명한 마법학자들은 우리를 번영의 미래로 인도할 계획을 세울 거요.'),
(18688, 0, 0, '선조님의 보살핌이 있기를, 친절한 이여...'),
(18688, 0, 1, '울음을 멈추어라! 그만!'),
(18688, 0, 2, '모든 게 기억나는구나...'),
(18688, 0, 3, '이럴 수가...'),
(18688, 0, 4, '너에게 다가온다...'),
(18688, 1, 0, '영혼들이 부르고 있다... 난 지쳤구나.'),
(18688, 1, 1, '통제가 안 된다... 나를 끌어당기고 있어... 보이드가 성장하고 있다...'),
(18688, 1, 2, '죽어가고 있어... 죽어가고 있구나... 죽어가...'),
(18688, 1, 3, '차가운 손길이 기다리고 있구나...'),
(18688, 1, 4, '너무나 고통스럽구나.'),
(18688, 1, 5, '내게 무슨 일이 벌어지고 있는 것이냐?'),
(18688, 1, 6, '도대체 무슨 짓이냐? 난... 아악...'),
(18688, 1, 7, '이곳이 함락된다면 우리는 어떻게 되는 것이냐?'),
(18698, 0, 0, '침입자 발견! 위험 요소 즉시 제거 요망!'),
(18705, 0, 0, '%s|1이;가; 기절합니다.'),
(18708, 0, 0, '%s|1이;가; 대기에서 에너지를 흡수합니다...'),
(18728, 0, 0, '3차 대전쟁에서 패했을 당시 그 뼈저린 고통은 절대 잊을 수 없다. 오랫동안 복수의 이날을 기다려 왔노라. 이제 불타는 군단의 그림자가 세계 곳곳에 드리워질지니, 너희 같은 하등 종족이 멸망하는 건... 시간문제일 뿐이다.'),
(18728, 1, 0, '불타는 군단이 모두 정복하리라!'),
(18728, 1, 1, '필멸의 종족은 모두 멸망하리라!'),
(18728, 2, 0, '모든 생명의 뿌리를 뽑아버리겠다!'),
(18728, 2, 1, '뼈도 못 추리게 해주마!'),
(18728, 3, 0, '키렐 나라크!'),
(18728, 3, 1, '이 비천한 족속들!'),
(18728, 3, 2, '우주의 질서가 새롭게 정립되리라!'),
(18728, 4, 0, '불타는 군단에... 패배란 없다.'),
(18728, 5, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(18728, 6, 0, '침입자여, 그대는 망각의 절벽 위에 위태롭게 매달려 있구나! 불타는 군단이 도래함과 동시에 너의 종말도 올 것이다.'),
(18728, 6, 1, '건방진 놈들. 네 놈들은 잠시 시간을 늦췄을 뿐 결코 너희의 운명을 피할 수는 없다. 하나가 쓰러지면 열이 새로 일어날 것이니... 그것이 나 카자크의 뜻이니라...'),
(18731, 0, 0, '후회할 거야!'),
(18731, 1, 0, '불쌍한 것들! 큰 대가를 치르게 해주마.'),
(18731, 1, 1, '파멸의 쓴맛을 보여주마.'),
(18731, 1, 2, '드디어, 지루함을 달래줄 일이 생겼구나.'),
(18731, 2, 0, '이 멍청이 같은 놈들, 더 늦기 전에 지원하라!'),
(18731, 3, 0, '죽음이 두렵나?'),
(18731, 3, 1, '이게 바로 내가 제일 좋아하는 일이지.'),
(18731, 4, 0, '너무 자만하지는 마라. 필멸의 존재들아.'),
(18732, 0, 0, '죽음이 두렵나?'),
(18732, 1, 0, '네 피를 제물로 바칠 것이다.'),
(18732, 1, 1, '너는 다른 자들에게 좋은 표본이 될 것이다.'),
(18732, 1, 2, '좋아! 훌륭한 제물이 되겠군!'),
(18732, 2, 0, '도와줘라! 네 주인을 보호해라!'),
(18732, 3, 0, '난 자존심으로 먹고살지.'),
(18732, 3, 1, '너의 죽음은 대의를 위한 것이다.'),
(18732, 4, 0, '내 생명을 기꺼이 드립니다.'),
(18744, 0, 0, '멈춰!'),
(18744, 0, 1, '제발 그만 좀...'),
(18760, 0, 0, '좋아요, 여기서 나갑시다!'),
(18785, 0, 0, '경비병!'),
(18788, 0, 0, '경비병!'),
(18789, 0, 0, '경비병!'),
(18791, 0, 0, '경비병!'),
(18805, 5, 0, '장난은 여기까지다! 이제 진정한 우주의 분노를 보여주마.'),
(18805, 6, 0, '나는 공허의 세계와... 하나가 되리라!'),
(18807, 0, 0, '경비병!'),
(18808, 0, 0, '경비병!'),
(18809, 0, 0, '경비병!'),
(18831, 0, 0, '그론이 아웃랜드의 진정한 강자다!'),
(18831, 1, 0, '그룰 님의 손아귀에서 벗어나지 못할 것이다!'),
(18831, 2, 0, '다음번은 만만치 않을 것이다.'),
(18831, 2, 1, '푸하! 그런다고 달라지는 건 없다!'),
(18831, 2, 2, '하나도 두렵지 않다!'),
(18831, 2, 3, '좋아, 이제 나랑 싸우자!'),
(18831, 3, 0, '약해 빠졌구나!'),
(18831, 3, 1, '%s|1이;가; 웃습니다.'),
(18831, 3, 2, '마울가르는 왕 중의 왕이다!'),
(18831, 4, 0, '그룰 님이... 복수해 주실 것이다.'),
(18850, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(18853, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(18879, 0, 0, '%s|1이;가; 매우 약해집니다.'),
(18896, 0, 0, '직무: 첩보요원, 고문관'),
(18896, 1, 0, '잔인한 세이야드는 불타는 군단의 성전이 지닌 교활한 면을 보여 주는 좋은 증거입니다.'),
(18896, 2, 0, '그들은 고통을 주는 것을 즐깁니다. 그들의 끔찍한 고문 수법은 악몽과도 같습니다.'),
(18896, 3, 0, '지옥수호병'),
(18896, 4, 0, '종족: 모아그'),
(18896, 5, 0, '소속: 불타는 군단'),
(18896, 6, 0, '직무: 일반 병사'),
(18896, 7, 0, '모아그 종족 출신으로 불타는 군단에게 징병되었으며 이 전사들은 불타는 군단의 고위 계층의 사병입니다.'),
(18896, 8, 0, '그들은 두려움을 모르고 주인의 의지를 위해 맹목적으로 충성합니다.'),
(18896, 9, 0, '파멸의 수호병'),
(18896, 10, 0, '종족: 에레드루인'),
(18896, 11, 0, '직무: 돌격대, 집행부'),
(18896, 12, 0, '강한 힘과 영리한 머리를 가지고 있으며 날개가 달린 이 돌연변이들은 그 잔인함으로 전 우주에 악명을 떨치고 있습니다.'),
(18896, 13, 0, '파멸의 수호병은 자신들이 모시는 지옥의 군주에게 절대적으로 충성하며 세계를 파괴하는 것을 즐깁니다.'),
(18896, 14, 0, '격노수호병'),
(18896, 15, 0, '종족: 에레다르'),
(18896, 16, 0, '직무: 근위병'),
(18896, 17, 0, '사악하고 잔인한 격노수호병은 불타는 군단의 에레다르 고위직을 보호합니다.'),
(18896, 18, 0, '절대로 그들의 전투 기술을 얕잡아 봐서는 안 됩니다.'),
(18896, 19, 0, '서큐버스'),
(18896, 20, 0, '종족: 세이야드'),
(18896, 21, 0, '쉬바라'),
(18896, 22, 0, '종족: 쉬바라'),
(18896, 23, 0, '직무: 여사제, 군종 신부'),
(18896, 24, 0, '매우 카리스마적이자 살게라스에게 충실한 이 여사제들은 오직 살게라스의 죽음의 환영의 힘을 전파하기 위해서 살아갑니다.'),
(18896, 25, 0, '그들은 불타는 성전의 휘몰아치는 힘입니다.'),
(18896, 26, 0, '공포의 군주'),
(18896, 27, 0, '종족: 나스레짐'),
(18896, 28, 0, '직무: 비밀 요원, 심문관'),
(18896, 29, 0, '나스레짐은 불멸의 존재의 에너지를 먹고 사는 무자비한 악마입니다.'),
(18896, 30, 0, '그들은 공포와 속임수를 사용합니다. 전 세계가 그들의 어둠의 세력 앞에 무릎을 꿇자 형제와 다투는 일도 종종 생기고 있습니다.'),
(18896, 31, 0, '에레다르'),
(18896, 32, 0, '직무: 대군주, 전략가'),
(18896, 33, 0, '교활하며 강력한 에레다르의 흑마법사들은 한때 우리의 소중한 동지였습니다.'),
(18896, 34, 0, '하지만 그들은 살게라스의 꼬임에 넘어가 지금은 우리의 가장 강력한 적이 되었습니다.'),
(18896, 35, 0, '지옥의 군주'),
(18896, 36, 0, '종족: 아나이힐란'),
(18896, 37, 0, '직무: 사령관, 지휘관'),
(18896, 38, 0, '이 거대한 파괴자들은 불타는 군단의 사령관을 맡고 있습니다.'),
(18896, 39, 0, '그들은 강한 만큼이나 잔인합니다. 또한 존재하는 모든 것을 파괴하려 합니다.'),
(18896, 40, 0, '간아그'),
(18896, 41, 0, '직무: 땜장이, 기계 기술자'),
(18896, 42, 0, '이 왜소한 모아그들은 매우 영리하며 좀 더 큰 동족의 조수로 고용되기도 합니다.'),
(18896, 43, 0, '본성이 사악한 그들은 자신들이 급조한 기술을 사용하는 것을 좋아합니다.'),
(18896, 44, 0, '모아그'),
(18896, 45, 0, '직무: 기술자, 과학자'),
(18896, 46, 0, '야만적인 방법으로 보이겠지만 끔찍한 공포야말로 최고의 기술자이자 대장장이입니다.'),
(18896, 47, 0, '그들의 검은색 강철 구조물은 천 개의 세계에 걸쳐 죽음의 바람을 불러 왔습니다.'),
(18929, 0, 0, '으, 정말 따분하기 짝이 없는 장사네요!'),
(18930, 0, 0, '건방진 놈들. 네놈들은 잠시 시간을 늦췄을 뿐 결코 너희의 운명을 피할 수는 없다. 하나가 쓰러지면 열이 새로 일어날 것이니... 그것이 나 카자크의 뜻이니라...'),
(18931, 0, 0, '경비병!'),
(18937, 0, 0, '경비병!'),
(18939, 0, 0, '경비병!'),
(18942, 0, 0, '경비병!'),
(18952, 0, 0, '침입자에게 죽음을!'),
(18953, 0, 0, '경비병!'),
(18956, 0, 0, '풀어 주셔서 감사합니다, $n! 저는 샤트라스에 있는 오빠에게 가겠습니다!'),
(18999, 0, 0, '이보시오, 이 지명수배 전단 읽어 봤소?'),
(18999, 0, 1, '해골 무덤이라니! 현상금이 아무리 두둑해도 해골 무덤에는 절대 갈 수 없소!'),
(18999, 0, 2, '이 전단을 보면 소위 모험가라고 하는 자들에게 어떤 녀석들을 처치하고 돌아오면 현상금을 보상으로 지급하겠다고 되어 있소이다. 이게 우리가 하는 일 아니오? 같은 일을 하는데 내가 받는 보수가 너무 적은 거 아니냔 말이오!'),
(18999, 0, 3, '근무가 끝나면 현상금 사냥 한번 해볼 생각 없소?'),
(18999, 0, 4, '이 수배 전단을 보면 해골채찍 독수리의 목에 현상금이 걸려 있소. 내가 그 일을 하는 건 어떻겠소?'),
(18999, 1, 0, '당신이 오늘 하루종일 떠들던 현상 수배 전단이 저거요?'),
(18999, 1, 1, '근무가 끝나면 바로 현상금 사냥을 시작할 생각이오.'),
(18999, 1, 2, '용돈 벌이는 되겠군.'),
(18999, 1, 3, '글쎄... 뭐, 하고 싶은 대로 하시오.'),
(18999, 1, 4, '해골 무덤의 해골채찍 독수리들은 가볍게 볼 상대들이 아니오. 녀석들에게 무서운 질병이 있다는 소리도 들었소이다!'),
(19035, 0, 0, '오, 달콤하고, 맛있고, 반점이 있는 알아, 넌 내 거야...'),
(19035, 1, 0, '이 빌어먹을 기계가 작동하게 만들 수만 있다면!'),
(19035, 2, 0, '아주 맛있어 보이는데...'),
(19044, 0, 0, '와서... 죽어라.'),
(19044, 1, 0, '꺼져라.'),
(19044, 1, 1, '숨을 곳은 없다.'),
(19044, 2, 0, '그대로 멈춰라.'),
(19044, 2, 1, '살려 달라고 애원해 봐라.'),
(19044, 3, 0, '여기까지다!'),
(19044, 3, 1, '하찮은 것들.'),
(19044, 3, 2, '죽어라.'),
(19044, 4, 0, '스랄, 빠져나오셨군요!'),
(19044, 5, 0, '%s|1이;가; 점점 커집니다!'),
(19055, 0, 0, '%s|1이;가; 끔찍한 소리를 내지릅니다.'),
(19138, 0, 0, '그리될 것입니다.'),
(19181, 0, 0, '경비병!'),
(19188, 0, 0, '%s|1이;가; 격노합니다!'),
(19191, 0, 0, '이렇게 건방지고 거만한 놈이 있나! 내 집에서 날 이길 생각을 하다니!'),
(19191, 1, 0, '주인님, 실패했습니다...'),
(19196, 0, 0, '전쟁이 빠른 속도로 가까워지고 있다는 걸 알겠군. 과일 상인이 오우거한테까지 도움을 구했으니 말이야. 나도 어디엔가 도움을 요청해야겠군.'),
(19196, 1, 0, '과일 상인! 아직도 네 마차가 우리 영업을 방해하고 있다! 앞으로 한 시간을 줄 테니 우리 구역에서 마차를 빼라. 우리 인내심을 시험하지 마라!'),
(19216, 0, 0, '오늘 이곳 빛의 정원에 모인 여러분을 환영합니다.'),
(19216, 1, 0, '아달은 성스러운 빛의 충실한 종인 저에게 수많은 계시를 내려주었습니다.'),
(19216, 2, 0, '신성한 부름에 따라 진실을 알고자 하는 모든 이에게 그 실체를 말씀드리겠습니다.'),
(19216, 3, 0, '우리 모두의 마음속에는 성스러운 빛이 존재합니다...'),
(19216, 4, 0, '자연의 모든 생명체가 조건 없이 가질 수 있는 선물이지요.'),
(19216, 5, 0, '성스러운 빛은 느낌으로 나타납니다. 처음에는 미약해서 쉽게 지나칠 수도 있지만 마침내는 진실을 보여주고 옳은 일을 하도록 인도하죠.'),
(19216, 6, 0, '순수한 친절, 자비로운 행동, 도움이 필요한 이들을 도와주는 일... 이 모든 게 성스러운 빛의 열매입니다.'),
(19216, 7, 0, '성스러운 빛은 자신의 조언에 귀를 기울이는 자에게 눈에 보이는 혹은 보이지 않는 축복으로 보답합니다.'),
(19216, 8, 0, '그러면 희망과 신념에 대한 믿음이 강해지면서 점점 더 강한 빛을 받아들일 수 있습니다.'),
(19216, 9, 0, '성스러운 빛의 가르침을 따르다 보면 그 목소리와 힘에 점점 민감해지는 자신을 느낄 수 있을 겁니다.'),
(19216, 10, 0, '성스러운 빛을 충실히 섬기는 이들의 치유 능력과 축복의 힘은 정말 대단하지요.'),
(19216, 11, 0, '그런데 슬프게도 성스러운 빛을 무시하고 죽을 운명 속에서 헤매는 이들이 있습니다.'),
(19216, 12, 0, '성스러운 빛이 자취를 감추면 오직 어둠만이 남습니다.'),
(19216, 13, 0, '빛이 없는 곳에서는 절망과 혐오, 그리고 분노만이 창궐하는 법이지요.'),
(19216, 14, 0, '우리는 어둠의 세력이 우리를 파멸하려고 성난 이를 드러내는 위험한 시대에 태어났습니다.'),
(19216, 15, 0, '이제 성스러운 빛과 조화를 이뤄야 할 때입니다.'),
(19216, 16, 0, '제 말을 잘 기억하여 마음속의 성스러운 빛으로 진실을 직접 확인하십시오.'),
(19216, 17, 0, '그대 안의 빛을 받아들이십시오, 동지들이여! 어둠을 멀리하십시오...'),
(19216, 18, 0, '우리는 믿음으로 이 시련을 견뎌내야 합니다. 그러면 언젠가 승리를 거둘 겁니다.'),
(19218, 0, 0, '끔찍한 죽음이 예상되는군.'),
(19218, 1, 0, '계획에 큰 오류가 있었군.'),
(19218, 1, 1, '그래, 논리적으로 당연한 결과지.'),
(19218, 2, 0, '계산은 꼼꼼히! 자를 땐 단번에!'),
(19218, 2, 1, '계산대로라면... 지금쯤 송장이 됐겠군.'),
(19218, 3, 0, '정말 뜻하지 않은... 사고로군... 아...'),
(19219, 0, 0, '기회가 있을 때 어서들 흩어져라.'),
(19219, 1, 0, '멋지게 한 방 날려 봐. 근성을 보여주지!'),
(19219, 2, 0, '흠집이라도 낼 수 있을 것 같은가? 어림도 없는 소리...'),
(19219, 3, 0, '내가 분명 경고했을 텐데...'),
(19219, 3, 1, '내 실력이 녹슬지 않았군!'),
(19219, 4, 0, '얼씨구!'),
(19220, 0, 0, '우린 철저히 계획대로 움직인다. 방해하지 마라!'),
(19220, 1, 0, '협조자를 찾고 있던 참이야...'),
(19220, 1, 1, '날 위해 일해 줘야겠다!'),
(19220, 2, 0, '노동력을 보충할 시간이군.'),
(19220, 3, 0, '진짜 싸움을 시작해 볼까...'),
(19220, 4, 0, '사소한 골칫거리였군.'),
(19220, 4, 1, '네놈이 진 것 같구나.'),
(19220, 5, 0, '계획은 예정대로... 진행된다.'),
(19227, 0, 0, '이봐, $r! 자네에게 딱 맞는 물건이 있어. 정말 용한 수호 부적을 본 적 있나? 우는 애를 잡아 간다는 호랑이처럼 아주 무서운 놈이라고. 자네도 모르게 신기한 재주를 부릴 거야. 자네에게는 꼭 필요한 부적이지. 그리고 내가 판매하는 모든 수호 부적의 품질은 절대 보장한다고!'),
(19227, 0, 1, '여기 좀 보라고, $c! 보여줄 물건이 있네. 자네에게 꼭 필요한 물건이야. 그게 뭐냐고? 바로 비누야. 어린이용 끈 달린 비누지! 기분을 상하게 할 생각은 없어. 솔직히 자네는 아직 덜 여물지 않았나. 내가 하는 말 알아듣겠지?'),
(19227, 0, 2, '어서 오게, $r... 던전에 들어가서 위험을 자초하고 싶지는 않겠지? 지저분한 임무, 그리고 또 뭐가 있지? 아무짝에도 쓸모없는 싸구려 장신구? 맙소사, 자네에겐 내 아뮬렛이 필요해. 효과는 내가 장담하네!'),
(19227, 1, 0, '피곤해 보이는군. 자네에게 딱 맞는 물건이 있네. 내가 파는 아뮬렛을 걸면 적들을 휙휙 뛰어넘고 강에서는 물 만난 고기처럼 헤엄칠 수 있다고. 그리고 자네가 먹는 음식에 힘을 불어넣어 순식간에 상처를 아물게 하지!'),
(19227, 1, 1, '이봐, $r! 자네에게 딱 맞는 물건이 있어. 정말 용한 수호 부적을 본 적 있나? 우는 애를 잡아 간다는 호랑이처럼 아주 무서운 놈이라고. 자네도 모르게 신기한 재주를 부릴 거야. 자네에게는 꼭 필요한 부적이지. 그리고 내가 판매하는 모든 수호 부적의 품질은 절대 보장한다고!'),
(19227, 1, 2, '여기 좀 보라고, $c! 보여줄 물건이 있네. 자네에게 꼭 필요한 물건이야. 그게 뭐냐고? 바로 비누야. 어린이용 끈 달린 비누지! 기분을 상하게 할 생각은 없어. 솔직히 자네는 아직 덜 여물지 않았나. 내가 하는 말 알아듣겠지?'),
(19227, 2, 0, '상사병에 걸린 것 같군. 도대체 얼마나 특별한 사랑이기에 그토록 침울해졌나? 전혀 걱정할 필요 없네. 내가 파는 이 목걸이를 사서 걸고 나가면 그 누구라도 자네를 사랑할 거야!'),
(19227, 2, 1, '놀라운 아뮬렛을 구경해보게! 정말 희귀한 작품일세! 오랜 세월에 걸쳐 검증을 받은 그립타 가문의 진정한 솜씨 앞에서는 최신 세공 기술도 어린애 장난에 불과하지! 마법 부적을 저렴한 가격에 구입해서 능력을 향상시킬 절호의 기회라고!'),
(19227, 2, 2, '바깥은 참 위험하지... 자네에게 가장 필요한 것이 뭘까? 바로 안전이지. 죽음을 피할 수 있도록 내가 도와주겠어! 이 기적적인 불멸의 광석 목걸이를 목에 걸면 설령 영혼의 세계에 가게 됐더라도 다시 돌아올 수 있다고! 마치 소풍이라도 가듯 자네 시체를 찾아가서 생생한 몸으로 부활하는 거지!'),
(19228, 0, 0, '여러분! 제 농담이 지연되는 시간에 보상은 절대 없습니다.'),
(19228, 0, 1, '방금 아이언포지에서 날아왔죠. 그놈 날개가 엄청 뻐근할 겁니다!'),
(19228, 0, 2, '오늘이 제 첫무대이니... 예쁘게 봐주시기 바랍니다.'),
(19228, 0, 3, '저를 보러 와주신 모든 분께 감사합니다! 여러분은 오늘 저와 함께 좋은 시간을 보낼 것입니다.'),
(19228, 0, 4, '우와! 이 모든 박수가 절 위한 것입니까? 와주신 모든 분께 감사합니다!'),
(19228, 1, 0, '그 어떤 타우렌이라도 이 용도에만은 안성맞춤이더군요...'),
(19228, 2, 0, '추수절 선물용 소갈비 모둠 말이죠!'),
(19228, 3, 0, '지난주에 황금골에 갔다 왔습니다. 여러분은 거기 가본 적 있으세요?'),
(19228, 4, 0, '조그마한 마을에서 한 꼬마에게 지도를 그려달라고 부탁했습니다. 그랬더니 데피아즈단 현상 수배 전단 뒷면에 지도를 그리지 뭡니까...'),
(19228, 5, 0, '그것도 아주 정확한 비율로요!'),
(19228, 6, 0, '흉내 내기 시간이 돌아왔습니다! 자, 제목은 ''멍청한 타우렌''입니다.'),
(19228, 7, 0, '희극 배우가 헛기침을 하며 목을 가다듬습니다.'),
(19228, 8, 0, '희극 배우가 타우렌 흉내를 냅니다.'),
(19228, 9, 0, '재미난 수수께끼 하나 내볼까요... 왜 수박에는 물이 많을까요?'),
(19228, 10, 0, '바로 희망이 샘솟는 봄에 씨를 뿌리기 때문이랍니다!'),
(19228, 11, 0, '여성들과 도대체 어떤 관계가 있을까요? 그러니까 그들은 항상...'),
(19228, 12, 0, '희극 배우가 인간 여성 흉내를 냅니다.'),
(19228, 13, 0, '그리고 노움들은 더 상태가 안 좋아요! 그들이 항상 하는 말이...'),
(19228, 14, 0, '희극 배우가 노움 흉내를 냅니다.'),
(19228, 15, 0, '엘레크가 여러분 댁 울타리에 앉았다면?'),
(19228, 16, 0, '당장 울타리를 새로 쌓아야겠죠!'),
(19228, 17, 0, '이럴 줄 알았으면 웃음 보너스 효과가 붙은 장화라도 신고 오는 건데...'),
(19228, 17, 1, '제가 여러분께는 그리 우호적인 평판을 얻지 못했군요.'),
(19228, 17, 2, '흠! 여기 계신 분들은 좀처럼 웃지를 않으시는군요.'),
(19228, 18, 0, '하하하! 주정뱅이 라리크를 좀 보세요... 그의 어머니는 너무 뚱뚱해서 오우거 신문의 표지를 장식한다고 해도 몸이 다 나오지도 못할 거예요...'),
(19228, 19, 0, '아마 뒷면 표지까지 다 쓴다고 해도 모자랄 겁니다!'),
(19228, 20, 0, '한때 노움은 친절하고 예의 바른 종족이었죠...'),
(19228, 21, 0, '며칠 전 어떤 친구가 실성이라도 한 듯, 거리를 걸어가면서 "당신도 한번 노움을 알면 다시는 고향으로 돌아오지 못한다!"라고 외치는 걸 봤어요.'),
(19228, 22, 0, '저는 블러드 엘프 여성을 좋아합니다. 특히 그들이 이런 말을 할 때는 정말 최고죠...'),
(19228, 23, 0, '희극 배우가 블러드 엘프 흉내를 냅니다.'),
(19228, 24, 0, '그러니까 블러드 엘프들은 자신들이 한 발자국만 앞으로 나가면 이 세계를 지배하게 될 거로 생각한다는 거군요...'),
(19228, 25, 0, '한 발자국은 무슨, 백만 스물 하고도 두 발자국이겠죠!'),
(19228, 26, 0, '마지막 흉내 내기입니다. 좀 어렵긴 하지만 누군지 알아맞혀 보세요...'),
(19228, 27, 0, '희극 배우가 오크 흉내를 냅니다.'),
(19228, 28, 0, '공연이 끝났으니 절 붉은십자군 수도원으로 데려다 주실 분 없습니까?'),
(19228, 28, 1, '고맙습니다! 담당 웨이터에게 팁 주는 것 잊지 마세요! 모두 좋은 밤 되세요.'),
(19228, 28, 2, '자, 웃음 제조기들은 이만 물러날 시간이네요. 모두 즐거운 밤 되십시오!'),
(19228, 28, 3, '벌써 끝났느냐고요? 여러분은 오늘 정말 좋은 관객이셨습니다. 조심해서 돌아가시고 좋은 밤 되십시오.'),
(19228, 29, 0, '등불의 심지를 갈려면 코볼트가 몇 명이나 있어야 할까요?'),
(19228, 30, 0, '너 양초 못 가져간다!'),
(19228, 31, 0, '황금골의 여관은 멋진 호숫가 전망을 자랑한다고 선전하더군요...'),
(19228, 32, 0, '그런데 창문 너머로 멀록이 수영하는 모습만 보이더군요.'),
(19228, 33, 0, '여러분, 귀여운 꼬마 오크들이 모두 똑같이 생겼다는 사실을 알고 계세요?'),
(19228, 34, 0, '귀여운 외모를 점점 잃는 것은 참 유감스러운 일이죠. 불모의 땅에는 "옥상에서 떨어진 메주보다 아름다운 것도 없다."라는 격언이라도 있나봐요.'),
(19228, 35, 0, '노움이 소원을 들어준다는 얘기를 들었습니다...'),
(19228, 36, 0, '제 소원은 그들이 없어져 버렸으면 좋겠다는 거예요!'),
(19228, 37, 0, '여기 누가 있는지 보십시오. 우리 친구, 주정뱅이 라리크입니다. 그의 어머니는 너무 뚱뚱해서 용 아가리에도 못 들어가지요.'),
(19228, 38, 0, '그들 모자는 남은 음식을 보관할 데가 없어서 모조리 뱃속에다 넣지요!'),
(19228, 39, 0, '아내와 저는 23년 동안 행복했습니다...'),
(19228, 40, 0, '그리고 이제 우리가 만났습니다!'),
(19228, 41, 0, '망가진 부메랑을 뭐라고 부르게요?'),
(19228, 42, 0, '그냥 막대기죠!'),
(19228, 43, 0, '이 노움이 한 타우렌에게 자기가 화산 심장부에 가본 적이 있다고 했답니다.'),
(19228, 44, 0, '그러자 타우렌이 "그때 넌 소떼 한가운데 빠진 거였어."라고 했답니다.'),
(19228, 45, 0, '아니 도대체 상황이 얼마나 절박하기에 가축을 동료로 받아들인답니까?'),
(19228, 46, 0, '저도 개를 한 마리 기르고 있지만 검을 주지는 않아요.'),
(19228, 47, 0, '여러분도 고블린을 믿지 않으시지요...'),
(19228, 48, 0, '제가 뭐라고 반박하겠습니까? 고블린과 거래를 트기 전에는 지갑에 쇠 자물쇠부터 다는 게 상책인데요.'),
(19255, 0, 0, '그렇다, 우리는 몇 가지 어려움에 처해 있다. 어떤 어려움인지는 확실히 인지하고 있다. 그러나 문제는 그 어려움을 어떻게 해결하느냐 하는 것이다.'),
(19255, 0, 1, '이 생활에 익숙해져야 한다, 보병들이여. 우리는 비참한 삶을 이어가기 위해 이곳에 왔다. 새로운 고향 지옥불 반도에 온 것을 환영하는 바이다.'),
(19255, 0, 2, '도대체 얼마나 많은 보병이 시체가 되어 고향으로 돌아가야만 불타는 군단의 살인 부대로 뛰어드는 것이 자살 행위라는 것을 알겠는가? 그리고 마치 내 말을 이해한다는 듯이 그 큰 머리 좀 끄덕이지 말라!'),
(19255, 0, 3, '솔직하게 말하겠다. 우리는 그곳을 공격할 것이다! 그럼 제군들 중에 그 임무를 맡을 용감한 오크는 과연 누구인가?'),
(19270, 0, 0, '배꼽이 빠져라 웃고 싶은 분은 세상의 끝 선술집으로 오십시오!'),
(19271, 0, 0, '오늘 밤, 이 자리를 찾아주신 모든 여러분께 감사드립니다. 샤트라스 최고의 희극 배우 페리 가트너를 박수로 맞아주시기 바랍니다!'),
(19271, 1, 0, '페리 가트너! 정말 대단한 배우죠! 이곳은 밤새도록 문을 여니까 편히 앉아서 즐기시기 바랍니다!'),
(19273, 0, 0, '편대사령관 브락크를 찾아가 보십시오, $n. 당신에게 파괴의 장갑 와이번 한 마리를 내줄 것입니다. 그럼, 행운을 빕니다!'),
(19283, 0, 0, '제발 우리를 지나치지 마세요...'),
(19283, 0, 1, '한푼만 줍쇼.'),
(19283, 0, 2, '여보시오. 적선 좀 하시려오? 먹여 살릴 자식이 다섯이나 있소이다...'),
(19308, 0, 0, '이번 전쟁에서 어떻게든 이기겠지 하는 생각은 버리십시오. 이번 전쟁이 단지 전쟁일 뿐이라는 착각도 버리는 게 좋을 겁니다. 이 파괴된 땅의 모든 것을 위해 싸우고, 할퀴고, 걷어차지 않으면 모든 것을 잃게 될 테니까요.'),
(19308, 0, 1, '그곳에 관심을 쏟기도 전에 얼마나 많은 병사들이 죽어 나가야 하는 겁니까?'),
(19308, 0, 2, '악마들이 정정당당하게 싸울 것이라 생각하시오? 그 짐승들은 오크보다도 야만적이고 언데드보다도 교활하오. 일반적인 전쟁을 기준으로 불타는 군단과 맞서려는 생각은 버리시오.'),
(19317, 0, 0, '경비병!'),
(19346, 0, 0, '수도자 닌두멘, 청이 하나 있습니다.'),
(19346, 1, 0, '방금 또 다른 신병 부대를 나그란드로 보냈습니다. 그들을 위해 기도해 주시겠습니까?'),
(19346, 2, 0, '그리될 것입니다.'),
(19354, 0, 0, '이 뒤틀린 드레나이 녀석들을 가루로 만들어 버려라, 일리다리! 이 버림받은 땅에 쓸만한 물건이 있다면 우리가 찾아낼 것이다!'),
(19354, 0, 1, '이놈들이 잠시도 쉬지 못하게 하라! 이곳에 아타말 수정이 있다면 반드시 찾을 것이다!'),
(19354, 0, 2, '이 뒤틀린 드레나이 놈을 잘 감시해라! 탈출한 녀석들이 너무 많다!'),
(19354, 0, 3, '주인님께서 원하시는 걸 찾게 될 것이다! 실패는 용납할 수 없다!'),
(19362, 0, 0, '게으름 피우다 걸리는 일꾼은 투석기에 매달아서 검은 사원으로 날려버리겠다!'),
(19362, 0, 1, '바로 저쪽에 묘지가 있으니 쉬고 싶은 일꾼들은 언제든지 말만 해라.'),
(19378, 0, 0, '물론일세, 친구여... 어떻게 도와주면 되겠나?'),
(19378, 1, 0, '에로뎀, 자네의 그 고귀한 부탁은 우리에게 큰 영광일세.'),
(19378, 2, 0, '모두 함께 겸손한 자세로 성스러운 빛에게 기도를 올릴 시간이다.'),
(19378, 3, 0, '우리를 비춰주시는 성스러운 빛이여, 당신에게 간청하나니...'),
(19378, 4, 0, '우리는 어둠을 몰아내기 위해 우리의 젊은이들을 사지로 보냈습니다.'),
(19378, 5, 0, '부디 축복으로 그들을 지켜주시고 우리에게 해를 끼치려는 자들로부터 승리를 거둘 수 있게 해주소서...'),
(19378, 6, 0, '우리의 오랜 고향에 계속해서 축복을 내려주시길 빕니다.'),
(19378, 7, 0, '그리고 우리에게 엘프 불청객들을 견뎌낼 인내심을 허락해 주소서.'),
(19378, 8, 0, '나루의 이름으로 그리될 겁니다.'),
(19394, 0, 0, '어이, 브론! 날 때려 봐!'),
(19394, 1, 0, '아니, 그건 겁쟁이나 하는 짓이지. 망치를 날려봐!'),
(19394, 2, 0, '어서 해, 계집애 같은 녀석!'),
(19394, 3, 0, '... 헷, 정말 재밌었어!'),
(19395, 0, 0, '%s|1이;가; 눈을 깜빡이며 난처한 표정을 짓습니다.'),
(19395, 1, 0, '뭐라고? 주먹으로?'),
(19395, 2, 0, '음... 정말 좋은 생각일까? 모크, 다쳐도 난 몰라...'),
(19395, 3, 0, '에... 모크?'),
(19412, 0, 0, '시원한 바람이 당신의 얼굴을 감쌉니다. 부드러운 선율의 콧노래가 조용히 울려 퍼지고 있습니다.'),
(19419, 0, 0, '%s|1이;가; 격노합니다!'),
(19440, 0, 0, '%s에게 발각되었습니다!'),
(19442, 0, 0, '%s|1이;가; 검은늑대들을 부릅니다.'),
(19442, 1, 0, '%s|1이;가; 격노합니다!'),
(19453, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(19456, 0, 0, '이미 충분히 귀찮게 하지 않았나? 꼭 잠까지 깨워야겠나?'),
(19456, 1, 0, '이런 폭력으로 무슨 이득을 얻을 수 있나? 지난 일은 지난 일일 뿐이야. 난 우리 동족을 실망시켰네.'),
(19466, 0, 0, '입 다물지 못하겠소, 파렴치한 같으니! 빛의 여사제님께 무례한 말투를 삼가도록 하시오!'),
(19466, 1, 0, '당신도 이것만은 인정해야 하오. 당신이 변절자들로부터 얻은 정보는 오래된 것이고 확실하지도 않소이다. 우리는 치밀하게 계산된 전술을 바탕으로 마나괴철로를 공격하여 최대한 많은 정보를 캐내야 하오.'),
(19468, 0, 0, '이보시오, 고귀하신 드레나이 친구. 우리끼리 폭풍우 요새에 쳐들어가자는 소리가 아니오. 하지만 기회가 오면 바로 차지해야 하는 것이 아니오?'),
(19468, 1, 0, '...그리고 결국 어떻게 됐는지 보시오!'),
(19468, 2, 0, '드디어 저 친구에게서 뭔가 있어 보이는 작전이 나오는군!'),
(19475, 0, 0, '조사하는 중입니다, 와플프라이 씨. 뭐 다른 할 일 없으신가요? 새로운 기계 장치를 시험해 봐야 한다든가...'),
(19480, 0, 0, '대체... 내가 어떻게 된 거지? 아아아아악...'),
(19516, 0, 0, '경고! 제거 대상 발견!'),
(19516, 1, 0, '제거 완료'),
(19516, 1, 1, '무단 침입 생명체 기능 정지.'),
(19516, 1, 2, '위협 요소 제압.'),
(19516, 2, 0, '시스템 종... 료...'),
(19516, 3, 0, '대체 공격 실행 중...'),
(19516, 3, 1, '파괴력 변수 계산 중...'),
(19523, 0, 0, '꽝!'),
(19523, 1, 0, '착하게 굴면 살려주지.'),
(19523, 2, 0, '나 배고프다!'),
(19523, 3, 0, '넌 여기 있어. 난 가서 다른 놈 처치하고 올게.'),
(19523, 4, 0, '우린 다른 놈 죽인다!'),
(19523, 5, 0, '나 저놈 싫어...'),
(19523, 6, 0, '나 지루해.'),
(19523, 7, 0, '하하하!'),
(19523, 8, 0, '이봐!'),
(19523, 9, 0, '우린 이놈 친구 죽인다!'),
(19523, 10, 0, '이놈은 아주 쉽군!'),
(19523, 11, 0, '내가 힘든 일은 다 해서 그런 거야!'),
(19524, 0, 0, '나도 말 좀 하면 안 될까?'),
(19524, 1, 0, '아니, 그래도 안 살려줄 거야.'),
(19524, 2, 0, '넌 항상 배가 고프지. 그래서 그렇게 뚱뚱한 거야!'),
(19524, 3, 0, '대체 뭘 하고 있는 거야?'),
(19524, 4, 0, '웃기지도 않아!'),
(19524, 5, 0, '아직 안 끝났어, 멍청이!'),
(19524, 6, 0, '야, 이 멍청아!'),
(19524, 7, 0, '지겹다구? 거의 끝장낼 수 있었단 말이야.'),
(19524, 8, 0, '난 피곤해. 다음은 네가 해!'),
(19524, 9, 0, '내가 힘든 일은 다 해서 그런 거야!'),
(19533, 0, 0, '혹시 거래를 하려고 하십니까? 그렇다면 더 멀리 갈 필요 없습니다. 저는 정직한 장사꾼입니다. 제가 가진 물건 들은 매우 구하기 힘들었습니다. 뭐, 그렇지만 어디서 났는지는 상관없지 않겠습니까? 당신에게 필요한 건 뭐든지 있으니 둘러보십시오.'),
(19534, 0, 0, '이곳에는 강한 괴물들이 많습니다, 여행자님. 살아남으려면 충분한 탄약이 필요할 겁니다. 제 가게에는 좋은 화살, 총알, 그리고 투척용 무기들이 잔뜩 구비되어 있으니 손님께선 운이 좋으시군요. 주위 환경을 고려한다면 이 가격도 싼 편이랍니다.'),
(19535, 0, 0, '아, 강한 모험가들을 여러 번 만나게 되는군요. 황천의 폭풍은 위험한 곳이니 가장 효과가 뛰어난 마법이 필요할 겁니다. 저는 최고급 재료만을 팔고 있으며 일반 제품과 아제로스에서 들여온 물건들 등 모두 있답니다. 와서 한번 구경해 보시면 절대 실망하지 않을 겁니다!'),
(19541, 0, 0, '기계 부품을 넘치도록 가진 이웃이 주위에 널려 있어서 정말 다행스러워.'),
(19541, 0, 1, '이번 근무 시간이 끝나면 다른 요원들을 불러 모아 그곳으로 가봐야 하려나?'),
(19541, 0, 2, '흠, 비전 파멸자는 정말 강하지. 휠러 아저씨는 자신이 뭘 요구하고 있는지 알기는 하는 건가?'),
(19541, 0, 3, '지난번에 누군가 황천바위거인의 목에 걸린 현상금을 노리고 나간 적이 있었는데 우리에게 돌아온 것이라고는 무모한 모험가의 납작한 시체뿐이었다고!'),
(19541, 0, 4, '황천바위거인?! 놈이 그 거대한 발을 한 발짝만 옮겨도 당신들은 쥐포가 될 거라고! 고맙지만, 난 됐어!'),
(19543, 0, 0, '검을 두고 나가다니 제정신이 아닌가 봅니다. 그런데 제가 검이 여기 있는 것을 봤다면 그냥 놔두고 갔을 리는 없는데...'),
(19544, 0, 0, '망토 없이 외출할 수는 없지. 이 안에 망토가 있으면 좋겠어...'),
(19544, 1, 0, '여기 있었군! 마지막에 확인할 때만 해도 분명 여기 없었는데...'),
(19545, 0, 0, '휴! 내 행운의 모자가 여기 있었네. 사방을 뒤져도 없더니만.'),
(19558, 0, 0, '경비병!'),
(19579, 0, 0, '휴! 내 행운의 모자가 여기 있었네. 사방을 뒤져도 없더니만.'),
(19580, 0, 0, '망토 없이 외출할 수는 없지. 이 안에 망토가 있으면 좋겠어...'),
(19580, 1, 0, '여기 있었군! 마지막에 확인할 때만 해도 분명 여기 없었는데...'),
(19606, 0, 0, '누가 이 현상 수배 전단 좀 읽어줘! 그렉은 글을 읽을 줄 몰라.'),
(19606, 1, 0, '그렉 술 마신다!'),
(19606, 2, 0, '그러지!'),
(19606, 3, 0, '이 기름은 나한테 아무짝에도 소용이 없군! 이 그렉이 로브나 뒤집어쓰고 다니는 약골로 보이나?'),
(19622, 0, 0, '나의 백성은 에너지와 마력에 중독됐지. 태양샘이 파괴되자 지독한 금단 현상이 발생했다. 미래에 온 것을... 환영하노라. 중단하기에는 이미 늦었다. 이제 아무도 날 막지 못해! 셀라마 아샬라노레!'),
(19622, 1, 0, '카퍼니안, 놈들이 여기 온 것을 후회하게 해 줘라.'),
(19622, 2, 0, '좋아, 그 정도 실력이면 수석기술자 텔로니쿠스를 상대해 볼만하겠어.'),
(19622, 3, 0, '암흑의 인도자 탈라드레드를 상대로 얼마나 버틸지 볼까?'),
(19622, 4, 0, '최고의 조언가를 상대로 잘도 버텨냈군. 허나 그 누구도 붉은 망치의 힘에는 대항할 수 없지. 보아라, 군주 생귀나르를!'),
(19622, 5, 0, '보다시피 내 무기고에는 굉장한 무기가 아주 많지.'),
(19622, 6, 0, '네놈들을 과소평가했나 보군. 모두를 한꺼번에 상대하라는 건 불공평한 처사지만, 나의 백성도 공평한 대접을 받은 적 없기는 매한가지. 받은 대로 돌려주겠다.'),
(19622, 7, 0, '때론 직접 나서야 할 때도 있는 법이지. 발라모어 샤날!'),
(19622, 8, 0, '이대로 물러날 내가 아니다! 반드시 내가 설계한 미래를 실현하리라! 이제 진정한 힘을 느껴 보아라!'),
(19622, 9, 0, '네놈들 따위에겐 승리란 없다!'),
(19622, 9, 1, '용기는 가상했다만 어림없다!'),
(19622, 9, 2, '애들 장난이군.'),
(19622, 10, 0, '복종하라!'),
(19622, 10, 1, '내 뜻에 굴복하라.'),
(19622, 11, 0, '세상을 거꾸로 뒤집으면 어떻게 되는지 구경해 볼까..'),
(19622, 11, 1, '마냥 서 있기만 하려니 힘들지 않나?'),
(19622, 12, 0, '아나라넬 벨로레!'),
(19622, 12, 1, '태양의 힘으로!'),
(19622, 13, 0, '쿠엘 탈라스를... 위하여!'),
(19632, 0, 0, '%s|1이;가; 격노합니다!'),
(19635, 0, 0, '아, 아침에 맡는 황천의 냄새가 좋군.'),
(19635, 1, 0, '냄새가 마치...'),
(19635, 2, 0, '...승리의 냄새 같구나.'),
(19664, 0, 0, '그 어떤 것과도 비교할 수 없는 최고의 머핀이 왔어요.'),
(19664, 1, 0, '네, 정말 최고의 머핀이 왔어요! 이리 와서 신선한 머핀 사세요!'),
(19664, 2, 0, '방금 나온 따끈따끈한 머핀이 왔어요. 이리 오세요!'),
(19664, 2, 1, '아, 네. 저는 머핀 장수랍니다. 제가 왜 머핀 장수냐고요? 그야 머핀을 파니까 머핀 장수죠!'),
(19666, 0, 0, '다른 에테리얼의 욕망을 과소평가하지 마라!'),
(19685, 0, 0, '이방인이여, 저를 따라오십시오. 오래 걸리지는 않을 겁니다.'),
(19685, 1, 0, '샤트라스는 한때 이 세계에 살던 드레나이의 수도였습니다. 샤트라스는 ''빛이 거하는 곳''이라는 뜻이죠.'),
(19685, 2, 0, '불타는 군단 때문에 오크들이 드레나이에게 등을 돌렸을 때 이곳에서 가장 격렬한 전투가 벌어졌습니다. 드레나이는 끝까지 싸웠지만 결국 도시는 함락되었죠.'),
(19685, 3, 0, '폐허가 된 도시에는 어둠만이 남아 있었습니다... 하지만, 샤타르가 도착하자 얘기가 달라졌죠.'),
(19685, 4, 0, '고난의 거리로 갑시다. 한 가지 미리 알려드리자면 샤트라스는 아웃랜드에 남아 있는 몇 안 되는 안전한 피난처이기 때문에 과거에 벌어진 전쟁이나 현재 진행 중인 전쟁을 피해 많은 난민이 몰려들고 있습니다.'),
(19685, 5, 0, '''빛에서 태어난 자''라고도 불리는 샤타르는 불타는 군단의 악마들과 싸우기 위해 아웃랜드로 온 나루입니다.'),
(19685, 6, 0, '그들이 폐허의 도시 샤트라스로 이끌려 왔을 때 살아남은 소수의 드레나이 사제들은 바로 이곳의 부서진 신전에서 의식을 거행하고 있었습니다.'),
(19685, 7, 0, '알도르라는 이름의 그 사제들은 나루가 돌아왔으며 재건 사업이 곧 시작된다는 소식을 듣고 금세 기운을 회복했습니다. 부서진 사원은 현재 부상당한 난민들을 위한 진료소로 사용되고 있습니다.'),
(19685, 8, 0, '하지만 얼마 후 샤트라스는 또다시 공격을 받았습니다. 이번에는 일리단의 군대였지요. 일리단의 동맹인 캘타스 선스트라이더가 수많은 블러드 엘프들을 보내 샤트라스를 파괴했습니다.'),
(19685, 9, 0, '블러드 엘프 군대가 바로 이 다리를 건널 때 알도르 사제회의 총독과 구원자들이 빛의 정원을 방어하고자 진을 쳤습니다. 그런데 그때 전혀 예상치 못한 일이 벌어졌습니다.'),
(19685, 10, 0, '갑자기 블러드 엘프들이 도시의 수호자들 앞에 무기를 내려놓은 겁니다. 그리고 그들의 지도자인 블러드 엘프 장로 보렌살이 빛의 정원에 뛰어들어 아달과 대화를 요구했습니다.'),
(19685, 11, 0, '나루가 나타나자 보렌살은 무릎을 꿇고 이렇게 말했습니다. "나루여, 환영 속에서 당신을 보았습니다. 당신은 우리 종족이 살아남을 수 있는 유일한 희망입니다. 저와 부하들은 당신을 따르고자 이곳에 왔습니다."'),
(19685, 12, 0, '보렌살과 그 부하들의 변절은 그때까지 캘타스의 군대가 입었던 어떤 피해보다도 큰 손실이었습니다. 더구나 이들은 평범한 블러드 엘프들이 아니었죠. 캘타스를 따르던 최고의 학자들과 마법학자들 중 상당수가 보렌살의 영향을 받아 마음이 흔들렸습니다.'),
(19685, 13, 0, '나루는 캘타스를 배신한 이들을 받아들였습니다. 점술가 길드라고 불리게 된 그들은 지금 저 위 언덕에서 살고 있죠. 그곳은 점술가 길드에 속한 자들만이 마음 편히 드나들 수 있습니다.'),
(19685, 14, 0, '알도르 사제회는 성스러운 빛을 섬기며 용서와 구원의 가치를 소중하게 생각하지요. 하지만, 아무리 그들이라도 블러드 엘프들이 캘타스의 명령을 받던 시절에 저질렀던 잘못을 쉽게 잊을 수 없었습니다.'),
(19685, 15, 0, '사실 알도르의 많은 사제들이 나루를 섬기겠다고 맹세한 그 마법학자들에게 살해되었었지요. 사제회의 일원들은 한때 적이었던 자들과 같은 도시에 산다는 게 별로 달갑지 않았던 것입니다.'),
(19685, 16, 0, '저 위에 알도르의 가장 신성한 신전과 주거지들이 있습니다. 그 곳은 매우 신성한 장소로 사제회에 속한 자들만이 환영을 받는 곳이지요.'),
(19685, 17, 0, '샤트라스를 향한 공격이 계속되었지만 보시다시피 도시는 함락되지 않았습니다. 한편, ''지리''라는 나루가 일리단의 본거지 바로 앞에 있는 어둠달 골짜기를 성공리에 습격했습니다.'),
(19685, 18, 0, '그곳에서 그는 알도르 사제회와 점술가 길드의 지원을 받아 일리단의 군대와 계속해서 전투를 벌이고 있습니다. 그렇다고 해서 그 두 진영이 서로에 대한 오랜 적개심을 잊은 것은 아니죠.'),
(19685, 19, 0, '사실, 바로 그런 해묵은 감정 때문에 그들은 나루를 돕고자 떠나는 영광스러운 임무를 맡으려고 경쟁을 벌입니다. 매일 이 도시의 아달이 그 결정을 내리죠. 군대는 어둠달 골짜기로 출정하기 전에 아달의 축복을 받으려고 이곳에서 집결합니다.'),
(19685, 20, 0, '카드가 님을 다시 찾아가십시오. 샤타르를 섬기려면 알도르 사제회 또는 점술가 길드 중 한 편과 동맹을 맺어야 한다는 사실을 기억하십시오. 참고로, 둘 중 한 편과 뜻을 함께하기로 결정하면 다른 편은 적이 될 겁니다.'),
(19685, 21, 0, '이방인이여, 행운을 빌겠습니다. 그리고 샤트라스에 오신 것을 환영합니다.'),
(19710, 0, 0, '숨 쉴 시간이 대략 5초 남았다.'),
(19710, 1, 0, '정확한 각도와 속도가 중요하지.'),
(19710, 1, 1, '단순하지만 효과는 만점!'),
(19710, 2, 0, '예상한 결과였다.'),
(19710, 2, 1, '일정이 착착 들어맞고 있군!'),
(19710, 3, 0, '계산에는... 없었는데...'),
(19710, 4, 0, '%s|1이;가; 자신의 망치를 위협적으로 치켜듭니다...'),
(19720, 0, 0, '버르장머리를 고쳐주마, 요 쥐방울만한 놈!'),
(19720, 1, 0, '셋 셀 때까지 썩 꺼지지 않으면 험한 꼴을 보게 될 것이다.'),
(19720, 2, 0, '하나...'),
(19720, 3, 0, '둘...'),
(19720, 4, 0, '도로 엄마 뱃속으로 들여보내 주마!'),
(19720, 5, 0, '좋아, 좋소! 항복하겠소! 해치지만 마시오!'),
(19725, 0, 0, '%s|1이;가; 손마디를 우두둑 꺾습니다.'),
(19726, 0, 0, '%s|1이;가; 손마디를 우두둑 꺾습니다.'),
(19763, 0, 0, '당신이 여기 오다니 신의 은총이로군. 마침 저녁 시간이 다 되었는데!'),
(19764, 0, 0, '휴... 정말 죽는 줄만 알았습니다.'),
(19766, 0, 0, '타락한 오크들에게 잡아먹히는 것과 노예상인인 라젤크라즈 밑에서 일하는 것 중 어느 게 더 불행하기 짝이 없는 인생인지 모르겠지만... 어쨌든 고맙습니다!'),
(19827, 0, 0, '%s|1이;가; 격노합니다!'),
(19830, 0, 0, '설마 농담이겠죠?! 이 마나괴철로를 운영하기에도 인원이 턱없이 부족하단 말입니다!'),
(19830, 1, 0, '알겠습니다.'),
(19831, 0, 0, '아르도니스, 듀로 마나괴철로로 지원 병력을 보내라. 이것은 부탁이 아니라 명령이다.'),
(19831, 1, 0, '명령대로 해라. 듀로 마나괴철로가 마나 생명체의 공격을 받고 있으며 도저히 수습할 수 없는 상황이다. 명령 불복종은 용납하지 않는다!'),
(19831, 2, 0, '각하!'),
(19831, 3, 0, '알겠습니다.'),
(19831, 4, 0, '지켜보겠다, 아르도니스!'),
