(20060, 1, 0, '안 돼! 나는... 절대로...'),
(20063, 0, 0, '아나랄라 벨로레!'),
(20063, 1, 0, '이걸로 안심하긴... 이르다.'),
(20064, 0, 0, '각오 단단히 해라!'),
(20064, 1, 0, '용서하십시오, 왕자님... 제가... 졌습니다.'),
(20064, 2, 0, '%s|1이;가; $n|1을;를; 노려봅니다!'),
(20071, 0, 0, '좀 더 조용한 곳에서 토론을 진행합시다. 절 따라오십시오, $n...'),
(20071, 1, 0, '내가 정말로 네놈과 다시 거래를 할 것이라 생각하지는 않았겠지? 손해를 줄이는 것이 수익을 남기는 최선의 방법일 때도 있는 법이다!'),
(20095, 0, 0, '멍청하고 우스운 것... 박살 내주마!'),
(20095, 0, 1, '열 받았어. 얼굴에 한 방 날린다!'),
