(20095, 2, 0, '너! 너 말이다! 놈들을 해치워라!'),
(20095, 2, 1, '한 명도 놓치지 마라, 이 벌레 같은 놈들!'),
(20095, 2, 2, '얼라이언스와 호드 돼지들 해치워라!'),
(20095, 2, 3, '거기 일어서. 칼날첨탑 요새로 진격한다. 내 탑을 고르딤의 머리로 장식하고 싶다!'),
(20100, 0, 0, '그게... 모두 꿈이었다니? 하늘안개 섬, 핏빛안개 섬, 장가르 습지대, 어둠달 골짜기... 그리고 줄아만까지도... 제인! 어디 있니?!'),
(20100, 1, 0, '아, 멋지군요. 모든 게 한낱 꿈이었습니다...'),
(20140, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(20159, 0, 0, '내가 친구를 그리 쉽게 배신할 줄 알았느냐. 착각하지 마라! 내게 맞서보아라, 이 불한당 같은 녀석!'),
(20159, 1, 0, '살려 주십시오! 아렐리온의 비밀에 대해 알려드리겠습니다.'),
(20209, 0, 0, '경고! $n|1이;가; %s 긴급 차단 시스템을 가동하였습니다. 2분 후에 차단이 완료됩니다.'),
(20209, 1, 0, '긴급 차단까지 1분 남았습니다.'),
(20209, 2, 0, '긴급 차단까지 30초 남았습니다.'),
(20209, 3, 0, '긴급 차단까지 10초 남았습니다.'),
(20209, 4, 0, '긴급 차단이 완료되었습니다.'),
(20209, 5, 0, '마나괴철로 차단이 취소되었습니다. 마나괴철로를 다시 가동합니다.'),
(20218, 0, 0, '긴급 차단을 막아야 한다! 캘타스 님께서 이 일을 알게 되시면 우릴 가만두지 않으실 것이다!'),
(20218, 0, 1, '당장 멈춰라!'),
(20218, 0, 2, '나루의 긴급 차단 시스템이 가동되면 마나괴철로를 영원히 쓸 수 없게 된다. 그러니 반드시 취소해야 한다!'),
(20221, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(20227, 0, 0, '너를 철창에서 꺼내 줄 시간이 된 것 같구나.'),
(20227, 1, 0, '자, 이제 중화제를 뿌려 주면...'),
(20227, 2, 0, '성공이야!'),
(20234, 0, 0, '경비병!'),
(20239, 0, 0, '중화제를 호수에 섞자 수정에 오염된 물이 깨끗해지는 것 같습니다.'),
(20242, 0, 0, '밀수품 중 최상품은 바로 여기에 모여 있습니다, $n. 누이 좋고 매부 좋은 일이죠! 고블린의 세금과 나루의 금지령을 피할 수 있는 물건들입니다. 저희 무역연합은 당신이 필요한 모든 물건을 언제나 공급해 드리고 있습니다!'),
(20279, 0, 0, '%s|1이;가; 격노합니다!'),
