(20334, 1, 1, '아... 나... 죽는다.'),
(20334, 1, 2, '오그릴라... 간다.'),
(20334, 1, 3, '$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?'),
(20334, 1, 4, '$G왕:여왕;님... 나 죽여라.'),
(20334, 1, 5, '$G왕:여왕;님, $n, 나 이제 죽는다.'),
(20342, 0, 0, '무슨 일이오, 내트?'),
(20342, 1, 0, '어떤 꿈 말이오?'),
(20342, 2, 0, '대체 무슨 말도 안 되는 소리오, 내트?'),
(20342, 2, 1, '내트, 그런 터무니없는 소리를 처음 듣는 건 아니지만 이건 좀 너무하는군.'),
(20342, 2, 2, '말도 안 돼!'),
(20344, 0, 0, '할...'),
(20344, 1, 0, '어젯밤 또 그 꿈을 꿨습니다...'),
(20344, 2, 0, '그 꿈 말입니다... 아주 황당한 꿈. 기억 안 나십니까?'),
(20344, 3, 0, '타렌 제분소가 언데드 군대에 의해 파괴되고 남녘해안과 영원히 원수지간이 되는 꿈 말입니다.'),
(20344, 4, 0, '상상이 됩니까, 할? 그런 일은 없겠지요?'),
(20344, 5, 0, '수천 명의 사람들이 하늘 위에서 우리를 바라보던 그 꿈...'),
(20344, 6, 0, '우리는 그들의 꼭두각시 인형처럼 춤추고, 울고, 싸우고, 어리석은 말을 하면서 그들을 즐겁게 했지요.'),
(20344, 7, 0, '가끔 깨어 있을 때도 그들이 우리를 바라보고 있다고 생각합니다. 아마 지금 이순간도 지켜보고 있겠지요...'),
(20344, 8, 0, '그러니까 내가 어떤 거대하고 오래된 나무가 있는 산에 있었습니다. 주위에는 엘프들이 여기저기 뛰어다니고 있었고요...'),
(20344, 9, 0, '그런데 갑자기 키가 100미터 정도 되는 악마가 나타나 그 거대한 나무를 오르기 시작하는 겁니다.'),
(20344, 10, 0, '더욱 희한한 것은 그 거대한 악마가 둥둥 떠다니는 자그마한 빛 같은 것들에 죽임을 당하는 것이었습니다. 아, 그리고 저는 여자 엘프였습니다. 네... 황당했지요...'),
(20344, 11, 0, '이번 꿈에서 나는 세상에서 제일가는 어부였답니다. 그리고 칼림도어라고 불리는 곳으로 갔지요...'),
(20344, 12, 0, '그리고 전 세계에서 사람들이 찾아와 제게 고기 잡는 법을 배워 갔답니다.'),
(20344, 13, 0, '저는 낚시의 신이나 마찬가지였습니다...'),
(20344, 14, 0, '정말 오싹한 꿈이었습니다... 그러니까 왕의 아들인 아서스가... 우서 경과 함께 악을 무찌르러 가는데... *이마의 땀을 닦는 내트*'),
(20344, 15, 0, '가엾게도 아서스 왕자는 악마에게 마음을 빼앗겨 악마가 되고 맙니다...'),
(20344, 16, 0, '그는 착한 척하며 기회를 잡아 왕인 아버지에게 다가간 후 칼을 뽑아 즉시 왕을 살해했답니다.'),
(20344, 17, 0, '믿을 수가 없지만 말입니다...혹시 폴로르와 티굴이라는 두 건달 녀석들을 알고 있습니까?'),
(20344, 18, 0, '이번 꿈에선 그자들이 아이스크림이라고 불리는 뭔가를 발명했는데 딸기 맛이 났습니다... 간단히 말해서 그자들이 아이스크림으로 엄청난 부자가 됐지 뭡니까!'),
(20344, 19, 0, '더 웃긴 것은 그들이 아이스크림 장사를 그만두고 모험가가 된다는 겁니다... 전 세계를 여행하다 결국은 어떤 차원문에 들어가게 되곤... 전 그 뒤에 식은땀을 흘리며 깨어났답니다...'),
(20344, 20, 0, '그 왜 제가 던홀드에 있는 꿈과 블랙무어가 노예로 부리던 오크가 탈출하는 꿈 말입니다.'),
(20344, 21, 0, '결국 그는 감옥을 통째로 부수고 포로가 된 오크들을 모두 구출한 뒤 오크들의 왕이 되었답니다... 대족장인가 뭐라고 부르는 것 같았습니다.'),
(20344, 22, 0, '황당한 꿈이지요?'),
(20350, 0, 0, '다른 자들이 근처에 있으니 목소리를 낮추시오, 헬쿨라.'),
(20350, 1, 0, '강령술. 강령술이라고 하오. 그리고 당신에게 내 힘에 담긴 그 기술을 가르쳐 줄 수 있소이다.'),
(20350, 2, 0, '헬쿨라, 당신은 키린 토의 일원도 아니고 강령술사도 아니니 당신이 걱정할 일이 아니오.'),
(20350, 3, 0, '솔직히 말해 키린 토가 어떻게 생각하든 난 전혀 관심이 없소! 그들은 구시대적인 방식만을 고집하는 바보들이라오.'),
(20350, 4, 0, '때가 되면, 헬쿨라... 모든 것은 때가 되면 이루어질 것이오...'),
(20353, 0, 0, '음, 그래서... 저에게 이것 저것 가르쳐 주실 수...'),
(20353, 1, 0, '그럼 키린 토에서는요? 그들은 강령술에 대해 뭐라고 하던가요?'),
(20353, 2, 0, '켈투자드 님, 절 가르쳐 주십시오. 당신이 알고 있는 모든 것을..'),
(20415, 0, 0, '긴급 차단이 완료되었습니다.'),
(20415, 1, 0, '긴급 차단이 완료되었습니다.'),
(20417, 0, 0, '경고! $n|1이;가; %s 긴급 차단 시스템을 가동하였습니다. 2분 후에 차단이 완료됩니다.'),
(20417, 1, 0, '긴급 차단까지 1분 남았습니다.'),
(20417, 2, 0, '긴급 차단까지 30초 남았습니다.'),
(20417, 3, 0, '긴급 차단까지 10초 남았습니다.'),
(20417, 4, 0, '긴급 차단이 완료되었습니다.'),
(20417, 5, 0, '마나괴철로 차단이 취소되었습니다. 마나괴철로를 다시 가동합니다.'),
(20418, 0, 0, '경고! $n|1이;가; %s 긴급 차단 시스템을 가동하였습니다. 2분 후에 차단이 완료됩니다.'),
