(20440, 5, 0, '마나괴철로 차단이 취소되었습니다. 마나괴철로를 다시 가동합니다.'),
(20474, 0, 0, '수송관을 보호해라! 침입자들을 막아라!'),
(20482, 0, 0, '적군이 감지되었소. 전송 종료!'),
(20482, 1, 0, '자유연합 전송 완료.'),
(20600, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(20610, 0, 0, '%s|1이;가; 근처에 있는 수컷에게 도움을 요청합니다!'),
(20610, 1, 0, '%s|1이;가; 약해진 것 같습니다.'),
(20677, 0, 0, '당신이 날 구해 줬구려! 다시 한 번 바람이 우리 일족에게 말을 하고 힘을 주고 있소이다. 정말 고맙소.'),
(20678, 0, 0, '드디어 자유로구나! 우리 일족이 그들의 주인과 싸울 용기를 얻을 수 있도록 불의 정령에게 돌아와 달라고 부탁하겠소이다! 고맙소.'),
(20679, 0, 0, '드디어 자유다! 물의 정령이 우리 일족에게 돌아올 것이오. 그러면 우리는 이 험난한 땅에서 살아남을 수 있는 지혜를 얻을 수 있소이다. 당신에게 빚을 졌구려, $n.'),
(20680, 1, 0, '그 뒤틀린 드레나이 벌레 녀석이 지팡이를 줬군. 그렇지? 자기가 바로 동족을 팔아먹은 장본인이라는 말도 하던가? 어찌 됐든 네놈들은 대가를 치러야 한다!'),
(20756, 0, 0, '멍청하고 우스운 것... 박살 내주마!'),
(20756, 0, 1, '열 받았어. 얼굴에 한 방 날린다!'),
(20756, 0, 2, '우어어!!! 나 $r 죽일거야!'),
(20756, 1, 0, '작은 $r... 넌 하찮은 $g왕:여왕;이었...다...'),
(20756, 1, 1, '아... 나... 죽는다.'),
(20756, 1, 2, '오그릴라... 간다.'),
(20756, 1, 3, '$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?'),
(20756, 1, 4, '$G왕:여왕;님... 나 죽여라.'),
(20756, 1, 5, '$G왕:여왕;님, $n, 나 이제 죽는다.'),
(20762, 0, 0, '경비병!'),
(20763, 0, 0, '고맙습니다, 친구여. 여기서 나갈 수 있게 도와주시겠습니까?'),
(20763, 1, 0, '자유연합 경비초소가 그리 멀지 않습니다, $n. 이쪽입니다!'),
(20763, 2, 0, '사령관님! 이 친구가 절 구했습니다!'),
(20763, 3, 0, '%s|1이;가; 사령관 야미르에게 경례합니다.'),
