(20765, 0, 1, '열 받았어. 얼굴에 한 방 날린다!'),
(20765, 0, 2, '우어어!!! 나 $r 죽일거야!'),
(20765, 1, 0, '작은 $r... 넌 하찮은 $g왕:여왕;이었...다...'),
(20765, 1, 1, '아... 나... 죽는다.'),
(20765, 1, 2, '오그릴라... 간다.'),
(20765, 1, 3, '$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?'),
(20765, 1, 4, '$G왕:여왕;님... 나 죽여라.'),
(20765, 1, 5, '$G왕:여왕;님, $n, 나 이제 죽는다.'),
(20765, 2, 0, '%s|1이;가; 격노합니다!'),
(20766, 0, 0, '멍청하고 우스운 것... 박살 내주마!'),
(20766, 0, 1, '열 받았어. 얼굴에 한 방 날린다!'),
