(20768, 0, 1, '열 받았어. 얼굴에 한 방 날린다!'),
(20768, 0, 2, '우어어!!! 나 $r 죽일거야!'),
(20768, 1, 0, '작은 $r... 넌 하찮은 $g왕:여왕;이었...다...'),
(20768, 1, 1, '아... 나... 죽는다.'),
(20768, 1, 2, '오그릴라... 간다.'),
(20768, 1, 3, '$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?'),
