(20774, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(20777, 0, 0, '%s|1이;가; 약해진 것 같습니다.'),
(20787, 0, 0, '당신이 절 구했군요! 야미르에게 당신의 고귀한 행동에 대해 말하겠습니다.'),
(20802, 0, 0, '어서 끝냅시다... 제가 장치를 운반하는 동안 절 엄호해 주십시오.'),
(20802, 1, 0, '맙소사! 여길 좀 보십시오! 살라다르가 뭘 계획하고 있는지 상상이 되는군요. 어서 계속 갑시다.'),
(20802, 2, 0, '이렇게 많은 공허의 폐기물과 물기를 보니 독성 수액괴물이 그리 멀지 않은 곳에 있는 것 같군요.'),
(20802, 3, 0, '저기 좀 보십시오! 살라다르의 수송관이로군요! 그자가 공허의 힘을 잘 관리하고 있군...'),
(20802, 4, 0, '좋습니다, 제가 이 장치를 설치하는 동안 절 엄호해 주십시오. 그리 오래 걸리지 않을 겁니다.'),
(20802, 5, 0, '끝났습니다! 어서, 뒤로! 물러나십시오!'),
(20802, 6, 0, '여기서 제가 할 일은 끝난 것 같군요. 송수신기로 돌아가서 야미르의 홀로그램 영상에게 보고하도록 하십시오.'),
(20802, 7, 0, '공격받고 있습니다! 반복합니다, 공격받고 있습니다!'),
(20802, 7, 1, '저들이 저한테 접근하지 못하게 해주십시오!'),
(20812, 0, 0, '축하해. 여기 오니까 폐허에 있을 때보다 냄새가 더 지독해졌군.'),
(20812, 0, 1, '이봐 뚱보, 너희는 왜 변으로 가득한 구덩이에서 살기를 고집하는 거지?'),
(20812, 0, 2, '먹을 것 좀 주면 안 될까??? 이건 말도 안 돼!'),
(20812, 0, 3, '네 발 냄새나 변을 가득 채운 치즈와 생선 조각. 이보다 더 지독한 냄새가 있을까?'),
(20812, 1, 0, '두 번 다시 잡히지 않을 거예요! 약속해요! 그럼 또 안녕히!'),
(20870, 0, 0, '집어삼킬 생명이 나타났다...'),
(20870, 1, 0, '이제 빈... 껍데기뿐이군.'),
(20870, 1, 1, '다... 먹어... 치웠다.'),
(20870, 2, 0, '어둠이... 널... 삼키리라.'),
(20870, 2, 1, '암흑은... 모든 걸 먹어치우지.'),
(20870, 3, 0, '공허가... 날... 부른다.'),
(20886, 0, 0, '달리아를 혼내주러 왔군. 구경 좀 해도 되겠지?'),
(20886, 1, 0, '짜증이 나던 참이었는데, 잘 걸렸다!'),
(20886, 2, 0, '음, 기분이 좀 나아지는군.'),
(20886, 3, 0, '각오해라!'),
(20886, 3, 1, '각자 알아서 방어하는 게 좋을 거다...'),
(20886, 4, 0, '역시... 벗어나는 길은... 이것뿐인가...'),
(20886, 5, 0, '무슨 문제라도 있나, 달리아? 쌤통이군.'),
(20886, 5, 1, '오늘이 네 마지막 날이다, 달리아. 정말 수치스럽겠어.'),
(20886, 5, 2, '새로운 전략 하나 제안하지... 네가 얻어터지는 동안 난 지원군을 모으는 거야.'),
(20886, 6, 0, '결국, 해냈군! 잘했어!'),
(20886, 7, 0, '날 찾았나, 달리아?'),
(20886, 8, 0, '무거운 걸 들어달라고 불렀을 테지.'),
(20886, 9, 0, '그렇다면, 철저히 무시해주지.'),
(20886, 10, 0, '너야말로 철저함과는 거리가... 잠깐, 여기 손님들이 오신 것 같군...'),
(20904, 0, 0, '왕자님께서 노하실 줄은 알았지만, 난... 제정신이 아니었어. 그들을 풀어줄 수밖에 없었다고! 봐, 위대한 분께서 말씀하시잖아! 잠깐... 캘타스 왕자님께서 보낸 자들이 아니잖아! 좋았어... 네놈들이 죄수를 풀어줬다고 일러바치면 되겠군!'),
(20904, 1, 0, '나루는 세상에서 가장 위험한 존재들을 이곳에 가두었다. 내 친히 소개하지...'),
(20904, 2, 0, '그래, 좋아!'),
(20904, 3, 0, '잘 봐라, 무한한 힘을 가진 절대 공포의 존재가 강림하신다!'),
(20904, 4, 0, '뭐... 뭐야? 땅딸보 노움? 오, 위대한 분이시여, 노여워 마소서.'),
(20904, 5, 0, '이 혼란! 이 공포! 위대한 분이시여, 선견지명에 감탄했습니다!'),
(20904, 6, 0, '드디어 마지막이군. 예. 위대한 분이시여, 즉시 시행하겠습니다!'),
(20904, 7, 0, '어서 오십시오. 저는 당신의 충실한 종입니다.'),
(20912, 0, 0, '나약한 정신은 조종하기 아주 쉽지... 난 시간과 운명조차 건드릴 수 없는 강력한 분께 충성을 맹세했느니라. 이 세계와 저 너머 세계의 어느 누구도 우리를 꺾지 못해... 저 잘난 불타는 군단조차도!'),
(20912, 1, 0, '네 운명을 마무리 짓고자 내가 왔노라!'),
(20912, 2, 0, '네 운명이 결정되었다.'),
(20912, 2, 1, '지금까지의 혼돈은 맛보기에 불과하다...'),
(20912, 3, 0, '명령에 복종하라. 나약한 자여...'),
(20912, 3, 1, '너의 의지는 나의 것이다.'),
(20912, 4, 0, '공포에 떨며 도망쳐라.'),
(20912, 4, 1, '상상도 못할 공포를 보여주마.'),
(20912, 5, 0, '밤하늘의 무한한 별처럼 온 우주를 덮으리라!'),
(20912, 6, 0, '나는 무한한 선구자 중... 한 명일 뿐...'),
(20977, 0, 0, '여기는 얄리얄리 얄라셩 어디쯤인가? 넌 누구... 으아악, 이햐! 머리가 깨질 듯 아파!'),
(20977, 1, 0, '땅딸보 노움이라고? 친구... 당신이 누구든지 간에 아무도 이 위대한 밀하우스 마나스톰 님을 땅딸보라고는 부르지 않아!'),
(20977, 2, 0, '전 좀 준비할 게 있네요. 여러분은 시작하셔도 좋아요. 물 좀 만들어야 해서...'),
(20977, 3, 0, '다음엔 이 백옥 같은 피부를 보호할 마법도 걸고... 자, 한바탕 놀아볼까나!'),
(20977, 4, 0, '으으, 내 정신 좀 봐. 마나부터 채워야지. 굉장한 기술이 나오니까 쫌만 참아요.'),
(20977, 5, 0, '쪼오오아았어! 이렇게 신나게 두들겨팰 덩어리를 누가 불러줬지?'),
(20977, 6, 0, '이 정도야 식은 죽 먹기보다 더 쉽지!'),
(20977, 6, 1, '언제든지 덤비라고.'),
(20977, 7, 0, '화끈하게 놀아주마, 귀여운 것!'),
(20977, 8, 0, '얼음! 얼음이라니깐!'),
(20977, 9, 0, '도와줘! 여러분의 사랑으로 치유의 힘을 모아주세요! 노움 죽네!'),
(20977, 10, 0, '으으이햐... 신고하고 말 거야!'),
(20977, 11, 0, '누가 악당이야? 누가 악당이냐고? 맞았어! 우리가 악당이지!'),
(20983, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(21024, 0, 0, '정령들이 공격할지도 모르니 물러서시오, $n.'),
(21024, 1, 0, '정령이여, 우리는 그대들을 돕고 싶소. 그대들의 지혜를 구합니다.'),
(21024, 2, 0, '그대들의 말이 맞소, 정령이여... 그대들에게 그런 짓을 한 것은 나의 동족이었소. 우리가 그 잘못을 바로잡게 해주시오.'),
(21024, 3, 0, '제발 이것만은 알려주시오. 대체 사이루크가 뭐요?'),
(21024, 4, 0, '불... 불의 군주라고 하셨소? 정령들의 군주가 깨어났다는 말이오? 그렇군... 굴단 당신은 정말 바보였소!'),
(21024, 5, 0, '분명 방법이 있을 거요.'),
(21024, 6, 0, '정령이여, 나와 동료를 믿어주시오. 그리고 불의 군주를 소환할 방법을 알려주시오. 우리 동맹이 놈을 쓰러뜨릴 거요.'),
(21024, 7, 0, '우리는 반드시 그 주문을 찾아낼 거요. 그리고 놈을 소환해 해치우겠소.'),
(21024, 8, 0, '%s|1이;가; 고개를 끄덕입니다.'),
(21024, 9, 0, '이제 잃어버린 주문을 되찾을 시간이오!'),
(21024, 10, 0, '%s|1이;가; 고개 숙여 인사합니다.'),
(21027, 1, 0, '조심해!'),
(21057, 0, 0, '감히 누가 나의 작업을 방해하느냐?'),
(21104, 0, 0, '승리 또는 죽음!'),
(21104, 0, 1, '너희에게는 시간이 얼마 없다!'),
(21104, 0, 2, '균열을 보호해야 한다!'),
(21107, 0, 0, '경비병!'),
(21114, 0, 0, '으악!!'),
(21114, 0, 1, '악! 내 몸에 불이 붙었어!!!'),
(21114, 0, 2, '부... 불타고 있어!!'),
(21114, 0, 3, '이런 또 내 몸에 불이 붙었어!!!'),
(21114, 0, 4, '왜 하필 나만 이러냐고?!'),
(21114, 0, 5, '또...?'),
(21118, 0, 0, '가자!!'),
(21118, 1, 0, '방어 포탑 발사!'),
(21118, 2, 0, '지원군은 언제 오는 거지? 당장 필요한데 말이야!'),
(21118, 3, 0, '마지막 공격이다! 놈들에게 본때를 보여주자!'),
(21118, 4, 0, '잘했다, 제군들! 마지막 놈들이다!'),
(21118, 4, 1, '마지막 놈들이니 모두 정신 차려!'),
(21118, 5, 0, '이제 우리가 통제할 수 있습니다. 기병대 여러분, 이만 해산해도 좋습니다.'),
(21118, 6, 0, '어서, 이 바보야. 영원히 살고 싶지 않아?'),
(21118, 6, 1, '몸을 풀고 녀석들에게 실력을 제대로 보여주란 말이야!'),
(21118, 6, 2, '내 규칙은 딱 하나지. 모두 싸우고 아무도 그만두지 못한다.'),
(21129, 0, 0, '우리를 왜 사로잡았지?'),
(21129, 1, 0, '바보 같은! 불의 군주 사이루크 말일세! 연결 고리가 끊어졌을 때 사이루크가 깨어났지. 사이루크의 눈물이 흘러내려 이 땅을 용암으로 채운 걸세.'),
(21129, 2, 0, '그래, 맞아! 그 주문... 파멸의 주문... 자네의 스승이었던 어둠의 존재가 사용했던 그 주문!'),
(21129, 3, 0, '대화... 대화가 필요하오... 필멸의 생명체여, 이제 우리를 풀어주시오.'),
(21130, 0, 0, '이렇게 해서 얻으려는 게 뭔가?'),
(21130, 1, 0, '지금 그는 제정신이 아닐세. 세계가 파괴되는 동안 미쳐버렸지. 우리 정령들이 쉴 수가 없어.'),
(21130, 2, 0, '그래... 굴단...'),
(21131, 0, 0, '지혜라고 했나? 사이루크의 억제할 수 없는 분노를 부른 것은 자네 종족이었잖아.'),
(21131, 1, 0, '그래, 방법이 있어. 바로 사이루크를 해치우는 걸세. 정령의 군주를 해치워야 해.'),
(21132, 0, 0, '우리가 왜 너희를 도와야 하지? 이 세계는 폐허가 되었어. 멸망했단 말이지.'),
(21132, 1, 0, '주문을 외워야 하네...'),
(21213, 0, 0, '심연의 해일이 집어삼키리라!'),
(21213, 1, 0, '바다의 힘으로!'),
(21213, 1, 1, '나의 피조물들아, 놈들을 파괴하라!'),
(21213, 2, 0, '숨을 곳은 아무 데도 없다!'),
(21213, 2, 1, '곧 끝장내주마!'),
(21213, 3, 0, '끝장이다!'),
(21213, 3, 1, '발버둥쳐 봤자 고통만 더할 뿐...'),
(21213, 3, 2, '오직 강한 자만이 살아남지.'),
(21213, 4, 0, '아지온의... 거대한 파도가 날 기다린다...'),
(21213, 5, 0, '%s|1이;가; 자신의 적을 수중 무덤으로 내몹니다!'),
(21213, 6, 0, '근처에 있던 멀록들이 격렬한 지진을 느끼고 주위로 달려듭니다!'),
(21213, 7, 0, '%s|1이;가; 물방울을 일으킵니다!'),
(21214, 0, 0, '경비병! 여기 침입자들이 있다...'),
(21214, 1, 0, '그 자만심이 파멸로 이끌리라! 경비병, 힘을 보태줘야겠다!'),
(21214, 2, 0, '계속해라! 난 더 강해질 테니까!'),
(21214, 2, 1, '나는 그 어느 때보다 더 강력하다!'),
(21214, 2, 2, '더 많은 지혜와 더 강한 힘을!'),
(21214, 3, 0, '땅벌레 주제에!'),
(21214, 3, 1, '알라나 베렌도르!'),
(21214, 3, 2, '또 한 놈 처치했다.'),
(21214, 4, 0, '여군주께서... 기다리고... 계신다.'),
(21215, 0, 0, '드디어, 내가 풀려났도다!'),
(21215, 1, 0, '꺼져라, 엘프 꼬맹이. 지금부터는 내가 주인이다!'),
(21215, 2, 0, '누구나 마음속에 악마를 품고 살지...'),
(21215, 3, 0, '나를 상대할 자 누구냐?!'),
(21215, 3, 1, '꺼져 버려라!'),
(21215, 3, 2, '그래... 이거야!'),
(21215, 4, 0, '죽어라, 죽어!'),
(21215, 4, 1, '좋아, 바로 이거야!'),
(21215, 4, 2, '이제 누가 주인인지 알았지?'),
(21215, 5, 0, '안 돼... 안 돼! 무슨 짓이냐? 내가 주인이야! 내 말 듣지 못해? 나란 말이야! 내가... 으아악! 놈을 억누를 수... 없...어.'),
(21215, 6, 0, '드디어 해방이구나. 진정한 자유를 맛보는 게 대체 얼마 만인가!'),
(21215, 7, 0, '날 죽일 순 없다, 멍청한 놈들! 다시 돌아오겠다... 난...'),
(21216, 0, 0, '방해하도록 놔두지 않겠습니다!'),
(21216, 1, 0, '아... 기분이 훨씬 좋군.'),
(21216, 2, 0, '이럴 수밖에 없었습니다.'),
(21216, 2, 1, '선택의 여지가 없었습니다.'),
(21216, 3, 0, '드디어... 해방이다...'),
(21216, 4, 0, '으아아, 독이...'),
(21216, 5, 0, '이곳을 깨끗이 정화하겠다!'),
(21216, 5, 1, '그들과 다를 게 하나도 없구나!'),
(21216, 6, 0, '오염된 건... 내가 아니라... 너희다!'),
(21218, 0, 0, '%s|1이;가; 격노합니다!'),
(21238, 0, 0, '멍청하고 우스운 것... 박살 내주마!'),
(21238, 0, 1, '열 받았어. 얼굴에 한 방 날린다!'),
(21238, 0, 2, '우어어!!! 나 $r 죽일거야!'),
(21238, 1, 0, '작은 $r... 넌 하찮은 $g왕:여왕;이었...다...'),
(21238, 1, 1, '아... 나... 죽는다.'),
(21238, 1, 2, '오그릴라... 간다.'),
(21238, 1, 3, '$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?'),
(21238, 1, 4, '$G왕:여왕;님... 나 죽여라.'),
(21238, 1, 5, '$G왕:여왕;님, $n, 나 이제 죽는다.'),
(21238, 2, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(21279, 0, 0, '실험을 시작할 테니 잠시 기다리게...'),
(21279, 1, 0, '이건... 흥미롭군.'),
(21279, 2, 0, '아니, 이건 뭐야?'),
(21279, 3, 0, '맙소사!'),
(21279, 4, 0, '오래전 내 피가 차갑게 굳어버리지 않았다면 지금 엄청나게 끓어올랐을 거야...'),
(21291, 0, 0, '순순히 불어라, 물고기 인간아...'),
(21291, 1, 0, '파멸의 암호는 어디 있느냐? 세 번째 조각이 이 마을에 있다는 걸 알고 있다.'),
(21291, 2, 0, '아니라고? 물론 그렇게 대답하겠지. 내가 무슨 생각을 한 줄 아느냐? 파멸의 암호의 세 번째 조각을 지키려는 이유가 뭐지?'),
(21291, 3, 0, '내가 어리석었군. 족쇄를 풀고 널 놓아주면 대답을 하겠지?'),
(21291, 4, 0, '나가야, 내가 그렇게 멍청하게 보였나? 고통을 보여주마!'),
(21291, 5, 0, '%s|1이;가; 갈퀴흉터 나가에게 침을 뱉습니다.'),
(21291, 6, 0, '일어나, 이 썩어 문드러진 쓰레기 같은 놈아! 끝장내기 전에 일어서!'),
(21291, 7, 0, '말해라...'),
(21293, 0, 0, '숨어! 놈들이 자네를 발견하기 전에 어서! 물러나란 말이야!'),
(21293, 1, 0, '공격 시간이 얼마 안 남았다. 이카리우스를 끝장내라.'),
(21293, 2, 0, '여기 있다. 다시는 잃어버리지 마라!'),
(21295, 0, 0, '무슨... 말을 하는 거냐, 부드러운 비늘을 가진 자여?'),
(21295, 1, 0, '우리 나가는... 암호를... 갖고 있지 않다...'),
(21295, 2, 0, '그래... 그래... 날 풀어다오...'),
(21295, 3, 0, '%s|1이;가; 의식을 회복합니다.'),
(21295, 4, 0, '오크여, 더 이상 때리지 마라! 말할 테니까! 암호는... 갈퀴흉터 거점에 있는 상자들 중 하나에 숨겨져 있다... 그곳에 있는 나가가 열쇠를 지니고 있다...'),
(21295, 5, 0, '갈퀴흉터 거점 말이다!'),
(21296, 0, 0, '멍청하고 우스운 것... 박살 내주마!'),
(21296, 0, 1, '열 받았어. 얼굴에 한 방 날린다!'),
(21296, 0, 2, '우어어!!! 나 $r 죽일거야!'),
(21296, 1, 0, '작은 $r... 넌 하찮은 $g왕:여왕;이었...다...'),
(21296, 1, 1, '아... 나... 죽는다.'),
(21296, 1, 2, '오그릴라... 간다.'),
(21296, 1, 3, '$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?'),
(21296, 1, 4, '$G왕:여왕;님... 나 죽여라.'),
(21296, 1, 5, '$G왕:여왕;님, $n, 나 이제 죽는다.'),
(21326, 0, 0, '%s|1이;가; 코이코이 영혼의 지배에서 벗어나서 매우 고마워하는 것 같습니다.'),
(21332, 0, 0, '저기! 놈을 해치우세요! 파멸의 암호를 되찾아야 해요!'),
(21332, 1, 0, '놈이 죽었군! 두 번째 파멸의 암호 조각은 이제 우리 것이다. 나... 나는...'),
(21332, 2, 0, '난 사라지고 있어... 알토르에게 돌아... 가... 십시오...'),
(21409, 0, 0, '멈춰라!'),
(21409, 1, 0, '자라스, 즉시 검은 사원으로 돌아가라! 내가... 일리단 님의 명령서를 놓고 온 것 같다. 서둘러라!'),
(21409, 2, 0, '자라스, 나 혼자서도 얼마든지 해그늘 주둔지까지 갈 수 있다. 서한을 전달하지 않으면 일리단 님께 우리 모두 죽게 될 것이다! 이만 돌아가도록!'),
(21409, 3, 0, '오, 맛있는 내 피엉겅퀴... 아마도 해그늘 주둔지의 더러운 중독자들 중 한 놈이 흘리고 갔겠지.'),
(21409, 4, 0, '놈들의 손실이 내게 이렇게 큰 기쁨이 되는구나...'),
(21409, 5, 0, '%s|1이;가; 로브 속에 피엉겅퀴 한 묶음을 넣습니다.'),
(21409, 6, 0, '이런, 빌어먹을! 교묘한 함정이었군. 하지만, 안타깝게도 네놈이 살아 돌아가서 얘기를 전할 가망은 없을 것이다...'),
(21410, 0, 0, '무슨 일입니까?'),
(21410, 1, 0, '그럼 호위는 누가 합니까? 무슨 일이라도 생기면 일리단 님께서 절 가만두지 않으실 겁니다.'),
(21410, 2, 0, '분부대로 하겠습니다.'),
(21426, 0, 0, '기병대! 자, 나가자!'),
(21427, 0, 0, '도움이 필요합니까, 여러분?'),
(21502, 0, 0, '좋아, 파멸의 군주 카자크께서 기뻐하실 것이다. 공격 속도를 높여라. 최대한 빨리 오크와 드워프의 요새를 파괴해라.'),
(21502, 1, 0, '그 문제는 걱정하지 마라. 죽음의 괴철로의 생산량을 늘려 놓았다. 네가 명령을 수행하기에 충분한 지옥불정령을 거느릴 수 있을 것이다. 실패하지 마라, 조바안.'),
(21502, 2, 0, '무엇을 도와드릴까요?'),
(21502, 3, 0, '상자? 너한테 상자를 보낸 적이 없다, 조바안. 이 일보다 더욱 중요한 일이 있지 않던가? 가서 그 일이나 처리하라!'),
(21504, 0, 0, '절대 요청이 아니다.'),
(21504, 1, 0, '듀로 마나괴철로가 보강될 것이다! 울트리스 마나괴철로는 끔찍한 재앙이었어. 같은 실수를 반복하지는 않을 것이다!'),
(21504, 2, 0, '지금까지 우리는 너무나 많은 실패를 겪었다. 지옥불 성채, 무너진 하늘 마루, 불꽃날개 거점... 캘타스 왕자님께서 일이 이 이상 지연되는 것을 용서치 않을 것이다. 나 역시 완벽한 성공을 원한다!'),
(21504, 3, 0, '나는 폭풍우 요새로 돌아간다. 내가 다시 찾아올 일을 만들지 않도록 주의해라!'),
(21504, 4, 0, '현재까지는 그렇다. 하지만, 계속 분발하기 바란다. 캘타스 왕자님께서는 무너진 하늘 마루에서 수정 실험이 실패한 것에 대해 실망하셨다. 그래서 세나리온의 드루이드들을 대상으로 폭탄을 실험하는 것이다.'),
(21504, 5, 0, '저 아래 안마당의 마나 폭탄을 조속한 시간 내에 실전에 투입할 수 있도록 준비하지 못하면 어떤 일이 일어날지는 말 안 해도 알지? 놈들이 숲으로 들어간 이후 여기 투렘과 남쪽의 해골이빨 폐허에서 진행 중인 우리 작전을 사사건건 방해하고 있다.'),
(21504, 6, 0, '호드와 얼라이언스 놈들에게 교훈을 가르쳐 줘야겠다. 평생 잊지 못할 교훈으로!'),
(21504, 7, 0, '지켜보겠다, 샤르스! 만약 네 말대로 되지 않으면 너는 천천히 그리고 고통스럽게 죽게 될 것이다.'),
(21504, 8, 0, '보아하니, 적들이 찾아왔군. 샤르스, 이 문제부터 우선 해결해라. 그런 다음 마나 폭탄으로 놈들의 마을을 파괴하도록!'),
(21514, 0, 0, '누가 감히 용포식자 고르그롬의 제단을 더럽히느냐?'),
(21514, 1, 0, '놈을 잡아다 가죽을 벗겨 살점을 뜯어먹은 후 뼈를 하나씩 차례대로 부러뜨릴 것이다.'),
(21633, 0, 0, '모든 준비가 완료되었습니다, 전쟁인도자님.'),
(21633, 1, 0, '전쟁인도자님, 그러려면 요새의 지옥불정령을 모조리 동원해야 합니다. 자칫하면 역습을 당할 수가 있습니다.'),
(21633, 2, 0, '말씀하신 대로 행하겠습니다, 전쟁인도자님. 질문이 하나 있습니다만 여쭤도 되올지요...'),
(21633, 3, 0, '저 상자 안에 뭐가 들어 있는 겁니까?'),
(21644, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(21648, 0, 0, '고맙다, 필멸의 존재여.'),
(21661, 0, 0, '%s|1이;가; 격노합니다!'),
(21661, 1, 0, '넌 이제 끝장이다!'),
(21661, 1, 1, '우리한테서 쉽게 벗어날 수 있을 줄 알았느냐!'),
(21661, 1, 2, '보복하고 말 테다!'),
(21694, 0, 0, '%s|1이;가; 격노합니다!'),
(21717, 0, 0, '%s|1이;가; 격노합니다!'),
(21769, 0, 0, '치유사여, 원하는 게 무엇이오?'),
(21769, 1, 0, '눈은 장식품으로 달고 다니나? 바로 우리 코앞에 악마가 있는 게 안 보이시오? 여유 병력이 없소!'),
(21769, 2, 0, '당신이 믿는 신에게 기도나 올리시오. 아마도 도와주러 올 거요. 하지만, 호드는 갈 수 없소...'),
(21771, 0, 0, '이런 보상이 있다는 걸 알면 모험가들이 그냥 지나칠 리가 없겠죠...'),
(21773, 0, 0, '이해할 수가 없군! 당신 눈이 멀기라도 했나? 저 밖에 악마들이 우리 문을 두드리며 쳐들어오려는 게 보이지 않나 보지? 누굴 보내서 당신의 주술사 친구들을 도우라는 거요? 골라보시오!'),
(21797, 0, 0, '하하하, 네 육체는 내 것이다! 우리 운명은 이제 영원히 얽혀 있다.'),
(21838, 0, 0, '누가 나를 이리로 불러냈지? 아직은 때가 아니야... 내 힘이 아직 충분하지 않단 말이다! 이놈들... 이 대가는 충분히 치르게 해 주마!'),
(21838, 1, 0, '네 몸이 무엇으로 되어 있는지 한번 보자꾸나, $n!'),
(21838, 2, 0, '크와! 네놈은 날 죽일 수 없다, 나는 불사신이니까!'),
(21838, 3, 0, '%s|1이;가; 그의 보호막이 부서지자 광포해집니다.'),
(21851, 0, 0, '칠흑으로 덮인 밤이 찾아오면 다시 한 번 까마귀가 어둠 속으로 날아올라 본성을 드러낼 것이다. 그때를 대비하라. 충성을 바치면 까마귀와 함께 비상할 것이고, 그렇지 못한 자들은 날개가 잘려 잊혀진 채 비참하게 땅을 걷게 되리라.'),
(21851, 1, 0, '마음 굳게 먹고 정신 차려라. 땅에서 발을 뗄 수 없는 노예가 된 이들의 약한 마음을 어둠의 날개들이 교란하여 갉아먹을 것이니라.'),
(21851, 2, 0, '까마귀가 찾아오고 하늘에 어둠이 깃들면 오래된 피가 다시 한 번 흘러내릴지니. 붉은 밤이 찾아오면 과거가 깨어나리라.'),
(21851, 3, 0, '까마귀는 준비가 덜 된 상태로 너무 높이 날다가 다시 떨어졌다. 비상할 때를 위해 영겁의 시간은 암흑의 감시자를 준비했다. 지평선 너머 어둠의 망토를 드리우고자...'),
(21873, 0, 0, '나즈자타의 심연을 위해!'),
(21873, 0, 1, '죽어라, 이 동물아!'),
(21873, 0, 2, '주인님을 위하여!'),
(21873, 0, 3, '일리단 만세!'),
(21873, 0, 4, '내 피는 맹독과 같다!'),
(21907, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(22007, 0, 0, '사미아, 혹시 콜피스 다크스케일이 누군지 아시오?'),
(22019, 0, 0, '%s|1이;가; 격노합니다!'),
(22083, 0, 0, '모르고르, 이게 무슨 짓이냐?'),
(22083, 1, 0, '조용히 해!'),
(22083, 2, 0, '헛소리 마라, 이 멍청한 녀석. 어리석고 무능한 광대 같으니...'),
(22083, 3, 0, '이자가 네놈의 용사란 말이냐?'),
(22083, 4, 0, '너는 속았다, 바보 같은 녀석.'),
(22083, 5, 0, '이... 이번 일 전체가... 위험할 뻔했단 말이다!'),
(22083, 6, 0, '이 벌레의 시체를 조각내어 한 시간 내로 내게 가져와라. 만일 실패하거든 죽음보다 더한 고통에 떨게 해 주겠다.'),
(22105, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(22127, 0, 0, '악마추종자의 방독면을 복제할 기회를 얻다니 정말 운이 좋군.'),
(22143, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(22160, 0, 0, '멍청하고 우스운 것... 박살 내주마!'),
(22160, 0, 1, '열 받았어. 얼굴에 한 방 날린다!'),
(22160, 0, 2, '우어어!!! 나 $r 죽일거야!'),
(22160, 1, 0, '작은 $r... 넌 하찮은 $g왕:여왕;이었...다...'),
(22160, 1, 1, '아... 나... 죽는다.'),
(22160, 1, 2, '오그릴라... 간다.'),
(22160, 1, 3, '$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?'),
(22160, 1, 4, '$G왕:여왕;님... 나 죽여라.'),
(22160, 1, 5, '$G왕:여왕;님, $n, 나 이제 죽는다.'),
(22160, 2, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(22181, 0, 0, '%s|1이;가; 생포될 듯 보입니다.'),
(22199, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(22293, 0, 0, '엔진이 고장을 일으키자 %s에서 격렬한 소음이 들립니다.'),
(22314, 0, 0, '야호!'),
(22314, 0, 1, '새처럼 생긴 그 이상한 자들이 우리를 잡아먹으려고 했던 거로군요. 우웩!'),
(22314, 0, 2, '야호! 드디어 자유다!'),
(22314, 0, 3, '윽, 역겨워!'),
(22343, 0, 0, '%s|1이;가; 격노합니다!');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(22373, 0, 0, '테로크의 부하들이 더 몰려오고 있습니다!'),
(22373, 1, 0, '침입자들이 남아 있습니다! 막아야 합니다!'),
(22373, 2, 0, '테로크의 화신이 나타났습니다! 전투를 준비하십시오!'),
(22373, 3, 0, '테로크의 화신을 물리쳤다! 테로크에게 죽음을! 스케티스에게 죽음을!'),
(22374, 0, 0, '누가 감히 내 카르가스 사령관 중 한 명을 죽였느냐? 이 일에 대한 대가는 반드시 목숨으로 치러야 한다!'),
(22384, 0, 0, '너 내가 죽인다!'),
(22384, 0, 1, '우어어!!! 나 $r 죽일거야!'),
(22384, 0, 2, '너 박살내 버린다!'),
(22384, 1, 0, '작은 $r... 넌 하찮은 $g왕:여왕;이었...다...'),
(22384, 1, 1, '아... 나... 죽는다.'),
(22384, 1, 2, '오그릴라... 간다.'),
(22384, 1, 3, '$G왕:여왕;님 정말... 오그릴라 있다고... 생각하나?'),
(22384, 1, 4, '$G왕:여왕;님... 나 죽여라.'),
(22384, 1, 5, '$G왕:여왕;님, $n, 나 이제 죽는다.'),
(22458, 0, 0, '좋아, 모두 잘 들으십시오! 내 주변에 원형으로 포진한 후 조사를 떠나도록 합시다!'),
(22458, 1, 0, '$c님, 우리가 작업하는 동안 안전하게 지켜주시기 바랍니다. 일을 마치면 보상을 드리겠습니다.'),
(22458, 2, 0, '우리가 발굴 작업을 진행할 곳은 여기서 바로 북쪽입니다. 자, 갑시다.'),
(22458, 3, 0, '드디어 도착했군! 모두 땅을 팝시다!'),
(22458, 4, 0, '이 모래 아래 뭔가 묻혀 있는 것 같아요!'),
(22458, 5, 0, '자, 힘냅시다. 거의 다 팠습니다!'),
(22458, 6, 0, '이럴 수가 있나! 이게 뭐지!? 이... 이건 북 같은데...'),
(22458, 7, 0, '지금 제정신입니까? 이런 북을 쳐보지도 않고 가자는 말인가요? 아이언포지의 자손이라면 절대 그런 말 못합니다! 암요, 절대 안 되고 말고요!'),
(22458, 8, 0, '자, 자, 입 좀 다뭅시다! 이제 이 북을 치겠으니 우리 얘기는 여기서 끝입니다!'),
(22458, 9, 0, '낯빛이 싹 바뀌는군요! 그러게 내가 여기 뭔가 있다고 말하지 않았습니까!'),
(22458, 10, 0, '$c! 거기 그러고 멍하니 서 있지 말고 가서 $g그:그녀;를 도와주십시오!'),
(22458, 11, 0, '$c|1이여;여;, 정말 큰 도움이 되었습니다! 놈들이 더 몰려오기 전에 여기서 나갑시다! 드워포위츠에게 당신이 일을 매우 잘했다고 전할 테니 그에게 가보십시오.'),
(22464, 0, 0, '오... 대단하군요... 이런 북이 나오다니...'),
(22464, 1, 0, '이번 발견은 현대 고고학의 초석에 큰 파장을 불러올 겁니다.'),
(22464, 2, 0, '네, 정말 대단한 발견이로군요. 근데 이제 여길 떠나도 되지 않을까요? 이런 사막에 있으려니까 두드러기가 나는 것 같아서요.'),
(22464, 3, 0, '이런 상황이 발생하니까 당신이 우리에게 실리더스를 수색하여 모래 노움의 증거를 찾으라고 했던 일이 생각나는군요.'),
(22464, 4, 0, '또 당신이 20세기 역병의 치료제를 찾았다고 말하던 때도 새록새록 기억나는군요. 그런데 그것마저 뭐였죠? 그 20세기인가 뭔가 하는 그거 말입니다!'),
(22464, 5, 0, '그래도 지금 상황이, 여명의 설원 빙하 아래 아서스의 ''사촌'' 유골이 묻혀 있다는 소리를 들었다고 레톨이 말하던 그때보다 더 어이없진 않네요. 그거 때문이라도 난 당신을 용서할 수가 없어요, 레톨. 진심이라고요... 아서스의 사촌이 어쩌고저쩌고라고요?'),
(22464, 6, 0, '정말 뭐가 뭔지 모르겠군요. 지금 이 상황은, 레톨 당신이 우리는 사실 어떤 상상의 존재이며, 우리가 단지 그들의 즐거움을 위해 존재한다고 말하던 그때보다 더 화가 나지는 않아요. 가족과 함께 식사를 하는 동안엔 잘 넘어갔지만 말입니다.'),
(22464, 7, 0, '방금 그 소린 뭐였죠?'),
(22485, 0, 0, '경비병!'),
(22515, 1, 0, '푸른 사파이어 관문이 공격받고 있습니다!'),
(22515, 2, 0, '초록 에메랄드 관문이 공격받고 있습니다!'),
(22515, 3, 0, '붉은 태양 관문이 공격받고 있습니다!'),
(22515, 4, 0, '보라 자수정 관문이 공격받고 있습니다!'),
(22515, 5, 0, '노란 달 관문이 공격받고 있습니다!'),
(22515, 6, 0, '노란 달 관문이 무너졌습니다!'),
(22515, 7, 0, '보라 자수정 관문이 무너졌습니다!'),
(22515, 8, 0, '붉은 태양 관문이 무너졌습니다!'),
(22515, 9, 0, '초록 에메랄드 관문이 무너졌습니다!'),
(22515, 10, 0, '푸른 사파이어 관문이 무너졌습니다!'),
(22515, 11, 0, '얼라이언스가 동부 무덤을 차지했습니다!'),
(22515, 12, 0, '얼라이언스가 서부 무덤을 차지했습니다!'),
(22515, 13, 0, '얼라이언스가 남부 무덤을 차지했습니다!'),
(22515, 14, 0, '호드가 동부 무덤을 차지했습니다!'),
(22515, 15, 0, '호드가 서부 무덤을 차지했습니다!'),
(22515, 16, 0, '호드가 남부 무덤을 차지했습니다!'),
(22515, 17, 0, '유물의 방이 공격받고 있습니다!'),
(22515, 18, 0, '유물의 방 방어선이 깨졌습니다! 티탄 유물이 위험합니다!'),
(22834, 0, 0, '%s|1이;가; 무릎을 꿇더니 벌떡 일어납니다. 하지만, 자신이 어디 있는지 알아차리지 못하는 것 같습니다.'),
(22834, 1, 0, '침입자여, 이세라 님의 영역에서 뭘 하는 거지? 우리를 떠나게! 이곳은 그대 종족을 환영하지 않아!'),
(22834, 2, 0, '%s|1이;가; 발꿈치를 딛고 서서 주위를 둘러봅니다.'),
(22834, 3, 0, '그대는... 저들과 한패가 아니로군! 놈들이 우릴 발각하기 전에 어서 벗어나자고! 서두르게!'),
(22834, 4, 0, '$r|1이여;여;, 놈들이 날 쫓고 있어! 놈들에게 발각되기 전에 이곳에 왜 왔는지부터 말하게! 놈들이 날 잡으면, 나와 그대는 끝장이란 말이야!'),
(22844, 0, 0, '%s|1이;가; 격노합니다!'),
(22871, 0, 0, '그래, 내가 시초였다... 죽음의 수레바퀴가 수도 없이 돌았지. 참으로 오랜 세월이 흘렀어... 끝내야 할 일이 너무 많다.'),
(22871, 1, 0, '복수는 나의 것이다!'),
(22871, 2, 0, '쓸모가 있을 듯하군...'),
(22871, 2, 1, '악순환만 되풀이되리라.'),
(22871, 3, 0, '무얼 두려워하느냐?'),
(22871, 3, 1, '죽음이란 게... 꼭 나쁜 일만은 아니야...'),
(22871, 4, 0, '굴복하라.'),
(22871, 4, 1, '특별한 선물이다.'),
(22871, 5, 0, '제대로 경의를 표하란 말이다!'),
(22871, 6, 0, '또다시 운명의... 바퀴가... 도는구나...'),
(22887, 0, 0, '여군주 바쉬의 이름으로 사형에 처하노라!'),
(22887, 1, 0, '못 벗어난다!'),
(22887, 1, 1, '넌 나중에 처리해주마.'),
(22887, 2, 0, '덧없는 성공도 끝인 줄 알아라!'),
(22887, 2, 1, '작별을 고할 시간이로군.'),
(22887, 3, 0, '벨라넨 달로라이!'),
(22887, 3, 1, '피가... 강을... 이루리라!'),
(22887, 4, 0, '발, 라메 지타!'),
(22887, 5, 0, '인내심의 한계로구나! 죽어라, 죽어!'),
(22887, 6, 0, '일리단... 경께서... 갚아... 주시리라!'),
(22898, 0, 0, '궁극의 심연이 새로운 대상을 포착했습니다!'),
(22898, 1, 0, '궁극의 심연이 분노하여 땅을 내리찍습니다!'),
(22898, 2, 0, '땅이 갈라져서 열리기 시작합니다!'),
(22911, 0, 0, '감히 네 녀석이 날 소환한 것이냐?'),
(22911, 1, 0, '이제 내가 더 강해졌으니 널 쓰러뜨리고 말리라!'),
(22916, 0, 0, '루로사, 아비아나의 유물은 $n의 손에 맡겨서 모르디스 위스퍼윙에게 전하면 될 거야. 나는 당장 에메랄드의 꿈으로 돌아가야만 하네. $n|1이;가; 실패하지 않도록 잘 인도해 주게.'),
(22917, 0, 0, '부하들아, 이 반역자에게 응당한 처벌을 내려라!'),
(22917, 1, 0, '누가 또 이 칼날 맛을 보고 싶은 거냐?'),
(22917, 1, 1, '너무 쉽구나!'),
(22917, 2, 0, '어찌 감히 날 건드리려 하느냐!'),
(22917, 3, 0, '보라, 아지노스의 불꽃을!'),
(22917, 4, 0, '배신자의 눈을 똑바로 쳐다봐라!'),
(22917, 5, 0, '내 안에 깃든... 악마의 힘을 보여주마!'),
(22917, 6, 0, '시간을 너무 오래 끌었군. 이제 끝을 보겠다.'),
(22917, 7, 0, '네 증오가 느껴지는구나.'),
(22917, 7, 1, '공포에 굴복하라!'),
(22917, 7, 2, '진정한 힘에 무지한 족속들이여!'),
(22917, 7, 3, '건방진 놈!'),
(22917, 8, 0, '아카마, 너의 불충은 그리 놀랍지도 않구나. 너희 흉측한 형제들을 벌써 오래전에 없애버렸어야 했는데...'),
(22917, 9, 0, '입을 잘도 놀리는구나. 허나, 가당치도 않다!'),
(22917, 10, 0, '너흰 아직 준비가 안 됐다!'),
(22917, 11, 0, '필멸의 종족들이여, 나에 대한 증오가 고작 이 정도냐?'),
(22917, 12, 0, '마이에브... 어떻게 이런 일이...?'),
(22917, 13, 0, '만 년 동안 응어리진 증오를 보여주마!'),
(22917, 14, 0, '네가 이겼다... 마이에브. 하지만, 사냥감이 없는 사냥꾼은... 살아갈 힘을 잃는 법... 너도... 내가 없으면... 아무것도 아니야...'),
(22935, 0, 0, '경비병!'),
(22936, 0, 0, '경비병!'),
(22940, 0, 0, '그록은 도움이 필요한데... 왜 아무도 안 도와주는 거야?!'),
(22940, 0, 1, '아무도 안 도와주면 그록 여기서 난장판 만들 거야!'),
(22940, 1, 0, '난쟁이들아, 아무도 칼날 산맥으로 가서 모그도그를 도와주지 않으면 그록 정말 화낸다!'),
(22940, 1, 1, '칼날첨탑 일족은 정정당당하게 싸우지 않는다. 그들을 도와주는 그론 있지. 너 칼날 산맥으로 가라. 주름투성이 모그도그와 얘기해라. 그론 죽여라.'),
(22940, 1, 2, '주름투성이 모그도그가 그록한테 도시로 가라고 했다. 피망치 일족을 도와줄 착한 종족을 찾아보라고. 그래서 그록 여기 왔다.'),
(22940, 2, 0, '나 배고프다. 과일이 맛나 보이는군.'),
(22948, 0, 0, '호드가... 박살내주마.'),
(22948, 1, 0, '죽음의 향연이다!'),
(22948, 1, 1, '더 많이! 더 많이 오너라!'),
(22948, 2, 0, '각오 단단히 해라!'),
(22948, 2, 1, '힘이 고프다!'),
(22948, 3, 0, '으아아! 모두 다 쓸어주마!'),
(22949, 0, 0, '이깟 놈들이나 상대해야 하다니...'),
(22949, 1, 0, '게임은 끝났다!'),
(22949, 2, 0, '마지막 순간이니 실컷 즐겨라.'),
(22949, 3, 0, '넌 내 것이다!'),
(22949, 4, 0, '셀라마 아모로노르!'),
(22949, 5, 0, '잘했다!'),
(22949, 6, 0, '일리단경이시여, 저는...'),
(22950, 0, 0, '수준 낮은 언어를 쓰는 족속이로군. 반달!'),
(22950, 1, 0, '샬모르 시나바날!'),
(22950, 2, 0, '디엘 피날.'),
(22950, 3, 0, '샤아무르 아라 마샬?'),
(22950, 4, 0, '쇼렐러란.'),
(22950, 5, 0, '벨레사 멘노르!'),
(22950, 6, 0, '디엘 마안... 오린델로.'),
(22951, 5, 0, '이래야지.'),
(22952, 0, 0, '날 시험하겠다고?'),
(22952, 1, 0, '날 없애겠다고? 하하하! 너희가 먼저다!'),
(22952, 2, 0, '이런 대접도 아까운 놈들!'),
(22952, 3, 0, '아나랄라 벨로레!'),
(22952, 4, 0, '용기는 가상하군.'),
(22952, 5, 0, '영웅적인 업적이로다!'),
(22952, 6, 0, '운 좋은 줄... 알아라.'),
(22990, 0, 0, '어둠에서 빠져 나와라! 우리의 진정한 적을 물리치기 위해 내가 너희를 다시 이끈다! 쇠사슬을 벗어 던져라! 무기를 들고 일리다리 놈들에 맞서라!'),
(22990, 1, 0, '오래 버티진 못하겠다.'),
(22990, 2, 0, '아직은 안 돼!'),
(22992, 0, 0, '어리석은 자여, 결코 참매의 정수가 네 손안에 들어가는 일은 없을 것이다!'),
(22992, 1, 0, '까마귀 신의 시대가 도래했도다. 네놈들의 시대는 여기까지다!'),
(22993, 0, 0, '감히 네가 까마귀 신의 충성스러운 신도들을 방해하느냐?'),
(22993, 1, 0, '$c|1이여;여;, 그 자만심이 죽음을 재촉하리라!'),
(22994, 0, 0, '수리매는 쓰러졌다. 다시는 날아오르지 못할 것이다! 헛된 임무는 일찌감치 포기해라!'),
(22994, 1, 0, '예언의 계시대로 까마귀 신은 반드시 재림하실 것이노라. 네놈에게 미래를 거스를 힘은 없어!'),
(22997, 0, 0, '%s|1이;가; $n|1을;를; 노려봅니다!'),
(23002, 1, 0, '진정하라고!'),
(23035, 0, 0, '일어나라, 내 아이들아. 너의 주인을 도와라!'),
(23035, 1, 0, '네 약해 빠진... 케 코우... 마력 쯤은... 얼마든지 되돌려 주마...'),
(23035, 1, 1, '그래... 그 대단한 주문을 한번 외워 보거라, 아카아악!'),
(23049, 0, 0, '광폭 태세를 갖춰라! 저들을 무자비하게 공격하라!'),
(23083, 0, 0, '%s|1이;가; 격노합니다!'),
(23089, 0, 0, '조심하시오, 친구들. 배신자가 코앞에서 명상을 취하고 있으니...'),
(23089, 1, 0, '이놈들은 내가 처리하겠소! 친구들, 어서 배신자를 공격하시오!'),
(23089, 2, 0, '일리단! 너의 통치를 종식시키기 위해 우리가 왔다! 우리 종족은 물론 아웃랜드 전체를 해방시키리라!'),
(23089, 3, 0, '때가 왔다. 기다리던 순간이!'),
(23089, 4, 0, '성스러운 축복의 빛이 이 음산한 전당에 다시 한번 내리쬐리라.'),
(23139, 0, 0, '이리 오게, $n. 군주님께서 기다리시네.'),
(23139, 1, 0, '일리단 님께서 곧 도착할 것이네.'),
(23139, 3, 0, '군주님이시여... 저는 이해를 하지 못하겠습니다. 이 오크는...'),
(23139, 4, 0, '분부대로 하겠습니다.'),
(23139, 5, 0, '그래, 네놈이 모르고르를 속이려고 했단 말이구나, 그렇지? 일리단 님께 가기 전에 살아서는 구경도 못할 고통을 선사해주마. 기꺼이 내가 당한 복수를 해 주지.'),
(23139, 6, 0, '용아귀 부족의 용사들이여, 모두 모여라! 너희 중 한 용사가 군주가 되었다! 고개를 숙여 경의를 표하라! 너희의 군주이신 $n 님께 존경과 충성을 바치거라!'),
(23139, 7, 0, '모두 일리단 님을 맞이하라!'),
(23141, 0, 0, '그를 해치지 못할 걸, 모르고르! $n, 서둘러 등에 오르게나!'),
(23162, 0, 0, '바키즈가 위협적으로 당신을 향해 몸을 비틀자, 무서운 바람이 바키즈를 감쌉니다.'),
(23162, 1, 0, '무시무시한 분노에 쌓인 %s의 몸이 산산이 부서집니다!'),
(23163, 0, 0, '%s|1이;가; 송곳니를 드러내고 날카로운 소리를 내면서 주변을 위협합니다.'),
(23163, 1, 0, '%s|1이;가; $n에 집중합니다.'),
(23191, 0, 0, '뒤틀린 잿빛혓바닥일족이여, 너희의 지도자가 말하노라!'),
(23191, 1, 0, '그 배신자는 더 이상 우리를 지배하지 못한다. 잿빛혓바닥일족의 영혼을 지배하던 검은 마법의 힘이 파괴된 것이다!'),
(23191, 2, 0, '어둠에서 빠져 나와라! 우리의 진정한 적을 물리치기 위해 내가 너희를 다시 이끈다! 쇠사슬을 벗어 던져라! 무기를 들고 일리다리 놈들에 맞서라!'),
(23196, 0, 0, '%s|1이;가; 격노합니다!'),
(23222, 0, 0, '%s|1이;가; 격노합니다!'),
(23224, 0, 1, '그럼요. 제가 관여하지 않는다면요.'),
(23224, 0, 2, '내일과 다음 10년 사이에 일어날 일 같아요. 분명해요.'),
(23224, 0, 3, '좋아 보이네요... 저한텐 안 좋은 거 같지만.'),
(23224, 0, 4, '동료 임프들에게 의견을 물어봤는데요, 한 친구만 빼곤 다 긍정적이네요.'),
(23224, 0, 5, '전망은 좋지만 전 아직 부정적이랍니다.'),
(23224, 0, 6, '이렇게 말하긴 가슴 아프지만... 대답은 ''네''랍니다.'),
(23224, 0, 7, '드워프가 맥주 마다하는 거 보셨나요? 보셨다고요? 그럼 ''네''라고 해드리죠!'),
(23224, 0, 8, '당연히 그렇게 되죠. 하지만, 그다지 유쾌한 결과는 아닐 걸요.'),
(23224, 0, 9, '$r, 주위에서 보고 듣는 거 말하지 마라.'),
(23224, 0, 10, '안타깝게도... 그렇네요.'),
(23224, 0, 11, '안 될 거 없지요, 하지만 지금 당장은 많은 걸 볼 순 없네요.'),
(23224, 0, 12, '당신 영혼을 내기에 걸겠어요.'),
(23224, 0, 13, '그럼요, 하지만 다른 사람들이 물으면요... 제가 말했다고 하지 마세요.'),
(23224, 0, 14, '전에 물어보지 않았어요? 이미 ''네''라고 대답했잖아요!'),
(23224, 0, 15, '제발요... 킬제덴이 빨간색인가요?'),
(23224, 0, 16, '네네, 물론이죠. 계속 그렇게 생각하세요.'),
(23224, 0, 17, '그렇겠죠.'),
(23224, 0, 18, '물론이죠.'),
(23224, 0, 19, '3번 뛰고 10분 동안 춤을 추면 분명히 일어날 거예요!'),
(23224, 0, 20, '네! 반도를 걸어도 좋아요!'),
(23224, 0, 21, '오, 그거야 물론이죠.'),
(23224, 0, 22, '네, 하지만 당신이 생각하는 그런 방식은 아니에요.'),
(23224, 0, 23, '네, 그렇다고요. 천 번도 더 말한 거 같은데!'),
(23224, 0, 24, '그래, 당신 소원대로 돼요. 그러니까 그만 좀 들볶으라고요!'),
(23224, 0, 25, '여기서 나가게 해 준다면 대답은 ''네''랍니다.'),
(23224, 0, 26, '내 등에 난 종기들만큼이나 확실해요!'),
(23224, 0, 27, '이 안에서 대답은 ''네''랍니다. 바깥이라도 다른 대답이 나올 리는 없겠죠.'),
(23224, 0, 28, '세 단어로 하죠. 그-래-요!'),
(23224, 0, 29, '네, 하지만 그 질문에 대답하는 일은 없길 바랐는데...'),
(23224, 0, 30, '나중에 다시 물어보세요. 코를 긁는 중이라 집중하기가 어렵네요.'),
(23224, 0, 31, '제가 왜 대답해야 하지요? 당신은 사람들이 당신을 막 흔들면 운세를 점쳐주나요?'),
(23224, 0, 32, '네, 비가 오겠네요. 아, 그런 건 안 물어봤다고요? 안됐네요!'),
(23224, 0, 33, '미안하지만, 전 악마어로만 얘기할 수 있어요.'),
(23224, 0, 34, '네! 아, 제 말은 아니라고요! 아, 어떤 답을 해야 제가 여기서 벗어날 수 있죠?'),
(23224, 0, 35, '네, 아니요, 아마 그럴 테죠.'),
(23224, 0, 36, '당신은 내일 죽을 테니 상관없겠네요.'),
(23224, 0, 37, '이렇게 물어봤어야죠, "절 죽이려고 제 뒤에 도적이 숨어 있나요?"'),
(23224, 0, 38, '재사용 대기시간이 더 길었으면 하는 그런 때이네요.'),
(23224, 0, 39, '%s|1이;가; 누가 알겠냐는 듯 어깨를 으쓱합니다.'),
(23224, 0, 40, '우리 엄마는 항상 이렇게 말씀하시죠. [악마어] "라지스 크하지 쥐하쉬스애쉬스."'),
(23224, 0, 41, '%s|1이;가; 당신을 나 몰라라 합니다.'),
(23224, 0, 42, '왜 저죠? 왜 고블린이나 노움이 아니고...'),
(23224, 0, 43, '뒤틀린 황천에서 일어난 일은 뒤틀린 황천에 묻고 가세요.'),
(23224, 0, 44, '별 필요 없는 도박은 피하도록 하세요. 당신의 운명의 숫자는 2, 2의 반 그리고 11이랍니다.'),
(23224, 0, 45, '알고 싶지 않나 보죠?'),
(23224, 0, 46, '오, 오, 오! 이번 건 분명하게 보이네요... 앗, 없어졌어요.'),
(23224, 0, 47, '내 계약엔 이런 건 없었어요!'),
(23224, 0, 48, '즈라 락히 마지즈라!'),
(23224, 0, 50, '절 놀리는 건가요?'),
(23224, 0, 51, '제가 어떤 임프라고 생각하는거죠?'),
(23224, 0, 52, '제발이라고 해야죠?'),
(23224, 0, 53, '저랑 자릴 바꾸고 싶으세요?'),
(23224, 0, 54, '구슬 속에 갇혀 있기만 하다면 누구한테든 이런 걸 물어보나요?'),
(23224, 0, 55, '이봐요! 당신 집을 난장판으로 만들 머저리랑 집 정리를 하는 꼴이라고요!'),
(23224, 0, 56, '가능하게 해드릴게요. 점선 아래에 서명만 해주세요...'),
(23224, 0, 57, '애매하고 살짝 음습한 대답밖에 안 나와요. 잘 말려서 다시 시도해 보시던가요.'),
(23224, 0, 58, '저를 이 지옥의 감옥에서 풀어주는 데 집중해서 다시 시도해 보세요.'),
(23224, 0, 59, '25 실버를 넣고 다시 시도해 주세요.'),
(23224, 0, 60, '대니, 내 친구 맞죠?'),
(23224, 0, 61, '머리에 땜빵 내던 그 시절을 기억하세요?'),
(23224, 0, 62, '오, 좋은 자세군요. 뭐, 스스로 운명을 개척할 필요 있나요?'),
(23224, 0, 63, '한 마디로 말해서 불가능해요!'),
(23224, 0, 64, '당신에겐 신비한 지능이 필요해요, 왜냐하면 답은 분명히 ''아니요!''거든요.'),
(23224, 0, 65, '당신 생에서는 안 돼요!'),
(23224, 0, 66, '운명을 볼 줄 아는 임프가 아니라도 그 질문의 답은 ''절대 안 돼!''라고 할 걸요!'),
(23224, 0, 67, '32.33333333 퍼센트의 성공 가능성이 있어요.'),
(23224, 0, 68, '검은바위가 다 녹아버릴 때요!'),
(23224, 0, 69, '하하하하하하, 지금 농담하는 거죠?'),
(23224, 0, 70, '믿을 수가 없군!'),
(23224, 0, 71, '대답은 ''아니요''랍니다. 다른 대답을 원하면 절 고문하시던가요.'),
(23224, 0, 72, '실현 가능성은... 제가 이 구슬에서 나갈 확률 정도?'),
(23224, 0, 73, '오늘 저를 흔드는 시간을 잘못 골랐어요! 풀 죽을 준비나 하시라고요.'),
(23224, 0, 74, '당신이 대단한 친구라도 된다면 모를까... 아, 그리고 자신을 속이지 마세요. 당신은 대단하지 않아요.'),
(23224, 0, 75, '실현 가능성은... 제가 서큐버스 양과 데이트를 할 확률 정도?'),
(23224, 0, 76, '제 운세 점치기 실력은 대단하답니다. 그래도 당신은 기회가 없다네요.'),
(23224, 0, 77, '아니요. 더 좋은 운세를 얻겠다고 절 흔들려고 하진 마세요!'),
(23224, 0, 78, '제 대답은 ''네''랍니다...'),
(23224, 0, 79, '... 아니요!'),
(23224, 0, 80, '아!니!요!라는 대답을 드리려고 해요.'),
(23224, 0, 81, '당신에겐 전망이 매우 좋지 않네요! 하하, 순순히 받아들이라고요!'),
(23224, 0, 82, '설문 결과는 이렇네요. 삐!'),
(23237, 0, 0, '%s|1이;가; 격노합니다!'),
(23239, 0, 0, '%s|1이;가; 격노합니다!'),
(23282, 0, 0, '오늘 밤 오우거와 $r의 살을 마음껏 즐기리라.'),
(23311, 0, 0, '아으윽! 부메랑!'),
(23311, 0, 1, '아야아야! 언젠가 나 저 부메랑 갖는다...'),
(23311, 0, 2, '그만! 부메랑 그만 던지라고! 나 미안해! 나 일한다!'),
(23311, 0, 3, '아악! 부메랑이 나 아프게 한다! 부메랑보다 일이 더 낫군!'),
(23311, 0, 4, '아으으으윽! 알았다, 알았어, 나 일 다시 한다!'),
(23311, 0, 5, '왜 부메랑으로 나 때리는 거지?? 왜??'),
(23311, 0, 6, '넌 나쁜 오크야... 나아쁜... 으아악!'),
(23319, 0, 0, '우리의 지도자에게 영광을! 아카마 만세!'),
(23319, 1, 0, '아카마 만세!'),
(23364, 0, 0, '%s|1이;가; 엄마를 찾으며 울부짖습니다.'),
(23377, 0, 0, '적이 포착되었다! 대형을 갖추고 폭격 준비를 하라!'),
(23377, 1, 0, '서둘러라! 불길로 지상군을 지원하라. 그 고대의 마법으로 테로크의 보호막을 제거해야 한다.'),
(23377, 2, 0, '해냈군! 적들을 물리쳤어! 모두 기지로 귀환하라!'),
(23418, 0, 0, '너희를 기다리는 건 고통과 슬픔뿐이야!'),
(23418, 1, 0, '날 혼자 두고 가지마!'),
(23418, 2, 0, '일부러 그런 건 아니야!'),
(23418, 2, 1, '이러고 싶지는 않았어!'),
(23418, 2, 2, '고통은 이제 시작일 뿐!'),
(23418, 3, 0, '나 안 돌아갈래!'),
(23418, 4, 0, '이제 어쩌면 좋지?'),
(23418, 5, 0, '%s|1이;가; 격노합니다!'),
(23420, 0, 0, '각오해라. 내가 살아났다!'),
(23420, 0, 1, '너무... 어리석군.'),
(23420, 1, 0, '너무... 어리석군.'),
(23420, 1, 1, '딱 좋아, 이만 하면 됐어!'),
(23420, 2, 0, '무릎을 꿇어라!'),
(23420, 3, 0, '두고 보자, 겁쟁이들!'),
(23420, 4, 0, '날... 무시하지... 마라!'),
(23439, 0, 0, '%s|1이;가; 막 죽은 차원의 추격자를 먹습니다.'),
(23543, 0, 0, '각오해라. 종은 이미 울렸다! 병자와 노인과 어린 아이들을 숨겨라! 너희 모두 죗값을 치를 테니! 자비를 구해라! 심판의 날이 다가왔다!'),
(23543, 1, 0, '활활 타오르는구나! 너는 실패했다. 정의가 승리했도다!'),
(23543, 2, 0, '내 불꽃은 흔적조차 남지 않았구나. 죽음의 암흑이여, 내가 너에게 가노라.'),
(23543, 3, 0, '하늘이 어둡구나. 불길이 솟구친다. 운명의 수레바퀴 안에서 네 수고는 무익하도다.'),
(23543, 4, 0, '정화의 불꽃이여, 활활 불타는구나! 시간이 없도다! 나는 곧 물러나리니...'),
(23543, 5, 0, '내 피를 보려고 기를 쓰는구나! 하지만, 아직 멀었다... 네 녀석이 없애야 할 건, 내 머리다!'),
(23557, 0, 0, '무릎 꿇고 경배하라... 송곳니와 발톱에!'),
(23557, 1, 0, '산산조각 내 주마!'),
(23557, 1, 1, '깨끗이 베어 주마!'),
(23557, 2, 0, '깨끗이 베어 주마!'),
(23557, 3, 0, '혼이여, 이리 돌아오라!'),
(23557, 4, 0, '너흰 너무 약해!'),
(23557, 4, 1, '모두 처치해 주마!'),
(23557, 5, 0, '차가... 초카진...'),
(23557, 6, 0, '뭐 하는 거냐? 겁에 질려 오줌이라도 지렸나...'),
(23564, 0, 0, '%s|1이;가; 자신을 주체하지 못하고 적이든 아군이든 닥치는 대로 공격하기 시작합니다!'),
(23567, 0, 0, '알 수 없는 발굽 자국에, 검게 그을린 방패, 휘장은 떨어져 있고... 이 모든 현상을 어떻게 이해해야 하겠습니까?'),
(23574, 0, 0, '나는 사냥꾼이다! 너흰 먹잇감이고...'),
(23574, 1, 0, '먹어라, 형제들아!'),
(23574, 2, 0, '징징대지 마라!'),
(23574, 2, 1, '꺼져버려!'),
(23574, 3, 0, '내 영혼까지... 죽이지는... 못해!'),
(23576, 0, 0, '움직여라, 경비병들! 신나게 썰어 봐라!'),
(23576, 1, 0, '어서 가란 말이다! 누가 더 무섭나, 응? 저들인가? 나인가...'),
(23576, 2, 0, '어서 가라! 가서 녀석들을 처치하고 그 증거를 가져와라!'),
(23576, 3, 0, '인내심에 한계가 온다! 계속해라. 태어난 것을 후회하게 해 줘라!'),
(23576, 4, 0, '저승으로 보내 주마!'),
(23576, 4, 1, '아마니 제국이 다시 지배하리라!'),
(23576, 5, 0, '고통을 안겨주마!'),
(23576, 6, 0, '너희들이 짐승을 불러냈다. 놀랄 준비나 해라!'),
(23576, 7, 0, '날로라크 나가신다!'),
(23576, 8, 0, '이제 뭐라 할 테냐, 응?'),
(23576, 9, 0, '나... 다른 세상에서 기다리겠다...'),
(23577, 0, 0, '무릎 꿇고 경배하라... 송곳니와 발톱에!'),
(23577, 1, 0, '야생의 혼이 내 편이다...'),
(23577, 2, 0, '혼이여, 이리 돌아오라!'),
(23577, 3, 0, '깨끗이 베어 주마!'),
(23577, 3, 1, '산산조각 내 주마!'),
(23577, 4, 0, '차가... 초카진...'),
(23578, 0, 0, '바람의 혼이 너희를 쓸어내리라!'),
(23578, 1, 0, '태워버리겠다!'),
(23578, 2, 0, '다 어디 갔지? 당장 알을 부화시켜!'),
(23578, 3, 0, '힘을 보여주마... 한꺼번에.'),
(23578, 4, 0, '네놈들은 이제 끝이다!'),
(23578, 5, 0, '타자가 추!'),
(23579, 0, 0, '브록 여기서 지내도 된다고 네가 말했다! 돌망치 일족 땅 다시 찾게 도와준다고 너 브록한테 약속했다!'),
(23579, 1, 0, '그래도 브록에게 맞는 집 여기밖에 없다! 고블린은 집 너무 작게 만든다!!'),
(23586, 0, 0, '침입자다! 경보를 울려라!'),
(23597, 0, 0, '침입자다! 경보를 울려라!'),
(23597, 1, 0, '%s|1이;가; 격노합니다!'),
(23602, 0, 0, '자네가 긍지를 갖고 테라모어를 지키는 걸 보니 기쁘군, 친구.'),
(23602, 0, 1, '비번일 때 함께 여관에 가세. 내가 한잔 살 테니. 좋았던 옛날 얘기나 나눠 보세나.'),
(23602, 0, 2, '자네, 옛 영광을 되돌리고 싶다는 생각이 들지는 않나? 내 친구들이 그렇게 할 방도를 아는데 말이야...'),
(23602, 1, 0, '여기 있는 모든 이는 프라우드무어 제독님이 진정한 영웅이셨다는 걸 알게 될 것이다!'),
(23602, 1, 1, '방해해 봤자 소용없다! 제이나가 얼마나 비겁한지 우리가 세상에 알리고 말 테다!'),
(23602, 1, 2, '우리를 막을 수 있다고 생각했다면 큰 오산이다, ''친구''.'),
(23602, 1, 3, '바로 너 같은 녀석들 때문에 얼라이언스가 약해지고, 우리가 열심히 싸워서 지켜 온 것들을 호드한테 빼앗긴 거야!'),
