(23675, 0, 2, '당신 같은 친구는 처음 보는데...'),
(23675, 0, 3, '기다려라! 멈춰!'),
(23675, 0, 4, '정지!! 정지!! 이젠 고철들이 저절로 움직이나?'),
(23675, 1, 0, '그래... 미안하군. 어디까지 얘기했지?'),
(23675, 1, 1, '모두 위대한 창조자를 맞이하라!'),
(23675, 1, 2, '물론 그 말이 맞아. 계속하지.'),
(23675, 1, 3, '무례를 용서하시오!'),
(23675, 1, 4, '두 배로 일해야겠군!'),
