(23675, 2, 1, '틀렸어!'),
(23682, 0, 0, '다 끝이다. 더 찾을 필요는 없다. 이제 운명에 묻자. 누가 정의로운지를...'),
(23682, 1, 0, '완전하고 순수한 내 몸이여! 이제 더럽혀진 네 영혼을 치유하리라!'),
(23682, 2, 0, '들어라, 비겁자여! 일격에 널 끝내리니! 이제 뜨거운 맛을 봐라!'),
(23682, 3, 0, '일어나라, 병사들이여. 나가서 싸워라! 이 쇠락한 기사에게 승리를 안겨다오!'),
(23682, 4, 0, '너의 몸은 망가지고 으스러져 만신창이가 되었구나! 나의 저주가 곧 너의 저주가 되리니, 이제는 되돌릴 길이 없도다!'),
(23682, 4, 1, '이 멍청한 몸뚱이야, 난 이쪽에 있다!'),
(23682, 5, 0, '죽음은 이미 겪어 보았노라. 이제 어떤 모험이 날 기다리는가?'),
(23683, 0, 0, '이리 와서 발리브루의 흑맥주를 드셔보시죠!'),
(23683, 0, 1, '발리브루는 아제로스 최고의 양조장이죠!'),
(23683, 0, 2, '발리브루는 양조계의 기술 혁신을 이끌어 왔습니다. 발리브루의 신상품 청맥주를 드셔보시죠!'),
(23683, 1, 0, '누가 이 특제 맥주잔도 던지십시오!!'),
(23683, 2, 0, '마시고 던져라! 던지고 마셔라!'),
(23683, 2, 1, '공짜로 받은 맥주는 마셔 버리고 험상궂은 선술집 녀석들에게 맥주잔을 던지십시오!'),
(23684, 0, 0, '썬더브루는 양조 업계에서 최고지.'),
(23684, 0, 1, '썬더! 썬더! 썬더! 썬더브루, 야호!'),
(23684, 0, 2, '시원한 게 필요한 모양인데, 썬더브루가 시원하게 목을 축여 주지!'),
(23684, 1, 0, '누가 이 특제 맥주잔도 던지십시오!!'),
(23684, 2, 0, '마시고 던져라! 던지고 마셔라!'),
(23684, 2, 1, '공짜로 받은 맥주는 마셔 버리고 험상궂은 선술집 녀석들에게 맥주잔을 던지십시오!'),
(23685, 0, 0, '너 술 마시고 싶지?! 우리한테 술 있다!'),
(23685, 0, 1, '이봐 너! 오우거 맥주 마셔라! 크고 힘 세진다!'),
(23685, 0, 2, '맛을 봤으면 전부 마셔야지! 오우거 맥주!!'),
(23698, 0, 0, '아, 안 돼...'),
(23698, 0, 1, '즐거운 시간 보내라고! <딸꾹!>'),
(23698, 0, 2, '여기 이게 다 웬 야단법석이지?'),
(23698, 0, 3, '술을 마시는 데 있어서 가좡 중요한 건 말이야... 술 취한 척하는 거라고... 딸꾹... 난 그냥 남자인 척 하는거고... 꺼억...'),
(23698, 0, 4, '딸꾹... 여어, 췬구들! 잘 지냈나?'),
(23698, 0, 5, '이봐! 누가 예쁜 금봘 드워프 아가씨 봤나? 분명히 방금 여기 있었다고... 딸꾹...'),
(23698, 0, 6, '이보라고! 내 말 좀 들어봐! 내가 말이지... 중요하게 할 얘기가 있단 말이야! 쉿... 좀 기다려보라고... 꺼억... 내가 무슨 말을 했더라? 배하고 뭐 떠다니는 거였는데... 딸꾹... 맞아! 그러니까 배를 띄우지 말라고... 딸꾹... 그래, 고맙다고... 꺼억...'),
(23698, 1, 0, '아, 안 돼...'),
(23698, 1, 1, '즐거운 시간 보내라고! <딸꾹!>'),
(23698, 1, 2, '여기 이게 다 웬 야단법석이지?'),
(23698, 1, 3, '술을 마시는 데 있어서 가좡 중요한 건 말이야... 술 취한 척하는 거라고... 딸꾹... 난 그냥 남자인 척 하는거고... 꺼억...'),
(23698, 1, 4, '이거 정말 해봐야 한다니까 그러네... 딸꾹...'),
(23698, 1, 5, '이봐! 당신 호드야? <딸꾹> 나도 호드야!'),
(23709, 0, 0, '누가 "맥주는 공짜"라고 그러지 않았어?'),
(23709, 0, 1, '꿀꺽꿀꺽! 얼씨구! 꿀꺽꿀꺽! 절씨구!'),
(23709, 0, 2, '쭉 들이켜라고, 친구들!'),
