(23782, 0, 0, '적 함대를 상대로 실험했던 결과 보고서가 들어왔습니다!'),
(23782, 1, 0, '저기... 좋은 소식은 우리가 증원군을 물리쳤다는 것입니다.'),
(23782, 2, 0, '역병이 그다지... 치명적이지 않았습니다. 하지만 메스꺼움, 불안감, 심한 복통 같은 증상을 유발했다고 보고되었습니다.'),
(23782, 3, 0, '네, 알겠습니다!'),
(23786, 0, 0, '왜 영혼 깨웠어? 다른 돌망치 일족 어디 있지?'),
