(23786, 1, 1, '우어어!!! 나 $r 죽일거야!'),
(23837, 0, 0, '얼음왕관에서 벌어지는 여러 대수롭지 않은 일들을 점치던 중, 무언가 흥미로운 것을 발견합니다...'),
(23837, 1, 0, '뒤에서 뭔가 소리가 들립니다!'),
