(23859, 0, 0, '경비병!'),
(23861, 0, 0, '가버리십시오, 당신이 누구든 간에! 마녀 언덕은 내 겁니다... 내 거요!'),
(23861, 0, 1, '이미 늦어서 자를도 가망이 없습니다... 너무나 강력한 힘에 붙들려 있기 때문에...'),
(23861, 0, 2, '저희는 틀렸습니다, 생명이 있으신 분이여. 어서 친구와 함께 여기를 벗어나십시오... 둘 다 목숨을 잃기 전에...'),
(23861, 0, 3, '그 녀석은... 끔찍한... 악마였습니다...'),
