(23861, 0, 5, '그 영지는... 누군가 다른 사람까지... 곧 타버릴 겁니다...'),
(23861, 0, 6, '암흑... 부패... 이 모두가 아무도 눈치를 못 챌 만큼 빠르게 들이닥쳤습니다.'),
(23861, 0, 7, '왜 여기에 왔습니까, 이방인이여? 고통만이 있을 뿐인데! 당신도 우리와 같은 운명에 놓일 겁니다...'),
(23863, 0, 0, '오호, 난 새로운 기술을 익혔지... 내 형제, 곰처럼...'),
(23863, 1, 0, '내가 쓰러져도... 우리 아마니 제국은... 절대로 사라지지 않는다.'),
(23863, 2, 0, '용매를 하늘에서만 찾을 필요는 없다!'),
(23863, 3, 0, '독수리의 눈을 피할 수는 없다!'),
(23863, 4, 0, '불길로 너희를 끝장내 주마!'),
(23863, 5, 0, '다 아마니 디 츄카!'),
(23863, 5, 1, '더 많은 놈들이 너처럼 쓰러지리라.'),
(23863, 5, 2, '이것 봐라... 끝났잖아?'),
(23863, 6, 0, '오, 내 새로운 형제, 송곳니와 발톱을 보아라!'),
(23863, 7, 0, '잔달라가 우릴 돕는다. 이제 누구도 아마니를 괴롭히지 못해!'),
(23864, 0, 0, '그 가증스러운 발을 딛기 훨씬 전부터 이 땅은 내 것이었노라.'),
