(24014, 0, 7, '언제나 한 자리는 남아 있지.'),
(24014, 0, 8, '열매가 여물어 줄기에서 떨어졌군...'),
(24015, 0, 0, '제물이 제 발로 기어들어와? 정신이 나간 게냐?!'),
(24015, 0, 1, '감히 윈터스코른에 대적하겠다고?! 그 보잘것없는 깃발로 네 몸뚱이를 꿰어주마!'),
(24015, 0, 2, '네 녀석의 시체는 비수집 만에서 상어 밥이 될 것이다!'),
(24032, 0, 0, '경비병!'),
(24035, 0, 0, '희생된 친구들을 위해 복수해 주십시오!'),
(24035, 0, 1, '제물 따위가 되고 싶지 않아!'),
(24035, 0, 2, '저 지하묘지로 끌려가고 싶지 않단 말입니다!'),
(24035, 0, 3, '저 꼭대기의 샬레르브론 브리쿨 중 누군가 열쇠를 가진 걸 봤습니다.'),
(24035, 0, 4, '브리쿨 녀석들이 열쇠를 가진 걸 본 것 같습니다.'),
(24035, 0, 5, '나를 구해 줄 영웅은 없단 말인가?'),
(24035, 0, 6, '고맙습니다, 영웅이여!'),
(24035, 0, 7, '오, 고맙습니다! 고마워요!'),
(24035, 0, 8, '제발 여기서 꺼내 주십시오!'),
(24035, 0, 9, '고맙습니다! 여신께서 당신을 보살피기를!'),
(24035, 0, 10, '고맙습니다. 절대 잊지 않겠습니다!'),
(24035, 0, 11, '열쇠... 열쇠를 찾으십시오!'),
(24035, 0, 12, '브리쿨들은 악마입니다. 처치해야 합니다!'),
(24035, 0, 13, '저자들이 지하묘지에서 뭔가 부정한 의식을 진행하고 있어요. 그리고 제가 곧 제물로 바쳐질 겁니다!'),
(24035, 0, 14, '이제 끝이군.'),
(24035, 0, 15, '늦기 전에 이 미친 짓을 끝장내야 해요!'),
(24035, 0, 16, '당신이 제 목숨을 구했군요!'),
(24043, 0, 0, '한 생물이 암흑 속에서 빠져나와 그 모습을 드러냅니다!'),
(24052, 0, 0, '여기선 편자 같은 건 취급 안 합니다. 게다가 지금은 원정대 일만 맡게 되어 있어요.'),
(24052, 1, 0, '나랑은 상관없어요! 집을 못 지을까 봐 그렇게 안달복달이면 이 요새에다 집 짓고 들어가 사시던가!'),
(24052, 2, 0, '그럼, 이제 내 모루에서 당신 나귀 좀 치워주면 고맙겠습니다...'),
(24061, 0, 0, '경비병!'),
(24078, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(24120, 0, 0, '누가 저 박쥐 좀 쏴서 떨어트려!'),
(24120, 0, 1, '저 액체는 뭐지? 냄새가 고약해!'),
(24120, 0, 2, '속이 거북해...'),
(24120, 0, 3, '끔찍했습니다... 꿈에서 저는 친구들의 적이 되어 싸웠습니다.'),
(24120, 0, 4, '도와줘! 내 눈!'),
(24126, 0, 0, '좋아. 내용이 뭔가? 사망자 수는 집계되었나?'),
(24126, 1, 0, '아니, 왜 말을 못하나? 나쁜 소식은 뭔가?'),
(24126, 2, 0, '심한 복통?'),
(24126, 3, 0, '심한 복통이라고 했나?!'),
(24126, 4, 0, '우린 왕립 연금술 학회란 말이다! 고작 배탈 따위나 일으키는 게 우리의 임무라고 생각하나!'),
(24126, 5, 0, '여기는 덜떨어진 놈들만 있나? 내일 아침까지 새로운 역병 품종을 완벽하게 분석해서 보고하도록! 지금 당장 시작하게, 라비엔!'),
(24126, 6, 0, '언더시티에서는 역병 연구가 꽤 진척됐었지. 그런데 갑자기 우리가 만든 변종이 실험하는 족족 실패하지 뭔가!'),
(24126, 6, 1, '언더시티에서 마지막에 보낸 10가지 변종은... 전부 쓰레기야!'),
(24126, 6, 2, '이런 조건에서는 일 못하겠어! 쓸 만한 변종이 필요해!'),
(24152, 0, 0, '잠깐...'),
(24152, 1, 0, '이건 그냥...'),
(24152, 2, 0, '맥주! 흔해빠진 맥주잖아!'),
(24152, 3, 0, '특별한 점이라고는 눈꼽만큼도 없군.'),
(24152, 4, 0, '거기 당신! 그릭에게는 한마디도 하지 마시오! 알겠소?'),
(24155, 0, 0, '경비병!'),
(24175, 0, 0, '아킬존이시여, 침략자들이 다가옵니다!'),
(24177, 0, 1, '빛... 빛 너무 밝아...'),
(24177, 0, 2, '아아아아악...'),
(24177, 0, 3, '가... 저리 가...'),
(24177, 0, 4, '빛 나빠... 너무 아파...'),
(24177, 0, 5, '탄다! 타오른다!'),
(24177, 1, 1, '배... 배고파...'),
(24177, 1, 2, '와... 이리 와...'),
(24177, 1, 3, '먹을 거...'),
(24177, 1, 4, '먹이! 너 먹는다!'),
(24177, 1, 5, '뇌를 줘어어어어!'),
(24178, 0, 0, '%s|1이;가; 고기 냄새를 맡고 잠에서 깨어나 분노에 찬 포효를 내지릅니다!'),
(24199, 0, 0, '%s|1이;가; 자신을 주체하지 못하고 적이든 아군이든 닥치는 대로 공격하기 시작합니다!'),
(24200, 0, 0, '달론! 네 솜씨가 얼마나 좋은지 한번 보자!'),
(24200, 1, 0, '아직... 끝나지... 않았다.'),
(24200, 2, 0, '전사다운... 죽음을.'),
(24200, 3, 0, '얄겐 올트!'),
(24200, 4, 0, '하! 무슨 놈의 강령술사가 죽음 앞에 무릎을 꿇느냐? 무능한 녀석 같으니!'),
(24201, 0, 0, '시끄럽구나... 물에 빠져 죽으면 입만 동동 뜰 녀석 같으니! 가서 싸우기나 해!'),
(24201, 1, 0, '곧... 다시... 보자.'),
(24201, 2, 0, '이보다... 더한 명예는... 없으리라...'),
(24201, 3, 0, '날 섬길 때가 되었구나.'),
(24201, 4, 0, '스카발드, 이 무능한 놈 같으니! 돌아와라. 도움이 좀 돼 보란 말이다!'),
(24202, 0, 0, '이리 와서 발리브루의 흑맥주를 드셔보시죠!'),
(24202, 0, 1, '가발양 기획사를 눈여겨 봐주십시오! 가을 축제 발리브루 양조사들입니다!'),
(24202, 0, 2, '우리 발리브루가 발로 만들어도! 썬더브루보다는 나을 겁니다. 배부르지도 않고, 속 쓰리지도 않은 깔끔한 맛일 테니까요...'),
(24202, 0, 3, '여러분 입맛에 딱 맞는 건 발리브루입니다! 가을 축제에서 발리브루 맥주 맛을 꼭 확인하십시오!'),
(24202, 1, 0, '썬더브루는 양조 업계에서 최고지.'),
(24202, 1, 1, '가을 축제에서 천둥벼락이 치길 바라신 분들! 천둥벼락같이 화끈한 맛, 썬더브루가 바로 제격입니다!'),
(24202, 1, 2, '밋밋한 맥주 때문에 파티가 밋밋하십니까, 썬더브루가 해결해 드립니다! 가을 축제에 오셔서 썬더브루의 맛을 확인해 보십시오!'),
(24202, 1, 3, '신비한 마법을 맛보고 싶으십니까? 최고의 경지에 도달한 썬더브루 양조사들! 그들이 빚어낸 신비한 맛을 가을 축제에서 맛보십시오!'),
(24202, 2, 0, '제대로 놀 줄 안다면 드론의 양조장을 선택하셔야지요! 가을 축제에서 확인해 보십시오!'),
(24202, 2, 1, '진짜 좋은 술이 뭔지 제대로 아는 오크들과 가을 축제를 즐겨봅시다! 가을 축제에서 드론의 양주장에 꼭 들러 주십시오!'),
(24202, 2, 2, '오크가 한 방 날릴 줄 안다고 생각하셨다면, 오크 맥주도 드셔 보십시오. 더 강력한 한 방을 날려주니까요! 드론의 양조장에 오셔서 확인하십시오, 가을 축제에서만 만나실 수 있습니다!'),
(24202, 2, 3, '드론의 양조장으로 오셔서 형제자매 여러분과 함께 호드를 위하여 건배하십시오!'),
(24202, 3, 0, '정말로 오크나 오우거가 만든 맥주를 드시겠다는 겁니까? 가을 축제에서 촬리의 부두 양조장을 선택하신다면 후회하지 않으실 겁니다!'),
(24202, 3, 1, '이국적인 맛의 맥주를 즐기시는 분이라면, 가을 축제에서는 촬리의 부두 양조장 맥주가 제격입니다!'),
(24202, 3, 2, '긴장 한번 풀어보시렵니까? 가을 축제에 오셔서 촬리의 부두 양조장을 찾아주시면 부드럽게 넘어가는 맥주를 맛보실 수 있습니다!'),
(24202, 3, 3, '흥겨움이 넘치는 곳이라면 촬리의 부두 맥주가 어울리지요! 가을 축제에 오셔서 흥겨움을 만끽하십시오!'),
(24203, 0, 0, '이리 와서 발리브루의 흑맥주를 드셔보시죠!'),
(24203, 0, 1, '가발양 기획사를 눈여겨 봐주십시오! 가을 축제 발리브루 양조사들입니다!'),
(24203, 0, 2, '우리 발리브루가 발로 만들어도! 썬더브루보다는 나을 겁니다. 배부르지도 않고, 속 쓰리지도 않은 깔끔한 맛일 테니까요...'),
(24203, 0, 3, '여러분 입맛에 딱 맞는 건 발리브루입니다! 가을 축제에서 발리브루 맥주 맛을 꼭 확인하십시오!'),
