(24203, 1, 1, '가을 축제에서 천둥벼락이 치길 바라신 분들! 천둥벼락같이 화끈한 맛, 썬더브루가 바로 제격입니다!'),
(24203, 1, 2, '밋밋한 맥주 때문에 파티가 밋밋하십니까, 썬더브루가 해결해 드립니다! 가을 축제에 오셔서 썬더브루의 맛을 확인해 보십시오!'),
