(24204, 2, 2, '오크가 한 방 날릴 줄 안다고 생각하셨다면, 오크 맥주도 드셔 보십시오. 더 강력한 한 방을 날려주니까요! 드론의 양조장에 오셔서 확인하십시오, 가을 축제에서만 만나실 수 있습니다!'),
