(24204, 3, 2, '긴장 한번 풀어보시렵니까? 가을 축제에 오셔서 촬리의 부두 양조장을 찾아주시면 부드럽게 넘어가는 맥주를 맛보실 수 있습니다!'),
(24204, 3, 3, '흥겨움이 넘치는 곳이라면 촬리의 부두 맥주가 어울리지요! 가을 축제에 오셔서 흥겨움을 만끽하십시오!'),
(24205, 0, 0, '이리 와서 발리브루의 흑맥주를 드셔보시죠!'),
(24205, 0, 1, '가발양 기획사를 눈여겨 봐주십시오! 가을 축제 발리브루 양조사들입니다!'),
(24205, 0, 2, '우리 발리브루가 발로 만들어도! 썬더브루보다는 나을 겁니다. 배부르지도 않고, 속 쓰리지도 않은 깔끔한 맛일 테니까요...'),
(24205, 0, 3, '여러분 입맛에 딱 맞는 건 발리브루입니다! 가을 축제에서 발리브루 맥주 맛을 꼭 확인하십시오!'),
(24205, 1, 0, '썬더브루는 양조 업계에서 최고지.'),
(24205, 1, 1, '가을 축제에서 천둥벼락이 치길 바라신 분들! 천둥벼락같이 화끈한 맛, 썬더브루가 바로 제격입니다!'),
(24205, 1, 2, '밋밋한 맥주 때문에 파티가 밋밋하십니까, 썬더브루가 해결해 드립니다! 가을 축제에 오셔서 썬더브루의 맛을 확인해 보십시오!'),
(24205, 1, 3, '신비한 마법을 맛보고 싶으십니까? 최고의 경지에 도달한 썬더브루 양조사들! 그들이 빚어낸 신비한 맛을 가을 축제에서 맛보십시오!'),
(24205, 2, 0, '제대로 놀 줄 안다면 드론의 양조장을 선택하셔야지요! 가을 축제에서 확인해 보십시오!'),
(24205, 2, 1, '진짜 좋은 술이 뭔지 제대로 아는 오크들과 가을 축제를 즐겨봅시다! 가을 축제에서 드론의 양주장에 꼭 들러 주십시오!'),
(24205, 2, 2, '오크가 한 방 날릴 줄 안다고 생각하셨다면, 오크 맥주도 드셔 보십시오. 더 강력한 한 방을 날려주니까요! 드론의 양조장에 오셔서 확인하십시오, 가을 축제에서만 만나실 수 있습니다!'),
(24205, 2, 3, '드론의 양조장으로 오셔서 형제자매 여러분과 함께 호드를 위하여 건배하십시오!'),
(24205, 3, 0, '정말로 오크나 오우거가 만든 맥주를 드시겠다는 겁니까? 가을 축제에서 촬리의 부두 양조장을 선택하신다면 후회하지 않으실 겁니다!'),
(24205, 3, 1, '이국적인 맛의 맥주를 즐기시는 분이라면, 가을 축제에서는 촬리의 부두 양조장 맥주가 제격입니다!'),
(24205, 3, 2, '긴장 한번 풀어보시렵니까? 가을 축제에 오셔서 촬리의 부두 양조장을 찾아주시면 부드럽게 넘어가는 맥주를 맛보실 수 있습니다!'),
(24205, 3, 3, '흥겨움이 넘치는 곳이라면 촬리의 부두 맥주가 어울리지요! 가을 축제에 오셔서 흥겨움을 만끽하십시오!'),
(24211, 0, 0, '대지와 바람의 정령이 그대를 축복하기를.'),
(24211, 0, 1, '저는 돌아가야 합니다. 즐거운 사냥이 되시기를.'),
(24211, 0, 2, '당신에게 목숨을 빚졌습니다, 이방인이여.'),
(24211, 0, 3, '이상한 유령이 이 땅을 돌아다닙니다. 조심하십시오!'),
(24211, 0, 4, '고맙습니다, 이방인이여.'),
(24211, 0, 5, '그들은 우리를 한 명씩 데려갔습니다. 분명히 다른 생존자가 있을 겁니다.'),
(24211, 0, 6, '비틀린 숲을 지나가는 게 아니었습니다. 다른 사람들처럼 우리도 조심했어야 했어요!'),
(24211, 0, 7, '저를 죽음에서 구해 주셨군요. 그대에게 빚을 졌습니다.'),
(24238, 0, 0, '[조잡한 브리쿨어] 비요른네 엄마는 얼레리꼴레리!'),
(24238, 1, 0, '그딴 식으로 우리 어머니를 모독하지 마라!'),
(24238, 2, 0, '침입자들을 몰아내라! 앵거보다 여왕님을 위하여!'),
(24238, 2, 1, '두려워 말고 싸워라! 발키르 님께서 보상을 내리실 것이다!'),
(24238, 2, 2, '윈터스코른 부족은 이기리라!'),
(24239, 0, 0, '너희에게 그림자가 드리우리라...'),
(24239, 1, 0, '깨어나지 못할 악몽을 꾸어라!'),
(24239, 1, 1, '아자가 추고 진!'),
(24239, 2, 0, '넌 이제 내것이다!'),
(24239, 3, 0, '네 영혼이 피를 흘리리라!'),
(24239, 4, 0, '그런다고 달라질 건 없다.'),
(24239, 4, 1, '너흰 더 끔찍한 운명을 맞으리라.'),
(24239, 4, 2, '하, 제법이군.'),
(24239, 5, 0, '이게... 끝은 아니다!'),
(24248, 0, 0, '%s|1이;가; 당신에게 고개를 돌립니다.'),
(24248, 1, 0, '%s|1이;가; 이를 드러내고 웃습니다.'),
(24248, 2, 0, '아, 주술의 냄새가 나는구나... 그 덕에 여기까지 왔나 보군. 한때는, 나도 주술사였지.'),
(24248, 3, 0, '아니. 이자는 아직 멀었어.'),
(24248, 4, 0, '필멸의 존재여, 내게서 죽음이 느껴지느냐? 그 죽음은 내가 만지는 모든 것을 덮치지. 손가락만 까딱해도, 네 영혼은 지옥에 떨어져 영원히 괴로움에 몸부림칠 것이다.'),
(24248, 5, 0, '하지만... 아직은 리치 왕을 섬길 때가 아니다... 그래... 더 큰 운명이 너를 기다린다. 힘을... 나를 섬기기 전에, 너는 더 큰 힘을 길러야 한다.'),
(24248, 6, 0, '보아라, 발키르. 내가 이자를 움켜쥐는 것을 보아라. 아직 여물지 않았다는 걸 알겠느냐? 이 존재가 꽃피고, 말라 비틀어져 떨어지는 것을 보아라.'),
(24248, 7, 0, '고집이냐, 어리석음이냐? 상관없다. 이 일을 교훈으로 삼아라, 필멸자여.'),
(24271, 0, 0, '정지! 신분을 밝혀라!'),
(24271, 0, 1, '이 구역은 출입 금지다!'),
(24271, 0, 2, '당신 같은 친구는 처음 보는데...'),
(24271, 0, 3, '기다려라! 멈춰!'),
(24271, 0, 4, '정지!! 정지!! 이젠 고철들이 저절로 움직이나?'),
(24271, 1, 0, '그래... 미안하군. 어디까지 얘기했지?'),
(24271, 1, 1, '모두 위대한 창조자를 맞이하라!'),
(24271, 1, 2, '물론 그 말이 맞아. 계속하지.'),
(24271, 1, 3, '무례를 용서하시오!'),
(24271, 1, 4, '두 배로 일해야겠군!'),
(24271, 2, 0, '토석인 침입자를 제거한다.'),
(24271, 2, 1, '틀렸어!'),
(24271, 3, 0, '해체 작업을 계속한다.'),
(24271, 3, 1, '빈둥거리지 마라.'),
(24271, 3, 2, '작업을 계속해야 한다. 생산량을 두 배로 올려라.'),
(24271, 3, 3, '그분은 모든 것을 보고 계신다.'),
(24271, 3, 4, '지원군이 이동 중이다. 기능이 저하되어서는 안 된다.'),
(24271, 3, 5, '창조자의 전언을 가지고 왔나?'),
(24271, 3, 6, '위대한 창조주를 맞이하십시오.'),
(24277, 0, 0, '수작 부리지 마라!'),
(24284, 0, 0, '브리쿨 죄수가 목을 부여잡고 구역질하기 시작합니다.'),
(24314, 0, 0, '그럼 우리도 저주를 받았단 말이오?'),
(24314, 1, 0, '%s|1이;가; 아기를 가리킵니다.'),
(24314, 2, 0, '신께서 우리를 버렸소! 이미론의 귀에 들어가기 전에 죽여야 하오!'),
(24314, 3, 0, '여보, 그럼 어쩌자는 거요? 다른 방법이 없잖소. 그들이 알면 우리 둘 다 처형하고 말 거요.'),
(24321, 0, 0, '%s|1이;가; 조용히 하라는 신호를 보냅니다.'),
(24321, 1, 0, '브리쿨이여, 그대들의 왕이 하는 말에 귀 기울여라!'),
(24321, 2, 0, '청중이 공포에 질려 숨을 들이켭니다.'),
(24321, 3, 0, '바로 지금, 가장 절박한 이 시대에조차 신은 우리를 기만했노라!'),
(24321, 4, 0, '우리가 티탄을 가장 절실히 찾는 이때 그들은 어디에 있는가? 우리의 여인들은 두 발로 혼자 설 수조차 없는, 꼴사나운 기형아들을 낳고 있다. 약하고, 추하고... 쓸모없는 것들을...'),
(24321, 5, 0, '이미론은 고뇌했다. 왕좌에 오래도록 앉아 왜 우리가 이런 곤경에 처했는지 깊이 고민했다. 해답은... 이유는... 단 하나뿐이다...'),
(24321, 6, 0, '티탄 외에 그 누가 그런 저주를 내릴 수 있는가? 무엇이 그런 강력한 힘을 가질 수 있는가?'),
(24321, 7, 0, '해답은 없다... 우리에게 저주를 내린 건 바로 티탄이기 때문이다!'),
(24321, 8, 0, '청중이 환호합니다.'),
(24321, 9, 0, '오늘 이 순간부터 모든 브리쿨은 낡은 믿음을 버린다! 우리는 더는 해묵은 신을 섬기지 않을 것이다! 모든 브리쿨은 이미론에게 충성을 다하라! 이미론이 고귀한 우리 종족을 보호할 것이다!'),
(24321, 10, 0, '이제 브리쿨에게 첫 번째 명령을 내리겠노라! 브리쿨의 어버이가 낳은 모든 기형아는 태어나는 즉시 제거한다! 우리의 피를 반드시 순수하게 보존해야 한다! 이미론의 명령을 어기는 자는 샬레르브론으로 보내 처형할 것이다!'),
(24322, 0, 0, '조용히 해!'),
(24322, 1, 0, '왕이시여, 자비를 베푸소서! 그들은 우리의 혈육입니다!'),
(24322, 2, 0, '우리의 위대한 왕 이미론께 경배하라!'),
(24323, 0, 0, '죄인에게 자비를 보이지 마십시오, 이미론이시여!'),
(24323, 1, 0, '그들이 우리를 약해지게 한다! 그 존재만으로 우리의 힘이 꺾인다! 그들을 모두 없애라!'),
(24358, 0, 0, '좋을 대로 하시오. 하지만 안에 들어가려거든 최소한 세 명은 나를 도와야 하오. 따라오시오...'),
(24358, 1, 0, '내 계산에 따르면, 충분한 인원이 한꺼번에 징을 울리면 이 문을 막은 봉인이 깨져 안으로 들어갈 수 있을 거요.'),
(24362, 0, 0, '무쇠 드워프는 이렇게 생긴 상자에 도구를 보관합니다. 천막 근처에서 찾아보세요.'),
(24362, 1, 0, '거인을 지배할 수 있으리라 생각하는 룬을 새기려는 참입니다.'),
(24362, 2, 0, '"북쪽"과 "서쪽"을 뜻하는 룬은 뺐습니다. 거인에게 어떤 영향을 미칠지 확실하지 않아서 말입니다. 그리고 얼마 동안 제어할 수 있을지 정하는 룬도 넣고 있습니다.'),
(24362, 3, 0, '여기 있습니다, 지배의 룬입니다... 그 이름대로 작동한다면 말이지만 말입니다. 무쇠 드워프가 만든 것만큼 사악한 의도는 없지만 쓸 만할 겁니다.'),
(24363, 0, 0, '혼들이 오늘 잔치를 벌이겠구나! 의식을 시작해라. 포로를 제물로 바쳐라... 새 손님을 맞아야지!'),
(24366, 0, 0, '경비병!'),
(24374, 0, 0, '%s|1이;가; 분노에 휩싸입니다!'),
(24375, 0, 0, '이곳은 내가 전체적으로 연구해왔으니 바보 같은 보물 사냥꾼들이 덤벼들어 박물관으로 가져갈 만한 보물을 훔쳐가게 두지는 않을 것이오. 내가 앞장서리다.'),
(24375, 1, 0, '사실, 당신네는 그냥 여기 있는 게 돕는 거요. 거치적거리기만 할 뿐이니...'),
(24405, 0, 0, '고맙습니다!'),
(24458, 0, 0, '널 위해 남겨뒀다, 덩치 큰 녀석아!'),
(24480, 0, 0, '이렇게 해달라고 할 줄 몰랐는데!'),
(24480, 0, 1, '벌레는 먹으라고 주진 않을 거라 약속할게...'),
(24480, 0, 2, '별로 오래 걸리진 않을 거야, 안 그래?'),
(24480, 0, 3, '이게 바로 개구리 스타일이지!'),
(24480, 0, 4, '들어 봐, $n, 내가 여기서 멀지 않은 조그만 늪을 하나 아는데 말이야...'),
(24480, 0, 5, '네가 사는 수련잎으로 갈까? 아니면 내 잎?'),
(24480, 0, 6, '조그만 개구리가 된 것 같지?'),
(24480, 0, 7, '주변에서 모조를 별로 못 봐서 그래...'),
(24484, 0, 0, '으악, 검은무쇠 드워프다!!!'),
(24484, 0, 1, '도망가자! 검은무쇠 드워프가 나타났다!'),
(24484, 0, 2, '저들이 우리 맥주를 가지러 왔다!'),
(24484, 0, 3, '누가 우리 맥주통 좀 어떻게 해 줘요!'),
(24484, 0, 4, '맥주를 귀히 여긴다면, 어서 저걸 좀 지켜줘요!'),
(24492, 0, 0, '드론의 술은 전설이 됐지! 이리 와서 전설을 맛보라고!'),
(24492, 0, 1, '호드를 위해 건배! 자네도 호드를 위해 마시나? 드론의 양조장에서 보여달라고!'),
(24492, 0, 2, '거기, 키 큰 자네 말이야... 알딸딸한 기분에 젖고 싶은 거 같은데? 드론의 양조장이 도와 주지!'),
(24492, 0, 3, '이봐 자네! 촬리의 부두 양조장에서 만든 맥주를 마신다고 죽지는 않는다고! 물론 그럴 만한 것도 있지만 말이야...'),
(24492, 1, 0, '누가 이 특제 맥주잔도 던지십시오!!'),
(24492, 2, 0, '마시고 던져라! 던지고 마셔라!'),
(24492, 2, 1, '공짜로 받은 맥주는 마셔 버리고 험상궂은 선술집 녀석들에게 맥주잔을 던지십시오!'),
(24493, 0, 0, '인생을 최대한 즐기고 싶다면 촬리의 부두 맥주를 마셔야지!'),
(24493, 0, 1, '흥겨움이 넘치는 곳이라면 촬리의 부두 맥주가 어울리지요! 가을 축제에 오셔서 흥겨움을 만끽하십시오!'),
(24493, 0, 2, '이봐 자네! 촬리의 부두 양조장에서 만든 맥주를 마신다고 죽지는 않는다고! 물론 그럴 만한 것도 있지만 말이야...'),
(24493, 0, 3, '촬리의 부두 맥주보다 나은 건 못 찾을걸! "주간 고블린 맥주"에서 "최고의 맥주"로 뽑힌 상품이라고!'),
(24493, 1, 0, '누가 이 특제 맥주잔도 던지십시오!!'),
(24493, 2, 0, '마시고 던져라! 던지고 마셔라!'),
(24493, 2, 1, '공짜로 받은 맥주는 마셔 버리고 험상궂은 선술집 녀석들에게 맥주잔을 던지십시오!'),
(24495, 0, 0, '우와! 다시 지나가 봐, 멋진 아가씨!'),
(24495, 0, 1, '저기요! 끝내주는 언니들, 여기 좀 보세요!'),
(24495, 0, 2, '이봐, 이봐, 귀염둥이! 아휴, 예뻐 죽겠어!'),
(24495, 0, 3, '헤이, 거기! 그래, 자기! 몸매가 정말 예술이네!'),
(24495, 0, 4, '와! 한 덩치하는 누님! 제 상대가 되시려나 어쩌려나?'),
(24525, 0, 0, '칼 받아라, 못생긴 개굴! 형제 배신 누구인지 보여라!'),
(24525, 1, 0, '여기 그런 동네 아냐. 어떤 반항쟁이도 내 칭구한테 장난치고 도망 못 가.'),
(24528, 0, 0, '노새에게 편자를 신기는 데 얼마나 내야 합니까?'),
(24528, 1, 0, '말귀를 못 알아듣는군! 빨리 준비하지 못하면 집 짓기 좋은 땅을 다 뺏긴단 말입니다!'),
(24528, 2, 0, '저건 말입니다, 대장장이 양반, 노새라고요!'),
(24530, 0, 0, '%s|1이;가; 격노합니다!'),
(24531, 0, 0, '그래, 여보. 하지만 작물을 심고 수확하기 전까진 그 양고기를 먹어야 한단 건 알아 둬요...'),
(24531, 1, 0, '당신 목소리보다 차라리 그놈 울음소리를 듣는 게 마음이 편하겠소, 여보.'),
(24531, 2, 0, '물론이지, 여보.'),
(24534, 0, 0, '빌더바르 요새에 잘 오셨소, 용감한 개척자 여러분! 주위의 모든 땅이 우리 손길을 기다리고 있소!'),
(24534, 1, 0, '노스렌드가 척박한 땅인 것은 분명하지만, 우린 강인하고 굳센 사람들이니 충분히 이 일을 해낼 수 있소!'),
(24534, 2, 0, '우리의 검으로 이 땅을 손에 넣고 우리의 농기구로 이 땅을 일구어 나갈 것입니다! 여러분은 거친 땅을 길들인 자로서 두고두고 기억될 것이오!'),
(24534, 3, 0, '하지만 여러분은 혼자가 아니오. 내 부하들이 여러분에게 가장 필요한 보급품을 짐노새에 실어 가져왔소.'),
(24534, 4, 0, '도끼, 곡괭이, 씨앗, 못, 음식, 담요, 물... 필요한 건 뭐든지 거기 다 있소. 가격도 딱 적당할 거요.'),
(24534, 5, 0, '충분하고도 남을 만큼 많이 있소. 만약 다른 물건이 필요하다면 주저하지 말고 요청하시오!');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(24534, 6, 0, '그럼 친애하는 소비자 여러... 아니, 친구들이여. 모든 이를 위해 이 땅을 개척해 나갑시다!'),
(24536, 0, 0, '아무도 검은무쇠 드워프가 나타날 줄 몰랐겠지!'),
(24536, 1, 0, '생맥주도 흑맥주도 마셔버릴 거야!\n맥주잔도 맥주통도 비워버릴 거야!\n마시고 떠들고 떠들고 마시자!\n다리에 감각이 없을 때까지!'),
(24536, 1, 1, '코렌에게 잔을 넘기자!\n헐레이 블랙브레스한테도 줘야지!\n이 맥주는 심심해. 톡 쏘는 맛도 없고!\n하지만 어쨌든 맥주라네! 아싸!'),
(24536, 1, 2, '맥주를 전부 다 마셔 버리면\n어둠괴철로로 돌아가야지.\n라그나로스에게 쓰디쓴 건배를...\n맥주는 한 방울도 안 갖다줄 거지만!'),
(24536, 1, 3, '우리는 검은바위 산에서 왔다네.\n너희 맥주를 마셔버릴 거야!\n검은무쇠 드워프는 거짓말을 안해.\n그러니 조심하는 게 좋을걸!'),
(24536, 1, 4, '검은무쇠 흑맥주도 안 마시고\n검은무쇠 맥주도 안 판다네!\n우리를 빼놓고 가을 축제를 한다고?\n해 보라지! 후회하게 될걸!'),
(24536, 2, 0, '후퇴! 우리는 $3151W의 희생자를 내며 밀리고 있다! 피해가 막심하다! 물러나라!'),
(24536, 3, 0, '우리가 해냈다, 친구들! 험상궂은 주정뱅이 선술집으로 돌아가서 상처 입은 $3151W명 몫까지 마셔버리자!'),
(24537, 0, 0, '난 예술에 대해서는 잘 몰라도... 내가 뭘 좋아하는지는 잘 알지!'),
(24539, 0, 0, '날 시험하지 마라, 천박하기 그지없는 놈! 나는 혈기사 훈련을 받은 몸이란 말이다!'),
(24539, 1, 0, '갚을게! 갚는다고! 으악! 제발 때리지 마!'),
(24547, 0, 0, '%s|1이;가; 주인의 몸을 덥석 삼킵니다.'),
(24547, 0, 1, '%s|1이;가; 주인의 몸을 덥석 삼킵니다.'),
(24560, 0, 0, '그들을 제거하십시오.'),
(24642, 0, 0, '좋은 술과 친구들만큼 날 즐겁게 하는 건 아무것도 없지... 딸꾹!'),
(24642, 0, 1, '...그 녀석은 두 다리가 의족이고, 왼손은 갈고리고, 두 눈알은 유리 눈에, 코는 나무로 깎아 만든 코야!'),
(24642, 0, 2, '좋은 술과 친구들만큼 날 즐겁게 하는 건 아무것도 없지... 딸꾹!'),
(24642, 0, 3, '뭘 보는 거냐, 쥐새끼 같은 녀석아? 하하... 농담이야.'),
(24642, 0, 4, '좋은 술과 친구들만큼 날 즐겁게 하는 건 아무것도 없지... 딸꾹!'),
(24642, 0, 5, '...그 녀석은 두 다리가 의족이고, 왼손은 갈고리고, 두 눈알은 유리 눈에, 코는 나무로 깎아 만든 코야!'),
(24642, 0, 6, '테리가 그 그림 중 한 점을 천 골드에 팔았다고 들었는데 말이야. 나도 그 미술품 거래에 한 몫 거들어야겠어!'),
(24642, 0, 7, '테리가 그 그림 중 한 점을 천 골드에 팔았다고 들었는데 말이야. 나도 그 미술품 거래에 한 몫 거들어야겠어!'),
(24642, 0, 8, '엿이나 먹으라고? 어디 엿이 있어야지...'),
(24642, 0, 9, '뭘 보는 거냐, 쥐새끼 같은 녀석아? 하하... 농담이야.'),
(24642, 0, 10, '앉아서 한 잔 하시오, 친구! 나한테도 한 잔 사 주고!'),
(24642, 0, 11, '앉아서 한 잔 하시오, 친구! 나한테도 한 잔 사 주고!'),
(24642, 0, 12, '좋은 술과 친구들만큼 날 즐겁게 하는 건 아무것도 없지... 딸꾹!'),
(24642, 0, 13, '...그 녀석은 두 다리가 의족이고, 왼손은 갈고리고, 두 눈알은 유리 눈에, 코는 나무로 깎아 만든 코야!'),
(24642, 0, 14, '엿이나 먹으라고? 어디 엿이 있어야지...'),
(24642, 0, 15, '뭘 보는 거냐, 쥐새끼 같은 녀석아? 하하... 농담이야.'),
(24642, 0, 16, '"으아아아아아아아... 미치겠군!" 잠깐... 이게 아닌 것 같은데...'),
(24642, 0, 17, '테리가 그 그림 중 한 점을 천 골드에 팔았다고 들었는데 말이야. 나도 그 미술품 거래에 한 몫 거들어야겠어!'),
(24642, 0, 18, '테리가 그 그림 중 한 점을 천 골드에 팔았다고 들었는데 말이야. 나도 그 미술품 거래에 한 몫 거들어야겠어!'),
(24642, 0, 19, '... 그래서 그가 말했지. "당연히 두 개로 보일 리가 없지! 난 눈알이 하나뿐이니까!"'),
(24642, 0, 20, '앉아서 한 잔 하시오, 친구! 나한테도 한 잔 사 주고!'),
(24642, 0, 21, '... 그래서 그가 말했지. "당연히 두 개로 보일 리가 없지! 난 눈알이 하나뿐이니까!"'),
(24642, 0, 22, '"으아아아아아아아... 미치겠군!" 잠깐... 이게 아닌 것 같은데...'),
(24642, 0, 23, '"으아아아아아아아... 미치겠군!" 잠깐... 이게 아닌 것 같은데...'),
(24664, 0, 0, '너무 으스대지 마라. 무슨 생각을 하는지 알겠다만, 폭풍우 요새는 잠시 머무르는 곳이었을 뿐이야. 내가 정말로 눈먼 반쪽짜리 나이트 엘프 잡종 따위에게 미래를 맡길 거라고 생각했나?'),
(24664, 1, 0, '복수여, 타올라라!'),
(24664, 2, 0, '펠로민 아샬!'),
(24664, 3, 0, '세상을... 거꾸로... 뒤집어주마.'),
(24664, 4, 0, '주인님, 제게 힘을 주소서.'),
(24664, 5, 0, '너무... 편안해하지는 마라.'),
(24664, 6, 0, '이런다고 달라질 것 같으냐! 주인님께서 널 가만두지 않을 것이다! 피의 강에서 허우적대라! 세상은 불타버릴 것이다! 으아아!'),
(24669, 0, 0, '깨우는 의식이 방해를 받아 브리쿨이 죽습니다.'),
(24669, 0, 1, '잘못된 방법으로 잠에서 깬 브리쿨이 죽습니다.'),
(24669, 0, 2, '각성의 지팡이를 잘못 사용하자 잠들어 있는 브리쿨이 죽습니다.'),
(24703, 0, 0, '스컬지가 우리를 포위했네. 얼마간은 마을을 방어할 수 있겠지만, 결국 저들을 물리치지 못한다면 우리는 모두 죽을 걸세.'),
(24703, 1, 0, '뭔가 행동을 해야 하네. 스컬지가 우리를 몰살하기 전에 놈들에게 어떻게 대항할지 결정해야만 해.'),
(24703, 2, 0, '전장에서의 장렬한 최후라는 낭만에 내 전사들을 희생할 생각은 없네. 살아남고자 벌인 싸움에서 아무도 살아남지 못한다면 그게 무슨 소용인가?'),
(24703, 3, 0, '언젠가 싸울 날이 올 걸세, 두름. 하지만 먼저 이 불리한 상황을 뒤집을 가능성이 있는지부터 찾아봐야지. 뭔가 좋은 생각이 있는가, 아이레?'),
(24703, 4, 0, '자네가 생각하는 명예는 대체 얼마나 값진 것인가, 두름? 자네의 목숨을 버릴 만큼? 내 목숨만큼? 아니면 어릴 때부터 자네를 길러준, 눈멀고 늙은 대부 마한의 목숨을 희생할 만큼 값진가?'),
(24703, 5, 0, '죽은 자에게 명예란 아무 의미도 없네. 전사는 명예를 위해 전장에서 죽어갈 수도 있지만, 족장은 그보다 더 많은 것을 책임져야 하는 법이야. 현자 아이레의 계획에 따르기로 하고 마을을 계속 방어하세.'),
(24703, 6, 0, '아이레, $n|1이;가; 가죽을 구해 왔네. 내가 토하기 전에 어서 가져가 주게.'),
(24706, 0, 0, '생각할 것도 없습니다. 공격해야 합니다. 우리가 불리하다는 건 알지만, 타운카로서 가만히 앉아 당할 수만은 없습니다.'),
(24706, 1, 0, '저는 차라리 도끼를 움켜쥐고 적의 피를 뒤집어쓴 채로 죽어가겠습니다!'),
(24706, 2, 0, '명예라곤 찾아볼 수 없는 계획이군요.'),
(24710, 0, 0, '좋아요! 그럼 어디 독한 맥주를 마셔 볼까요...'),
(24710, 1, 0, '브론즈비어드의 수염이여! 이거 정말 끝내주는데요!'),
(24710, 2, 0, '$n, 이 맥주는... 가을 축제에 나온 맥주 중에서 최고일지도 몰라요!'),
(24710, 3, 0, '모든 사람이 코렌의 독한 맥주를 맛볼 수 없다는 게 아쉽군요! 불경스러운 말인 줄은 알지만, 검은무쇠 드워프 녀석들이 부러울 정도라고요!'),
(24710, 4, 0, '안녕하세요! 가을 축제에 오신 걸 환영합니다!'),
(24710, 4, 1, '반갑습니다, 우리의 친구분! 가을 축제 광장에 오신 걸 환영합니다!'),
(24710, 4, 2, '안녕하세요, 거기 멋진 $c님! 아이언포지의 연례 행사, 가을 축제를 즐기세요!'),
(24711, 0, 0, '시간은 돈인데, 이렇게 시간을 낭비할 수는 없죠! 그럼 마셔 볼까요...'),
(24711, 1, 0, '우와! 정말 목구멍이 뻥 뚫리는데요!'),
(24711, 2, 0, '제가 정직한 고블린이었다면, 이 맥주가 축제 최고의 맥주라고 말했을 겁니다...'),
(24711, 3, 0, '코렌이 죽었다니 유감이군요. 그 친구한테 맥주를 사들여서 물 좀 섞고 제 상표를 붙여 팔았으면 꽤 짭짤했을 텐데 말이에요!'),
(24711, 4, 0, '여어, 거기 있는 친구! 가을 축제에 오신 걸 환영합니다. 이리 와서 몇 잔 걸치세요!'),
(24711, 4, 1, '요즘 어때요, 친구? 가을 축제 광장에 오신 걸 환영합니다! 저쪽에서 마실 것을 팔고 있답니다!'),
(24711, 4, 2, '이야, 또 다른 $c님이시로군요! 함께 올해의 가을 축제를 축하합시다. 가서 마시고 즐기자고요!'),
(24713, 0, 0, '저주받을 개구리 같으니! 그래, 난 예전에 남쪽바다 해적단의 일원이었어. 그게 뭐 어쨌다는 건가, 친구? 당장 절단을 내 주겠어!'),
(24717, 0, 0, '워, 워, 워! 모두 멈추라고, 친구들!'),
(24717, 1, 0, '오, 바위와 철의 신이시여... 그거... 그걸로 대체 뭘 하겠다는 거야?'),
(24717, 2, 0, '드워프들이 모두 큰 소리로 낄낄댑니다.'),
(24718, 0, 0, '이봐, 그거론 절대 성공할 수 없어. 무쇠 드워프들이 그런 잡동사니에 속을 리가 없잖아!'),
(24718, 1, 0, '이봐, 지금 무슨 짓을 하려는 건지 알고나 있나? 나 레브론스키는 자네가 내 양탄자 위로 그 고철덩이를 끌고 다니는 게 싫단 말이네.'),
(24718, 2, 0, '굉장한데. 어쩌면 이 고철덩이가 뭔가 해낼지도 모르겠어...'),
(24720, 0, 0, '아버지가 살아서 저 꼴을 보셨어야 하는데!'),
(24723, 0, 0, '놀아줄 시간이 없다!'),
(24723, 1, 0, '힘을 원해! 끝없는 힘을!'),
(24723, 2, 0, '그래!! 나는 신이다!'),
(24723, 3, 0, '흥, 기분 전환이 됐군.'),
(24723, 3, 1, '아무도 날 이기지 못해!'),
(24723, 4, 0, '안돼... 더, 조금 더!'),
(24723, 5, 0, '%s|1이;가; 근처의 지옥 수정에서 힘을 끌어냅니다. 수정을 파괴하십시오!'),
(24742, 0, 0, '하하하하! 절대로 내 망원경을 얻을 수 없을 거다, 더러운 녀석!'),
(24742, 0, 1, '하하하하! 절대로 내 망원경을 얻을 수 없을 거다, 더러운 녀석!'),
(24742, 1, 0, '이게 네 주인에 대한 보답이냐, 이 더러운 짐승아? 끄아아아아!'),
(24742, 1, 1, '이게 네 주인에 대한 보답이냐, 이 더러운 짐승아? 끄아아아아!'),
(24744, 0, 0, '생명... 삼킨다...'),
(24744, 1, 0, '억제할 수... 없다...'),
(24744, 2, 0, '해방... 하라...'),
(24744, 3, 0, '삼켰... 다...'),
(24744, 4, 0, '벡살루스가 순수한 힘을 방출합니다!'),
(24779, 0, 0, '오늘 저녁엔 네놈이 반찬이다!'),
(24779, 0, 1, '너무 쉬운 사냥감이군...'),
(24779, 0, 2, '누가 누굴 사냥한다고?'),
(24788, 0, 0, '물론이지, 귀염둥이. 술값은 해리 앞으로 달아 놓으라고. 그 친구 나한테 한 잔 사기로 했으니 말이야!'),
(24788, 1, 0, '공짜 술...? 내가 제일 좋아하는 술이군!'),
(24788, 2, 0, '넵튤론이시여! 오늘은... 너무 많이... 마셨군!'),
(24790, 0, 0, '하하하하! 내 보물을 가져가고 싶다면... 싸워 이기고 가져가라!'),
(24790, 1, 1, '끄아아아... 또 죽다니!'),
(24796, 0, 0, '넌 죽었어, 애송이!'),
(24797, 0, 0, '바다표범 암컷과 바다표범 수컷이 사랑에 빠졌습니다.'),
(24806, 0, 0, '발진합니다.'),
(24807, 0, 0, '내 완벽한 창조물 좀 보라고!'),
(24807, 1, 0, '뭘 몰라도 한참 모르는군, 레브론스키! 주제넘은 소리하곤! 무쇠 드워프들은 자기들이 뭐에 당했는지도 모를 거야! 자넨 그 양탄자에 묻은 똥의 비밀이나 파헤치는 거 계속하고, 나 같은 진짜 과학자님께서 하시는 일에는 참견하지 말라고!'),
(24823, 0, 0, '무쇠룬 피조물 모델명 U-9207는 당신의 말투가 마음에 들지 않습니다. 양탄자 소멸 작업을 시작합니다, 레브론스키.'),
(24825, 0, 0, '발진합니다.'),
(24825, 1, 0, '경보! 경보! 적들의 방어선 통과가 감지되었습니다! 수가 증가하고 있습니다.'),
(24825, 1, 1, '피조물이 임무 보고합니다. 최우선 임무: 감시'),
(24825, 1, 2, '이곳에는 감시할 대상이 없습니다. 명령에 따라 임무를 계속합니다.'),
(24825, 1, 3, '피조물의 작업에 방해되는 요인은 모두 제거합니다. 해산하십시오.'),
(24825, 1, 4, '무쇠 드워프는 피조물에게 질문할 수 없습니다. 파괴 작업을 진행합니다.'),
(24825, 1, 5, '피조물은 하급 존재들과 대화하도록 승인되지 않았습니다. 하급 존재들은 생산량을 두 배로 높여야 합니다.'),
(24825, 1, 6, '지갑을 분실하셨습니까? 피조물이 화폐로 가득 찬 지갑을 발견했습니다.'),
(24830, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(24847, 0, 0, '천둥소리가 동굴 곳곳에 울려 퍼집니다.'),
(24847, 1, 0, '오너라, 하인들아! 네 주인이 명한다!'),
(24847, 2, 0, '폭풍우 봉우리에서 너희 형제가 하는 일이 매우 빠른 속도로 진행되고 있다. 머지않아 아버지께서 자유로워질 것이다.'),
(24847, 3, 0, '북쪽의 너희 형제가 돌 괴수를 굴복시켜 울두아르로 가는 길에 배치했다. 머지않아 판테온의 나머지 방어군도 제거될 것이다.'),
(24847, 4, 0, '필멸의 존재들이 이 지역에서 만든 세 균열은 반드시 봉해야 한다. 그렇지 않으면 대지가 우리의 작업을 보고 들어, 끊임없이 우리를 방해할 것이다.'),
(24847, 5, 0, '이곳을 파묻어라! 네 주인이 명한다!'),
(24847, 6, 0, '천둥소리가 점점 사라집니다.'),
(24850, 0, 0, '으아!! 난 이제 말리고스의 노예가 아니다! 덤벼라, 끝장을 내주마!'),
(24850, 1, 0, '킬제덴의 이름으로!'),
(24850, 1, 1, '난 이미 경고했다!'),
(24850, 2, 0, '크나큰 빚을 졌습니다. 킬제덴을 쓰러뜨린다면, 이 세계 역시 그대들에게 빚을 지는 겁니다.'),
(24850, 3, 0, '나는 완전히 깨어났다! 모두 없애 주마!'),
(24874, 0, 0, '너무 늦었다. 보잘것없는 존재여. 네게 닥쳐오는 안개가 느껴지느냐? 크발디르가 돌아온다...'),
(24875, 0, 0, '형제들이 깨어났다. 너희가 한 노력은 헛수고일 뿐...'),
(24876, 0, 0, '안개와 연기를 타고 크발디르가 올 것이다. 살아서 숨 쉴 수 있을 때 도망가라...'),
(24877, 0, 0, '바다를 보아라. 너의 파멸이 굽이치는 파도를 타고 온다.'),
(24882, 0, 0, '불쌍한 도마뱀 같으니! 널 기다리는 건 죽음뿐이다!'),
(24882, 1, 0, '하! 마법이 귀엽기도 하지!'),
(24882, 2, 0, '박살 내 주마!'),
(24882, 3, 0, '즐거웠습니다.'),
(24882, 4, 0, '자, 운을 시험해 봐라!'),
(24882, 5, 0, '하, 새끼 양이 잔뜩 몰려오는구나!'),
(24882, 6, 0, '버러지 같은 놈들!'),
(24882, 6, 1, '넌 내 밥이다!'),
(24882, 6, 2, '약해 빠졌어!'),
(24882, 7, 0, '자, 어서 덤벼 봐라!'),
(24882, 7, 1, '으하하! 영광스러운 전투를 위하여!'),
(24882, 7, 2, '난 싸우기 위해 산다!'),
(24882, 8, 0, '그래, 그 정도면 괜찮았다. 죽어라!'),
(24882, 9, 0, '으아! 잘했다! 이제 좀... 재미있군...'),
(24891, 0, 0, '나를... 도와주오! 더는... 버틸 수가... 없어!'),
(24891, 1, 0, '으아아악! 내 정신을 지켜주시오!'),
(24891, 2, 0, '어서요! 날 잃어 가고 있어!'),
(24892, 0, 0, '아무도 널 도울 수 없어! 내 할 일이 거의 끝나 간다!'),
(24892, 1, 0, '가련한 필멸자여!'),
(24892, 1, 1, '말하지 않았나? 나는 항상 이긴다!'),
(24892, 2, 0, '우리는... 절대... 지지 않는다!'),
(24892, 3, 0, '네 고통은 내 행복이지!'),
(24892, 4, 0, '피를 보고야 말겠다.'),
(24910, 0, 0, '살아생전에는 네 녀석이 이겼을지 몰라도, 죽은 나는 절대로 못 이길 거다! 발사!'),
(24910, 0, 1, '발사! 보물이 탐나거든 쏴라, 이놈들아!'),
(24910, 0, 2, '쏴! 쏘라고, 겁쟁이 녀석들아!'),
(24911, 0, 0, '거기 애송이, 보물을 가져와!'),
(24911, 0, 1, '요호호, 노움이 얼마나 용감한지 봤지?!'),
(24911, 0, 2, '보물은 우리 것이다!'),
(24911, 0, 3, '술과 여자가 우리를 기다리는군!'),
(24911, 0, 4, '거기 애송이, 보물을 가져와!'),
(24911, 0, 5, '술과 여자가 우리를 기다리는군!'),
(24911, 0, 6, '요호호, 노움이 얼마나 용감한지 봤지?!'),
(24911, 0, 7, '보물은 우리 것이다!'),
(24911, 0, 8, '녀석이 쓰러졌다!'),
(24960, 0, 0, '안 돼! 네놈에게 이곳을 내줄 수는 없다!'),
(24966, 0, 0, '꺼져라! 이곳은 우리 차지다!'),
(24981, 0, 0, '배치를 완료했습니다. 침입자들을 제압합니다.'),
(24981, 0, 1, '임무가 입력되었습니다. 보안 작업을 시작합니다.'),
(24992, 0, 0, '소를로프의 보물이 바닥에 떨어집니다.'),
(25038, 0, 0, '%s|1이;가; 숨을 깊게 한번 들이마십니다.'),
(25038, 4, 1, '최후의 순간이다!'),
(25132, 0, 0, '무너진 태양 공격대 녀석들이다! 발사!'),
(25144, 0, 0, '서쪽에서 용매가 날아온다! 저 $c|1을;를; 떨어트려!'),
(25144, 0, 1, '악마들한테서 눈을 떼지 마십시오. 오늘은 스컬지를 사냥하러 온 게 아닙니다.'),
(25162, 0, 0, '주목!'),
(25162, 1, 0, '알았다. 조용히 하도록. 제군들, 지금 우리에겐 할 일은 많지만 시간은 없다.'),
(25162, 2, 0, '자네 드레나이들 중 일부는 스케티스에서 또 일부는 어둠달 골짜기에서 만났던 것 같군. 하지만 지금 이곳은 아제로스고 상황이 좋지 않다.'),
(25162, 3, 0, '우선 신도레이들은 잘 들어라. 나는 무엇보다도 기강을 중시한다. 점술가 길드와 있을 때와는 전혀 분위기가 다를 것이야. 그러니 전력을 기울이든가 아니면 당장 배로 돌아가라!'),
(25162, 4, 0, '이제 주사위는 던져졌다. 쿠엘다나스 섬에 온 것을 환영한다. 태양샘은 남쪽 고원에 있고, 캘타스 왕자는 동쪽에 있는 마법학자의 정원에 숨어 있다.'),
(25162, 5, 0, '위에서 불러들인 ''모험가''라는 자들을 지원하는 일이 우리가 이곳에서 맡은 임무다. 우리는 그들이 섬 곳곳의 요충지를 방어하는 일을 돕고, 맡은 임무를 수행할 수 있도록 그들을 보호해야 한다.'),
(25162, 6, 0, '질문 있나? 없다면 자세한 지시와 명령은 각자의 분대장에게서 받도록 해라. 이상이다. 건투를 빈다!'),
(25162, 7, 0, '주목!'),
(25162, 8, 0, '태양샘에 온 것을 환영한다. 날씨도 따뜻하고 경치도 훌륭하지만, 제군들은 이곳에 휴가를 온 것이 아니다!'),
(25162, 9, 0, '현재 상황은 이렇다. 경험 많고 더 좋은 장비를 갖춘 병력이 캘타스 왕자를 향해 진격하는 동안, 우리는 온 힘을 기울여 방어하고 있다.'),
(25162, 10, 0, '그렇다. 우리는 그자가 죽었다고 알고 있었지만 실상은 그렇지 않다. 그자는 태양샘을 통해 불타는 군단의 우두머리, 킬제덴을 이 세상으로 불러들이려 한다.'),
(25162, 11, 0, '다시 한 번 말하지만, 그자가 성공한다면 이 세상은 아웃랜드에서 지금껏 일어났던 일보다 훨씬 험한 상황에 부닥칠 거다. 그러니 무슨 수를 써서라도 이를 막아내야 한다.'),
(25162, 12, 0, '전사들은 요충지 방어 임무에 배치될 것이고, 사수들은 적의 공중병력을 막아내는 임무를 맡을 것이다.'),
(25162, 13, 0, '난 제군들에게 줄 특별 임무에 대한 명령을 기다리는 중이다. 그때까지 언제든지 이동할 수 있는 상태를 갖추고 여기서 대기해라!'),
(25162, 14, 0, '주목!'),
(25162, 15, 0, '반갑다, 신병 제군들. 난 훈련교관 바둠이다. 제군들은 앞으로 며칠간 교육을 받게 된다.'),
(25162, 16, 0, '쿠엘다나스 섬은 캘타스 선스트라이더 왕자의 군대가 장악했다. 그가 죽었다는 정보가 입수된 바 있지만, 이 정보는 잘못된 것이다.'),
(25162, 17, 0, '이 고원에서 그자와 그의 악마들이 태양샘을 가동시켜 그자들의 우두머리인 킬제덴을 다시 이 세계로 불러올 균열을 만들려고 한다.'),
(25162, 18, 0, '우리의 임무는 놈의 총알받이를 최대한 많이 없애면서 우리 지도자들이 모셔온 전문가들을 지원하는 것이다.'),
(25162, 19, 0, '말할 것도 없겠지만, 제군들이 살아서 돌아갈 확률은 매우 낮다. 하지만 배운 걸 기억하고 그대로만 한다면 그 확률은 얼마든지 높일 수 있다.'),
(25162, 20, 0, '이상이다. 정신 똑바로 차려라, 제군들.'),
(25165, 0, 0, '그들이 어디 있는지 말해라!'),
(25165, 1, 0, '그들이 어디 있는지 말해라!'),
(25165, 2, 0, '그들이 어디 있는지 말해라!'),
(25165, 3, 0, '그들이 어디 있는지 말해라!'),
(25166, 0, 0, '어둠이 불꽃을 지피리라!'),
(25166, 1, 0, '어둠이 불꽃을 지피리라!'),
(25166, 2, 0, '혼돈...'),
(25166, 3, 0, '혼돈...'),
(25208, 0, 0, '함께 싸워서 겨울지느러미 은신처로 돌아가는 거야. 준비됐지?'),
(25208, 1, 0, '그럼, 출발!'),
(25208, 2, 0, '이제 됐어. 여기서부턴 나 혼자 갈 수 있어.'),
(25208, 3, 0, '구해줘서 고마워, $r. 왕께 내가 돌아왔다고 전해 줘.'),
(25210, 0, 0, '나는 열쇠지기다. 당신이 문지기인가?'),
(25220, 0, 0, '광산에서 일했습니다.'),
(25220, 0, 1, '농장 일꾼입니다.'),
(25220, 0, 2, '재단사였습니다.'),
(25220, 0, 3, '대장장이였습니다.'),
(25220, 0, 4, '목수입니다.'),
(25220, 0, 5, '조선공입니다.'),
(25220, 0, 6, '석공이었습니다, 징집관님.'),
(25220, 0, 7, '요리사였습니다.'),
(25222, 0, 0, '자, 노스렌드에 오기 전엔 뭘 했나?'),
(25222, 0, 1, '직업이 뭐였는지 말해보게.'),
(25222, 0, 2, '좋아. 자네는 무슨 일을 했나?'),
(25222, 0, 3, '예전엔 무슨 일을 했나, 신병?'),
(25222, 0, 4, '직업은?'),
(25222, 1, 0, '좋아. 자네는 꽤 경험이 많은 것 같군. 당장 시민 연락원에게 보고하게. 자네 같은 사람이 더 필요해!'),
(25222, 1, 1, '자네 같은 사람은 이미 충분히 모집했다고 생각했는데, 지금 보니 아직 자리가 좀 남았군. 시민 연락원에게 보고하게.'),
(25222, 1, 2, '자네에게 맡길 만한 일이 좀 있군. 시민 연락원에게 보고하게.'),
(25222, 1, 3, '좋아. 자네 같은 사람이 더 있으면 좋으련만. 시민 연락원에게 보고하고 임무를 받도록 하게.'),
(25222, 2, 0, '그 일 할 사람은 넘쳐! 여기 자네 검이 있으니 병영에 가서 보고하고 임무를 받게!'),
(25222, 2, 1, '겁낼 것 없네, 친구. 여기 검과 방패가 있네. 병영에 가서 보고하고 임무를 받게나.'),
(25222, 2, 2, '마음이 다 아프군... 나도 채워야 할 할당량이 있어서 어쩔 수가 없네. 자네도 이해하겠지? 칼은 다룰 줄 아나? 병영으로 가 보게.'),
(25222, 2, 3, '그런 훌륭한 팔로 말인가? 아마도 자네는 최전방으로 가야 할 것 같네. 병영에 가서 보고하게.'),
(25222, 2, 4, '자리가 하나 더 있었던 것 같은데... 이런, 내가 잘못 알았군. 하나가 아니라 일곱이었네. 자네가 칼 좀 쓰는 사람이었으면 좋겠군. 병영에 가서 보고하게.'),
(25222, 3, 0, '자, 다음!'),
(25222, 3, 1, '이보게들, 계속 움직이게.'),
(25222, 3, 2, '다음!'),
(25237, 0, 0, '%s|1이;가; 투덜거립니다.'),
(25237, 1, 0, '항로... 보급품... 지겹도록 들었더니 귀에 딱지가 앉을 지경이군요! 필요한 건 호드의 투쟁 정신뿐입니다, 사울팽! 이 얼어붙은 황무지에 요새까지 굳건히 세운 이상 그 무엇도 우릴 막을 순 없습니다!'),
(25237, 2, 0, '계획 말입니까? 제 계획이 뭔지 보여드리지요!'),
(25237, 3, 0, '저기... 이제 저희도 수송로가 있지 않습니까.'),
(25237, 4, 0, '게다가 덤으로...'),
(25237, 5, 0, '뒷일 얘기까지 하지는 마시지요, 어르신.'),
(25237, 6, 0, '하지만, 그 아이들이 정말로 천진난만할 뿐이라고 확신할 수 있습니까? 커서 우리에게 무기를 들이댈지 누가 알겠습니까!'),
(25237, 7, 0, '어떻게 그토록 오래 살아남았습니까, 사울팽? 마음속에 있는 기억 때문에 무너지지 않고 말입니다.'),
(25245, 0, 0, '규칙은 알고 있겠지. 근무 중인 병사에게는 술을 줄 수 없어. 장군님 손에 죽게 만들 셈인가?'),
(25245, 1, 0, '알았어, 알았다고... 하지만 이걸 내가 줬다고 말하면 안 돼!'),
(25248, 0, 0, '흠...'),
(25248, 1, 0, '드디어! 이 바보 같은 장난도 끝났군... 아서스 님, 제게 힘을 주소서!'),
(25248, 2, 0, '누구한테 덤비는 건지 제대로 모르는 모양이구나, $c! 죽어라!'),
(25248, 3, 0, '여기까지인가 보군. 그렇다고 내가 곱게 죽어줄 거라고는 생각지 마라!'),
(25250, 0, 0, '내게.. 대체 무슨 일이...'),
(25250, 1, 0, '으어어... 머리가 깨질 것 같아...'),
(25256, 0, 0, '우리는 포위당했네... 적이 사방에서 밀려오고 있네, 젊은 헬스크림이여.'),
(25256, 1, 0, '스컬지 놈들이 개떼처럼 북쪽에서부터 내려오는 중이네.'),
(25256, 2, 0, '얼라이언스가 이 지역으로 안전하게 수송하는 길은 단 하나뿐이네. 게다가 그마저도 저 무시무시한 안개 때문에 놓칠 위험에 처해 있지.'),
(25256, 3, 0, '재보급을 받을 수 있는 유일한 항구는 이 저주받은 대륙 반대편에 있는데, 그나마도 포세이큰이 장악했네!'),
(25256, 4, 0, '비행선으로 운반할 수 없는 물자는 여기까지 오려면 배로 길고 긴 노스렌드를 지나야 하네.'),
(25256, 5, 0, '공성 무기, 탄약, 방어구... 이런 준비도 없이 저 얼음왕관의 벽을 어떻게 무너트릴 생각인가?'),
(25256, 6, 0, '돌아온 탕아께서 계속 그렇게 말해 오셨지!'),
(25256, 7, 0, '정말 그 아버지에 그 아들이군. 헬스크림, 언제나 성급하지... 성급하고 무모해.'),
(25256, 8, 0, '자넨 그저 무조건 앞으로 달려나가는 것만 알아. 뒷일은 생각도 않고 말이지.'),
(25256, 9, 0, '자네 아버지가 마신 그 피를 나도 마셨네, 가로쉬. 저주스러운 만노로스의 독이 내 혈관을 타고 요동쳤다네.'),
(25256, 10, 0, '적의 육신과 정신, 그 모두에 내 무기를 찔러넣었지.'),
(25256, 11, 0, '그리고 그롬은 영광스러운 죽음으로써 우리 모두를 피의 저주에서 자유롭게 했지만... 과거의 끔찍한 기억까지는 씻어내지 못했지.'),
(25256, 12, 0, '그러한 그롬의 행동도 우리가 저지른 참사까지는 지울 수 없었네.'),
(25256, 13, 0, '%s|1이;가; 잠시 말을 멈춥니다.'),
(25256, 14, 0, '저주에서 벗어나고서 겨울이 닥치자, 나 같은 노련한 오크 수백 명은 절망의 늪에 빠지고 말았지.'),
(25256, 15, 0, '우리 마음은 마침내 자유를 얻었네. 그랬지... 그렇게 자유로운 마음으로, 우리가 불타는 군단에 영혼을 빼앗겼을 때 저질렀던 끔찍한 일들을 다시 떠올렸네.'),
(25256, 16, 0, '%s|1이;가; 고개를 끄덕입니다.'),
(25256, 17, 0, '노련한 오크 대부분이 절망에 빠진 이유는 드레나이 아이 목소리 때문이었네. 한 번 들으면 절대로 잊을 수 없지...'),
(25256, 18, 0, '톱니멧돼지 농장에 가 본 적 있나? 잡을 수 있을 만큼 돼지가 자랐을 때... 바로 그 소리 말일세. 돼지 멱 따는 그 소리... 엄청나게 큰 소리로 울려 퍼지는 걸세. 우리같이 나이 든 전사들에게는 정말이지 힘든 시기였지.'),
(25256, 19, 0, '%s|1이;가; 고개를 젓습니다.'),
(25256, 20, 0, '나는 지금 적의 아이들만 놓고 얘기하는 게 아닐세...'),
(25256, 21, 0, '%s|1이;가; 잠시 말을 멈춥니다.'),
(25256, 22, 0, '자네가 우리를 또다시 어둠의 길로 끌고 가도록 내버려두진 않겠네, 젊은 헬스크림. 그런 날이 오면 내 손으로 자네를 처치해 주겠네...'),
(25256, 23, 0, '돼지고기를 먹지 않는다네... 물론, 쇠고기도.'),
(25256, 24, 0, '%s|1이;가; 침을 뱉습니다.'),
(25258, 0, 0, '전선으로 떠나기 전에 마지막으로 한잔할까?'),
(25258, 1, 0, '주인장! 가장 독한 맥주를 가져오시오. 우리는 전선으로 떠나오.'),
(25258, 2, 0, '우리에게는 예외를 베풀어 주겠지? 다시 돌아오지 못할 수도 있잖아.'),
(25258, 3, 0, '그럼 이게 끝인가 보군. 이제 가자.'),
(25259, 0, 0, '그래, 안 될 것 없지.'),
(25260, 0, 0, '이봐, 다들! 기다려!'),
(25261, 0, 0, '내가 마셔 본 맥주 중 최악이었어.'),
(25288, 0, 0, '경비병!'),
(25315, 0, 0, '모든 힘을 수정구에 실었습니다! 이제 그대들의 몫입니다!'),
(25315, 1, 0, '파멸이 점점 더 가까워진다!'),
(25315, 1, 1, '아나크 키리!'),
(25315, 2, 0, '누굴 믿을 수 있겠나?'),
(25315, 2, 1, '적은 이 안에 있다!'),
(25315, 3, 0, '녀석들은 소모품일 뿐이다. 자, 봐라! 살게라스가 해내지 못한 일을 내가 해낼 것이다! 이 보잘것없는 세상을 갈가리 찢어발기고 불타는 군단의 진정한 주인으로 우뚝 서리라! 종말이 다가왔다! 어디 한번 세계를 구해 봐라!'),
(25315, 4, 0, '혼돈을!'),
(25315, 4, 1, '파괴를!'),
(25315, 4, 2, '망각!'),
(25315, 5, 0, '나를 부정할 수는 없다! 이 세계는 멸망하리라!'),
(25315, 6, 0, '헛된 꿈을 꾸고 있구나! 너흰 이길 수 없어!'),
(25315, 7, 0, '으아! 태양샘의 마력이... 나를... 거부한다! 무슨 짓을 한 거지? 무슨 짓을 한 거냐???'),
(25315, 8, 0, '킬제덴이 정신을 집중하여 암흑의 기운을 모읍니다.'),
(25317, 0, 0, '뭡니까, $c 양반? 너무 잘나셔서 우리처럼 줄은 못 서겠다 이겁니까?'),
(25319, 0, 0, '바로 지금입니다, 영웅들이여! 기만자가 약해진 틈을 타 공격하십시오!'),
(25319, 1, 0, '수정구에 힘을 쏟겠습니다! 준비하세요!'),
(25319, 2, 0, '다른 수정구에 힘을 불어넣었습니다! 어서요!'),
(25319, 3, 0, '다른 수정구가 준비됐습니다! 서두르세요!'),
(25319, 4, 0, '모든 힘을 수정구에 실었습니다! 이제 그대들의 몫입니다!'),
(25319, 5, 0, '안비나, 깨어나 줘! 네 도움이 필요해!'),
(25319, 6, 0, '이겨내야만 돼! 진정한 너 자신이 돼야만 해! 바로 지금이라고, 안비나!'),
(25319, 7, 0, '사랑해, 안비나! 내 목소리를 들어줘! 날 위해서라도 제발 돌아와! 오직 너만이 태양샘을 정화할 수 있어!'),
(25319, 8, 0, '그래, 나야 안비나! 이제 운명에 몸을 맡겨!'),
(25319, 9, 0, '안녕, 내 사랑 안비나... 그대 이름을 기억하는 이는 적겠지만, 세상을 구한 건 바로 그대야. 이제 타락은 걷혔어, 안비나... 영웅들이여, 그녀의 희생이 헛되지 않게 해 주오.'),
(25319, 10, 0, '그대들만 싸우는 게 아닙니다! 푸른용군단이 힘을 보탤 겁니다!'),
(25321, 0, 0, '절 풀어줘서 고맙습니다! 파도의 가호가 항상 함께하길 빌겠습니다.'),
(25321, 0, 1, '카스칼라는 이곳에서 일어난 일을 절대 잊지 않을 겁니다.'),
(25322, 0, 0, '도와줘서 고맙습니다, $c|1이여;여;. 조상께서 항상 보살피시길 빌겠습니다.'),
(25322, 0, 1, '고맙습니다, $c|1이여;여;. 바람과 바다가 항상 보호하시길.'),
(25380, 0, 0, '명심하시오, $n. 그 핏빛포자 가루를 사용하면 감모스에 있는 어떤 마그나타우르도 약하게 할 수 있소.'),
(25396, 0, 0, '우리 모두를 막을 수는 없습니다!'),
(25396, 0, 1, '당신들도 곧 제 뒤를 따르게 될 겁니다...'),
(25401, 0, 0, '%s|1을;를; 설치했습니다.'),
(25401, 1, 0, '폭발 5초 전...'),
(25416, 0, 0, '누가 감히 내게 덤비느냐?!'),
(25416, 1, 0, '멈춰!'),
(25416, 2, 0, '임페리안에게 휴전할 의사가 있다고 알려라. 하지만 먼저 물보라가 내 땅에서 물장난을 그만둬야 할 것이야!'),
(25416, 3, 0, '네 녀석이 지겨워지는구나. 썩 물러가라!'),
(25418, 0, 0, '그 말에... 따르겠다. 잿불바람이 내 웅덩이를 계속 끓여대지만 않는다면 휴전에 응하기로 하지.'),
(25418, 1, 0, '이제 내 앞에서 사라져라. 내 눈에 다시 띌 만큼 어리석지는 않겠지.'),
(25418, 2, 0, '잠깐... 그만해라!'),
(25428, 0, 0, '카다 누 뱃트카, 오트!'),
(25428, 0, 1, '에투 마그모스레가르, 챠!'),
(25428, 0, 2, '카가니슈!'),
(25429, 0, 0, '카다 누 뱃트카, 오트!'),
(25429, 0, 1, '에투 마그모스레가르, 챠!'),
(25429, 0, 2, '카가니슈!'),
(25432, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(25462, 0, 0, '나의 모든 것, 분노와 잔혹함과 복수를 너에게 내리노라, 선택받은 기사여. 불멸의 힘을 주었으니 스컬지의 새롭고 어두운 시대를 열어라.'),
(25462, 1, 0, '아래의 땅을 내려다보아라. 붉은십자군은 내 일을 되돌리려 발버둥 치고, 희망의 빛 예배당은 이 역병지대의 오점처럼 우리에게 맞서고 있다. 반항의 대가가 무엇인지 모두에게 보여 주어라.'),
(25462, 2, 0, '너는 나의 응징의 힘이 되리라. 네가 걷는 곳마다 파멸이 따를 것이다. 가서 네 운명을 쟁취하라, 죽음의 기사여.'),
(25478, 0, 0, '어리석은 녀석! 말리고스 님의 종은 적을 돕느니 스스로 목숨을 끊을 것이다...'),
(25478, 1, 0, '으히히히! 어디 계속해 보시지, $c! 절대로 말하지 않겠다!'),
(25478, 2, 0, '으히히하하하! 풀어줘! 난 아는 게 없어! 정말이다!'),
(25478, 3, 0, '그만! 간지러워 죽겠어, 그만해 줘. 제발...'),
(25478, 4, 0, '으히히... 알았어! 내가 졌다. 네놈들의 그 고귀하신 대마법사는 봉인된 공중 감옥에 갇혀 있다. 구하려고 해 봤자 열쇠는 살란드 님께서 직접 지니고 계시다. 네놈들은 바보짓을 하는 거야!'),
(25478, 5, 0, '후후히히히... 이봐, 난 이미 불었다고, $r! 이건 시간 낭비야...'),
(25478, 6, 0, '으히히히하하... 그마아아안! 이건 너무 비인간적이잖아! 원하는 걸 말해줬잖나... 차라리 날 죽여 줘!'),
(25504, 0, 0, '으히히히하하... 그마아아안! 이건 너무 비인간적이잖아! 원하는 걸 말해줬잖나... 차라리 날 죽여 줘!'),
(25504, 1, 0, '으히히히하하... 그마아아안! 이건 너무 비인간적이잖아! 원하는 걸 말해줬잖나... 차라리 날 죽여 줘!'),
(25504, 2, 0, '으히히히하하... 그마아아안! 이건 너무 비인간적이잖아! 원하는 걸 말해줬잖나... 차라리 날 죽여 줘!'),
(25504, 3, 0, '으히히히하하... 그마아아안! 이건 너무 비인간적이잖아! 원하는 걸 말해줬잖나... 차라리 날 죽여 줘!'),
(25504, 4, 0, '으히히히하하... 그마아아안! 이건 너무 비인간적이잖아! 원하는 걸 말해줬잖나... 차라리 날 죽여 줘!'),
(25589, 0, 0, '난 간식거리가 아니라고!'),
(25589, 1, 0, '이건 어때요? 여기서 날 내보내 주면, 당신이 생각하는 것보다 훨씬 좋은 보상을 주겠어요!'),
(25608, 0, 0, '이 순간을 위해 모든 계획을 세웠다!'),
(25608, 0, 1, '정신 바짝 차려라. 시간 낭비 말고!'),
(25608, 0, 2, '나는 충분히 기다렸다!'),
(25608, 0, 3, '나를 실망시키면 영원히 고통받으리라!'),
(25608, 0, 4, '저 소녀를 빨아들여라! 빈 껍데기만 남을 때까지 힘을 모조리 빼앗아!'),
(25610, 0, 0, '놈들이 나를 괴물로 만들지 못하게 막아주시오!'),
(25610, 0, 1, '죽여... 날 당장 죽이란 말이다!'),
(25610, 0, 2, '누가 제발... 도와주시오...'),
(25610, 0, 3, '놈들이 나를 괴물로 만들지 못하게 막아주시오!'),
(25610, 1, 0, '마침내 풀려났다! 당장 전쟁노래 요새로 돌아가야겠소!'),
(25610, 1, 1, '이 빚은 두고두고 갚겠소, 동지.'),
(25610, 1, 2, '고맙소, 친구여.'),
(25610, 1, 3, '그대에게 감사를 드리오, 이방인.'),
(25618, 0, 0, '이게 전부인가? 위대한 호드가 모을 수 있는 병력이 고작 이것뿐이란 말인가?'),
(25618, 1, 0, '오, 이런 너무 애처롭군.'),
(25618, 2, 0, '너 같은 녀석들을 도저히 이해할 수 없더군. 영웅놀이나 하는 녀석들...'),
(25618, 3, 0, '왜 순리에 따르지 않는 건가? 왜 운명에 맞서려는 거지?'),
(25618, 4, 0, '리치 왕을 막을 수는 없다. 포기해라.'),
(25618, 5, 0, '이 세상은 종말을 맞을 것이다. 불타게 두란 말이다.'),
(25618, 6, 0, '이 $g녀석:여자;의 시체를 가져가서 되살려낼 준비를 해라.'),
(25618, 7, 0, '이게 무슨 일이지?'),
(25618, 8, 0, '정녕 그렇다면 네놈은 바보로구나.'),
(25618, 9, 0, '네가? 오크 혼자서 말이냐? 나에게 대적하겠다니...'),
(25618, 10, 0, '일어나라!'),
(25618, 11, 0, '저것들을 모두 되살려 리치 왕님의 종으로 삼겠다! 이리 가져와라...'),
(25678, 0, 0, '오, 좋아... 재료가 생겼군!'),
(25678, 0, 1, '다 됐다!'),
(25678, 0, 2, '애송이 녀석이군!'),
(25678, 0, 3, '내장은 어떻게 처리해 줄까!'),
(25678, 0, 4, '안 좋아... 너부터 손을 좀 봐야겠군.'),
(25678, 0, 5, '산 자여, 저주를 받아라!'),
(25678, 0, 6, '학자님이 오셨다!'),
(25682, 0, 0, '우리를 막을 순 없다!'),
(25697, 0, 0, '얼음 기둥이 녹아 내렸다!'),
(25729, 0, 0, '올 것이 왔군, $n. 종말의 시작이지. 자네도 직접 목격하게 된 걸세...'),
(25729, 1, 0, '가세나...'),
(25729, 2, 0, '미... 믿을 수 없군요... 사울팽 님... 당신과 함께 싸울 수 있어 참으로 여... 영광이었습니다, 대군주여...'),
(25729, 3, 0, '자네는 전쟁노래 요새로 돌아가야 하네. 헬스크림 님께서 이곳에서 일어난 일을 분명히 알고 싶어하실 걸세. 그리고 사울팽 님께도 무슨 일이 일어났는지도 말이야...'),
(25740, 0, 0, '얼음 기둥이 녹아 내렸다!'),
(25740, 1, 0, '아훈, 네 힘은 더 커지지 못한다!'),
(25740, 2, 0, '얼어붙은 통치의 시대는 오지 않을 것이다!'),
(25740, 3, 0, '대지 고리회가 공격을 펼치기 시작합니다.'),
(25740, 4, 0, '아훈이 물러납니다. 막아내는 힘이 약해집니다.'),
(25740, 5, 0, '아훈은 잠시 후에 다시 나타납니다.'),
(25751, 0, 0, '$n의 몸에 손끝 하나 대기도 전에 네 오그라든 심장을 내 손으로 열어주마, 강령술사여.'),
(25751, 1, 0, '자넨 절대 혼자가 아니었다네, $n.'),
(25751, 2, 0, '네가 파괴하려는 이 땅은 우리의 고향이다.'),
(25751, 3, 0, '우리의 육체가 먼지와 부스러기만 남을 때까지 모든 힘을 다해 싸울 것이다. 끝까지 싸울 것이야.'),
(25751, 4, 0, '너는 곧 그 바보의 손에 죽게 될 거다, 강령군주여. 리치 왕이 살려낼 수도 없을 정도로 완전히 박살 내 주마!'),
(25751, 5, 0, '%s의 눈빛이 일순간 붉게 달아오릅니다.'),
(25751, 6, 0, '고작 이 정도냐?'),
(25751, 7, 0, '나에 대해서는 입도 뻥긋하지 말아야 할 걸세. 자네도 마찬가지야!'),
(25753, 0, 0, '경보 발령! 경보 발령! 침입자 발견! 침입자 발견!'),
(25753, 0, 1, '적 감지. 아군으로 편입 혹은 제거.'),
(25753, 0, 2, '대응 절차 시작. 침입자 제거.'),
(25758, 0, 0, '하늘을 나는 $r|1이;가; 온다! 맞춰서 떨어트려!'),
(25773, 0, 1, '살았다! 내 몸을 다시 찾았어!'),
(25773, 0, 2, '난... 사실... 기계노움이 마음에 들었는데!'),
(25773, 0, 3, '여기가 어디야? 당신 누구죠? 이 이상한 느낌은 뭐지?'),
(25773, 0, 4, '내 몸이 돌아왔다! 고마워요, $c님!'),
(25783, 0, 0, '다시 피와 살로 이루어진 노움이 되다니! 기분 좋군요!'),
(25802, 0, 0, '감히 이 매머드 학살자 카우에게 도전하겠다고? 내 분노를 느껴 보아라!'),
(25804, 0, 0, '내 귀를 먹게 할 속셈인가? 애처로운 시도로군... 잠깐... 이게 무슨 소리지?'),
(25806, 0, 0, '이게 바로 진정한 재미지!'),
(25806, 0, 1, '죽여, 죽여, 죽여어어어!!!'),
(25806, 0, 2, '헤멧이 네 뼈를 어딘가 유용하게 써먹을 거다!'),
(25806, 0, 3, '포기해라, 하찮은 짐승아!'),
(25806, 0, 4, '발굽 50개만 더 모으면 새 총을 가질 수 있어!'),
(25806, 0, 5, '말도 안 돼! 코뿔소 머리 30개에 코뿔소 보호모 하나를 주는 게 아주, 아주 싼 가격이라고? 두 개는 받아야겠소!'),
(25806, 0, 6, '네싱워리가 네 가죽을 몇 푼이나 쳐 줄지 궁금하군!'),
(25806, 0, 7, '오늘 저녁거리는 네 녀석이다!'),
(25806, 0, 8, '이런 식으로 하면 네싱위리는 파산하고 말 걸! 레인은 자기가 뭘 하는지도 모르는 게야!'),
(25814, 1, 1, '우리는 기계노움이다... 저항은 무의미하다.'),
(25814, 1, 2, '육체는 약하다. 우리가 너를 보다 강하고... 빠르게 바꿔 주마.'),
(25814, 1, 3, '저주를 풀어 주마. 우리에게는 기술이 있으니까.'),
(25827, 0, 0, '흠...'),
(25827, 1, 0, '드디어! 이 바보 같은 장난도 끝났군... 아서스 님, 제게 힘을 주소서!'),
(25827, 2, 0, '누구한테 덤비는 건지 제대로 모르는 모양이구나, $c! 죽어라!'),
(25827, 3, 0, '여기까지인가 보군. 그렇다고 내가 곱게 죽어줄 거라고는 생각지 마라!'),
(25828, 0, 0, '흠...'),
(25828, 1, 0, '드디어! 이 바보 같은 장난도 끝났군... 아서스 님, 제게 힘을 주소서!'),
(25828, 2, 0, '누구한테 덤비는 건지 제대로 모르는 모양이구나, $c! 죽어라!'),
(25828, 3, 0, '여기까지인가 보군. 그렇다고 내가 곱게 죽어줄 거라고는 생각지 마라!'),
(25830, 0, 0, '트웡키!'),
(25831, 0, 0, 'ED-210 작동 개시!'),
(25832, 0, 0, '나는 메카조드 님이 보낸 전령이다. 네게 걸린 저주를 풀어주마!'),
(25833, 0, 0, '쓸데없는 참견도 이걸로 끝이다. 내가 널 쓰러뜨리고 나면 메카조드 님이 저주를 풀어주실 것이다.'),
(25834, 0, 0, '아이야, 나를 찾고 있었느냐? 왜 나를 죽이려 하느냐, $n? 난 단지 도우려는 것뿐인데.'),
(25834, 1, 0, '내가 다시 조립되었으니 우리는 완벽의 시대로 돌아갈 수 있다... 티탄의 시대로 말이다!'),
(25834, 2, 0, '하지만, 네 눈을 보고 네 맥박을 들으니 알겠구나. 너는 내가 약속한 영생을 뿌리치고 날 파괴할 작정임을 말이다!'),
(25834, 3, 0, '좋다. 일이 이렇게 되어 슬프구나. 너희를 모두 내 자식처럼 생각했건만... 그래야만 한다면, 죽여 주마!'),
(25849, 0, 0, '이번엔 분명히 작동할 거야... 그렇지?'),
(25849, 1, 0, '작동하는군요, 도레인! 진짜로 작동한다고요!'),
(25849, 2, 0, '간다아아아아아!!!!!!'),
(25849, 3, 0, '으악!'),
(25849, 4, 0, '집어치워! 고블린 발명품은 이제 지긋지긋해!'),
(25885, 0, 0, '이봐요, 선구자 씨, 조사는 어떻게 진행되고 있나요? 당신이 그 결과를 일러주기만 하면 와플제 초강력 다리미를 드릴 수도 있는데!'),
(25885, 1, 0, '놀랍기 그지없는 얼룩 제거용 정전기학 광선총을 동네에서 제일 먼저 소유하는 기쁨을 누리시죠!'),
(25885, 2, 0, '이 광선총은 무너진 태양 공격대의 최첨단 군사학 기술을 이용한 거고요, 아무리 오래 찌든 때라도 단번에 날려버린답니다!'),
(25885, 3, 0, '포도주 흘린 자국, 풀물, 심지어 애완동물 배설물 자국도 얼룩 제거용 정전기학 광선총 앞에선 상대가 안 되죠!'),
(25885, 4, 0, '자, 망설이지 마세요! 지금 당장 주문하시면 제가 만든 와플제 초강력 다리미를 끼워드리죠!'),
(25979, 0, 0, '이게 바로 진정한 재미지!'),
(25979, 0, 1, '죽여, 죽여, 죽여어어어!!!'),
(25979, 0, 2, '헤멧이 네 뼈를 어딘가 유용하게 써먹을 거다!'),
(25979, 0, 3, '포기해라, 하찮은 짐승아!'),
(25979, 0, 4, '발굽 50개만 더 모으면 새 총을 가질 수 있어!'),
(25979, 0, 5, '말도 안 돼! 코뿔소 머리 30개에 코뿔소 보호모 하나를 주는 게 아주, 아주 싼 가격이라고? 두 개는 받아야겠소!'),
(25979, 0, 6, '네싱워리가 네 가죽을 몇 푼이나 쳐 줄지 궁금하군!'),
(25979, 0, 7, '오늘 저녁거리는 네 녀석이다!'),
(25979, 0, 8, '이런 식으로 하면 네싱위리는 파산하고 말 걸! 레인은 자기가 뭘 하는지도 모르는 게야!'),
(25983, 0, 0, '페직스, 그 작은 엔진 문제를 우리가 해결한 것 같소.'),
(26045, 0, 0, '넌 날 지배할 수 없다, 하찮은 $r|1이여;여;!'),
(26073, 0, 0, '누가 나의 명상을 방해하느냐?'),
(26076, 0, 0, '웬 놈이냐?! 만찬을 즐기던 중이었는데!'),
(26097, 0, 0, '구해주셔서 고맙습니다. 저희는 우연히 톱니반장 메카조드의 조각을 발견해서 다시 조립해냈습니다.'),
(26097, 1, 0, '그 보답으로 그는 소위 ''저주''를 풀어줬어요. 우리를 ''고쳐''서 기계 상태로 되돌린다면서 말이에요.'),
(26097, 2, 0, '그는 티탄의 모든 창조물이 ''육체의 저주''에 걸린 거라고 주장하더군요. 태초의 노움은 기계노움이라나요.'),
(26097, 3, 0, '그놈은 완전히 정신이 나갔습니다! 너무 늦기 전에 누군가 나서서 놈을 막아야 합니다!'),
(26165, 0, 0, '죽음은 네가 겪을 고통의 시작일 뿐이다.'),
(26170, 0, 0, '레리사!'),
(26170, 1, 0, '내 동생에게 무슨 짓을 한 거냐, 이 사악한 엘프 자식아?!'),
(26170, 2, 0, '차라리 혀를 깨물겠다. 이 쓰레기 같은 놈... 넌 부하들을 배신했어, 아서스! 맹세코 널 가만두지 않겠다!'),
(26170, 3, 0, '레리사! 너, 너 괜찮니?'),
(26170, 4, 0, '아직은 너와 함께 돌아갈 수 없어, 레리사. 난 스컬지와 볼일이 남았거든.'),
(26170, 5, 0, '네 말이 맞을지도 모르지. 난 조국에 대한 임무는 끝냈다. 하지만 아직 나 자신에게 빚진 게 있어.'),
(26170, 6, 0, '걱정하지 마, 레리사. 무슨 일이 있어도 난 돌아갈 거다. 넌 세상에 단 하나 남은 내 가족이니까.'),
(26179, 0, 0, '승리가 아니면 죽음뿐! 호드를 위하여!'),
(26184, 0, 0, '승리가 아니면 죽음뿐! 호드를 위하여!'),
(26196, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(26199, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(26203, 0, 0, '발라나르, 여기 임무를 훌륭히 수행하고 있군. 무척 기쁘구나.'),
(26203, 1, 0, '호, 이것 참 놀랍군, 타사리안. 모그레인이나 다른 죽음의 기사들은 몇 달째 소식이 없는데. 다시 스컬지에 돌아오겠다는 의사로 받아들여도 되겠나?'),
(26203, 2, 0, '날 실망시키지 마라, 산레인. 이 멍청이의 머리를 손에 넣기 전에는 얼음왕관으로 돌아오지 마라.'),
(26287, 0, 0, '텔잔의 성물함이 얼음폭풍의 발밑에 떨어집니다.'),
(26293, 0, 0, '덩치 큰 요르문가르가 입을 크게 벌린 채 잠시 비틀거립니다.'),
(26321, 0, 0, '%s|1이;가; 감사의 뜻을 표합니다.'),
(26334, 0, 0, '피조물들이여, 목숨을 걸고 수도를 방어하라!'),
(26334, 0, 1, '싸워라, 아이들아! 한 치도 봐주지 마라!'),
(26334, 0, 2, '바위의 후손을 뭉개버려라, 무쇠 형제들아!'),
(26334, 0, 3, '영주님을 위하여! 로켄을 위하여!'),
(26417, 0, 0, '다 끝났다고 생각했는데... 날 풀어주어 고맙다.'),
(26417, 0, 1, '그대에게 감사의 말을 전한다.'),
(26417, 0, 2, '그 끔찍한 주문에서 해방될 줄은 꿈에도 몰랐다!'),
(26417, 0, 3, '고맙다, 작은 존재여.'),
(26420, 0, 0, '아, 그래. 로켄이라면 잘 안다.'),
(26420, 1, 0, '우리에 대항해 싸우는 전쟁에서 무쇠의 후예를 지휘하는 존재가 바로 그놈이다.'),
(26420, 2, 0, '그놈은 바위 거인을 파멸시키려는 목적으로 은신처에 숨어서 전쟁을 준비하고 있다!'),
(26421, 0, 0, '%s|1이;가; 당신의 요청에 화를 내더니 공격합니다!'),
(26421, 1, 0, '%s|1이;가; 떠나기 전 자신의 껍질을 조금 뜯어내더니 당신에게 건넵니다.'),
(26484, 0, 0, '녀석도 날 잡으러 온 거요! 나 같으면 좀 더 조심하겠소, 여행자 양반. 녀석이 어느 나무 뒤에 숨어 있을지 모르니까 말이오!'),
(26484, 1, 0, '림피 조가 할 것 같은 질문은 아닌데! 하지만 내가 로켄에 대해 아는 건 확실하지.'),
(26484, 2, 0, '세상에, 림피 조를 죽이고 고기를 가져오다니! 우리가 여기 있는 줄은 어떻게 알았소?'),
(26484, 3, 0, '당신도 날 죽이러 온 거라면 그리셀다에게 뭔가를 먹일 때까지 좀 기다려 주지 않겠소? 불쌍하게도 벌써 며칠째 아무것도 먹지 못했다오.'),
(26484, 4, 0, '자, 먹어라. 마지막으로 주는 식사로구나! 곧 림피 조를 죽인 자가 나 또한 끝장낼 테니 말이다...'),
(26484, 5, 0, '어떻게 그 불쌍하고 힘없는 늙은 조를 죽일 수가 있소? 그리고 그 고기는 대체 왜 가져온 거요?'),
(26484, 6, 0, '알 수 없는 친구로군... 그리고 말해 두지만, 난 알 수 없는 친구와 엮이고 싶지 않소...'),
(26484, 7, 0, '그리셀다가 후식을 찾기 전에 어서 떠나는 게 좋을 거요.'),
(26484, 8, 0, '일어나시오, 그리셀다. 이쪽이라오.'),
(26484, 9, 0, '우리가 여기 있는 줄 절대 모를 거요, 그렇지 않소? 림피 조와 플라넬 맥기처럼 잡혀갈 순 없어!'),
(26484, 9, 1, '안 돼! 우린 저 괴물들한테서 도망친 거라고! 저것들은 우리랑은 다르다오, 그리셀다.'),
(26484, 9, 2, '당신과 난 사냥꾼이오. 늑대인간은 여기 없소. 없고말고.'),
(26484, 9, 3, '눈을 떼지 마시오! 절대로 잡혀선 안 되오!'),
(26499, 0, 0, '드디어 나타나셨군, 우서.'),
(26499, 1, 0, '어찌 그걸 잊겠습니까. 잘 들으세요, 우서. 역병에 대해 얘기할 게 있습니다.'),
(26499, 2, 0, '안 돼... 너무 늦었어. 사람들이 모두 감염돼 버렸군! 지금은 괜찮아 보일지 모르지만, 언데드로 변하는 것은 시간문제입니다!'),
(26499, 3, 0, '도시 전체를 쓸어버려야 합니다.'),
(26499, 4, 0, '닥치시오, 우서! 미래의 왕인 내 명에 따라, 이 도시를 정화하시오!'),
(26499, 5, 0, '명을 따르지 않는다면 반역으로 받아들이겠소.'),
(26499, 6, 0, '내가? 우서 경, 정당하고도 확고한 내 왕위 계승권에 따라 명한다. 지금부터 그대의 지휘권을 박탈하고 그대의 성기사들에게 근신 조치를 내리노라.'),
(26499, 7, 0, '그만! 이 땅을 구할 의지와 용기가 있는 자는 나를 따르라! 그렇지 않다면... 내 눈앞에서 사라져라!'),
(26499, 8, 0, '제이나?'),
(26499, 9, 0, '여기서 대기하라. 내가 먼저 소규모 부대를 이끌고 스트라솔름에 들어가겠다. 로데론의 모든 이를 위해, 감염자를 격리하고 처치해야 한다!'),
(26499, 10, 0, '준비가 된 것 같군. 명심해라. 이들은 끔찍한 역병에 걸렸고, 어차피 죽을 것이다. 스컬지의 손아귀에서 로데론을 지키려면 스트라솔름을 정화해야 한다. 가자.'),
(26499, 11, 0, '그대를 도울 길은 이것뿐이라네.'),
(26499, 12, 0, '이건 시작일 뿐이다...'),
(26499, 13, 0, '그렇게 둘 것 같으냐! 죽어서 네놈의 노예가 되게 하느니 차라리 내 손으로 죽일 것이다!'),
(26499, 14, 0, '말가니스는 우리를 방해하려고 스컬지 부하들을 보낼 것이다. 너희 중 강한 힘과 마력을 지닌 이가 나서서 상대해야 한다. 나는 나머지 병력을 이끌고 감염자를 처리하겠다.'),
(26499, 15, 0, '용사들이여, 당장 마을회관으로 집결해라. 말가니스를 상대해야 한다.'),
(26499, 16, 0, '나를 따르라. 내가 인도하겠다.'),
(26499, 17, 0, '그래. 나도 자네를 구할 수 있어 기쁘네.'),
(26499, 18, 0, '이건 무슨 조화지?'),
(26499, 19, 0, '이건 스컬지가 아닌데... 대체 무슨 수작이지? 어쨌든 서두르자!'),
(26499, 20, 0, '사악한 놈들이 더 있군! 전투를 준비해라!'),
(26499, 21, 0, '움직이자.'),
(26499, 22, 0, '뒤를 조심해라. 놈들은 우릴 포위하고 있어.'),
(26499, 23, 0, '장애물이 하나 줄었군.'),
(26499, 24, 0, '말가니스가 잔꾀를 부리는군.'),
(26499, 25, 0, '바퀴벌레 같은 놈들...'),
(26499, 26, 0, '이젠 어떻게 방해할 작정이지?'),
(26499, 27, 0, '난 로데론을 지킬 뿐이다. 네가 무슨 짓을 해도 날 막을 수는 없어.'),
(26499, 28, 0, '저 책장 뒤에, 말가니스에게 가는 지름길이 있다.'),
(26499, 29, 0, '오래 걸리진 않을 것이다.'),
(26499, 30, 0, '비밀 통로가 남아 있어 다행이군.'),
(26499, 31, 0, '되도록 빨리 빠져나가야겠군. 언데드에게 죽지 않아도 불에 타 죽게 생겼어.'),
(26499, 32, 0, '잠시 쉬며 숨을 돌려라. 하지만 곧 이동해야 한다.'),
(26499, 33, 0, '그만! 이제 움직이자. 말가니스가 기다리고 있다.'),
(26499, 34, 0, '그나마 낫군. 상가에는 아직 불길이 번지지 않았다. 말가니스는 저 너머 십자군 광장에 있을 것이다. 이동할 준비가 되면 내게 보고해라.'),
(26499, 35, 0, '정의는 실현될 것이다.'),
(26499, 36, 0, '이제 결판을 낼 때다, 말가니스! 너와, 내가 말이다...'),
(26499, 37, 0, '세상 끝까지라도 널 쫓아갈 것이다! 들리나? 끝까지 말이다!'),
(26499, 38, 0, '오늘 큰 공을 세웠군. 말가니스가 남긴 건 모두 너희 것이다. 보상으로 받아 둬라. 난 이제 노스렌드 원정 준비를 시작해야겠다.'),
(26500, 0, 0, '여기서 기다리겠다.'),
(26528, 0, 0, '말조심하게, 젊은이. 자네가 왕자일지언정, 나는 성기사로서 자네 상관일세!'),
(26528, 1, 0, '뭐지?'),
(26528, 2, 0, '어떻게 그런 말을 할 수 있나? 다른 방법이 있을 걸세.'),
(26528, 3, 0, '자넨 아직 내 왕이 아닐세! 설령 왕이었다 한들 그런 명령은 따를 수 없네!'),
(26528, 4, 0, '반역이라고? 자네 미쳤나, 아서스?'),
(26528, 5, 0, '자네는 넘지 말아야 할 선을 넘었네, 아서스.'),
(26529, 0, 0, '놀 시간이다!'),
(26529, 1, 0, '지루해!'),
(26529, 1, 1, '이거, 고장 났나?'),
(26529, 1, 2, '일어나! 나 더 놀래!'),
(26529, 2, 0, '새 장난감이다!'),
(26529, 3, 0, '이건... 재미 없다...'),
(26530, 0, 0, '아, 재미있는 일이 벌어지겠군!'),
(26530, 1, 0, '너무 늦었군, 로데론의 용사여. 오늘은 죽은 자의 잔칫날이다.'),
(26530, 2, 0, '이제부터가 즐거울 거다!'),
(26530, 2, 1, '아! 괜찮은 물건인데.'),
(26530, 2, 2, '걱정하지 마라. 내가 잘 써먹어 주지!'),
(26530, 3, 0, '넌 주인님의 계획을... 따르고 있을 뿐...'),
(26530, 4, 0, '뻥! 으하하하하하...'),
(26530, 4, 1, '피... 파괴... 상쾌하군!'),
(26530, 5, 0, '좋은 견본이군...'),
(26530, 5, 1, '그 힘은... 내가 가질 거야!'),
(26530, 5, 2, '육신이 널 배반하리라...'),
(26530, 6, 0, '내 구울 친구를 소개합니다!'),
(26530, 6, 1, '스트라솔름의 시민 여러분! 구세주랑 인사해야지...'),
(26531, 0, 0, '%s|1이;가; 제겐의 칼에 반사되는 햇살을 보고 넋을 잃습니다.'),
(26531, 1, 0, '%s|1이;가; 정박 중인 배로 시선을 돌리며 시끄럽게 울어댑니다.'),
(26532, 0, 0, '아서스 메네실 왕자, 오늘 엄청난 암흑이 네 영혼을 사로잡았다. 네가 다른 이에게 안겨주려고 했던 죽음은, 오늘 널 찾아올 것이다.'),
(26532, 1, 0, '두고 보면 알겠지, 젊은 왕자여.'),
(26532, 2, 0, '똑딱똑딱...'),
(26532, 2, 1, '아직 너무 느려!'),
(26532, 2, 2, '어서 끝내기로 하지.'),
(26532, 3, 0, '너에게 미래 따윈 없다.'),
(26532, 3, 1, '크나큰 승리가 눈앞에 다가왔다!'),
(26532, 3, 2, '너는 실패할 운명이다.'),
(26533, 0, 0, '그렇다. 이건 시작일 뿐이지. 널 기다리고 있었다, 젊은 왕자여. 나는 말가니스다.'),
(26533, 1, 0, '보다시피 네 백성은 이제 내 손에 들어왔다. 이 도시의 모든 집을 하나씩 하나씩 찾아가 주마. 생명의 불씨가 영원히 꺼질 때까지...'),
(26533, 2, 0, '실력이 얼마나 되는지 보자, 아서스 왕자.'),
(26533, 3, 0, '흠, 이거 실망인데...'),
(26533, 3, 1, '어둠의 군주는 귀찮게 구는 녀석을 싫어하지.'),
(26533, 3, 2, '나는 아서스 왕자를 원한다. 네가 아니라...'),
(26533, 4, 0, '아나크 키리!'),
(26533, 4, 1, '붉은돌격대가 리치 왕의 군대를 쓸어버릴 것이다!'),
(26533, 4, 2, '헛된 죽음이로다, 필멸의 존재여.'),
(26533, 4, 3, '너에게 주어진 시간은 끝났다.'),
(26533, 5, 0, '쉴 때다.'),
(26533, 5, 1, '피곤해 보이는데?'),
(26533, 6, 0, '으으으으아! 저 약한 몸뚱이 안에 너무 오래 있었어!'),
(26533, 7, 0, '키렐 나라크! 나는 말가니스다. 나는 불멸이다!'),
(26533, 8, 0, '그만! 시간 낭비만 했군. 돌아가서 힘을 다시 모아야겠다.'),
(26533, 9, 0, '내 도움 없이 리치 왕을 물리칠 수 있을 것 같으냐? 나는 복수할 것이다... 녀석에게도, 너희에게도!'),
(26533, 10, 0, '너의 여정은 이제 막 시작이다, 젊은 왕자여. 병사들을 모아 극한의 땅, 노스렌드로 나를 찾아와라. 그곳에서 모든 일이 결판날 것이다. 네 진정한 운명도 그곳에서 시작되지.'),
(26537, 0, 0, '전쟁노래 요새로 가는 비행선이 방금 도착했습니다! 북풍의 땅으로 가시는 분들은 모두 타세요!'),
(26566, 0, 0, '경비병!'),
(26588, 9, 0, '야영지가 보이는 것 같아요! 이제 거의 다 왔어, 깡총 군! 어서 가자!'),
(26588, 10, 0, '야영지가 보이는 것 같아요! 이제 거의 다 왔어, 깡총 군! 어서 가자!'),
(26593, 0, 0, '완벽하군. 닥치는 대로 베고 쓰러트리며 다니지만 않으면 놈들은 차이를 알아채지 못할 거요.'),
(26602, 0, 0, '경비병!'),
(26604, 0, 0, '수컬지 트롤들이 불타고 있네...'),
(26604, 1, 0, '... 뜨거운 불 위에...'),
(26604, 2, 0, '끝입니다! 지금까지 쓴 내용이에요... 어떤가요?'),
(26626, 0, 0, '일어나라, 용사들이여! 너희의 새로운 주인을 위해 싸워라!'),
(26626, 1, 0, '놈들을 즐겁게 해 줘라. 리치 왕께서 보고 계신다!'),
(26626, 2, 0, '그렇게 기를 쓰고 달아나지 마라! 네놈들에게 줄 작별 선물이 있다...'),
(26630, 0, 0, '배고프다! 목마르다! 밥 내놔!'),
(26630, 1, 0, '좀 이따 슥슥 해서 꿀꺽!'),
(26630, 2, 0, '너무 배고파! 밥 줘!'),
(26630, 3, 0, '터져라, 뻥!'),
(26631, 0, 0, '견딜 수 없는 한기가 죽음을 몰고 오리니.'),
(26631, 1, 0, '와서 나를 보호해라! 어서! 망할 놈들아!'),
(26631, 2, 0, '부질없는 짓인 줄 잘 알고 있겠지!'),
(26631, 2, 1, '그냥 단념하고 목숨을 바쳐라!'),
(26631, 3, 0, '이래 봤자... 아무 소용없다.'),
(26631, 4, 0, '리치 왕께 맞서는 자는 이런 운명을 맞게 되지!'),
(26631, 5, 0, '%s|1이;가; 부하들을 부릅니다!'),
(26632, 0, 0, '타론자는 모든 걸 안다! 필멸자 따위가 불멸의 제국을 무너뜨릴 수는 없어!'),
(26632, 1, 0, '타론자가 예언한 대로!'),
(26632, 1, 1, '이미 정해진 대로!'),
(26632, 2, 0, '네 육신은 이제 타론자 거다!'),
(26632, 2, 1, '연약한 껍데기도 써먹을 데가 있지!'),
(26632, 3, 0, '안 돼! 너무... 너무 짧았어!'),
(26632, 3, 1, '아아악! 타론자는 더 빼앗을 테다!'),
(26632, 4, 0, '으으... 이럴 수가! 타론자는 불멸이란 말이다! 타론자는...'),
(26635, 0, 0, '지원군! 지원군이 필요하다!'),
(26635, 1, 0, '도와줘! 저들은 수가 너무 많다!'),
(26648, 4, 0, '이 말을 무시하고 물에 뛰어들지 않으면 무슨 일이 일어날지 꽤 궁금하군요.'),
(26654, 0, 0, '일어나라, 형제여... 일어나라... 일어나서 다시 한 번 싸워라.'),
(26660, 0, 0, '시간이 됐군! 어서 목재를 챙겨서 이동하라고. 아무리 호드라도 세상 끝날 때까지 싸우진 않을 거란 말이지. 돈을 벌 때는 바로 지금이라고!'),
(26666, 0, 0, '칼을 거두십시오, 족장님. 어쩌면 우리에게 도움이 될지도 모릅니다.'),
(26666, 1, 0, '이전에 발견한 드워프 일지 기억나십니까? 어쩌면 이 드워프는 브란 브론즈비어드를 생포하는 데 반드시 필요한 인물일지도 모릅니다.'),
(26666, 2, 0, '험한 꼴을 보고 싶지 않거든 협조하는 게 좋을 거다.'),
(26666, 3, 0, '이 정도면 되겠지요, 족장님?'),
(26687, 0, 0, '여기가 어디지? 나... 너희... 밟아주마!'),
(26687, 1, 0, '너 죽어라! 주인님께서 원하신다.'),
(26687, 1, 1, '쉬운 일이지!'),
(26687, 2, 0, '릴스 브와, 우나트 프쉬 자.'),
(26693, 0, 0, '웬 놈들이 감히 여길? 정신 차려라, 형제들아! 녀석들을 처치하면 거하게 한 상 차려 주마!'),
(26693, 1, 0, '뮬 나 울 크발!'),
(26693, 1, 1, '이젠 겁이 좀 나나 보군...'),
(26693, 1, 2, '첨탑 꼭대기에 매달아 주마!'),
(26693, 2, 0, '으아아! 그딴 걸... 공격이라고... 내가 제대로... 으아아아...'),
(26693, 3, 0, '브리쿨 전사를 불렀는데, 웬 코흘리개들만 싸우러 오느냐! 이미론의 이름으로, 저들을 처치해라!'),
(26693, 4, 0, '한 번만 더 내 비룡에게 작살을 던졌다간 뼈도 못 추릴 줄 알아라!'),
(26693, 5, 0, '피도 눈물도 없는 것들아! 불쌍한 비룡을 괴롭히다니, 가만두지 않겠다!'),
(26763, 0, 0, '혼돈이 손짓한다.'),
(26763, 1, 0, '네, 여기 있습니다.'),
(26763, 2, 0, '실재가... 무너진다.'),
(26763, 3, 0, '파괴할 수 없다.'),
(26763, 4, 0, '%s|1이;가; 혼돈의 균열을 엽니다!'),
(26763, 5, 0, '%s|1이;가; 보호막을 치고 균열에 힘을 집중합니다!'),
(26794, 0, 0, '안 돼!'),
(26794, 1, 0, '으아아아아!'),
(26794, 2, 0, '돌아가!'),
(26794, 3, 0, '피 흘려라!'),
(26794, 4, 0, '죽어라!'),
(26796, 0, 0, '뭐지? 여긴 대체... 제군들, 놀지 말라고! 뭐라도 해치워!'),
(26796, 1, 0, '이제 뭐가 좀 되는군!'),
(26796, 2, 0, '고작 그 정도... 냐...'),
(26798, 0, 0, '이건 뭐지? 모크토린 카! 혼내 줘라!'),
(26798, 1, 0, '임무는 아직 끝나지 않았다!'),
(26798, 2, 0, '으아아...'),
(26811, 0, 0, '이제 영원히 잠들 수 있어...'),
(26811, 0, 1, '드디어 쉴 수 있겠구나...'),
(26811, 0, 2, '마침내 자유로군.'),
(26811, 0, 3, '내 미라는 어디 있지?'),
(26812, 0, 0, '이제 영원히 잠들 수 있어...'),
(26812, 0, 1, '드디어 쉴 수 있겠구나...'),
(26812, 0, 2, '마침내 자유로군.'),
(26812, 0, 3, '내 미라는 어디 있지?'),
(26814, 0, 0, '걱정하지 마시오. 내 뒤에 숨어 있으면 안전할 거요.'),
(26814, 1, 0, '의식의 방이군. 내가 제물이 될 예정이었던...'),
(26814, 2, 0, '이제 끝을 볼 때도 됐지!'),
(26814, 3, 0, '이제 가셔도 됩니다, 아가씨.'),
(26814, 4, 0, '이상하군. 보통 이렇게 하면 되는데.'),
(26814, 5, 0, '뭐, 잘 됐군. 안 그래도 이곳은 지긋지긋했으니 말이오.'),
(26814, 6, 0, '이게 뭐지?'),
(26814, 7, 0, '으으, 뱀은 싫은데!'),
(26814, 8, 0, '잘 들으시오, 젊은이. 이건 나 혼자서도 해결할 수 있는 일이라오. 그러니 내 뒤나 잘 봐주시오!'),
(26814, 9, 0, '또 봅시다, 젊은이!'),
(26815, 0, 0, '네 녀석은 북쪽으로 오는 배를 타지 않았어야 했어!'),
(26817, 0, 0, '노움 흉내를 내는 그놈들을 고철 조각으로 만들어 버리겠어요!'),
(26817, 0, 1, '뭐라고요? 다시 거기로 가란 말입니까?'),
(26844, 0, 0, '경비병!'),
(26845, 0, 0, '경비병!'),
(26846, 0, 0, '경비병!'),
(26847, 0, 0, '경비병!'),
