(26852, 0, 0, '경비병!'),
(26853, 0, 0, '경비병!'),
(26861, 0, 0, '검은 폭풍의 비요른이여! 그대의 존재로 저를 축복하소서!'),
(26861, 1, 0, '검은 폭풍의 비요른이여! 그대의 존재로 저를 축복하소서!'),
(26861, 1, 1, '검은 폭풍의 비요른이여! 그대의 존재로 저를 축복하소서!'),
