(26861, 2, 0, '검은 폭풍의 비요른이여! 그대의 존재로 저를 축복하소서!'),
(26861, 3, 0, '검은 폭풍의 비요른이여! 그대의 존재로 저를 축복하소서!'),
(26861, 4, 0, '검은 폭풍의 비요른이여! 그대의 존재로 저를 축복하소서!'),
