(26881, 0, 0, '경비병!'),
(26893, 0, 0, '%s|1이;가; 숨을 깊게 들이마십니다.'),
(26893, 1, 0, '학살자 스카디가 작살 발사대의 사정거리 안에 들어왔습니다!'),
(26902, 0, 0, '감히 대가도 없이 나를 불러냈단 말이냐!'),
(26920, 0, 0, '이런 짓을 저지른 대가를 치르게 해주마!'),
(26920, 0, 1, '어리석은 놈! 너는 절대 도망칠 수 없다!'),
(26920, 0, 2, '감히 무쇠의 후예에게 덤빈단 말이냐?'),
(26920, 0, 3, '네가 무슨 짓을 저지르고 있는지 알고나 있나?'),
(26921, 0, 0, '이런 짓을 저지른 대가를 치르게 해주마!'),
(26921, 0, 1, '어리석은 놈! 너는 절대 도망칠 수 없다!'),
(26921, 0, 2, '감히 무쇠의 후예에게 덤빈단 말이냐?'),
(26921, 0, 3, '네가 무슨 짓을 저지르고 있는지 알고나 있나?'),
(26922, 0, 0, '이런 짓을 저지른 대가를 치르게 해주마!'),
(26922, 0, 1, '어리석은 놈! 너는 절대 도망칠 수 없다!'),
(26922, 0, 2, '감히 무쇠의 후예에게 덤빈단 말이냐?'),
(26922, 0, 3, '네가 무슨 짓을 저지르고 있는지 알고나 있나?'),
(26923, 0, 0, '이런 짓을 저지른 대가를 치르게 해주마!'),
(26923, 0, 1, '어리석은 놈! 너는 절대 도망칠 수 없다!'),
(26923, 0, 2, '감히 무쇠의 후예에게 덤빈단 말이냐?'),
(26923, 0, 3, '네가 무슨 짓을 저지르고 있는지 알고나 있나?'),
(26971, 0, 0, '나이가 어떻게 되지?'),
(26971, 1, 0, '절대 피할 수 없을 거다. 왜냐고? 넌 그냥 꼬마일 뿐이니.'),
(26971, 2, 0, '네 아버지는 나약했다, 사샤... 자기가 해야 할 일을 해낼 수 있는 배짱이 없었다.'),
(26971, 3, 0, '결국은 우리 모두가 리치 왕님을 섬기게 된다, 꼬마야. 시체가 되어 썩어가는 것보단 그게 나을 거다.'),
(26971, 4, 0, '잠깐! 쏘지 마! 타트야나를 해치지 마!'),
(26971, 5, 0, '그 녀석은 산 반대편의 늑대 우리에 잡혀 있다. 아루갈에게 바쳐지기로 되어 있어. 이제 우릴 풀어줄 건가?'),
(26971, 6, 0, '타트야나... 날 용서하시오.'),
(26971, 7, 0, '너희 힘 따위는 아루갈 님의 힘과 비교조차 되지 않는다! 내가 직접 너희를 없애버리겠어!'),
(27002, 0, 0, '네놈을 잡아먹고 뼈는 이쑤시개로 써 주마!'),
(27002, 1, 0, '네놈은 마그나타우르도 아닌데! 그런... 힘을... 대체... 어디서 얻었지?'),
(27003, 0, 0, '네가 왜 왔는지 안다. 저 평원의 멍청한 마그나타우르 하나가 문제를 일으켜서 용을 끌어들이고 만 게지. 그래, 용족의 앞잡이 노릇이 맘에 드느냐?'),
(27003, 1, 0, '지도자가 누군지 궁금하다 이거지... 쥐방울만한 녀석아, 감히 천둥의 인도자 그롬타르가 이끄는 부족과 전쟁을 벌이겠다고? 그렇게 죽고 싶으냐?'),
(27003, 2, 0, '하! 그렇게 원한다면야. 청금석 용제단 남쪽으로 가서, 횃불로 이루어진 원 안에 들어가 마그나타우르 대장에게 빼앗은 뿔피리를 불어 보려무나. 명복을 빈다. 그롬타르가 올 게다...'),
(27061, 0, 0, '싱크의 벌목기가 준비되어 벌목 작업을 시작할 수 있습니다.'),
(27061, 1, 0, '싱크의 벌목기 보안 기능이 활성화되었습니다. 기지로 돌아갑니다.'),
(27113, 0, 0, '구해줘서 고맙습니다. 하지만 다른 이들이 아직 저 위쪽에 잡혀 있습니다!'),
(27114, 0, 0, '정말 고맙네! 놈들이 날 바위 거인들과 싸우도록 강요할까 봐 무척 걱정하고 있었다네.'),
(27199, 0, 0, '마침내 제대로 된 공물이 도착했군!'),
(27199, 1, 0, '으아악! 나한테 무슨 일이 일어난 거냐?'),
(27199, 2, 0, '감히 대가도 없이 나를 불러냈단 말이냐!'),
(27202, 0, 0, '아벤디스 님께 네 시체를 보여 드리겠다!'),
(27202, 0, 1, '불결한 자 같으니!'),
(27202, 0, 2, '으아! 뭘 하는 거요?'),
(27202, 0, 3, '내 눈앞에서 냉큼 사라져라!'),
(27202, 0, 4, '빛의 이름으로!'),
(27202, 0, 5, '불결한 자여!'),
(27202, 0, 6, '몹쓸 녀석!'),
(27202, 1, 0, '보병, 당신에게서 오염된 이 땅의 기운이 느껴집니다. 다음 교대 시간이 오기 전에 주교님께 보고하십시오.'),
(27202, 1, 1, '당신은 강한 수호를 받고 있습니다. 일을 계속하십시오.'),
(27202, 1, 2, '우리의 헌신적인 모습을 보고자 총사령관께서 직접 오셨다. 그렇게 축 늘어진 모습을 또 보인다면 내 손으로 널 없애버리겠어.'),
(27202, 1, 3, '그대에게는 주교님의 축복이 필요하겠군요. 어서 가보십시오.'),
(27202, 1, 4, '침입자들이 속닥거리는 소리를 들었습니다. 조심하십시오.'),
(27202, 1, 5, '순수한 길을 걸으십시오. 빛이 당신을 지켜줄 것입니다.'),
(27202, 2, 0, '도와주세요! 도와주세요! 이 $g남자:여자;가 내 모습을 훔쳐갔어요!!'),
(27203, 0, 0, '철의 힘으로 너를 정화하리라!'),
(27203, 0, 1, '빛의 이름으로!'),
(27203, 0, 2, '빛의 이름으로!'),
(27203, 0, 3, '너를 정화하겠다!'),
(27209, 0, 0, '놀아보자는 건가?'),
(27209, 1, 0, '으윽! 네놈한테는 아무 말도 안 하겠다, 이 더러운 $r 녀석!'),
(27209, 2, 0, '잠깐... 잠깐! 알고 싶은 게 대체 뭔가?! 네놈이 $n|1이라는;라는; $c|1이라는;라는; 건 안다.'),
(27209, 3, 0, '으윽... 안 돼! 우리가 아는 거라곤 너희가 우리 방어구와 무기에다 군마까지 훔쳐갔다는 것뿐이야!'),
(27209, 4, 0, '우리가 아는 건... 왜 우리에게 그 파멸의 역병이라는 게... 효과가 없는지... 너희가 모른다는 것뿐이야. 웨스트윈드 님께서 대수도원장님께 그 축복의 기도를 알려줬지. 부탁이니... 제발... 그만?!'),
(27209, 5, 0, '으아아아아아아! 제발... 우리가... 아는 거라곤... 우리 중에... 우리처럼 분장한... 너희들 첩자가 있다는 사실이야! 그래... 내가 아는 건 그게 다야. 제발... 자비를... 그만!'),
(27209, 6, 0, '제발... 그만해. 뭐든지... 해줄 테니...'),
(27209, 7, 0, '부탁이다... 그만해라.'),
(27209, 8, 0, '우와아아아아아아아!'),
(27209, 9, 0, '네놈은... 내게서 아무것도... 알아내지 못할 거다!'),
(27209, 10, 0, '놈들 모두... 살려 달라고... 애원했었다!'),
(27209, 11, 0, '말했잖나... 더는... 아무것도... 모른다고!'),
(27209, 12, 0, '차라리 날... 죽여라.'),
(27212, 0, 0, '늦었구나, 감독관이여.'),
(27212, 1, 0, '운명은 기다려주지 않는다. 바위 거인 지도자와 그의 군대가 울두아르에 도착하기 전에 전쟁 골렘을 더 많이 생산해야 한다.'),
(27212, 2, 0, '룬대장장이들에게 계속해서 바위 거인들을 변환하라고 일러라. 굴복하지 않는 놈들은 모두 제거해 버려라.'),
(27212, 3, 0, '울두아르에서 벌이는 우리 일을 바위 거인들이 방해하면, 너와 네 영주에게 책임을 묻겠다. 필멸의 존재들이 거인을 도우러 오게 놔둬서는 안 된다.'),
(27212, 4, 0, '돌아가서 일을 계속하라, 감독관. 일꾼들을 재촉하는 일을 잊지 말아라.'),
(27221, 0, 0, '효과가 있는지 봅시다.'),
(27221, 1, 0, '여기는 타운카의 원크와 야영지다, 드워프여.'),
(27221, 2, 0, '우리 공통의 적과 싸우는 것을 도와준다면, 너는 다치지 않을 것이다.'),
(27221, 3, 0, '생각해 봐라, 발굴조사단장. 하지만 우리도 속히 행동을 취해야 하니 결정을 빨리 내려야 한다.'),
(27221, 4, 0, '네 능력을 인정한다, 드워프여. 계획이 성공한 걸 보니 기쁘고도 놀랍군.'),
(27221, 5, 0, '하지만 널 돌려보낼 수도 없고, 그렇다고 계속 데리고 있을 수도 없다...'),
(27221, 6, 0, '쓸모가 있는 동안은 살려 두지. 내가 너라면 행동을 조심할 게다, 드워프여.'),
(27227, 0, 0, '여기가... 여기가 어디죠?'),
(27227, 1, 0, '잠깐! 내가 도와주면 목숨만은 살려준다 하지 않았소. 난 약속을 지켰소!'),
(27227, 2, 0, '오, 빛이시여, 브란이 살아 있다고? 그를 잡는 일 따위에는 절대 협조하지 않겠소!'),
(27232, 0, 0, '더러운 것. 살아갈 가치조차 없는 것들이로구나. 받아라!'),
(27234, 0, 0, '너흰 잘못 생각하고 있다! 붉은돌격대는 온갖 거짓으로 가득해! 스컬지와 포세이큰은 우리의 적이 아니다! 눈을 떠!'),
(27235, 0, 0, '붉은돌격대를 버려라! 더는 고위사령관과 제독의 거짓말에 속아서는 안 된다!'),
(27236, 0, 0, '아벤디스는 하찮은 여자일 뿐이고, 제독 바리안 웨스트윈드 제독은 우리를 팔아먹은 것처럼 그 여자를 헐값에 팔아치우고 있어!'),
(27237, 0, 0, '고위사령관 아벤디스가 북으로 온 일은 실수였고, 우리 모두 죽은 목숨이라고 내게 직접 말했다! 모두 무기를 내려놓고 더 늦어지기 전에 떠나라!'),
(27238, 0, 0, '내 아름다운 제재소가! 네 이놈! 죽을 줄 알아라!'),
(27246, 0, 0, '잘 오셨습니다, 어린 양이여. 그대를 둘러싼 빛의 가호가 약해져 있군요.'),
(27246, 1, 0, '다 됐습니다. 계속해서 빛을 섬기십시오.'),
(27246, 2, 0, '감히 우리의 신성한 일을 방해한단 말이냐?!'),
(27247, 0, 0, '이봐, 누가 종을 울린 거냐?'),
(27250, 0, 0, '네?'),
(27250, 1, 0, '하지만... 전 말씀하신 대로 만들었을 뿐이에요! 뭐, 죄송해요.'),
(27250, 2, 0, '으악!'),
(27316, 0, 0, '물러나 계십시오, $n. 저 짐승이 달려들어 당신을 해칠지도 모릅니다.'),
(27316, 1, 0, '고드프리! 내 말을 들어라, 악마여! 내 말을 들어라, 내가 빛을 대신하여 너를 악으로부터 구해주겠다!'),
(27316, 2, 0, '좋아. 이제 말을 들을 준비가 되었나, 고드프리?'),
(27316, 3, 0, '우리가 취할 방법에는 두 가지가 있다, 고드프리. 첫 번째 방법은 네가 이 책에 기록된 부정한 문자를 해독해 달라는 내 요청을 들어주기만 하면 된다. 어떻게 하겠나?'),
(27316, 4, 0, '그렇다면 두 번째 방법을 써야겠군.'),
(27316, 5, 0, '너를 위한 기도를 올리겠다, 길 잃은 영혼이여. 빛이 너를 거두어 가시길.'),
(27316, 6, 0, '그럼 설교를 시작하지.'),
(27316, 7, 0, '빛이 너를 거두리라, 악마여!'),
(27316, 8, 0, '성스러운 불꽃으로 타올라라!'),
(27316, 9, 0, '빛을 받아들여라, 고드프리 구다르!'),
(27316, 10, 0, '빛의 힘으로 널 굴복시키리라!'),
(27316, 11, 0, '네가 빛을 볼 수 있을 거로 생각했다, 고드프리... 어서 말해라, 이 악마 같으니. 뭐라고 적혀 있지?'),
(27316, 12, 0, '말도 안 되는 소리! 고드프리, 내가 무슨 바보인 줄 아는가? 스컬지들의 선전 문구를 빛을 섬기는 자에게 늘어놓다니! 지금 말하지 않으면 하인들을 시켜 이가 들끓는 개처럼 성수로 목욕을 시켜주마!'),
(27316, 13, 0, '뭐? 그 오래된 마을 지하에 묘지가 있다고? 어리석게도 여태껏 그것도 모르고 있었다니! 반드시 그곳을 찾아서 네 주인을 쓰러트려 주겠다, 고드프리. 이 악몽을 반드시 끝내고야 말겠어.'),
(27316, 14, 0, '넌 우리가 그 빌어먹을 녀석을 어떻게 없애버릴 지나 두고 봐라, 고드프리.'),
(27316, 15, 0, '할포드 님께 돌아가 시장이 친절하게도 정보를 제공했다는 소식을 전하십시오, $n. 전 여기 남아 이 녀석이 텔잔에 관해 아는 정보가 뭐가 됐든 짜내 보겠습니다. 그럼 좀처럼 보기 어려운 "세 번째 방법"을 고드프리에게 써봐야겠군요.'),
(27316, 16, 0, '그럼 우리 단둘이 이야기 좀 해볼까, 고드프리.'),
(27328, 0, 0, '내 뒤에 있으시오, $r. 온 힘을 다해 그대를 보호하겠소.'),
(27328, 1, 0, '우르속을 구하지 못한다면 내 자유에는 아무 의미도 없소. 서두르시오, $n.'),
(27328, 2, 0, '그대와 그대의 동료를 지키겠소, $r.'),
(27328, 3, 0, '우르속, 우르솔의 형제이자 펄볼그 부족의 수호자여... 모습을 보이시오!'),
(27344, 0, 0, '경비병!'),
(27349, 0, 0, '%s|1은;는; 신음하고 있지만, 스컬지의 역병에 영향을 받은 것 같지는 않습니다.'),
(27355, 0, 0, '안 돼... 안 돼! 대체 뭘 한 거냐?! 아까운 고룡 뼈를 망치다니... 대체 무슨 마법이냐?'),
(27355, 1, 0, '멍청한 심부름꾼 같으니... 내 일을 방해했으니 죽어줘야겠다!'),
(27355, 2, 0, '이걸로 끝나지 않는다... 죽음은 우리를... 강하게 할 뿐...'),
(27359, 0, 0, '마침내 영웅이 오셨군요!'),
(27359, 0, 1, '당신이 와 주어 천만다행입니다, 영웅이여! 녀석들한테 당할 찰나였어요!'),
(27359, 0, 2, '당신을 절대 잊지 않겠습니다.'),
(27359, 0, 3, '친절한 영혼을 지니셨군요. 고맙습니다.'),
(27373, 0, 0, '그대들에게 감사한다. 볼드랏실의 뿌리는 고대 악마의 거처까지 뻗어가 버렸고, 그래서 현명한 드루이드들은 볼드랏실을 파괴하기로 한 것이다.'),
(27373, 1, 0, '그대들은 그런 악마를 고대 신으로 알고 있다. 요그사론을 조심하라. 그 짐승은 입이 천 개이며, 그 악은 볼드랏실의 뿌리 너머까지 퍼졌다.'),
(27376, 1, 0, '이봐요, 이쪽입니다!'),
(27378, 0, 0, '그럴 수는 없네... 자네를 바보로 만들 내용을 작성해 주지, $c!'),
(27378, 1, 0, '제발 날 여기서 좀 꺼내주게!'),
(27379, 0, 0, '안 돼! 제발 부탁이오! 날 죽이지 마시오!'),
(27379, 1, 0, '날 여기서 꺼내줄 자가 아무도 없는 거요? 원한의 초소로 돌아가서 내 일을 마저 끝내야 한단 말이오.'),
(27381, 0, 0, '이게 무슨 짓인가?! 그만두게! 놈들이 말한 수고비의 두 배를 주겠네!'),
(27381, 1, 0, '난 이제 막 원한의 초소에 온 몸이네. 내가 자네에게 무슨 잘못을 했단 말인가?'),
(27383, 0, 0, '나도 한때는... 너와 같았다, 필멸의 존재여. 연약했지. 뼈와 살만 가진, 나약하고 소심한 존재였다!'),
(27383, 1, 0, '우리의 왕인 아서스 님께서는 내게서 인간의 연약함을 발견하셨다.'),
(27383, 2, 0, '"목숨으로써 날 섬긴다면 네 영혼에 깃든 연약함을 제거해 주겠다. 그 존재 자체를 지워주겠다!" 그분께 선택받고자... 난 그렇게 리치 왕의 축복을 받게 되었다.'),
(27383, 3, 0, '그래서 난 그분을 섬겼다... 내가 아니었으면 이 영광스러운 공포의 요새 낙스라마스는 결코 노스렌드로 돌아오지 못했을 것이야.'),
(27383, 4, 0, '말이 너무 길었군... 너는 이 황혼의 인도자와 맞서 싸우려고 세상 먼 곳에서부터 나를 찾아 여기까지 왔다. 너를 실망시키지는 않으마...'),
(27383, 5, 0, '우리의 주인께서 날 구원하셨듯이, 내가 너를 구원해 주겠다!'),
(27383, 6, 0, '성기사여, 두 번 다시 그 이름을 입에 담지 못하게 해 주마! 마지막 숨을 쉴지어다!'),
(27383, 7, 0, '일어나라, 나의 아이들아! 너희의 주인이 명한다!'),
(27405, 0, 0, '지금 무슨 일이 벌어지는 거지요?'),
(27406, 0, 0, '나도 모르겠습니다. 말썽이 일어나지 않게 하려면 둘 다 없애는 게 좋겠군요!'),
(27411, 0, 0, '물리지 않았소?'),
(27411, 1, 1, '대답하시오! 어디 물리지 않았느냔 말이오!'),
(27411, 2, 2, '당신, 정말 아무것도 모르는 거군? 덫사냥꾼? 그들은 인간이 아니라오... 어서 여기서 나가야 하오! 어서, 이리 오시오!'),
(27411, 3, 3, '듀칼의 말을 타시오. 그도 지금은 놈들과 한 패거리요!'),
(27411, 4, 4, '말 뒷잔등에 등잔 기름이 있소. 그걸 써보시오. 저 망할 녀석들은 불을 싫어하니까!'),
(27430, 0, 0, '파괴의 수호물에 마력이 모입니다.'),
(27430, 1, 0, '파괴의 수호물이 마력으로 충만해졌습니다!'),
(27439, 0, 0, '조용히 이야기를 나눌 만한 곳이 근처에 있소. 따라오시오.'),
(27439, 1, 0, '내가 너의 그 어설픈 위장술도 간파하지 못할 거로 생각했나, $n?'),
(27439, 2, 0, '너 같은 작자가 이해할 수 없는 일은 많다, $r. 주인님은 모든 걸 아신다.'),
(27439, 3, 0, '그분께서 네가 나타날 것이라 말씀하셨다. 하지만 난 네 손에 죽지는 않을 것이야. 난 네가 우리 동족들에게 어떤 짓을 해왔는지 안다.'),
(27439, 4, 0, '그래. 난 내가 원하는 방식으로 이 세계를 떠날 것이다. 그리고 내가 돌아오면 총사령관님도 날 인정하겠지!'),
(27439, 5, 0, '으아아아아아아아아아아악........................................'),
(27447, 0, 0, '내 사전엔 자비란 없다!'),
(27447, 1, 1, '적을 없애라! 날려 버려!'),
(27447, 2, 2, '%s|1이;가; 하늘빛 고리 경비대장을 부릅니다!'),
(27447, 3, 3, '그들은... 너무 강하다! 그들의 힘을... 과소평가했어...'),
(27447, 4, 0, '침입자들아, 너희 승리는 덧없는 것이다. 나는 사령관인 바로스 클라우드스트라이더다. 내 비룡들이 하늘을 지키고, 이 마력의 통로를 보호하지. 분명히 말하건대, 마력의 눈을 너희에게 내주지는 않을 것이다.'),
(27455, 0, 0, '부대장, 왜 다들 위치를 벗어났지?'),
(27455, 1, 0, '우서가 내 부대를 불러들여? 빌어먹을! 병사들이 떠나면 어떻게 말가니스를 잡으란 말인가! 병사들이 해안에 도착하기 전에 배를 불태워야겠어!'),
(27455, 2, 0, '완전히 불태울 겁니다! 임무를 마칠 때까지 아무도 돌아갈 수 없습니다!'),
(27455, 3, 0, '이해하십시오, 무라딘. 당신은 말가니스가 무슨 짓을 했는지 모릅니다.'),
(27455, 4, 0, '보십시오, 무라딘. 우리의 구원, 서리한입니다.'),
(27455, 5, 0, '왕국을 지킬 수 있다면 저주 따윈 상관없습니다.'),
(27455, 6, 0, '부하들이 무엇이길래요! 그 무엇도 내 복수를 막을 순 없습니다! 오랜 친구인 당신조차도요...'),
(27455, 7, 0, '이제 여기를 떠도는 영혼들을 부르겠습니다. 백성을 구할 수만 있다면, 나는 아무것도 마다하지 않을 겁니다.'),
(27463, 0, 0, '아... 좀 낫군요.'),
(27463, 0, 1, '후우, 죽는 줄 알았습니다. 고맙습니다!'),
(27463, 0, 2, '고맙습니다, $c|1이여;여;.'),
(27476, 0, 0, '죄송합니다만, 왕자님은 일이 있어 자리를 비우셨습니다. 무슨 일로 여기까지 오셨습니까?'),
(27476, 1, 0, '그냥 여길 떠나도 된다고요?'),
(27476, 2, 0, '망할 놈의 언데드... 제군들, 숲을 가로지르자!'),
(27476, 3, 0, '왕자님, 폐하께서 우서 경의 청에 따라 회군을 명하셨습니다.'),
(27480, 0, 0, '그건 너무 심하지 않나?'),
(27480, 1, 0, '자넨 부하들에게 거짓말을 했고, 자네를 믿고 싸운 용병들을 배신했네. 대체 왜 그러나? 자네에겐 오직 복수만이 중요한가?'),
(27480, 2, 0, '기다리게. 제단에 뭔가 새겨져 있군. 이건 경고일세. "이 검을 집는 자는 무한한 힘을 얻게 될 것이다. 그러나 검이 육신을 베듯이, 이 힘은 영혼에 상처를 남기리라..." 아아, 왜 몰랐을까! 이 검은 저주받았네! 어서 여기서 나가세!'),
(27480, 3, 0, '오오... 그냥 놔두게, 아서스. 이번 일은 잊고, 부하들과 돌아가게!'),
(27480, 4, 0, '으으, 머리야... 여... 여기는 어디지?'),
(27480, 5, 0, '나... 나는 누구지?'),
(27482, 0, 0, '거의 포기하려던 참이오. 내 목숨을 구해줬구려!'),
(27482, 0, 1, '그대에게 신의 가호가 있기를. 죽을 뻔했소이다...'),
(27482, 0, 2, '당신이 도와주지 않았다면 난 지금쯤 죽었을 거요...'),
(27482, 0, 3, '$r|1이여;여;, 고맙습니다!'),
(27492, 0, 0, '병사를 이끌고 즉각 본국으로 귀환하라는 왕명을 전하러 왔소. 우서 경이 폐하를 설득해 이 원정을 중지하도록 했소.'),
(27492, 1, 0, '그렇소. 헌데 이곳에서 해안으로 나가는 길을 언데드가 장악했다고 하더군. 배로 돌아가려면 다른 길을 찾아야 할 거요.'),
(27551, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(27570, 0, 0, '이러다 다 죽겠군!'),
(27570, 0, 1, '여기서 나가야 해!'),
(27570, 0, 2, '더는 여기 못 있겠어!'),
(27570, 0, 3, '됐어! 집에 갈 거야!'),
(27570, 0, 4, '난 이런 계약한 적 없다고!'),
(27577, 0, 0, '%s|1이;가; 으르렁거립니다.'),
(27577, 1, 0, '%s|1이;가; 위협적인 소리를 냅니다!'),
(27577, 2, 0, '네놈 따위에게 할 말 없다, 설교자 녀석.'),
(27577, 3, 0, '켈투자드 님도 하지 못하셨고 리치 왕께서도 하지 못할 일을 네가 어떻게 하겠다는 거냐?'),
(27577, 4, 0, '고서는 널 구원할 수 있겠지. 그래... 하지만 넌 아무것도 알아낼 수 없다! 난 아무것도 말하지 않을 거다! 아무것도!'),
(27577, 5, 0, '빛은 저리 치워! 그만! 부탁이다!'),
(27577, 6, 0, '아파서 못 견디겠어!'),
(27577, 7, 0, '앞으로 다가올 종말에 대해 이야기한다. 이 세계가 어떻게 불타 사라지고 어떻게 파멸에서 다시 태어나는지가 적혀 있다.'),
(27577, 8, 0, '안돼애애!!! 말한다! 뭐든지 다 말한다!'),
(27577, 9, 0, '인간들은... 윈터가드 마을 지하에 묘지를 만들어 놓았지! 낙스라마스가 왜 그곳을 공격했는지 모르겠나? 텔잔 님은 너희의 납골당에 숨은 채로 너희에게 수천 구의 시체를 올려 보내고 계신다! 너희는 패하게 돼 있어...'),
(27577, 10, 0, '어떻게? 인간들은 참으로 어리석군. 안 그런가? 황혼의 인도자 텔잔 님이시란 말이다! 텔잔님은 리치시다! 인간의 뼈와 살에서 태어나 힘을 위해 모든 것을 희생한, 리치 왕의 가호를 받는 분이시란 말이다!'),
(27577, 11, 0, '너희는 텔잔 님을 막을 수 없다! 그분은 리치 왕께서 몸소 하사하신 암흑의 힘을 보유하신 분이다!'),
(27619, 0, 0, '일어나라, 아루갈! 리치 왕님의 힘으로 네게 명한다!'),
(27624, 0, 0, '그래... 그라면 우리 목적에 아주 적격이지. 준비되면 이자를 극지 마을로 보내라. 일이 늦어진다면 아서스 님께서 좋아하지 않으실 거다.'),
(27629, 0, 0, '전투 준비가 되셨습니까, $c|1이여;여;?'),
(27629, 0, 1, '전장으로 이끌어 주십시오, $n!'),
(27629, 0, 2, '적을 먼저 없애실 건가요? 아니면 제단부터 처리하실 건가요?'),
(27629, 0, 3, '당신을 기다리고 있었습니다, $n. 이제 우리가 유리해졌군요.'),
(27629, 0, 4, '푸른용군단이 우리를 공격하다니, 믿을 수가 없습니다. 놈들에게 받은 대로 돌려주겠습니다!'),
(27629, 0, 5, '저는 준비됐습니다. 요새를 수호합시다!'),
(27629, 0, 6, '어디에 먼저 갈까요?'),
(27629, 0, 7, '명성이 아주 자자하더군요, $n. 오늘이 기대됩니다.'),
(27629, 1, 0, '$r|1을;를; 태우고 전투를 치르리라고는 생각도 못 해봤습니다.'),
(27629, 1, 1, '푸른용 하나를 또 잡았군요. 그대와 나는 좋은 짝인 것 같습니다!'),
(27629, 1, 2, '그대와 내가 함께라면 이 전투도 금방 끝날 겁니다.'),
(27629, 1, 3, '말리고스는 미친 것이 분명합니다.'),
(27629, 1, 4, '잘하셨습니다.'),
(27629, 1, 5, '이런 건 본 적이 없습니다. 그대와 함께 있어 다행입니다.'),
(27629, 1, 6, '저 녀석을 쓰러뜨려 주셔서 기쁘군요!'),
(27629, 1, 7, '꽉 붙잡으십시오. 재빠르게 임무를 완수해야지요.'),
(27629, 2, 0, '어서 여기서 벗어납시다. 소생이 필요합니다!'),
(27631, 0, 0, '%s|1이;가; 격노합니다!'),
(27654, 0, 0, '죄수들을 풀어줄 순 없다! 말리고스 님의 말씀은 법이다!'),
(27654, 1, 0, '죄수들을 풀어줄 순 없다! 말리고스 님의 말씀은 법이다!'),
(27654, 1, 1, '죄수들을 풀어줄 순 없다! 말리고스 님의 말씀은 법이다!'),
(27654, 1, 2, '전사자 추가...'),
(27654, 2, 0, '전쟁은.. 계속된다...'),
(27654, 3, 0, '달아나기엔 너무 늦었어.'),
(27654, 3, 1, '집합해라...'),
(27654, 3, 2, '아무도 못 도망간다!'),
(27654, 3, 3, '네놈들에게... 사형을 선고한다!'),
(27654, 4, 0, '벌벌 떨어라!'),
(27654, 4, 1, '박살 내 주마!'),
(27654, 4, 2, '날아볼 테냐?'),
(27655, 0, 0, '어디 보자... 마법의 지배자께 반항하는 자들인가? 이해력도, 통찰력도 없는 것들... 어떻게 해야 알겠느냐? 말리고스 님은 세상을 근본적으로 구하고 계신단 말이다! 하! 말해 봐야 입만 아프지!'),
(27655, 1, 0, '내 부하들이 쓰러졌구나. 하지만 또 다른 녀석들이 등장할 게다.'),
(27655, 2, 0, '여전히 반항이냐. 여전히 잘못된 신념에 매달리느냐. 이번에도 살아남는다면, 중심원에서 날 찾을 수 있을 게다.'),
(27655, 3, 0, '어리석은 족속들!'),
(27655, 4, 0, '%s|1이;가; 강화된 신비한 폭발을 시전합니다!'),
(27655, 5, 0, '마법의 지배자의 힘을... 약간... 아주 약간 느껴봐라!'),
(27655, 5, 1, '불안정한 에너지라... 하지만 네놈들을 처치하려면 위험을 감수해야지!'),
(27655, 6, 0, '내가 행한 모든 일은... 아제로스를 위한 것...'),
(27655, 7, 0, '내가 누차 얘기했건만!'),
(27655, 7, 1, '이제 알겠느냐? 알겠냔 말이다!'),
(27655, 7, 2, '어디 보자... 마법의 지배자께 반항하는 자들인가? 이해력도, 통찰력도 없는 것들... 어떻게 해야 알겠느냐? 말리고스 님은 세상을 근본적으로 구하고 계신단 말이다! 하! 말해 봐야 입만 아프지!'),
(27656, 0, 0, '얼간이 같은 놈들! 너희가 지금 무슨 짓을 하고 있는지, 전혀 모르는구나. 지맥의 흐름을 방해하게 놔둘 것 같으냐? 내 너희를 완전히 끝장내 주마!'),
(27656, 1, 0, '무례한 침입자 놈들, 정신이 나갔구나! 저 아래 내던져 주마!'),
(27656, 2, 0, '무례하고, 오만한 것들... 가만두지 않겠다!'),
(27656, 3, 0, '얼간이 같은 놈들! 너희가 지금 무슨 짓을 하고 있는지, 전혀 모르는구나. 지맥의 흐름을 방해하게 놔둘 것 같으냐? 내 너희를 완전히 끝장내 주마!'),
(27656, 3, 1, '저기 땅에서나 놀아라!'),
(27656, 3, 2, '떨어지니 즐거우냐?'),
(27656, 4, 0, '하찮은 승리에 도취할 것 없다, 어리석은 생명체여. 너희와 다른 용군단이 여기선 이겼을지 모르나, 우리는... 마력 전쟁에서... 승리할 것이다.'),
(27656, 5, 0, '얼간이 같은 놈들! 너희가 지금 무슨 짓을 하고 있는지, 전혀 모르는구나. 지맥의 흐름을 방해하게 놔둘 것 같으냐? 내 너희를 완전히 끝장내 주마!'),
(27656, 5, 1, '불길을 잡는 건 식은 죽 먹기지.'),
(27656, 5, 2, '자연의 마법은 이제 너희 편이 아니다.'),
(27658, 0, 0, '절 자유롭게 해주셔서 감사합니다, 필멸의 존재여. 명심하십시오. 푸른용군단은 그대의 존재를 경계하고 있습니다. 지금 이 순간에도 말리고스는 마력의 눈을 보호하려고 바로스 클라우드스트라이더와 고리 수호자들을 보내지요. 이에 맞서려면 저희 도움이 필요하리라 생각합니다.'),
(27692, 0, 0, '%s|1이;가; 하늘 저 멀리 날아갑니다.'),
(27692, 1, 0, '환영하노라, 친구여. 고개를 낮추고 꼭 잡으라!'),
(27692, 2, 0, '적에 피해를 주면서 동시에 날 지속적으로 회복시키려면 착취 독을 사용하라. 악몽 접근 기술은 매우 강력하지만, 나에게까지 피해가 오니 내 체력이 많을 때만 사용해야 한다!'),
(27692, 3, 0, '내 힘이 최고조에 달한 지금이라면 꿈의 집중을 사용할 수 있도다. 그걸로 다른 비룡들을 치료할 수 있지만, 내 체력도 닳게 되므로 착취 독과 함께 사용하는 것을 잊지 말아라!'),
(27692, 4, 0, '부상이 심각하다! 더는 버티지 못하겠노라!'),
(27692, 5, 0, '원심력 피조물이 $3486W개 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27692, 6, 0, '이제 원심력 피조물이 하나 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27692, 7, 0, '보호막이 사라졌구나. 이제 바로스는 약해졌으리라! 바로스를 처치하고 하늘빛 고리 수호자들을 도망가게 하면 상층 고리에 접근할 수 있도다. 바로스는 떠다니는 단 위에 있는데, 그 장소는 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27692, 8, 0, '마법사 군주 우롬이 다음 목표이다. 우롬은 변환의 고리에 있는 떠다니는 단 어딘가에 숨어 있는데, 아마 마력의 눈 꼭대기에 가까이 있을 것이로다. 조심하라, 우롬은 강력한 요술사인데다 혼자 있지는 않으리라.'),
(27692, 9, 0, '이제 마력의 눈을 조종하면서 우리를 방해하는 것은 지맥 수호자 에레고스뿐이리라. 에레고스는 마력의 눈 가장 꼭대기에 있는 정렬의 고리 위를 날아다닌다. 에레고스는 믿을 수 없을 만큼 강한 놈이니, 싸움은 내게 맡기고 뒤에 숨어 있거라.'),
(27713, 0, 0, '뭔 일인가?'),
(27713, 0, 1, '이게 끝일까? 지금 이 괴물을 막아내면 분노의 관문에서 승리할 수 있는 걸까?'),
(27713, 0, 2, '너희와 어깨를 나란히 하고 싸운 건 내게 크나큰 영광이자 기쁨이었다는 사실을 알아줘...'),
(27713, 0, 3, '누구든... 언젠가는 죽음을 맞이하게 마련이지만, 때 이른 죽음을 자초하는 사람도 있지. 오늘 우리는 그런 이를 눈먼 영웅이라 부르지만... 내일 누군가는 그를 바보라고 부를지도 몰라.');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(27713, 0, 4, '제발... 제발 좀 끝났으면 좋겠군!'),
(27713, 0, 5, '저건 그야말로 지옥의 문 같아!'),
(27713, 0, 6, '조금 걱정이 되는걸. 이 전투에서 우리를 이끌기로 한 영웅은 대체 어디 있는 거지?'),
(27713, 0, 7, '내가 살아서 윈터가드에 돌아가지 못하면, 가족들에게 내가 용감히 싸웠다고 전해 줘. 그리고 사랑한다는 말도...'),
(27713, 1, 0, '대영주님이다!'),
(27719, 0, 0, '신사 숙녀 여러분! 그... 뭐랄까, 이번 시합은 놓치지 않는 게 좋을 겁니다!'),
(27726, 2, 2, '두고 보면 알겠지.'),
(27755, 0, 0, '%s|1이;가; 하늘 저 멀리 날아갑니다.'),
(27755, 1, 0, '환영하노라, 친구여. 고개를 낮추고 꼭 잡으라!'),
(27755, 2, 0, '적에 피해를 주려면 충격의 창을 사용하라. 위험에 처하면 시간 정지를 사용해 모든 적을 그 자리에 멈추게 하여 충격의 창으로 어마어마한 피해를 주어라!'),
(27755, 3, 0, '내 힘이 최고조에 달한 지금이라면 시간의 균열을 사용할 수 있도다. 그걸 사용해 적들에게 더 큰 피해를 주고 충격 충전을 얻을 수 있으리라. 충격 충전을 모아 충격의 창을 사용하면 큰 피해를 줄 수 있노라!'),
(27755, 4, 0, '부상이 심각하다! 더는 버티지 못하겠노라!'),
(27755, 5, 0, '원심력 피조물이 $3486W개 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27755, 6, 0, '이제 원심력 피조물이 하나 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27755, 7, 0, '보호막이 사라졌구나. 이제 바로스는 약해졌으리라! 바로스를 처치하고 하늘빛 고리 수호자들을 도망가게 하면 상층 고리에 접근할 수 있도다. 바로스는 떠다니는 단 위에 있는데, 그 장소는 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27755, 8, 0, '마법사 군주 우롬이 다음 목표이다. 우롬은 변환의 고리에 있는 떠다니는 단 어딘가에 숨어 있는데, 아마 마력의 눈 꼭대기에 가까이 있을 것이로다. 조심하라, 우롬은 강력한 요술사인데다 혼자 있지는 않으리라.'),
(27755, 9, 0, '이제 마력의 눈을 조종하면서 우리를 방해하는 것은 지맥 수호자 에레고스뿐이리라. 에레고스는 마력의 눈 가장 꼭대기에 있는 정렬의 고리 위를 날아다닌다. 에레고스는 믿을 수 없을 만큼 강한 놈이니, 싸움은 내게 맡기고 뒤에 숨어 있거라.'),
(27756, 0, 0, '%s|1이;가; 하늘 저 멀리 날아갑니다.'),
(27756, 1, 0, '환영하노라, 친구여. 고개를 낮추고 꼭 잡으라!'),
(27756, 2, 0, '한번에 여러 적을 상대할 때는 불타는 격노를 사용하고, 내가 공격을 받기 시작하면 교묘한 회피를 사용하라. 단, 교묘한 회피를 사용하려면 먼저 공격을 받아 회피력을 충전해야 한다는 것을 기억해 두어라!'),
(27756, 3, 0, '내 힘이 최고조에 달한 지금이라면 희생을 사용할 수 있도다. 이것을 사용해 다른 비룡들을 보호할 수 있지만, 내가 집중 공격을 받게 될 테니 꼭 교묘한 회피와 함께 사용하여라.'),
(27756, 4, 0, '부상이 심각하다! 더는 버티지 못하겠노라!'),
(27756, 5, 0, '원심력 피조물이 $3486W개 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27756, 6, 0, '이제 원심력 피조물이 하나 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27756, 7, 0, '보호막이 사라졌구나. 이제 바로스는 약해졌으리라! 바로스를 처치하고 하늘빛 고리 수호자들을 도망가게 하면 상층 고리에 접근할 수 있도다. 바로스는 떠다니는 단 위에 있는데, 그 장소는 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라.'),
(27756, 8, 0, '마법사 군주 우롬이 다음 목표이다. 우롬은 변환의 고리에 있는 떠다니는 단 어딘가에 숨어 있는데, 아마 마력의 눈 꼭대기에 가까이 있을 것이로다. 조심하라, 우롬은 강력한 요술사인데다 혼자 있지는 않으리라.'),
(27756, 9, 0, '이제 마력의 눈을 조종하면서 우리를 방해하는 것은 지맥 수호자 에레고스뿐이리라. 에레고스는 마력의 눈 가장 꼭대기에 있는 정렬의 고리 위를 날아다닌다. 에레고스는 믿을 수 없을 만큼 강한 놈이니, 싸움은 내게 맡기고 뒤에 숨어 있거라.'),
(27784, 0, 0, '다음은 낙스라마스에서 정점에 선 강력한 존재들에 대해 이야기하겠다. 이 두 괴물은 노스렌드에 있는 모든 존재에게 엄청난 위협이지.'),
(27784, 1, 0, '다음으로 낙스라마스 죽음의 기사단 전당에 대해 설명해 주지. 이 타락한 전당에서는 훌륭한 우리 전사들이 타락하고 변질되어 스컬지의 전사로 다시 태어나, 밤낮으로 그들이 기술을 연마하는 소리가 울려 퍼진다고 한다.'),
(27784, 2, 0, '다음 차례는 낙스라마스 골렘의 전당이다. 그곳에서 스컬지는 놈들의 괴물 군단 중에서도 가장 강력하고 끔찍한 돌연변이를 개발한다.'),
(27784, 3, 0, '이번에는 낙스라마스에 있는 저주받은 거미의 전당에 대해 이야기하겠다. 스컬지는 그곳에서 더욱 독성이 강하고 위험한 놈들을 만들어내고 있다.'),
(27784, 4, 0, '다음으로 낙스라마스 역병의 전당에 대해 이야기하겠다. 스컬지는 그곳에서 로데론에 뿌렸던 것보다 더 강한 역병을 만드는 중이다.'),
(27784, 5, 0, '복습할 수 있도록 영상은 계속 켜 두겠다. 상대의 능력을 잘 파악해라. 그 능력이 약점일 수도 있으니 말이다.'),
(27784, 6, 0, '사피론은 한때 노스렌드의 산악 지대에 살던 고귀한 푸른용이었지. 하지만 얼어붙은 북쪽 땅을 진군하던 아서스에게 살해당했고, 부활하여 그를 섬기게 되었다. 사피론은 영원토록 켈투자드의 둥지를 지키며, 감히 그의 주인에게 다가가려는 자를 기다리고 있지.'),
(27784, 7, 0, '켈투자드는 무시무시한 리치다. 리치 왕에게 무조건 복종하는 그는 살아있을 적에도 강력한 강령술사로 이름을 떨쳤지만, 죽어서 다시 태어난 이후로는 강령술에서 그를 따라올 자가 없게 되었지. 켈투자드는 리치 왕의 가장 충성스러운 신하라고 한다.'),
(27784, 8, 0, '빛의 결사단에서 가장 강한 자의 영혼조차 산산이 부서졌을 법한 시련을 켈투자드는 견뎌냈다. 계획에 따라 자신의 목숨을 아서스에게 선뜻 내주고는, 후에 태양샘의 힘으로 다시 태어났지.'),
(27784, 9, 0, '역병지대에서 켈투자드는 은빛 여명회의 요원들에게 또다시 패하고 말았지. 하지만 그의 성물함은 가짜 결사단 요원에게 넘어가 버렸다. 우린 아직도 누가, 무슨 목적으로 그 성물함을 훔쳐갔는지 밝혀내지 못했다.'),
(27784, 10, 0, '주목. 이자가 훈련교관 라주비어스이다. 켈투자드는 모든 죽음의 기사를 교육하는 임무를 직접 이자에게 맡겼지. 그의 기술은 워낙 뛰어나서 직접 가르친 수제자 정도만이 겨우 그에게 맞서 싸울 수 있다고 하더군.'),
(27784, 11, 0, '영혼 착취자 고딕이다. 강령술과 주술의 전문가인 고딕은 눈 깜짝할 사이에 언데드 군단을 불러낼 수 있다고 한다. 그가 인도하면 가장 약한 죽음의 기사조차도 시체를 일으킬 수 있지.'),
(27784, 12, 0, '낙스라마스 죽음의 기사 중에서도 4인 기사단이 가장 강력하다. 그들은 켈투자드의 최정예 경비병이기도 하지. 첫 번째인 영주 코스아즈는 불의 힘을 다룬다.'),
(27784, 13, 0, '다음은 여군주 블라미우스이다. 암흑의 힘으로 살아있는 자의 영혼을 뽑아 탐욕스럽게 흡수한다고 하지.'),
(27784, 14, 0, '생전에 성기사였던 젤리에크 경은 그 엄청난 신앙심 덕에 언데드가 되어서도 빛의 힘을 다루어 적을 물리친다고 한다.'),
(27784, 15, 0, '마지막 죽음의 기사인 대영주 모그레인은 죽음의 기사 중에서도 가장 뛰어난 전사였다. 하지만 아제로스에서 일어난 사건 이후로 그는 종적을 감췄지. 켈투자드가 그 자리에 누구를 임명했는지는 아직 밝혀지지 않았다.'),
(27784, 16, 0, '봐라, 패치워크이다. 그의 존재가 처음 빛의 결사단에게 알려졌을 때만 해도 그토록 엄청난 힘과 속도를 지닌 누더기골렘이 정말 있다고 믿는 사람은 아무도 없었다. 그래서 패치워크가 쓰러졌다는 소식 또한 믿는 사람이 드물었지...'),
(27784, 17, 0, '그라불루스는 살덩이 거인 군대의 첫 번째 병사이다. 놈은 낙스라마스의 역병 걸린 진흙괴물을 체내에 넣고 다니며 적의 몸에 그 살아 있는 액체를 주입하지. 이 공격을 당한 이는 두려움에 아군이 있는 곳으로 도망가게 마련이고, 그러면 모두 함께 몰살당하고 만다.'),
(27784, 18, 0, '낙스라마스의 언데드 야수 글루스는 식욕이 워낙 왕성해 산 자만으로는 놈의 허기를 달랠 수가 없다고 한다. 그래서 퓨진은 매일같이 놈에게 좀비 한 부대를 먹이로 준다더군. 전투에 내보내도 별 소용이 없는 약한 언데드를 재활용하는 셈으로 말이지.'),
(27784, 19, 0, '타디우스는 여자와 아이의 육신으로 만들어졌다. 그 가엾은 영혼들은 하나로 융합되어, 더러운 육체의 감옥에 영원토록 갇혀 있다고 한다.'),
(27784, 20, 0, '아졸네룹의 고위 거미 군주인 아눕레칸은 원래 아눕아락의 휘하에 있었으나, 리치 왕에게 패한 이후로 스컬지의 휘하에 들어갔다. 옛날에는 아눕아락 휘하의 지휘관 중에서도 가장 충성스러웠다고 하더군.'),
(27784, 21, 0, '귀부인 팰리나는 생전에 식물학자였고, 죽어서는 거미를 키우고 돌본다. 거미 무리를 감독하면서 리치 왕을 위해 강력한 독을 개발하고 있지.'),
(27784, 22, 0, '맥스나는 오래전에 노스렌드의 깊은 산 속에서 태어났다. 그녀는 공포의 요새 낙스라마스로 잡혀가 거기서 새끼를 낳아 기르고 있다. 무모하게 낙스라마스에 침입한 자들의 시체를 먹이면서 말이지.'),
(27784, 23, 0, '잘 봐라, 역병술사 노스이다. 살아 있는 자의 영혼을 뽑아내어 언데드라는 감옥에 가두는 방법을 창조한 장본인이지. 노스는 지금도 이 과정을 개량하고 있다고 한다.'),
(27784, 24, 0, '잘 봐라. 부정의 헤이건이다. 아름다운 아제로스를 역병지대로 바꾸어 버린 역병 가마솥을 배후에서 조종한 인물이지.'),
(27784, 25, 0, '헤이건은 낙스라마스의 벽과 바닥에 수많은 함정을 설치해 놓았고, 자신이 원하는 대로 얼마든지 작동시킬 수 있다고 한다.'),
(27784, 26, 0, '로데브다. 역병지대의 살아 있는 역병과 아제로스의 수렁 괴물을 결합시킨 끔찍한 괴물이지. 로데브에게는 치유 그 자체를 좌지우지하는 힘이 있다.'),
(27788, 0, 0, '구울의 먹이가 될 뻔했습니다! 구해 주셔서 감사합니다!'),
(27788, 0, 1, '당신이 와 줘서 얼마나 다행인지! 우린 완전히 죽은 목숨이었습니다!'),
(27788, 0, 2, '엄호해 주셔서 감사합니다! 저 아래는 완전히 지옥이에요!'),
(27788, 0, 3, '우와, 죽는 줄만 알았는데! 감사합니다!'),
(27842, 0, 0, '노움들은 오늘 밤도 박쥐 창자나 먹게 생겼군...'),
(27842, 0, 1, '대체 무슨 근거로 박쥐가 저 각도로 안전히 착지할 거로 생각하는 건지 모르겠단 말이야. 남는 건 부러진 목에 냄새 나는 박쥐 스튜밖에 없을 거라고.'),
(27842, 0, 2, '"나무가 얼마나 좋은가, 펜릭. 우리에게 은신처를 제공한단 말일세."라고? 나무를 안 베고 어떻게 해결하라는 건지.'),
(27842, 0, 3, '대체 앞으로 증원군이 몇 명이나 더 다쳐야 저 나무를 베도록 허락해 줄지 모르겠군. 박쥐 때문에 엄청난 돈을 날리고 있는데 말이야. 여기에 그물이라도 쳐 놔야 하나...'),
(27842, 1, 0, '경비병, 도움이 필요하다!'),
(27843, 0, 0, '제가 놈을 꾀어오겠습니다, $n! 당신은 놈이 올 때를 대비해 준비하십시오!'),
(27844, 0, 0, '쏴라! 쏴라! 놈을 떨어트려라!'),
(27851, 0, 0, '서리한 동굴의 벽이 심하게 흔들립니다.'),
(27857, 0, 0, '마음을 굳게 먹어라, 제군들. $n|1이;가; 이 모든 일을 끝낼 마지막 조각을 구해줬다. 공포의 대상이던 리치 텔잔은 곧 은신처에서 기어나올 것이다. 그리고 우리는 녀석에게 반드시 승리할 것이야!'),
(27857, 1, 0, '이 성물함, 텔잔의 성물함이야말로 승리의 열쇠이다!'),
(27857, 2, 0, '제군들, 자세를 가다듬어라!'),
(27858, 0, 0, '명예, 용기, 연민, 그리고 정의! 텔잔, 너도 한때는 은빛 여명회의 사제로서 이런 가치를 위해 싸웠지.'),
(27858, 1, 0, '자네는 목숨을 다해 스컬지와 싸울 것을 다짐했었네. 놈들이 로데론에 무슨 짓을 했는지 똑똑히 봤지 않나. 리치 왕은 자네에게서 모든 것을 앗아갔네!'),
(27858, 2, 0, '그런데, 은빛 여명회가 자랑하던 미덕의 수호자, 이니고 몬토이 신부가 어째서 자신이 그토록 증오하던 존재로 변해버렸을까?'),
(27858, 3, 0, '이제, 모두 일어나 전투에 참가하라! 함께 텔잔에게 최후를 안겨 주자!'),
(27858, 4, 0, '얼라이언스에 승리를!'),
(27858, 5, 0, '자네가 윈터가드를 구했네! 텔잔이란 더러운 존재가 사라졌으니 나머지 스컬지는 7군단이 손쉽게 처리할 수 있을 걸세. 여기 일을 마치거든 앙그라타르로 와서 보고하게!'),
(27871, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(27899, 1, 0, '안녕, $n. 경계할 것 없어. 나야... 미래에서 온... 너라고. 널 도우러 왔지.'),
(27899, 2, 0, '정신 바짝 차려... 그들이 오고 있으니까. 힘이 닿는 데까지 널 도와주지. 놈들이 모래시계에 가까이 다가오지 못하게 막자고!'),
(27899, 3, 0, '어찌 됐든, 네가 죽어서는 안 되지. 그렇게 되면 나까지 사라져버릴 테니까. 그렇지? 하지만, 내가 너였을 때는 이 자리에 내가 있었는데... 아아, 헷갈려!'),
(27899, 4, 0, '내가 그런 걸 입고 다녔다니, 믿기지 않는군.'),
(27899, 5, 0, '미안해. 하지만 크로미가 말하길, 미래에 대한 그 어떤 정보도 너에게 알려줘서는 안 된대. 만약 그랬다가는 내 존재 자체가 사라져버리는 모양이야.'),
(27899, 6, 0, '세상에, 내가 이 정도로 미숙했었나?'),
(27899, 7, 0, '싸우는 모습을 보고 있자니 답답하군... 내가 왜 주정뱅이가 됐는지 알겠어.'),
(27899, 8, 0, '뭐 하는 거지? 나 혼자 싸우게 둘 참이냐? 우리 둘 다 이 일에 목숨이 달렸다고!'),
(27899, 9, 0, '내 말 잘 들어. 원래 이런 얘길 해서는 안 되지만... 어쨌거나 넌 말이지, 나중에 어떤 잔치에 초대받을 거야. 거기 가거든, 무슨 일이 있어도 절대 음료수는 마시지 마!'),
(27899, 10, 0, '네가 상대해야 할 무한의 용군단이 얼마나 되는지 기억이 나면 좋을 텐데. 나한테는 하도 오래전 일이라...'),
(27899, 11, 0, '저걸 봐, $n, 모래시계에 노즈도르무가 보이잖아!'),
(27899, 12, 0, '작별할 시간이군, $n. 목숨을 아끼고, 되도록 좋은 장비를 갖춰 줘!'),
(27913, 0, 0, '스컬지 군대가 왕의 광장 분수대 근처에서 목격되었습니다!'),
(27913, 1, 0, '스컬지 군대가 상가 관문 근처에서 목격되었습니다!'),
(27913, 2, 0, '스컬지 군대가 축제의 거리 관문 근처에서 목격되었습니다!'),
(27913, 3, 0, '스컬지 군대가 장로의 광장 관문 근처에서 목격되었습니다!'),
(27913, 4, 0, '스컬지 군대가 마을회관 근처에서 목격되었습니다!'),
(27914, 0, 0, '제가 왔습니다. 그럼 일을 시작해 볼까요?'),
(27914, 1, 0, '아, 정수를 더 흡수할 수 있겠군요...'),
(27914, 2, 0, '당신 몫은 여기 있습니다.'),
(27923, 0, 0, '모자 안 날아가게 꽉 잡으세요, $n 님! 해적 야영지로 갑니다!'),
(27923, 1, 0, '조오오오았어! 다 왔다고요! 해적 야영집니다!'),
(27951, 0, 0, '해치워, 아벤디스! 날 실망시키지 마라!'),
(27951, 1, 0, '제독이 눈을 가늘게 뜨고 잠시 당신을 관찰합니다.'),
(27951, 2, 0, '목적은 이뤘구나.'),
(27951, 3, 0, '얼음왕관에서 보자... 네놈들이 그때까지 산다면 말이다!'),
(27959, 0, 0, '명상을 한다고 날 떨쳐버릴 수 있을 것 같으냐?'),
(27959, 1, 0, '어리석도다! 너를 파멸시키고 지난 세월동안 네 안에서 쌓아올린 존재가 되어주마!'),
(27959, 2, 0, '넌 나를 꺾을 수 없다. 난 절대로 떼어놓을 수 없는 너의 일부니까!'),
(27959, 3, 0, '안 돼애애애애애애애!'),
(27977, 0, 0, '밟을 거야...'),
(27977, 1, 0, '하... 하... 하...'),
(27977, 2, 0, '부서져라...'),
(27977, 3, 0, '으어어어어어어...'),
(27978, 0, 0, '허약하고 물렁물렁한 육신. 짧고 덧없는 생명. 너희는 육체의 저주를 피할 수 없다!'),
(27978, 1, 0, '풀빈 뷸 흐람 안!'),
(27978, 1, 1, '살덩이는 무쇠에 상대가 안 되지!'),
(27978, 1, 2, '무쇠의 군대가 세계를 뒤덮을 거다!'),
(27978, 2, 0, '로켄 님께서... 어떻게든 용광로를 되찾을 것이다! 네놈들은... 헛수고를 하는 거야!'),
(27986, 0, 0, '그러지, 해 보겠소.'),
(27986, 1, 0, '바로 내가 원하는 거로군!'),
(27986, 2, 0, '마음에 쏙 드는군! 이걸 마시면 누구보다도 용감해질 수 있을 것이오.'),
(27986, 3, 0, '자넨 끝내주는 구경거리를 놓쳤다네, 도리안! 수십 년에 한 번 볼까 말까 한 광경이었는데!'),
(27986, 4, 0, '우린 쿵쿵이 등에 타고 전속력으로 놈을 향해 달려갔지...'),
(27986, 5, 0, '글쎄다, 꼬마야. 먼저 ''가시덤불 골짜기의 푸른 언덕''을 읽어 보면 어떨까. 그러고 나면 우리 탐험대에 들어올 수도 있을 거야. 어때?'),
(27990, 0, 0, '너무 늦었구나, $n. 달라란에서 다른 이가 와서 그대와 마찬가지로 오색 용검에 대해 물었다.'),
(27990, 1, 0, '그대의 설명을 들어 보니, 앞서 온 이에게 빌려준 책을 보면 그 무기가 무엇인지 쉽게 알 수 있을 듯하구나.'),
(27990, 2, 0, '미안하지만 그자에게 가서... 아니, 어쩌면 칼렉고스가 도울 수 있을지도 모르겠군.'),
(27990, 3, 0, '$n|1이;가; 오색 검의 잔해를 찾았나 보오, 칼렉고스. 그대가 이 손님을 좀 도와주겠소?'),
(27990, 4, 0, '우리의 동맹이 검에 담긴 힘을 제대로 제어하지 못하리라 생각하시오?'),
(27990, 5, 0, '우리 모두 그리할 것이오.'),
(27990, 6, 0, '자, 필멸의 존재여, 달라란에 있는 신비술사 티발린과 이야기하기 바란다. 그가 선리버와 협상해 책을 볼 수 있게 해줄 게다.'),
(27990, 7, 0, '자, 필멸의 존재여, 달라란에 있는 마법학자 하소렐과 이야기하기 바란다. 그가 은빛 서약단과 협상해 책을 볼 수 있게 해줄 게다.'),
(27990, 8, 0, '안심하라, 케켁. 용의 여왕이 맞다. 우리는 작은 존재를 상대할 때 종종 그들과 같은 모습을 취하기도 한다.'),
(28012, 0, 0, '교활한 마법사 군주 우롬이 세 번째 고리를 보호하고 있습니다. 놈은 무방비 상태로 혼자 있는 것처럼 보이지만, 겉모습에 속아서는 안 됩니다! 우롬은 실체 없는 생물 군단을 지휘하는 강력한 요술사입니다. 위쪽에서 그를 찾아보십시오.'),
(28012, 1, 0, '가장 큰 도전이 눈앞에 있습니다. 지맥 수호자 에레고스는 엄청난 힘을 지닌 푸른용입니다. 에레고스는 꼭대기 고리 위를 선회하고 있을 것입니다.'),
(28012, 2, 0, '그대의 비룡은 이제 최고의 힘을 사용할 수 있습니다. 그 힘을 사용해 에레고스를 격파하십시오!'),
(28016, 0, 0, '아, 드디어 드락타론 성채에 돌아왔군!'),
(28016, 1, 0, '드라쿠루가 드락타론 성채를 내려다봅니다.'),
(28016, 2, 0, '잘했네, 친구...'),
(28016, 3, 0, '더 바랄 수 없을 만큼 훌륭했어.'),
(28016, 4, 0, '자네는 그 대가로 엄청난 보상을 얻게 될 거야.'),
(28016, 5, 0, '바로 깨달음을!'),
(28016, 6, 0, '숨을 죽이게, 친구. 진실을 똑똑히 목격하게!'),
(28016, 7, 0, '주인님, 저는 임무를 완수했습니다.'),
(28016, 8, 0, '필멸의 존재에게 도움을 받아, 이 지역의 적을 박살 냈습니다.'),
(28016, 9, 0, '주인님의 뜻대로...'),
(28016, 10, 0, '속여서 미안하네, 친구. 다 자네를 생각해서 그런 게야.'),
(28016, 11, 0, '괜찮은 녀석이란 확신이 필요했거든...'),
(28016, 12, 0, '줄드락을 공략하려면 유능한 부하가 필요해, 친구. 진정한 힘을 다룰 줄 아는 자가 말일세.'),
(28016, 13, 0, '이제 알았겠지? 리치 왕께서는 복종하는 자에게 너그러우시다네.'),
(28016, 14, 0, '이 길을 따르게, 친구. 그러면 자네는 불멸을 맛보게 될 게야!'),
(28030, 0, 2, '최후의 심판이다.'),
(28030, 0, 5, '죽어라!'),
(28033, 0, 0, '드디어, 놈리건의 정신호를 수리할 부품이 우리 손에 들어왔어요.'),
(28033, 1, 0, '어디 볼까요. 여기를 조정하고, 저기를 조절하면...'),
(28033, 2, 0, '자 다 됐어요. 이게 바로 놈리건의 정신호예요!'),
(28033, 3, 0, '그 비행기를 타도 좋지만, 좌석에 톱날이 있다고 투덜거리지는 마세요. 구할 수 있는 부품이 그게 다였으니까요.'),
(28041, 0, 0, '조심하십시오, $c|1이여;여;. 이 트롤 녀석들은 자기네가 섬기던 뱀 신마저 죽였습니다!'),
(28041, 0, 1, '조심하십시오. 드라카리 녀석들은 아주 비열합니다.'),
(28041, 0, 2, '드라카리란 족속은 그저 사소한 골칫덩이일 뿐입니다. 우린 이곳을 떠나 정의를 행하러 가야 합니다!'),
(28041, 0, 3, '나중에 봅시다.'),
(28041, 0, 4, '대체 어디로 간다는 건지 모르겠군요. 그리고, 우리가 떠나면 누가 이놈들을 상대합니까?'),
(28041, 0, 5, '네. 하사관님께 돌아가겠습니다.'),
(28041, 0, 6, '$n|1이라고;라고;? 죽었다고 들었는데.'),
(28047, 0, 0, '전 항상 그림부즈가 만든 술에 관심이 많답니다.'),
(28047, 1, 0, '글쎄요, 지금까지는 우리 집사람이 마시던 거랑 비슷한 거 같은데...'),
(28047, 2, 0, '이게 바로 그림부즈의 술 맛이죠! 맘에 드는군요!'),
(28054, 0, 0, '수염은 안 돼! 균형이 안 맞게 돼 버렸잖아!'),
(28054, 0, 1, '악! 좋아, 이제 표적 신세는 사양하겠어!'),
(28054, 0, 2, '내 귀! 내 귀를 쏘다니!'),
(28054, 1, 0, '멋진 사격이야!'),
(28068, 0, 0, '음, 모조가 더 있군.'),
(28068, 1, 0, '안 돼애애애애애.........!'),
(28068, 2, 0, '감히 우리를 공격해? 어리석은 놈들! 우리가 신의 힘을 얻었다는 걸 모르는 게냐?!'),
(28068, 2, 1, '야생 신의 힘이 우리 핏줄을 타고 흐르는 이상, 그 누구도, 리치 왕이라 하더라도 우리를 막을 수는 없다!'),
(28068, 2, 2, '거기 벌레 같은 녀석아! 가까이 와라.'),
(28068, 2, 3, '감히 우리 제단을 더럽히는 저 침입자들을 죽여라!'),
(28068, 2, 4, '은빛십자군을 쳐부술 테다! 스컬지를 뭉개버릴 테다!'),
(28068, 2, 5, '놈들을 모두 죽이고 나면 남쪽에 있는 놈들의 동족을 죽이러 간다!'),
(28068, 2, 6, '세라투스의 모조는 우리 것이다. 곧 모든 것이 드라카리의 힘 앞에 산산이 부서지리라!'),
(28068, 2, 7, '형제여, 깊게 들이마셔라!'),
(28070, 0, 0, '이거 전보다 더 까다로운데? 젠장, 온다!'),
(28070, 1, 0, '마도란이시여! 저건 또 뭐야? 오! 잠깐! 알 것 같은데...'),
(28070, 2, 0, '하하, 됐어요! 지원군이 갑니다! 이거나 받아라! 무쇠 괴물아!'),
(28070, 3, 0, '온몸이 만신창입니다... 더 버틸 수가...'),
(28070, 4, 0, '로켄?! 이거 정말 귀찮아졌군... 무쇠 드워프는 무찌른 것 같습니다만, 아직 저 어딘가에 무쇠 브리쿨을 대량으로 뽑아내는 기계가 있나 봅니다!'),
(28070, 5, 0, '아직은... 안돼...'),
(28070, 6, 0, '잠시 저와 함께 이 순간을 즐깁시다. 이제, 모든 게 밝혀질 거예요. 좋아요. 시작합시다!'),
(28070, 7, 0, '해답을 찾을 시간입니다! 이제 가보자고요!'),
(28070, 8, 0, '오, 밥값 좀 하시는군요!'),
(28070, 8, 1, '좋아요! 바로 그겁니다!'),
(28070, 8, 2, '밀어붙이세요! 모두를 위해 잘하고 계십니다!'),
(28070, 9, 0, '이제 잘 보시라고요! 제가 눈 깜짝할 사이에 정보를...'),
(28070, 10, 0, '아이고, 좋은 소리 같진 않네요. 에... 문제가 한두 개 생길지도...'),
(28070, 11, 0, '허허, 해보겠다는 거냐, 엉? 이쪽도 방법이 있지!'),
(28070, 12, 0, '조금만 있으면 제가... 어, 어라?'),
(28070, 13, 0, '상승했다고? 좀 좋은 소식은 없나?'),
(28070, 14, 0, '그래, 이게 문제였군! 이제 방법을 알았으니...'),
(28070, 15, 0, '잠깐! 내가 권한을 쥐고 있는데, 검증 따위 받을 것 같으냐!'),
(28070, 16, 0, '하! 늙은이의 노련한 손길이 마침내 통하는군! 이제 이걸...'),
(28070, 17, 0, '소거? 안 돼, 안 돼, 안 돼... 어째서 이게... 아하, 이러면 되겠군!'),
(28070, 18, 0, '해답을 찾을 시간입니다! 이제 가보자고요!'),
(28070, 19, 0, '할 수 있는 건 다 하고 있습니다!'),
(28070, 19, 1, '빛이 돌봐줄 겁니다!'),
(28070, 19, 2, '무의미한 희생이 아니길 빕니다!'),
(28070, 20, 0, '질문? 내가 여기 왜 왔겠나, 엉? 척 하면 딱 해야지!'),
(28070, 21, 0, '드워프가 어떻게 창조됐는지 얘기해 봐라! 처음부터 낱낱이!'),
(28070, 22, 0, '됐어, 됐어. 세상 깊숙한 곳을 다듬게 하려고 창조주가 돌로 토석인을 만들었지? 그런데 부작용은 왜 생겼나? 모형 불안정화 어쩌고 하는 얘기 있잖나.'),
(28070, 23, 0, '기생성 뭐 어째? 공용어로 얘기해라! 엉?!'),
(28070, 24, 0, '고대 신이라... 그들이 토석인에게 육체의 저주를 걸었단 말이지... 에... 그래서?'),
(28070, 25, 0, '고대 신들을 없앴다면, 아제로스는 산산조각났을 게야...'),
(28070, 26, 0, '무슨 수호자?'),
(28070, 27, 0, '에시르와 바니르... 그래... 그래서 의지의 용광로로 새 토석인을 만들기 시작했다는 거군... 그럼 옛 토석인은 어찌 됐지?'),
(28070, 28, 0, '잠깐, 잠깐! 에시르와 바니르가 전쟁을 했다고? 왜?'),
(28070, 29, 0, '으으... 이 "로켄"이란 녀석, 아주 나쁜 놈 같군. 이제 내 이 녀석한테 신경 쓸 필요가 없어서 다행이야. 그래서... 내가 바로 이해했다면, 어떤 이유에서인지 원조 토석인이 이 정체 상태에서 벗어났고, 그때 그... 불안정환지 뭔지 때문에, 결국 지금의 드워프가 된 거지. 아니면, 드워프의 조상이 됐거나. 응?'),
(28070, 30, 0, '으음... 그래... 정말 대단한 얘기였어. 곰곰이 생각 좀 해봐야겠군. 고맙네.'),
(28070, 31, 0, '용광로로 토석인을 한 무리 만들어내서 경비를 세우겠습니다. 하지만 가장 힘든 일이 남았어요. 로켄을 찾아서 저지하세요!'),
(28070, 32, 0, '괜찮아요! 늙은 브란이 있잖습니까! 무쇠 괴물 좀 맡아주세요. 그동안 저는 이 기계가 도움이 될지 만져보죠.'),
(28070, 33, 0, '입구 근처의 문 뒤에 무엇이 숨어 있는지 확인해봐야겠습니다. 조용히 그쪽으로 이동할게요. 문 앞에서 만나서 같이 들어갑시다.'),
(28070, 34, 0, '당신 말이 맞아요. 나중에 다시 올 수도 있죠. 지금은 저 입구 근처에 있는 문 뒤에 뭐가 있는지 확인해볼 시간이에요. 제가 저리로 슬그머니 숨어들어 갈게요. 문으로 오시면 제가 우리 모두 들어가도록 하겠어요.'),
(28076, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(28077, 0, 0, '날름이와 한 패가 되다니 어리석어! 너는 이제 광란심장 일족 친구 아니다. 광란심장 일족이 손 좀 봐줄 거야.'),
(28078, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(28090, 0, 0, '우리가 이 땅을 정화하겠습니다! 들리느냐, 아서스!'),
(28090, 0, 1, '당신 말이 맞습니다! 우린 해낼 수 있어요!'),
(28090, 0, 2, '당신 말이 맞습니다! 전 대체 무슨 생각을 하고 있었던 거죠? 나와라, 스컬지 놈들아!'),
(28092, 0, 0, '최후의 룬이 배치되었습니다. 성공적으로 활성화되었습니다.'),
(28095, 0, 0, '안 돼! 내가 찍어놓은 놈을 훔쳤어! 너 게크게크한테 빚졌다!'),
(28095, 1, 0, '멍청아! 쏘지 마! 게크게크가 저놈 멀쩡한 상태로 잡을 거다!'),
(28095, 2, 0, '도망치게 두면 안 돼! 이번에 꼭 잡는다.'),
(28095, 2, 1, '조심해! 그놈이 지난번처럼 할퀴지 못하게 해.'),
(28095, 2, 2, '으아아! 우리한테 오잖아!'),
(28103, 0, 0, '우르그레스가 강력한 어둠의 기운을 내뿜기 시작합니다!'),
(28105, 0, 0, '내 보물! 타르텍의 물건에 손대지 마라, 멍청한 배신자, 날름이의 친구야!'),
(28105, 1, 0, '이 타르텍과 무시무시한 용이 널 혼내줄 거다! 너 바보야.'),
(28113, 0, 0, '내 반짝이... 가져가. 이젠 다 끝이야...'),
(28113, 0, 1, '우리 아무 짓도 안했어... 저놈들한테... 나 이해 안 가.'),
(28113, 0, 2, '내 반짝이 가져가... 다시 날씨 좋게 해줘... 언데드 같은 거 가버리게 해.'),
(28113, 0, 3, '우리 제단에 반짝이 바쳤어... 우리 욕심쟁이 아냐... 그런데 왜 이런 일 일어나?'),
(28113, 0, 4, '내가 나쁜 짓 한 거야? 나 미안해...'),
(28113, 1, 0, '살았다. 너 착해, 뽀송피부.'),
(28113, 1, 1, '너도 날씨 좋게 할 수 있어?'),
(28113, 1, 2, '너 우리 구해줬어! 너 만세야!'),
(28113, 1, 3, '고마워! 너 착해!'),
(28113, 3, 0, '이끼걸음골록 희생자가 고통 속에서 신음합니다.'),
(28120, 0, 0, '우와! 반짝반짝!'),
(28120, 0, 1, '빛나는 반짝이 더 있을 거야! 우리는 반짝이 좋아해!'),
(28120, 0, 2, '라푸 보물이다! 제단에 바칠 보물이다!'),
(28120, 0, 3, '파자, 파자, 파자...'),
(28120, 0, 4, '바삭바삭 벌레는 너무 맛나. 좀 줄까?'),
(28120, 0, 5, '진짜 이상해. 누가 우리 벌레를 다 가져갔어. 네가 그랬어?'),
(28120, 1, 0, '이번엔 절대로 돌아오지 마!'),
(28120, 2, 0, '언젠가는 너도 수뽀송피부 될 수도 있어. 좋지?'),
(28120, 2, 1, '파이 있어? 몇 년 전에 누가 우리한테 파이 준 적 있어. 정말 맛있었는데.'),
(28120, 2, 2, '크고 편한 나무야. 좋은 집이지.'),
(28120, 2, 3, '위대한 자들 만나본 적 없어. 없다고. 그냥 제단만 봤어.'),
(28120, 2, 4, '네 눈알 진짜 웃겨.'),
(28120, 3, 0, '집 좋아. 그래도 오래 있으면 안 돼! 모험을 더 해야지!'),
(28120, 4, 0, '쉿... 쉿... 죽었어. 완전히 죽었어.'),
(28121, 0, 0, '반짝이! 반짝이! 내 수정만큼 반짝거리지는 않지만, 그래도 반짝이는 반짝이!'),
(28121, 0, 1, '보물 더 나와라! 가지가지 나와라! 야호 보물이다!'),
(28121, 0, 2, '반짝이는 수정은 가져도 가져도 또 가지고 싶어! 아무렴!'),
(28121, 0, 3, '우리 땅 진짜 빨리 파지! 봐봐... 벌써 다 했어! 빠르지, 그렇지?'),
(28121, 1, 0, '맘에 들어? 안 드는 거 같아! 네가 왜 맘에 안 들어하는지 알아. 왜냐면 넌 죽었으니까! 우하하하!'),
(28121, 1, 1, '승...리...를! 띠리리 리리리!'),
(28121, 1, 2, '신나게 쓸어보자!'),
(28121, 2, 0, '안개부름이는 제단의 힘으로 날씨를 참 잘 다스려. 어떤 수정을 사용하는지 그냥 안다니까! 정말 잘해!'),
(28121, 2, 1, '걸어서 여행한 적 있어? 우린 있어. 좀 힘들지. 하지 마, 재미없어. 절대로.'),
(28121, 2, 2, '우리 도움 필요해? 뭐 도와줄까? 우리 도와주기 잘해.'),
(28121, 2, 3, '안녕! 너 정말 튼튼하고 착하고 멋져. 나 너 좋아. 우리 친구 하자, 응?'),
(28121, 2, 4, '안개야. 아주 자욱해. 너한테도 안개같이 보여? 그렇게 짙은 안개는 아닐지도 모르지.'),
(28121, 2, 5, '나무에서 뛰어 보자! 폴짝! 재밌다!'),
(28121, 3, 0, '그 조그만 녀석들 잡아! 그 녀석들 잡으라고! 그런데 너무 빠르잖아!'),
(28121, 3, 1, '위대한 자들이 안전하게 집 지켜줬어. 점쟁이 조합을 좋아하기 때문이라고 생각해! 우리가 착하고 괜찮다는 걸 아니까.'),
(28121, 3, 2, '집으로 집으로 집으로... 반짝이들이 가득한 곳이야!'),
(28121, 4, 0, '너한테 그 용 뭐인가가 있다는 거 다 알아! 너랑 그 용인지 뭐인지 다 잡아 버릴 거야!'),
(28121, 4, 1, '우리 보물 훔쳐오는 법 가르쳐줄게! 우리 보물은... 우리 거니까, 그렇지?'),
(28121, 4, 2, '하룻강아지가 숨을 차례다! 꼭꼭 숨어라... 머리카락 보일라!'),
(28121, 5, 0, '타르텍도 너 못 이겨! 너 기술 있잖아. 앗싸!'),
(28122, 0, 0, '도대체 반짝거리는 토끼가 여기 왜 있는 거지?'),
(28122, 0, 1, '내가 여기서 뭐 하냐면, 얼마 전에 만난 어떤 분의 뜻을 따라 땅에서 쓸모없는 쓰레기들을 파낸다고... 이게 말이 된다고 생각해?'),
(28122, 0, 2, '저기... 쓸데없는 벌레만 더 나올 거 같은데.'),
(28122, 0, 3, '만세... 또 흙이야.'),
(28122, 1, 0, '믿을 수가 없어... 전부 다... 죽었어.'),
(28122, 1, 1, '우리 공격에 또 하나 쓰러졌어.'),
(28122, 2, 0, '아직 여기 남아 있는 이유라도 있어? 있으면 말해봐.'),
(28122, 2, 1, '좋아. 지금 가자고.'),
(28122, 2, 2, '여기선 볼 일 끝났어.'),
(28122, 3, 0, '낮잠 자러 갈 거야? 자는 동안 네 얼굴을 밟을지도 모르니까 미리 사과할게.'),
(28122, 3, 1, '그냥 그렇게 계속 뭉개고 있을 참이야, 아니면 좀 영양가 있는 일을 해볼 셈이야?'),
(28122, 3, 2, '행성만 한 두뇌를 가진 나에게 당신을 다른 마을로 데려다주라니. 이게 보람찬 일이라고 생각합니까? 나는 아닙니다.'),
(28122, 4, 0, '이끼걸음 부족은 좋은 이들이었어요... 이런 일을 당할 이유가 없었습니다.'),
(28122, 4, 1, '내가 그놈들을 좀 얕잡아보고 말하는 거 알아. 하지만, 우리 골록 하나라도 죽는 건 보고 싶지 않거든.'),
(28122, 4, 2, '이끼걸음골록이 생각보다 빨리 기운을 회복하는 걸 보니 좋아.'),
(28122, 4, 3, '여기서 살아남은 누군가가 있다니 믿기지 않아.'),
(28122, 4, 4, '아직 살아 있는 게 더 있을지도 몰라! 계속 움직여야 해.'),
(28122, 4, 5, '저 희생자를 끌고 어디로 가는 거야? 희생자한테 무슨 짓을 하는 거야?'),
(28122, 5, 0, '이 싸움은 전부 너한테 맡길게!'),
(28122, 6, 0, '언데드가 되어 돌아온 골록이 아무도 없어서 그나마 다행스러워.'),
(28136, 0, 0, '고맙습니다, 친구여. 당신 도움이 아니었다면 난 이곳에 없었을 것입니다.'),
(28136, 1, 0, '내 인생도 이걸로 끝이군요...'),
(28142, 0, 0, '뭐, 더 나쁘게 죽었을 수도 있지.'),
(28142, 1, 0, '내 인생도 이걸로 끝이군요...'),
(28160, 0, 0, '제 비행기로 분지에 보내드리겠습니다. 헤멧에게 무슨 일이 일어났는지에 대한 단서를 잘 찾아보십시오!'),
(28167, 0, 0, '아서스 왕자님, 빛의 가호가 있기를! 마을 사람 여럿이 심각한 병에 걸렸습니다. 저희를 도와주시겠지요?'),
(28169, 0, 0, '뭐라고요? 이럴 수가!'),
(28175, 0, 0, '사로나이트라고 했던가?'),
(28175, 1, 0, '들어본 적도 없네. 그야말로 악의 정수로 보이는군.'),
(28175, 2, 0, '내 도끼에 맞으면 어떻게 되는지 보지!'),
(28175, 3, 0, '이럴 수가? 내 도끼를 맞고도 흠집조차 나지 않는다니! 이토록 강한 광석은 지금까지 본 적이 없어!'),
(28175, 4, 0, '어이쿠!'),
(28176, 0, 0, '그래. 정말로 그토록 강한지 시험해 보지.'),
(28176, 1, 0, '소용없군.'),
(28177, 1, 0, '아악!'),
(28178, 0, 0, '%s|1이;가; 골똘히 뭔가를 생각합니다.'),
(28178, 1, 0, '놀랍지도 않군.'),
(28178, 2, 0, '뭐지?'),
(28178, 3, 0, '좋아. 하지만 기억해 두게, 형제여. 성스러운 빛의 힘은 손쉽게 일으킬 수 있는 게 아니라네.'),
(28178, 4, 0, '광석이 왜 저러지?'),
(28178, 5, 0, '우와!'),
(28178, 6, 0, '%s|1이;가; 투덜거립니다.'),
(28179, 0, 0, '리치 왕은 신속하게 그 틈으로 반격해왔네. 예견했던 것보다도 더 빨리 말일세.'),
(28179, 1, 0, '나더러 뭘 하란 말인가?'),
(28179, 2, 0, '언사를 조심하라, 죽음의 기사여. 지금 헌신한 자들에 둘러싸여 있으니.'),
(28179, 3, 0, '우린 명예롭게 이 일을 해낼 걸세. 승리를 거둔다는 일념으로 스컬지와 같은 수준으로 추락하지는 않을 걸세. 그렇게 한다면 우리가 싸워 물리치려는 저들과 다를 바가 없지 않겠나!'),
(28189, 0, 0, '주인님, 신도들을 침투시켜 얼라이언스 지도부를 장악하는 계획이 착착 진행되고 있습니다.'),
(28189, 1, 0, '제게 허락하신 힘은 인간의 마음을 조종하는 데 대단히 유용했습니다. 지금 보여 드릴 제물이 그 증겁니다.'),
(28189, 2, 0, '제가 침입자를 처리하게 해주십시오. 놈들에게 지옥을 맛보여 주겠습니다.'),
(28189, 3, 0, '예, 주인님!'),
(28205, 0, 0, '서두르게. 가서 가져와...'),
(28205, 0, 1, '그걸 넣어야겠군...'),
(28205, 0, 2, '이번에 가져올 건...'),
(28205, 0, 3, '더 필요한 게...'),
(28205, 0, 4, '그게 좀 필요하겠는데...'),
(28205, 0, 5, '더 필요한 게...'),
(28205, 1, 0, '흐음, 이번에 넣을 건...'),
(28205, 1, 1, '다음은...'),
(28205, 1, 2, '맛을 보니 더 넣어야 할 게 있는데...'),
(28205, 1, 3, '거의 다 됐네. 이번에 가져올 건...'),
(28205, 2, 0, '잘 되고는 있는데, 아직 필요한 게 있어...'),
(28205, 2, 1, '뻑뻑해지기 전에 그걸 넣어야 해...'),
(28205, 3, 0, '끓어 넘치기 전에 넣어야 할 텐데...'),
(28205, 3, 1, '뻑뻑해지고 있잖아! 어서! 그걸 좀 가져오게...'),
(28205, 4, 0, '자넨 너무 느리군. 처음부터 다시 시작해야 하나...'),
(28205, 4, 1, '안 돼! 물약을 망쳐버렸잖아!'),
(28205, 5, 0, '솜엉겅퀴 뿌리!'),
(28205, 6, 0, '소금에 절인 독수리 알!'),
(28205, 7, 0, '얼룩덜룩한 조분석!'),
(28205, 8, 0, '말라버린 박쥐날개!'),
(28205, 9, 0, '가미한 주룩주룩 탄산수!'),
(28205, 10, 0, '분쇄된 가고일 이빨!'),
(28205, 11, 0, '진흙투성이 늪 구더기!'),
(28205, 12, 0, '뾰족한 거미 알!'),
(28205, 13, 0, '털투성이 청어 머리!'),
(28205, 14, 0, '악취나는 해적 땀!'),
(28205, 15, 0, '병에 든 얼음왕관 샘물!'),
(28205, 16, 0, '말벌 날개!'),
(28205, 17, 0, '오색 모조!'),
(28205, 18, 0, '랩터 발톱!'),
(28205, 19, 0, '호박색 씨앗!'),
(28205, 20, 0, '쭈그러든 용의 발톱!'),
(28205, 21, 0, '한기서린 뱀 점액!'),
(28205, 22, 0, '결정화된 돼지 코딱지!'),
(28205, 23, 0, '박살난 바실리스크 수정!'),
(28205, 24, 0, '트롤맹독!'),
(28205, 25, 0, '얼어붙은 거미 수액!'),
(28213, 0, 0, '%s|1이;가; 분노에 찬 포효를 내지르며 자신의 새끼를 도우려 달려갑니다.'),
(28214, 0, 0, '집에 왔군! 고어게크가 먹을 고기를 가져 와라, 노예.'),
(28214, 0, 1, '고어게크 자러 간다. 먹을 거 구해 놔라, 노예.'),
(28214, 0, 2, '고어게크 술 마실 거다. 고어게크가 준비될 때까지 구석에 처박혀 있어라.'),
(28214, 0, 3, '고어게크 배고프다. 모닥불 위에 올라가라, 노예. 다 구워지면 말해라.'),
(28214, 0, 4, '고어게크가 닭 전부 잡을 거다!'),
(28214, 0, 5, '고어게크 준비될 때까지 기다려라.'),
(28214, 0, 6, '기다려라, 노예. 고어게크 식사 중이다.'),
(28214, 1, 0, '고어게크는 최고의 사냥꾼이다...'),
(28214, 1, 1, '하하! 고어게크가 잡았다!'),
(28214, 1, 2, '다음번엔 고어게크가 너한테 시켜봐야겠다.'),
(28214, 1, 3, '급소를 정확히 찔렀어! 고어게크 참 잘한다.'),
(28214, 1, 4, '끼익! 깨액! 끝내주는군!'),
(28214, 1, 5, '광란심장 일족이 제일 강하다!'),
(28214, 1, 6, '그렇게 하는 거다, 노예. 언젠가는 너도 알게 될 거다.'),
(28214, 2, 0, '고어게크 왜 네놈을 데려왔지. 아무짝에도 쓸모가 없는데.'),
(28214, 2, 1, '장로가 뭐라 말하든 간에 넌 영원히 고어게크의 노예다.'),
(28214, 2, 2, '검은 갈기는 어차피 약해빠졌어... 아니면 이 고어게크가 왜 그놈을 그냥 놔두겠어?'),
(28214, 2, 3, '자기가 자기를 때리다니! 하하! 정말 바보다, 노예.'),
(28214, 3, 0, '조심해라, 노예. 커다랗고 나쁜 비단돌기고릴라가 널 먹어치울지도 모른다! 하하!'),
(28214, 3, 1, '바위돌기고릴라는 아직도 네 발로 기어다닌다... 고어게크 생각엔 좀 바보 같다.'),
(28214, 3, 2, '도망쳐라, 멍청한 비단돌기고릴라야! 꼬챙이로 푹푹 찔러버릴 거다!'),
(28214, 3, 3, '도망가라, 비단돌기고릴라들아! 고어게크가 잡으러 나가신다!'),
(28214, 3, 4, '구경이나 해라, 노예. 고어게크가 바위돌기고릴라 다 해치운다!'),
(28214, 3, 5, '고어게크 가는 길을 막지 않는 게 좋을 거다!'),
(28214, 3, 6, '비켜라, 멍청한 노예같으니! 고어게크가 잡을 거다!'),
(28214, 3, 7, '이 고어게크는 바위돌기고릴라를 수백 번이나 상대했다.'),
(28214, 4, 0, '아하! 고어게크는 최고 사냥꾼이다! 제일 큰 바위돌기고릴라 고어게크가 잡았다!!'),
(28214, 5, 0, '광란심장 일족이 카르탁에게 날름이들을 먹이로 주었기 때문에 카르탁이 우리를 먹지 않는다. 그래서 우리가 너희보다 똑똑하다는 거다, 노예.'),
(28215, 0, 0, '광란심장 일족이 새로운 보금자리를 찾아 이곳으로 온 것도 그리 오래전은 아니다... 날름이 보금자리가 꽤 좋은 곳이어서 우린 그곳도 차지하려 한다. 어쨌든 좋은 놈들은 아니니까.'),
(28215, 0, 1, '강한 광란심장 일족 여기 많다. 다지크가 대부분 가르쳤지. 처음에는 너 같은 것도 가르쳤지. 알겠지만 너는 광란심장 일족이 아니다.'),
(28215, 0, 2, '가시털멧돼지나 먹는 게 어때? 쫓아다니는 것도 지겹다.'),
(28215, 0, 3, '광란심장 일족이 닭을 쫓아가지 않는 이유가 있다. 닭을 잃어버리면 얼간이로 보이기 때문이지.'),
(28215, 0, 4, '아는지 모르겠지만, 닭은 꽤 잽싸게 움직인다.'),
(28215, 0, 5, '다지크가 쓸모 있는 걸 또 알려주지! 고어게크가 또 닭을 풀어놓거든 직접 잡으라고 해.'),
(28215, 0, 6, '말뚝 대부분을 내가 박아놓았다. 뾰족뾰족하게 딱 좋은 정도지. 맘에 드나?'),
(28215, 0, 7, '아! 다지크에게 좋은 생각이 있다. 닭 울음소리를 내면 닭이 너한테 몰려올지도 모른다!'),
(28215, 1, 0, '그런거 치워 버려! 다지크는 그런 거치적거리는 것들 딱 질색이야. 짜증난다.'),
(28215, 1, 1, '그 얼굴 봤나? 완전히 겁에 질렸더군. "아, 난 이제 죽었구나!"하는. 하하.'),
(28215, 1, 2, '하! 드디어 뭘 좀 배운 모양이군!'),
(28215, 1, 3, '그래! 혹시 모르니까 몇 번 더 찔러! 막 찌르라고!'),
(28215, 1, 4, '어떻게 여기 왔는지 모르겠다. 죽었으니 상관없지만.'),
(28215, 2, 0, '우리 뭔가를 하러 오지 않았나? 기억이 안 난다.'),
(28215, 2, 1, '아무것도 잊어버리지 마라. 난 가끔씩 그런다.'),
(28215, 2, 2, '다지크는 네가 뭔가 먹는 걸 못 본 것 같다. 뭔가 먹긴 하나?'),
(28215, 2, 3, '끝내주는 공격 계획을 짜던 중이었는데... 내 분필이 너한테 있다.'),
(28215, 2, 4, '다지크가 쓸모 있는 걸 또 알려주지! 뭔가 꺼내려 입을 열어 보기 전에 죽었는지 반드시 확인해라!'),
(28215, 3, 0, '다지크가 돌아올 때마다 벌레들이 늘어나는 것 같다. 왜 줄어들지를 않는 거지?'),
(28215, 3, 1, '다지크가 쓸모 있는 걸 또 알려주지! 독침 달린 놈들을 정면으로 잡으려 하지 마라. 별로 좋은 방법이 아니다.'),
(28215, 3, 2, '궁금할까 봐 말해주겠는데, 벌레들한테 쏘이면 별로 기분이 좋지 않다. 괜히 시험해볼 생각 마라.'),
(28215, 3, 3, '일꾼은 보이는 것만큼 세지 않다. 말벌은 좀 껄끄럽지만.'),
(28215, 3, 4, '다지크가 쓸모 있는 걸 또 알려주지! 독침 달린 놈들을 정면으로 잡으려 하지 마라. 별로 좋은 방법이 아니다.'),
(28215, 4, 0, '안 돼! 여왕을 죽여버리다니! 무슨 짓을... 잠깐, 신경 쓰지 마라. 미안하다. 괜찮다.'),
(28215, 5, 0, '지난번에 다지크에게 배웠던 놈은 모래 괴물에게 먹혀 버렸다. 하지만 이번엔 그렇게 안 될걸!'),
(28215, 6, 0, '광란심장 일족이 사냥한 여왕이 이게 처음은 아니다. 언제나 여왕 더 있었던 것 같다.'),
(28215, 7, 0, '날름이들이 가끔 수정을 캐러 오곤 한다. 우리가 놈들을 사냥하니까 지금은 오지 않는다.'),
(28215, 7, 1, '다지크가 쓸모 있는 걸 또 알려주지! 등 긁는 데 수정을 써봤자 별 쓸모가 없다. 해보지 마라.'),
(28215, 7, 2, '뭔가 거대한 것이 기둥을 만들고 수정을 만들고 모든 걸 만들었다. 하지만 더는 이곳에 없으니 광란심장 일족은 별로 신경 쓰지 않는다.'),
(28215, 8, 0, '여기서 비단돌기고릴라를 더 찌르려 한다면 이 다지크가 너까지 찔러버릴 거다. 그건 고어게크 나쁜 습관이다.'),
(28215, 8, 1, '음... 여긴 어디지? 이상하다. 바위돌기고릴라를 찾으라는 얘기 내가 하지 않았나? 했었나?'),
(28215, 9, 0, '다지크가 쓸모 있는 걸 또 알려주지! 시체가 널렸다는 건 시체가 될 가능성도 크다는 거다. 다지크는 지금 여기서 나간다.'),
(28215, 9, 1, '죽은 놈들은 이미 무너진 기둥이 주는 교훈을 깨달았을 테지. 교훈은 죽은 얼간이들이나 곱씹게 내버려 둬라. 이제 집으로 돌아간다.'),
(28215, 9, 2, '이제 배울 것은 다 배웠군! 모두 배웠어! 이제 너와 끔찍한 피 봉우리와도 작별이다.'),
(28216, 0, 0, '좋은 고기를 가져오면 그날은 야영지에서 대주술사님처럼 대접 받을 거다. 괜찮은 거래잖아.'),
(28216, 0, 1, '하르케크 장로님은 좋은 광란심장 일족이다. 내가 어릴 때 여러모로 도와주셨다. 다지크는 좋아하지 않아.'),
(28216, 0, 2, '그렇게 서두를 건 없어. 쉬고 싶으면 여기서 좀 쉬어도 괜찮아.'),
(28216, 0, 3, '내가 항상 여기 머물지는 않아. 얼마 전까지도 세계 곳곳을 혼자 여행했지. 난 야수와 용족, 신과 보물 이야기를 좋아해.'),
(28216, 0, 4, '닭들을 다시 풀어준 다음 고어게크가 했다고 말해. 유치하다고 생각할 거 없어.'),
(28216, 1, 0, '하하! 저거 봤어? 벼락이 머리에 정통으로 꽂혔어!'),
(28216, 1, 1, '또 한 놈 잡았어! 그놈은 무슨 일이 일어났는지도 모르나봐.'),
(28216, 1, 2, '또 놀아 줄래?'),
(28216, 2, 0, '용이나 신이나 뭐 그런 것들이랑 싸워본 적 있어? 제피크는 이야기 듣는 거 좋아해.'),
(28216, 2, 1, '쓸만하군! 타고난 사냥꾼이야. 나처럼 말이지.'),
(28216, 2, 2, '고어게크는 자기가 대장이라고 생각하지만... 엄청나게 먹기만 할 뿐, 사냥은 쥐꼬리만큼 해와.'),
(28216, 2, 3, '좋은 고기를 가져오면 그날은 야영지에서 대주술사님처럼 대접 받을 거다. 괜찮은 거래잖아.'),
(28216, 2, 4, '다지크는 자기가 뭘 하는지, 어디 있는지 잊어버려... 자기 이름도 기억 못 할걸. 그러니 별로 좋은 스승은 못 되지.'),
(28216, 2, 5, '하르케크 장로님은 좋은 광란심장 일족이다. 내가 어릴 때 여러모로 도와주셨다. 다지크는 좋아하지 않아.'),
(28216, 2, 6, '고어게크는 절대로 닭장에 "걸려 넘어지는" 게 아니야. 그놈은 항상 멍청한 배를 채우려 들어. 닭을 다 잡고 보면 꼭 한 마리가 빈단 말이지.'),
(28216, 2, 7, '다지크는 내게 사냥하는 법을 가르치려 했는데, 난 내 식대로 할 때 더 잘해.'),
(28216, 3, 0, '날름이들아, 이거나 먹어라!'),
(28216, 3, 1, '이런! 이 제피크가 할 일도 좀 남겨 달라고.'),
(28216, 3, 2, '여기 주변 호수에는 바다 생물이 잔뜩 살고 있어. 어떻게 흘러든 건지 모르겠네... 물살에 떠밀려 온 건가?'),
(28216, 3, 3, '내가 왜 날름이 사냥을 좋아하는지 곰곰이 생각해 봤지... 다른 사냥감처럼 멍청하지 않아. 제대로 싸울 수 있거든.'),
(28216, 3, 4, '안개 날름이들은 가끔 제단인지 무엇인지 옆에 있으면 똑똑해져... 사방이 안개로 뒤덮이면 놈들을 찾기가 쉽지 않아.'),
(28216, 3, 5, '하! 이거 재미있군!'),
(28216, 3, 6, '불! 파괴! 죽음! 내 가슴 속에 검은 불길이 끓고 있다! ...내뿜어야만 해! 우하하!'),
(28216, 4, 0, '나를 믿어봐. 마음에 들 거다!'),
(28216, 5, 0, '꽝! 아주 좋아! 좀 더! 좀 더!'),
(28217, 0, 0, '상처입은 구름몰이골록 점쟁이가 힘겹게 두 발로 일어섭니다.'),
(28217, 1, 0, '집에 갈 때가 되면 얘기해 줘.'),
(28217, 2, 0, '집이 멀지 않다. 가자!'),
(28217, 3, 0, '고맙다!'),
(28217, 4, 0, '안 돼! 하룻강아지들이 쫓아온다!'),
(28244, 0, 0, '자, 이제 이 광석이 스컬지에게 왜 그렇게 중요한지 알아보세나.'),
(28244, 1, 0, '코팩스, 이 사로나이트라는 광석에 대해 아는 게 있나?'),
(28244, 2, 0, '레인, 림블랫, 자연과 정령의 힘을 써 보는 건 어때?'),
(28244, 3, 0, '메츠?'),
(28244, 4, 0, '왜 불렀는지 알잖나.'),
(28244, 5, 0, '%s|1이;가; 몸에 묻은 먼지를 털어냅니다.'),
(28244, 6, 0, '계속해 봤자 소용없겠어. 이 사로나이트를 폴드링 대영주님께 보내 더 자세히 연구하도록 해야겠네.'),
(28244, 7, 0, '힘써줘서 고맙네, 친구여. 우리는 비밀을 밝혀내고 말 거야. 바라건대, 너무 늦기 전에 말이지.'),
(28256, 0, 0, '그래, 점쟁이가 너를 돕기로 했다는 말이구나, 이방인. 좋다, 내가 아는 걸 말해 주마.'),
(28256, 1, 0, '네 동료는 우두머리 수정뿔 코뿔소인 파룬을 찾고 있다. 녀석은 자기 형제들에게서 멀리 떨어져 있지.'),
(28256, 2, 0, '파룬은 너희가 거센물결 호수라 부르는 곳의 북쪽에 있다. 녀석은 언제나 혼자 다니지만, 일단 마주쳐 보면 녀석에겐 보호자 따윈 필요 없다는 걸 알게 될 것이다.'),
(28256, 3, 0, '너희 동료에게 돌아가라. 계속 나아가서 파룬을 처치하고 전리품을 취하라고 일러라.'),
(28256, 4, 0, '일을 마치거든 조용히 이 땅을 떠나라고 전해라. 그는 이 땅에 속한 자가 아니다.'),
(28284, 3, 0, '유레카!'),
(28315, 0, 0, '다시 돌아온다면 광란심장 일족 손에 죽을 것이다. 우리는 이제 너 환영하지 않는다!'),
(28325, 0, 0, '주변 어딘가에서 낮게 으르렁거리는 소리가 들립니다.'),
(28327, 0, 0, '주술사 베크지크가 근처의 덤불 사이로 모습을 드러냅니다.'),
(28327, 1, 0, '구름몰이골록을 돕다니! 네놈이 구름몰이골록 돕는 걸 봤어! 배신이야!'),
(28327, 2, 0, '날름이들 친구 되겠다면 더는 광란심장 일족 친구 아니야! 마을에 말하겠어! 이제 너 믿지 않아!'),
(28327, 3, 0, '주술사 베크지크가 광란심장 언덕을 향해 달려갑니다.'),
(28328, 0, 0, '자존심 말고는 멀쩡하잖아, 친구. 입 좀 다물어!'),
(28328, 0, 1, '징징거리지 말라고. 그래도 아직은 운이 좋군.'),
(28328, 0, 2, '흠, 좀 나아졌군.'),
(28328, 0, 3, '조용히 해, 친구. 그냥 새총일 뿐이라니까!'),
(28347, 0, 0, '라이트, 자네가 만든다던 새 혼합물은 다 만들었나? 가게에 포자가 잔뜩 널려 있는 꼴은 그만 보고 싶단 말일세!'),
(28347, 1, 0, '그럼 다음에는 두 배로 넣어!'),
(28347, 2, 0, '내 말 잘 듣게, 젊은이. 자넨 항상 자네 생각보다 더 형편없어. 제대로 하게!'),
(28347, 3, 0, '다음에는 반만 집어넣게.'),
(28347, 4, 0, '입만 열면 그 소리군. 죽을 때까지 못 끝내는 건 아닌지 모르겠구먼.'),
(28347, 5, 0, '안녕하신가요.'),
(28347, 5, 1, '안녕하시오, $c.'),
(28347, 5, 2, '반갑습니다! 천천히 둘러보십시오.'),
(28347, 5, 3, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(28347, 5, 4, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(28355, 0, 0, '점장님. 우리 맹독에 여신의 고뇌가 부족하다고 손님들이 항의하시는데요.'),
(28355, 1, 0, '점장님, 지난번에 독을 제조할 때 무기력의 뿌리를 빠트린 것 같습니다.'),
(28355, 2, 0, '아직 만들고 있습니다. 만족스러운 품질이 나올 때까지는 손님들에게 내놓지 않으려는 것뿐이에요. 금방 끝날 겁니다.'),
(28355, 3, 0, '점장님, 우리 정신 마취 독에 죽음의 풀이 부족하다고 손님들이 항의하시는데요.'),
(28406, 0, 0, '물약 금지!'),
(28406, 0, 1, '오늘을 기억하라, $n. 아주 망신스러운 날이 될 테니.'),
(28406, 0, 2, '확실히 발라 주마, 애송이!'),
(28406, 0, 3, '확실히 발라 주마, 애송이!'),
(28406, 0, 4, '눈물을 쏙 빠지게 해 주마...'),
(28406, 0, 5, '감히 죽음에 직접 도전하다니!'),
(28406, 0, 6, '리치 왕께서 오늘의 진정한 우승자를 친히 만나실 것이다!'),
(28406, 0, 7, '널 쓰러뜨리고 말겠어!'),
(28406, 0, 8, '너는 가망이 없다, $n.'),
(28415, 0, 0, '아우...'),
(28415, 0, 1, '당신에게 빚을 졌군요.'),
(28415, 0, 2, '죽는 줄만 알았습니다!'),
(28444, 0, 0, '%s|1이;가; 막강한 스컬지 군대를 소집합니다!'),
(28444, 1, 0, '스컬지 군대여, 내 말을 들어라! 붉은십자군 대참사가 시작됐다! 이 땅을 갈가리 찢어발기고, 너희가 지나간 자리에 죽음만을 남겨라!'),
(28473, 0, 0, '육신을 벗어나 유령 상태가 되었습니다!'),
(28479, 0, 0, '고대의 신이시여, 간청합니다. 저희는 어떻게 해야 합니까? 이 땅의 신들을 구하려면 어떻게 해야 하겠습니까?'),
(28486, 0, 0, '주, 주인님... 주인님 마, 말을 솔질할까요...?'),
(28486, 0, 1, '주, 주인님... 가, 갑옷을 닦아드릴까요...?'),
(28486, 0, 2, '주, 주인님... 시, 시체 가루를 더 가, 가져다 드릴까요...?'),
(28486, 1, 0, '예, 주, 주인님...'),
(28494, 0, 0, '잔달라 부족과 그 허수아비들에게 죽음을! 이제 그 무엇도 우리를 막을 수 없다!'),
(28495, 0, 0, '죽여라! 놈들을 모두 죽이고 짐토르가를 되찾아라!'),
(28496, 0, 0, '하하! 순순히 내 보물을 가져가게 둘 것 같나!'),
(28498, 0, 0, '잘해 줬다, 드라쿠루.'),
(28498, 1, 0, '네가 드라카리 제국을 배신해 준 덕분에 내게는 새로운 군대가 생겼지.'),
(28498, 2, 0, '너의 군대가...'),
(28498, 3, 0, '일어나라. 내 너에게 상을 주겠다.'),
(28498, 4, 0, '이제 너에게 줄드락을 깨끗이 쓸어내는 임무를 맡기겠다.'),
(28498, 5, 0, '날 실망시키면 너는 파멸하리라...'),
(28498, 6, 0, '성공하면 더욱더 강력한 힘을 맛보게 될 것이다!'),
(28498, 7, 0, '너는 나를 실망시켰다, 드라쿠루!'),
(28498, 8, 0, '고통받을 자는 바로 너다. 순식간에 죽여 주는 걸 감사해라...'),
(28498, 9, 0, '네 녀석은...'),
(28498, 10, 0, '이 깜찍한 배신을 칭찬하는 의미로 이번엔 네 하찮은 목숨을 보전해 주마. 어쩌면 너에겐 가능성이 조금 있을지도 모르니.'),
(28498, 11, 0, '명심해라...'),
(28498, 12, 0, '다음에 만날 때도 살고 싶다면, 더 그럴듯한 이유를 준비해야 할 게다.'),
(28511, 0, 0, '아케루스의 눈이 목표를 향해 발사됩니다.'),
(28511, 1, 0, '아케루스의 눈을 사용할 수 있습니다.'),
(28514, 0, 0, '하지만 시도조차 하지 않으면 모든 것을 잃을 게다. 드라카리는 그들의 신과 자신을 모두 죽이게 될 것이다!'),
(28515, 0, 0, '점박이 무늬를 찾아야 한다. 그들의 운명은 서로 엉켜 있다.'),
(28516, 0, 0, '하지만 그녀는 구속되어 있다. 그녀를 해방해 줄 방법을 찾아야 한다.'),
(28517, 0, 0, '이 필멸의 존재가 그녀의 제단까지 가야 한다. 쉽지 않겠지. 어쩌면 불가능한 일일 수도 있다.'),
(28518, 0, 0, '늙은 나스가 어떻게 길을 찾아 돌아올지 모르겠군. 아마도 냄새를 맡고 찾아오겠지...'),
(28521, 0, 0, '그가 줄드락으로 가자더군요. 이 난장판의 최고봉이라나요...'),
(28521, 0, 1, '스컬지 머리털을 한 뭉치 모을 때마다 내 존엄성도 조금씩 사라져 가는군요...'),
(28521, 0, 2, '다 모으려면 아직 멀었나요?'),
(28541, 0, 0, '나 주는 거야? 정말?'),
(28541, 1, 0, '너... 너무 예쁘다!'),
(28546, 0, 0, '주인님과 마주하고 싶은 게냐? 그럼 먼저 폭풍을 이겨내라!'),
(28546, 1, 0, '파멸은 아주 자그만 불꽃에서 시작되지.'),
(28546, 1, 1, '안전한 곳은 없다!'),
(28546, 2, 0, '그래, 충격이겠지.'),
(28546, 2, 1, '불가능에 도전하는구나.'),
(28546, 2, 2, '생명의 불꽃이... 사그라들었다.'),
(28546, 3, 0, '주인님... 손님이 왔습니다.'),
(28557, 0, 0, '아아... 이젠... 이젠 지쳤어...'),
(28557, 0, 1, '전... 고향에 병든 할머니가 계십니다... 할머니 피붙이라곤 저밖에 없습니다.'),
(28557, 0, 2, '이런, 술 끊기엔 안 좋은 주를 골랐군!'),
(28557, 0, 3, '전 아이들이 다섯이나 있습니다! 제가 없으면 아이들은 다 죽습니다!'),
(28557, 0, 4, '이러지 마십시오! 사람을 해쳐선 안 됩니다!'),
(28563, 0, 0, '위에 있는 구조물이 에너지와 공명하기 시작합니다.'),
(28566, 0, 0, '5초 내로 증류가 시작될 걸세.'),
(28566, 1, 0, '오렌지를 더 넣게! 빨리!'),
(28566, 2, 0, '증류기에 파파야를 넣게나!'),
(28566, 3, 0, '바나나가 부족하네!'),
(28566, 4, 0, '압력이 너무 올라갔군! 압력 밸브를 열게!'),
(28566, 5, 0, '증류기에 열이 부족하네! 화로를 켜게!'),
(28566, 6, 0, '좋아! 눈 똑바로 뜨고 있게.'),
(28566, 6, 1, '됐네. 다음엔 뭐가 필요해질지 모르겠군...'),
(28566, 6, 2, '좋아! 정신 바짝 차리게나!'),
(28566, 6, 3, '잘했네! 다시 준비하게!'),
(28566, 7, 0, '안 좋은데! 증류기를 내려야겠어...'),
(28566, 8, 0, '증류가 끝났네! 통을 가져다주게.'),
(28568, 1, 0, '이런 맙소사...'),
(28575, 0, 0, '더러운 $r 침입자야. 죽어라!'),
(28575, 0, 1, '루노크가 힘을 되찾으면 우린 모두 죽는다!'),
(28575, 0, 2, '주위에 침입자가 있군. 놈들이 일을 망치기 전에 없애라!'),
(28575, 0, 3, '곰 신이 쇠약한 상태여야 예언자가 의식을 마칠 수 있다.'),
(28575, 0, 4, '녀석의 힘을 계속 빼 놔라!'),
(28579, 0, 0, '%s|1이;가; 격노합니다!'),
(28586, 0, 0, '%s|1이;가; 전투 태세로 전환합니다!'),
(28586, 1, 0, '%s|1이;가; 광폭 태세로 전환합니다!'),
(28586, 2, 0, '%s|1이;가; 방어 태세로 전환합니다!'),
(28586, 3, 0, '우리 아버지 자식 중에 내가 제일 세! 넌 이제 큰일 났다!'),
(28586, 4, 0, '있는 힘껏 쳐 봐라!'),
(28586, 5, 0, '막아 봐라! 그럴 수 있다면 말이다!'),
(28586, 6, 0, '으아아아! 무쇠와 강철의 분노를 맛보아라!'),
(28586, 7, 0, '이걸로 저주가 풀렸구나.'),
(28586, 7, 1, '살덩이 따위는 약해!'),
(28586, 7, 2, '볼빈 움욜 말냐르.'),
(28586, 8, 0, '뭔가 잘못됐어... 살덩이 따위가... 강할 리가...'),
(28587, 0, 0, '너희가... 내 자식들을 건드렸냐? 가만두지 않겠다!'),
(28587, 1, 0, '무에서 생명을... 너희에겐 죽음을!'),
(28587, 1, 1, '내 작업에 군더더기란 없다. 보면 알게 되겠지...'),
(28587, 2, 0, '내가 한번 제대로 밟아주마!'),
(28587, 2, 1, '작품이... 덜 됐어!'),
(28587, 3, 0, '무쇠로 만든 군대가 세상을 정복할 것이다!'),
(28587, 3, 1, '흥! 형편없구나!'),
(28587, 3, 2, '네놈 때문에... 일이 밀려 버렸다!'),
(28587, 4, 0, '주인님이... 걱정했던 대로군...'),
(28587, 5, 0, '%s|1이;가; 모루로 달려갑니다!'),
(28587, 6, 0, '%s|1이;가; 빛바랜 골렘을 무너뜨리려고 합니다!'),
(28601, 0, 0, '멍청한 녀석! 넌 우리에게 위협이 되는 유일한 존재에게 우릴 안내해 줬을 뿐이다! 에티미디안을 노스렌드에 데려갈 수는 없어!'),
(28604, 0, 0, '아야! 어딜 당기십니까!'),
(28604, 1, 0, '도와드릴 수 있어 다행입니다!'),
(28608, 0, 0, '십자군은 승리한다!'),
(28608, 0, 1, '정화를 시작한다!'),
(28608, 0, 2, '여긴 네가 있을 곳이 아니다, 이 괴물!'),
(28609, 0, 0, '십자군은 승리한다!'),
(28609, 0, 1, '정화를 시작한다!'),
(28609, 0, 2, '여긴 네가 있을 곳이 아니다, 이 괴물!'),
(28610, 1, 0, '곧 교수대에 매달릴 거다, 스컬지 괴물 녀석!'),
(28610, 1, 1, '날 죽여야 할 거다, 이 괴물아. 난 아무것도 말하지 않을 테니까!'),
(28610, 1, 2, '매질이 꼭 계집애처럼 약하구나. 겨우 그 정도로 되겠느냐?'),
(28610, 1, 3, '아악! 마지막 남은 내 질 좋은 휘장을 태우다니!'),
(28610, 1, 4, '아윽... 이 고통... 내가 어린애였을 때 학교에서 받은 매질이 이렇게 아팠지...'),
(28610, 1, 5, '난 종교재판장 이실리엔 님을 위해 일해왔다! 매일 오후면 고통을 즐겼지!'),
(28610, 2, 0, '뭐든 말하겠다! 그만해라! 제발!'),
(28610, 3, 0, '우리... 우린 "진홍빛 서광"은 깨어남이라고만 들었다. 너... 너도 알겠지만 빛은 고위사령관님께 말한다. 빛이...'),
(28610, 4, 0, '빛이 우리를 인도한다. 이번 일은 너희가 오기 전부터 추진되었다. 우... 우린 우리가 들은 대로 한다. 반드시 해야 하는 일이다.'),
(28610, 5, 0, '그밖에는 아는 게 없다... 고위사령관님은 갈 자와 남을 자를 결정하신다. 더는 아는 게 없다... 제발 믿어다오!'),
(28610, 6, 0, '헛소리! 네가 앞으로 느낄 고통은 몇 년 동안 얘깃거리가 될 게다!'),
(28610, 7, 0, '그만! 제발! 하나 잊고 말하지 않은 게 있다... 하스글렌에서... 곧 급사가 온다...'),
(28610, 8, 0, '언젠가는 이야기하게 될 것이다! "진홍빛 서광"이 무엇인지 말해라. 그러면 목숨은 살려주겠다!'),
(28610, 8, 1, '"진홍빛 서광"의 정체가 뭔지 말하지 않으면 매질이 계속될 것이다!'),
(28610, 8, 2, '인간이여, 난 지금까지 예의 바르게 대했다! "진홍빛 서광"이 뭐냐?'),
(28610, 8, 3, '네 생명이 소중하지 않단 말이냐? "진홍빛 서광"에 대해서 말해라. 그러면 네 고통을 끝내주마.'),
(28610, 8, 4, '붉은십자군의 개야, 내가 지치기라도 할 것 같으냐?! "진홍빛 서광"이 뭔지 말해라!'),
(28610, 8, 5, '"진홍빛 서광"이 뭐지?'),
(28610, 8, 6, '"진홍빛 서광"이 도대체 뭐냐! 말해라!'),
(28611, 0, 0, '십자군은 승리한다!'),
(28611, 0, 1, '정화를 시작한다!'),
(28611, 0, 2, '여긴 네가 있을 곳이 아니다, 이 괴물!'),
(28636, 0, 0, '내 북을 두드리는 놈이 누구냐?'),
(28636, 1, 0, '내려가서 네놈을 끝장내 주마, $r!'),
(28636, 2, 0, '이제 넌 죽는다!'),
(28646, 0, 0, '이미 비행은 시작되었소! 거기 덩굴 조심하시오!'),
(28646, 1, 0, '이 전방 지역은 스컬지가 아주 심하게 공격한 것 같소...'),
(28646, 2, 0, '저거 봤소? 정말... 어마어마하게 크군!'),
(28646, 3, 0, '자, 갑시다! 꽉 잡으시오. 전방에 풍향이 고르지 않소!'),
(28646, 4, 0, '이 빙하는 얼음왕관에서부터 흘러나오고 있군... 게다가 언데드까지 사방에 있다니! 여기는 학자께서 보실 때까지 그냥 두는 게 좋겠소!'),
(28646, 5, 0, '우리에게 오고 있소! 그 로켓을 빨리 쏘시오!'),
(28646, 6, 0, '아아아아아악! 당했소! 이제 당신이 비행기를 조종해서 돌아가야 하오! 서두르시오. 비행기가 곧 폭발할지도 모르오!'),
(28654, 0, 0, '어둠의 영역이 기다리는구나...'),
(28659, 0, 0, '아, 네가 그 영웅이로군. 네 꼬마 친구가 너희가 올 거라고 하더구나. 몸소 잡으러 나서는 수고를 덜어주었구나.'),
(28659, 1, 0, '전쟁과 고통을 백 년이나 견디어 왔다. 진정 필멸의 존재가 불멸의 존재에 맞서는 일이 현명하다고 생각하는가? 감히 말하건대 네 쪽이 잃을 것이 더 많으리라.'),
(28659, 2, 0, '산산조각이 났어도, 사방에 있는 수정은 나를 약하게 한다... 티탄들을 그렇게 얕잡아보지 말았어야 했다...'),
(28659, 3, 0, '용감하지만, 무지하기 짝이 없는 이 바보 둘은 서로 경멸하면서도, 너는 영웅이라고 말했다. 너희에게는 어느 한편에 설 의지가 없는 듯한데... 선택할 기회를 더 주어 보겠다.'),
(28659, 4, 0, '알트루이스가 보호막에 둘러싸였습니다. 보호막을 없애려면 어느 편을 도울지 빨리 선택해야 합니다.'),
(28659, 5, 0, '아서스 님께서 힘... 같은 힘을 다시 찾으시면... 너는 그분과 같은 길을 따라가게 될 것이다.'),
(28665, 0, 0, '구해 주셔서 감사합니다, $n 님. 보답으로 해드릴 수 있는 게 이 정도뿐이군요. 꼭 잡으세요. 출발합니다.'),
(28665, 1, 0, '상황이 좋아 보이진 않는군요. 뭘 하시든 간에 떨어지지는 마세요. 저기엔 역겨운 것들이 가득합니다!'),
(28665, 2, 0, '이럴 수가... 쿠에츠룬 님께서 돌아가셨군요! 숨을 죽이세요. 예언자를 몰래 지나쳐 갈 겁니다.'),
(28665, 3, 0, '들켰습니다! 꽉 잡으세요. 여길 벗어나야 합니다!'),
(28665, 4, 0, '이제 안전한 것 같습니다. 돌아갑시다!'),
(28665, 5, 0, '우리가 해냈어요! 몸조심하세요, $n 님. 그리고 다시 한 번 감사합니다!'),
(28667, 0, 0, '넌 이제 우리 못 잡아! 이젠 우리가 너 혼내 준다. 나쁜 언데드야! 나빠!'),
(28668, 0, 0, '크고 나쁜 언데드 녀석아! 넌 이제 죽었다! 잠자는 제피크를 건드렸겠다!'),
(28671, 0, 0, '이 애처롭고 작은 벌레는 뭐지? 죽으러 왔나?'),
(28671, 1, 0, '이 불쾌한 냄새는 맡아본 적이 있는데... 새끼 눈표범 등에 타고는 숨어서 내 뒤를 지나간 게 바로 네 녀석이구나!'),
(28671, 2, 0, '아니? 어떻게 이런 일이?'),
(28671, 3, 0, '잠깐... 멈춰! 힘을 되찾아서는 안 돼!!!'),
(28671, 4, 0, '안 돼애애애애애애애애!'),
(28684, 0, 0, '이 왕국은 스컬지의 것... 오직 죽은 자만 들어올 수 있다!'),
(28684, 1, 0, '감히 여기엘 오다니...'),
(28684, 1, 1, '아눕아락 님의 뜻이다!'),
(28684, 2, 0, '고마워할 자격 따위... 잃은 지... 오래다...'),
(28684, 3, 0, '그들은 굶주렸지...'),
(28684, 3, 1, '얘들아, 밥 시간이다!'),
(28684, 4, 0, '통로를 주시해라. 아무도 들여보내선 안 돼!'),
(28684, 5, 0, '발소리가 들리는데... 경계 태세를 취해라.'),
(28684, 6, 0, '산 자가 왔나 보군. 준비해라.'),
(28684, 7, 0, '침입자가 몰려온다! 가라! 놈들을 해치우고 시체를 가져와!'),
(28684, 8, 0, '문을 보호해야 한다. 공격! 모두 박살을 내버려라!'),
(28684, 9, 0, '어떤 수를 써서라도 문을 지켜야 한다! 가서 놈들을 쓸어버려!'),
(28710, 0, 0, '엔진이 폭발했습니다! 빅의 비행기를 호반의 착륙장으로 되돌려야 합니다!'),
(28714, 0, 0, '어서 오십시오.'),
(28714, 0, 1, '안녕하신가요.'),
(28714, 0, 2, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(28715, 0, 0, '반갑습니다! 천천히 둘러보십시오.'),
(28715, 0, 1, '안녕하시오, $c.'),
(28715, 0, 2, '어서 오십시오!'),
(28717, 0, 0, '이 땅 일부는 이미 나의 것일세, 친구. 하지만 그건 시작에 불과해!'),
(28717, 1, 0, '여기, 독선적인 십자군 녀석들이 우리를 방해하고 있네. 녀석들은 파멸할 것이야!'),
(28717, 2, 0, '곧 이 모두가 리치 왕께 속할 걸세!'),
(28717, 3, 0, '드라카리는 자기 땅을 파괴하고 있어! 녀석들은 자멸할 걸세... 곧 말이야, 친구.'),
(28717, 4, 0, '아아, 저기 우리 운명이 있네... 군드락 말이야!'),
(28717, 5, 0, '여길 잘 파악해 둬. 내가 여기를 정복할 때 날 도와줘야 할 테니까!'),
(28717, 6, 0, '아, 그렇지! 이곳에 있었던 위대한 영광이 재현될 거야!'),
(28717, 7, 0, '리치 왕은 자기 힘을 섬기는 사람들에게 나눠준다네.'),
(28717, 8, 0, '나한테 와봐, $n. 너한테 할 말이 있어.'),
(28718, 0, 0, '어서 오십시오!'),
(28718, 0, 1, '안녕하신가요.'),
(28718, 0, 2, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(28718, 0, 3, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(28718, 0, 4, '반갑습니다! 천천히 둘러보십시오.'),
(28718, 0, 5, '안녕하시오, $c.'),
(28718, 0, 6, '어서 오십시오.'),
(28721, 0, 0, '반갑습니다! 천천히 둘러보십시오.'),
(28721, 0, 1, '안녕하시오, $c.'),
(28721, 0, 2, '안녕하신가요.'),
(28721, 0, 3, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(28721, 0, 4, '어서 오십시오.'),
(28721, 0, 5, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(28723, 0, 0, '안녕하시오, $c.'),
(28723, 0, 1, '안녕하신가요.'),
(28723, 0, 2, '어서 오십시오.'),
(28725, 0, 0, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(28725, 0, 1, '어서 오십시오.'),
(28725, 0, 2, '반갑습니다! 천천히 둘러보십시오.'),
(28725, 0, 3, '어서 오십시오!'),
(28726, 0, 0, '반갑습니다! 천천히 둘러보십시오.'),
(28726, 0, 1, '어서 오십시오!'),
(28726, 0, 2, '안녕하시오, $c.'),
(28726, 0, 3, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(28726, 0, 4, '안녕하신가요.'),
(28726, 0, 5, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(28727, 0, 0, '어서 오십시오!'),
(28727, 0, 1, '안녕하십니까.'),
(28727, 0, 2, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(28727, 0, 3, '반갑습니다! 천천히 둘러보십시오.'),
(28750, 0, 1, '므프흐므므 르므프흐히므므 르르후므그흐프흐?'),
(28750, 0, 2, '므흐르루므프흐 루므므르후므 프후르르!'),
(28752, 0, 0, '안 돼애애애애애애애애.......!'),
(28756, 0, 0, '%s|1이;가; 격노합니다!'),
(28756, 1, 0, '추워!'),
(28756, 2, 0, '%s|1이;가; 폭발합니다!'),
(28780, 0, 0, '5초 후에 폭발합니다...'),
(28780, 1, 0, '4초 후에 폭발합니다...'),
(28780, 2, 0, '3초 후에 폭발합니다...'),
(28780, 3, 0, '2초 후에 폭발합니다...'),
(28780, 4, 0, '1초 후에 폭발합니다...'),
(28793, 0, 1, '그 분장으로 나를 속일 수는 없다, 살덩어리야! 널 쓰러뜨리면 드라쿠루 님께서 기뻐하시겠지!'),
(28841, 0, 0, '이건 왜 여기 있는 거야? 감독한테 혼나기 전에 어서 배로 가져가야겠군!'),
(28841, 1, 0, '이제 좀 쉴 수 있겠군!'),
(28859, 0, 0, '여기가 어디라고, 하등한 것들이! 한심하구나... 용기가 넘친들 우둔함을 극복할 수 있을 것 같으냐?'),
(28859, 0, 1, '푸른용군단의 일원만이 여기서 환영받는다. 이건 알렉스트라자가 꾸민 짓이겠지? 그렇다면, 그녀는 너희를 사지로 밀어 넣은 셈이다!'),
(28859, 0, 2, '무엇을 이룰 수 있겠느냐? 뻔뻔하게도 내 영토에 난입해서, 마법을 쓰겠다고? 나를 상대로?'),
(28859, 0, 3, '이곳에서 내 힘은 무한하다. 현실 법칙 따위 여기선 통하지 않아! 이 영역은, 내가 지배한다!'),
(28859, 0, 4, '마지막 기회를 주마. 충성을 맹세해라. 그러면 목숨은 살려줄지도 모르니.'),
(28859, 1, 0, '더는 참을 수가 없구나. 다 없애 버리겠다!'),
(28859, 2, 0, '내가 숨 쉬는 한, 너희는 이길 수 없다!'),
(28859, 3, 0, '우둔함이 결국은 죽음을 낳는구나!'),
(28859, 3, 1, '거두어들일 마력이 늘어났군.'),
(28859, 3, 2, '미숙한 것들 같으니...'),
(28859, 4, 0, '되도록 빨리 끝내 주고 싶었다만, 너희는 생각보다... 완강하구나. 어쨌거나 의미 없는 짓거리다. 이 전쟁의 책임은 무모하고 부주의한 필멸의 존재들에게 있다. 나는 할 일을 할 뿐이다. 너희를 멸종시켜야만 한다면, 그리할 수밖에!'),
(28859, 5, 0, '지금부터 너희가 겪을 고통을 맛본 자는 거의 없었지...'),
(28859, 6, 0, '마법에 대한 너희 지식이 얼마나 보잘것없는지 똑똑히 보여주마!'),
(28859, 7, 0, '마지막 남은 희망마저 휩쓸려 가는 걸 지켜보아라!'),
(28859, 8, 0, '네 마력은 좋은 일에 쓰일 게다.'),
(28859, 8, 1, '나는 마법의 지배자다! 내 힘은 무한하다!'),
(28859, 8, 2, '네 영혼은 영원히 이곳을 헤매리라!'),
(28859, 9, 0, '그만! 아제로스의 마력을 되찾고 싶으냐? 어디 가져가 봐라...'),
(28859, 10, 0, '네놈들의 후원자가 나타났구나. 하지만 너무 늦었어! 이곳에 흘러넘치는 마력은 세계를 수십 번은 파괴하고도 남는다. 녀석들이 무슨 도움이 될 것 같으냐?'),
(28859, 11, 0, '항복해라!'),
(28859, 12, 0, '%s|1이;가; 숨을 깊게 들이쉽니다.'),
(28859, 13, 0, '이곳에 흐르는 마력은 네놈들이 상상할 수 있는 수준이 아니다!'),
(28859, 14, 0, '날 멈출 순 없다!'),
(28859, 15, 0, '알렉스트라자, 네 아이가 또 하나 쓰러졌다!'),
(28859, 15, 1, '모기보단 좀 세군!'),
(28859, 15, 2, '시뻘건 네놈의 동료와 운명을 같이해라!'),
(28859, 16, 0, '아직도 버텨? 오래가진 못할 게다.'),
(28859, 16, 1, '헛수고만 하고 있구나!'),
(28859, 16, 2, '나약한 정신을 산산조각 내주지!'),
(28859, 17, 0, '이런 일이! 필멸의 존재들은... 모든 걸 파괴할 텐데! 누이여, 무슨 짓을...'),
(28859, 18, 0, '%s|1이;가; 당신을 주시합니다!'),
(28859, 19, 0, '%s|1이;가; 분노에 휩싸여 광폭해집니다!'),
(28860, 0, 0, '내 임무는 알을 보호하는 것. 알에 손대지 못하게 모두 불태워 주마.'),
(28860, 1, 0, '시시한 장난도 여기서 끝이다!'),
(28860, 2, 0, '불타라, 비천한 것들!'),
(28860, 3, 0, '샤드론! 이리 와라! 위험한 상황이다!'),
(28860, 4, 0, '테네브론! 너도 알을 지킬 책임이 있어!'),
(28860, 5, 0, '베스페론! 알이 위험하다! 날 도와라!'),
(28860, 6, 0, '패배의 대가가... 이것인가...'),
(28860, 7, 0, '아... 불에 아주 잘 타겠군!'),
(28860, 7, 1, '새카맣게 타버릴 줄 알아라!'),
(28860, 7, 2, '뜨거운 맛 좀 보여줄까...'),
(28860, 7, 3, '모두 재로 만들어주마!'),
(28860, 8, 0, '우리 아이들에게 좋은 먹잇감이 되겠어.'),
(28860, 8, 1, '어차피 너흰 상대가 안 돼.'),
(28860, 8, 2, '이래서 너희가 하등하다는 거다!'),
(28860, 9, 0, '%s|1을;를; 둘러싼 용암이 끓어오릅니다!'),
(28902, 0, 0, '%s|1이;가; 격노합니다!'),
(28902, 1, 0, '마력 깃든 티키를 가지고 있다니?! 네놈이 내 가족을 죽였구나!'),
(28902, 2, 0, '네놈의 목숨을 끊어 놓으리라, $n!'),
(28907, 0, 0, '정복당한 자들의 고통이 하늘을 찌를 것이다!'),
(28907, 1, 0, '허약한 붉은십자군 따위가 우릴 막을 수는 없다!'),
(28907, 2, 0, '저항하는 자는 시체가 되어 우리의 일원이 될 뿐이다!'),
(28907, 3, 0, '붉은십자군 함대가 갈라진 해안에 있는 폐허에 자리를 잡았다!'),
(28907, 4, 0, '적 하나를 죽일 때마다 우리 힘이 커진다! 놈들을 가엾게 여기지 마라!'),
(28907, 5, 0, '리치 왕께서 너희 모두에게 말씀하셨다! 그분의 말씀이 너희 사이에서 다시 한번 울려 퍼지게 하라!'),
(28907, 6, 0, '모두 죽여라'),
(28907, 7, 0, '너희가 지나간 자리에 누구도 살아남지 못하게 하라, 형제자매들이여!'),
(28907, 8, 0, '약한 자에게 자비를 베풀지 마라!'),
(28907, 9, 0, '공포!'),
(28907, 10, 0, '혼돈을!'),
(28907, 11, 0, '파괴를!'),
(28907, 12, 0, '어둠이 다가오면 붉은십자군에 종지부를 찍으리라. 너희는 다시 한번 싸울 것이다! 스컬지를 위하여! 리치 왕을 위하여!'),
(28907, 13, 0, '고통을 즐겨라, 죽음의 기사여!'),
(28912, 0, 0, '내 룬검과 방어구를 찾아야 합니다... 잠깐만 기다리십시오.'),
(28912, 1, 0, '난 아직 약하지만, 아마도 대마법 보호막 정도는 만들 수 있을 것 같습니다. 보호막을 벗어나면 저들의 주문에 크게 당할 테니 조심하십시오.'),
(28912, 2, 0, '이 보호막을 유지하는 것만 해도 엄청난 집중력이 필요합니다. 저들을 해치우십시오!'),
(28912, 3, 0, '더 세게 공격해올 겁니다. 자신을 지키십시오! 대마법 보호막을 벗어나지 마십시오! 보호막의 도움을 받지 못하면 저들이 그대를 조각낼 겁니다!'),
(28912, 4, 0, '더는 보호막을 유지할 수 없을 것 같습니다... 그 겁쟁이는 어디 갔습니까?'),
(28912, 5, 0, '종교재판관이군! 준비하십시오, 죽음의 기사여! 녀석이 그대를 대마법 보호막 밖으로 끌어내게 두지 마십시오! 그를 처치하세요!'),
(28912, 6, 0, '대마법 보호막 안에 머무르십시오! 저들이 그대에게 다가오게 하십시오!'),
(28912, 7, 0, '신 아발론 종교재판관의 죽음은 얼마 안 있어 알려질 겁니다. 당장 여길 떠나십시오! 놈들이 더 몰려오기 전에 어서 가십시오. 난 혼자서 빠져나갈 수 있습니다.'),
(28912, 8, 0, '내가 저들의 눈길을 끌겠습니다. 내가 나간 후에 빠져나가십시오.'),
(28912, 9, 0, '너희 종교재판관은 아무것도 아니다. 붉은십자군 녀석들아! 아무도 스컬지의 손아귀를 벗어날 수 없다!'),
(28922, 0, 0, '문이 파괴됐다! 서둘러라! 부대를 편성해, 침입자를 막아라!'),
(28922, 1, 0, '이제 시간이 없다! 남은 병력은 모두 침입자를 공격하라!'),
(28923, 0, 0, '희망이 있는 줄 아느냐? 꿈 깨라!'),
(28923, 1, 0, '나는 수많은 제국의 흥망을 지켜보았다... 모든 종의 발생과 멸종을 목격했다... 아무리 강산이 바뀌어도, 필멸의 존재들은 항상 멍청했지. 너희가 여기 나타난 게 그 증거다.'),
(28923, 2, 0, '주인님께서 미래를 보여주셨다. 하지만 너희는 거기 없어! 아제로스는 어둠 속에서 다시 태어날 것이다. 요그사론이 풀려날 것이다! 판테온은 무너지리라!'),
(28923, 3, 0, '운명을 거부할 순 없다!'),
(28923, 3, 1, '가까이 와라. 빨리 끝내주지.'),
(28923, 3, 2, '연약한 몸뚱이로 얼마나 버틸까?'),
(28923, 4, 0, '미약한 존재여...'),
(28923, 4, 1, '나는... 불멸이다!'),
(28923, 4, 2, '살 날이 얼마나 남았다고 낭비하느냐!'),
(28923, 5, 0, '나의 죽음은... 세상의 종말을 예고할 뿐이다.'),
(28923, 6, 0, '나락을 향해 달리는 눈먼 자들이여!'),
(28923, 7, 0, '무지함이 하늘을 찌르는구나. 이 길이 어디로 향하는지 모르겠느냐?'),
(28923, 8, 0, '결국은 파멸을 향해 치닫는구나!'),
(28923, 9, 0, '%s|1이;가; 번개 회오리를 시전합니다!'),
(28939, 1, 0, '곧 교수대에 매달릴 거다, 스컬지 괴물 녀석!'),
(28939, 1, 1, '날 죽여야 할 거다, 이 괴물아. 난 아무것도 말하지 않을 테니까!'),
(28939, 1, 2, '매질이 꼭 계집애처럼 약하구나. 겨우 그 정도로 되겠느냐?'),
(28939, 1, 3, '아악! 마지막 남은 내 질 좋은 휘장을 태우다니!'),
(28939, 1, 4, '아윽... 이 고통... 내가 어린애였을 때 학교에서 받은 매질이 이렇게 아팠지...'),
(28939, 1, 5, '난 종교재판장 이실리엔 님을 위해 일해왔다! 매일 오후면 고통을 즐겼지!'),
(28939, 2, 0, '뭐든 말하겠다! 그만해라! 제발!'),
(28939, 3, 0, '우리... 우린 "진홍빛 서광"은 깨어남이라고만 들었다. 너... 너도 알겠지만 빛은 고위사령관님께 말한다. 빛이...'),
(28939, 4, 0, '빛이 우리를 인도한다. 이번 일은 너희가 오기 전부터 추진되었다. 우... 우린 우리가 들은 대로 한다. 반드시 해야 하는 일이다.'),
(28939, 5, 0, '그밖에는 아는 게 없다... 고위사령관님은 갈 자와 남을 자를 결정하신다. 더는 아는 게 없다... 제발 믿어다오!'),
(28939, 6, 0, '헛소리! 네가 앞으로 느낄 고통은 몇 년 동안 얘깃거리가 될 게다!'),
(28939, 7, 0, '그만! 제발! 하나 잊고 말하지 않은 게 있다... 하스글렌에서... 곧 급사가 온다...'),
(28939, 8, 0, '언젠가는 이야기하게 될 것이다! "진홍빛 서광"이 무엇인지 말해라. 그러면 목숨은 살려주겠다!'),
(28939, 8, 1, '"진홍빛 서광"의 정체가 뭔지 말하지 않으면 매질이 계속될 것이다!'),
(28939, 8, 2, '인간이여, 난 지금까지 예의 바르게 대했다! "진홍빛 서광"이 뭐냐?'),
(28939, 8, 3, '네 생명이 소중하지 않단 말이냐? "진홍빛 서광"에 대해서 말해라. 그러면 네 고통을 끝내주마.'),
(28939, 8, 4, '붉은십자군의 개야, 내가 지치기라도 할 것 같으냐?! "진홍빛 서광"이 뭔지 말해라!'),
(28939, 8, 5, '"진홍빛 서광"이 뭐지?'),
(28939, 8, 6, '"진홍빛 서광"이 도대체 뭐냐! 말해라!'),
(28940, 1, 0, '곧 교수대에 매달릴 거다, 스컬지 괴물 녀석!'),
(28940, 1, 1, '날 죽여야 할 거다, 이 괴물아. 난 아무것도 말하지 않을 테니까!'),
(28940, 1, 2, '매질이 꼭 계집애처럼 약하구나. 겨우 그 정도로 되겠느냐?'),
(28940, 1, 3, '아악! 마지막 남은 내 질 좋은 휘장을 태우다니!'),
(28940, 1, 4, '아윽... 이 고통... 내가 어린애였을 때 학교에서 받은 매질이 이렇게 아팠지...'),
(28940, 1, 5, '난 종교재판장 이실리엔 님을 위해 일해왔다! 매일 오후면 고통을 즐겼지!'),
(28940, 2, 0, '뭐든 말하겠다! 그만해라! 제발!'),
(28940, 3, 0, '우리... 우린 "진홍빛 서광"은 깨어남이라고만 들었다. 너... 너도 알겠지만 빛은 고위사령관님께 말한다. 빛이...'),
(28940, 4, 0, '빛이 우리를 인도한다. 이번 일은 너희가 오기 전부터 추진되었다. 우... 우린 우리가 들은 대로 한다. 반드시 해야 하는 일이다.'),
(28940, 5, 0, '그밖에는 아는 게 없다... 고위사령관님은 갈 자와 남을 자를 결정하신다. 더는 아는 게 없다... 제발 믿어다오!'),
