(28940, 8, 1, '"진홍빛 서광"의 정체가 뭔지 말하지 않으면 매질이 계속될 것이다!'),
(28940, 8, 2, '인간이여, 난 지금까지 예의 바르게 대했다! "진홍빛 서광"이 뭐냐?'),
(28940, 8, 3, '네 생명이 소중하지 않단 말이냐? "진홍빛 서광"에 대해서 말해라. 그러면 네 고통을 끝내주마.'),
(28940, 8, 4, '붉은십자군의 개야, 내가 지치기라도 할 것 같으냐?! "진홍빛 서광"이 뭔지 말해라!'),
(28940, 8, 5, '"진홍빛 서광"이 뭐지?'),
(28940, 8, 6, '"진홍빛 서광"이 도대체 뭐냐! 말해라!'),
(28948, 0, 0, '아... 오셨군요. 주인님께서 당신이 곧 오실 거라고 말씀하셨습니다.'),
(28948, 1, 0, '절 따라오시지요, $n 님. 보셔야 할 게 많습니다...'),
(28948, 2, 0, '당신께서 드락타론에 오신 이래, 주인님께서는 언젠가는 당신이 여기 올라와 주인님과 함께할 거라고 종종 말씀하셨죠.'),
(28948, 3, 0, '자랑스러워하셔도 좋습니다. 주인님께서 작전을 공개하시는 건 당신이 처음이니까요.'),
(28948, 4, 0, '지금 제가 보여 드리는 것을 볼타루스 밖에서는 절대로 발설해선 안 됩니다. 머지않아 온 세상이 우리 비밀을 알게 될 겁니다!'),
(28948, 5, 0, '역병 결정이 여기 저장되어 있습니다. 이 결정 덕에 작전을 진행할 수 있었지요.'),
(28948, 6, 0, '당신께서 힘써주신 덕에 수정을 이만큼 비축할 수 있었다는 걸 압니다.'),
(28948, 7, 0, '당신께서 전장에 모습을 드러내게 했던 트롤 족장들도 이 중에 있습니다. 실로 대가의 솜씨를 보여주셨죠...'),
(28948, 8, 0, '바로 이곳, 다가오는 자신의 운명을 볼 수 있는 여기에 이들을 두는 게 가장 좋다고 생각합니다.'),
(28948, 9, 0, '그들의 운명이 어떤 것인지 말씀드리지요...'),
(28948, 10, 0, '역병이 천천히 그들의 몸에 스며들어, 점차 변환에 적합한 상태가 된답니다.'),
(28948, 11, 0, '그들이 상상해 보지도 못했을 크나큰 힘을, 이 특별한 과정을 거쳐 얻게 되지요.'),
(28948, 12, 0, '곧, 주인님께서 그들에게 어둠의 선물을 내려 영원히 리치 왕을 섬기게 할 겁니다!'),
(28948, 13, 0, '얼마든지 여기 머무셔도 됩니다, $n 님. 이 영광은 당신의 수고가 맺은 결실이니까요!'),
(28948, 14, 0, '주인님의 계획을 완성하는 데 당신께서 정말 큰 도움을 주셨지요. 당신의 힘이 계속해서 강대해지기를...'),
(28952, 0, 0, '내가 풀려났다, 조그만 드라카리 녀석들아. 이제 너희가 저지른 수많은 불경에 대한 대가를 치를 때다!'),
(28989, 0, 0, '반갑습니다! 천천히 둘러보십시오.'),
(28989, 0, 1, '안녕하신가요.'),
(28989, 0, 2, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(28989, 0, 3, '안녕하시오, $c.'),
(28989, 0, 4, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(28989, 0, 5, '어서 오십시오.'),
(28994, 0, 0, '안녕하신가요.'),
(28994, 0, 1, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(28994, 0, 2, '어서 오십시오.'),
(28994, 0, 3, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(28996, 0, 0, '그만!'),
(28996, 1, 0, '아칼리, 이제 주인님께 네 피를 바치고 네 힘은 내가 취하리라!'),
(28996, 2, 0, '모두 끝났다. 네 주인에게 돌아가라. 하르코아에게 돌아가란 말이다. 내가 찾아간다고 전해라!'),
(28997, 0, 0, '안녕하시오, $c.'),
(28997, 0, 1, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(28997, 0, 2, '안녕하신가요.'),
(28997, 0, 3, '어서 오십시오!'),
(28998, 0, 0, '이걸 보게! 누구도 보지 못한 최고의 스컬지 군대를 우리가 만드는 걸세!'),
(28998, 1, 0, '이건 시작일 뿐일세! 우리는 줄드락을 바람처럼 휩쓸고 지나갈 게야.'),
(28998, 2, 0, '이런 식으로 날 배신하다니! 이 죄는 네 목숨으로 갚아야 될 게다!'),
(28998, 3, 0, '지배의 홀이 밝게 빛납니다! 지금 사용하십시오!'),
(28998, 4, 0, '어떻게 이럴 수가! 리치 왕께서 널 위한 멋진 계획이 있다고 하셨는데...'),
(28998, 4, 1, '숙명을 거부하다니, 바보 같은 녀석... 넌 이제 끝이다!'),
(28998, 4, 2, '바보야! 넌 엄청난 힘을 가질 수도 있었는데!'),
(28998, 4, 3, '네놈이 배신했다고 내가 눈 하나 깜짝할 것 같으냐!'),
(28998, 4, 4, '세상에 정말 믿을 놈이 하나도 없군!'),
(28998, 4, 5, '네놈 따윈 필요하지도 않았다. 너 없이도 줄드락쯤은 뭉개버릴 수 있어!'),
(28998, 5, 0, '그만!'),
(28998, 6, 0, '이 배신이 네 운명을 결정했다...'),
(28998, 7, 0, '주인님, 비열한 필멸의 존재가 우리를 속였습니다. 녀석은 고통받아 마땅합니다!'),
(28998, 8, 0, '스컬지 위장이 풀립니다! 스컬지를 피하십시오!'),
(29001, 0, 0, '붉은십자군이 너희를 정화해 이 세상에서 몰아내리라!'),
(29001, 1, 0, '내가 직접 너희를 상대해야겠구나. 스컬지여, 종교재판관의 무서움을 느껴 보아라!'),
(29001, 2, 0, '동료를 해방하러 왔나? 난 너희를 해방하러 왔다!'),
(29001, 2, 1, '빛이 너를 정화하리라!'),
(29001, 2, 2, '겁쟁이 녀석!'),
(29001, 3, 0, '%s|1이;가; 땅바닥에 쓰러집니다.'),
(29021, 0, 0, '여전히 우리는 네 미래가 어둡다고 본다. 그러나 이 임무는 네 운명이다, $n. 예언자가 너무 강력해 너와 네 동료가 이겨낼 수 없을지도 모른다. 그래도, 너는 이 일을 해야 한다.'),
(29022, 0, 0, '한 번 더 우리가 네 부름에 응해 주겠다, 쿠푸. 너와 $n|1이;가; 소망하는 지혜가 우리에게 있지. 너희는 큰 위험에 처했고 빨리 행동을 취해야 한다. 그렇지 않으면 너희 모두 하르코아와 함께 죽으리라.'),
(29023, 0, 0, '망자 쿠에츠룬의 감시자가 지닌 돌풍 정수를 얻어야 예언자를 이 세계로 끌어당길 수 있으리라. 이 두 가지 희귀한 물건을 하르코아에게 가져다주어라.'),
(29024, 0, 0, '수호자의 흠집 없는 심장을 얻어 도전 정신과 힘을 보여라. 질투심 많은 짐루크가 거느리는 자들이 그것을 숨기고 있다.'),
(29028, 0, 0, '이건 뭐지? 아칼리를 죽였을 때 너를 느꼈다. 모두가 두려워하는 $n 녀석이로구나.'),
(29028, 1, 0, '난 두렵지 않다, 애송이 녀석. 오히려 그 반대지. 너를 해치울 날을 내가 얼마나 기다렸는지 아느냐? 이제 아무도 내가 짐토르가로 가는 걸 방해할 수 없겠군!'),
(29028, 2, 0, '이제야 진실을 알게 되다니, 가엾기 그지없구나. 나는 신의 힘을 휘두른다! 너는 필멸의 존재일 뿐이지. 날 쓰러뜨리겠다고? 꿈도 꾸지 마라!'),
(29028, 3, 0, '너와 상관없는 일에 사사건건 간섭해 왔겠다. 너는 이방인이자 침입자일 뿐이다. 죽을 준비나 해라!'),
(29028, 4, 0, '예언자가 파멸의 의식을 시작합니다.'),
(29028, 5, 0, '뭐지? 하르코아?!'),
(29028, 6, 0, '좋다, 고양이야. 어차피 언젠가는 닥칠 네 죽음을 더는 미룰 필요가 없겠다. 이 얼간이부터 처리하고 나서 바로 너를 상대해 주마.'),
(29028, 7, 0, '안 돼! 난 지지 않아!'),
(29032, 0, 0, '일을 마무리하러 왔군, 그렇지?'),
(29032, 1, 0, '일을 마무리하러 왔군, 그렇지?'),
(29032, 2, 0, '끝장을 내러 왔나 보군. 그렇지?'),
(29032, 3, 0, '내 눈을 똑바로 보시오. 일을 처리...'),
(29032, 4, 0, '이 아이언포지의 후예는...'),
(29032, 5, 0, '참 얄궂지 않소? 죽게 된다는 거 말이오...'),
(29032, 6, 0, '내게 한 가지만 허락해 준다면...'),
(29032, 7, 0, '내 믿음은 오직...'),
(29032, 8, 0, '난 오크로서 죽고 싶소...'),
(29032, 9, 0, '내 믿음은 오직...'),
(29032, 12, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?'),
(29032, 13, 0, '$n, 어디서든 그 촉수를 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 건가요, $n?'),
(29032, 14, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29032, 15, 0, '$n, 어디서든 그 부패한 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29032, 16, 0, '$n, 어디서든 그 뿔은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29032, 17, 0, '내가 그 엄니를 몰라볼 리가 있겠나, $n... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29032, 18, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 드레나이였던 그 이유 자체를 말입니다!'),
(29032, 19, 0, '날 기억하지 못하는군, 그런 거요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소이다. 당신이 아이언포지의 후예였던 그 이유 자체를 말이오!'),
(29032, 20, 0, '날 기억하지 못하는군, 아니오? 우린 한때, 아주 오래전에 인간이었지. 로데론이 스컬지들의 손에 들어가기 전까지 말이오. 내가 스컬지 좀비가 된 후 바로 당신도 스컬지 좀비로 변했소. 그 후로 오래지 않아 우리의 정신은 어둠의 여왕님 덕분에 해방되었다오.'),
(29032, 21, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 이루는 정의로운 힘은 노움 만큼이라도 모두 빨아들이려고 했습니다. 선의라면 마지막 한 방울까지도요... 당신이 노움이었던 그 이유 자체를 말입니다!'),
(29032, 22, 0, '절 기억하지 못하시는군요, 아닌가요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했어요. 당신이 인간이었던 그 이유 자체를 말이에요!'),
(29032, 23, 0, '절 기억하지 못하는군요? 그대의 어머니는 달의 신을 섬기는 동안 어린 그대를 제게 맡겼었습니다. 그분이 돌아오실 때까지 나는 그대를 이 팔에 안고 꿀과 양 젖을 먹이면서 달랬었습니다. 천사 같은 아이였지요. 망할 스컬지 같으니... 저들이 그대에게 무슨 짓을 한 건가요, $n?'),
(29032, 24, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 오크였던 그 이유 자체를 말이오!'),
(29032, 25, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 타우렌이었던 그 이유 자체를 말이오!'),
(29032, 26, 0, '날 기억하지 못하는군? 망할 스컬지들! 그들이 당신을 모조 전문가로 만든 모든 것을 빨아들이려고 했었소. 최후의 모조까지... 당신이 트롤 영웅이었던 그 이유 자체를 말이오!'),
(29032, 27, 0, '계약은 이루어졌소, $g형제:자매;여! 우린 리치 왕에 맞서는 복수를 맹세했소! 그가 우리에게 한 짓에 대한 복수 말이오! 포세이큰으로서 우리는 스컬지와 싸워 그들을 역병지대로 몰아내고 티리스팔을 자유의 땅으로 만들었소! 당신과 나는 포세이큰의 용사였소!'),
(29032, 28, 0, '빛나던 삶을 기억해보란 말입니다. 당신은 한때 칼도레이의 용사였습니다! 이건 진정한 당신 모습이 아닙니다.'),
(29032, 29, 0, '생각해 보세요, $n. 회상해 보란 말이에요. 당신이 태어난 실버문의 웅장한 전당을 떠올려 보세요. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말이에요. 당신은 한때 신도레이의 용사였어요! 지금의 이 모습은 진정한 당신의 모습이 아니에요.'),
(29032, 30, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 아르거스의 훌륭한 산세를 떠올려 보십시오. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말입니다. 당신은 한때 드레나이의 용사였습니다! 지금의 이 모습은 진정한 당신의 모습이 아닙니다!'),
(29032, 31, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 눈 덮인 던 모로의 산을 기억해 보시오. 빛나던 삶을 떠올려 보란 말이오. 당신은 한때 드워프의 용사였소! 지금의 모습은 진정한 당신 모습이 아니오!'),
(29032, 32, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 빌어먹을 트로그가 점령하기 전의 놈리건을 기억해 보십시오. 만능 스패너의 감촉을 떠올려 보란 말입니다. 당신은 한때 노움의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다!'),
(29032, 33, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 엘윈의 계곡과 언덕을 기억해 보십시오. 빛나던 삶을 기억해보란 말입니다. 당신은 한때 얼라이언스의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다.'),
(29032, 34, 0, '생각해 보시오, $n. 회상해 보란 말이오. 듀로타를 떠올려 보시오! 우리 영웅들의 희생으로 우리가 피의 저주에서 벗어날 수 있었던 일을 떠올려 보시오. 우리가 악마의 영향을 받지 않고 세상에 다시 태어났던 시험의 골짜기로 하켄이 돌아왔소. 우린 화려한 삶을 찾았소. 함께 말이오! 이건 당신이 아니오. 당신은 한때 호드의 용사였소이다!'),
(29032, 35, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 멀고어의 그 넘실거리는 초원을 기억해 보시오. 빛나던 삶을 기억해보란 말이오. 당신은 한때 타우렌 용사였소! 지금의 모습은 진정한 당신의 모습이 아니오.'),
(29032, 36, 0, '생각해 보시오, $n. 회상해 보란 말이오. 우린 검은창 부족이었소! 형제와 자매였단 말이오! 우리가 잘라제인과 싸웠을 때와 그 죽음의 증거를 가져가 메아리 섬을 해방해 주었던 때를 기억해 보시오! 떠올려 보란 말이오! 당신은 검은창 트롤의 영웅이었소!'),
(29032, 37, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29032, 38, 0, '내 말을 들으시오, $n. 리치 왕의 지배에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 조종에서 벗어나시오!'),
(29032, 39, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29032, 40, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29032, 42, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 실버문을 기억하십시오. 이 세상은 구할 가치가 있는 곳입니다.'),
(29032, 43, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 아르거스를 기억하십시오. 이 세계에도 같은 일이 벌어지게 두지 마십시오.'),
(29032, 44, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 카아아아아아아즈으모오오오오오오다아안 만세!'),
(29032, 45, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오, $n. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 티리스팔을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오.'),
(29032, 46, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 놈리건을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29032, 47, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸습니다. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 엘윈을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29032, 48, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 텔드랏실을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29032, 49, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 호드를 위하여! 이 세상은 구할 가치가 있는 곳이라오.'),
(29032, 50, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 멀고어를 기억하시오. 이 세상은 지켜낼 가치가 있는 곳이라오.'),
(29032, 51, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 끝났소. 날 죽여주시오, $n. 날 죽이지 않아도 저들이 우리 둘 다 죽일 거요. $n... 센진 마을을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오!'),
(29032, 52, 0, '어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!'),
(29032, 53, 0, '%s|1이;가; 심한 부상으로 목숨을 잃습니다.'),
(29053, 41, 0, '거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?'),
(29061, 0, 0, '일을 마무리하러 왔군, 그렇지?'),
(29061, 1, 0, '일을 마무리하러 왔군, 그렇지?'),
(29061, 2, 0, '끝장을 내러 왔나 보군. 그렇지?'),
(29061, 3, 0, '내 눈을 똑바로 보시오. 일을 처리...'),
(29061, 4, 0, '이 아이언포지의 후예는...'),
(29061, 5, 0, '참 얄궂지 않소? 죽게 된다는 거 말이오...'),
(29061, 6, 0, '내게 한 가지만 허락해 준다면...'),
(29061, 7, 0, '내 믿음은 오직...'),
(29061, 8, 0, '난 오크로서 죽고 싶소...'),
(29061, 9, 0, '내 믿음은 오직...'),
(29061, 12, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?'),
(29061, 13, 0, '$n, 어디서든 그 촉수를 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 건가요, $n?'),
(29061, 14, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29061, 15, 0, '$n, 어디서든 그 부패한 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29061, 16, 0, '$n, 어디서든 그 뿔은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29061, 17, 0, '내가 그 엄니를 몰라볼 리가 있겠나, $n... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29061, 18, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 드레나이였던 그 이유 자체를 말입니다!'),
(29061, 19, 0, '날 기억하지 못하는군, 그런 거요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소이다. 당신이 아이언포지의 후예였던 그 이유 자체를 말이오!'),
(29061, 20, 0, '날 기억하지 못하는군, 아니오? 우린 한때, 아주 오래전에 인간이었지. 로데론이 스컬지들의 손에 들어가기 전까지 말이오. 내가 스컬지 좀비가 된 후 바로 당신도 스컬지 좀비로 변했소. 그 후로 오래지 않아 우리의 정신은 어둠의 여왕님 덕분에 해방되었다오.'),
(29061, 21, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 이루는 정의로운 힘은 노움 만큼이라도 모두 빨아들이려고 했습니다. 선의라면 마지막 한 방울까지도요... 당신이 노움이었던 그 이유 자체를 말입니다!'),
(29061, 22, 0, '절 기억하지 못하시는군요, 아닌가요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했어요. 당신이 인간이었던 그 이유 자체를 말이에요!'),
(29061, 23, 0, '절 기억하지 못하는군요? 그대의 어머니는 달의 신을 섬기는 동안 어린 그대를 제게 맡겼었습니다. 그분이 돌아오실 때까지 나는 그대를 이 팔에 안고 꿀과 양 젖을 먹이면서 달랬었습니다. 천사 같은 아이였지요. 망할 스컬지 같으니... 저들이 그대에게 무슨 짓을 한 건가요, $n?'),
(29061, 24, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 오크였던 그 이유 자체를 말이오!'),
(29061, 25, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 타우렌이었던 그 이유 자체를 말이오!'),
(29061, 26, 0, '날 기억하지 못하는군? 망할 스컬지들! 그들이 당신을 모조 전문가로 만든 모든 것을 빨아들이려고 했었소. 최후의 모조까지... 당신이 트롤 영웅이었던 그 이유 자체를 말이오!'),
(29061, 27, 0, '계약은 이루어졌소, $g형제:자매;여! 우린 리치 왕에 맞서는 복수를 맹세했소! 그가 우리에게 한 짓에 대한 복수 말이오! 포세이큰으로서 우리는 스컬지와 싸워 그들을 역병지대로 몰아내고 티리스팔을 자유의 땅으로 만들었소! 당신과 나는 포세이큰의 용사였소!');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(29061, 28, 0, '빛나던 삶을 기억해보란 말입니다. 당신은 한때 칼도레이의 용사였습니다! 이건 진정한 당신 모습이 아닙니다.'),
(29061, 29, 0, '생각해 보세요, $n. 회상해 보란 말이에요. 당신이 태어난 실버문의 웅장한 전당을 떠올려 보세요. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말이에요. 당신은 한때 신도레이의 용사였어요! 지금의 이 모습은 진정한 당신의 모습이 아니에요.'),
(29061, 30, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 아르거스의 훌륭한 산세를 떠올려 보십시오. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말입니다. 당신은 한때 드레나이의 용사였습니다! 지금의 이 모습은 진정한 당신의 모습이 아닙니다!'),
(29061, 31, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 눈 덮인 던 모로의 산을 기억해 보시오. 빛나던 삶을 떠올려 보란 말이오. 당신은 한때 드워프의 용사였소! 지금의 모습은 진정한 당신 모습이 아니오!'),
(29061, 32, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 빌어먹을 트로그가 점령하기 전의 놈리건을 기억해 보십시오. 만능 스패너의 감촉을 떠올려 보란 말입니다. 당신은 한때 노움의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다!'),
(29061, 33, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 엘윈의 계곡과 언덕을 기억해 보십시오. 빛나던 삶을 기억해보란 말입니다. 당신은 한때 얼라이언스의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다.'),
(29061, 34, 0, '생각해 보시오, $n. 회상해 보란 말이오. 듀로타를 떠올려 보시오! 우리 영웅들의 희생으로 우리가 피의 저주에서 벗어날 수 있었던 일을 떠올려 보시오. 우리가 악마의 영향을 받지 않고 세상에 다시 태어났던 시험의 골짜기로 하켄이 돌아왔소. 우린 화려한 삶을 찾았소. 함께 말이오! 이건 당신이 아니오. 당신은 한때 호드의 용사였소이다!'),
(29061, 35, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 멀고어의 그 넘실거리는 초원을 기억해 보시오. 빛나던 삶을 기억해보란 말이오. 당신은 한때 타우렌 용사였소! 지금의 모습은 진정한 당신의 모습이 아니오.'),
(29061, 36, 0, '생각해 보시오, $n. 회상해 보란 말이오. 우린 검은창 부족이었소! 형제와 자매였단 말이오! 우리가 잘라제인과 싸웠을 때와 그 죽음의 증거를 가져가 메아리 섬을 해방해 주었던 때를 기억해 보시오! 떠올려 보란 말이오! 당신은 검은창 트롤의 영웅이었소!'),
(29061, 37, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29061, 38, 0, '내 말을 들으시오, $n. 리치 왕의 지배에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 조종에서 벗어나시오!'),
(29061, 39, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29061, 40, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29061, 42, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 실버문을 기억하십시오. 이 세상은 구할 가치가 있는 곳입니다.'),
(29061, 43, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 아르거스를 기억하십시오. 이 세계에도 같은 일이 벌어지게 두지 마십시오.'),
(29061, 44, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 카아아아아아아즈으모오오오오오오다아안 만세!'),
(29061, 45, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오, $n. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 티리스팔을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오.'),
(29061, 46, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 놈리건을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29061, 47, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸습니다. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 엘윈을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29061, 48, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 텔드랏실을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29061, 49, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 호드를 위하여! 이 세상은 구할 가치가 있는 곳이라오.'),
(29061, 50, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 멀고어를 기억하시오. 이 세상은 지켜낼 가치가 있는 곳이라오.'),
(29061, 51, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 끝났소. 날 죽여주시오, $n. 날 죽이지 않아도 저들이 우리 둘 다 죽일 거요. $n... 센진 마을을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오!'),
(29061, 52, 0, '어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!'),
(29061, 53, 0, '%s|1이;가; 심한 부상으로 목숨을 잃습니다.'),
(29065, 0, 0, '일을 마무리하러 왔군, 그렇지?'),
(29065, 1, 0, '일을 마무리하러 왔군, 그렇지?'),
(29065, 2, 0, '끝장을 내러 왔나 보군. 그렇지?'),
(29065, 3, 0, '내 눈을 똑바로 보시오. 일을 처리...'),
(29065, 4, 0, '이 아이언포지의 후예는...'),
(29065, 5, 0, '참 얄궂지 않소? 죽게 된다는 거 말이오...'),
(29065, 6, 0, '내게 한 가지만 허락해 준다면...'),
(29065, 7, 0, '내 믿음은 오직...'),
(29065, 8, 0, '난 오크로서 죽고 싶소...'),
(29065, 9, 0, '내 믿음은 오직...'),
(29065, 12, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?'),
(29065, 13, 0, '$n, 어디서든 그 촉수를 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 건가요, $n?'),
(29065, 14, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29065, 15, 0, '$n, 어디서든 그 부패한 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29065, 16, 0, '$n, 어디서든 그 뿔은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29065, 17, 0, '내가 그 엄니를 몰라볼 리가 있겠나, $n... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29065, 18, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 드레나이였던 그 이유 자체를 말입니다!'),
(29065, 19, 0, '날 기억하지 못하는군, 그런 거요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소이다. 당신이 아이언포지의 후예였던 그 이유 자체를 말이오!'),
(29065, 20, 0, '날 기억하지 못하는군, 아니오? 우린 한때, 아주 오래전에 인간이었지. 로데론이 스컬지들의 손에 들어가기 전까지 말이오. 내가 스컬지 좀비가 된 후 바로 당신도 스컬지 좀비로 변했소. 그 후로 오래지 않아 우리의 정신은 어둠의 여왕님 덕분에 해방되었다오.'),
(29065, 21, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 이루는 정의로운 힘은 노움 만큼이라도 모두 빨아들이려고 했습니다. 선의라면 마지막 한 방울까지도요... 당신이 노움이었던 그 이유 자체를 말입니다!'),
(29065, 22, 0, '절 기억하지 못하시는군요, 아닌가요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했어요. 당신이 인간이었던 그 이유 자체를 말이에요!'),
(29065, 23, 0, '절 기억하지 못하는군요? 그대의 어머니는 달의 신을 섬기는 동안 어린 그대를 제게 맡겼었습니다. 그분이 돌아오실 때까지 나는 그대를 이 팔에 안고 꿀과 양 젖을 먹이면서 달랬었습니다. 천사 같은 아이였지요. 망할 스컬지 같으니... 저들이 그대에게 무슨 짓을 한 건가요, $n?'),
(29065, 24, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 오크였던 그 이유 자체를 말이오!'),
(29065, 25, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 타우렌이었던 그 이유 자체를 말이오!'),
(29065, 26, 0, '날 기억하지 못하는군? 망할 스컬지들! 그들이 당신을 모조 전문가로 만든 모든 것을 빨아들이려고 했었소. 최후의 모조까지... 당신이 트롤 영웅이었던 그 이유 자체를 말이오!'),
(29065, 27, 0, '계약은 이루어졌소, $g형제:자매;여! 우린 리치 왕에 맞서는 복수를 맹세했소! 그가 우리에게 한 짓에 대한 복수 말이오! 포세이큰으로서 우리는 스컬지와 싸워 그들을 역병지대로 몰아내고 티리스팔을 자유의 땅으로 만들었소! 당신과 나는 포세이큰의 용사였소!'),
(29065, 28, 0, '빛나던 삶을 기억해보란 말입니다. 당신은 한때 칼도레이의 용사였습니다! 이건 진정한 당신 모습이 아닙니다.'),
(29065, 29, 0, '생각해 보세요, $n. 회상해 보란 말이에요. 당신이 태어난 실버문의 웅장한 전당을 떠올려 보세요. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말이에요. 당신은 한때 신도레이의 용사였어요! 지금의 이 모습은 진정한 당신의 모습이 아니에요.'),
(29065, 30, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 아르거스의 훌륭한 산세를 떠올려 보십시오. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말입니다. 당신은 한때 드레나이의 용사였습니다! 지금의 이 모습은 진정한 당신의 모습이 아닙니다!'),
(29065, 31, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 눈 덮인 던 모로의 산을 기억해 보시오. 빛나던 삶을 떠올려 보란 말이오. 당신은 한때 드워프의 용사였소! 지금의 모습은 진정한 당신 모습이 아니오!'),
(29065, 32, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 빌어먹을 트로그가 점령하기 전의 놈리건을 기억해 보십시오. 만능 스패너의 감촉을 떠올려 보란 말입니다. 당신은 한때 노움의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다!'),
(29065, 33, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 엘윈의 계곡과 언덕을 기억해 보십시오. 빛나던 삶을 기억해보란 말입니다. 당신은 한때 얼라이언스의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다.'),
(29065, 34, 0, '생각해 보시오, $n. 회상해 보란 말이오. 듀로타를 떠올려 보시오! 우리 영웅들의 희생으로 우리가 피의 저주에서 벗어날 수 있었던 일을 떠올려 보시오. 우리가 악마의 영향을 받지 않고 세상에 다시 태어났던 시험의 골짜기로 하켄이 돌아왔소. 우린 화려한 삶을 찾았소. 함께 말이오! 이건 당신이 아니오. 당신은 한때 호드의 용사였소이다!'),
(29065, 35, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 멀고어의 그 넘실거리는 초원을 기억해 보시오. 빛나던 삶을 기억해보란 말이오. 당신은 한때 타우렌 용사였소! 지금의 모습은 진정한 당신의 모습이 아니오.'),
(29065, 36, 0, '생각해 보시오, $n. 회상해 보란 말이오. 우린 검은창 부족이었소! 형제와 자매였단 말이오! 우리가 잘라제인과 싸웠을 때와 그 죽음의 증거를 가져가 메아리 섬을 해방해 주었던 때를 기억해 보시오! 떠올려 보란 말이오! 당신은 검은창 트롤의 영웅이었소!'),
(29065, 37, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29065, 38, 0, '내 말을 들으시오, $n. 리치 왕의 지배에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 조종에서 벗어나시오!'),
(29065, 39, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29065, 40, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29065, 42, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 실버문을 기억하십시오. 이 세상은 구할 가치가 있는 곳입니다.'),
(29065, 43, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 아르거스를 기억하십시오. 이 세계에도 같은 일이 벌어지게 두지 마십시오.'),
(29065, 44, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 카아아아아아아즈으모오오오오오오다아안 만세!'),
(29065, 45, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오, $n. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 티리스팔을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오.'),
(29065, 46, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 놈리건을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
