(29065, 50, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 멀고어를 기억하시오. 이 세상은 지켜낼 가치가 있는 곳이라오.'),
(29065, 51, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 끝났소. 날 죽여주시오, $n. 날 죽이지 않아도 저들이 우리 둘 다 죽일 거요. $n... 센진 마을을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오!'),
(29065, 52, 0, '어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!'),
(29065, 53, 0, '%s|1이;가; 심한 부상으로 목숨을 잃습니다.'),
(29067, 0, 0, '일을 마무리하러 왔군, 그렇지?'),
(29067, 1, 0, '일을 마무리하러 왔군, 그렇지?'),
(29067, 2, 0, '끝장을 내러 왔나 보군. 그렇지?'),
(29067, 3, 0, '내 눈을 똑바로 보시오. 일을 처리...'),
(29067, 4, 0, '이 아이언포지의 후예는...'),
(29067, 5, 0, '참 얄궂지 않소? 죽게 된다는 거 말이오...'),
(29067, 6, 0, '내게 한 가지만 허락해 준다면...'),
(29067, 7, 0, '내 믿음은 오직...'),
(29067, 8, 0, '난 오크로서 죽고 싶소...'),
(29067, 9, 0, '내 믿음은 오직...'),
(29067, 12, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?'),
(29067, 13, 0, '$n, 어디서든 그 촉수를 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 건가요, $n?'),
(29067, 14, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29067, 15, 0, '$n, 어디서든 그 부패한 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29067, 16, 0, '$n, 어디서든 그 뿔은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29067, 17, 0, '내가 그 엄니를 몰라볼 리가 있겠나, $n... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29067, 18, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 드레나이였던 그 이유 자체를 말입니다!'),
(29067, 19, 0, '날 기억하지 못하는군, 그런 거요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소이다. 당신이 아이언포지의 후예였던 그 이유 자체를 말이오!'),
(29067, 20, 0, '날 기억하지 못하는군, 아니오? 우린 한때, 아주 오래전에 인간이었지. 로데론이 스컬지들의 손에 들어가기 전까지 말이오. 내가 스컬지 좀비가 된 후 바로 당신도 스컬지 좀비로 변했소. 그 후로 오래지 않아 우리의 정신은 어둠의 여왕님 덕분에 해방되었다오.'),
(29067, 21, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 이루는 정의로운 힘은 노움 만큼이라도 모두 빨아들이려고 했습니다. 선의라면 마지막 한 방울까지도요... 당신이 노움이었던 그 이유 자체를 말입니다!'),
(29067, 22, 0, '절 기억하지 못하시는군요, 아닌가요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했어요. 당신이 인간이었던 그 이유 자체를 말이에요!'),
(29067, 23, 0, '절 기억하지 못하는군요? 그대의 어머니는 달의 신을 섬기는 동안 어린 그대를 제게 맡겼었습니다. 그분이 돌아오실 때까지 나는 그대를 이 팔에 안고 꿀과 양 젖을 먹이면서 달랬었습니다. 천사 같은 아이였지요. 망할 스컬지 같으니... 저들이 그대에게 무슨 짓을 한 건가요, $n?'),
(29067, 24, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 오크였던 그 이유 자체를 말이오!'),
(29067, 25, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 타우렌이었던 그 이유 자체를 말이오!'),
(29067, 26, 0, '날 기억하지 못하는군? 망할 스컬지들! 그들이 당신을 모조 전문가로 만든 모든 것을 빨아들이려고 했었소. 최후의 모조까지... 당신이 트롤 영웅이었던 그 이유 자체를 말이오!'),
(29067, 27, 0, '계약은 이루어졌소, $g형제:자매;여! 우린 리치 왕에 맞서는 복수를 맹세했소! 그가 우리에게 한 짓에 대한 복수 말이오! 포세이큰으로서 우리는 스컬지와 싸워 그들을 역병지대로 몰아내고 티리스팔을 자유의 땅으로 만들었소! 당신과 나는 포세이큰의 용사였소!'),
(29067, 28, 0, '빛나던 삶을 기억해보란 말입니다. 당신은 한때 칼도레이의 용사였습니다! 이건 진정한 당신 모습이 아닙니다.'),
(29067, 29, 0, '생각해 보세요, $n. 회상해 보란 말이에요. 당신이 태어난 실버문의 웅장한 전당을 떠올려 보세요. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말이에요. 당신은 한때 신도레이의 용사였어요! 지금의 이 모습은 진정한 당신의 모습이 아니에요.'),
(29067, 30, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 아르거스의 훌륭한 산세를 떠올려 보십시오. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말입니다. 당신은 한때 드레나이의 용사였습니다! 지금의 이 모습은 진정한 당신의 모습이 아닙니다!'),
(29067, 31, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 눈 덮인 던 모로의 산을 기억해 보시오. 빛나던 삶을 떠올려 보란 말이오. 당신은 한때 드워프의 용사였소! 지금의 모습은 진정한 당신 모습이 아니오!'),
(29067, 32, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 빌어먹을 트로그가 점령하기 전의 놈리건을 기억해 보십시오. 만능 스패너의 감촉을 떠올려 보란 말입니다. 당신은 한때 노움의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다!'),
(29067, 33, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 엘윈의 계곡과 언덕을 기억해 보십시오. 빛나던 삶을 기억해보란 말입니다. 당신은 한때 얼라이언스의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다.'),
(29067, 34, 0, '생각해 보시오, $n. 회상해 보란 말이오. 듀로타를 떠올려 보시오! 우리 영웅들의 희생으로 우리가 피의 저주에서 벗어날 수 있었던 일을 떠올려 보시오. 우리가 악마의 영향을 받지 않고 세상에 다시 태어났던 시험의 골짜기로 하켄이 돌아왔소. 우린 화려한 삶을 찾았소. 함께 말이오! 이건 당신이 아니오. 당신은 한때 호드의 용사였소이다!'),
(29067, 35, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 멀고어의 그 넘실거리는 초원을 기억해 보시오. 빛나던 삶을 기억해보란 말이오. 당신은 한때 타우렌 용사였소! 지금의 모습은 진정한 당신의 모습이 아니오.'),
(29067, 36, 0, '생각해 보시오, $n. 회상해 보란 말이오. 우린 검은창 부족이었소! 형제와 자매였단 말이오! 우리가 잘라제인과 싸웠을 때와 그 죽음의 증거를 가져가 메아리 섬을 해방해 주었던 때를 기억해 보시오! 떠올려 보란 말이오! 당신은 검은창 트롤의 영웅이었소!'),
(29067, 37, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29067, 38, 0, '내 말을 들으시오, $n. 리치 왕의 지배에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 조종에서 벗어나시오!'),
(29067, 39, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29067, 40, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29067, 42, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 실버문을 기억하십시오. 이 세상은 구할 가치가 있는 곳입니다.'),
(29067, 43, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 아르거스를 기억하십시오. 이 세계에도 같은 일이 벌어지게 두지 마십시오.'),
(29067, 44, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 카아아아아아아즈으모오오오오오오다아안 만세!'),
(29067, 45, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오, $n. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 티리스팔을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오.'),
(29067, 46, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 놈리건을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29067, 47, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸습니다. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 엘윈을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29067, 48, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 텔드랏실을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29067, 49, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 호드를 위하여! 이 세상은 구할 가치가 있는 곳이라오.'),
