(29073, 8, 0, '난 오크로서 죽고 싶소...'),
(29073, 9, 0, '내 믿음은 오직...'),
(29073, 12, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?'),
