(29073, 15, 0, '$n, 어디서든 그 부패한 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29073, 16, 0, '$n, 어디서든 그 뿔은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29073, 17, 0, '내가 그 엄니를 몰라볼 리가 있겠나, $n... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29073, 18, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 드레나이였던 그 이유 자체를 말입니다!'),
(29073, 19, 0, '날 기억하지 못하는군, 그런 거요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소이다. 당신이 아이언포지의 후예였던 그 이유 자체를 말이오!'),
(29073, 20, 0, '날 기억하지 못하는군, 아니오? 우린 한때, 아주 오래전에 인간이었지. 로데론이 스컬지들의 손에 들어가기 전까지 말이오. 내가 스컬지 좀비가 된 후 바로 당신도 스컬지 좀비로 변했소. 그 후로 오래지 않아 우리의 정신은 어둠의 여왕님 덕분에 해방되었다오.'),
(29073, 21, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 이루는 정의로운 힘은 노움 만큼이라도 모두 빨아들이려고 했습니다. 선의라면 마지막 한 방울까지도요... 당신이 노움이었던 그 이유 자체를 말입니다!'),
(29073, 22, 0, '절 기억하지 못하시는군요, 아닌가요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했어요. 당신이 인간이었던 그 이유 자체를 말이에요!'),
(29073, 23, 0, '절 기억하지 못하는군요? 그대의 어머니는 달의 신을 섬기는 동안 어린 그대를 제게 맡겼었습니다. 그분이 돌아오실 때까지 나는 그대를 이 팔에 안고 꿀과 양 젖을 먹이면서 달랬었습니다. 천사 같은 아이였지요. 망할 스컬지 같으니... 저들이 그대에게 무슨 짓을 한 건가요, $n?'),
(29073, 24, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 오크였던 그 이유 자체를 말이오!'),
(29073, 25, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 타우렌이었던 그 이유 자체를 말이오!'),
(29073, 26, 0, '날 기억하지 못하는군? 망할 스컬지들! 그들이 당신을 모조 전문가로 만든 모든 것을 빨아들이려고 했었소. 최후의 모조까지... 당신이 트롤 영웅이었던 그 이유 자체를 말이오!'),
(29073, 27, 0, '계약은 이루어졌소, $g형제:자매;여! 우린 리치 왕에 맞서는 복수를 맹세했소! 그가 우리에게 한 짓에 대한 복수 말이오! 포세이큰으로서 우리는 스컬지와 싸워 그들을 역병지대로 몰아내고 티리스팔을 자유의 땅으로 만들었소! 당신과 나는 포세이큰의 용사였소!'),
(29073, 28, 0, '빛나던 삶을 기억해보란 말입니다. 당신은 한때 칼도레이의 용사였습니다! 이건 진정한 당신 모습이 아닙니다.'),
(29073, 29, 0, '생각해 보세요, $n. 회상해 보란 말이에요. 당신이 태어난 실버문의 웅장한 전당을 떠올려 보세요. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말이에요. 당신은 한때 신도레이의 용사였어요! 지금의 이 모습은 진정한 당신의 모습이 아니에요.'),
(29073, 30, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 아르거스의 훌륭한 산세를 떠올려 보십시오. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말입니다. 당신은 한때 드레나이의 용사였습니다! 지금의 이 모습은 진정한 당신의 모습이 아닙니다!'),
(29073, 31, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 눈 덮인 던 모로의 산을 기억해 보시오. 빛나던 삶을 떠올려 보란 말이오. 당신은 한때 드워프의 용사였소! 지금의 모습은 진정한 당신 모습이 아니오!'),
(29073, 32, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 빌어먹을 트로그가 점령하기 전의 놈리건을 기억해 보십시오. 만능 스패너의 감촉을 떠올려 보란 말입니다. 당신은 한때 노움의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다!'),
(29073, 33, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 엘윈의 계곡과 언덕을 기억해 보십시오. 빛나던 삶을 기억해보란 말입니다. 당신은 한때 얼라이언스의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다.'),
(29073, 34, 0, '생각해 보시오, $n. 회상해 보란 말이오. 듀로타를 떠올려 보시오! 우리 영웅들의 희생으로 우리가 피의 저주에서 벗어날 수 있었던 일을 떠올려 보시오. 우리가 악마의 영향을 받지 않고 세상에 다시 태어났던 시험의 골짜기로 하켄이 돌아왔소. 우린 화려한 삶을 찾았소. 함께 말이오! 이건 당신이 아니오. 당신은 한때 호드의 용사였소이다!'),
(29073, 35, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 멀고어의 그 넘실거리는 초원을 기억해 보시오. 빛나던 삶을 기억해보란 말이오. 당신은 한때 타우렌 용사였소! 지금의 모습은 진정한 당신의 모습이 아니오.'),
(29073, 36, 0, '생각해 보시오, $n. 회상해 보란 말이오. 우린 검은창 부족이었소! 형제와 자매였단 말이오! 우리가 잘라제인과 싸웠을 때와 그 죽음의 증거를 가져가 메아리 섬을 해방해 주었던 때를 기억해 보시오! 떠올려 보란 말이오! 당신은 검은창 트롤의 영웅이었소!'),
(29073, 37, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29073, 38, 0, '내 말을 들으시오, $n. 리치 왕의 지배에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 조종에서 벗어나시오!'),
(29073, 39, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29073, 40, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29073, 42, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 실버문을 기억하십시오. 이 세상은 구할 가치가 있는 곳입니다.'),
(29073, 43, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 아르거스를 기억하십시오. 이 세계에도 같은 일이 벌어지게 두지 마십시오.'),
(29073, 44, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 카아아아아아아즈으모오오오오오오다아안 만세!'),
(29073, 45, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오, $n. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 티리스팔을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오.'),
(29073, 46, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 놈리건을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29073, 47, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸습니다. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 엘윈을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29073, 48, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 텔드랏실을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29073, 49, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 호드를 위하여! 이 세상은 구할 가치가 있는 곳이라오.'),
(29073, 50, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 멀고어를 기억하시오. 이 세상은 지켜낼 가치가 있는 곳이라오.'),
(29073, 51, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 끝났소. 날 죽여주시오, $n. 날 죽이지 않아도 저들이 우리 둘 다 죽일 거요. $n... 센진 마을을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오!'),
(29073, 52, 0, '어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!'),
(29073, 53, 0, '%s|1이;가; 심한 부상으로 목숨을 잃습니다.'),
(29074, 0, 0, '일을 마무리하러 왔군, 그렇지?'),
(29074, 1, 0, '일을 마무리하러 왔군, 그렇지?'),
(29074, 2, 0, '끝장을 내러 왔나 보군. 그렇지?'),
(29074, 3, 0, '내 눈을 똑바로 보시오. 일을 처리...'),
(29074, 4, 0, '이 아이언포지의 후예는...'),
(29074, 5, 0, '참 얄궂지 않소? 죽게 된다는 거 말이오...'),
(29074, 6, 0, '내게 한 가지만 허락해 준다면...'),
(29074, 7, 0, '내 믿음은 오직...'),
(29074, 8, 0, '난 오크로서 죽고 싶소...'),
(29074, 9, 0, '내 믿음은 오직...'),
(29074, 12, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 겁니까, $n?'),
(29074, 13, 0, '$n, 어디서든 그 촉수를 알아볼 수 있습니다... 도대체... 저들이 당신에게 무슨 짓을 한 건가요, $n?'),
(29074, 14, 0, '$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29074, 15, 0, '$n, 어디서든 그 부패한 얼굴은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29074, 16, 0, '$n, 어디서든 그 뿔은 알아볼 수 있소... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29074, 17, 0, '내가 그 엄니를 몰라볼 리가 있겠나, $n... 도대체... 저들이 당신에게 무슨 짓을 한 거요, $n?'),
(29074, 18, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했습니다. 당신이 드레나이였던 그 이유 자체를 말입니다!'),
(29074, 19, 0, '날 기억하지 못하는군, 그런 거요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소이다. 당신이 아이언포지의 후예였던 그 이유 자체를 말이오!'),
(29074, 20, 0, '날 기억하지 못하는군, 아니오? 우린 한때, 아주 오래전에 인간이었지. 로데론이 스컬지들의 손에 들어가기 전까지 말이오. 내가 스컬지 좀비가 된 후 바로 당신도 스컬지 좀비로 변했소. 그 후로 오래지 않아 우리의 정신은 어둠의 여왕님 덕분에 해방되었다오.'),
(29074, 21, 0, '절 기억하지 못하시는군요, 그렇죠? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 이루는 정의로운 힘은 노움 만큼이라도 모두 빨아들이려고 했습니다. 선의라면 마지막 한 방울까지도요... 당신이 노움이었던 그 이유 자체를 말입니다!'),
(29074, 22, 0, '절 기억하지 못하시는군요, 아닌가요? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했어요. 당신이 인간이었던 그 이유 자체를 말이에요!'),
(29074, 23, 0, '절 기억하지 못하는군요? 그대의 어머니는 달의 신을 섬기는 동안 어린 그대를 제게 맡겼었습니다. 그분이 돌아오실 때까지 나는 그대를 이 팔에 안고 꿀과 양 젖을 먹이면서 달랬었습니다. 천사 같은 아이였지요. 망할 스컬지 같으니... 저들이 그대에게 무슨 짓을 한 건가요, $n?'),
(29074, 24, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 오크였던 그 이유 자체를 말이오!'),
(29074, 25, 0, '날 기억하지 못하는군, 아니오? 망할 스컬지 같으니... 그놈들은 당신이라는 존재를 말하던 정의로운 힘은 물론 마지막 선의까지도 모두 빨아들이려고 했소. 당신이 타우렌이었던 그 이유 자체를 말이오!'),
(29074, 26, 0, '날 기억하지 못하는군? 망할 스컬지들! 그들이 당신을 모조 전문가로 만든 모든 것을 빨아들이려고 했었소. 최후의 모조까지... 당신이 트롤 영웅이었던 그 이유 자체를 말이오!'),
(29074, 27, 0, '계약은 이루어졌소, $g형제:자매;여! 우린 리치 왕에 맞서는 복수를 맹세했소! 그가 우리에게 한 짓에 대한 복수 말이오! 포세이큰으로서 우리는 스컬지와 싸워 그들을 역병지대로 몰아내고 티리스팔을 자유의 땅으로 만들었소! 당신과 나는 포세이큰의 용사였소!'),
(29074, 28, 0, '빛나던 삶을 기억해보란 말입니다. 당신은 한때 칼도레이의 용사였습니다! 이건 진정한 당신 모습이 아닙니다.'),
(29074, 29, 0, '생각해 보세요, $n. 회상해 보란 말이에요. 당신이 태어난 실버문의 웅장한 전당을 떠올려 보세요. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말이에요. 당신은 한때 신도레이의 용사였어요! 지금의 이 모습은 진정한 당신의 모습이 아니에요.'),
(29074, 30, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 아르거스의 훌륭한 산세를 떠올려 보십시오. $g형제:자매;여, 화려했던 삶을 떠올려 보란 말입니다. 당신은 한때 드레나이의 용사였습니다! 지금의 이 모습은 진정한 당신의 모습이 아닙니다!'),
(29074, 31, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 눈 덮인 던 모로의 산을 기억해 보시오. 빛나던 삶을 떠올려 보란 말이오. 당신은 한때 드워프의 용사였소! 지금의 모습은 진정한 당신 모습이 아니오!'),
(29074, 32, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 빌어먹을 트로그가 점령하기 전의 놈리건을 기억해 보십시오. 만능 스패너의 감촉을 떠올려 보란 말입니다. 당신은 한때 노움의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다!'),
(29074, 33, 0, '생각해 보십시오, $n. 회상해 보란 말입니다. 당신이 태어난 엘윈의 계곡과 언덕을 기억해 보십시오. 빛나던 삶을 기억해보란 말입니다. 당신은 한때 얼라이언스의 용사였습니다! 지금의 모습은 진정한 당신의 모습이 아닙니다.'),
(29074, 34, 0, '생각해 보시오, $n. 회상해 보란 말이오. 듀로타를 떠올려 보시오! 우리 영웅들의 희생으로 우리가 피의 저주에서 벗어날 수 있었던 일을 떠올려 보시오. 우리가 악마의 영향을 받지 않고 세상에 다시 태어났던 시험의 골짜기로 하켄이 돌아왔소. 우린 화려한 삶을 찾았소. 함께 말이오! 이건 당신이 아니오. 당신은 한때 호드의 용사였소이다!'),
(29074, 35, 0, '생각해 보시오, $n. 회상해 보란 말이오. 당신이 태어난 멀고어의 그 넘실거리는 초원을 기억해 보시오. 빛나던 삶을 기억해보란 말이오. 당신은 한때 타우렌 용사였소! 지금의 모습은 진정한 당신의 모습이 아니오.'),
(29074, 36, 0, '생각해 보시오, $n. 회상해 보란 말이오. 우린 검은창 부족이었소! 형제와 자매였단 말이오! 우리가 잘라제인과 싸웠을 때와 그 죽음의 증거를 가져가 메아리 섬을 해방해 주었던 때를 기억해 보시오! 떠올려 보란 말이오! 당신은 검은창 트롤의 영웅이었소!'),
(29074, 37, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29074, 38, 0, '내 말을 들으시오, $n. 리치 왕의 지배에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 조종에서 벗어나시오!'),
(29074, 39, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29074, 40, 0, '내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 당신이 그의 목적을 이루는 도구로 이용당해서는 안 되오. 당신은 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!'),
(29074, 42, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 실버문을 기억하십시오. 이 세상은 구할 가치가 있는 곳입니다.'),
(29074, 43, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 아르거스를 기억하십시오. 이 세계에도 같은 일이 벌어지게 두지 마십시오.'),
(29074, 44, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 카아아아아아아즈으모오오오오오오다아안 만세!'),
(29074, 45, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오, $n. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 티리스팔을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오.'),
(29074, 46, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 놈리건을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29074, 47, 0, '이젠... 내게 더 남은 시간이 없습니다. 난 이제 틀렸습니다. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 엘윈을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29074, 48, 0, '이젠... 내게 더 남은 시간이 없습니다. 이제 틀렸어요. 날 죽여 주십시오. 그러지 않으면 저들이 우리 둘 다 죽일 겁니다. $n... 텔드랏실을 기억하십시오. 이 세상은 지켜낼 가치가 있는 곳입니다.'),
(29074, 49, 0, '이젠... 내게 더 남은 시간이 없소. 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 호드를 위하여! 이 세상은 구할 가치가 있는 곳이라오.'),
(29074, 50, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 멀고어를 기억하시오. 이 세상은 지켜낼 가치가 있는 곳이라오.'),
(29074, 51, 0, '이젠... 내게 더 남은 시간이 없소. 난 이제 끝났소. 날 죽여주시오, $n. 날 죽이지 않아도 저들이 우리 둘 다 죽일 거요. $n... 센진 마을을 기억하시오! 이 세상은 구할 가치가 있는 곳이라오!'),
(29074, 52, 0, '어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!'),
(29074, 53, 0, '%s|1이;가; 심한 부상으로 목숨을 잃습니다.'),
(29076, 0, 0, '흠, 이상한 나무로군. 조사해 봐야겠어.'),
(29076, 1, 0, '이게 뭐지? 이건 나무가 아니잖아! 경비병! 경비병!'),
(29120, 0, 0, '영원한 고통이 너희를 기다린다!'),
(29120, 1, 0, '곧, 주인님이 널 부를 것이다.'),
(29120, 1, 1, '네가 자초한 일이다.'),
(29120, 1, 2, '네놈을 제일 먼저 고문해 주지...'),
(29120, 2, 0, '으아... 으아아아! 그에게서 벗어날 수 있을 줄은, 꿈에도...'),
(29120, 3, 0, '메뚜기 떼에는 갑옷도 쓸모없다!'),
(29120, 3, 1, '우우낙 히티쉬 틱크크!'),
(29120, 3, 2, '독충한테 한번 당해 봐라!'),
(29120, 4, 0, '아움 날락크, 쉬.'),
(29120, 4, 1, '오너라, 형제들이여! 잔치를 벌이자!'),
(29173, 0, 0, '스컬지 군대여! 준비하라! 은빛 여명회 놈들에게 우리의 분노를 보여줄 때다!'),
(29173, 1, 0, '짓밟힌 대지를 보며 하늘도 눈물을 흘리는구나. 머지않아, 온 아제로스가 우리 앞에 피눈물을 흘리리라!'),
(29173, 2, 0, '아케루스 죽음의 기사여, 죽음의 행진을 시작하자!'),
(29173, 3, 0, '스컬지 병사여, 아케루스 죽음의 기사여, 어둠의 추종자여! 대영주의 부름에 응답하라!'),
(29173, 4, 0, '일어나라!'),
(29173, 5, 0, '하늘이 희생자의 피로 붉게 물들었다! 리치 왕께서 우리를 굽어보고 계신다! 너희가 휩쓸고 간 자리에는 재와 비탄만을 남겨라!'),
(29173, 8, 0, '대영주에게 무릎을 꿇어라!'),
(29173, 8, 1, '희망 따위는 없다!'),
(29173, 8, 2, '스컬지가 여기를 휩쓸 것이다!'),
(29173, 8, 3, '네놈의 목숨을 끊어주겠다.'),
(29173, 8, 4, '고통 없는 삶이란 무의미하다!'),
(29173, 8, 5, '너희가 얼마나 더 버틸 것 같으냐?'),
(29173, 8, 6, '은빛 여명회는 끝났다!'),
(29173, 8, 7, '모두 없애라!'),
(29173, 8, 8, '왜 이러지? 검을... 휘두를 수가...'),
(29173, 8, 9, '내게 복종하라, 검이여!'),
(29173, 8, 10, '내 명령을 따라라! 나는 너의 주인이다!'),
(29173, 8, 11, '이럴... 이럴 수가... 검이 내게 맞서다니!'),
(29173, 8, 12, '내게 무슨 일이 벌어지고 있는 것이냐?'),
(29173, 8, 13, '힘이... 빠져나가...'),
(29173, 8, 14, '파멸의 인도자가 반항을!'),
(29173, 8, 15, '제군들! 와서 나를 도와라!'),
(29173, 26, 0, '포기해라, 죽음의 기사여. 우리는 졌다. 이곳엔... 빛이 가득해... 희망이 없다...'),
(29173, 30, 0, '닥쳐라, 늙은이. 그 말이 마지막이 될지도 모르니...'),
(29173, 32, 0, '아버지!'),
(29173, 33, 0, '으아! 이게... 대체...'),
(29173, 43, 0, '넌... 나를 배신했다! 우리 모두를 배신했다! 모그레인의 분노에 맞서 보아라!'),
(29173, 51, 0, '그날이 오늘은 아니다...'),
(29173, 52, 0, '티리온!'),
(29173, 67, 0, '칠흑의 기사단도 함께할 것이다. 비록 너희 사이에 우리 자리는 없겠지만, 리치 왕을 끝장낼 때까지 싸울 것이다! 맹세한다!'),
(29173, 68, 0, '티리온!'),
(29173, 69, 0, '티리온!'),
(29173, 70, 0, '티리온!'),
(29173, 72, 0, '패배한 %s|1이;가; 티리온 폴드링 앞에 무릎을 꿇습니다.'),
(29173, 77, 0, '패배한 %s|1이;가; 티리온 폴드링 앞에 무릎을 꿇습니다.'),
(29173, 81, 0, '패배한 %s|1이;가; 티리온 폴드링 앞에 무릎을 꿇습니다.'),
(29173, 82, 0, '%s|1이;가; 털썩 주저앉습니다.'),
(29173, 85, 0, '패배한 %s|1이;가; 티리온 폴드링 앞에 무릎을 꿇습니다.'),
(29175, 24, 0, '너는 졌다, 다리온!'),
(29175, 25, 0, '예배당 앞으로 데려가라!'),
(29175, 27, 0, '아직도 모르겠나, 젊은이? 넌 네 아버지가 맞서 싸우던 적이 되었다! 저 겁쟁이 아서스처럼, 너도 어둠에, 분노에 무릎 꿇고 말았구나. 고문당하고 죽임당한 사람들의 고통을 먹고 사는 괴물이 되었어!'),
(29175, 28, 0, '예배당 아래 뭐가 있는지 네 주인은 안다. 그래서 나타나지 않는 게지! 너와 죽음의 기사들만 사지로 보낸 것이다.'),
(29175, 29, 0, '수천의 영혼이 느끼는 고통을 지금 너도 느낄 것이다! 너와 네 주인이 데려온 영혼의 괴로움을! 빛이 너를 갈기갈기 찢을 것이다...'),
(29175, 46, 0, '넌 지독한 괴물이다, 아서스!'),
(29175, 53, 0, '아서스!'),
(29175, 55, 0, '너의 패배다.'),
(29175, 59, 0, '일어나라, 다리온. 내 말을 들어라...'),
(29175, 60, 0, '우리는 끔찍한 비극을 목격했다. 선한 이의 피가 이 땅을 적셨다! 명예로운 기사들이 죽어갔다. 자신을, 우리를 지키기 위해...'),
(29175, 61, 0, '이 비극을 되새겨, 우리는 목적을 위해 더욱 정진해야 한다!'),
(29175, 62, 0, '리치 왕은 죗값을 치러야 한다. 리치 왕이 우리 세계를 파괴하지 못하게 해야 한다.'),
(29175, 63, 0, '이 자리에서 약속한다, 형제자매여. 리치 왕은 패배할 것이다! 오늘 여기서, 나는 연합을 선언한다.'),
(29175, 64, 0, '은빛 여명회와 은빛 성기사단이 하나가 될 것이다! 수많은 이가 실패했어도, 우리는 승리하리라!'),
(29175, 65, 0, '우리는 아서스와 싸우고, 얼음왕관의 벽을 무너뜨릴 것이다!'),
(29175, 66, 0, '은빛십자군이 간다. 기다려라, 아서스!'),
(29175, 79, 0, '%s|1이;가; 숨 막히는 소리를 냅니다.'),
(29175, 83, 0, '%s|1이;가; 파멸의 인도자를 들고 리치 왕에게 돌진해 공격합니다.'),
(29176, 6, 0, '스컬지 군대가 다가온다!'),
(29178, 7, 0, '버텨라, 형제자매여! 빛은 승리할 것이다!'),
(29178, 49, 0, '공격!!!'),
(29183, 42, 0, '감동적이군...'),
(29183, 44, 0, '그는 내 것이지...'),
(29183, 45, 0, '애처롭군...'),
(29183, 47, 0, '그래, 폴드링. 내가 그들을 사지에 내보냈지. 가치 없는 목숨들이다. 하지만 네 목숨은...'),
(29183, 48, 0, '위대한 티리온 폴드링을 쥐구멍에서 끌어내는 게 이렇게 쉬울 줄이야. 성기사여, 넌 이제 허허벌판에 섰다. 무엇도 널 지켜줄 순 없어...'),
(29183, 50, 0, '대참사를!'),
(29183, 54, 0, '무슨 일이지?'),
(29183, 56, 0, '이럴 수가...'),
(29183, 57, 0, '이걸로... 끝난 건... 아니다!'),
(29183, 58, 0, '다음번엔 성스러운 땅의 도움은 받지 못할 게다...'),
(29183, 78, 0, '%s|1이;가; 티리온에게 주문을 시전합니다.'),
(29183, 80, 0, '%s|1이;가; 강력한 주문을 시전해 수호자들을 죽이고 나머지를 밀쳐냅니다.'),
(29183, 84, 0, '%s|1이;가; 사라집니다. 티리온이 다리온이 쓰러진 곳으로 걸어갑니다.'),
(29196, 0, 0, '피의 사도로서, 자네들은 적의 생명력을 지배할 수 있도록 노력해야 한다.'),
(29196, 1, 0, '칼로든 마법으로든 피를 흘리면, 공격은 강해지고 적은 약해지리라.'),
(29196, 2, 0, '진정한 대가라면 전투에서 피가 가진 원래 힘보다 더 많은 것을 끌어낼 줄 알아야 한다.'),
(29196, 3, 0, '싸우는 놈이나 쓰러진 놈 가리지 않고, 적의 기운을 빼앗아버리면 더 작은 존재들이 나가떨어지는 곳에서도 우리가 버틸 수 있다.'),
(29196, 4, 0, '그리고 적은 기운이 흡수되고 빼앗긴 채 모두 쓰러져, 우리 공격에 힘을 더하리라.'),
(29196, 5, 0, '피의 대가가 된 우리는, 영원히 싸우리라...'),
(29196, 6, 0, '굶주림이 영원히 가시지 않으리라는 것을 안다...'),
(29196, 7, 0, '힘을 영원히 정복하지 못하리라는 것을 안다...'),
(29196, 8, 0, '피의 대가로서, 우리는 모두 삶과 죽음 그 자체를 다스리는 대가이다. 우리에게 대항하는 자는, 희망조차 말라버리고 사라질 것이다.'),
(29204, 71, 0, '%s|1이;가; 도망칩니다.'),
(29227, 31, 0, '다리온! 사랑하는 내 아들아!'),
(29227, 36, 0, '돌아오는 게 당연하잖니, 다리온. 내 집이, 가족이 여기 있는데.'),
(29227, 38, 0, '다리온 모그레인, 넌 이제 겨우 칼을 들 수 있는 나이란다. 로데론의 언데드 군대와 전투라니? 네가 죽으면 어쩌란 말이냐. 생각만 해도 난...'),
(29227, 40, 0, '얘야... 언젠가 네가 파멸의 인도자를 휘두를 날이 올 게다. 검을 들고, 너는 온 세상을 누비며 정의를 수호하겠지. 난 믿어 의심치 않는단다. 그날이 오면, 너는 우리 모두의 자랑이 되고 로데론은 내 아들 덕에 더 살기 좋은 땅이 될 테지. 하지만 아들아, 아직은 때가 아니다.'),
(29227, 41, 0, '잊지 말거라...'),
(29227, 73, 0, '%s|1이;가; 도착합니다.'),
(29227, 76, 0, '%s|1이;가; 사라지고 리치 왕이 나타납니다.'),
(29228, 34, 0, '아버지! 돌아오셨군요!'),
(29228, 35, 0, '너무 오래 떠나 계셨어요. 전 그만...'),
(29228, 37, 0, '아버지, 함께 전장에 나가서 싸우고 싶어요. 저도 싸우겠어요! 가만히 있긴 싫어요!'),
(29228, 39, 0, '제가 죽는다면, 제 의지에 따라 죽겠어요! 언데드 무리와 싸우다가 말입니다! 죽는다면, 아버지와 함께 죽겠어요!'),
(29228, 74, 0, '%s|1이;가; 과거의 망령이 되어 아버지에게 다가갑니다.'),
(29228, 75, 0, '%s|1이;가; 아버지를 끌어안습니다.'),
(29260, 1, 0, '스파크라이트의 탈것 상점이 영업을 개시했다고, 친구!'),
(29262, 1, 0, '리그스파크가 탈것 상점을 열었습니다!'),
(29266, 0, 0, '아무래도 내 자유는 피로 사야 하나 보군.'),
(29266, 1, 0, '개인적 원한은 없다.'),
(29266, 1, 1, '영업 종료.'),
(29266, 1, 2, '수익 달성!'),
(29266, 2, 0, '이건... 복구할 수 없는... 손실이군.'),
(29266, 3, 0, '영업시간이다. 이제, 탈출 계획을 실행에 옮겨야겠지?'),
(29266, 4, 0, '재협상의 시간이 온 것 같군.'),
(29266, 5, 0, '공기 중에 숨은 에너지가 상당한데? 훌륭한 수확이야.'),
(29266, 5, 1, '손 닿는 곳에 넘쳐나는 자원이라... 이런 건 써먹어 줘야지!'),
(29266, 6, 0, '흥미롭군... 근처에 비전 에너지가 꽤 많은데? 작업을 시작해 볼까...'),
(29280, 0, 0, '너의 희생이 네 충성심을 증명하는구나. 그래. 넌 자격이 있다. 일어나라. 이제부터 네 이름은 스발라 소로우그레이브다!'),
(29280, 1, 0, '첫 번째 시험이 기다린다. 초대받지 않은 손님들을 처치해라.'),
(29304, 0, 0, '독사의 자식들아... 내 부름에 응해라!'),
(29304, 1, 0, '수많은 이빨이 네 살점을 찢을 것이다!'),
(29304, 2, 0, '%s|1이;가; 독 회오리를 시전합니다!'),
(29304, 3, 0, '%s|1이;가; 쓰러지면서 그의 발코니 바닥에 설치된 제단에서 희미하게 빛이 나기 시작합니다.'),
(29304, 4, 0, '이 땅을 침입하는 놈은... 드라카리 손에 죄다 죽는다!'),
(29304, 5, 0, '숨이 멎었나? 좋아...'),
(29304, 5, 1, '슬슬 겁이 나나?'),
(29304, 5, 2, '몸은 따로... 쓸 데가 있지.'),
(29304, 6, 0, '가장 무서운 적은... 스컬지가 아니었구나...'),
(29305, 0, 0, '%s|1이;가; 모습을 바꾸기 시작합니다!'),
(29305, 1, 0, '%s|1이;가; 매머드로 모습을 바꿉니다!'),
(29305, 2, 0, '%s|1이;가; 쓰러지면서 그의 발코니 바닥에 설치된 제단에서 희미하게 빛이 나기 시작합니다.'),
(29305, 3, 0, '우리는 스컬지와 싸웠다. 네깟 것들은 아무것도 아니지!'),
(29305, 4, 0, '진짜... 커다란 걸... 보여주겠다!'),
(29305, 5, 0, '땅이 너희를 삼켜버릴 것이다!'),
(29305, 6, 0, '바퀴 같은 놈들... 밟아주마!'),
(29305, 6, 1, '누가 날 막겠다고? 네가?'),
(29305, 6, 2, '별것도 아니구나!'),
(29305, 7, 0, '신께서도 죽는데... 우리라고 다르겠나...'),
(29306, 0, 0, '오늘이 네놈들 제삿날인 줄 알아라!'),
(29306, 1, 0, '지금 이 순간부터 아무것도 남지 않을 것이다!'),
(29306, 1, 1, '힘이 뭔지 알고 싶나? 진짜 힘을 보여주지!'),
(29306, 2, 0, '들이받아라! 꿰뚫어 버려라!'),
(29306, 2, 1, '전부 없애버려라!'),
(29306, 2, 2, '커다란 내 친구를 소개하지!'),
(29306, 3, 0, '너무 빠른 거 아니냐?'),
(29306, 3, 1, '우리가 바로 신인데, 신이 왜 필요하지?'),
(29306, 3, 2, '내가 말하지 않았나!'),
(29306, 4, 0, '강하다고... 불멸은 아니지...'),
(29306, 5, 0, '$n|1이;가; 관통당했습니다!'),
(29308, 0, 0, '마법의 기운이 사라지면서 공기의 울림이 잦아듭니다...'),
(29308, 1, 0, '침입자들! 누가 감히 고대 왕국을 침범하는가?'),
(29308, 2, 0, '너희의 종말에 축배를 들겠노라!'),
(29308, 3, 0, '빈 도레이 암오벨!'),
(29308, 3, 1, '축배는 일을 끝내고 나서 들겠다.'),
(29308, 3, 2, '최후의... 포옹이다.'),
(29308, 4, 0, '여전히... 배고프다. 여전히... 목마르다.'),
(29308, 5, 0, '아주... 감미롭군.'),
(29308, 5, 1, '신선하고 따뜻한 피... 아, 너무 오랜만이야.'),
(29308, 6, 0, '너희 심장 소리가... 나에겐 음악과도 같구나.'),
(29308, 6, 1, '나는 어디에도 없다. 나는 어디에든 있다. 난 보이지 않는 감시자다...'),
(29309, 0, 0, '심연의 비밀은 계속 비밀로 남을 것이다.'),
(29309, 1, 0, '차가운 어둠 속에 잠들거라...'),
(29309, 1, 1, '리치 왕을 위하여!'),
(29309, 1, 2, '우린 곧 같은 편이 될지도 모른다.'),
(29309, 2, 0, '주인님... 제 임무는 이제... 끝입니까?'),
(29309, 3, 0, '어린애가 배를 곯아선 안 되지...'),
(29309, 3, 1, '샤드 아크 케리쉬... 샤칵칵칵칵!'),
(29309, 4, 0, '안카하르 수호자가 깨어납니다!'),
(29311, 0, 0, '샤글라요스 플라프 음흐나우스.'),
(29311, 1, 0, '길 잃은 영혼을 맛본 자는 영원히 굶주림에 시달리게 되지.'),
(29311, 2, 0, '굴카프 안셸 율. 요칼 쉰키 이와크 눌.'),
(29311, 3, 0, '공허를 들여다보아라. 그들이 속한 불멸의 영역이지.'),
(29311, 4, 0, '이와크 마크 오우, 이와크 막 싸아크. 이와크 마 쉬픈.'),
(29311, 5, 0, '그들은 죽지 않는다. 그들은 살지 않는다. 그들은 생명의 순환을 벗어난 존재다.'),
(29311, 6, 1, '릴스 브와, 우나트 프쉬 자.'),
(29311, 7, 1, '하나가 죽으면, 수많은 이가 그 자리를 대신하지.'),
(29311, 8, 0, '이와크 풀 크스근 온마 예글루 주.'),
(29311, 9, 0, '그들은 공포를 마신다. 그것은 생명이다.'),
(29311, 10, 0, '이와크 마 프와쿨 낙푸.'),
(29311, 11, 0, '그들은 매서운 바람의 속삭임이다.'),
(29311, 12, 0, '우울비 각 어훈그 우.'),
(29311, 13, 0, '그들의 그림자가 영원토록 이 땅을 옥죄리라.'),
(29313, 0, 0, '필멸의 존재여, 비켜라!'),
(29313, 1, 0, '내가 바로 자연의 힘이다!'),
(29313, 1, 1, '나는 나아가리라!'),
(29313, 1, 2, '파도를 멈출 순 없다!'),
(29313, 2, 0, '나는... 물러난다...'),
(29313, 3, 0, '나는 주체할 수 없는 분노다!'),
(29313, 4, 0, '나는... 삼키고, 휩쓸고, 압도하고, 파괴하리라! 강력한 바다의 분노에 굴복하라!'),
(29313, 5, 0, '날 가두진 못한다!'),
(29313, 6, 0, '물은... 모든 형태를 담고, 아무 모양이나 취하고, 어떤 장애도 뛰어넘지.'),
(29313, 7, 0, '%s|1을;를; 둘러싼 거품 보호막이 터집니다!'),
(29314, 0, 0, '박멸한다.'),
(29314, 1, 0, '아직... 부족하다.'),
(29314, 1, 1, '포기하라.'),
(29314, 1, 2, '암흑에... 굴복하라.'),
(29314, 2, 0, '흩어진다...'),
(29314, 3, 0, '나... 소생했다.'),
(29314, 4, 0, '내... 고통을... 맛보라.'),
(29314, 5, 0, '공허를... 주시하라.'),
(29315, 0, 0, '나, 도망간다! 비켜!'),
(29315, 1, 0, '케케케!'),
(29315, 1, 1, '귀한 생명을... 낭비했구나!'),
(29315, 1, 2, '강한 놈만... 살아남는다!'),
(29315, 2, 0, '안 돼... 도망갈래...'),
(29315, 3, 0, '이제... 날 수 있다. 못 찾을걸! 탈출!'),
(29315, 4, 0, '내가... 좋아하는 녀석! 악 악 아악!'),
(29315, 5, 0, '나쁜 놈들... 죽어! 그래... 죽어!'),
(29319, 0, 0, '성난 수컷입니다!'),
(29319, 1, 0, '암컷입니다.'),
(29327, 0, 0, '성난 수컷입니다!'),
(29327, 1, 0, '암컷입니다.'),
(29368, 0, 0, '뻔한 놈들! 하긴, 돌 따위가 그보다 낫기를 기대한다는 게 무리지!'),
(29368, 1, 0, '네놈이 정 그렇게 싸우고 싶다면, 그 소원을 들어주마. 하지만 네놈이 여기서 하는 짓은 아무것도 무쇠 거대괴수의 완성을 막을 순 없을 것이야!'),
(29369, 0, 0, '너희 누난 렌치고, 너희 형은 시포리움이지?'),
(29384, 0, 0, '계산할 수 없습니다. 기능에 문제가 있습니다. 지령. 작동 중지.'),
(29384, 0, 1, '새 지령. 광산을 떠나 발명가의 도서관으로 갑니다.'),
(29384, 0, 2, '새 지령. 무쇠 드워프를 쓰러뜨립니다.'),
(29384, 0, 3, '자유라고요? 미미르 님께서 시키신 일을 마저 해야겠군요.'),
(29384, 0, 4, '감사합니다. 저도 무쇠 드워프를 상대하는 데 힘을 보태겠습니다.'),
(29434, 0, 0, '준비가 되면 알려주세요. 좀 빨리 갔으면 좋겠군요. 독이다 뭐다 해서 서서히 죽어 가고 있으니까 말이에요...'),
(29434, 1, 0, '리켓에게 독주머니를 가져가겠습니다... 그런 후에는.. 예상하시겠지만... 쓰러지겠지요. 도와줘서 고맙습니다!'),
(29466, 0, 0, '믿을 수가 없군! 이제 집에 갈 수 있다니!'),
(29466, 0, 1, '이제 해방인가? 나 풀려났다!'),
(29466, 0, 2, '전속력으로 달려가자고! 고마워, 친구!'),
(29491, 0, 0, '어서 오십시오. 찾는 물건이라도 있으십니까?'),
(29491, 0, 1, '어서 오십시오.'),
(29519, 0, 0, '너 방금 엄청난 실수한 거라고, 머저리!'),
(29519, 0, 1, '한때는 나도 성스러운 빛을 따르는 병사였다... 지금 내 꼴이 어떤지 봐라...'),
(29519, 0, 2, '$r, 넌 상대할 가치도 없다.'),
(29519, 0, 3, '내가 가치 없는 존재라고 낙인을 찍었다고? 가치가 어떤 건지 직접 보여주마!'),
(29519, 0, 4, '무기와 방어구를 사용하도록 허락해 주겠지?'),
(29519, 0, 5, '반드시 자유를 얻어내어 이 빌어먹을 장소에서 벗어날 것이다!'),
(29519, 0, 6, '이 썩어빠진 구렁텅이를 무너뜨리고 말 테다!'),
(29519, 0, 7, '하나만 살아나갈 수 있다!'),
(29519, 1, 0, '덤벼라!'),
