(29523, 0, 3, '$c님, 찾는 물건이 있다면 말씀만 하세요.'),
(29525, 0, 0, '고맙네, 고마워! 이 시퍼런 미치광이 여인들로부터 이제 벗어날 수 있겠군!'),
