(29560, 0, 0, '잘했네. 이 일을 마무리짓도록 하세.'),
(29560, 1, 0, '자, 랜드그렌. 아주 중요한 질문을 해야 하니 그 영혼을 드러내라.'),
(29560, 2, 0, '웨스트윈드가 어디 있는지 당장 털어놓지 않으면 네 영혼을 박살 내 버리겠다!'),
(29560, 3, 0, '그렇다면, 별수 없군. 이런 일이 또 나름대로 재미가 없는 것도 아니니.'),
(29560, 4, 0, '잘 생각했다. 어서 말해라!'),
(29560, 5, 0, '숨겨진 동굴이라고? 흥미로운 사실이군. 네 할 바를 다 해주어서 고맙다, 랜드그렌. 안타깝지만, 이번에는 다시 살아나지 못할 것이다!'),
(29560, 6, 0, '마무리가 좀 유쾌하지는 않았군. 이제 네가 웨스트윈드 총사령관을 어떻게 처리할지나 얘기해보지.'),
(29565, 0, 0, '너 방금 엄청난 실수한 거라고, 머저리!'),
