(29572, 0, 0, '나에게서 아무것도 알아내지 못할 것이다, 비열한 놈. 나는 네 능력으로는 감당할 수 없는 존재이다.'),
(29572, 1, 0, '안 돼.'),
(29572, 2, 0, '멈춰! 그렇게까지 중요한 일도 아니니. 웨스트윈드가 어디 있는지 말해 주겠다.'),
(29572, 3, 0, '이 섬 남쪽 끝 무렵에 동굴이 하나 있다. 숨겨진 동굴이라는 곳이지. 총사령관은 그 안에 숨어 리치 왕과 마지막 결전을 벌일 준비를 하고 있다.'),
(29572, 4, 0, '으아아아아아아아아아아악........................................'),
(29573, 0, 0, '%s|1이;가; 모조로 물보라를 일으키며 정면으로 돌진합니다!'),
(29573, 1, 0, '%s의 마지막 잔여물이 바닥으로 스며들면서 근처 바닥에 설치된 제단에서 희미하게 빛이 나기 시작합니다.'),
(29579, 0, 0, '오... 무슨 말인지 이해하겠습니다! 이제 정말 대화를 나눌 수 있겠군요. 제게 설명해 주셔야 할 일이 있습니다!'),
(29579, 1, 0, '어떻게 탐험가 연맹에서 제 통신기를 구한 거지요?'),
(29579, 2, 0, '탐험가 연맹에서 사람을 보냈는지 어떤지는 모르겠습니다. 저는 단지 무쇠 드워프가 점령한 야영지에서 당신의 쪽지를 발견했을 뿐입니다.'),
(29579, 3, 0, '무쇠 드워프를 손봐 주셨나 보군요. 감사합니다. 하지만, 왜 호드가 제게 관심을 두는 거지요?'),
(29579, 4, 0, '한 척후병이 토르 모단에서 당신의 일지를 발견했습니다. 이후로 호드는 계속 당신을 찾고 있었지요.'),
(29579, 5, 0, '그 척후병이 설마 보르타크는 아니겠지요? 그가 무자비하다는 소문은 저 같은 사람도 들어 봤다고요. 그가 저를 붙잡으려고 하나요?'),
(29579, 6, 0, '일지를 보셨다면, 제가 어떤 작업에 매달려 왔는지 아실 텐데요. 우리는 서로 칼을 겨누고 있지만, 둘 다 티탄의 창조물입니다!'),
(29579, 7, 0, '로켄과 무쇠 드워프들이 토석인을 내쫓고 울두아르를 차지했습니다.'),
(29579, 8, 0, '우리가 계속 서로 싸우는 데 힘을 소비하면, 로켄이 울두아르의 자원을 이용해 호드와 얼라이언스 둘 다를 무너뜨릴 겁니다.'),
(29579, 9, 0, '당신네 기지로 돌아가 사령관에게 이야기하세요. 보르타크의 멍청한 계획은 잊으라고 설득하시라고요.'),
(29614, 0, 0, '저승에서도 도망칠 곳 따위는 없으리라!'),
(29614, 0, 1, '네 영혼까지 먹어 버릴 테다!'),
(29614, 0, 2, '이제 잘 알겠지. 넌 죽어야 한다!'),
(29614, 0, 3, '살아서 이 동굴을 나가지 못할 것이다!'),
(29614, 1, 0, '흑마술사가 완전히 다른 모습으로 변하며 사악한 미소를 흘립니다.'),
(29618, 0, 0, '크르르...'),
(29618, 0, 1, '나 안 무섭다!'),
(29618, 0, 2, '그물로 나 잡을 수 없어! 없는데... 그물로 나 잡았다.'),
(29618, 0, 3, '나 죽이지 마!'),
(29618, 0, 4, '안 돼!'),
(29618, 0, 5, '너 나... 못 데려간다!'),
(29621, 0, 0, '어떻게 날 찾았지? 랜드그렌이 불었나?'),
(29621, 1, 0, '정말 날 쓰러뜨릴 수 있다고 생각했나?'),
(29621, 2, 0, '뭐지?! 상관없다. 보호의 구슬이 없어도, 네놈들쯤이야! 내 진정한 모습을 보여주마! 각오해라!'),
(29621, 3, 0, '으으으으아! 저 약한 몸뚱이 안에 너무 오래 있었어!'),
(29621, 4, 0, '키렐 나라크! 나는 말가니스다. 나는 불멸이다!'),
(29621, 5, 0, '그만! 시간 낭비만 했군. 돌아가서 힘을 다시 모아야겠다.'),
(29621, 6, 0, '내 도움 없이 리치 왕을 물리칠 수 있을 것 같으냐? 나는 복수할 것이다... 녀석에게도, 너희에게도!'),
(29647, 1, 0, '내 형제가 날 구하러 오면 너흰 진짜 힘이 뭔지 알게 될 거다!'),
(29647, 1, 1, '너희 모두 밟아 주겠다!'),
(29647, 1, 2, '못생긴 꼬마 괴물아, 내가 여기서 못 나가길 빌어라!'),
(29647, 1, 3, '날 괴롭혀 봤자 내 분노만 북돋울 뿐이다!'),
(29647, 1, 4, '못생긴 꼬마 괴물아, 내가 여기서 못 나가길 빌어라!'),
(29647, 1, 5, '비열한 놈들!'),
(29647, 1, 6, '통째로 삼켜 버리겠다!'),
(29647, 1, 8, '비열한 놈들!'),
(29647, 1, 9, '못생긴 꼬마 괴물아, 내가 여기서 못 나가길 빌어라!'),
(29647, 1, 10, '날 괴롭혀 봤자 내 분노만 북돋울 뿐이다!'),
(29647, 7, 7, '자유다!!! 이제 폭풍의 왕의 분노를 보여주마!'),
(29686, 0, 0, '풉, 트롤따윈 가소롭다!'),
(29686, 0, 1, '아아아으으으으으윽!'),
(29686, 0, 2, '착한 울바르 씨는 이제 안녕이다!'),
(29709, 0, 0, '브룬힐다르 마을로 돌아가라!'),
(29709, 0, 1, '원시비룡이 자유의 냄새를 맡고는 고향으로 날아갑니다!'),
(29762, 0, 0, '경비병!'),
(29801, 0, 0, '드디어, 폭풍으로 벼려낸 무쇠 드워프의 횡포가 끝이 나는구나!'),
(29801, 1, 0, '우리는 발두란을 물리치고 그 휘하에 있는 거대괴수를 쓰러뜨릴 것입니다.'),
(29821, 0, 0, '아, 네가 그를 풀어주었구나. 맞나? 상관없다. 그를 죽였다가 재조립하는 일이 잠시 늦춰졌을 뿐이니.'),
(29821, 1, 1, '스림... 복수를... 해 다오...'),
(29880, 0, 0, '죽고 싶어서 왔냐!'),
(29880, 0, 1, '덜 떨어진 놈!'),
(29880, 0, 2, '멀록 수프에 넣어 줄까...'),
(29881, 0, 0, '그들이 오고 있다.'),
(29881, 0, 1, '공포에 굴복해라.'),
(29881, 0, 2, '모두 처치해라... 네가 당하기 전에.'),
(29881, 0, 3, '그들은 너를 배신했지. 이제, 복수해라.'),
(29881, 0, 4, '기억해라. 그들은 진정한 친구가 아니야.'),
(29881, 0, 5, '탈출구는 없다. 지금 생에서도, 다음 생에서도.'),
(29881, 0, 6, '너는 보이지 않는 힘의 포로다.'),
(29881, 0, 7, '그건 네 탓이었어.'),
(29884, 1, 0, '자이머의 커다란 신발 맛을 봐라!'),
(29884, 1, 1, '밟아버리겠다!'),
(29884, 1, 2, '폭풍이 내게 힘을 주었다!'),
(29884, 1, 3, '조그만 것들아, 밟아주마!'),
(29884, 1, 4, '네놈 몸뚱이로 장화나 닦아야겠다!'),
(29884, 1, 5, '으아아아아아아아아아아아!! 힘이 넘친다!'),
(29884, 1, 6, '번개가 내 분노를 이끈다!'),
(29884, 1, 7, '번개가 나를 타고 흐른다!'),
(29884, 8, 8, '선택받은 알가르는 여기서 북동쪽으로 가면 나오는 고통의 성물함에 있다. 나바리우스 왕자가 있는 곳은 동쪽에 있는 죽음의 들판 반대쪽이다.'),
(29884, 9, 9, '선택받은 알가르는 여기서 북동쪽으로 가면 나오는 고통의 성물함에 있다. 나바리우스 왕자가 있는 곳은 동쪽에 있는 죽음의 들판 반대쪽이다.'),
(29884, 10, 10, '잘 가거라, 친구여. 더 좋은 상황에서 다시 만나길. 네가 날 위해 해준 일을 잊지 않겠다!'),
(29887, 1, 0, '구워 줄까!'),
(29887, 1, 1, '덜 떨어진 놈!'),
(29887, 1, 2, '멀록 수프에 넣어 줄까...'),
(29887, 1, 3, '확, 그냥!'),
(29887, 1, 4, '우글린 우아 비욜!'),
(29887, 1, 5, '구워 줄까!'),
(29887, 1, 6, '웬 놈이냐!'),
(29887, 1, 7, '머리카락으로 신발을 만들어 버리겠다.'),
(29895, 0, 0, '주인님! 안 돼!'),
(29895, 1, 1, '스림이 밟아줄 테다!'),
(29919, 1, 0, '칠흑의 기사단 사령관이자 스컬지 제압자, 어둠의 무기고에서 승리를 거두신 란크랄 공작님의 명령에 따라, 즉각 사퇴를 선고하는 바이다. 어떤 의견이 있는가?'),
(29919, 2, 0, '무슨 일이지?'),
(29919, 3, 0, '내 결정 말이냐? 이게 내 결정이다, 하찮은 심부름꾼아!'),
(29919, 4, 0, '멀록 수프에 넣어 줄까...'),
(29932, 0, 0, '모조 웅덩이 속에서 무언가 움직입니다...'),
(30007, 0, 0, '직접 보지 못하면 믿을 수도 없을 전투! 한 상냥한 투스카르 어부가, 잔인한 바다사자 무리와 열받은 펭귄에게 온 가족을 잃고 무정한 용병으로 돌변하고 말았습니다! 이제 그를 움직이는 논리는 오로지 돈입니다! 신사 숙녀 여러분, 오리노코 터스크브레이커를 소개합니다!!'),
(30007, 1, 0, '겨울도끼 트롤 최고의 전사가 자네에게 도전했네, $n! 마음의 준비를 하라고!'),
(30007, 2, 0, '머나먼 알터랙 산맥에서 왔습니다! 지금껏 이 투기장에 모습을 드러낸 이 중 가장 강력한 전사, 피의 광전사 콜라크입니다!!!'),
(30007, 3, 0, '전투가 곧 시작됩니다! 헉, 제 눈이 잘못된 걸까요?! 이번... 이번 상대는 무시무시한 마그나타우르 군주, 노린내수염입니다! 그렇습니다, 여러분! 무려 노린내수염이라고요! $n|1은;는; 이제 끝장입니다!'),
(30007, 6, 0, '여러분, 느껴지십니까? 관중석이 후끈 달아올랐습니다! 곧 전투가 시작되겠군요!'),
(30007, 7, 0, '웅장한 고뇌의 투기장이 자네를 기다리는군, $n. 기억하라고. 일단 전투가 시작되면 투기장에서 나가면 안 돼. 죽이 되든 밥이 되든 말이지!'),
(30007, 8, 0, '신사 숙녀 여러분, 새로운 이야기가 시작됩니다. 고뇌의 투기장에서 펼쳐지는 삶과 죽음의 드라마를 지켜보십시오! 이번에 $n의 상대는 덩치 큰 요르문가르, 이그... 이그드? 이그도즈? 이거 뭐라고 읽는 거야? 아, 하여튼... $n|1과;와; 커다란 벌레의 대결입니다!'),
(30007, 9, 0, '전투 준비를 하라고, $n! 고뇌의 투기장에 내려가서 대기해야 해! 기억하라고. 자네든 적이든 투기장을 벗어나면 실격이야!'),
(30007, 10, 0, '$n|1이;가; 이그... 이그 어쩌고 하는 큰 벌레를 물리쳤습니다!'),
(30007, 11, 0, '$n|1이;가; 대전에서 또 승리를 거뒀습니다!'),
(30007, 12, 0, '$n|1이;가; 마그나타우르 군주를 압도했습니다! 용의 안식처에 있는 노린내수염의 가족들이 슬퍼하겠군요!'),
(30007, 13, 0, '얼음왕관에 있는 야만전사의 절벽 출신, 도살자 블라도프와 그의 매머드 왕발굽을 소개합니다! 우리의 도전자에게는 희망이 없군요! 피와 눈물이 강을 이루는 한판을 기대하십시오!'),
(30007, 14, 0, '믿을 수가 없군요! 새로운 용사가 고뇌의 투기장을 접수했습니다!!! 어중이떠중이로 이루어진 어설픈 무리에게 도살자 블라도프가 지고 말았군요! 참으로 극적입니다!'),
(30007, 15, 0, '바닥에 떨어진 핏방울 말고는 도전자의 흔적이란 찾아볼 수도 없군요!'),
(30007, 15, 1, '어이쿠! 눈을 가리십시오, 신사 숙녀 여러분! 참혹합니다!'),
(30007, 15, 2, '광대를 내보내는 게 낫겠군요! 텅 빈 투기장에서 곡예라도 부리게 말입니다!'),
(30007, 15, 3, '우왓! 저분은 완전히 곤죽이 되셨는데요.'),
(30007, 15, 4, '어떻게 이런 일이! 저런! 차라리 그냥 없어져 버리라고!'),
(30007, 15, 5, '도전자는 와르르 무너지고 말았습니다!'),
(30012, 0, 0, '그대는 저를 꺾을 수 없습니다!'),
(30014, 1, 0, '%s|1이;가; 모습을 드러냅니다!'),
(30017, 0, 0, '%s|1이;가; 격노합니다!'),
(30017, 1, 0, '노린내수염이 간다, 쥐방울만한 녀석들아!'),
(30019, 1, 0, '흐물흐물 녹여 주마!'),
(30019, 2, 0, '나의 왕국을 불태우려는 건 소용없는 짓이다! 오너라 노예들아, 나는 아직 건재하다!'),
(30020, 0, 0, '오너라, 땅에 사는 자여! 엄니와 수염의 분노에 맞서 보아라!'),
(30020, 1, 0, '어디 있느냐, 왕수염? 날 도와라!'),
(30022, 1, 0, '그래, 귀여운 것. 우리가 저들을 밟아주자! 단 하나의, 진정한 왕을 위하여!'),
(30022, 2, 0, '쓸모없는 짐승 같으니! 내가 직접 상대하겠다!'),
(30022, 3, 0, '블라도프가 매머드에서 내립니다!'),
(30022, 4, 0, '%s|1이;가; 마법 보호막 안에서 회전하기 시작합니다!'),
(30023, 1, 0, '콜라크가 왔노라, 나약한 존재들이여! 눈사태 무덤은 겨울도끼 부족의 것이다! 아, 그게 아니라... 고뇌의 투기장은 겨울도끼 부족 거다!'),
(30023, 2, 0, '여긴 무덤이 없으니 콜라크를 상대로 사악한 장난을 칠 수 없을걸! 죽어라!'),
(30024, 1, 0, '넵튤론 님을 위하여! 바다와 폭풍이여, 적을 뭉개버려라!'),
(30024, 2, 0, '나는 세상에서 가장 무섭고 차가운 존재이다! 정령들아, 나를 따라 모든 것을 얼리고 지배하자!'),
(30025, 1, 0, '일어나라, 대지의 형제들아! 필멸의 존재들이 에라시우스 손에 쓰러지는 것을 지켜보아라!'),
(30025, 2, 0, '나는 세상에서 가장 위대한 진흙왕이다! 부하들아, 너희의 왕인 나를 도와라!'),
(30026, 1, 0, '알아키르 님께서 곧바로 적들에 냉혹한 죽음을 안기시리라!'),
(30026, 2, 0, '나의 힘센 바람은 나무들도 쓰러뜨린다! 부하들아, 날 도와 저들이 멋대로 굴지 못하도록 해라!'),
(30081, 0, 0, '감히 날 건드리다니?! 네가 무슨 짓을 하든 나는 반드시 리치 왕께 내 가치를 증명할 것이다!'),
(30084, 0, 0, '마력의 불꽃이 근처에 있는 틈에서 올라옵니다!'),
(30098, 0, 0, '간식 있어요!'),
(30098, 0, 1, '간식거리 팝니다!'),
(30098, 0, 2, '맛있는 간식 사세요!'),
(30098, 0, 3, '간식 있어요! 맛잇는 간식 사세요!'),
(30098, 0, 4, '팝콘 있어요! 팝콘 사 가세요!'),
(30098, 0, 5, '땅콩 있어요! 맛있는 땅콩 사세요!'),
(30098, 0, 6, '쓰디 쓴 에일 맥주 있어요! 쓰디 쓴 에일 맥주 있습니다!'),
(30098, 0, 7, '팝콘! 땅콩! 맥주 있어요!'),
(30124, 0, 0, '오, 안녕하신가. 작은 $r 친구.'),
(30146, 0, 0, '날 짐승처럼 대하다니, 저주를 받아라!'),
(30146, 0, 1, '이제 그만! 네 녀석의 버르장머리를 고쳐주마!'),
(30146, 0, 2, '노예처럼 사느니 죽을 때까지 싸우겠다!'),
(30146, 1, 0, '일터로... 돌아가야...'),
(30146, 1, 1, '언젠가는...복수해줄 테다.'),
(30146, 1, 2, '우릴 짐승보다 더 심하게 취급하다니!'),
(30152, 0, 0, '네 졸개들이 더는 돌의 생명체들과 동맹들을 공격하지 못할 것이다.'),
(30152, 1, 0, '발두란, 네 운명은 내 손에 있다!'),
(30152, 2, 0, '잘 싸웠소! 오늘은 우리가 이겼지만, 전쟁은 계속될 것이오!'),
(30180, 0, 0, '오누준이 곧 송장으로 만들어주마!'),
(30190, 0, 0, '외래종 금속 견본이 감지되었습니다.'),
(30190, 1, 0, '분석을 시작합니다...'),
(30190, 2, 0, '이 금속 견본은 사로나이트와 무쇠 합금 물질임이 확인되었습니다.'),
(30190, 3, 0, '이 견본에 사용된 광석은 아제로스의 지각 깊은 곳에서 생겨났으며 최근에 발굴되었습니다.'),
(30190, 4, 0, '이 견본에 들어 있는 사로나이트는 거의 순수한 광석 자체입니다. 이와 같은 광석은 본래 아제로스의 지면에서 발견되지 않습니다.'),
(30190, 5, 0, '이 광석은 강력하고 악의에 찬 힘으로만 생성할 수 있습니다. 더 자세한 정보를 얻고자 정보 저장고에 접속을 시도합니다...'),
(30190, 6, 0, '접근이 거부되었습니다?!'),
(30190, 7, 0, '추가적인 정보는 관리자 로켄의 명령에 의해서만 울두아르 내에 있는 저장고에서 접근할 수 있습니다.'),
(30190, 8, 0, '한 가지 확실한 점은 이 금속의 크기, 두께, 볼트 구멍이 거대한 구조물을 위한 갑옷에 사용된다는 겁니다.'),
(30190, 9, 0, '명령을 완료했습니다. 대기 상태로 전환합니다.'),
(30215, 1, 0, '호디르의 후예여! 당신에게 드리노니...'),
(30215, 2, 0, '호디르의 투구!'),
(30219, 0, 0, '검은늑대가 적들을 찾아 뛰쳐나갑니다.'),
(30219, 1, 0, '사냥감에 접근하자 검은늑대가 으르렁거립니다.'),
(30219, 2, 0, '서리 검은늑대가 길게 짖자 사냥감이 뛰쳐나옵니다!'),
(30224, 0, 0, '무슨 생각하나?'),
(30225, 0, 0, '영원노래 숲 말입니다, 달포르스 님. 저는 아서스가 죽음의 낫을 휘두르기 전에 영원노래 숲이 얼마나 아름다웠는지를 생각하고 있습니다...'),
(30243, 0, 0, '구워 줄까!'),
(30243, 0, 1, '멀록 수프에 넣어 줄까...'),
(30243, 0, 2, '멀록 수프에 넣어 줄까...'),
(30243, 0, 3, '뼈를 알뜰히 매만져주마...'),
(30243, 0, 4, '덜 떨어진 놈!'),
(30243, 0, 5, '우글린 우아 비욜!'),
(30243, 0, 6, '죽고 싶어서 왔냐!'),
(30243, 0, 7, '확, 그냥!'),
(30243, 0, 8, '하라크 폴른!'),
(30243, 0, 9, '머리카락으로 신발을 만들어 버리겠다.'),
(30243, 0, 10, '확, 그냥!'),
(30243, 0, 11, '머리카락으로 신발을 만들어 버리겠다.'),
(30271, 0, 0, '경비병!'),
(30274, 0, 0, '감사합니다. 안녕히 가십시오, $c님. 저는 은빛십자군 선봉기지로 돌아가야 합니다.'),
(30292, 0, 0, '이 곰은 옆구리가 딱딱하게 얼었습니다... 다시 시도해 보십시오.'),
(30299, 0, 0, '내가 네 놈에게 아무런 제재도 하지 않고 터벅터벅 걸어와서 폭풍의 심장을 넙죽 내 줄 거라 생각하진 않겠지?'),
(30299, 1, 0, '네놈이 발두란을 쓰러뜨렸다고 해서 내가 거대괴수를 완성하지 못할 거란 생각은 마라.'),
(30313, 0, 0, '발명의 신전 분석을 시작합니다.'),
(30313, 1, 0, '발명의 신전은 손상되지 않은 것으로 확인되었습니다.'),
(30313, 2, 0, '기계노움 수행원들 사이에 싸움이 있었던 것으로 보입니다. 수행원들이 한구석에 어지러이 쌓여 있습니다.'),
(30313, 3, 0, '남아 있는 기계노움 수호자들은 알 수 없는 성분에 오염되었습니다.'),
(30313, 4, 0, '감시자 미미르는 더는 존재하지 않는 것으로 확인되었습니다. 분석을 종료합니다.'),
(30313, 5, 0, '겨울의 신전 분석을 시작합니다.'),
(30313, 6, 0, '겨울의 신전은 손상되지 않은 것으로 확인되었습니다.'),
(30313, 7, 0, '신전의 수호자들이 사망한 것으로 확인되었습니다. 유황 냄새가 나는 것으로 보아 불 속성을 지닌 상대에게 당한 것으로 판단됩니다.'),
(30313, 8, 0, '기존에 신전에서 관찰되던 추위 변화는 사라졌습니다.'),
(30313, 9, 0, '감시자 호디르가 더는 존재하지 않는 것으로 확인되었습니다. 분석을 종료합니다.'),
(30313, 10, 0, '생명의 신전 분석을 시작합니다.'),
(30313, 11, 0, '생명의 신전은 심하게 파손되어 복구 불능으로 확인되었습니다.'),
(30313, 12, 0, '치열한 전투가 벌어졌음을 보여주는 증거가 발견되었습니다. 감시자 프레이야의 상대는 프레이야와 비슷한 몸집과 힘을 지녔던 것으로 추정됩니다.'),
(30313, 13, 0, '신전의 수호자들이 더는 존재하지 않습니다. 신전에서 자라던 식물들은 죽었습니다.'),
(30313, 14, 0, '감시자 프레이야가 더는 존재하지 않는 것으로 확인되었습니다. 분석을 종료합니다.'),
(30313, 15, 0, '질서의 신전 분석을 시작합니다.'),
(30313, 16, 0, '질서의 신전은 손상되지 않은 것으로 확인되었습니다.'),
(30313, 17, 0, '전투의 흔적이 보이지 않습니다. 수호자가 존재하지 않습니다.'),
(30313, 18, 0, '감시자 티르가 더는 존재하지 않는 것으로 확인되었습니다. 분석을 종료합니다.'),
(30331, 0, 0, '잠깐 기다려라, 작은 $r|1이여;여;.'),
(30331, 1, 0, '토림! 나와라, 모습을 드러내란 말이다!'),
(30331, 2, 0, '그대의 $r의 공헌이 수준을 넘어섰다, 폭풍군주여. $g그:그녀;의 공헌은 우리 백성의 마음을 누그러트리는 데 일조했다.'),
(30331, 3, 0, '강대한 토림에게서 이런 겸허한 말을 들어본 적이 없군. 그대가 한 말을 던 니펠렘에 전하겠다.'),
(30331, 4, 0, '이로써 내 백성이 그 어두운 나날에 벌어진 일들을 용서하였다. 그들은 다시 그 일에 대해서 언급하지 않을 거다.'),
(30331, 5, 0, '다시 다져진 우리 친선을 알리는 의미로 그대의 물건인 것을 돌려 주겠다...'),
(30331, 6, 0, '거대한 폭발이 그 지역을 뒤덮었을 때, 내 아버지께서는 우리 적의 손에 넘어가지 않도록 그 거대한 망치에 룬 마법을 시전하셨다. 그분이 행하신 마지막 일이셨지...'),
(30331, 7, 0, '강대한 토림이여, 우린 그대의 곁에서 싸울 기회를 기꺼이 받아들이는 바이다.'),
(30331, 8, 0, '던 니펠렘으로 돌아가야만 한다. 폭풍군주여, 우린 곧 다시 만날 것이다.'),
(30344, 0, 0, '발사! 발사!'),
(30344, 1, 0, '어서 승선하라! 여기에서 늑장부려서는 안 된다! 이쪽 산 전체가 언제 무너질지 아무도 모른다.'),
(30377, 0, 0, '대영주님께서 상대하시는 자는 가장 교활하고 지능적이며 무자비한 마음을 지닌 존재입니다.'),
(30377, 1, 0, '리치 왕은 여태까지 상대하셨던 적과 다릅니다, 대영주님. 비록 희망의 빛 예배당의 신성한 땅에서는 물리치셨지만, 지금은 리치 왕의 영지 안이란 말입니다.'),
(30377, 2, 0, '이기지 못할 겁니다. 이런 식으로는요...'),
(30377, 3, 0, '아무것도요. 빛에 구속된 이상 대영주님께서 하실 수 있는 일은 없습니다. 성스러운 빛이 완전히 조종하고 있기 때문에, 그 고결함으로 꼼짝할 수 없으실 겁니다.'),
(30377, 4, 0, '%s|1이;가; 고개를 젓습니다.'),
(30377, 5, 0, '저 들판을 보십시오, 대영주님. 리치 왕은 대영주님께서 전진하지 못하도록 막아선 데다가 우위까지 점하지 않았습니까!'),
(30377, 6, 0, '대영주님께서 만들어낸 그 틈은 열리자마자 네루비안 거미줄로 막혀버렸고 말입니다.'),
(30377, 7, 0, '대영주님의 병사들을 메아리 골짜기에서 포격을 막아내는 인간 방패로 이용하기에 리치 왕의 군대는 아무런 방해도 받지 않고 기지로 공격해 오는 상황입니다.'),
(30377, 8, 0, '리치 왕은 대영주님의 한도가 무엇인지 압니다. 부하를 향해 발포할 수 없는 분임을 알지요. 이해가 안 가십니까? 리치 왕에게는 한도가 없습니다. 어떤 것에도 구속받지 않는단 말입니다.'),
(30377, 9, 0, '그런 생각 때문에 패하신 겁니다, 대영주님.'),
(30381, 0, 0, '그런데 자네를 거의 기억하지 못하는군. $n|1은;는; 북풍에 맞서 용감하게 싸워 자네를 지켰었네.'),
(30381, 1, 0, '자네가 바람과 맞서 싸웠던 일은 벌써 수백 년도 더 된 일일세, 스톰후프. 자네가 그 바람을 약하게 한 덕분에 내내 잠잠했었지.'),
(30381, 2, 0, '하지만, 북풍은 그리 호락호락 패배를 인정하지 않았다네. 그 대신에 자네 기억을, 고향을 파괴하는 것이 최고의 복수라 생각하고 때를 기다리며 힘을 모았지.'),
(30381, 3, 0, '그 바람은 하수인들을 보내 자네 종족에 전해 내려오는 이야기를 바꿔버리고 명예롭게 죽어간 자들의 영혼까지 파괴하면서 이곳의 역사를 왜곡했다네.'),
(30381, 4, 0, '만약 $n|1과;와; 북풍이 역사적으로 그 근원을 어떻게 타락시켰는지 즉, 자네가 예전에 치러냈던 그 전투를 추적하지 않았더라면 바람이 계획한 대로 되었을 걸세.'),
(30381, 5, 0, '내 도움을 받아, $n|1은;는; 자네가 싸웠던 그때로 시간 여행을 떠나서 역사가 올바르게 놓이도록 했다네. 북풍은 운명을 봉인 당했고, 자네의 이야기는 원래대로 되살려졌지.'),
(30381, 6, 0, '편히 쉬게나, 영웅이여.'),
(30381, 7, 0, '전혀 옳지 않아, $n. 바람의 조련사 바라가 해준 이야기에 따르면 스톰후프는 악당이 아닌 영웅이었네.'),
(30381, 8, 0, '북풍은 예로부터 타운카의 적이었네. 그는 정령의 군주이자 부족민의 목숨을 오랫동안 앗아간 존재라네.'),
(30381, 9, 0, '그들은 북풍에 굴하기는커녕 죽음을 택했을 걸세. 뭔가 잘못되었어.'),
(30381, 10, 0, '가르침의 망치라...'),
(30381, 11, 0, '더욱 의심스러워지는군. 시간의 실마리가 꼬이며 잘못된 무늬를 만들어내 버렸어. 하지만 어떻게 말인가?'),
(30381, 12, 0, '누군가가 스톰후프와 툰카로 야영지 전사들의 실제 역사를 왜곡한 것이 틀림없네. 하지만 대체 누가 그런 짓을?');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(30381, 13, 0, '아니다! 역사 속에 울리는 진정한 외침이 승리하리라. 우리는 네놈이 파괴한 것을 모두 원래대로 되돌릴 것이다!'),
(30381, 14, 0, '$n|1이여;여;, 북풍이 시간을 왜곡하기 시작한 시간대를 서둘러 찾아야 하네. 그래야만 북풍을 물리치고 시간을 바로잡을 수 있네.'),
(30388, 0, 0, '그 뿔! 그놈이 약해졌을 때 그 뿔을 사용하시오!'),
(30388, 1, 0, '신전 중앙으로 가서 자연 격노의 뿔피리를 사용하십시오!'),
(30390, 0, 0, '제왕 요쿰, 날 소환한 것인가?'),
(30390, 1, 0, '요쿰, 아른그림의 아들이여. 이곳에서 내가 행한 일들에 대해서 항상 후회했었다. 비탄에 잠긴 채 나는 나와 가장 가까운 자들에게 막대한 피해를 불러왔지.'),
(30390, 2, 0, '내가 그대와 그대의 백성에게 불러들인 고통을 용서해 주기를 청하고 싶도다.'),
(30390, 3, 0, '크롤미르로군... 요쿰, 고맙도다. 이 망치가 아직도 남아 있으리라 감히 기대하지 않았다. 다시 한번 영광스러운 전투에 나서게 되리라!'),
(30395, 0, 0, '나의 형제 스톰후프는 나보다 훨씬 위대한 전사였네. 내가 부족장이 되기 위한 훈련을 받는 동안 그는 더욱 중대한 임무를 준비했지.'),
(30395, 1, 0, '그런데 어째서 위험에 빠지게 된 거지? 그는 그저 부족의 골칫거리인 정령을 지배할 힘을 얻으려 한 것뿐이라네.'),
(30395, 2, 0, '그는 어떤 뿔피리를 찾으려 했던 것 같네. 오랜 기간 마을을 떠나 그 유물을 찾으러 다녔지.'),
(30395, 3, 0, '그가 뿔피리를 손에 얻자 무서운 적이 그를 추격하기 시작했는데... 기억이 나질 않는군... 그다음에... 무슨 일이 일어났는지 말이야.'),
(30395, 4, 0, '마치 내 기억이 안갯속에 가려진 것 같다네. 그에게 무슨 일이 있었는지조차 생각나질 않아. 이것이 혹시 그가 위험에 처한 이유인가?'),
(30395, 5, 0, '아마도 묘지에서 일어난 문제와 관련이 있는 게 틀림없네. 주위를 둘러보게, $n. 저들이 보이는가?'),
(30395, 6, 0, '그래, 잘못은 그들에게 있지만 나에겐 그를 막을 힘이 없다네. 툰카로 주민에게 경고해주겠나, 이방인이여? 그들의 선조와 과거가 위험에 처했다고 말이야.'),
(30403, 0, 0, '일단 네르겔드가 되면, 썩어가는 살덩이는 생명을 얻는다.'),
(30403, 1, 0, '%s|1이;가; 산산조각이 납니다.'),
(30404, 0, 0, '감히 어떤 녀석이냐?! 가만두지 않을 테다. 네 녀석을 잡으러 가는 데 네르겔드를 파괴해야 한다고 해도 말이야!'),
(30404, 1, 0, '이제 악몽이 현실이 되었지. 공포의 박사가 왔다. 너희를 두려움에 떨게 하고 온 세상을 무릎 꿇리리라. 그리고 나는... 아무것도 느끼지 않지.'),
(30404, 2, 0, '나는 다시 일어날 것이며, 그때 모든 것을 복수하리라!'),
(30407, 0, 0, '여기서 빨리 나갑시다! 서두르십시오!'),
(30407, 1, 0, '좀 더 서두르십시오, 영웅이여! 우리는 은빛십자군 선봉기지로 돌아가서 공격이 임박했다고 경고해야 합니다!'),
(30407, 1, 1, '적군이 수백 명은 있습니다! 어쩌면 수천 명일 수도 있습니다! 당장에라도 공격해올지 모릅니다! 확실합니다!'),
(30407, 1, 2, '당신이 함께 와주시지 않았다면 전 분명히 죽은 목숨이었을 겁니다!'),
(30407, 1, 3, '저들은 엄청난 공격을 하려고 계획하고 있습니다! 폴드링 대영주님께 경고해야 합니다!'),
(30407, 2, 0, '고맙습니다, 영웅이여.'),
(30407, 2, 1, '감사합니다. 하지만, 이 곤란한 상황을 완전히 벗어난 것은 아닙니다!'),
(30409, 0, 0, '박사님의 계획을 캐내러 왔구나! 죽음이나 캐내 가거라!'),
(30409, 1, 0, '박사님께서는 전신이 거의 다 바르굴인 살덩이 거인 네르겔드를 만드는 계획을 내게 맡기셨다! 네르겔드는 네 한심한 병력을 끝장내도록 만들어질 피조물 군단과 살덩이 거인 무리 전체를 통틀어 가장 강력한 존재일 것이다!'),
(30449, 0, 0, '네놈들 따위 겁낼 줄 아느냐... 비천한 것들! 어디 한번 덤벼봐라!'),
(30449, 1, 0, '싸움을 걸 줄만 알고 싸울 줄은 모르는군!'),
(30449, 1, 1, '하... 그 정도밖에 못 하겠나?'),
(30449, 2, 0, '난... 더 싸울 수... 있는데...'),
(30449, 3, 0, '네놈들 무기로 이빨이나 쑤셔야겠다.'),
(30449, 4, 0, '아버지 말씀 틀린 게 하나도 없어, 살타리온. 넌 약해빠졌어!'),
(30449, 5, 0, '교활한 녀석들 같으니! 나라고 계략이 없는 줄 아느냐...'),
(30449, 5, 1, '너희와 달리 나는 다재다능하다!'),
(30449, 6, 0, '네놈들 따위 겁낼 줄 아느냐... 비천한 것들! 어디 한번 덤벼봐라!'),
(30449, 7, 0, '베스페론의 신도가 황혼에서 나타납니다!'),
(30451, 0, 0, '난 두렵지 않다! 특히 너희 같은 것들은!'),
(30451, 1, 0, '변변치 않은 것들.'),
(30451, 1, 1, '보잘것없는 저항이로군...'),
(30451, 2, 0, '나처럼 고귀한 몸이... 어떻게... 이렇게...'),
(30451, 3, 0, '너흰... 너무나도 쉬워!'),
(30451, 4, 0, '불쌍히 여겨주마, 살타리온. 이번 한 번만이다.'),
(30451, 5, 0, '아버지의 이름으로.'),
(30451, 5, 1, '무릎을 꿇어라!'),
(30451, 6, 0, '%s|1이;가; 황혼의 차원문을 엽니다!'),
(30451, 7, 0, '샤드론의 신도가 황혼에서 나타납니다!'),
(30461, 0, 0, '%s|1이;가; 둥지 위로 내려앉으며 큰 소리로 울부짖습니다.'),
(30462, 0, 0, '아래를 조심하게!'),
(30462, 1, 0, '진정하거라, 아가야! 네 예전 주인을 알아보지 못하겠느냐?'),
(30462, 2, 0, '폭풍의 신전에서 다시 보자꾸나. 베라누스를 다시 길들여야 할 것 같구나.'),
(30474, 0, 0, '어리석기는! 네놈은 절대로 나를 이길 수 없다!'),
(30474, 1, 0, '네놈이 우리에게 자연 격노의 뿔피리를 사용하도록 놔두지 않겠다! 죽어라, 애송이!'),
(30475, 0, 0, '베소드의 검이라고?!! 아주 잘했다, $r. 네 도전을 받아들이겠노라. 그전에 먼저, 내 용사와 싸워 이겨야 한다. 볼구르! 와서 이 벌레를 뭉개버려라!'),
(30475, 1, 0, '브리타, 이 빈약한 $c|1을;를; 벌집으로 만들어 줘라!'),
(30475, 2, 0, '내 용사들은 꺾었는지도 모르겠다. 그러나 나는 완전히 다르다.'),
(30475, 3, 0, '빨리 죽게 해달라고 빌기나 해라.'),
(30479, 0, 0, '여기는 툰카로 야영지군요. 우리 형제가 다스리는 마을이지만, 당... 당신은 기억에 없습니다.'),
(30479, 1, 0, '북풍 말입니까? 그것이 우리 종족을 아직도 괴롭힙니까?'),
(30479, 2, 0, '저와 저희 마을을 대신해서 두 분께 감사를 드려야겠습니다. 두 분께서 어떤 일을 해내셨는지 많은 이들이 모를 테지만 말입니다.'),
(30479, 3, 0, '저는 여기에 남을 수 없습니다. 제가 속한 무덤으로 돌아가야 하지만, 조상님들을 다시 뵌다면, 그대의 이야기를 꼭 전하겠습니다.'),
(30523, 0, 0, '안돼애애애애애애애애애애애애!'),
(30549, 0, 0, '죽고 싶나?'),
(30549, 0, 1, '아무도 못 나간다!'),
(30549, 0, 2, '꼼짝 마라!'),
(30549, 1, 0, '잡담은 그만! 어서 덤벼 봐라. 모두 박살을 내주마.'),
(30549, 1, 1, '화를 다스려라. 분노를 억제하라. 머지않아 마음껏 좌절하게 해주마.'),
(30549, 1, 2, '삶은 무의미하다. 진정한 시험은 죽음과 함께 시작되지!'),
(30549, 2, 0, '스컬지의 힘을 숭배하라!'),
(30549, 3, 0, '죽어서도 평화는 없을 것이다.'),
(30549, 3, 1, '주인님의 뜻이다.'),
(30549, 4, 0, '죽음 따위가... 날 막을 순 없다.'),
(30550, 0, 0, '괜한 애쓰지 마라, 타우렌 애송이. 스톰후프도 네놈도, 그리고 네 친구 어느 누구도 나를 가로막을 수 없다.'),
(30550, 1, 0, '지금도 내 힘은 강해지고 있다. 오랫동안 복수를 완성할 날만을 기다려 왔다.'),
(30550, 2, 0, '스톰후프와 그의 일족들은 역사에서 완전히 사라지고, 이 땅은 원래 주인에게 되돌아갈 것이다!'),
(30632, 0, 0, '머리카락으로 신발을 만들어 버리겠다.'),
(30632, 0, 1, '구워 줄까!'),
(30632, 0, 2, '하라크 폴른!'),
(30632, 0, 3, '구워 줄까!'),
(30632, 0, 4, '덜 떨어진 놈!'),
(30632, 0, 5, '웬 놈이냐!'),
(30725, 0, 0, '죽고 싶어서 왔냐!'),
(30725, 0, 1, '웬 놈이냐!'),
(30725, 0, 2, '머리카락으로 신발을 만들어 버리겠다.'),
(30824, 0, 0, '발사! 발사!'),
(30824, 1, 0, '승선하라, 당장! 언제 이쪽 산 전체가 무너져내릴지 모른다.'),
(30835, 0, 0, '주인님.'),
(30835, 1, 0, '요툰하임에서 소식이 들어왔습니다. 수면의 감시자들이 상당히 중요한 인물을 발견한 모양입니다.'),
(30835, 2, 0, '이교도가 정신없이 말을 쏟아냅니다.'),
(30835, 3, 0, '생김새요? 글쎄요, 브리쿨처럼 보이던데요. 저도 아직 본 적은 없어서요. 어둠의 무기고 때 이후로 통...'),
(30835, 4, 0, '이름이요? 아, 맞다. 그 이름이... 이스칼더였던 것 같은데요.'),
(30835, 5, 0, '쏜살처럼 다녀오겠습니다, 주인님.'),
(30838, 1, 1, '죽음 그 자체에 도전하겠다는 건가! 그렇다면 와라. 모그레인의 힘을 보여주마!'),
(30838, 2, 1, '메아리 골짜기에서 보자. 고생해라, 동지.'),
(30840, 1, 1, '내 작은 친구에게 인사해라!'),
(30840, 2, 2, '일어나라, 말랑아!'),
(30840, 3, 3, '여기 일은 다 끝났으니, 가보겠다.'),
(30884, 1, 1, '이스칼더입니다! 서둘러 해골 마녀의 아뮬렛을 사용하십시오!'),
(30891, 0, 0, '축복받은 십자군 깃발이 세워졌습니다.\n모든 공격으로부터 깃발을 보호해야 합니다.'),
(30899, 0, 0, '경고. 식별할 수 없는 생명체입니다. 기록 처리를 중지합니다. 혼선이 계속되면 지정된 작업을 실행합니다.'),
(30899, 1, 0, '생명체 추방 완료.'),
(30899, 2, 0, '위협 지수가 높습니다. 공허 분석을 종료합니다. 안전성 검증을 시작합니다.'),
(30899, 3, 0, '경고. 보안 잠금장치가 비활성화되었습니다. 기억 장치 소거를 시작합...'),
(30899, 4, 0, '정상 작동 중입니다. 생명체가 식별되었습니다. 환영합니다, 브란브론짱 님. 질문은?'),
(30899, 5, 0, '선사 자료 검색 중... 완료. 최초에 토석인이 창조된 이유는,'),
(30899, 6, 0, '검색 중... 아제로스는 초기 발전 단계에서 기생성 숙주 잠식 공생체에 감염되어 질환을 앓았습니다.'),
(30899, 7, 0, '지시어. 고대 신. 고대 신들은 동화 작업을 용이하게 할 목적으로, 토석인을 포함한 모든 생명체에 무력화 작업을 수행했습니다. 이 모형 불안정화 작업을 "육체의 저주"라고 부릅니다. 불안정화 작업의 효과는 시간이 지날수록 증대되었습니다.'),
(30899, 8, 0, '알겠습니다, 브란브론짱 님. 열람을 종료합니다.'),
(30924, 0, 0, '$n, 이제 나와 싸우세요! 이스칼더를 죽이세요!'),
(30994, 0, 0, '어떤 처방도 듣지 않습니다. 도시 전체가 병들었어요...'),
(30994, 0, 1, '음식이 잘못되었다는 소문 때문에 공황에 빠진 병사들이 늘어갑니다. 이웃들은 음식에 독을 넣었다며 서로 고발하고 있습니다. 도시 전체가 혼란에 빠질 것입니다!'),
(30994, 0, 2, '하나둘씩 모두 앓아눕고 있습니다. 이건 전염병입니다!'),
(30994, 1, 0, '지금 저도 몸이 안 좋은데, 스트레스성 위궤양이기를 기도합니다...'),
(30994, 1, 1, '전체적으로 이런 위기 상황에 빠진 도시를 제가 어떻게든 도울 방법이 없을까요?'),
(30994, 1, 2, '정말 어찌할 바를 모르겠습니다. 평범한 사람이 이런 재난 상황에서 무엇을 할 수 있겠습니까?'),
(31003, 0, 0, '빛이시여! 이 저주 받은 괴물들! 놈들이 우리 형제들에게 한 짓을 보게!'),
(31003, 1, 0, '다 불태워라, 형제들이여. 모조리 다.'),
(31003, 2, 0, '올 테면 와 보라지. 죗값을 단단히 치르게 해줄 테니!'),
(31003, 3, 0, '우린 해냈네, 친구들! 봉우리에서 스컬지를 몰아냈다고! 서둘러 구스타프 신부에게 가서 이 좋은 소식을 전해 주게! 우린 여기서 정비를 하겠네. 어서 떠나게!'),
(31013, 0, 0, '한 놈도 살려두지 마라!'),
(31013, 1, 0, '내 끔찍한 피조물 앞에서 몸서리쳐라!'),
(31013, 2, 0, '맘껏 즐겨라, 나의 자식들아! 산 자의 육신을 맘껏 즐겨라!'),
(31013, 3, 0, '무의미한 저항은 그만두고, 내게 영혼을 바쳐라!'),
(31036, 0, 0, '첫 번째 호드 경비탑이 무너졌다! 세 개를 모두 무너뜨리면 적은 금세 퇴각할 것이다!'),
(31036, 1, 0, '두 번째 경비탑이 무너졌다! 마지막 경비탑을 파괴하면 적은 금세 퇴각할 것이다!'),
(31036, 2, 0, '호드 경비탑이 모두 무너졌다! 이제 놈들은 힘을 잃었다. 잔병을 처리해라!'),
(31036, 3, 0, '동물 같은 호드 녀석들에게 자비를 베풀지 마시오, $n!'),
(31057, 0, 0, '안녕하십니까. 프라스 샤비 주인님께서는 출타 중이십니다. 샤비의 최고급 담배를 맛보시려면 내일 다시 와주시기 바랍니다! 삐빅!'),
(31091, 0, 0, '첫 번째 얼라이언스 경비탑이 무너졌다! 세 개를 모두 무너뜨리면 적은 금세 퇴각할 것이다!'),
(31091, 1, 0, '록타르! 두 번째 경비탑이 무너졌다! 마지막 경비탑을 파괴하면 적은 금세 퇴각할 것이다!'),
(31091, 2, 0, '얼라이언스 경비탑이 모두 무너졌다! 이제 놈들은 힘을 잃었다. 잔병을 처리해라!'),
(31091, 3, 0, '동물 같은 호드 녀석들에게 자비를 베풀지 마시오, $n!'),
(31108, 0, 0, '영원의 불씨를 회수하는 호드를 저지하세요, $n. 전투가 다시 재개되었을 때 그들이 우위를 선점하는 걸 감당할 순 없습니다.'),
(31109, 0, 0, '저들의 더러운 전쟁 기계를 파괴하세요, $n!'),
(31125, 0, 0, '%s|1이;가; 분노에 휩싸여 광폭해집니다!'),
(31125, 1, 0, '%s|1이;가; $n에게 돌진합니다!'),
(31126, 0, 0, '아아, 마침내 오셨군요, 아서스 왕자님. 딱 적절한 때에 와주셔서 기쁩니다.'),
(31126, 1, 0, '이해하려고 애쓸 것 없다, 아서스. 너는 그저 죽어주면 그만이야.'),
(31134, 4, 0, '훌륭한 방어였다만, 도시를 지키게 둘 수는 없지! 내 직접 말리고스 님의 의지를 실현하리라!'),
(31134, 5, 0, '훌륭한 방어였다만, 도시를 지키게 둘 수는 없지! 내 직접 말리고스 님의 의지를 실현하리라!'),
(31134, 6, 0, '훌륭한 방어였다만, 도시를 지키게 둘 수는 없지! 내 직접 말리고스 님의 의지를 실현하리라!'),
(31135, 3, 3, '발할라스의 전사한 영웅들이 땅속에서 일어나 다시 전투를 벌이려고 합니다!'),
(31135, 7, 7, '어둠의 지배자 키트릭스가 남동쪽으로부터 발할라스로 오고 있습니다!'),
(31135, 10, 10, '발할라스를 맴돌던 시그리드 아이스본이 복수의 대상을 찾아 접근합니다!'),
(31135, 14, 14, '남쪽에서 육중한 소리가 들리고, 살육자의 냄새가 점점 진해집니다!'),
(31135, 18, 18, '남동쪽을 바라보자 바나호그 영주가 모습을 드러냅니다.'),
(31135, 23, 23, '마치 마법처럼, 산도발 공작이 발할라스에 홀연히 나타납니다!'),
(31222, 0, 0, '전투가 끝나면, 너희를 아졸네룹의 성벽에 줄줄이 걸어 놓겠다!'),
(31235, 0, 0, '빛이여, 다시 한 번 기회를 허락해 주심에 감사합니다. 감사합니다, $n|1이여;여;.'),
(31235, 1, 0, '그대의 도움이 없었다면 리치 왕이 만들어 낸 끔찍한 괴물들 틈에서 영원히 죽지 못하는 저주받은 삶을 살았을 것입니다.'),
(31235, 2, 0, '나중에 다시 정식으로 감사드리겠습니다. 지금은 전투에 집중하십시오!'),
(31237, 0, 0, '왜 그러셨어요! 그가 싫어할 거예요.'),
(31254, 0, 0, '언데드들이 공격한다!'),
(31254, 0, 1, '소문이 사실이었어! 아서스 왕자는 미쳐버린 거야!'),
(31258, 0, 0, '뼈를 알뜰히 매만져주마...'),
(31258, 0, 1, '구워 줄까!'),
(31277, 0, 0, '그만! 너희 같은 버러지는 이 신성한 장소에 들어올 자격조차 없다! 명예는 내팽개쳐 버렸군! 나아지는 모습도 없어!'),
(31277, 1, 0, '내 공격을 받고 죽어라, 이 겁쟁이들아!'),
(31277, 2, 0, '하라크 폴른!'),
(31279, 0, 0, '빛의 심판을 받을지어다!'),
(31279, 0, 1, '내 죽는 한이 있어도, 절대 네놈들에게 잡혀가진 않을 것이다!'),
(31279, 1, 0, '어려울 때 도와주셔서 감사합니다, $n. 빛의 가호가 함께하길.'),
(31279, 2, 0, '이곳은 이제 지긋지긋합니다. 어서 출발합시다.'),
(31279, 3, 0, '당신은 형제들에게 제가 살아있음을 알려야 합니다.'),
(31279, 4, 0, '제 목숨을 구해주셔서 감사합니다. 동료들에게 돌아가 당신의 용맹함을 널리 알리겠습니다. 온 힘을 다해 스컬지와 맞서 주십시오. 우리들이 곁에서 응원하겠습니다.'),
(31301, 0, 0, '내가 물러날 거라 감히 생각한 건가? 내 계획을 무너뜨렸다고?'),
(31301, 1, 0, '그래 봐야 아무 소용없는 일이다!'),
(31301, 2, 0, '너의 부질없는 저항은 파멸을 앞당겼을 뿐이다.'),
(31301, 3, 0, '그렇게 아등바등 지칠 때까지 지껄여 봐라. 그래 봐야 넌 내 것이다. 모르비두스가 네 죽음의 전령이 될 것이다!'),
(31301, 4, 0, '모르비두스, 왕의 말을 거역하는 자의 최후가 어떤 것인지 보여줘라.'),
(31306, 0, 0, '칠흑의 기사단이여, 전투를 준비하라!'),
(31397, 0, 0, '아하하하하... 당신도 곧 우리 일원이 될 거야!'),
(31397, 0, 1, '난 떠나기 싫어! 여기 있을 거야!'),
(31397, 0, 2, '아니! 그렇지 않아! 내 머릿속의 목소리는 아름답다고!'),
(31397, 0, 3, '제 생명은 당신의 것입니다!'),
(31397, 0, 4, '지금 가고 있습니다, 주인님!'),
(31426, 0, 0, '경비병!'),
(31428, 0, 0, '언젠가 네 행동을 후회할 날이 올 것이다! 은빛십자군을 위하여!'),
(31773, 0, 0, '역병 가마솥이 부글부글 끓기 시작합니다!'),
(31810, 0, 0, '좋습니다. 이 쐐기돌을 완성할 수 있을지 보죠.'),
(31810, 1, 0, '쐐기돌이 완성되었습니다! 우리가 해냈군요, $n!'),
(31810, 2, 0, '울두아르의 저장고에 어떤 비밀이 숨겨져 있을지 누가 알겠습니까? 전 이제 그 비밀을 파헤치러 출발합니다. 다시 한번 도와줘서 고맙다고 말하고 싶군요. 당신의 도움이 없었다면 쐐기돌을 찾는 일만 계속하고 있었을 겁니다.'),
(31814, 0, 0, '브란 브론즈비어드, 환영한다. 난 이 신전의 수호자가 남긴 잔재이다.'),
(31814, 1, 0, '그대는 탐험가로서나 지식의 탐구자로서의 자질을 증명했다.'),
(31814, 2, 0, '또한 토석인들에게 확고한 동맹으로서의 위치를 계속 지켜주었다.'),
(31814, 3, 0, '그대와 그대의 친구는 전투 기술에서나 쐐기돌을 얻고자 하는 목적에서 그 자질을 증명해 보였다.'),
(31814, 4, 0, '그대의 동기는 순수하다. 쐐기돌 조각은 합쳐지리라. 울두아르로 가서 그대의 질문에 대한 해답을 구하라, 브란 브론즈비어드.'),
(32149, 0, 0, '끔찍했습니다... 꿈에서 저는 친구들의 적이 되어 싸웠습니다.'),
(32149, 0, 1, '너무 지쳤습니다. 잠시 쉬도록 해주십시오.'),
(32149, 0, 2, '사람들의 비명소리는 이제 들리지 않는군요. 이제 전부 끝난 겁니까?'),
(32149, 0, 3, '드디어... 쉴 수 있겠구나.'),
(32149, 0, 4, '마침내, 악몽이 끝난 겁니까?'),
(32236, 0, 0, '이 야릇한 느낌은 뭐지. 으잉?!'),
(32236, 0, 1, '누구야, 어떤 겁 없는 녀석이 나한테 수정구를 던져?'),
(32236, 0, 2, '뭐야?!'),
(32236, 1, 0, '내가 한 게 아니야. 이건 모함이라고. 제발 절 놓지 마세요!'),
(32236, 1, 1, '오해야. 나야, 나. 정복자!'),
(32236, 1, 2, '안 돼애애애애!'),
(32273, 0, 0, '감히 우리 일을 방해하다니!'),
(32273, 1, 0, '이제... 모두 끝났다...'),
(32273, 2, 0, '모든 과정이 끝났다! 내 일은 여기서 끝이다.'),
(32414, 0, 0, '저희를 도와주러 오셨습니까?'),
(32442, 0, 0, '역병 가마솥이 부글부글 끓기 시작합니다!'),
(32443, 0, 0, '일어나라, 신드라고사! 일어나 서리고룡족을 이끌고 전쟁터로 향하라!'),
(32445, 0, 0, '가마솥에서 무언가 떠오릅니다!'),
(32445, 1, 0, '가마솥이 계속 끓습니다...'),
(32445, 2, 0, '역병이 중화되었습니다.'),
(32576, 0, 0, '키잡이가 네놈을 맞이해주마!'),
(32576, 1, 0, '이 오라부스가 상대해주마, 어리석은 것!'),
(32588, 0, 0, '죽을 준비나 해라!'),
(32663, 0, 0, '이 길이 맞습니까, 친구?'),
(32663, 0, 1, '저 술맛처럼 끝내주는 건 세상 어디에도 없지요.'),
(32663, 0, 2, '이제 됐습니다, 형제여!'),
(32663, 0, 3, '헤헤헤! 이거 정말 재미있을 겁니다, 친구!'),
(32663, 0, 4, '오늘은 트롤 형제들이 아주 재밌어하겠어요, 친구!'),
(32663, 0, 5, '트롤식 술래잡기를 할 시간이군요, 친구!'),
(32663, 0, 6, '<킁킁> 냄새가 나는데요, 친구.'),
(32663, 0, 7, '아니, 아닙니다, 친구. 여기에는 트롤이 없어요...'),
(32663, 0, 8, '좋습니다, 친구. 트롤 형제들 근처에 가면 말해 주세요.'),
(32663, 0, 9, '이봐요! 절 트롤 형제들한테 데려다 주십시오!'),
(32736, 0, 0, '여기 경치가 끝내주는군요!'),
(32736, 0, 1, '가벼운 깃털을 집에 놔두고 와서 너무 아쉽습니다... 여기서 저속 낙하를 하면 정말 멋질 텐데요!'),
(32739, 0, 0, '여기 경치가 끝내주는군요!'),
(32739, 0, 1, '가벼운 깃털을 집에 놔두고 와서 너무 아쉽습니다... 여기서 저속 낙하를 하면 정말 멋질 텐데요!'),
(32741, 0, 0, '여기 경치가 끝내주는군요!'),
(32741, 0, 1, '가벼운 깃털을 집에 놔두고 와서 너무 아쉽습니다... 여기서 저속 낙하를 하면 정말 멋질 텐데요!'),
(32845, 0, 0, '침입자는 쓴맛을 보게 될 게다!'),
(32845, 1, 0, '비극이로군. 그 먼 길을 왔건만 패배하다니.'),
(32845, 1, 1, '끝없는 겨울을 맞이해라.'),
(32845, 2, 0, '북극의 바람이 너희를 삼키리라!'),
(32845, 3, 0, '%s|1이;가; 격분하여 포효합니다.'),
(32845, 4, 0, '드디어... 드디어 그의 손아귀를... 벗어나는구나.'),
(32845, 5, 0, '그만! 이제 다 끝이다!'),
(32845, 6, 0, '%s|1이;가; 호디르의 희귀품 보관함을 부숴버립니다!'),
(32845, 7, 0, '%s|1이;가; 순간 빙결을 시전합니다!'),
(32845, 8, 0, '%s|1이;가; 얼음 일격 효과를 얻습니다!'),
(32857, 0, 0, '세상에서 가장 큰 모기건 세상에서 가장 위대한 영웅이건, 너흰 어차피 필멸의 존재야.'),
(32857, 1, 0, '자비로운 죽음을!'),
(32857, 1, 1, '하!'),
(32857, 2, 0, '가만히 서서 빛을 들여다봐라!'),
(32857, 3, 0, '폭풍 구름이 몰려와 너희에게 죽음을 마구 퍼부으리라!'),
(32857, 4, 0, '폭풍의 힘은 죽지 않는다.'),
(32857, 5, 0, '네놈들은 광기의 도가니에 빠져들고 있을 뿐이야!'),
(32857, 6, 0, '무쇠 평의회의 이번 회합은 끝났다!'),
(32857, 7, 0, '%s|1이;가; 과부하되기 시작합니다!'),
(32865, 0, 0, '침입자라니! 감히 내 취미 생활을 방해하는 놈들은 쓴맛을 단단히... 잠깐... 너는...'),
(32865, 1, 0, '네가 기억난다... 산속에서... 하지만... 이게 뭐지? 난 대체...'),
(32865, 2, 0, '물러서지 마라! 놈들을 물리쳐라!'),
(32865, 3, 0, '건방진 젖먹이 같으니... 감히 여기까지 기어올라와 내게 도전해? 내 손으로 쓸어버리겠다!'),
(32865, 4, 0, '싸움을 할 줄은 아느냐?'),
(32865, 4, 1, '형편없군.'),
(32865, 5, 0, '더는 참아줄 수가 없구나!'),
(32865, 6, 0, '실패자! 약골 같으니!'),
(32865, 7, 0, '무기를 거둬라! 내가 졌다!'),
(32865, 8, 0, '악몽에서 막 깨어난 것만 같구나. 하지만 아직 어둠이 채 가시지 않았다.'),
(32865, 9, 0, '시프... 시프가 여기 있었나? 아니... 그녀는 내 형제의 손에 죽었다. 참으로 끔찍한 악몽이었지...'),
(32865, 10, 0, '생각할 시간이 필요하다... 원한다면, 너희의 임무에 힘을 빌려주겠다. 그만큼은 빚을 졌지. 잘 가라.'),
(32865, 11, 0, '이놈! 넌 내 사랑이 아니야! 물러가라, 마귀여!'),
(32865, 12, 0, '울두아르를 덮친 모든 사악함 뒤에는 보이지 않는 손이 있었다. 놈이 내 왕국을 폐허로 만들고, 내 형제를 망치고, 내 아내를 죽였지.'),
(32865, 13, 0, '이제 너희 몫이다, 용사들이여. 우리 모두를 대신해 복수해다오! 너희 앞에 어려운 임무가 놓여 있지만, 내가 최대한 너희를 돕겠노라. 너희는, 승리해야만 한다!'),
(32867, 0, 0, '무쇠 평의회가 그리 쉽게 무너질 것 같으냐, 침입자들아!'),
(32867, 1, 0, '허약하고, 물렁한 놈들!'),
(32867, 1, 1, '살덩이라... 장애일 뿐이지.'),
(32867, 2, 0, '울두아르의 비밀을 찾고 있느냐? 그럼 가져가 봐라!'),
(32867, 3, 0, '내 죽음은 네놈들의 파멸을 앞당길 뿐이다.'),
(32867, 4, 0, '이럴 수가...'),
(32867, 5, 0, '무쇠 평의회의 이번 회합은 끝났다!'),
(32871, 0, 0, '순간이동 완료. 아제로스 행성 분석 시작.'),
(32871, 1, 0, '물러서라, 필멸자여. 나는 싸우러 온 것이 아니다.'),
(32871, 2, 0, '분석 결과 시스템의 손상이 발견된다면, 이 행성을 재창조하는 것이 전 우주를 위하는 길이다. 방해하지 마라.'),
(32871, 3, 0, '너희 행동은 비논리적이다. 이 전투에서 가능한 결말은 모두 계산되었다. 결과와 상관없이 판테온은 관찰자의 전갈을 받을 것이다.'),
(32871, 4, 0, '내 눈을 통해 너희 세상을 보아라. 측정할 수 없이 광활한 우주를... 너희 지성으로는 절대 이해할 수 없다.'),
(32871, 5, 0, '별이 나를 도우러 온다!'),
(32871, 6, 0, '%s|1이;가; 붕괴하는 별을 소환하기 시작합니다!'),
(32871, 7, 0, '우주의 분노를 목격하라!'),
(32871, 8, 0, '%s|1이;가; 대폭발을 시전합니다!'),
(32871, 9, 0, '너희에겐, 시간이 없다.'),
(32871, 10, 0, '%s|1이;가; 우주의 강타를 시전하기 시작합니다!'),
(32871, 11, 0, '창조의 도구를 바라보아라!'),
(32871, 12, 0, '나는 창조주의 불길이 씻어내린 세상을 보았다. 모두 변변히 저항도 못하고 사그라졌지. 너희 필멸자의 심장이 단 한 번 뛸 시간에 전 행성계가 탄생하고 무너졌다. 그러나 그 모든 시간 동안, 나는 공감이란 감정을... 몰랐다. 나는, 아무것도, 느끼지, 못했다. 무수한, 무수한 생명이 꺼졌다. 그들이 모두 너희처럼 강인했더냐? 그들이 모두 너희처럼 삶을 사랑했단 말이냐?'),
(32871, 13, 0, '어쩌면, 너희는 자유의지를 지닌 불완전한 존재이기 때문에... 우주의 절대적인 질서에 맞설 수 있는지도 모르겠다. 티탄의 완벽한 창조물이 스러진 곳에서 너희는 번성하는구나.'),
(32871, 14, 0, '응답 코드를 다시 만들었다. 너희 행성은 유지될 것이다. 이제 나는 내 계산을 믿을 수가 없다.'),
(32871, 15, 0, '신호를 전송할 힘이 없다. 서둘러라... 하늘 가까이에서... 힘이 깃든 장소를... 찾아라.'),
(32871, 16, 0, '내 운명을 걱정하지 마라, 브론젠. 시간 안에 신호를 전송하지 못하면, 재창조가 시작되고 말 것이다. 너희의 세상을... 지켜라...'),
(32871, 17, 0, '분석 완료. 행성 생명 유지 시스템이 부분적으로 손상되었을 뿐 아니라, 행성 수호 장치 대부분이 완전히 손상됐다.'),
(32871, 18, 0, '전송 시작. 응답 코드 오메가. 행성 재창조가 요청되었다.'),
(32871, 19, 0, '잘 가라, 필멸자여. 그토록 결함이 있는 생명체치고 너희는 참으로 용감했다.'),
(32871, 20, 0, '불가피한 죽음이다.'),
(32871, 20, 1, '의무를 다했을 뿐.'),
(32906, 2, 0, '용서해라.'),
(32913, 0, 0, '여긴 필멸자가 있을 곳이 아니다!'),
(32913, 1, 0, '돌아가라! 난 곳으로 돌아가라!'),
(32913, 1, 1, '사라져라!'),
(32913, 2, 0, '프레이야 님! 저들이 당신을 잡으러 갑니다.'),
(32914, 0, 0, '여기가 바로 네놈들의 무덤이다.'),
(32914, 1, 0, '여기가 바로 네놈들의 무덤이다.'),
(32914, 1, 1, '쓰레기 같으니...'),
(32914, 2, 0, '마님, 달아나세요! 참으로 냉혹한 놈들입니다...'),
(32915, 0, 0, '마님, 정원에 적이 침입했습니다!'),
(32915, 1, 0, '비료나 되어라.'),
(32915, 1, 1, '네 몸이 땅을 기름지게 하리라.'),
(32915, 2, 0, '마님, 제가 당하고 말았습니다...'),
(32927, 0, 0, '남김없이 쓸어버려야 속이 시원하겠군.'),
(32927, 1, 0, '시시한 생명이 또 하나 사라졌군.'),
(32927, 1, 1, '불손함의 대가란 이런 것이다.'),
(32927, 2, 0, '해독해 봐라!'),
(32927, 3, 0, '쇄도하는 번개에 맞서 봐라!'),
(32927, 4, 0, '폭풍의 유산은 사라지지 않으리.'),
(32927, 5, 0, '날 쓰러뜨리면 나아질 줄 아느냐? 파멸은 조금도 멀어지지 않았다...'),
(32927, 6, 0, '무쇠 평의회의 이번 회합은 끝났다!'),
(32930, 0, 0, '아무도 못 나간다!'),
(32930, 1, 0, '콜 다리쉬!'),
(32930, 1, 1, '넌 실패했다!'),
(32930, 2, 0, '긁힌 정도지!'),
(32930, 3, 0, '얕은 상처야!'),
(32930, 4, 0, '망각!'),
(32930, 5, 0, '꽉꽉 쥐어짜 주마!'),
(32930, 6, 0, '주인님, 그들이 옵니다...'),
(32930, 7, 0, '아무도 날 이기지 못해!'),
(32930, 8, 0, '콜로간이 바위 손아귀를 시전합니다!'),
