(33113, 0, 0, '적대적인 존재 감지. 위협 수준 평가 체제 가동. 주 목표물과 교전. 위협 수준 재평가까지 30초.'),
(33113, 1, 0, '위협 수준 평가 작업 변경. 목표물의 현재 위협 수준: 0. 새로운 목표물 포착.'),
