(33118, 5, 0, '지옥의 불길에 먹혀 버려라!'),
(33118, 5, 1, '지옥의 불길에 먹혀 버려라!'),
(33118, 6, 0, '이제 끝인 줄 알아라!'),
(33118, 7, 0, '%s|1이;가; 화염 분출을 시전합니다!'),
(33127, 0, 0, '달표범이 나직하게 으르렁거리면서 잠에서 깹니다.'),
(33127, 0, 1, '달표범이 갑자기 잠에서 깨더니 낮은 그르렁소리를 냅니다.'),
(33127, 0, 2, '달표범이 이빨을 드러내고 껑충 뛰어오릅니다.'),
(33127, 0, 3, '달표범이 방해받아 화를 내며 일어납니다.'),
(33176, 0, 0, '이 위에 있는 동안에는 저기 땅에 있는 트롤들 걱정은 하지 마시오. 고대 정령들의 발에 짓밟혀 버릴 테니까.'),
(33186, 0, 0, '%s|1이;가; 완전히 땅에 내려앉았습니다!'),
(33186, 1, 0, '%s|1이;가; 숨을 깊게 들이쉽니다.'),
(33210, 0, 0, '반갑습니다, 용사 여러분! 도저히 저놈을 끌어내릴 수가 없군요. 작살포로 놈을 끌어내리게 좀 도와주세요.'),
(33210, 1, 0, '움직이세요! 오래 붙잡아둘 순 없을 겁니다!'),
(33210, 2, 0, '정신 바짝 차리세요! 곧 땅에서 굴착기가 솟아나 성가신 무쇠 드워프를 쏟아낼 겁니다!'),
(33213, 0, 0, '그리하겠다, $n.'),
(33213, 1, 0, '용사들이여, 겨울의 장막이 너희를 보호하리라!'),
(33233, 0, 0, '작살 포탑이 준비되었습니다!'),
(33235, 0, 0, '무쇠 평의회를 쓰러뜨리고 고대 기록관을 여셨군요! 대단하십니다!'),
(33235, 1, 0, '와... 이런 걸 바로 끝내주는 발견이라고 하죠!'),
(33235, 2, 0, '새로운 명령이다! 별자리 투영관 입구를 냉큼 열어라.'),
(33235, 3, 0, '네 감시자? 인장? 나랑 수수께끼 놀이하자는 거냐, 이 괘씸한 기계야!'),
(33235, 4, 0, '내가 권한을 보여주지, 이 망할 기계야. 자, 여기 노르간논의 쐐기돌이다!'),
(33235, 5, 0, '제가 전에 발견한 티탄의 다른 기록관과 비슷하군요. 음... 더 낡았고... 더 크다는 점만 빼면요.'),
(33235, 6, 0, '잠깐, 이건 뭔가 안 좋아 보이는데! 이 깜빡이는 불빛 옆에, 알갈론이라는 신호는 뭐냐?'),
(33235, 7, 0, '제1관리자? 어디서 들은 말이지... 아! 우리 할아버지의 수염을 걸지! 로켄이 아제로스의 제1관리자야! 로켄이 죽어서 이렇게 된 거라고!'),
(33235, 8, 0, '뭐? 신호를 받는 쪽이 누구지? 그리고 무슨 일이 벌어지나?'),
(33235, 9, 0, '행성 재창조가 뭐야? 알아듣게 말해라, 구닥다리 기계야!'),
(33235, 10, 0, '들었어요, 여러분? 세상이 그냥 끝난대요! 뭐 하는 거야, 이 고물 기계야? 응답 코드 ''알파''를 보내. 다 정상이야! 내가 한잔 살게!'),
(33235, 11, 0, '그럼 알갈론은 어떤 식으로 진단 결과를 내지? 우린 희망이 없는 거냐?'),
(33235, 12, 0, '큰일 났네요. 우리 곧 싸워야 할 것 같습니다.'),
(33235, 13, 0, '그 인장은 어떻게 구하란 말이냐? 감시자한테 가서 좀 달라 그럴까?'),
(33235, 14, 0, '그럼 손상을 되돌리는 방법을 얘기해 주겠군, 그렇지?'),
(33235, 15, 0, '수년 동안 티탄의 전당에서 활보할 순간만을 꿈꿨는데, 티탄의 창조물 때문에 위험해질 줄이야...'),
(33241, 0, 0, '그리하겠다, $n.'),
(33242, 0, 0, '그리하겠다, $n.'),
(33242, 1, 0, '골가네스여, 제게 힘을 주소서! 필멸의 동료에게 번개의 힘을 나눠주소서!'),
(33244, 0, 0, '그리하겠다, $n.'),
(33244, 1, 0, '전투 회로망 강화! 놀라운 속도를 즐기라고!'),
(33271, 0, 0, '너희의 파멸은 새로운 고통의 시대를 열 것이다!'),
(33271, 1, 0, '죽음의 군단과 마주하고는, 살아나갈 수 있을 줄 알았나?'),
