(33288, 1, 0, '광기가 너희를 삼키리라!'),
(33288, 2, 0, '%s의 마음속으로 가는 차원문이 열립니다!'),
(33288, 3, 0, '죽음의 진정한 얼굴을 보아라! 다가오는 종말을 느껴라!'),
(33288, 4, 0, '영원한 고통이 기다린다!'),
(33288, 5, 0, '%s|1이;가; 입을 크게 벌립니다!'),
(33288, 6, 0, '너희 운명이 결정됐다. 너희와, 이 작고 가련한 세상에 사는 모든 것들에게 마침내 종말이 닥친다. 우울위 이피스 할란 가그 에르옹그 위스...'),
