(33293, 0, 0, '새 장난감? 내 거? 이번엔 진짜로 안 망가뜨릴게!'),
(33293, 1, 0, '아, 피곤해. 나 잠깐만 쉬어야지!'),
(33293, 2, 0, '놀 준비 됐다고!'),
(33293, 3, 0, '싫어어어! 싫어, 싫어, 싫어, 싫어, 싫어, 싫어어!'),
(33293, 4, 0, '어... 또 망가졌나 봐.'),
