(33293, 7, 0, '나, 이 장난감 짜증 나. 이제 그만 놀래!'),
(33293, 8, 0, '%s의 심장이 드러나 에너지를 방출합니다.'),
(33293, 9, 0, '%s의 심장이 몸에서 분리됩니다.'),
(33293, 10, 0, '%s|1이;가; 짜증을 내자 땅이 마구 흔들립니다.'),
(33293, 11, 0, '%s|1이;가; 고철로봇을 소비해 체력을 회복합니다!'),
(33302, 0, 0, '네놈의 목숨은 도대체 몇 개인 것이냐? 이 질긴 오크 녀석!'),
(33302, 1, 0, '저주나 받아라, 벌레 같은 $r놈아! 이 숲은 칼도레이의 것이다!'),
(33303, 0, 0, '고맙다, 필멸자여! 지옥불에서 네가 설쳐 준 덕에 이렇게 탈출하게 되었군.'),
(33304, 0, 0, '고맙네, 친구여, 내 임무가 실패한 채로 알려진 채 눈을 감을 수는 없었다네.'),
(33304, 1, 0, '... 그리고 내 부하들의 희생도 아직 갚지 못했네.'),
(33304, 2, 0, '어서 서둘러야 하네. 내게 남은 시간이 얼마 없는 거 같네...'),
(33304, 3, 0, '바짝 붙어서 따라오게. 그리고 전투에 대비하게나!'),
(33304, 4, 0, '대장 엘렌딜라드는 앞에 보이는 섬에 숨어 겁쟁이같이 부하들에게 명령만 내리고 있네.'),
(33304, 5, 0, '그는 반드시 없어져야 하네!'),
(33304, 6, 0, '모습을 나타내라, 이 겁쟁이 엘프 녀석! 명예롭게 죽음을 맞아라!'),
(33306, 0, 0, '각오하십시오!'),
(33306, 0, 1, '준비해라!'),
(33306, 0, 2, '방어 태세를 갖춰라!'),
(33306, 0, 3, '시합을 시작합시다!'),
(33306, 1, 0, '승리는 나의 것이다!'),
(33306, 1, 1, '연습이 더 필요한 것 같군요. 아마 다음번에는 이길 수 있을 겁니다.'),
(33306, 1, 2, '내가 이겼군요. 다음번엔 좀 더 행운이 따르길 바라지요, 친구.'),
(33306, 1, 3, '아무래도 나를 꺾으려면 좀 더 연습해야겠군요.'),
(33306, 2, 0, '내가 패했군요.'),
