(33350, 0, 0, '이런, 이런! 손님이 올 줄은 전혀 몰랐다고! 작업장이 이렇게 난장판인데... 아휴, 부끄러워라...'),
(33350, 1, 0, '아니, 대체 왜 그런 짓을 한 게지? "누르지 마시오."라고 쓰인 경고 문구 못 봤나? 자폭 장치를 활성화해 놓으면, 도대체 어떻게 발명품을 시험하지?'),
(33350, 2, 0, '시간이 없어, 친구들! 내가 최근에 만든 기막힌 발명품을 시험하게 도와 주겠지? 자, 마음 바꿀 생각은 말라고. XT-002를 그 꼬락서니로 만들었으니, 너흰 나한테 빚진 셈이란 걸 잊지 마!'),
(33350, 3, 0, '의무병!'),
(33350, 3, 1, '내가 고쳐 줄게! 아니, 안 되나? 어이구... 어찌나 난장판인지...'),
(33350, 4, 0, '멋지군! 참으로 경이적인 결과야! 차체 내구도 98.9 퍼센트라! 손상이라고 보기도 어렵지! 계속하자고.'),
(33350, 5, 0, '봐라! VX-001 대인 공격포의 아름다운 자태를! 아마 숨고 싶어질걸!'),
(33350, 6, 0, '매혹적이야. 이런 걸 두고 한 방이라고 하지.'),
(33350, 6, 1, '적어놔야겠군. 대포는 살덩이에 대단히 효과적임.'),
(33350, 7, 0, '고맙다, 친구들! 너희 덕분에 멋진 자료를 좀 얻었어! 자, 그걸 어디 뒀더라... 아, 여기 있군.'),
(33350, 8, 0, '정말 아름답지? 난 이걸 위대한 공중 지휘기라 부르지!'),
(33350, 9, 0, '음, 이겼군!'),
(33350, 9, 1, '그거보단 잘해야지!'),
(33350, 10, 0, '예비 시험은 이걸로 끝이다. 자, 이제부터가 진짜라고!'),
(33350, 11, 0, '그 장엄함을 느껴라! 영광을 흠뻑 취해, 아니... 영광에 취해라! 소개하마... V-07-TR-0N!'),
(33350, 12, 0, '회복 가능성 없음! 하!'),
(33350, 12, 1, '다시는 일어날 수 없을 게다, 친구.'),
(33350, 13, 0, '내가 계산을 좀 잘못한 것 같군. 감옥에 갇힌 마귀가 내 마음을 타락시키고 제1지시를 재정의하고 말았다. 이제 모든 시스템이 제 기능을 찾았다. 정상이다.'),
(33350, 14, 0, '이런, 이런! 시간이 다 된 것 같다, 친구들.'),
(33382, 0, 0, '각오하십시오!'),
(33382, 0, 1, '준비해라!'),
(33382, 0, 2, '방어 태세를 갖춰라!'),
(33382, 0, 3, '시합을 시작합시다!'),
(33382, 1, 0, '승리는 나의 것이다!'),
(33382, 1, 1, '연습이 더 필요한 것 같군요. 아마 다음번에는 이길 수 있을 겁니다.'),
(33382, 1, 2, '내가 이겼군요. 다음번엔 좀 더 행운이 따르길 바라지요, 친구.'),
(33382, 1, 3, '아무래도 나를 꺾으려면 좀 더 연습해야겠군요.'),
