(33384, 2, 3, '내가 졌군요. 멋진 시합이었습니다!'),
(33437, 0, 0, '우리는 지원군이 올 때까지 버틸 것이다. 용감한 병사들이 성벽과 옥좌를 지키는 한, 스톰윈드는 무너지지 않는다.'),
(33440, 0, 0, '가까이 있어 주십시오, $r|1이여;여;. 엘프들이 가까이 오지 못하게 해 주십시오!'),
(33440, 0, 1, '제가 죽도록 내버려 두지는 않을 거죠, 네? 그럼 됐습니다...'),
(33440, 0, 2, '계속해서 망을 보십시오! 사방에 엘프들이 들끓고 있습니다!'),
(33440, 0, 3, '흠. 당신은 그다지 강해 보이지는 않습니다만... 괜찮겠군요.'),
(33440, 1, 0, '절 좀 지켜주십시오, $r님!'),
(33440, 1, 1, '느낌이 별로 좋지 않군요...'),
(33440, 1, 2, '당신을 믿습니다... 죽지 않게 해 주십시오!'),
(33440, 2, 0, '여기 있습니다, $r 님.'),
(33441, 0, 0, '감탄스러울 만큼 끈질기구나.'),
(33441, 1, 0, '부서뜨려 주마... 그를 부숴버렸던 것처럼!'),
(33442, 0, 0, '으아아아!'),
(33442, 1, 0, '하나도 두렵지 않다!'),
(33488, 0, 0, '가까운 사로나이트 증기 구름이 합쳐집니다!'),
(33515, 1, 2, '내 손아귀에서 절대로 벗어날 수 없다!'),
(33515, 2, 0, '시간이 아깝구나!'),
(33523, 0, 0, '다 끝났소. 담아야 할 것을 모두 담았어. 이제 용의 영혼을 영원히 봉인하겠소.'),
(33523, 1, 0, '정해진 과정을 밟을 뿐이야. 괜찮소.'),
(33532, 1, 0, '우와!'),
(33532, 2, 0, '나도 맞혔다!'),
(33532, 3, 0, '눈싸움 재밌었다!'),
(33532, 4, 0, '저거 봐라! 케켁 무지 센 전사다! 보이지? 케켁이 뭐라고 하나?'),
(33532, 5, 0, '흠... 저 케켁 많이 늙었다. 광란심장 일족 지도자, 장로인가 보다. 이거 좋다. 케켁 미래 훌륭하다. 전사도 되고 지도자도 된다. 케켁 여기 데려와 줘서 행복하다. 원장 아줌마는 케켁한테 이런 거 안 해준다.'),
(33532, 6, 0, '와아. 드디어, 케켁 헤멧 네싱워리 만났다!'),
(33532, 7, 0, '당신이 숄라자르에 온 다음에 광란심장 일족까지도 소문이 쫙 퍼졌다. 비결이 뭔지 케켁한테 알려줘라, 응?'),
(33532, 8, 0, '읽는다고 뭐가 달라지는지 모르겠다. 케켁은 글 못 읽는데. 헤멧 네싱워리가 그렇게 말한다면, 케켁 해볼 거다.'),
(33532, 9, 0, '아마 포기하고 동물들에게 책을 집어던지겠지만, 시도는 해본다.'),
(33532, 10, 0, '곰 인간이 싸워서 나무 도시 되찾은 것처럼 언젠가 케켁도 광란심장 일족 집에 데려갈 수 있을까? 케켁 우리 집 갖고 싶다. 보라색 인간들 많은 도시 말고, 날름이들 많은 정글도 말고.'),
(33532, 11, 0, '케켁은 용의 여왕 보러 가는 줄 알았는데. 이건 그냥 웃기는 뿔 달린 엘프 여자다.'),
(33532, 12, 0, '하지만 왜? 용은 크고 강하다. 엘프 여자 약하다. 케켁은 용의 여왕 진짜 모습 보고 싶다.'),
(33532, 13, 0, '오! 케켁 이제 알겠다. 큰 용 여자한테 깔리기 싫다. 사람 적을 때 다시 오던가 하자. 반가웠다, 용 여자.'),
(33533, 1, 0, '우와!'),
(33533, 2, 0, '루도 춤출 줄 안다!'),
(33533, 3, 0, '새 친구 생겼다!'),
(33533, 4, 0, '와, 다 왔다! 근데, 이게 진짜 세계수면, 이 안에 온 세상을 넣으려고 했을 때 왜 부러졌어?'),
(33533, 5, 0, '봐봐! 저게 루야? 루 같은데... 좀 늙었다, 그치?'),
(33533, 6, 0, '위대한 자들이 루 축복해 줬나 봐! 제단이 루한테 마법 줘서 언젠가 대점쟁이 되게 해줄까? 그럴까?'),
(33533, 7, 0, '와! 진짜 위대한 자야? 수세이가 진짜 위대한 자를 만났을 줄은 생각도 못했어!'),
(33533, 8, 0, '음, 안녕하세요. 위대한 자님, 만나뵈어 영광이에요.'),
(33533, 9, 0, '주무시나 봐요, 위대한 자님? 이해해요. 위대한 자님으로 저희가 바친 반짝이를 거두시려면 얼마나 피곤하시겠어요.'),
(33533, 10, 0, '선물을 가져왔어요, 위대한 자님. 일어나면 보시겠지요. 저희가 만나러 온 것도 기억하시겠지요, 네?'),
(33533, 11, 0, '저게 용의 여왕님이야? 흠... 더 클 줄 알았는데. 응, 그럴 줄 알았어.'),
(33533, 12, 0, '왜 다른 용이랑 다르게 생겼어? 맘만 먹으면 크고 늙은 용으로 변신하는 거야?'),
(33533, 13, 0, '저어... 폐하, 용으로 변신해 주시면 안 돼요?'),
(33533, 14, 0, '네... 그럼 지금은요?'),
(33535, 0, 0, '저것은 어떤 무기와도 다르오. 당연히 다른 무기와는 달라야지.'),
(33552, 0, 0, '수천의 죽음...'),
(33552, 1, 0, '네놈들의 시시한 분쟁은 나를 강하게 할 뿐...'),
(33552, 2, 0, '이르 은라이어스... 슐 아나그!'),
(33552, 3, 0, '그도 깨달을 것이다... 영원한 왕 따윈 없어! 오직 죽음만이 영원하다!'),
(33552, 4, 0, '놈의 동족은 얼마 안 가 교훈을 얻었지. 너희도 곧 배울 게다!'),
