(33564, 1, 2, '내가 이겼군요. 다음번엔 좀 더 행운이 따르길 바라지요, 친구.'),
(33564, 1, 3, '아무래도 나를 꺾으려면 좀 더 연습해야겠군요.'),
(33564, 2, 0, '내가 패했군요.'),
(33564, 2, 1, '훌륭한 전투였습니다. 당신에게 패했군요.'),
(33564, 2, 2, '당신의 능력을 과소평가했던 것 같군요. 잘하셨습니다.'),
(33564, 2, 3, '내가 졌군요. 멋진 시합이었습니다!'),
(33579, 0, 0, '펜타루스 대마법사님, 저 $g신사분:숙녀분; 말씀 들었죠? 보호막을 해제해서 이 용감한 영혼들이 지나가게 하세요!'),
(33579, 1, 0, '좋아요! 움직입시다. 차량에 올라타세요. 이제부터 무전기로 말씀드리죠.'),
(33579, 2, 0, '우리 동료는 준비를 마쳤습니다. 보호막을 걷고 길을 만드세요!'),
(33579, 3, 0, '앞에 보이는 기둥 아래쪽에 있는 문에서 무쇠 드워프들이 쏟아져 나오고 있습니다! 입구를 파괴하세요. 그럼 놈들도 후퇴할 겁니다!'),
(33579, 4, 0, '방어 구조물에 동력을 공급하는 네 개의 발전기가 있습니다. 그 발전기를 파괴하면 미사일 공격이 멈출 거예요!'),
(33624, 0, 0, '물론입니다, 브란. 잠깐 보호막을 내리겠습니다.'),
(33624, 1, 0, '키린 토의 마법사여, 브란의 명령에 따라 보호막을 해제하라! 목숨을 걸고 이곳과 우리의 동맹을 지켜라! 달라란을 위하여!'),
(33626, 0, 0, '전혀요. 죽어라 살펴봐도 어떻게 이걸 작동시키는지 전혀 모르겠어요.'),
(33626, 1, 0, '알아요, 알아요... 아직 포기한 건 아니에요. 그래도 너무 기대하지는 마세요. 여기 사용된 기술은 제 수준을 한참 뛰어넘는다고요.'),
(33626, 2, 0, '이 망할 기계가 드디어 작동하기 시작했어요! 이걸 이용하면 광장 끝까지 바로 가실 수 있답니다. 왜, 거대 화염전차랑 마지막으로 싸우시던 곳 있잖아요.'),
(33662, 0, 0, '좋은 소식이라도?'),
(33662, 1, 0, '그래도 계속 애써 주세요. 우리 짐작대로 이게 순간이동기라면, 공격에 대단히 유용할 겁니다.'),
(33686, 0, 0, '저는 이 단지와 관련된 필수적인 정보를 담는, 일종의 저장고 역할을 하도록 만들어졌습니다. 제 주요 기능에는 전방 방어 시스템의 상태 전달과, 이 단지에 수용해 두어야 하는 존재의 상태 평가가 포함되어 있습니다.'),
(33686, 1, 0, '단지 내부 접근은 현재 제한되어 있습니다. 주 방어 설비들이 작동 중입니다. 보조 시스템은 현재 비활성화되어 있습니다.'),
(33686, 2, 0, '단지가 위험에 처해 있음이 감지되었습니다. 보안 재정의가 활성화되었습니다. 질의가 허가되었습니다.'),
(33686, 3, 0, '주 방어 설비는 무쇠 피조물과, 필요에 따라 추가 무쇠 피조물을 생성하는 폭풍 봉화로 구성되어 있습니다. 보조 시스템은 궤도적 방어 설비로 구성되어 있습니다.'),
(33686, 7, 0, '존재 지시어. 요그사론. 보안 환경이 손상되었습니다. 감옥 관리 상황, 알 수 없음. 알림을 목적으로 감시자와 연락할 수 없습니다.'),
