(33788, 0, 0, '이 날카로운 바람으로부터 우릴 보호하는 방패가 되어 다오, 작은 묘목아.'),
(33788, 0, 1, '거기 있었구나.'),
(33788, 0, 2, '잘 자라거라, 작은 친구여.'),
(33853, 0, 0, '이번 마상시합은 오랜만에 열리는 가장 큰 행사입니다요! 집에 있는 가족들에게 가져갈 기념품을 사서 아이들에게 보여주세요.'),
(33853, 0, 1, '여러분! 여기 겹셔츠 좀 보세요! 펄럭거리고 거추장스러운 휘장을 입지 않아도 응원하는 도시의 색상을 자랑할 수 있답니다!'),
(33853, 0, 2, '저 친구 중 한 명과 전투를 하지 않고 자신의 긍지를 보여주고 싶지 않으신가요? 손님께서 어느 도시를 응원하든지, 손님께서 원하는 건 제게 다 있습니다요!'),
(33874, 0, 0, '접근이 거부되었습니다. 권한이 부족합니다.'),
(33874, 1, 0, '99.99 퍼센트입니다.'),
(33874, 2, 0, '물론 순환소수입니다.'),
(33874, 3, 0, '감시자 프레이야 상태 분석을 시작합니다.'),
(33874, 4, 0, '감시자의 힘은 하인 중 세 장로에 의해 증대됩니다.'),
(33874, 5, 0, '장로 밝은잎 강화력 분석 중... 태양 광선을 증폭하여 지속적인 광역 방어 효과를 강화합니다.'),
(33874, 6, 0, '장로 돌나무껍질은 마법 사용을 방해하는 음파 효과로 방어에 기여합니다.'),
(33874, 7, 0, '장로 무쇠줄기 조사 결과, 식물체에 기인한 이동 불가 효과가 관찰되었습니다.'),
(33874, 8, 0, '추가로, 장로들은 각각 프레이야의 주문 공격력, 물리 공격력, 소환수 능력의 증대와 연관되어 있음이 드러났습니다.'),
(33874, 9, 0, '세 장로를 처치하면 감시자 프레이야는 강화 효과를 상실합니다. 하지만, 프레이야 자신과 그녀의 소유물인 인장에도 영구적인 피해가 생길 가능성이 매우 큽니다.'),
(33874, 10, 0, '감시자 호디르 상태 분석을 시작합니다.'),
(33874, 11, 0, '호디르의 인장은 유물 보관함 안에 있는 것으로 보입니다.'),
(33874, 12, 0, '감시자 호디르는 쉽게 흥분하고 불안정한 행동을 하므로, 전투가 길어지면 보관함을 파괴할 가능성이 매우 큽니다.'),
(33874, 13, 0, '해당 전장에 있는 동료는 전력 상승과 전투 시간 최소화에 기여할 것입니다.'),
(33874, 14, 0, '호디르의 인장을 되찾으려면 보관함을 보호해야 합니다.'),
(33874, 15, 0, '감시자 토림 상태 분석을 시작합니다.'),
(33874, 16, 0, '토림의 죽은 배우자, 시프의 환영으로 위장하고 있는 외부 존재가 감지되었습니다.'),
(33874, 17, 0, '환영이 일으킨 정신 간섭은 부분적인 기억 손상을 유발할 가능성이 매우 큽니다.'),
(33874, 18, 0, '분석 결과, 전방에서 투기장으로 접근한 후 두 번째 부대를 지상 측면 통로로 분리하는 전략이 도출되었습니다. 이로써 외부 존재의 정신 지배가 완료되기 전에 토림의 관람석에 도착할 확률을 극대화합니다.'),
(33874, 19, 0, '감시자 미미론 상태 분석을 시작합니다.'),
(33874, 20, 0, '감시자 미미론의 인장은 창의성의 회랑 전체에 영향을 미치는 자폭 장치와 긴밀히 연결되어 있습니다.'),
(33874, 21, 0, '자폭 가동 장치의 코드명은 "큰 적색 단추"로서, 미미론 자신의 발명품입니다.'),
(33874, 22, 0, '미미론의 인장을 회수하려면 자폭 장치 가동 후 폭발 전까지 미미론을 처치하십시오.'),
(33874, 23, 0, '고대 기록관 접근을 허가합니다. 접근 제한 기능을 일시 중단합니다.'),
(33874, 24, 0, '질의를 시작합니다. 비상 안전장치 알갈론은 제1관리자 활동 정지 시 자동 실행되는 위급 신호입니다.'),
(33874, 25, 0, '그렇습니다. 제1관리자 로켄의 활동 정지 접수와 동시에 이 신호가 활성화됩니다.'),
(33874, 26, 0, '검색 중... 제1관리자 활동 정지는 행성 시스템의 오류를 알리는 첫 번째 신호로 간주됩니다. 이에 따라 관찰자 알갈론의 실체가 도착하여 행성 진단을 실행합니다. 도출될 수 있는 응답 신호는 두 가지로서, 응답 코드 알파는 "모두 정상" 신호, 응답 코드 오메가는 행성 재창조 신호입니다.'),
(33874, 27, 0, '행성과 생명체를 해체해 금속, 암석, 기체 등의 기본적인 요소로 되돌리는 작업을 뜻합니다. 이후에, 각 요소를 초기 행성 청사진에 맞게 재구성하는 절차가 뒤따릅니다.'),
(33874, 28, 0, '요청이 거부되었습니다. 응답 코드는 알갈론의 실체 안에 구성됩니다. 그는 전령이자 전갈 자체입니다.'),
(33874, 29, 0, '알갈론은 고대 신이 행성 중추 기능에 미친 시스템 손상 수준을 평가해 진단을 내립니다. 응답 코드 오메가를 도출할 확률은...'),
(33874, 30, 0, '요청이 거부되었습니다. 네 감시자의 인장을 수동으로 확인하는 과정이 필요합니다.'),
(33874, 31, 0, '울두아르의 네 감시자는 프레이야, 토림, 호디르, 미미론입니다. 인장은 그들의 육체와 정신에 긴밀하게 연결되어 있습니다. 별자리 투영관에 접근하려면 네 개의 인장이 모두 필요합니다.'),
(33874, 32, 0, '감시자 상태를 분석합니다. 대기하십시오.'),
(33874, 33, 0, '손상이 발견되었습니다. 외부 존재가 감시자를 장악하고 있습니다. 인장이 손상되었습니다.'),
(33874, 34, 0, '무력을 충분히 행사하면 감시자 기능이 초기화되어 외부 존재의 영향을 제거할 수 있습니다.'),
(33874, 35, 0, '이 과정에서 인장을 위험으로부터 보호하는 방법에 대해서는, 각 감시자의 상태를 분석한 계산 결과를 참고하십시오.'),
(33874, 36, 0, '조각 분석을 진행 중입니다.'),
(33874, 37, 0, '개체 식별. 고대 왕의 망치, 발아니르입니다.'),
(33874, 38, 0, '티탄이 직접 창조한 발아니르는 첫 번째 토석인 왕 우렐 스톤하트에게 주어졌습니다. 스톤하트는 망치로 형제들을 창조하고 생명을 불어 넣었습니다.'),
(33874, 39, 0, '발아니르는 토석인과 무쇠 드워프의 첫 번째 전쟁 때 파괴되었습니다. 무기의 파편은 유실되었다고 알려졌습니다.'),
(33874, 40, 0, '현재까지 알려진 일반적인 방법으로 복구에 성공할 확률은 0에 가깝습니다. 이론적인 방법이 분석될 때까지 대기하십시오.'),
(33874, 41, 0, '이론적으로 요그사론이라는 존재 내부에는 사로나이트를 액체로 변환하는 강력한 산성 물질이 수용되어 있습니다. 티탄이 만든 합금을 그 안에 담그면 금속 조직을 재결합할 수 있습니다.'),
(33890, 0, 0, '환상이 부서지며, 중앙에 있는 방으로 가는 길이 열립니다!'),
(33972, 0, 0, '돌진 표적에 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B표적이 무력화되었을 때 이어서 돌진으로 공격합니다.$B|Tinterface\\Icons\\Ability_Mount_Charger.blp:32|t'),
(33973, 0, 0, '방어를 시전합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$B그러고 나서 근접 표적에 찌르기를 사용합니다.$B|Tinterface\\Icons\\INV_Sword_65.blp:32|t'),
(33974, 0, 0, '원거리 표적에 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B표적에 방어가 사라진 동안 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t'),
(33978, 0, 0, '%s|1이;가; 물고기를 낚았습니다!'),
(33993, 0, 0, '%s|1이;가; 폭풍우 하수인을 과충전시킵니다!'),
(33993, 1, 0, '폭풍우 하수인이 에말론을 지키려 모습을 드러냅니다!'),
(33993, 2, 0, '%s|1이;가; 분노에 휩싸여 광폭해집니다!'),
(34044, 0, 0, '딱 좋군요. 그럼 신호를 보내버립시다.'),
(34054, 0, 0, '조심하세요! 정찰 편대가 보고하길 미사일 격납고 발전기에 동력이 들어오고 있다는군요!'),
(34054, 1, 0, '방어 구조물에 동력을 공급하는 네 개의 발전기가 있습니다. 그 발전기를 파괴하면 미사일 공격이 멈출 거예요!'),
(34054, 2, 0, '이 탑은 호디르의 망치에 동력을 공급하죠. 그 힘은 부대 전체를 얼려 버릴 만큼 무시무시하다고 들었습니다!'),
(34054, 3, 0, '프레이야의 탑에 접근 중이시군요. 메마른 황무지라도 단 하룻밤 새에 생기 넘치는 정글로 바꿀 수 있는 힘이 그 안에 있다더군요.'),
(34054, 4, 0, '이 발전기는 미미론의 눈에 동력을 공급합니다. 힘이 모이게 내버려 두면 안 돼요. 순식간에 흙을 바수고 돌을 녹인다고요!'),
(34054, 5, 0, '아, 크롤미르의 탑입니다. 딱 한 번 토림의 힘이 사용된 적이 있는데... 대륙 하나가 그냥 먼지가 되어 버렸다고 하더군요.'),
(34054, 6, 0, '미사일 발전기를 제어하는 장치는 탑 꼭대기에 있어요. 거기 가실 수만 있으면, 직접 끄실 수도 있을 겁니다.'),
(34054, 7, 0, '근처에 자동수리소가 있나 보군요! 단상 위로 탈것을 몰고 가시면 자동으로 수리가 될 겁니다.'),
(34054, 8, 0, '해내셨군요! 울두아르의 방어선을 무너뜨렸어요! 몇 분만 지나면 우린 이제...'),
(34054, 9, 0, '저건 뭐야? 조심하세요! 뭔가 다가오고 있어요!'),
(34054, 10, 0, '빨리요! 비상 회피! 비상 회피!'),
(34054, 11, 0, '좋아요! 움직입시다. 차량에 올라타세요. 이제부터 무전기로 말씀드리죠.'),
(34064, 0, 0, '우리가 해냈습니다! 알갈론보다 먼저 도착했다고요. 아마 시스템을 조작하면 알갈론의 분석을 방해할 수 있을...'),
(34064, 1, 0, '저는 고대 기록관으로 돌아가 신호를 방해해 볼게요. 당신들이 그를 상대하는 동안 시간을 좀 벌어 보죠.'),
(34064, 2, 0, '어딘지 압니다. 당신 괜찮겠어요?'),
(34207, 0, 0, '멀록 잔챙이들, 너희 보물을 훔치러 내가 왔다! 나를 막아 봐라! 어서!'),
(34207, 1, 0, '폭발 직전.'),
(34295, 0, 0, '잿빛 골짜기는 불타오를 것이다!'),
(34295, 0, 1, '죽음이 지하에서 솟아올라 땅 위를 뒤덮을 것이다! 도망칠 곳은 없다!'),
(34295, 0, 2, '부하들아, 저들을 죽여라!'),
(34295, 0, 3, '대지의 속박에서 풀려났으니 다시는 돌아가지 않을 것이다!'),
(34295, 0, 4, '대지 고리회는 나의 분노를 당해낼 수 없다!'),
(34340, 0, 0, '이 무지한 얼간이 친구야, 저 폐허는 똑같은 폐허란 말이야. 똑같은 곳을 뱅뱅 돌고 있었다고!'),
(34341, 0, 0, '호드 전쟁 무기를 위한 희생물이 더 있군.'),
(34341, 1, 0, '아무래도 이곳에 록레인의 병사들이 있는 것 같다. 돈트래그, 우트보크. 크롬가르 요새에 자네들의 노련한 기술이 필요할 것이다.'),
(34341, 2, 0, '남아 있는 그런트들이여! 무장하라! 죽여야 할 것들이 있다.'),
(34343, 0, 0, '최고로군요! 힘을 비축하세요, 아무개 씨. 갈 길이 머니까요.'),
(34343, 1, 0, '준비됐나요? 움직입시다!'),
(34343, 2, 0, '여기 보이는 폐허는 몇 달 전에 제가 판 폐허랑 똑같아요. 근데 물에 침수되고 말았죠! 기이하죠?'),
(34343, 3, 0, '아, 거의 다 왔군요, 아무개 씨! 제 일지를 놓고 온 야영지가 아주 가까워요!'),
(34343, 4, 0, '세 망치단의 이름으로, 저걸 좀 보라고요! 폐허가 더 있어요!'),
(34343, 5, 0, '내가 찾은 이 폐허들은 방금 떠나온 폐허들하고 완전히 똑같군! 일생일대의 발견이야!'),
(34343, 6, 0, '말도 안 돼, 보라고. 이게 내 일지라고, 여기 말이야.'),
(34343, 7, 0, '페르드, 지금 이 상황을 어떻게 생각하나?'),
(34386, 1, 0, '아, 여기 구경 왔던 게 기억나. 그럼, 그렇고말고. 새로운 친구한테 배운 걸 잊지 마, 작은 루. 네 미래는 멋져.'),
(34387, 1, 0, '걱정하지 마라, 케켁. 너 큰다. 광란심장 일족 위해 강해진다. 너, 고향으로 광란심장 일족 데려간다. 거기엔 새끼 날름이들 없다.'),
(34422, 0, 0, '아즈샤라, 다 끝났다! 나가를 이끌고 너희가 기어나온 바닷속 깊은 곳으로 돌아가라!'),
(34422, 1, 0, '저건 거짓말이 아니다. 놀드랏실이 위험해. 서둘러 하이잘 방어 준비를 해야겠다.'),
(34422, 2, 0, '고대정령의 뿔피리를 불어 소고스의 귀환을 막는 임무는 그대에게 맡기겠다.'),
(34423, 0, 0, '이미 늦었다... 그 유물은 우리가 얘기하는 바로 지금 아즈샤라 님께 바쳐지고 있다!'),
(34489, 1, 0, '내가 재밌는 거 보여 줄까?'),
(34489, 2, 0, '이제 같이 춤추자!'),
(34490, 1, 0, '조심하는 게 좋을걸!'),
(34490, 2, 0, '제대로 맞혔다!'),
(34496, 5, 0, '혼돈을!'),
(34496, 7, 0, '너흰 모두 끝장이야!'),
(34497, 5, 0, '혼돈을!'),
(34497, 7, 0, '너흰 모두 끝장이야!'),
(34503, 0, 0, '%s|1이;가; 그물에 걸렸습니다!'),
(34503, 1, 0, '%s|1이;가; 그물을 뚫고 나옵니다.'),
(34519, 0, 0, '장난감 돌려줘!'),
(34519, 1, 0, '멈춰!'),
(34519, 2, 0, '보육원 원장님한테 이를 거다!'),
(34520, 0, 0, '갖고 싶으면 가서 가져와, 새끼 날름아!'),
(34523, 0, 0, '<킁킁거리며> 아오!'),
(34523, 0, 1, '내게서 아무것도 알아내지 못할 것이다!'),
(34523, 0, 2, '아욱! 얼굴은 안 돼!'),
(34523, 0, 3, '악! 그래도 말 못한다!'),
(34523, 0, 4, '<킁킁거리며> 겨우 이 정도냐?'),
(34523, 0, 5, '아으으윽! 아무것도 말 못한다!'),
(34523, 1, 0, '킁킁!'),
(34523, 1, 1, '아무것도 말 못해!'),
(34523, 1, 2, '난 네놈이 두렵지 않아!'),
(34523, 1, 3, '아무것도 말할 수 없다! <킁킁거리며>'),
(34523, 2, 0, '%s|1이;가; 조심스럽게 음식을 받아먹습니다.'),
(34523, 3, 0, '<킁킁거리며>에이, 왜 음식을 요리해서 주는 거야? 토르터스크님이 음식은 훔쳐서 날것으로 먹는 게 가장 맛있다고 말씀하셨단 말이야.'),
(34523, 4, 0, '하하... <킁킁> 오하하하! <킁킁> 에헤헤! 안 돼! 그만해! <킁킁> 헤헤헤헤! <숨을 내쉬며> 전투모병관 토르터스크님이 간지럼 태우는 건 어떻게 참아야 하는지 안 가르쳐 주셨단 말이야!'),
(34523, 5, 0, '네 힘만 빼는 거야! 토르터스크님은 우리를 절대로 비밀을 말하지 않는 전사로 훈련시켰으니까.'),
(34523, 6, 0, '아, 이런. 내가 너무 많이 말했군!'),
(34564, 0, 0, '아아, 주인님께서 약속하신 대로 손님이 왔구나.'),
(34564, 1, 0, '여기가 네 무덤이 되리라!'),
(34564, 2, 0, '아움 날락크, 쉬. 일어나라, 부하들아. 먹어치워라...'),
(34564, 3, 0, '%s|1이;가; 땅속으로 숨어버립니다!'),
(34564, 4, 0, '%s|1이;가; 땅속에서 모습을 드러냅니다!'),
(34564, 5, 0, '착취의 무리가 너희를 덮치리라!'),
(34564, 6, 0, '%s|1이;가; 착취의 무리를 불러내어 스스로 치유합니다!'),
(34564, 7, 0, '프을라크 쉬얼!'),
(34564, 7, 1, '배를 채울 영혼이 또 생겼구나.'),
(34564, 8, 0, '실망시켜 드렸군요, 주인님...'),
(34660, 0, 0, '%s의 쐐기가 $n|1을;를; 쫓습니다!'),
(34674, 0, 0, '가만히 서 있으라고, $n! 그리고 바다 위로 떨어질지도 모르니까 숨은 멈추고...'),
(34715, 0, 0, '이제 오그리마야. 언제나처럼 거대하고 위협적인 모습이지. 잠시 숨을 돌려봐. 그러고 나선 다시 썬더 블러프로 돌아갈 테니!'),
(34715, 1, 0, '이번에 정류할 곳은, 썬더 블러프야!'),
(34715, 2, 0, '승강장과 사이가 넓으니 발이 빠지지 않게 조심해! 떨어져서 저 아래에 빈대떡이 되지 않았으면 해! 썬더 블러프에 온 모두를 환영해!'),
(34715, 3, 0, '좋아, 모두들. 이 녀석을 타고 다시 오그리마로 가자고!'),
(34716, 0, 0, '감사합니다, $c님.'),
(34716, 0, 1, '저들이 갇힌 이들을 죽이고 있습니다! 서둘러 도와주십시오.'),
(34716, 0, 2, '여기에서 살아서 나가리라고는 꿈에도 생각하지 못했습니다.'),
(34716, 0, 3, '저기에서 죽을 줄 알았습니다!'),
(34716, 0, 4, '마상시합 따위에 나오지 말았어야 했습니다!'),
(34723, 0, 0, '저 구름은 우리 대족장님을 닮았군요.'),
(34723, 0, 1, '저기 벌레가 한 마리 갑니다.'),
(34723, 0, 2, '배가 어디 있다는 겁니까! 하피입니다! ...잠시만요, 저건 또 다른 새군요.'),
(34723, 0, 3, '저기 새가 있습니다!'),
(34756, 0, 0, '쉿! 누군가 왔어요.'),
(34766, 0, 0, '모두 승선해! 오그리마행 비행선이 도착했어! 듀로타로 가실 분들은 모두 타라고!'),
(34780, 0, 0, '보이지도 않는 노움 주제에! 그렇게 까불더니 무덤을 파는구나!'),
(34780, 1, 0, '불타는 군단의 에레다르 군주, 자락서스 님이 상대해주마!'),
(34780, 2, 0, '$n|1이;가; |cFFFF0000군단 불꽃|r의 대상이 되었습니다!'),
(34780, 3, 0, '%s|1이;가; 황천의 차원문을 엽니다!'),
(34780, 4, 0, '나오너라, 자매여! 네 주인이 부르노라!'),
(34780, 5, 0, '$n|1이;가; |cFF00FFFF살점 소각|r에 걸렸습니다!'),
(34780, 6, 0, '뼈에서 살을!'),
(34780, 7, 0, '%s|1이;가; |cFF00FF00지옥불 화산|r을 일으킵니다!'),
(34780, 8, 0, '지옥불을 받아라!'),
(34780, 9, 0, '시시하구나!'),
(34780, 9, 1, '황천으로 사라져라!'),
(34780, 10, 0, '또 누군가 날 대신하여 오리라. 그러면, 다 끝이다...'),
(34780, 11, 0, '어둠의 주인님을 받들어. 리치 왕을 위하여. 너희에게. 죽음을. 안기리라.'),
(34796, 0, 0, '%s|1이;가; $n|1을;를; 노려보며 큰 소리로 울부짖습니다.'),
(34797, 0, 0, '%s|1이;가; $n|1을;를; 노려보며 큰 소리로 울부짖습니다.'),
(34797, 1, 0, '%s|1이;가; 원형경기장 벽을 들이받고 기절했습니다!'),
(34797, 2, 0, '전투에 참여한 이들을 밟아 뭉개며, %s|1이;가; 거품을 물고 분노합니다!'),
(34799, 0, 0, '동료가 죽는 모습을 본 %s|1이;가; 분노합니다!'),
(34830, 0, 0, '쏘지 마세요!'),
(34830, 0, 1, '인사부에 신고할거요!'),
(34830, 0, 2, '갈게요! 일하러 간다고요!'),
(34830, 0, 3, '이런, 휴식 시간이 끝났군요.'),
(34830, 0, 4, '죄송합니다. 이제 잘할게요.'),
(34830, 0, 5, '내가 뭐 잘못했나요? 점심 먹고 두 번 쉬는 거 아닌가요?'),
(34830, 0, 6, '언더마인에서보다 일하기 편한걸!'),
(34850, 0, 0, '경비병, 모두 경계 태세로! 침입자 수를 정확히는 모르나, 마루터기를 놈들에게 빼앗겼고 항구 쪽 마을로 통하는 길이 끊겼다. 적의 수가 엄청난 듯하다.'),
(34850, 1, 0, '방어선을 확실히 지키고 관문에는 경비병 두 명을 항상 배치하라. 아무도 내보내지 말고, 들이지도 말라.'),
(34850, 2, 0, '우리는 스컬지의 공격을 이겨냈다. 북문 반란군의 공격도 막아냈다. 어떤 위협이 다가오든, 우리는 길니아스를 지켜낼 것이다!'),
(34851, 0, 0, '저기... 지붕 위에 무언가가 있습니다!'),
(34851, 0, 1, '누가 좀 구해주세요!'),
(34851, 0, 2, '살려 주세요! 다시는 돌아오지 않겠습니다. 제발요!'),
(34851, 0, 3, '오늘 네가 내 아이들을 고아로 만드는구나, 친구여!'),
(34851, 0, 4, '저... 저들이 우린 안전할 거라고 약속했는데...'),
(34851, 0, 5, '난 죽기엔 너무 젊어!'),
(34851, 0, 6, '뭐든 말씀만 하시면 드리겠습니다! 목숨만 살려주세요!'),
(34851, 0, 7, '도와주세요! 도와주세요!'),
(34851, 1, 0, '그렇게 쉽게 죽지는 않을 것이다!'),
(34851, 1, 1, '스컬지의 개 같으니! 죽어라!'),
(34851, 1, 2, '스컬지라는 것들이 겨우 이 정도였나?'),
(34851, 1, 3, '목숨은 빼앗겨도 자유는 빼앗기지 않으리라!'),
(34851, 1, 4, '죽어라!'),
(34851, 1, 5, '싸워보지도 않고 개죽음을 당하진 않겠다!'),
(34864, 0, 0, '아무도 이곳을 벗어나지 못합니다. 리암 왕자님께서 명령하셨습니다.'),
(34864, 0, 1, '숲 속에 무언가가 돌아다니고 있으니 이곳을 벗어나면 위험합니다.'),
(34864, 0, 2, '가만히 있으십시오. 모든 일이 차질 없이 진행 중입니다.'),
(34883, 0, 0, '호드 구경꾼들이 $n에게 환호를 보냅니다.'),
(34884, 0, 0, '%s|1이;가; 격노합니다!'),
(34887, 0, 0, '얼라이언스 구경꾼들이 $n에게 환호를 보냅니다.'),
(34900, 0, 0, '스톰윈드에서 온 인간들이 $n에게 환호를 보냅니다.'),
(34901, 0, 0, '오그리마에서 온 오크들이 $n에게 환호를 보냅니다.'),
(34902, 0, 0, '센진 마을에서 온 트롤들이 $n에게 환호를 보냅니다.'),
(34903, 0, 0, '썬더 블러프에서 온 타우렌들이 $n에게 환호를 보냅니다.'),
(34904, 0, 0, '실버문에서 온 블러드 엘프들이 $n에게 환호를 보냅니다.'),
(34905, 0, 0, '언더시티에서 온 포세이큰들이 $n에게 환호를 보냅니다.'),
(34906, 0, 0, '아이언포지에서 온 드워프들이 $n에게 환호를 보냅니다.'),
(34908, 0, 0, '엑소다르에서 온 드레나이들이 $n에게 환호를 보냅니다.'),
(34909, 0, 0, '다르나서스에서 온 나이트 엘프들이 $n에게 환호를 보냅니다.'),
(34910, 0, 0, '놈리건에서 온 노움들이 $n에게 환호를 보냅니다.');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(34924, 0, 0, '관문이 무너졌다! 요새를 지켜라!'),
(34928, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
(34942, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
(34956, 0, 0, '빛이여, 감사합니다! 이런 미친 짓은 다시는 하지 않겠습니다!'),
(34956, 0, 1, '놈들은 제단에 저를 묶어 영혼을 빨아내려던 참이었습니다. 어서 여길 빠져나갑시다!'),
(34956, 0, 2, '미친 이교도 놈들을 상대하게 해주십시오! 반으로 쪼개버리겠습니다!'),
(34956, 0, 3, '남은 지원자를 구출해서 돌아갑시다. 이 일이 끝나고 나면 에일을 한 주전자는 마셔야겠어요!'),
(34956, 0, 4, '이교도 놈들에게 쓴맛을 보여주세요, $n 님. 이 성전사 쿨 님을 귀찮게 하면 호된 꼴을 면할 수 없지!'),
(34960, 0, 0, '모두 비행포격선에 오르십시오! 대포를 맡아 주시기 바랍니다!'),
(34980, 0, 0, '감히 바다의 왕인 드로틴 흐로스가르에게 도전하느냐?'),
(34981, 0, 0, '제발 저를 보호해 주십시오!'),
(34981, 0, 1, '고맙습니다!'),
(34981, 0, 2, '이곳은 안전하지 않습니다! 어서 떠나십시오!'),
(34981, 0, 3, '대체 무슨 일이지요? 얼른 도망칩시다!'),
(34981, 0, 4, '늑대인간입니다! 늑대인간이 나타났습니다!'),
(34990, 0, 0, '경의 야수들은 우리 용사들의 상대가 안 되오.'),
(34990, 1, 0, '호드 쓰레기를 처리하는 데 악마 군주의 도움 따위는 필요 없다! 덤벼 봐라!'),
(34990, 2, 0, '우리의 명예는 짓밟혔다! 호드는 말도 안되는 주장을 하며 거짓으로 우리를 비난했다! 나는 정의를 원한다! 티리온 경, 나의 용사들이 그대의 기사를 대신하여 싸우게 하시오. 우리는 호드에 도전할 것이오!'),
(34990, 3, 0, '얼라이언스의 영광을 위해 싸워라, 영웅들이여! 우리의 명예를 지켜라!'),
(34990, 4, 0, '얼라이언스에 영광을!'),
(34990, 5, 0, '리치 왕의 가장 강력한 부하라도 얼라이언스에는 저항할 수 없다. 모두 승리자를 맞이하라!'),
(34990, 6, 0, '그것도 도전이라고.'),
(34990, 6, 1, '하!'),
(34990, 6, 2, '호드란 놈들은 겨우 이정도였나?'),
(34990, 6, 3, '하찮은 놈 같으니.'),
(34990, 50, 0, '난 이런 경기에는 별 관심이 없소, 티리온 경. 그래도... 저들이 훌륭한 모습을 보여주리라 믿소.'),
(34990, 51, 0, '가만히 서 있지 마라! 놈을 없애!'),
(34990, 52, 0, '짐승들끼리 정신없이 서로 물고 뜯는 모습을 보러 여기 온 건 아니오, 티리온 경.'),
(34990, 53, 0, '잘 싸웠다.'),
(34994, 0, 0, '잘 싸워주게, 호드여! 록타르 오가르!'),
(34994, 1, 0, '잘했다, 호드여!'),
(34994, 2, 0, '가로쉬, 그만하게.'),
(34995, 0, 0, '피의 투기장도 이것보다는 훨씬 낫겠군. 우리 시간을 낭비하지 마라.'),
(34995, 1, 0, '비열한 얼라이언스 놈들! 호드 전사를 상대로 악마 군주를 소환해? 당장 죽음을 안겨 주마!'),
(34995, 2, 0, '호드는 정의를 원한다! 이제 얼라이언스에 도전한다! 성기사여, 우리가 그대의 기사를 대신하여 싸우도록 하라. 호드를 모욕한 대가를 이 쓰레기들에게 보여줄 테니.'),
(34995, 3, 0, '저들에게 자비란 없다, 호드 용사들이여! 록타르 오가르!'),
(34995, 4, 0, '앞으로 일어날 일의 맛보기일 뿐이다. 호드를 위하여!'),
(34995, 5, 0, '성기사여, 아직 호드의 힘에 의문을 품는가? 오는 대로 모두 상대해주겠다!'),
(34995, 6, 0, '약해빠진 놈!'),
(34995, 6, 1, '오, 이런 너무 애처롭군.'),
(34995, 6, 2, '맥도 못추는군...'),
(34995, 6, 3, '록타르!'),
(34995, 50, 0, '드디어 봐줄 만한 싸움을 하는군.'),
(34995, 51, 0, '놈을 조각내 버려!'),
(34995, 52, 0, '훌륭하다고? 하하! 나약하고 초라한 그쪽 용사들이 쓰러지는 모습을 즐겁게 감상해주지.'),
(34996, 0, 0, '어서 오게, 용사들이여! 은빛십자군의 부름에 담대히 응한 모두를 환영하네! 바로 이곳, 십자군 원형경기장에서 제군들은 엄청난 도전에 마주칠 걸세. 혹독한 원형경기장에서 살아남는 자는 은빛십자군의 일원이 되어 얼음왕관 성채로 진군해 나갈 걸세.'),
(34996, 1, 0, '폭풍우 봉우리의 가장 깊고 어두운 동굴에서 온, 꿰뚫는 자 고르목일세! 영웅들이여, 전투에 임하게!'),
(34996, 2, 0, '마음을 단단히 먹게, 영웅들이여. 두 배의 공포, 산성아귀와 공포비늘이 투기장으로 들어온다네!'),
(34996, 3, 0, '다음은, 소개하는 순간 공기마저 얼어붙게 하는 얼음울음일세! 죽이지 않으면 죽을 걸세, 용사들이여!'),
(34996, 4, 0, '끔찍한 괴물들이 무릎을 꿇었네!'),
(34996, 5, 0, '비극이야... 저들은 용감하게 싸웠지만, 노스렌드의 야수들이 승리를 거뒀네. 쓰러진 영웅을 위해 잠시 묵념을 올리세.'),
(34996, 6, 0, '대흑마법사 윌프레드 피즐뱅이 다음 상대를 소환할 걸세. 기다리고 있게나.'),
(34996, 7, 0, '서두르게, 영웅들이여. 악마 군주가 뒤틀린 악마 세계로 차원문을 열기 전에 처치하게!'),
(34996, 8, 0, '윌프레드 피즐뱅을 잃은 일은 안 됐지만, 흑마법으로 장난치는 자들에게는 교훈이 되었을 걸세. 아, 자네는 승리를 거뒀으니 다음 도전을 해야겠지.'),
(34996, 9, 0, '모두 흥분을 가라앉히고 진정하십시오! 이 경기엔 아무 음모도 없었습니다! 저 흑마법사는 얼라이언스와 상관없이 행동한 겁니다. 마상시합은 계속 진행되어야 합니다!'),
(34996, 10, 0, '다음 전투는 은빛십자군에서 가장 센 기사들을 상대해야 하네... 그들을 이겨야만 자신의 가치를 인정받을 걸세.'),
(34996, 11, 0, '좋습니다. 그러시지요. 명예롭게 싸워 주십시오!'),
(34996, 12, 0, '상처뿐인 승리로군. 오늘 받은 손해로 우리 전력은 약해졌네. 이런 어리석은 짓으로 리치 왕 말고 또 누가 이득을 보겠나? 위대한 용사들이 목숨을 잃었네. 무엇을 위해서였나? 진짜 위협은 저 앞에 있네. 리치 왕이 우리 모두를 죽음 안에서 기다린다네.'),
(34996, 13, 0, '함께 힘을 모아야만 마지막 도전을 이겨낼 수 있네. 얼음왕관 심연에서 가장 강력한 스컬지 대리인 둘이 왔네. 무시무시한 발키르, 날개를 단 리치 왕의 전령일세!'),
(34996, 14, 0, '흐흐흐흐... 게임을 시작하자!'),
(34996, 15, 0, '리치 왕에게 큰 타격을 주었군! 그대들은 은빛십자군의 강건한 용사임을 입증했네. 우리는 함께 얼음왕관 성채를 공격하고 남은 스컬지를 물리칠 걸세! 힘을 합친 우리가 이겨내지 못할 도전은 없네!'),
(34996, 16, 0, '아서스! 넌 이미 수적으로 열세다! 서리한을 내려놓아라. 합당한 죽음을 안겨주겠다.'),
(34996, 50, 0, '어서 오게, 용사여. 오늘, 여러 지도자와 동료 앞에서 자신이 얼마나 가치 있는 투사인지 증명할 수 있을 걸세.'),
(34996, 51, 0, '먼저 마상시합의 최고 용사 셋을 상대할 걸세! 이 용감무쌍한 싸움꾼들은 다른 이들을 모두 이기고 마상시합의 최고 수준에 올라선 자들일세.'),
(34996, 52, 0, '시작하게!'),
(34996, 53, 0, '잘 싸웠네! 다음 상대는 은빛십자군의 일원이라네. 그들을 상대로 자신의 무용을 증명해 보게.'),
(34996, 54, 0, '시작해도 좋네!'),
(34996, 55, 0, '잘했네. 오늘 자네의 가치를 잘 보여주었...'),
(34996, 56, 0, '이게 대체 무슨 일이지?'),
(34996, 57, 0, '축하하네, 용사들이여. 예정된 시험이든 뜻밖의 시험이든, 그대들은 모두 이겨냈군.'),
(34996, 58, 0, '이젠 가서 쉬게나. 그대들은 그럴 자격이 있네.'),
(35003, 0, 0, '모두 비행포격선에 올라타게! 대포를 맡도록!'),
(35028, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
(35029, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
