(35048, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
(35049, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
(35050, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
(35051, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
(35052, 6, 0, '%s|1이;가; 생생한 악몽을 불러일으킵니다!'),
(35111, 0, 0, '14번째 줄 구문 오류, 생존하려면 도망쳐라. 수동 모드 가동. *딸깍*'),
(35112, 0, 0, '그만! 난 이미 결정했네. 우리에겐 크롤리가 필요해.'),
(35115, 0, 0, '크롤리는 야수들과 함께 감옥에 있어야 마땅합니다!'),
(35116, 0, 0, '네가 무슨 짓을 저지르고 있는지 알고나 있나?'),
(35116, 1, 0, '우리 계획을 멈추기엔 이미 늦었어.'),
(35116, 2, 0, '누가 내 뒤를 밟지 못하게 해라.'),
(35118, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(35119, 0, 0, '도전할 실력은 있으십니까? 전 봐드리지 않습니다.'),
(35119, 1, 0, '각오 단단히 해라!'),
(35119, 2, 0, '정의의 망치로!'),
(35119, 3, 0, '도전할 실력은 있으십니까? 전 봐드리지 않습니다.'),
(35119, 3, 1, '도전할 실력은 있으십니까? 전 봐드리지 않습니다.'),
(35119, 4, 0, '항복! 제가 졌습니다. 훌륭한 솜씨군요. 이제 집에 가도 되겠습니까?'),
(35119, 5, 0, '%s|1이;가; 빛을 내뿜기 시작합니다. 눈을 가리십시오!'),
(35119, 6, 0, '도전할 실력은 있으십니까? 전 봐드리지 않습니다.'),
(35119, 10, 0, '도전할 실력은 있으십니까? 전 봐드리지 않습니다.'),
(35127, 0, 0, '금방 대령하겠습니다.'),
(35144, 0, 0, '동료가 죽는 모습을 본 %s|1이;가; 분노합니다!'),
(35167, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(35170, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(35175, 0, 0, '음료를 다시 채워줬으면 좋겠어요.'),
(35175, 0, 1, '이 거품 보글 음료수는 정말 맛있군요! 어디서 구하신 거죠?'),
(35175, 1, 0, '또 채워주셔서 고마워요!'),
(35175, 1, 1, '시원한 거품 보글 음료수 한 잔! 마시면 몸에 좋다고 의사가 그러더군요, $n 님.'),
(35175, 2, 0, '욱... 토할 것 같아요. 양동이 좀 주시겠어요?'),
(35175, 2, 1, '이게 마지막 잔이라고. 파티 끝나면 운전을 해야 해.'),
(35175, 3, 0, '아, 머리 아파.'),
(35175, 3, 1, '신발을 더럽혀서 미안하군요.'),
(35175, 4, 0, '같이 춤을 출 고블린이 있으면 좋으련만!'),
(35175, 5, 0, '신나게 춤춰 보자고요!'),
(35175, 5, 1, '최첨단 음악 연주기? 끝내주는군!'),
(35175, 6, 0, '불꽃놀이는 정말 재미있어요!'),
(35175, 6, 1, '호오, 이 포도주는 맛보기였군요!'),
(35175, 7, 0, '내 평생... 가장 멋진... 파티!'),
(35175, 7, 1, '이야, 폭죽 멋진데!'),
(35175, 8, 0, '정말 맛있군요! 다른 것들도 먹어볼 수 있을까요?'),
(35175, 8, 1, '냠냠...!'),
(35175, 9, 0, '고마워요! 배고파서 죽을 지경이었어요!'),
(35175, 9, 1, '손가락도 쪽쪽!'),
(35186, 0, 0, '음료를 다시 채워줬으면 좋겠어요.'),
(35186, 0, 1, '이 거품 보글 음료수는 정말 맛있군요! 어디서 구하신 거죠?'),
(35186, 1, 0, '또 채워주셔서 고마워요!'),
(35186, 1, 1, '시원한 거품 보글 음료수 한 잔! 마시면 몸에 좋다고 의사가 그러더군요, $n 님.'),
(35186, 2, 0, '욱... 토할 것 같아요. 양동이 좀 주시겠어요?'),
(35186, 2, 1, '이게 마지막 잔이라고. 파티 끝나면 운전을 해야 해.'),
(35186, 3, 0, '이제 훨씬 낫군요... 딸꾹!'),
(35186, 3, 1, '고마워요!'),
(35186, 4, 0, '같이 춤을 출 고블린이 있으면 좋으련만!'),
(35186, 5, 0, '고블린 사진처럼 흔들어보세요!'),
(35186, 5, 1, '제 춤 솜씨 어때요, $n 님?'),
(35186, 6, 0, '불꽃놀이는 정말 재미있어요!'),
(35186, 6, 1, '호오, 이 포도주는 맛보기였군요!'),
(35186, 7, 0, '내 평생... 가장 멋진... 파티!'),
(35186, 7, 1, '이야, 폭죽 멋진데!'),
(35186, 8, 0, '정말 맛있군요! 다른 것들도 먹어볼 수 있을까요?'),
(35186, 8, 1, '냠냠...!'),
(35186, 9, 0, '제가 먹어본 전채요리 중에서 단연 최고예요! 조리법을 알고 싶어요, $n 님!'),
(35186, 9, 1, '정말 돈 쓸 줄을 아시는군요! $n 님! 정말 멋져요!'),
(35188, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(35229, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(35230, 1, 0, '늑대인간을 최대한 많이 모아야 하오. 우리를 쫓지 않는 놈은 도망가는 생존자들을 쫓아갈 거요!'),
(35230, 2, 0, '절대로 우리를 잡지 못할 것이다, 빌어먹을 괴물들아!'),
(35257, 0, 0, '난 자유다!'),
(35257, 0, 1, '여기서 나가야지...'),
(35257, 0, 2, '악몽에서 깨어났군!'),
(35257, 0, 3, '돌이 돼 있던 시간도 일한 걸로 쳐 주는 거지?'),
(35257, 0, 4, '저 친구 봉급 올려주라고!'),
(35257, 0, 5, '이런 일을 당하느니 일 안 하고 말겠어!'),
(35257, 0, 6, '때려치울 테다!'),
(35257, 0, 7, '무진장 편안했는데...'),
(35321, 0, 0, '티리온 경.'),
(35321, 1, 0, '내게 너무 많은 걸 바라는군. 야만스러운 놈들의 자제력 따위를 믿고 구경이나 하라니 말이오.'),
(35321, 2, 0, '그럴지도 모르지. 이 계획이 효과 있을지 의심스럽소. 최후의 공격을 펼칠 군대를 준비하는 게 나을 텐데.'),
(35321, 3, 0, '하지만 이 경기를 지켜봐야만 경의 도움을 얻을 수 있다면, 자리를 지키겠소. 당장은 말이오.'),
(35361, 0, 0, '스랄 대족장님, 헬스크림 대군주님. 어서 오십시오.'),
(35361, 1, 0, '이 일의 가치를 언젠가 아셨으면 합니다, 가로쉬 님. 서로 계속 싸운다면 결코 스컬지를 이길 수 없습니다.'),
(35361, 2, 0, '여기에 계시는 동안, 허튼 행동은 안하리라 믿습니다.'),
(35361, 3, 0, '그럼, 이쪽으로 오시지요.'),
(35361, 4, 0, '바리안 폐하. 제이나 님. 와주셔서 감사합니다. 원형경기장에 자리를 마련했습니다.'),
(35361, 5, 0, '저들이 전투 규칙을 반드시 준수하도록 지켜보겠습니다. 관람석의 두 분을 보면 모두 힘을 얻을 것입니다.'),
(35361, 6, 0, '%s|1이;가; 고개를 끄덕이고 손님들에게 따라오라고 손짓합니다.'),
(35361, 7, 0, '얼라이언스와 호드의 투사여! 은빛십자군의 깃발 아래 모인 그대들을 환영한다.'),
(35361, 8, 0, '남쪽에 우리의 목표가 있다. 우리는 그가 거하는 곳, 얼음왕관 성채로 진격해 스컬지의 심장을 도려낼 것이다.'),
(35361, 9, 0, '이 일을 가벼이 여겨서는 안 된다.'),
(35361, 10, 0, '사지 멀쩡한 이를 모두 끌고 나와 대규모 공격을 벌여 봤자, 쓸데없이 우리 용사들만 죽어나갈 뿐이다. 쓰러진 이는 적으로 되살아날 것이다. 아제로스는 언데드의 위협 앞에 속수무책이 될 것이다.'),
(35361, 11, 0, '성공을 위해 우리에게 필요한 건 정예로만 구성된 소규모 타격 부대이다. 바로 그 때문에, 우리는 은빛십자군 마상시합을 열었다.'),
(35361, 12, 0, '이 벽 안에서 그대들은 시험을 받으리라. 그대들의 전투 실력이 노스렌드의 가장 무시무시한 적을 상대하기에 부족함이 없는지, 모든 지도자가 주의 깊게 지켜볼 것이다.'),
(35361, 13, 0, '그대들의 힘, 기술, 무용이 모두 꼼꼼히 평가될 것이다. 이 경기는, 아제로스 최고의 용사들을 가려내는 자리이다.'),
(35361, 14, 0, '승리자는 성채를 공격할 때 그에 걸맞은 자리를 얻으리라. 우리는 악에 굳건히 맞설 것이고, 아서스는 쓰러지리라!'),
(35368, 0, 0, '가로쉬, 여기선 자제해주기 바라네. 보랏빛 성채 때와 같은 상황을 또 만들고 싶진 않네.'),
(35368, 1, 0, '우린 여기에 손님으로 왔네, 가로쉬. 명예롭게 행동하도록.'),
(35368, 2, 0, '초대해줘서 고맙소, 티리온 대영주. 어떤 경기가 펼쳐질지 기대하고 있소.'),
(35368, 3, 0, '현명한 말씀이오.'),
(35368, 4, 0, '가로쉬, 그만!'),
(35368, 5, 0, '물론이오, 티리온 경. 가로쉬의 경거망동을 사과드리오. 다시는 이런 일이 없을 것이오.'),
(35369, 0, 0, '대체 내가 왜 이러는 거지??!'),
(35369, 1, 0, '내 얼굴이! 내 얼굴이 어떻게 된 거야!'),
(35369, 2, 0, '내 손이... 내 손을 보지 마!'),
(35369, 3, 0, '고통을 견딜 수가 없어!'),
(35369, 4, 0, '제발 그만!'),
(35369, 5, 0, '더는 참을 수가 없어!'),
(35372, 0, 0, '푸하! 그건 지도자로서 마땅히 보여줄 모습이었소. 마법사가 방해하기 전에 저 인간 녀석을 죽이지 못해서 유감이오.'),
(35372, 1, 0, '막대기를 들고 툭탁거리면서 무슨 명예를 얻는다는 말이오? 시간만 버릴 뿐이오.'),
(35372, 2, 0, '난 고맙지 않소, 스랄.'),
(35372, 3, 0, '바보같은 말이겠지. 호드는 당신이나 거들먹거리는 왕의 도움따위 없이도 언데드를 쓸어버릴 수 있소.'),
(35372, 4, 0, '흥.'),
(35451, 0, 0, '환영을 그렇게밖에 못하나. 쥐새끼 같은 놈.'),
(35451, 1, 0, '정말 리치 왕의 대리인이 이 한심하기 짝이 없는 마상시합장에서 무릎 꿇었다고 생각했나?'),
(35451, 2, 0, '내 할 일을 끝내러 왔다.'),
(35451, 3, 0, '장난은 여기까지다!'),
(35451, 4, 0, '썩어가는 살점 따위는 방해만 될 뿐이다!'),
(35451, 5, 0, '네놈들 따위를 처리하는 데 뼈는 필요 없다!'),
(35451, 6, 0, '한심하군.'),
(35451, 6, 1, '살점 낭비군.'),
(35451, 7, 0, '안 돼! 또 무릎 꿇을 수는... 없는데...'),
(35456, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(35458, 0, 0, '감사합니다, 대영주님. 도전자 여러분, 소환 의식을 시작하겠어요. 이 의식이 끝나면 무시무시한 파멸의 수호병이 나타날 거예요!'),
(35458, 1, 0, '눈 크게 뜨고 보세요!'),
(35458, 2, 0, '짜잔! 해냈어요! 이 엄청난 능력을 보세요! 소환의 대가, 윌프레드 피즐뱅입니다! 너는 이제 내 부하다, 악마야!'),
(35458, 3, 0, '아니, 그래도 내가 불러냈잖...'),
(35476, 0, 0, '물론 저는 참가자를 위해 악마를 소환하는 역할을 해요. 저는 윌프레드 피즐뱅, 소환의 대가랍니다! 악마들은 제 굳건한 의지에 속박되는 걸 상상만 해도 벌벌 떤다고요!'),
(35476, 0, 1, '곧 온 세상이 윌프레드란 이름을 알 거예요!'),
(35486, 0, 0, '금고에 침입하여 개인 재산을 찾아와야 합니다!'),
(35486, 1, 0, '보관 장치를 열려면 고블린 만능 허리띠의 각 장치를 사용해야 합니다.$B|Tinterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t |Tinterface\\Icons\\INV_Misc_Bomb_07.blp:64|t |Tinterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t |Tinterface\\Icons\\INV_Misc_EngGizmos_swissArmy.blp:64|t |Tinterface\\Icons\\INV_Weapon_ShortBlade_21.blp:64|t'),
(35486, 2, 0, '|cFFFF2222진행률 막대가 100퍼센트가 되면|r 보관 장치가 열립니다.$B|Tinterface\\Icons\\INV_Misc_coin_02.blp:64|t$B실수를 하면 진행률 막대가 내려갑니다.'),
(35486, 3, 0, '행운을 빕니다!'),
(35486, 4, 0, '성공입니다! 개인 재산을 찾았습니다!$B$B|Tinterface\\Icons\\INV_Misc_coin_02.blp:64|t'),
(35501, 0, 0, '호드의 대족장이신 스랄 님과 대군주 가로쉬 헬스크림 님께서 마상시합 광장에 도착하셨습니다! 입구에 이르는 길을 비우십시오!'),
(35501, 1, 0, '대영주 티리온 폴드링께서 마상시합 광장에 모인 청중 앞에서 연설하실 겁니다! 대영주님을 위해 연단까지 길을 내십시오!'),
(35501, 2, 0, '바리안 린 폐하와 여군주 제이나 프라우드무어 님께서 마상시합 광장에 납셨습니다! 길을 비키십시오!'),
(35503, 0, 0, '이곳을... 떠나라...'),
(35503, 0, 1, '이 땅은... 네 것이 아니다...'),
(35503, 0, 2, '돌아가라...'),
(35505, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(35550, 0, 0, '발사!'),
(35550, 0, 1, '방벽을 사수하라! 적에게 한 치도 내주지 마라!'),
(35550, 0, 2, '놈들을 막아라!'),
(35642, 0, 0, '죄송합니다만, 다른 볼일이 있어 이 자리를 떠나야 할 듯합니다. 다음에 또 찾아 주십시오.'),
(35753, 0, 0, '도와주세요! 여깁니다!'),
(35836, 0, 0, '제발 저를 보호해 주십시오!'),
(35836, 0, 1, '고맙습니다!'),
(35836, 0, 2, '이곳은 안전하지 않습니다! 어서 떠나십시오!'),
(35836, 0, 3, '대체 무슨 일이지요? 얼른 도망칩시다!'),
(35836, 0, 4, '늑대인간입니다! 늑대인간이 나타났습니다!'),
(35877, 0, 0, '폴드링, 이제 네게 마땅한 도전이 있으리라.'),
(35877, 1, 0, '폴드링, 네 용사가 쓰러지면 그 영혼은 내가 취하겠다.'),
(35877, 2, 0, '네루비안은 노스렌드의 얼어붙은 황무지 아래에 왕국을 건설했다. 그런데, 멍청하게도 넌 그 왕국 위에 이것저것 세우더군. 바로 내 왕국 위에 말이다.'),
(35905, 0, 0, '당신의 탈것을 이용해 크레난 아라나스를 구해 주십시오.$B|TInterface\\Icons\\inv_misc_groupneedmore.blp:64|t'),
(35906, 0, 0, '크롤리는 야수들과 함께 감옥에 있어야 마땅합니다!'),
(35906, 1, 0, '아라나스를 구출했다! 공격!'),
(35907, 0, 0, '도와주세요! 여깁니다!'),
(36061, 0, 0, '와, 그거 정제된 아즈샤리트인가?'),
(36095, 0, 0, '용사들이여, 살아 있었군! 십자군의 시험에서 상대를 모조리 때려눕혔을 뿐 아니라, 아서스의 계획을 방해하기까지 하다니! 그대들의 노련한 솜씨는 스컬지에 대항하는 강력한 무기가 될 걸세. 잘했네! 은빛십자군 마법사가 그대들을 지상으로 보내 줄 걸세!'),
(36095, 1, 0, '동료가 죽는 모습을 본 %s|1이;가; 분노합니다!'),
(36130, 0, 0, '어설픈 $r 녀석의 소환인가? 믿을 수 없군. 갈 데까지 갔거나 바보인 게지. 이것이 네 마지막 실수가 될 거다.'),
(36136, 0, 0, '작은 수레를 밀어야 해!'),
(36136, 1, 0, '얼굴이 다 젖었잖아.'),
(36136, 1, 1, '이거... 마시는 건가?'),
(36136, 1, 2, '입에서 축축한 맛이 나!'),
(36136, 1, 3, '와, 거참 무겁겠는데.'),
(36156, 0, 0, '돌연변이 고블린의 촉수가 떨어져 나가 땅 위를 기어갑니다!'),
(36213, 0, 0, '중얼거리지 말고 닥쳐! 이 얼간아!'),
(36217, 0, 0, '내가 지켜보고 있단 걸 명심하시오, 파라넬.'),
(36217, 1, 0, '당신을 지켜 주는 누더기골렘은 이제 없어. 비밀스러운 수작도, 어둠 속에서 책략을 꾸미는 것도 끝이야.'),
(36217, 2, 0, '내 허락 없이 손끝 하나라도 까딱하면, 이 연구실을 폐쇄하겠소. 강제로.'),
(36217, 3, 0, '두고 보면 알겠지.'),
(36217, 4, 0, '저 썩어 문드러진 놈이 입 닥치게 해라!'),
(36231, 0, 0, '화약 냄새 나는 통이다...'),
(36231, 0, 1, '으아아!!!! 이 안에서는 안 보여!'),
(36231, 0, 2, '어어... 이리 와! 없애버릴 거야!'),
(36231, 0, 3, '느낌이 안 좋다...'),
(36231, 0, 4, '이상한 기분인데...'),
(36231, 0, 5, '어어... 이거 꽤 아프겠다...'),
(36289, 0, 0, '해치지 마세요! 여동생을 찾고 있었어요! 애쉴리가 이 집 안에 있었던 것 같단 말이에요!'),
(36294, 0, 0, '누가 감히 코로스 깃발 건드리는 거지!?'),
(36294, 1, 0, '이 약삭빠른 도둑놈! 코로스가 찾아낸다! 코로스가 뭉개버린다!'),
(36296, 0, 0, '저들이 내가 누군지와 왜 이 일을 하는지 말해주려고 귀찮게 하든가?'),
(36296, 1, 0, '... 아니면 저들이 다른 모든 이들에게 하듯 자네를 이용하는 건가?'),
(36296, 2, 0, '뭐 알게 뭔가. 이젠 이 일을 끝내야 할 때이네.'),
(36296, 3, 0, '백스터! 이리 와서 돕거라! 어서!'),
(36296, 4, 0, '프라이, 시간 됐다! 공격해!'),
(36296, 5, 0, '... 부디 날 미천한 존재로 여기지 말게.'),
(36297, 0, 0, '히이이익!'),
(36297, 1, 0, '어, $n, 너였군. 그렇게 날 놀라게 하지 좀 마.'),
(36461, 0, 0, '이 고양이를 데려가야겠군. 아주 완벽한 미끼가 될 거야. 이제 죽을 준비나 해라, 멍청아!'),
(36476, 0, 0, '%s|1이;가; 독구름을 뿜어냅니다!'),
(36476, 1, 0, '%s|1이;가; 당신을 쫓습니다! 도망가세요!'),
(36477, 0, 0, '우리 일을 방해하게 둘 순 없어! 이크, 저놈들을 처리해!'),
(36477, 1, 0, '이 부분은 아마 쓸모가 있을 거야.'),
(36477, 1, 1, '팔과 다리가 부족해! 네가 보태준다니 고마워!'),
(36477, 2, 0, '이제 그만 돌아다녀! 저놈들을 날려버릴 동안 가만히 있으라고!'),
(36477, 3, 0, '%s|1이;가; 빠른 속도로 지뢰를 만들어냅니다!'),
(36477, 4, 0, '어서! 저놈들이 가까이 있을 때 독맛을 보여줘!'),
(36477, 5, 0, '아니, 저놈! 저놈이야! 저놈 잡아!'),
(36477, 5, 1, '마음이 바뀌었어, 대신 저놈을 잡아!'),
(36477, 5, 2, '왜 그놈을 공격해? 더 위험한 놈은 저기 있는데! 이 바보!'),
(36477, 6, 0, '잠깐! 멈춰! 제발, 죽이지 마! 다 얘기할게!'),
(36477, 7, 0, '네가 찾는 건 주인님의 보금자리에 있지만, 들어가려면 티라누스를 이겨야 할 거야. 투영의 전당에서 서리한을 찾을 수 있어. 거기... 거기에 진실이 있어.'),
(36477, 8, 0, '진짜야. 진짜야. 맹세해! 제발, 죽이지 마!!'),
(36477, 9, 0, '어억.. 안 돼!!'),
(36478, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(36494, 0, 0, '쥐방울만한 쪼끄만 존재들, 가프로스트에게 맛난 거 가져왔다!'),
(36494, 1, 0, '간식으로 남겨놔야지. 나중에 먹게.'),
(36494, 1, 1, '저건 아마... 지금 먹으면 맛없을 거다. 바보 가프로스트! 나쁘다! 나빠!'),
(36494, 2, 0, '가프로스트 커다란 속옷 안 보이면 좋겠다. 두목님 나중에 창피하지 않게.'),
(36494, 3, 0, '도끼 너무 약하다. 가프로스트 고쳐서... 너... 뭉갠다.'),
(36494, 4, 0, '조그만 파리, 가프로스트 지겹다. 이제 너 뼛속까지 얼어붙는다!'),
(36497, 0, 0, '드디어, 사로잡고 말았군요!'),
(36497, 1, 0, '제련할 때 써 드리겠습니다.'),
(36497, 1, 1, '또 다른 영혼이 힘을 더하는군요!'),
(36497, 2, 0, '포식자가 기다립니다...'),
(36497, 3, 0, '영혼의 소용돌이가 손짓하지 않습니까!'),
(36497, 4, 0, '몸과 영혼을 분리해 드리지요.'),
(36502, 0, 0, '감히 영혼의 지배자를 바라보다니? 집어삼켜 주마, 네놈을 통째로!'),
(36502, 1, 0, '감히 영혼의 지배자를 바라보다니? 집어삼켜 주마, 네놈을 통째로!'),
(36502, 2, 0, '지옥으로 떨어져라!'),
(36502, 2, 1, '저주받아라, 영원히!'),
(36502, 4, 0, '지옥으로 떨어져라!'),
(36502, 4, 1, '저주받아라, 영원히!'),
(36502, 5, 0, '영혼이 삼켜지는 걸 막을 수는 없다! 너희는 그저 시간을 조금 늦췄을 뿐이다.'),
(36502, 7, 0, '영혼이 삼켜지는 걸 막을 수는 없다! 너희는 그저 시간을 조금 늦췄을 뿐이다.'),
(36502, 8, 0, '고통! 번뇌! 혼돈! 일어나라, 먹어치워라!'),
(36502, 9, 0, '고통! 번뇌! 혼돈! 일어나라, 먹어치워라!'),
(36502, 10, 0, '고통! 번뇌! 혼돈! 일어나라, 먹어치워라!'),
(36502, 13, 0, '%s|1이;가; 울부짖는 영혼을 시전합니다!'),
(36502, 14, 0, '%s|1이;가; |cFFFF0000영혼 방출|r을 시작합니다!'),
(36502, 15, 0, '%s|1이;가; |cFFFFFF00비춰진 영혼|r을 시전합니다!'),
(36597, 0, 0, '그러니까 성스러운 빛이 자랑하던 정의가 마침내 왔다 이건가? 폴드링, 서리한을 내려놓고 자비라도 애걸하라는 건가?'),
(36597, 1, 0, '곧 깨달으리라. 내 일이 끝나면, 너는 자비를 구걸하겠지. 나는 거부할 테고. 고뇌에 찬 네 비명은 풀려난 내 힘에 대한 서약이 되리라...'),
(36597, 2, 0, '폴드링, 너는 살려서 최후를 지켜보게 하겠다. 이 비참한 세상이 내 생각대로 만들어지는 모습을 빛의 가장 위대한 용사가 놓치게 하고 싶지 않다.'),
(36597, 3, 0, '오라, 영웅들이여. 너희 분노로 나를 채워라!'),
(36597, 4, 0, '얼어붙은 껍질만 남을 때까지 네놈을 얼려주마.'),
(36597, 5, 0, '너를 둘러싼 세상이 무너지는 것을 지켜보아라!'),
(36597, 6, 0, '발키르여, 네 주인이 부르노라!'),
(36597, 7, 0, '서리한이 굶주렸다...'),
(36597, 8, 0, '서리한이여, 나에게 복종하라!'),
(36597, 9, 0, '서리한은 쓰러진 네 동료의 영혼으로 배를 채운다!'),
(36597, 10, 0, '희망이 사라진다...'),
(36597, 10, 1, '최후의 순간이다!'),
(36597, 11, 0, '비극적인 종말을 맛보아라.'),
(36597, 12, 0, '%s|1이;가; 파멸을 시전합니다!'),
(36597, 13, 0, '|TInterface\\Icons\\ability_creature_disease_02.blp:16|t |cFFBC05FF괴저 역병|r에 감염되었습니다! |Tinterface\\Icons\\ability_creature_disease_02.blp:16|t'),
(36597, 14, 0, '어떤 의문도 남지 않았다. 어떤 의심도 없다. 너희는 아제로스의 가장 위대한 용사들이다. 너희 앞에 놓아둔 모든 도전을 극복해 내었다. 가장 강력한 종들이 너희의 무자비한 살육 앞에 쓰러졌지... 너희가 억눌렀던 분노 앞에 말이다...'),
(36597, 15, 0, '진정으로 정의에 이끌렸단 말이냐? 궁금하구나...'),
(36597, 16, 0, '폴드링, 훈련을 잘 시켰구나. 역사상 가장 뛰어난 군대를 데려오다니... 바로 내 손에 말이다. 내가 계획한 대로구나! 의도는 아니었겠지만, 희생물을 바쳤으니 합당한 보상이 있으리라.'),
(36597, 17, 0, '이제 그들을 죽음에서 일으켜 스컬지의 주인으로 만드는 광경을 지켜보아라. 이 세계를 혼돈과 파괴로 덮을 자들이다. 그들이 직접, 아제로스의 몰락을 가져오리라. 그리고 가장 먼저 네놈부터 처리하리라.'),
(36597, 18, 0, '상황이 참 재미있구나.'),
(36597, 19, 0, '이럴 수가...'),
(36597, 20, 0, '양 앞에 선 사자와 같은 나를 두려워하지 않는구나.'),
(36597, 21, 0, '두려워할 수가 없겠지...'),
(36612, 0, 0, '필멸자들아, 이건 시작이자 끝이다. 주인님의 성소에는 아무도 들어갈 수 없다!'),
(36612, 1, 0, '스컬지가 죽음과 파괴의 무리가 되어 이 세상을 쓸어버리리라!'),
(36612, 2, 0, '뼈 폭풍을 받아라!'),
(36612, 3, 0, '뼈로 묶어주마!'),
(36612, 3, 1, '못 벗어난다!'),
(36612, 3, 2, '탈출할 길은 죽음뿐이다!'),
(36612, 4, 0, '뼈를 더 바쳐라!'),
(36612, 4, 1, '지옥으로 사라져라!'),
(36612, 5, 0, '어둠만이... 보이는구나.'),
(36612, 6, 0, '주인님의 분노가 나를 타고 흐른다!'),
(36612, 7, 0, '%s|1이;가; 소용돌이치는 뼈 폭풍을 일으킵니다!'),
(36624, 1, 0, '처음 봤을 때부터 용이 벼려낸 검임을 알았습니다.'),
(36624, 2, 0, '하지만, 정말일까요? 이 검이...'),
(36624, 3, 0, '반드시 은빛 서약단에 복원된 쿠엘델라를 가져다주겠다고 맹세한다.'),
(36626, 0, 0, '나빠! 너 구리구리 죽였어! 너 싫어!'),
(36626, 1, 0, '노는... 거야?'),
(36626, 2, 0, '주인님의 분노가 나를 타고 흐른다!'),
(36626, 3, 0, '%s|1이;가; 가스 포자를 퍼뜨립니다!'),
(36626, 4, 0, '나 속이 안 좋아...'),
(36626, 5, 0, '%s|1이;가; |cFFFF7F00자극적인 파멸의 역병|r을 시전합니다!'),
(36626, 6, 0, '나빠! 너 구리구리 죽였어! 너 싫어!'),
(36626, 7, 0, '아빠, 내가 했어!'),
(36626, 7, 1, '나빠, 나빠, 나빠!'),
(36626, 8, 0, '이제 안 놀거야!'),
(36626, 9, 0, '아... 빠...'),
(36627, 0, 0, '으응? 예삐가? 안돼애애애애애애애!!!'),
(36627, 1, 0, '우이이이이이!'),
(36627, 2, 0, '%s|1이;가; 독액 뿌리기를 시전합니다!'),
(36627, 3, 0, '끈적 끈적!'),
(36627, 4, 0, '|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s|1이;가; |cFFFF0000불안정한 수액괴물 폭발|r을 시전합니다!'),
(36627, 5, 0, '나 화나서 응가 나왔어. 빵하고 터질 거야!'),
(36627, 6, 0, '아빠가 너가지고 새 장난감 만들 거다!'),
(36627, 6, 1, '내가 망가뜨려었지...'),
(36627, 7, 0, '코 잘 시간이다!'),
(36627, 8, 0, '나쁜 소식이야, 아빠...'),
(36627, 9, 0, '|TInterface\\Icons\\ability_creature_disease_02.blp:16|t당신은 |cFF00FF00돌연변이 전염병|r에 걸렸습니다!'),
(36642, 1, 0, '이 검의 모양이나 무늬는 용이 벼려낸 검임을 암시합니다. 마침내 해답을 얻은 셈이군요.'),
(36642, 2, 0, '이토록 오랜 세월 후에, 정말 이 검이...'),
(36642, 3, 0, '쿠엘델라가 선리버를 위해 복원되도록 하는 일은 우리 손에 달렸습니다.'),
(36648, 0, 0, '저 악마 녀석들은 목표를 이루지 못할 것이다! 호드에게 힘과 명예를!'),
(36648, 1, 0, '침입자들이 달아났다! 힘과 명예를 호드에게!'),
(36649, 0, 0, '아주어고스를 구했는지는 모르나, $r, 네 목숨은 여기서 끝이다.'),
(36656, 1, 0, '여기는 리치 왕의 하수인이 올 곳이 아니다!'),
(36658, 0, 0, '다른 존재가 그를 대신하리라. 시간 낭비 마라.'),
(36658, 1, 0, '쓸모없는 놈! 네겐 죽음뿐이다!'),
(36658, 2, 0, '주인님이 계신 성소에 그렇게 쉽게 들여보내리라고는 생각지 마라. 용기가 있다면 쫓아와 봐라.'),
(36658, 3, 0, '추격해도 소용없다, 침입자들아. 리치 왕께서 언데드 군대를 내게 주셨다! 똑똑히 보아라!'),
(36658, 4, 0, '끈질긴 놈들! 주인님 계신 근처도 못 갈 것이다. 병사들아, 저놈들을 해치워라!'),
(36658, 5, 0, '서릿발송곳니, 굴 안으로 몰아라! 산 채로 묻어버려라!'),
(36658, 6, 0, '아아. 용감하고 용감한 모험가들아, 참견도 이제 끝이다. 네놈들 뒤에 있는 굴에서 뼈와 칼이 부딪치는 소리가 들리는가? 네놈들에게 곧 닥칠 죽음의 소리다.'),
(36658, 7, 0, '하하하, 어중이떠중이치고는 꽤 놀라운걸. 네놈을 처리하고 나면 주인님의 칼이 네 영혼으로 잔치를 벌이리라. 죽어라!'),
(36658, 8, 0, '리치 왕을 실망시키지 않겠다. 끝장을 내 주마!'),
(36658, 9, 0, '정말 꼴불견이로구나. 죽는 게 낫겠다.'),
(36658, 9, 1, '네놈이 숨 쉬는 공기가... 아깝구나.'),
(36658, 10, 0, '말도 안 돼... 서릿발송곳니... 경고를...'),
(36658, 11, 0, '서릿발송곳니, 이놈을 처치해라!'),
(36658, 12, 0, '서리고룡 서릿발송곳니가 $n|1을;를; 노려보며 얼음 공격을 준비합니다!'),
(36658, 13, 0, '힘이... 넘쳐흐른다!'),
(36658, 14, 0, '%s|1이;가; 울부짖자 어둠의 힘이 쇄도합니다!'),
(36669, 0, 0, '얼굴을 보니 마음이 놓입니다, 밀사여. 크라서스가 고대의 용이 벼려낸 검이라는 책을 우리에게 하나 내줬습니다.'),
(36669, 1, 0, '여기 책이 있습니다. 무슨 일이 벌어지는 건지 선리버에서 눈치채기 전에 반드시 이 책을 얼음왕관에 있는 칼라디스 브라이트스피어에게 가져다주십시오.'),
(36669, 2, 0, '어서 움직이십시오! 자기들이 찾는 정보를 우리가 쥐고 있다는 걸 알면, 선리버 놈들은 곧바로 행동을 개시할 겁니다.'),
(36670, 0, 0, '늦었군요, 밀사여. 아니, 변명은 듣지 않겠습니다. 이 임무는 너무나도 중요하니까요.'),
(36670, 1, 0, '우리의 대표자가 고룡쉼터 사원에서 가져온 고서입니다. 당장 이걸 미랄리온 선블레이즈에게 가져가십시오.'),
(36670, 2, 0, '뒤를 조심하십시오, 밀사여. 이 책의 가치를 다시 알려 드릴 필요는 없겠죠. 이걸 차지할 수만 있다면 은빛 서약단이 무슨 짓이든 하리란 것도 잘 아시리라 믿습니다.'),
(36678, 0, 0, '그냥 평범한 가스 구름 같지만, 잘 보세요. 평범한 가스 구름이 아니거든요!'),
(36678, 1, 0, '오, 구린속. 언제나 제일 좋아했어. 썩은얼굴 다음으로 말이야. 좋은 소식이라면 네가 가스를 많이 남겨서 내가 맛볼 수 있다는 거야!'),
(36678, 2, 0, '끝내주는 소식이에요, 여러분! 수액이 다시 나오는군요!'),
(36678, 2, 1, '좋은 소식이에요, 여러분! 독성 수액 배출관을 고쳤어요!'),
(36678, 3, 0, '끔찍한 소식이에요, 여러분. 썩은얼굴이 죽었답니다. 그런데 끝내주는 소식도 있어요, 여러분! 썩은얼굴은 죽어서 수액을 남겼답니다! 아니? 제가 이런 명언을 알다니... 놀랄 노자예요!'),
(36678, 4, 0, '좋은 소식이에요, 여러분! 아제로스의 모든 생명체를 파괴할 역병을 완성했어요!'),
(36678, 5, 0, '%s|1이;가; 불안정한 실험을 시작합니다!'),
(36678, 6, 0, '수액괴물 둘이 방 하나에 있네요. 짜잔! 정말 재미있겠지요?'),
(36678, 7, 0, '흠, 아무 느낌도 없군요. 엥?! 이건 어디서 온 거지요?'),
(36678, 8, 0, '이 맛은... 체리군요! 오! 이런 실례!'),
(36678, 9, 0, '|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s|1이;가; |cFF00FF00유연한 끈적이|r를 시전합니다!'),
(36678, 10, 0, '%s|1이;가; |cFFFF7F00숨막히는 가스탄|r을 시전합니다!'),
(36678, 11, 0, '흠, 흥미롭군요...'),
(36678, 11, 1, '이건 또 의외로군요!'),
(36678, 12, 0, '끝내주는 소식이에요, 여러분!'),
(36678, 13, 0, '나쁜 소식이에요, 여러분... 전 살 것 같지 않아요...'),
(36689, 0, 0, '네 생각이 틀렸다, 도마뱀 같은 녀석.'),
(36689, 1, 0, '임무는 끝났군.'),
(36723, 0, 0, '너는 리치 왕을 마주할 자격이 없다!'),
(36723, 1, 0, '주인님, 실패했습니다...'),
(36764, 0, 0, '당신이 마치 천사 같아 보이는군요... 제 기분 모르실 겁니다.'),
(36764, 0, 1, '극도로 지친 %s|1이;가; 곡괭이를 질질 끌며 다가옵니다.'),
(36764, 0, 2, '크게 한턱내야겠군요. 감사합니다, 친구여.'),
(36764, 0, 3, '살아서든 죽어서든 이 은혜는 꼭 갚겠습니다. 반드시 말입니다.'),
(36764, 0, 4, '채석장 입구로 돌아가겠습니다. 절 위해 몇 놈 더 혼내 주세요.'),
