(36772, 0, 4, '채석장 입구로 돌아가겠습니다. 절 위해 몇 놈 더 혼내 주세요.'),
(36773, 0, 0, '당신이 마치 천사 같아 보이는군요... 제 기분 모르실 겁니다.'),
(36773, 0, 1, '극도로 지친 %s|1이;가; 곡괭이를 질질 끌며 다가옵니다.'),
(36773, 0, 2, '크게 한턱내야겠군요. 감사합니다, 친구여.'),
(36773, 0, 3, '살아서든 죽어서든 이 은혜는 꼭 갚겠습니다. 반드시 말입니다.'),
(36773, 0, 4, '채석장 입구로 돌아가겠습니다. 절 위해 몇 놈 더 혼내 주세요.'),
(36774, 0, 0, '너희 선리버 추종자들은 다 똑같은 놈들이야.'),
(36774, 0, 1, '쉽게 도망칠 순 없을 게다!'),
(36776, 0, 0, '목숨을 부지하고 도망칠 수 있을 줄 알았더냐?'),
(36776, 0, 1, '우릴 이 도시 밖으로 몰아낼 순 없다, 은빛 서약단 폭력배 같으니!'),
(36789, 0, 0, '영웅들이여, 나를 도와다오. 더는... 더는 저들을 붙들어 둘 수 없다. 이 상처를 치유해다오!'),
(36789, 1, 0, '에메랄드의 꿈으로 가는 차원문을 열어두었다. 너희의 구원은 그 안에 있다...'),
(36789, 2, 0, '힘이 돌아오고 있다. 영웅들이여, 계속 싸워라!'),
(36789, 3, 0, '오래 버티진 못하겠다.'),
(36789, 4, 0, '오래 버티진 못하겠다.'),
(36789, 5, 0, '오래 버티진 못하겠다.'),
(36789, 6, 0, '오래 버티진 못하겠다.'),
(36789, 7, 0, '다시 힘을 얻었다! 이세라여, 더러운 생명들에 안식을 내릴 수 있도록 은혜를 베푸소서!'),
(36794, 1, 0, '쓸모없는 놈! 네겐 죽음뿐이다!'),
(36794, 2, 0, '주인님이 계신 성소에 그렇게 쉽게 들여보내리라고는 생각지 마라. 용기가 있다면 쫓아와 봐라.'),
(36823, 0, 0, '아서스를 심판하러 왔나? 리치 왕의 최후를 보러?'),
(36823, 1, 0, '먼저 서리한의 손아귀에서 탈출해야 한다. 그렇지 않으면 나처럼 저주받아 이 가증스러운 검 안에 영원히 갇히리라.'),
(36823, 2, 0, '이 고통받은 영혼들을 처리하도록 나를 도와라! 함께 서리한의 지배를 늦추고 안에서부터 리치 왕을 약하게 하자!'),
(36838, 0, 0, '|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t|cFFBC0000 과열 |r|Tinterface\\Icons\\Spell_Fire_Flameshock.blp:20|t'),
(36839, 0, 0, '|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t|cFFBC0000 과열 |r|Tinterface\\Icons\\Spell_Fire_Flameshock.blp:20|t'),
(36845, 0, 0, '정령이 화내며 공격합니다!'),
(36853, 8, 0, '사라져라!'),
(36853, 11, 0, '%s|1이;가; 분노에 휩싸여 광폭해집니다!'),
(36855, 0, 0, '여기까지 찾아올 수 있었던 것은 네가 앞 못 보는 저주에 걸린 이 세상에서 진정한 눈을 가진 몇 안 되는 자이기 때문이다.'),
(36855, 1, 0, '이 세계에 수의처럼 드리워진 안개를 헤치고 세상을 보며 진정한 힘이 어디에 있는지 깨달으리라.'),
(36855, 2, 0, '네 조잡한 손을 들여다보아라. 힘줄과 살덩이, 그 안에 흐르는 어두운 피까지.'),
(36855, 3, 0, '약하고 절뚝거리는 결함일 뿐이다... 창조주가 창조물에게 한 장난인 셈이지.'),
(36855, 4, 0, '자신이 부족한 존재임을 빨리 깨달을수록, 그걸 초월하는 자리에 더 빨리 오르리라.'),
(36855, 5, 0, '주인님을 통하면, 모든 것이 가능하도다. 그분의 능력은 무한하며, 의지는 굽힘이 없느니라.'),
(36855, 6, 0, '주인님에 맞서는 자는 완전히 파괴되리라. 주인님을 섬기는 자는... 마음과 영혼을 다 바쳐 온전하게, 의심 없이 섬기는 자는 이해할 수 있는 경지를 넘어 저 높은 곳에 이르렀도다.'),
(36855, 7, 0, '이게 무슨 소란이지? 감히 이 신성한 땅을 지나가려 해? 여기가 마지막 숨을 거둘 곳이 되리라!'),
(36855, 8, 0, '그만! 내 손으로 직접 처리해야겠구나!'),
(36855, 9, 0, '%s의 마나 방벽이 가물거리며 사라집니다!'),
(36855, 10, 0, '내 의지에 저항하기에는 나약하고 무능하구나!'),
(36855, 11, 0, '축복을 주노니 이 침입자들에게 주인님의 힘을 맛보여 주어라!'),
(36855, 12, 0, '신실한 자들이여, 육신의 구속에서 해방하노라!'),
(36855, 13, 0, '일어나라, 순수한 모습을 기뻐하라!'),
(36855, 14, 0, '부질없는 짓임을 아직도 깨닫지 못했느냐?'),
(36855, 14, 1, '어둠을 받아들여라... 영원의 어둠을.'),
(36855, 15, 0, '장난을 너무 오래 했나 보구나!'),
(36855, 16, 0, '모두 주인님의 계획이다... 너도 죽음을 피할 순 없다...'),
(36856, 0, 0, '운이 좋으시네요. 필요하시다는 그걸 막 빨랫감으로 받았거든요.'),
(36856, 1, 0, '저기 빨랫감이랑 물동이 보이시죠? 뭐가 필요한지 부를 테니, 찾아서 빨래통 안에 넣어 주세요. 준비되셨죠?'),
(36856, 2, 0, '어서요, 셔츠를 넣어 주세요!'),
(36856, 3, 0, '이제 빤... 아, 아니, ''속옷''을 넣어 주세요!'),
(36856, 4, 0, '빨래통에 물을 더 넣어야 해요!'),
(36856, 5, 0, '빨래통 안에 바지를 던져넣으세요!'),
(36856, 6, 0, '당신이랑 친하게 지내야겠네요.'),
(36856, 6, 1, '잘했다!'),
(36856, 6, 2, '바로 그렇게 하는 거죠!'),
(36856, 6, 3, '하얗게, 깨끗하게!'),
(36856, 6, 4, '잘하셨어요. 저 얼룩의 정체가 뭔진 알고 싶지 않네요.'),
(36856, 6, 5, '아쿠아노스가 힘든 모양이에요!'),
(36856, 7, 0, '아니, 아니죠! 그렇게 하면 안 되죠. 처음부터 전부 다시 세탁하게 지금 가서 세제를 더 가져와야겠어요!'),
(36856, 8, 0, '아쿠아노스, 빨랫감을 그렇게 높이 던지면 안 돼! 자기 바지가 분수대에 들어간 걸 보면 에이타스 선리버가 무슨 표정을 짓겠어?!'),
(36856, 9, 0, '여럿이 함께 일하니 정말 빠르죠? 깨끗한 빨래 중에 필요한 걸 가져가세요. 볼일이 끝나면 돌려주는 거 잊지 마시고요.'),
(36913, 0, 0, '고통으로 몸부림쳐라... 고통이 네 힘을 누르게 하라...'),
(36913, 0, 1, '삶의 끈을 놓아버려라...'),
(36913, 0, 2, '리치 왕을 막을 수는 없다...'),
(36913, 0, 3, '주인님의 뜻은 반드시 관철되리라...'),
(36913, 0, 4, '주인님의 분노에서 벗어날 수는 없다...'),
(36913, 0, 5, '죽음이 너를 삼키리라...'),
(36913, 0, 6, '굴복하라... 죽음의 차가운 손아귀에...'),
(36931, 0, 0, '이런 놀음도 이제 지겹군!'),
(36931, 1, 0, '바인! 네놈이 나타나다니! 붙잡아라!'),
(36931, 2, 0, '한심한 네 아비처럼 치욕스러운 죽음을 맞아라.'),
(36931, 3, 0, '이게 끝이라고 생각하지 마라, 바인...'),
(36937, 0, 0, '자넬 구원하러 왔어... 물론 공짜는 아냐!'),
(36937, 0, 1, '자네를 치료해 주지!'),
(36937, 0, 2, '내 치유 실력은 어딜 가나 알아주거든!'),
(36937, 0, 3, '하늘의 생명력을!'),
(36937, 0, 4, '아침에 구원하는 것만큼 상큼한 게 없지.'),
(36937, 0, 5, '자네에게 필요한 게 여기 있어!'),
(36937, 0, 6, '하던 일 계속 해.'),
(36937, 0, 7, '저번에는 6미터도 더 못 가지 않았어?'),
(36937, 1, 0, '요금은 월급에서 제할 거야.'),
(36937, 1, 1, '빛은 금이야, 친구.'),
(36937, 1, 2, '부활 준비!'),
(36937, 1, 3, '이제 업무 중에 눕지 말라고.'),
(36937, 1, 4, '빚이란 게 원래 쉽게 갚을 수 있는 게 아냐.'),
(36937, 1, 5, '그만 가 봐.'),
(36937, 1, 6, '자넨 벌써 3번째야, 친구. 다음부터는 요금이 오른다고.'),
(36937, 1, 7, '이번엔 위험 수당이 청구될 거야, 친구.'),
(36939, 0, 0, '호드의 아들딸이여, 일어나라! 오늘 우리는 증오하던 적과 전투를 벌이리라! 록타르 오가르!'),
(36939, 1, 0, '코르크론, 출발!'),
(36939, 2, 0, '저게 뭐지? 저 멀리서 무언가 다가온다.'),
(36939, 3, 0, '얼라이언스 비행포격선이다! 전원 집합!'),
(36939, 4, 0, '사울팽이다. 당장 응답하라!'),
(36939, 5, 0, '우리가 할 일을 당장 알려 주마. 코르크론, 저들을 처단하라!'),
(36939, 6, 0, '드워프여, 이건 네가 낄 싸움이 아니다. 물러나지 않으면 그 배를 부술 수 밖에 없다.'),
(36939, 7, 0, '감히 내 배에 올라와? 순식간에 죽여주마.'),
(36939, 8, 0, '약탈자, 하사관, 공격하라!'),
(36939, 9, 0, '도끼투척병, 더 빨리 던져라!'),
(36939, 10, 0, '로켓병, 재장전!'),
(36939, 11, 0, '선체가 공격받고 있다. 전투마법사를 불러 저 대포를 막아버려라!'),
(36939, 12, 0, '얼라이언스는 기가 꺾였다. 리치 왕을 향해 전진하라!'),
(36939, 13, 0, '상황을 수습하라! 저기 불을 꺼라. 호드는 아직 끝나지 않았다!'),
(36948, 0, 0, '속도를 올려라! 제군들, 곧 운명과 마주할 것이다!'),
(36948, 1, 0, '꼭 붙들어라!'),
(36948, 2, 0, '도대체 저게 뭐지? 선원, 망원경을 주게!'),
(36948, 3, 0, '수염 떨어질 뻔했네! 호드가 빠른 속도로 접근 중이다!'),
(36948, 4, 0, '대피하라! 포를 잡아라!'),
(36948, 5, 0, '비열한 놈들! 기습 공격을 하다니!'),
(36948, 6, 0, '내가 낄 싸움이 아니라고? 자기를 얼마나 대단하게 생각하는지 모르겠지만, 난 아서스에게 갚아야 할 원수가 있으니 방해할 생각은 마라! 총공격! 발사! 발사!'),
(36948, 7, 0, '당장 그 고철 덩어리 치워라. 그러지 않으면 날려버리겠다! 여기서 호드가 할 일은 없다.'),
(36948, 8, 0, '이건 뭐지?! 이 아이언포지의 후예가 이끄는 배를 그냥 차지하지는 못한다!'),
(36948, 9, 0, '해병, 하사관, 공격하라!'),
(36948, 10, 0, '소총병, 더 빨리 쏴라!'),
(36948, 11, 0, '박격포 부대, 재장전!'),
(36948, 12, 0, '선체가 공격받고 있다. 마술사를 불러 저 대포를 막아버려라!'),
(36948, 13, 0, '악당 놈들, 분명히 경고했다! 형제자매여, 전진!'),
(36948, 14, 0, '바틀릿 선장, 여기서 벗어나자! 피해가 너무 커 계속 항해할 수 없다!'),
(36954, 0, 0, '도망칠 곳은 없다... 너는 이제 나의 것이다!'),
(36954, 1, 0, '제이나, 네가 믿었던 대로 동맹이 왔구나. 너희 모두 스컬지의 강력한 하수인이 되리라.'),
(36954, 2, 0, '실바나스, 같은 실수를 두 번 하지는 않을 것이다. 이번에는 탈출할 수 없다. 모두 죽음으로 나를 섬기리라!'),
(36954, 3, 0, '죽음의 차디찬 손아귀가 기다린다.'),
(36954, 4, 0, '무덤의 한기에 굴복하라.'),
(36954, 5, 0, '또 막다른 곳이다.'),
(36954, 6, 0, '도망칠 방법은 없다!'),
(36954, 7, 0, '종말을 안겨주마. 망각으로... 사라져라.'),
(36954, 8, 0, '얼마나 더 싸울 수 있겠느냐?'),
(36954, 9, 0, '일어나라, 부하들아! 지나가게 하지 마라!'),
(36954, 10, 0, '잡아라, 부하들아. 나에게 그놈들 시체를 가져와라.'),
(37007, 0, 0, '주인님의 성소를 어지럽혔구나!'),
(37007, 0, 1, '내가... 깨어난다!'),
(37007, 0, 2, '거기... 누구냐?'),
(37058, 0, 0, '나도 그렇다, 그림토템.'),
(37058, 1, 0, '네놈들은 겁쟁이의 독과 헬스크림의 분노에 기대 우리 아버지를 꺾었지.'),
(37058, 2, 0, '이번엔 어쩔 테냐?'),
(37058, 3, 0, '아니, 끝났다.'),
(37058, 4, 0, '다 끝났네. 이제 멀고어는 그림토템 부족의 증오에 시달리지 않을 게야.'),
(37058, 5, 0, '썬더 블러프에서 다시 보세.'),
(37080, 0, 0, '감사합니다! 이곳부터는 혼자 갈 수 있습니다.'),
(37080, 0, 1, '당신은 제 생명의 은인입니다! 아이언포지를 위하여!'),
(37080, 0, 2, '아... 이제 좀 나아졌군요. 당신께 빚을 졌습니다.'),
(37108, 0, 0, '정령들이 우릴 거부하고 있어. 그리크니르가 도와줄 거야.'),
(37119, 0, 0, '최후의 순간이 왔다. 여기에서 일어나는 일은 세대를 거듭하여 전해지리라. 결과가 어떻든간에 우리가 명예롭게 싸웠음을 알리라. 자유와 우리 백성을 위해 싸웠음을!'),
(37119, 1, 0, '기억하게. 공포는 이 저주받은 전당에서 가장 위험한 적이네. 마음을 굳게 하면 그대들의 영혼은 천 개의 태양보다 더 밝게 빛날 걸세. 적들은 그대들 앞에 기가 꺾이겠지. 정의의 빛이 감쌀 때 모두 쓰러질 걸세!'),
(37119, 2, 0, '얼음왕관 성채 공격을 지금 시작한다!'),
(37119, 3, 0, '아서스! 네놈과 스컬지의 최후를 보겠다고 맹세했다! 희망의 빛 예배당에서 시작했던 일을 이제 끝내겠다!'),
(37119, 4, 0, '사울팽이여, 빛의 힘에는 한계가 없소. 그의 영혼은 엄청난 굴레에 묶여 있지만, 살아 있소. 지금은 말이오.'),
(37119, 5, 0, '빛의 힘으로, 그래야만 하오!'),
(37122, 0, 0, '제일 윗... 선반에선... 꺼내지 못했어...'),
(37122, 1, 0, '한심한 네놈들은 괜찮은 박쥐 날개 고르는 법도 몰랐지.'),
(37122, 2, 0, '그건 상한 거미 수액을 가져온 대가다!'),
(37122, 3, 0, '내 몸을... 핑클스타인이... 재료로 쓰게 두지는...'),
(37122, 4, 0, '동료의 죽음은 막을 수 없었습니다. 그들은 은빛십자군의 이름으로 살다 죽었습니다.'),
(37122, 5, 0, '그 미친 핑클스타인에게 하루 더 재료를 모아다 주느니 차라리 여기서 죽겠어.'),
(37123, 0, 0, '전 이제 틀렸습니다. 형제들이여, 계속 싸우십시오...'),
(37123, 1, 0, '뭐지? 이 힘은...? 모든 고통이 사라지다니! 당신도 나와 함께... 영원한 죽음의 품에 안겨야 합니다!'),
(37123, 2, 0, '이제 고통은 없지요. 안 그렇습니까?'),
(37123, 3, 0, '죄송합니다...'),
(37123, 4, 0, '스컬지를 상대하는 이 전쟁에서 큰일을 하셨습니다. 빛의 가호가 있기를.'),
(37123, 5, 0, '빛이시여, 순간이동기가 작동합니다!'),
(37124, 0, 0, '제발... 내 시체는 화장해줘. 다음 생에는 따뜻하게 살도록...'),
(37124, 1, 0, '안 돼! 안 돼! 왜 화장조차 허락되지 않는 거지? 너희 모두 불타버려!'),
(37124, 2, 0, '어때, 후끈하지?'),
(37124, 3, 0, '내가...무슨 짓을 한 거지? 안 돼!'),
(37124, 4, 0, '이 부정한 장소를 무엇으로 정화할 수 있겠나? 고맙네.'),
(37125, 0, 0, '두 번째도 보람있는 삶이었어...'),
(37125, 1, 0, '리치 왕의 뜻에서 벗어날 방법은 없다네. 뻥뻥 터지는 녀석들을 만나보게!'),
(37125, 2, 0, '폭탄과 가까이 있으면 그렇게 되는 거야!'),
(37125, 3, 0, '참으로... 뻥 터지는 결말이로군!'),
(37125, 4, 0, '위험이 도사리고 있음을 명심하게... 그리고 뻥 터지지 않도록 조심해.'),
(37126, 7, 0, '%s|1이;가; $n|1을;를; 꿰뚫었습니다!'),
(37126, 8, 0, '$n|1이;가; %s의 에테르 보호막을 없앴습니다!'),
(37129, 0, 0, '은빛십자군 형제들이여, 전투를 준비하시오. 브리쿨 놈들은 목숨 걸고 서리 여왕을 보호할 것이오.'),
(37129, 1, 0, '잡담은 그만하시오! 용사들이 도착했소. 전당을 돌파하는 동안 그들을 지원하시오!'),
(37129, 2, 0, '놈들을 우리 쪽으로 유인하시오. 지원하겠소.'),
(37129, 3, 0, '계속 공격하시오!'),
(37129, 4, 0, '스발나를 도울 지원군이 곧 올 거요. 신속히 처치해야 하오!'),
(37129, 5, 0, '내가 주의를 끌어 보겠소. 형제들을 무덤으로 돌려보내고 나서, 나를 도와주시오.'),
(37129, 6, 0, '으으! 잠시 쉬어야겠소.'),
(37129, 7, 0, '용사들이여! 더는 붙잡아 두지 못하겠소.'),
(37129, 8, 0, '내가 주의를 끌어 보겠소. 형제들을 무덤으로 돌려보내고 나서, 나를 도와주시오.'),
(37129, 9, 0, '나는 남아서 티리온 경에게 상황을 보고하겠소. 계속 나아가 신드라고사를 쓰러뜨리시오. 용사들이여, 록타르!'),
(37129, 10, 0, '스컬지 순간이동기를 작동시키느라 너무나 많은 피를 흘렸소. 이 수모는 반드시 갚도록 각오를 다져야 하오. 나를 따르시오, 제군들!'),
(37158, 0, 0, '서리한의 존재 앞에서 쿠엘델라가 생명을 얻습니다!'),
(37158, 1, 0, '%s|1이;가; 공격할 준비를 합니다!'),
(37173, 0, 0, '우린 기다린다. 그리크니르가 정령을 우리 편으로 만들 거야.'),
(37174, 0, 0, '얼음 밑에는 불이 잠들어 있어. 그 정령이 그리크니르에게 말했지.'),
(37181, 0, 0, '너는 지금 스컬지의 신성한 땅 위에 서 있다. 성기사여, 여기서는 빛도 너를 보호하지 못한다. 그 무엇도 널 보호하지 못해...'),
(37181, 1, 0, '폴드링, 넌 나의 가장 위대한 용사가 될 수도 있었다. 어둠의 힘으로 이 세계를 쓸어버리고 투쟁의 새로운 시대를 여는 용사 말이다.'),
(37181, 2, 0, '이제 그러한 명예는 네 몫이 아니다. 곧, 새로운 용사가 나타난다.'),
(37181, 3, 0, '그의 정신을 굴복시키는 일은 꽤 힘들었다. 그 영혼을 잔인하게 괴롭혔지... 오랫동안 저항했지만, 머지않아 자신이 섬길 왕 앞에 무릎 꿇고 말리라.'),
(37181, 4, 0, '결국에는, 나만을 섬기리라.'),
(37183, 0, 0, '절대로! 네놈 따위는... 섬기지... 않는다...'),
(37184, 0, 0, '로켓 장치 가동!'),
(37184, 1, 0, '로켓 장치 작동 중지. 장치를 다시 가동하려면 자포드 붐박스 근처로 가십시오.'),
(37187, 0, 0, '코르크론, 출발하라! 용사들이여, 뒤를 조심하게. 스컬지는...'),
(37187, 1, 0, '내 아들은 분노의 관문에서 목숨을 잃었다. 난 시신을 수습하러 왔을 뿐이다.'),
(37187, 2, 0, '그 애를 드라노쉬라고 이름 지었었다. 오크 말로 "드레노어의 심장"이라는 뜻이지. 흑마법사들이 그 애를 데려가게 두지는 않았다. 가라다르의 장로들이 숨겼으니 안전할 터였지.'),
(37187, 3, 0, '아내가 죽기 전에 약속했었다. 죽든 살든 어둠의 문은 나 혼자 넘고, 아들은 안전하게 있을 거라고. 더럽혀지지 않은 채로...'),
(37187, 4, 0, '오늘, 그 약속을 지키는구나.'),
(37187, 5, 0, '%s|1이;가; 돌진하여 공격합니다!'),
(37187, 6, 0, '바로 네 뒤에 내 외아들이 있다. 아무것도 나를 막지 못한다.'),
(37187, 7, 0, '바로 네 뒤에 내 외아들이 있다. 아무것도 나를 막지 못한다.'),
(37187, 8, 0, '바로 네 뒤에 내 외아들이 있다. 아무것도 나를 막지 못한다.'),
(37187, 9, 0, '바로 네 뒤에 내 외아들이 있다. 아무것도 나를 막지 못한다.'),
(37187, 10, 0, '이 배려는... 잊지 않겠소... 왕이여, 고맙소.'),
(37187, 11, 0, '%s|1이;가; 기침합니다.'),
(37187, 12, 0, '%s|1이;가; 아들의 시체 위로 눈물을 흘립니다.'),
(37187, 13, 0, '나그란드에서 제대로 장례를 치러 주마. 네 어머니와 조상을 화장한 곳 옆에 말이다.'),
(37187, 14, 0, '젊은 용사들이여, 아무리 끔찍한 전투라도... 도의까지 저버려서는 안 되네.'),
(37187, 15, 0, '그 성기사가 살아 있다고? 그게 정말이오, 대영주? 그가 살아 있단 말이오?'),
(37187, 16, 0, '그렇다면 그를 구해야 하오! 볼바르 폴드라곤을 구해내면, 얼라이언스와 호드의 갈등을 잠재울 수 있을 거요.'),
(37187, 17, 0, '이제 할 일이 뚜렷해지는군. 리치 왕이 죗값을 치르게 하고, 대영주 볼바르 폴드라곤을 구해내는 거요!'),
(37187, 18, 0, '코르크론, 오그림의 망치호 최후의 비행을 준비하라! 용사들이여, 성채 위쪽 적당한 곳을 찾아 비행포격선을 대겠네. 거기서 만나세!'),
(37188, 0, 0, '%s|1이;가; 울음을 터뜨립니다.'),
(37200, 0, 0, '그러면 이동하자! 이동...'),
(37200, 1, 0, '오크 혼자서 얼라이언스의 힘에 맞서겠다고?'),
(37200, 2, 0, '돌격!!!'),
(37200, 3, 0, '%s|1이;가; 숨 막히는 소리를 냅니다.'),
(37200, 4, 0, '저게 사울팽의 아들이다. 분노의 관문에서 호드를 지휘했던 자이지. 정말 비참한 최후로군...'),
(37200, 5, 0, '저게 뭐지? 저기, 멀리 말이다!'),
(37200, 6, 0, '저게 사울팽의 아들이다. 분노의 관문에서 호드를 지휘했던 자이지. 정말 비참한 최후로군...'),
(37200, 7, 0, '병사들이여, 집합하라! 호드가 한 번 더 공격하러 오는 듯하다!'),
(37200, 8, 0, '저게 사울팽의 아들이다. 분노의 관문에서 호드를 지휘했던 자이지. 정말 비참한 최후로군...'),
(37200, 9, 0, '오크, 나를 맘대로 움직일 수 없다. 지나가지 못한다.'),
(37200, 10, 0, '그... 그렇게는 못한다. 함선으로 돌아가면 목숨은 부지시켜주마.'),
(37200, 11, 0, '그... 그렇게는 못한다. 함선으로 돌아가면 목숨은 부지시켜주마.'),
(37200, 12, 0, '그리하지요, 폐하!'),
(37200, 13, 0, '폴드링 경, 볼바르가 살았을 수 있겠소? 그렇다면 얼라이언스와 호드 사이에도 평화가 찾아올지 모르오. 이 저주받은 곳 꼭대기로 가서 그 성기사를 풀어줘야겠소!'),
(37200, 14, 0, '공중에서 성채를 공격하도록 하늘파괴자호를 준비하라!'),
(37200, 15, 0, '영웅들이여, 그대들은 길을 뚫어 성채 안 구출 지점을 확보해야 하네. 성루에서 그대들과 합류하겠네!'),
(37217, 0, 0, '%s|1이;가; 큰 소리로 울부짖습니다!'),
(37225, 0, 0, '조심하게. 이전에 우리를 구했던 그 저주받은 검에 대해 들은 적 있네. 서리한 때문에 무엇이 생겨났는지 주위를 둘러보게나.'),
(37225, 1, 0, '시간이 얼마 없어. 이 검이 보는 걸 리치 왕도 본다네. 그가 곧 들이닥칠 걸세.'),
(37225, 2, 0, '리치 왕을 물리칠 순 없네. 여기선 말이지. 그냥 덤비는 건 바보짓이야. 리치 왕은 그대를 따르는 자들을 죽여, 강력한 스컬지 병사로 일으킬 걸세. 그렇지만, 실바나스... 그대에게는 지난번보다 더 끔찍한 일이 닥칠 걸세.'),
(37225, 3, 0, '그럴지도 모르지. 하지만, 이건 알아두게. 리치 왕은 언제나 존재해야만 해. 그대가 아서스를 물리쳐도, 누군가가 그의 자리를 대신해야만 하네. 리치 왕이 지배하지 않으면, 스컬지는 굶주린 메뚜기 떼처럼 이 세상을 휩쓸며 모든 것을 파괴할 테니까.'),
(37225, 4, 0, '밴시 여왕이여, 모르겠네. 어쩌면 스컬지가 아제로스를 쓸어 버리지 않는 유일한 이유는 리치 왕 안에 아서스의 일부가 남아서 그들을 막기 때문이 아닌가 하네.'),
(37225, 5, 0, '안타깝게도, 리치 왕을 무찌를 방법은 하나뿐이라네. 그 존재가 생겨난 곳에서 쓰러뜨려야 하지.'),
(37225, 6, 0, '그래. 으아아아아아아아... 그... 그가 오고 있어. 그대는... 어서...'),
(37225, 7, 0, '우서가 고개를 젓습니다.'),
(37225, 8, 0, '제이나! 정말 자네인가?'),
(37225, 9, 0, '시간이 얼마 없어. 이 검이 보는 걸 리치 왕도 본다네. 그가 곧 들이닥칠 거야.'),
(37225, 10, 0, '아니야. 아서스는 여기 없네. 아서스는 리치 왕의 마음 안에만 있는 존재야. 그것도 점점 희미해지지...'),
(37225, 11, 0, '제이나, 내 말 잘 듣게. 리치 왕을 쓰러뜨려야만 하네. 그를 설득할 수는 없어. 리치 왕은 자네와 동료를 모두 처치하고 강력한 스컬지 병사로 다시 일으킬 걸세.'),
(37225, 12, 0, '기운을 내게. 리치 왕은 그가 넬쥴과 합쳐진 곳에서 처치해야만 하네. 첨탑 꼭대기의 얼어붙은 왕좌 말이네. 그게 유일한 방법일세.'),
(37225, 13, 0, '리치 왕에 대해... 알아야 하는 게 더 있네. 스컬지에 대한 지배가 없어지면 안 돼. 리치 왕을 쓰러뜨린다 해도 누군가 그 자리를 대신해야만 하네. 주인이 다스리지 않으면, 스컬지는 굶주린 메뚜기 떼처럼 이 세상을 뒤덮고 모든 생명을 파괴할 테니까.'),
(37225, 14, 0, '고결한 영혼이 숭고하게 희생되어야...'),
(37225, 15, 0, '모르겠네, 제이나. 어쩌면 스컬지가 아제로스를 쓸어 버리지 않는 유일한 이유는 리치 왕 안에 아서스의 일부가 남아서 그들을 막기 때문이 아닌가 하네.'),
(37225, 16, 0, '안 돼, 제이나! 으아아아아아아아... 그... 그가 오고 있어. 자... 자네는 어서...'),
(37225, 17, 0, '우서가 고개를 젓습니다.'),
(37226, 0, 0, '조용히 해라, 성기사!'),
(37226, 1, 0, '죽은 자와 얘기하고 싶다는 건가? 그 소원을 들어주지.'),
(37226, 2, 0, '팔릭, 마윈. 끝나면 놈들의 시체를 내 방으로 가져오너라.'),
(37226, 3, 0, '실바나스, 같은 실수를 두 번 하지는 않을 것이다. 이번에는 탈출할 수 없다. 모두 죽음으로 나를 섬기리라!'),
(37226, 4, 0, '어리석군. 내가 오래전에 죽여버린 자를 찾다니. 그는 이제 그저 유령일 뿐이다. 내 마음에 울리는 희미한 메아리지...'),
(37491, 1, 0, '한심한 네놈들은 괜찮은 박쥐 날개 고르는 법도 몰랐지.'),
(37491, 2, 0, '그건 상한 거미 수액을 가져온 대가다!'),
(37491, 3, 0, '내 몸을... 핑클스타인이... 재료로 쓰게 두지는...'),
(37493, 1, 0, '뭐지? 이 힘은...? 모든 고통이 사라지다니! 당신도 나와 함께... 영원한 죽음의 품에 안겨야 합니다!'),
(37493, 2, 0, '이제 고통은 없지요. 안 그렇습니까?'),
(37493, 3, 0, '죄송합니다...'),
(37494, 1, 0, '안 돼! 안 돼! 왜 화장조차 허락되지 않는 거지? 너희 모두 불타버려!'),
(37494, 2, 0, '어때, 후끈하지?'),
(37494, 3, 0, '내가...무슨 짓을 한 거지? 안 돼!'),
(37495, 1, 0, '리치 왕의 뜻에서 벗어날 방법은 없다네. 뻥뻥 터지는 녀석들을 만나보게!'),
(37495, 2, 0, '폭탄과 가까이 있으면 그렇게 되는 거야!'),
(37495, 3, 0, '참으로... 뻥 터지는 결말이로군!'),
(37503, 0, 0, '서리 여왕께 다가가도록 두지 않겠다. 서둘러라! 저들을 막아라!'),
(37518, 0, 0, '<치지직>$b이게 작동하는 건가? 여보세요?'),
(37518, 1, 0, '아, 거기 있었군요. 안녕하세요! 당신이 카라노스로 날아가는 동안 눈마루 골짜기 밖에서 일어나는 일에 대한 정보를 줄 수 있을 거라고 짐작했어요.'),
(37518, 2, 0, '아무래도 눈마루쪽 사람들은 요 며칠 사이에 일어난 일 때문에 공포에 빠진 것 같아요.'),
(37518, 3, 0, '눈마루 골짜기에서 트롤 문제로 힘드셨다고요? 카라노스에 안 가 보셨으면 말을 하지 마세요! 대격변 때문에 트롤들이 몽땅 날뛰고 있어요.'),
(37518, 4, 0, '그리고 당신 왼쪽을 보면 노움들이 놈리건을 되찾았다는 걸 알 수 있을 거예요. 만세!'),
(37518, 5, 0, '이곳 역시 많은 일이 일어나고 있어요. 공항으로 가는 길이 열렸고, 동쪽에 검은무쇠 부족이 있다는 소문과... 아, 그리고 드워프의 왕이신 마그니 브론즈비어드 님께 무언가 이상한 일이 일어나는 것 같으니 아마도 그걸 한번 알아봐야 할 거예요.'),
(37518, 6, 0, '자, 다 왔어요! 카라노스에 오신 것을 환영해요! 내릴 때 발 조심하시고요.'),
(37570, 0, 0, '전 흉터를 봉인하겠습니다, $n. 다른 쪽에서 아무것도 들어오지 않도록 해주십시오!'),
(37592, 0, 0, '영웅들이여! 죽음을 각오하고, 숨을 거두는 그 순간까지 언데드를 저지하겠습니다. 스컬지군주를 상대하십시오!'),
(37592, 1, 0, '용감한 영웅들이여, 우리는 그대들에게 목숨을, 자유를 빚졌습니다... 이런 큰 빚을 갚기엔 너무나도 모자라겠지만, 그대들의 훌륭한 행동과 이 어두운 성채의 그림자를 가른 행보를 오늘부터 모든 이들에게 알리겠다고 맹세합니다.'),
(37592, 2, 0, '이 날은 그대들의 용맹함을 입증하고, 리치 왕조차도 적수가 안됨을 증거하는 날이 될 것입니다. 만약 얼라이언스와 호드가 차이를 극복하고...'),
(37813, 0, 0, '네놈들이 쓰러뜨린 호드 병사와 쓰러진 얼라이언스 쓰레기 하나하나가 리치 왕의 군대를 더 강대하게 했다. 지금 이 순간도 발키르가 쓰러진 너희 병사를 스컬지로 일으켜 세우지.'),
(37813, 1, 0, '상황이 훨씬 더 나빠지려 하는군. 오너라, 리치 왕께서 내리신 힘을 맛보게 해주마!'),
(37813, 2, 0, '드워프 놈들...'),
(37813, 3, 0, '드워프 놈들...'),
(37813, 4, 0, '함께하시지요, 아버지. 저와 손을 잡고 함께 이 세계를 스컬지의 이름으로 궤멸합시다. 리치 왕의 영광을 위하여!'),
(37813, 5, 0, '참 답답도 하시군요. 뭘 하실 수나 있습니까? 저는 한창때 아버지보다 훨씬 강합니다.'),
(37813, 6, 0, '나이를 헛드셨군요! 그렇다면 오시지요. 와서 스컬지의 힘에 맞서 보십시오!'),
(37813, 7, 0, '리치 왕의 힘으로!'),
(37813, 8, 0, '대지가 네 피로 붉게 물들리라!'),
(37813, 9, 0, '부하들아, 배불리 먹어라!'),
(37813, 10, 0, '네놈은 상대가 안 된다!'),
(37813, 10, 1, '여기에서 네 영혼은 구원받지 못하리라!'),
(37813, 11, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(37813, 12, 0, '나는 죽음... 그 자체다!'),
(37813, 13, 0, '이제... 나는... 해방되었다...'),
(37813, 14, 0, '%s의 피의 괴물이 피의 향기를 맡습니다!'),
(37879, 0, 0, '물러나시오, 무라딘. 슬픔에 잠긴 아버지 아니오.'),
(37879, 1, 0, '나는... 분노의 관문에 없었지만, 살아남은 병사들이 많은 이야기를 전해주었다. 그대의 아들은 명예롭게 싸웠고 영웅답게 전사했다. 그러니 영웅답게 묻힐 자격이 있다.'),
(37879, 2, 0, '제이나? 왜 우는 것이오?'),
(37879, 3, 0, '음, 무라딘! 갑판을 정리하고 위쪽 성채를 공격할 수 있도록 병사들을 준비하시오. 스톰윈드에서 병력을 더 보내겠소.'),
(37915, 0, 0, '경비병!'),
(37951, 0, 0, '동쪽의 훈련장에 직업 상급자가 있네. 검은창 부족의 자부심을 보여주게.'),
(37955, 3, 0, '피의 갈증으로 목이 마릅니다!'),
(37955, 4, 0, '고통을 느껴봐라!'),
(37955, 5, 0, '어둠이 쌓이더니 $n에게 몰려듭니다!'),
(37955, 12, 0, '%s|1이;가; 분노에 휩싸여 광폭해집니다!'),
(37970, 0, 0, '낙사나르에서는 잠시 물러났을 뿐이다! 보주의 힘으로, 발라나르는 복수를 행하리라!'),
(37970, 1, 0, '피의 기원이 공작 발라나르에게 옮겨갑니다!'),
(37970, 2, 0, '내 힘이 넘치는구나.'),
(37970, 3, 0, '%s|1이;가; 강력한 충격의 소용돌이를 시전하기 시작합니다!'),
(37970, 4, 0, '저녁이... 준비됐군.'),
(37970, 4, 1, '이제 암흑사도의 힘을 알겠느냐?'),
(37970, 5, 0, '산레인 앞에 무릎 꿇어라!'),
(37970, 6, 0, '산레인 앞에 무릎 꿇어라!'),
(37972, 0, 0, '엄청난 힘이다! 암흑사도의 보주로 나는 무적이다!'),
(37972, 1, 0, '피의 기원이 공작 켈레세스에게 옮겨갑니다!'),
(37972, 2, 0, '피가 강을 이루리라.'),
(37972, 3, 0, '무언가 하긴 했느냐?'),
(37972, 3, 1, '진실은 죽음 안에 있지.'),
(37972, 4, 0, '%s|1이;가; 미친 듯이 웃습니다.'),
(37972, 5, 0, '여왕님, 저들이... 옵니다.'),
(37973, 0, 0, '필멸자들아, 두려움으로 몸부림쳐라! 보주의 힘이 이 몸에 흐르니 말이다!'),
(37973, 1, 0, '피의 기원이 공작 탈다람에게 옮겨갑니다!'),
(37973, 2, 0, '고통을 즐겨봐라!'),
(37973, 3, 0, '강력한 불꽃이 $n|1을;를; 향해 달려갑니다!'),
(37973, 4, 0, '송장이나 다름없군.'),
(37973, 4, 1, '자비나 빌어봐라!'),
(37973, 5, 0, '%s|1이;가; 웃습니다.'),
(37973, 6, 0, '자비나 빌어봐라!'),
(37988, 0, 0, '좋습니다, 친구. 티키 표적을 박살 냅시다!'),
(37988, 1, 0, '당신을 가르쳐줄 사람이 여기 어딘가에 있을 겁니다. 나중에 봅시다.'),
(38002, 0, 0, '날쌘발톱이 멈추지 않습니다! 검은창 요새 근처에 있는 랩터 우리로 몰아넣으십시오.'),
(38015, 0, 0, '$n, 여기야! 여기! 나무 옆이네.'),
(38015, 1, 0, '놈들이 온다! 전원, 준비...'),
(38015, 2, 0, '피와 번개의 축복을!'),
(38015, 3, 0, '도망갈 생각 마라, 타우라조 학살자! 넌 죽은 목숨이다!'),
(38015, 4, 0, '얼라이언스가 공중에서 흔들리는 시체를 볼 수 있도록 나무에 매달아 놓읍시다. 블러드힐트 장군님께 돌아가 이 소식을 전하시오!'),
(38017, 0, 0, '필멸자들이 검을 찾게 도와줘야 한다고 확신하십니까?'),
(38017, 1, 0, '크라서스, 이 검은... 아주 오래전에 만들어졌습니다. 그땐 지금과... 상황이 달랐죠.'),
(38017, 2, 0, '한때, 적은 우리의 가장 강한 무기를 우리에게 들이댔습니다. 오색 검은 다르리라 생각하시는 이유가 있습니까?'),
(38017, 3, 0, '뜻을 따르겠습니다, 나의 여왕님. 그들을 방해하지 않겠습니다. 하지만 눈을 떼지는 않을 겁니다.'),
(38112, 0, 0, '남자든 여자든 아이든... 아무도 주인님의 분노를 피할 수 없다. 다 죽은 목숨이지.'),
(38112, 1, 0, '실컷 꿈틀대봐라!'),
(38112, 1, 1, '스트라솔름에 사는 어린애도 이보다는 잘 싸우겠다!'),
(38112, 2, 0, '마윈, 저놈들을 끝장내...'),
(38112, 3, 0, '로데론의 병사들아, 일어나 주인님의 부름에 응해라!'),
(38112, 4, 0, '절망... 너무나 달콤하지...'),
(38112, 5, 0, '공포... 너무나 상쾌하지...'),
(38112, 6, 0, '분부대로 하겠습니다, 주인님.'),
(38113, 0, 0, '네놈이 여기에서 얻을 것은 죽음뿐이다!'),
(38113, 1, 0, '그놈이 죽을 때도 똑같은 눈빛이었지. 테레나스는 믿지 못했지만.'),
(38113, 1, 1, '고통 속에 죽어가라!'),
(38113, 2, 0, '그래... 도망쳐라... 네 운명을 만날 때까지... 쓰라리고, 차디찬 결말이 너를 기다린다.'),
(38113, 3, 0, '주인님께서는 왕국을 살펴보고 모자라다고 생각하셨다. 그리고 자비도 주저함도 없이 심판하셨지. 모두 죽여주마!'),
(38113, 4, 0, '분부대로 하겠습니다, 주인님.'),
(38113, 5, 0, '썩어들어 가는 네 몸을 직접 보여주마!'),
(38113, 5, 1, '사라져라, 흔적도 없이!'),
(38113, 6, 0, '영혼들이 나타나 제단을 둘러쌉니다!'),
(38113, 7, 0, '영혼들이 다시 나타납니다!'),
(38142, 0, 0, '널 없애버리겠다, 검은창 쥐새끼 녀석!'),
(38172, 0, 0, '주인님께서 명령하신다.'),
(38172, 0, 1, '우리는 죽어서도 섬기리라.'),
(38172, 0, 2, '주인님을 위해 한 번 더 싸우리라.'),
(38172, 0, 3, '왜 죽음을 이런 곳에서 찾느냐?'),
(38172, 0, 4, '여기는 산 자가 올 데가 아니다.'),
(38172, 1, 0, '우리 고통은 영원하리라.'),
(38172, 1, 1, '이것이 우리의 마지막 안식은 아니다.'),
(38172, 1, 2, '모두 죽음 안에서 주인님을 섬긴다.'),
(38172, 1, 3, '이건 짧은 휴식일 뿐이다...'),
(38172, 1, 4, '우리 영혼은 결코 자유롭지 못하리라.'),
