(38177, 1, 4, '우리 영혼은 결코 자유롭지 못하리라.'),
(38225, 0, 0, '여기로 돌아오다니, 바보 같은 것. 네가 한 번은 복수의 손길을 빠져나갔다만, 검은창 부족이 이번에도 널 봐주리라 생각지는 마라.'),
(38225, 1, 0, '바다 마녀가 불에서 힘을 뽑아내고 있습니다. 빨리 화로를 끄십시오!'),
(38225, 2, 0, '끝났네. 오랜 원수를 마침내 처치했군.'),
(38225, 3, 0, '참으로 오랫동안 아버님의 복수를 염원했다네. 오늘 드디어 그 무거운 짐을 내려놓는군.'),
(38225, 4, 0, '나는 검은창 요새로 돌아가야 하네. 바니라가 소년을 치료하고 나면 돌아와서 날 찾아오게.'),
(38334, 0, 0, '뭘 그렇게 쳐다봐? 천재 처음 보나?'),
(38334, 1, 0, '네 일이나 신경 쓰라고 말로 하면 못 알아듣는군!'),
(38335, 0, 0, '맞아. 내가 이런 ''폭죽류''의 값을 부르는 걸 좋아하지.'),
(38335, 1, 0, '남쪽 바다에서 돌아오면 저걸로 짭짤하게 벌 거야.'),
(38335, 2, 0, '너... 내가 널 못 보리라 생각하지 마. 이제 날 내버려 두라고!'),
(38336, 0, 0, '이발도 면도도 말끔하게 됐군, 고마워.'),
(38336, 1, 0, '난 가버릴 거니까 좀 더 줄게.'),
(38336, 2, 0, '다시 생각해봤는데, 그냥 가방 채로 가져. 나는, 그러니까 가야 하거든.'),
(38336, 3, 0, '정말 이렇게 쉽게 나를 궁지에 몰아넣을 수 있다고 생각했어?'),
(38337, 0, 0, '뭘 그렇게 쳐다봐? 천재 처음 보나?'),
(38337, 1, 0, '네 일이나 신경 쓰라고 말로 하면 못 알아듣는군!'),
(38338, 0, 0, '맞아. 내가 이런 ''폭죽류''의 값을 부르는 걸 좋아하지.'),
(38338, 1, 0, '남쪽 바다에서 돌아오면 저걸로 짭짤하게 벌 거야.'),
(38338, 2, 0, '너... 내가 널 못 보리라 생각하지 마. 이제 날 내버려 두라고!'),
(38339, 0, 0, '이발도 면도도 말끔하게 됐군, 고마워.'),
(38339, 1, 0, '난 가버릴 거니까 좀 더 줄게.'),
(38339, 2, 0, '다시 생각해봤는데, 그냥 가방 채로 가져. 나는, 그러니까 가야 하거든.'),
(38339, 3, 0, '정말 이렇게 쉽게 나를 궁지에 몰아넣을 수 있다고 생각했어?'),
(38423, 0, 0, '이번엔 제가 끄겠습니다!'),
(38472, 0, 0, '죽어라, 침입자들아! 누구도 교단의 계획을 간섭할 순 없다!'),
(38472, 1, 0, '어... 여기 어딘가요...? 이 무슨 악몽을 꾼거지... 하지만 곰곰히 생각해 볼 시간은 없어요. 보고해야 할 정보가 많습니다!'),
(38485, 0, 0, '죽어라, 침입자들아! 누구도 교단의 계획을 간섭할 순 없다!'),
(38485, 1, 0, '어... 여기 어딘가요...? 이 무슨 악몽을 꾼거지... 하지만 곰곰히 생각해 볼 시간은 없어요. 보고해야 할 정보가 많습니다!'),
(38490, 0, 0, '$n|1이;가; 죽음의 역병에 걸렸습니다!'),
(38494, 0, 0, '$n|1이;가; 죽음의 역병에 걸렸습니다!'),
(38579, 0, 0, '마침내 풀려났구나! 아들아, 다 끝났다. 응보의 시간이 왔다.'),
(38579, 1, 0, '일어나라, 빛의 용사들이여!'),
(38748, 0, 0, '페로몬 냄새를 맡아 곤충집 안으로 들어가야 합니다!'),
(38805, 0, 0, '이제 요새로 천천히 돌아갈 수 있겠소...'),
(38805, 0, 1, '붕대가 상한 것 같소! 하지만 불평하면 안 되겠지.'),
(38805, 0, 2, '고맙소. 이곳은 학살 현장으로 변해가고 있소.'),
(38872, 0, 0, '$n, 도와주십시오! 밧줄을... 제발...'),
(38872, 1, 0, '아, 고맙습니다! 일단 협상은...계획대로 진행됐습니다.'),
(38872, 2, 0, '야영지까지는 제 힘으로 돌아갈 수 있습니다.'),
(38895, 0, 0, '끼이이이이야아아아아아아아아아아호!'),
(38895, 0, 1, '빌지워터 해적구단이 영원하기를!'),
(38931, 0, 0, '잠깐! 혼자서 다 처리하진 말라고요!'),
(38938, 0, 0, '말대꾸하지 마라, 트롤. 누가 여기 책임자인지 잘 알 텐데. 스랄이 어째서 당신이 아닌 나를 선택했는지 아직도 이해하지 못하겠나?'),
(38938, 1, 0, '내가 이 자리에서 네 숨을 끊지 않는 걸 다행으로 생각해라. 감히 호드의 대족장에게 그딴 식으로 말해도 된다고 생각하나?'),
(38938, 2, 0, '구체적으로 도대체 뭘 어떻게 하겠다는 거지? 그딴 게 위협이 된다고 생각하나? 이제 동족을 이끌고 뒷골목으로 썩 물러가라. 방 안에 가득 찬 악취를 이젠 도저히 참아줄 수가 없군.'),
(38938, 3, 0, '화를 자초하는군, 트롤.'),
(38938, 4, 0, '%s|1이;가; 볼진의 발에 침을 뱉습니다.'),
(38939, 0, 0, '볼진. 참으로 반갑네, 형제여.'),
(38939, 1, 0, '사실일세. 누군가 나를 죽이려 했지. 하지만 지금은 그게 중요한 게 아닐세. 세상은 내 도움이 필요해.'),
(38939, 2, 0, '볼진, 가로쉬에겐 이 시국에 호드를 이끌 힘이 있네. 그래서 그를 택했네.'),
(38939, 3, 0, '사람들은 나더러 지혜롭다고 하지... 하지만, 나도 지금껏 호드의 분열을 가까스로 막아냈네. 분노의 관문과 언더시티를 생각해 보게.'),
(38939, 4, 0, '호드는 정통성 있는 영웅을 원한다네. 절대로 인간에게 고개 숙이지 않을, 배신 따위를 허락하지 않을 진정한 오크이자 호드의 자긍심을 찾아줄 전사 말이야. 가로쉬는 그런 영웅이 될 수 있네.'),
(38939, 5, 0, '가볍게 결정한 게 아니라네, 볼진. 우리의 동맹이 흔들릴 것임을 아네. 호드가 되돌릴 수 없을 만큼 변하리란 것도 아네. 하지만, 호드에 필요한 인물이 바로 가로쉬임을 확신하기에 그를 선택했네.'),
(38939, 6, 0, '자네와 다른 지도자들이 우리 호드의 분열을 보고만 있지는 않겠지. 난 그대들을 믿네.'),
(38939, 7, 0, '트롬카, 친구여.'),
(38953, 0, 0, '아니, 잘 이해하고 있네, 가로쉬. 백성은 전쟁 영웅을 원하고, 자넨 그롬의 아들이지. 그래서 스랄이 대족장의 자리를 맡긴 게야.'),
(38953, 1, 0, '자넨 스랄이 생각하는 것보다 더 그롬을 닮았네. 악마의 피가 없어도 말이야.'),
(38953, 2, 0, '자네는 나의 대족장은 아니야. 나는 자네를 존경하지 않으며, 그 어리석은 전쟁욕이 호드를 파괴하는 걸 보고만 있지는 않겠네.'),
(38953, 3, 0, '헬스크림의 아들이여, 난 내가 어떻게 할지 확실히 알고 있다. 나는 지켜볼 것이야. 네 백성이 너의 무능함을 알게 되고, 나처럼 널 경멸하게 되는 걸 즐겁게 웃으며 지켜볼 테다.'),
(38953, 4, 0, '그리고 네가 완전히 무너지고, 네 힘이 아무런 의미도 없어지는 바로 그때, 내가 너의 통치를 빠르고 조용하게 끝낼 것이다.'),
(38953, 5, 0, '대족장으로 있는 동안, 넌 언제나 등 뒤를 신경 쓰고 어둠을 두려워할 것이다. 그리고 때가 되면, 넌 피 흘리며 죽어갈 것이다... 심장을 꿰뚫은 그 화살이 누구 것인지는... 말하지 않아도 잘 알겠지.'),
(38953, 6, 0, '너야말로, "대족장".'),
(38966, 0, 0, '자네에게 보여줄 게 있네. 직접 보는 게 더 이해하기 쉽겠지.'),
(38966, 1, 0, '검은창 부족은 내 지시에 따라 여기로 이주했네. 헬스크림의 손아귀에 떨어진 오그리마는 우리의 집이 아니야.'),
(38966, 2, 0, '하지만 내가 화를 못 이겨 경솔하게 행동한 건 아닌지 걱정스럽네. 스랄은 지금의 호드를 만드는 데 모든 것을 바쳤지. 충동적으로 호드를 떠나고 싶지는 않네. 깊이 생각해 볼 일이야.'),
(38966, 3, 0, '어쨌든 이건 나 같은 늙은이가 걱정할 일이지. 자넨 아직 배울 게 많네. 가서 검은창 부족을 돕게. 우린 곧 다시 만나게 될 게야.'),
(38966, 4, 0, '바다 마녀는 죽었고, 우리는 고향을 되찾았네. 하지만 우리의 미래는 아직 불안하군.'),
(38966, 5, 0, '나는 가로쉬가 싫네. 그건 확실하지. 하지만 호드를 떠나는 건 가볍게 내릴 결정이 아니야.'),
(38966, 6, 0, '내게 대답을 줄 수 있는 이는 하나뿐이지. 원한다면 자네도 지켜보게.'),
(38966, 7, 0, '스랄, 자네가 무사해서 다행이군. 흉흉한 소문을 들었는데.'),
(38966, 8, 0, '자네의 조언이 필요하네, 친구여. 가로쉬는 오로지 전쟁만을 바라보며 호드 사이에 불화를 일으키고 있네. 난 자네를 존경하지만, 이 새로운 호드는 존경할 수 없네... 그래서 호드를 나갈 생각을 하고 있지.'),
(38966, 9, 0, '알겠네, 형제여. 자네를 더 귀찮게 하지 않고 좀 더 생각해 보겠네. 자네는 세상을 구원해야지...'),
(38966, 10, 0, '자네는 강인하고 자긍심 높은 젊은이일세. 자네 같은 인재와 함께 싸워서 자랑스럽군.'),
(38966, 11, 0, '참으로 힘든 시기야... 하지만 모두를 위해, 역시 우리는 호드와 함께 해야 할 것 같네.'),
(38966, 12, 0, '스랄의 말이 옳네. 그는 언제나 옳았지. 호드란 무엇인가? 고집 센 늙은 지도자들, 노스렌드에서 명성을 날린 영웅 몇 명이 전부는 아니지. 사람들은 가로쉬의 이름을 외치고 있네. 적어도 지금은.'),
(38966, 13, 0, '그래도 난 스랄이 언젠가 우리에게 돌아오길 바라네. 지금은 미래에서 암울함과 피비린내밖에 느낄 수가 없군.'),
(38966, 14, 0, '이제 가게. 검은창 부족을 명예롭게 해 주게. 수많은 전투가 우리를 기다리고 있네. 그리고 자네는 어느 전투에서든 중요한 역할을 할 게야.'),
(38980, 0, 0, '여기가 어디지?'),
(38980, 1, 0, '잠깐, 여긴 지금... 집이잖아?'),
(38980, 2, 0, '당신들... 여기서 뭣들 하는 겁니까? 왜 우리 집에 있는 거죠?'),
(38980, 3, 0, '어머니.. 아버지... 투르만... 다 어디있나요? 저 좀 도와주세요!'),
(38980, 4, 0, '아니야... 기억났어. 내 가족은 모두 죽었지. 나도 죽었고.'),
(38980, 5, 0, '그리고 내 영혼은... 내 영혼은 스컬지의 것이다!'),
(38981, 0, 0, '가련한 그 목숨을 거둬주마! 죽어라!'),
(38989, 0, 0, '준비가 되면 제게 알려 주십시오.'),
(38995, 0, 0, '아서스, 순식간에 끝내주마. 그동안 너는 무수히 많은 생명을 고통스럽게 빼앗아왔지만 말이다.'),
(38995, 1, 0, '두고보자. 용사들이여, 공격하라!'),
(38995, 2, 0, '성스러운 빛이여, 마지막 축복을 내려주소서! 이 구속을 깨뜨릴... 힘을 주소서!'),
(38995, 3, 0, '아서스, 더는 없으리라! 네 증오에 소중한 생명이 희생되는 일은!'),
(39034, 0, 0, '천둥경기장으로 들어가라고, $n! 한 사람이 쓰러질 때까지 못 나오는 거야! 이제 경기를 시작하자고!'),
(39034, 1, 0, '죄송하지만 얌전하신 신사 숙녀 여러분께서는 자리를 비워 주시기 바랍니다... 진정한 사나이와 여장부만이 앞으로 펼쳐질 피비린내나는 광경을 참아낼 수 있을 테니까요! 첫 번째 상대를 소개합니다. 사막유랑단의 전사이자 카자콜라의 실권자인... 자이노무스!'),
(39034, 2, 0, '자이노무스가 졌습니다! $n|1은;는; 아직도 힘이 넘쳐 보이는군요!'),
(39034, 3, 0, '다음 상대는 줄파락 무덤의 깊은 곳에서 왔습니다! 저주받은 피를 마음껏 마시고 죽음에서 수도 없이 부활한, 격노와 포악함 밖에 모르는 존재! 인정사정없는 분노의 소유자... 주몽가!'),
(39034, 4, 0, '$n|1이;가; 또 해냈습니다! 주몽가가 다시 한번 쓰러졌군요'),
(39034, 5, 0, '심약하신 분들은 아마도 눈을 가려야 할지도 모릅니다! 이제 경기장으로 들어올 상대는 센티파르 곤충집의 어두운 굴속에서 생포해온 공포의 생명체니까요! 바람처럼 빠른 죽음의 존재! 사리넥스!'),
(39034, 6, 0, '사리넥스가 곤죽이 되었군요! $n|1을;를; 멈출 수 있는 자는 아무도 없습니다!'),
(39034, 7, 0, '자, 그건 그렇고. 싸움이 잘 마무리 됐군요. 폭력적으로 말이죠! 참가자들 이야기를 한번 들어보겠습니다!'),
(39034, 8, 0, '바닥에 떨어진 핏방울 말고는 도전자의 흔적이란 찾아볼 수도 없군요!'),
(39034, 8, 1, '도전자가 패배했습니다!'),
(39062, 0, 0, '구덩이에 들어가서 당신의 기술을 보여주십시오.'),
(39075, 0, 0, '그동안 폭력과 고통을 너무 많이 겪어왔지. 내게 좋은 해결책이 하나 있다. 바로 네놈이 내 앞에서 그냥 도망치는 것이다.'),
(39075, 1, 0, '정말 실망이군. 너는 내가 겪은 전쟁의 참화를 또다시 불러일으켰다.'),
(39082, 0, 0, '이봐요! 저 벌레들이 내 시계를 가져갔습니다!'),
(39082, 0, 1, '숨 쉴 수 있습니다!'),
(39082, 0, 2, '이제 살았습니다!'),
(39082, 0, 3, '너무 감사합니다!'),
(39082, 0, 4, '오늘 날짜가 어떻게 되죠?'),
(39097, 0, 0, '릴리안... 지금 네 모습은... 다시 만나게 되어 기쁘구나.'),
(39097, 1, 0, '아, 난...'),
(39097, 2, 0, '릴리안, 난...'),
(39128, 0, 0, '안 돼, 이럴 수가... 최전방 전초기지가 없어졌잖아!'),
(39128, 1, 0, '너무 늦은 것인가...? 데스윙의 존재가 느껴진다!'),
(39128, 2, 0, '불의 군주가 나타났군! 다른 이에게 알려야 한다. 서두르자!'),
(39148, 0, 0, '주몽가... 다 없애버린다...'),
(39217, 0, 0, '아서스를 심판하러 왔나? 리치 왕의 최후를 보러?'),
(39217, 1, 0, '먼저 서리한의 손아귀에서 탈출해야 한다. 그렇지 않으면 나처럼 저주받아 이 가증스러운 검 안에 영원히 갇히리라.'),
(39368, 0, 0, '좋아, 이 쓸모없는 깡통 녀석들, 한번 시작해 볼까?'),
(39368, 1, 0, '내가 너희들을 제대로 된 군인으로 만들어 주마!'),
(39368, 2, 0, '가장 먼저 배워야 할 것은 강인한 군인 정신이다.'),
(39368, 3, 0, '내가 신호를 주면 절도 있는 경례로 너희들의 군인 정신을 보여 준다!'),
(39368, 4, 0, '일동, 차렷, 경례!'),
(39368, 5, 0, '잘했어!'),
(39368, 6, 0, '전투에 돌입하면, 귀청이 떨어질 듯한 고함으로 적의 기선을 제압하는 것이 중요하다!'),
(39368, 7, 0, '내가 신호를 주면, 목이 찢어져라 커다란 고함을 지른다!'),
(39368, 8, 0, '고함 일발 장전, 발사!'),
(39368, 9, 0, '와우, 멋져. 무시무시한데!'),
(39368, 10, 0, '하지만 꼭 명심해라. 전투에서 승리하려면 사기를 높이는 게 필수적이다.');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(39368, 11, 0, '우렁찬 환호로 전투 중인 동료 병사들에게 용기를 북돋아 주는 거다. 자, 내가 신호를 하면 나를 향해 환호한다!'),
(39368, 12, 0, '일동, 환호!'),
(39368, 13, 0, '환상적이야!'),
(39368, 14, 0, '하지만 전투에서 가장 중요한 건 힘겹게 얻은 승리를 어떻게 축하하느냐이다.'),
(39368, 15, 0, '내가 신호를 주면 제군들은 승리를 축하하는 최고의 춤을 춘다!'),
(39368, 16, 0, '춤 일발 장전, 발사!'),
(39368, 17, 0, '최고야!'),
(39368, 18, 0, '어쩌면 제군들은 내가 만나 본 최고의 훈련생일지도 모르겠군. 자, 반복 훈련이다. 처음부터 다시!'),
(39378, 0, 0, '오, 불타는 빛이여... 날 데려가 주오.'),
(39378, 1, 0, '몹쓸 놈들! 더러운 놈들! 마귀 같으니! 여기에서 당장 꺼져라!'),
(39378, 2, 0, '느껴지느냐? 축복받은 태양의 온기가...'),
(39378, 3, 0, '네놈의 신에게 보내주마.'),
(39378, 3, 1, '이 목숨은 제물로 받겠다!'),
(39425, 0, 0, '무슨 짓을 한 거냐...'),
(39425, 1, 0, '침입자들아, 돌아가라! 전당을 어지럽히지 마라!'),
(39425, 2, 0, '빛이시여, 신성한 방패를 내려 주소서!'),
(39425, 3, 0, '후회는 없다.'),
(39425, 3, 1, '오만불손하게 군 벌이다.'),
(39428, 0, 0, '프타는... 이젠...'),
(39428, 1, 0, '내 벌레들이 배를 채우겠군...'),
(39428, 2, 0, '먼지로 돌아가라.'),
(39428, 2, 1, '땅이 진동한다!'),
(39625, 0, 0, '수많은 부하들이 내 명령을 기다린다. 네놈들이 어쩌겠다는 거냐?'),
(39625, 1, 0, '얘들아, 저녁밥이다!'),
(39625, 1, 1, '형편없군...'),
(39625, 2, 0, '선택할 수 있는 건 죽음뿐...'),
(39625, 3, 0, '앞길을 막는 자 살아남지 못하리라!'),
(39625, 4, 0, '공격해라, 이 겁쟁이들아!'),
(39625, 5, 0, '전방 병력을 강화해라. 침입자가 있다!'),
(39625, 6, 0, '후방을 지원해라! 알렉스트라자의 아이들이 우리를 공격한다!'),
(39644, 0, 0, '저들이 내게 무슨 짓을 한 거지? 야영지로 돌아가야 해...'),
(39644, 0, 1, '... 내가 지금 무슨 말을 하고 있는 거죠? 말도 안 되는 말을... 여길 나가야겠어요!'),
(39644, 0, 2, '어... 어라? 내가 왜 여기 있는 거지? 여기서 도망쳐야 해!'),
(39644, 0, 3, '무슨 일이 있었던 거죠? 전 떠납니다!'),
(39644, 0, 4, '아, 덕분에 절 따라다니던 목소리가 사라졌습니다. 전 여길 벗어나겠습니다!'),
(39644, 0, 5, '뇌가 ... 너무 ... 아파!'),
(39665, 0, 0, '초갈 두목님이 별로 안 좋아할 거야!'),
(39665, 1, 0, '봤지? 너 이렇게 된다!'),
(39665, 2, 0, '가만히 좀 있어! 롬오그가 머리 때려줄 거야!'),
(39665, 3, 0, '롬오그 미안하다...'),
(39670, 0, 0, '라즈... 부순다!'),
(39696, 0, 0, '도살로봇이 고기를 수집하겠습니다, 트랄랄랄라.'),
(39696, 0, 1, '찹 찹 찹! 잘 다지기!'),
(39696, 0, 2, '동맥이 필요해에에에에에에에에!'),
(39696, 0, 3, '부르르르르르르르르르르르르릉!'),
(39698, 0, 0, '너희 몸뚱이로 내 작품을 시험해야겠다!'),
(39698, 1, 0, '합금 속의 불순물 같은 놈!'),
(39698, 2, 0, '뜨거운 맛 좀 봐라!'),
(39698, 3, 0, '우리의 군대는 무한하다. 이래 봤자 소용없어...'),
(39705, 0, 0, '해답을 찾고 있는가! 내가 알려 주지! 너희 삶의 해답은 바로 죽음이다!'),
(39705, 1, 0, '주인님의 세계에 너희 자리는 없다.'),
(39705, 2, 0, '흙으로 형상을 빚을 순 있지만... 네놈들로는 못 하지! 쓸모없는 것들!'),
(39705, 3, 0, '날 파괴할 순 없다... 네놈들은... 시간을 벌었을 뿐...'),
(39712, 0, 0, '놈들은 우리의 생명을 앗아 갈지도 모른다. 하지만 절대로 앗아 가지 못할 것이 하나 있으니...'),
(39712, 1, 0, '...그건 바로 우리의 혁신 정신이다!'),
(39712, 2, 0, '내가 여기 있는 제군들에게 바라는 것은 이 구역에 있는 급유소, 주거지, 창고, 농장, 닭장, 화장실, 개집의 정확한 위치를 파악해 오는 것이다.'),
(39712, 3, 0, '제군들이 찾아야 할 자의 이름은 기계박사 텔마플러그라네.'),
(39712, 4, 0, '가서 그를 잡아라.'),
(39712, 5, 0, '밤에 몰래 쳐들어가지 않을 것이다! 사라지더라도 제대로 싸워보고 사라지겠다!'),
(39712, 6, 0, '우리는 죽지 않는다! 우리는 살아남을 것이다! 기억하라. 오늘은 우리의...'),
(39712, 7, 0, '...자율 투쟁의 날이다!'),
(39731, 0, 0, '생명의 순환은 계속된다...'),
(39731, 1, 0, '너희의 생기를 빼앗아 이 방을 푸르게 채우리라!'),
(39731, 2, 0, '생명의 기운이... 풀려난다!'),
(39731, 3, 0, '시들어 버려라!'),
(39731, 3, 1, '생기를 낭비했군.'),
(39732, 0, 0, '그래! 증오에... 몸을 맡겨라...'),
(39732, 1, 0, '너희는 제어할 수 없는 것을 두려워하지. 하지만, 두려움은 제어할 수 있는가?'),
(39732, 2, 0, '최후를 맞이해라!'),
(39732, 2, 1, '이제 이해하겠느냐?'),
(39746, 0, 0, '알렉스트라자가 쓸만한 동맹을 골랐군. ...딱하게도 내 손에 끝장나겠지만!'),
(39746, 1, 0, '기회가 있으리라 생각했나?'),
(39746, 1, 1, '참 잘 된 일이군.'),
(39746, 2, 0, '저놈들을 재로 만들어버려라!'),
(39746, 3, 0, '할리온 님! 저는...'),
(39747, 2, 0, '%s|1이;가; 격노합니다!'),
(39751, 0, 0, '고대의 존재여, 네 힘은 기울어간다. 곧 친구들을 만날 게다.'),
(39751, 1, 0, '아, 날 즐겁게 해주러 왔나 보군.'),
(39751, 2, 0, '발타루스는 누구도 살려두지 않는다!'),
(39751, 2, 1, '이 세상에는 영웅이 너무 많아.'),
(39751, 3, 0, '고통이 두 배면, 재미가 반이지.'),
(39751, 4, 1, '이... 건... 예상하지 못했다..'),
(39788, 0, 0, '안라펫 유닛 작동 종료...'),
(39788, 1, 0, '이 유닛은 정상적인 작동 규약 밖에서 활성화되었습니다. 새로운 작동 매개 변수를 내려받습니다. 내려받기 완료. 유닛 자가 방어 절차가 완전히 활성화되었습니다. 시스템 내 외부 유닛 파괴를 지금 시작합니다.'),
(39788, 2, 0, '목표 제거.'),
(39788, 2, 1, '정화 완료.'),
(39788, 3, 0, '오메가 태세 활성화. 외부 유닛 제거 임박.'),
(39788, 4, 0, '권한 없는 존재 정화 시작.'),
(39797, 0, 0, '좋소, 한번 해 봅시다! 당신이 오우거와 싸우는 동안, 난... 싸움을 피하겠소. 자, 출구로 갑시다!'),
(39797, 1, 0, '우리가 해냈소! 돌아가는 길은 나 혼자 찾겠소. 부탁할 게 하나 있는데, 로이스 더스크위스퍼에게 멍청한 황혼의 눈은 궁둥이에나 붙이라고 말해 주시오.'),
(39853, 0, 0, '네가 돌아온 걸 알고 있었다, 이손드레... 그저 시간 문제였을 뿐이야...'),
(39853, 1, 0, '평화? 평화라고?'),
(39853, 2, 0, '평화란 부질없는 꿈일 뿐! 이 세상은 악몽이 지배할 것이다!'),
(39853, 3, 0, '내 정수는... 사라지지... 않을 거다...'),
(39863, 0, 0, '두 세계의 압력에서 벗어난 %s|1이;가; 생명력을 회복합니다.'),
(39863, 1, 0, '보잘것없는 벌레들아! 너무 늦었다. 루비 성소는 이미 끝났다!'),
(39863, 2, 0, '너희 세상에 파멸의 바람이 불어온다. 파괴의 시대가 새로이 도래할 때 모두 그 증인이 되리라!'),
(39863, 3, 0, '하늘이 타오른다!'),
(39863, 4, 0, '황혼 세계에서는 고통만이 있으리라! 자신 있다면 들어와 봐라!'),
(39863, 5, 0, '필멸자들아, 승리를 만끽해라. 그것이 마지막일 테니. 주인님이 돌아오시면 이 세상은 불타버리리라!'),
(39863, 6, 0, '"영웅"이 또 하나 가셨군.'),
(39863, 7, 0, '아직 멀었다...'),
(39863, 8, 0, '당신의 노력으로 %s|1이;가; 현실 세계 밖으로 밀려납니다!'),
(39863, 9, 0, '동료들의 노력으로 %s|1이;가; 현실 세계로 밀려납니다!'),
(39873, 0, 0, '나를 도우러 오너라, 비룡이여!'),
(39908, 0, 0, '좋아요. 갑시다! 최종 출입 암호를 넣기만 하면 이 출입문이 작동할 거예요...'),
(39908, 1, 0, '자, 됐습니다! 제어실은 바로 이 뒤에 있을 거예요... 우와...'),
(39908, 2, 0, '어? 여긴 제어실이 아니잖아! 수호 장치가 또 하나 버티고 있는 데다가, 어떻게인지는 몰라도 망할 놈의 바위 트로그가 침입했군요. 트로그라. 왜 하필이면 트로그냐고!'),
(39908, 3, 0, '음... 잠깐 생각 좀 하죠.'),
(39908, 4, 0, '거대한 정령이 네 단에 있고...'),
(39908, 5, 0, '거울이 구석구석을 비추고 있고...'),
(39908, 6, 0, '알았습니다! 이 방을 설명하는 서판을 본 적이 있어요. 여긴 빛의 전당입니다! 좋아요. 이제 간단합니다. 모험가 여러분이 정령 넷을 처치하면 저 끝에 있는 문의 개폐 장치가 작동할 겁니다!'),
(39908, 7, 0, '하나 잡았고!'),
(39908, 8, 0, '또 하나 잡았군요! 광선 좀 보세요! 저 끝에 있는 문에 연결된 것 같습니다!'),
(39908, 9, 0, '하나만 더 잡으면 됩니다! 문이 거의 열렸어요!'),
(39908, 10, 0, '이야, 해냈군요! 전당 문이 열리고 있습니다. 이제... 허? 아이고...'),
(39908, 11, 0, '해냈어요! 이제 제어실로 들어갑시다!'),
(39908, 12, 0, '아, 좋아요! 이제 잠깐이면 됩니다...'),
(39921, 0, 0, '지금 악당 찾아낸다! 따라와!'),
(39921, 0, 1, '이쪽에 숨어 있다! 서둘러!'),
(39921, 1, 0, '우린 악당 찾는다! 빨리!'),
(39921, 1, 1, '이쪽이야! 놈들을 잡아!'),
(39974, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(39974, 1, 0, '모든 것이 재가 되리라.'),
(39974, 1, 1, '심연의 불꽃이여, 황혼의 망치단이 너를 부른다!'),
(39974, 1, 2, '세상을 활활 불태우고 싶군...'),
(39974, 1, 3, '모든 것의 종말이 다가온다!'),
(39974, 1, 4, '불꽃이... 날름댄다... 태운다... 언제나 태운다...'),
(39974, 1, 5, '세상은 불타 버릴 것이다.'),
(39974, 1, 6, '이래 봤자 종말이 조금 늦춰질 뿐이다.'),
(39974, 1, 7, '좋은 제물이 되겠군.'),
(39985, 0, 0, '%s|1이;가; 분노에 휩싸입니다!'),
(40083, 0, 0, '주위를 회전하는 구슬들이 고동치며 어둠의 기운을 내뿜습니다!'),
(40107, 0, 0, '어리석은 필멸의 존재 같으니. 육체는 불타리라.'),
(40107, 1, 0, '다른 자들이 올 것이다... 필멸의 존재... 네놈들의 시대는 끝났다.'),
(40142, 0, 0, '두 세계의 압력에서 벗어난 %s|1이;가; 생명력을 회복합니다.'),
(40142, 1, 0, '어둠을 경계하라!'),
(40142, 2, 0, '나는 빛이자 어둠이다! 필멸자들아, 데스윙의 사자 앞에 무릎 꿇어라!'),
(40142, 3, 0, '동료들의 노력으로 %s|1이;가; 황혼 세계로 밀려납니다!'),
(40142, 4, 0, '당신의 노력으로 %s|1이;가; 황혼 세계 밖으로 밀려납니다!'),
(40147, 0, 0, '악에 받친 남작 게돈이 최후의 힘을 모아 당신을 살아 있는 폭탄으로 만들었습니다! 동료에게서 떨어지십시오!'),
(40148, 0, 0, '물러나십시오!!!'),
(40148, 0, 1, '불이 가라앉을 때까지 그에게서 떨어지십시오!'),
(40148, 0, 2, '자, 옵니다! 물러서십시오!'),
(40148, 0, 3, '조심하십시오!'),
