(40177, 0, 0, '안 돼! 이거 처리 못 하면 트롱구스 매 맞는다.'),
(40177, 1, 0, '트롱구스가 네 몸 쓸 거다. 어디에 쓰지...'),
(40177, 1, 1, '하하, 너 금방 망가진다!'),
(40177, 2, 0, '죽는 거... 괜찮다. 제일 좋은 건 아니지만, 실패하고 매 맞는 것보단...'),
(40177, 3, 0, '으하하, 이건 절대로 못 뚫을 거다!'),
(40177, 4, 0, '흐아! 트롱구스가 다 벤다!'),
(40177, 5, 0, '으헤헤, 이건 아플 거다!'),
(40260, 0, 0, '저도 지원할게요!'),
(40260, 0, 1, '볼진 님을 위해서라면!'),
