(40301, 0, 0, '우두머리 암호랑이가 나타납니다. 전투를 통해 당신을 증명하십시오!'),
(40319, 0, 0, '뼛속부터 새카맣게 불태워 주마!'),
(40319, 1, 0, '식은 죽 먹기군!'),
(40319, 2, 0, '좀 더 제대로 준비해 왔어야지!'),
(40319, 3, 0, '발리오나, 놈들을 처치해라! 복수해 줘!'),
(40319, 4, 0, '정령이여! 불태워 버려라!'),
(40319, 4, 1, '불이여... 활활 타올라라!'),
(40319, 5, 0, '용이여, 내 명령을 따라라! 날 태워라!'),
(40320, 0, 0, '저들이 너를 못 죽이면 내가 그렇게 해 주지!'),
(40320, 1, 0, '네 뒤를 봐주다 죽을 순 없지!'),
(40352, 0, 0, '검은창 부족이여, 이제 영혼들의 조언을 구하겠노라! 자, 북을 울릴 준비를 하라!'),
(40352, 1, 0, '영혼이시여, 앞으로 우리의 갈 길을 여쭙고자 여기에 모였습니다.'),
(40352, 2, 0, '센진의 아들이자 우리의 지도자 볼진이 검은창 부족 전체를 대상으로 소집 명령을 내렸습니다. 메아리 섬을 되찾으려는 것입니다.'),
(40352, 3, 0, '영혼이시여! 여기 제 몸을 바칩니다! 저를 통해 말씀해 주십시오! 바로 지금이, 위대한 볼진이 이 과업을 추진하기에 적당한 시기입니까?'),
(40352, 4, 0, '의술사여, 선조들은 듣고 있느니라!'),
(40352, 5, 0, '너희들의 계획이 마음에 든다, 검은창 부족이여. 센진의 아들은 올바른 길을 걷고 있도다.'),
(40352, 6, 0, '너희들 앞에 놓인 임무가 쉽지는 않을 것이다. 하지만 우리가 곁에 있겠노라.'),
(40352, 7, 0, '메아리 섬을 떠나면서, 너희들은 고향을 버리고 선조들의 로아들을 버렸다. 로아들이 그런 대접을 받고 기뻐할 리가 있겠느냐?'),
(40352, 8, 0, '잘라제인을 물리치려면 죽은 이들의 수호자, 브원삼디와 화해해야 한다. 다른 방법은 없다. 센진의 아들에게 돌아가 그대로 전해라.'),
(40352, 9, 0, '영혼들이 우리에게 답을 내려 주셨다! 우리는 메아리 섬을 되찾을 것이다!'),
(40391, 0, 0, '고맙다, 정찰병. 계속 수고 부탁한다. 하지만 지금은 휴식을 좀 취하도록. 이상.'),
(40416, 0, 0, '병력이 상당히 많습니다. 무언가 계략을 꾸미는 것 같습니다.'),
(40416, 0, 1, '잘라제인은 사술에 걸린 트롤 병력의 대부분을 큰 섬의 숲 안쪽에 숨겨두었습니다.'),
(40460, 0, 0, '화염 감시기를 방어하십시오!'),
(40460, 1, 0, '승리했습니다! 화염 감시기를 방어했습니다.'),
(40460, 2, 0, '패배했습니다! 화염 감시기가 파괴되었습니다.'),
(40483, 1, 0, '싸움이 일어났습니다!'),
(40484, 0, 0, '칠흑 같은 어둠의 시대가 올 것이다!'),
(40484, 1, 0, '으하하하하!'),
(40484, 1, 1, '좋은 제물이로군.'),
(40484, 2, 0, '이와크 마크 오우, 이와크 막 싸아크. 이와크 마 쉬픈.'),
(40484, 3, 0, '플라크 겟! 어둠은 항상 굶주려 있다!'),
(40484, 4, 0, '오라, 고통이여... 오라, 혼돈이여!'),
(40494, 1, 0, '싸움이 일어났습니다!'),
(40529, 1, 0, '싸움이 일어났습니다!'),
(40530, 1, 0, '싸움이 일어났습니다!'),
(40551, 0, 0, '필멸의 존재! 넌 선을 넘었다.'),
(40551, 0, 1, '안 돼, 안 돼! 이건 우리 것이다...'),
(40551, 0, 2, '주인님께 이런 모욕을 안겨드릴 순 없다!'),
(40551, 0, 3, '주인님의 손아귀에서 쉽게 벗어날 수 없다...'),
(40551, 0, 4, '이... 저주받을... 연약한 존재가!'),
(40598, 0, 0, '경주주최자 미글렌이 화장실에서 탈출하고는 마구 몸을 휘저으며 쾌속선을 향해 헤엄칩니다.'),
(40599, 0, 0, '러그피즐이 화장실에서 탈출하고는 마구 몸을 휘저으며 쾌속선을 향해 헤엄칩니다.'),
(40737, 0, 0, '적이 너무 많습니다! 주술사님, 어떻게든 해 보십시오!'),
(40737, 1, 0, '제군들, 쉴 수 있을 때 휴식을 취하도록. 아직 끝이 아니다...'),
(40737, 2, 0, '전원, 준비하라!'),
(40737, 3, 0, '빚을 갚아주자!'),
(40737, 4, 0, '주위를 경계하라! 끌려가지 마라!'),
(40737, 5, 0, '포기하지 마라! 싸워라! 얼라이언스를 위해 싸우자!'),
(40737, 6, 0, '끝없이... 몰려오는군...'),
(40737, 7, 0, '제 부하들이... 모두 잡혀갔습니다... 가세요! 당신이라도 살아남으십시오!'),
(40788, 0, 0, '새로운 몸을 찾아야만 한다.'),
(40788, 1, 0, '너무 약해서 쓸모가 없군.'),
(40788, 1, 1, '남는 것은 오로지 기억뿐...'),
(40788, 2, 0, '그들은 생명의 순환을 벗어난 존재다.'),
(40788, 3, 0, '구르샤만이 존재한다.'),
(40788, 3, 1, '포기해라...'),
(40788, 3, 2, '네 동료가 누구인가?'),
(40788, 4, 0, '이것이, 진정, 현실인가?'),
(40792, 0, 0, '아... 두려움을 모르는 내 부관들이로군.'),
(40792, 1, 0, '하지만 여기까지 오다니 괜한 짓을 했다.'),
(40792, 2, 0, '내가 물을 정화하면, 저 역겨운 것들은 혼란에 빠져 우왕좌왕할 것이다! 보아라!'),
(40792, 3, 0, '아... 역겨운 것들이 나를 더럽힌다!'),
(40792, 4, 0, '힘이... 빠져나간다...'),
(40792, 5, 0, '멍청이들! 도움이 좀 돼 봐라...'),
(40792, 6, 0, '조바심 내지 마라. 물이 거의 정화됐다.'),
(40792, 7, 0, '야수가 돌아왔다! 놈이 물을 오염시키게 두면 안 된다!'),
(40792, 8, 0, '순수한 물의 힘을 느껴 보아라!'),
(40792, 9, 0, '물이 모두 정화되었다! 그 힘을 마셔라!'),
(40792, 10, 0, '역시 너희 족속은 믿을 수가 없어.'),
(40792, 11, 0, '너희는 내 영지에 있을 자격이 없다...'),
(40792, 11, 1, '네놈들 따위를 신경 쓰다니... 실수였다...'),
(40792, 12, 0, '드디어 내 영지에서 역겨움을 모조리 씻어냈구나.'),
(40792, 13, 0, '이제 너희는 물러가도 좋다.'),
(40825, 0, 0, '고맙습니다, 친구여. 용서하십시오. 전... 전 너무 약해져서 도움이 못 되겠습니다.'),
(40825, 1, 0, '너무... 힘들군요. 저 없이 계속 가셔야 합니다. 저는 기운을 좀 회복한 후 돌아가도록 하겠습니다.'),
(40845, 0, 0, '더럽다! 네놈의 나약한 육체가 내 작품을 더럽힌다.'),
(40959, 0, 0, '흠, 좋은 보물이다.'),
(40959, 0, 1, '반짝이는 거 많다. 제독보단 네가 더 좋은 것 같다.'),
(40959, 0, 2, '나 보물 숨기고 쉬러 간다.'),
(40959, 0, 3, '싸움 싫어. 돈 줘.'),
(40959, 0, 4, '이거 많은 금이다. 나 이제 못 본 척해줄게.'),
(40959, 0, 5, '쌍엄니는 절대 내게 보물을 주지 않는다!'),
(40959, 0, 6, '제독과 싸우고 싶어? 보물 많이 줘. 난 이만 가볼께!'),
(40991, 0, 0, '타란 대장님께 설치한 원격 관찰로봇이 제대로 작동하는 것을 확인하는 즉시 카라노스로 귀환할 것이라고 전해 주십시오.'),
(40994, 0, 0, '어서 이곳을 벗어나 트롤들과 맞서 싸우고 싶어 몸이 근질거리는군요.'),
(41056, 0, 0, '대격변이 일어난 뒤로 하루도 쉬는 날 없이 전투를 치러왔습니다. 휴식을 취할 수 있어서 정말 다행이군요. 비록 잠시뿐이라도 말이죠.'),
(41112, 0, 0, '쓸데없이 참견한 대가를 치르게 될 것이다, $c 놈아!'),
(41114, 4, 0, '아비아나의 제단에서 다시 만나요, $n 님!'),
(41196, 0, 0, '크레이블 콜비어드가 기절했습니다. 지금 얼라이언스의 제안서를 훔치십시오!'),
(41199, 0, 0, '경주로관리인 제린이 기절했습니다. 지금 호드의 제안서를 훔치십시오!'),
(41235, 0, 0, '제때에 오셨군요. 화살이 거의 떨어져 가던 참이었습니다.'),
(41235, 0, 1, '고맙네.'),
(41235, 0, 2, '놈들의 공격 빈도가 잦아지고 있습니다. 계속 이동하시는 게 좋겠습니다.'),
(41236, 0, 0, '네가 누군지 안다, $n! 너처럼 추잡한 놈에게 신성한 불꽃을 내줄 순 없지!'),
(41237, 0, 0, '%s|1이;가; 공기를 들이마시려고 헐떡거립니다.'),
(41237, 1, 0, '살려주셔서 감사합니다!'),
(41251, 0, 0, '공구를... 들 수가... 없잖아...'),
(41251, 0, 1, '조그맣게 만들지 마!'),
(41251, 0, 2, '무슨 짓을 하는 거야?'),
(41251, 0, 3, '왜 다른 친구들이 다 커진 거지?'),
(41251, 1, 0, '저주 좀 없애줘!'),
(41255, 0, 0, '한낱 벌레 같은 것이! 널 처단하고 제단도 불태우겠다!'),
(41255, 1, 0, '시간을 벌었을 뿐.. 목숨은 부지하지 못할 것이다... 부화장이 남아 있으니...'),
(41261, 0, 0, '한낱 벌레 같은 것이! 널 처단하고 제단도 불태우겠다!'),
(41261, 1, 0, '시간을 벌었을 뿐.. 목숨은 부지하지 못할 것이다... 부화장이 남아 있으니...'),
(41287, 0, 0, '지금 가고 있습니다, $n 님! 세스리아의 주의를 끄시는 동안, 저희가 돌아서 공격을 하겠습니다.'),
(41302, 0, 0, '막아라!'),
(41302, 0, 1, '검은 금은 다른 곳에서 찾으시지!'),
(41302, 0, 2, '원유 유출을 막아라! 왜 그 유명한 유출 사건 때 먹히던 방법 있잖아!'),
