(41302, 0, 5, '형제자매여! 무기를 들어라! 이들이 우리의 땅을 파괴하려 한다!'),
(41305, 0, 0, '막아라!'),
(41305, 0, 1, '검은 금은 다른 곳에서 찾으시지!'),
(41305, 0, 2, '금이 없으면 원유도 없다!'),
(41305, 0, 3, '피를 보리라!'),
(41305, 0, 4, '형제자매여! 무기를 들어라! 이들이 우리의 땅을 파괴하려 한다!'),
(41306, 0, 0, '막아라!'),
(41306, 0, 1, '원유 유출을 막아라! 왜 그 유명한 유출 사건 때 먹히던 방법 있잖아!'),
(41306, 0, 2, '금이 없으면 원유도 없다!'),
(41306, 0, 3, '피를 보리라!'),
(41306, 0, 4, '형제자매여! 무기를 들어라! 이들이 우리의 땅을 파괴하려 한다!'),
(41306, 0, 5, '우리의 새 터전을 오염시키지 마라!'),
(41376, 0, 0, '겁쟁이들아! 여왕에게서 도망치면 끔찍한 결과가 있으리라!'),
(41376, 1, 0, '암흑불길이 어떻게 뼈를 일으키는지 봐라! 저들은 내 명에 따라 싸우지!'),
(41376, 2, 0, '저주받을 필멸자들! 내 소중한 작품을 이렇게 망치다니! 쓴맛을 봐야 정신을 차리겠군!'),
(41376, 3, 0, '수영은 할 줄 알겠지... 용암 속에서 말이다!'),
(41376, 4, 0, '품위있는 집주인답게 행동하려 했건만, 네놈들이 도무지 죽질 않는군! 겉치레는 이제 집어치우자고. 그냥 모두 없애 버리겠어!'),
(41376, 5, 0, '살을 재로 만들어 주마!'),
(41376, 6, 0, '즐거운 시간이었다!'),
(41376, 6, 1, '그렇게 죽고 싶었나?'),
(41376, 7, 0, '패배가 이렇게 쓰디썼던가... 으아아...'),
(41376, 8, 0, '전기가 튀며 파지직하는 소리가 납니다!'),
(41378, 0, 0, '날 방해하게 둘 것 같으냐! 주인님을 기다리게 해선 안 돼! 또 실패하면 안 돼!'),
(41378, 1, 0, '나 같은 천재는 다시 없을 거...'),
(41378, 2, 0, '낭비는 금물!'),
(41378, 2, 1, '살을 모으고, 뼈를 거둔다!'),
(41378, 3, 0, '섞고 흔들어서, 열을 가한다...'),
(41378, 4, 0, '이건 좀 불안정하지만... 실패 없이는 성공도 없는 법이지!'),
(41378, 5, 0, '급격한 온도 변화에 필멸의 육신이 어떻게 반응할까? 아하하! 실험해 봐야지! 과학을 위해!'),
(41378, 6, 0, '너무 극단적인 실험을 하면 결과를 예측할 수가 없는데...'),
(41378, 7, 0, '저놈들은 지능이 낮은 대신 흉포함은 끝내주지!'),
(41378, 7, 1, '너희는 내 실패작에도 못 미쳐!'),
(41378, 8, 0, '아직 이르지만 할 수 없지... 녀석들을 시험해 봐야겠군! 일급 실험체를 상대해 봐라!'),
(41378, 8, 1, '내 두뇌가 주먹으로 승화되었다나 할까! 얘들아, 해치워라!'),
(41379, 0, 0, '하하하... 영광스러운 마지막을 향해 역경을 뚫고 온 영웅들이로군. 기분은 좀 어떤가? 마지막 전투를 벌일 준비는 됐나? 그럼 내 궁극의 창조물을 보여주지! 일어나라, 자매여!'),
(41379, 1, 0, '여왕이 되살아났다! 자, 오닉시아를 맞이하라... 내 작품 중 최고라고 할 수 있지.'),
(41379, 2, 0, '사랑하는 나의 자매여, 배가 고픈가? 그럼 우리 적을 먹어치워라!'),
(41442, 0, 0, '눈이 없어도 나는 적을 볼 수 있다. 너희가 풍기는 악취와 시끄러운 발걸음 소리만으로도 충분해!'),
(41442, 1, 0, '눈은 있으되 진실은 보지 못하는 것들. 모든 것의 종말을 받아들여라!'),
(41442, 1, 1, '어둠 속에서 죽음이 널 기다린다.'),
(41442, 2, 0, '이 비참한 생이... 마침내 끝나는구나.'),
(41442, 3, 0, '이글거리는 불길에서 도망갈 수는 없다!'),
(41442, 4, 0, '그래, 도망가라! 발을 디딜 때마다 맥박은 빨라지지. 점점 더 크게 울리는구나... 귀청이 터질 것만 같군! 넌 달아날 수 없다!'),
(41468, 0, 0, '네치 오와치, $c님. 반갑습니다, 그리고 감사합니다.'),
(41468, 1, 0, '곧 다시 뵙겠습니다. 함께 그림토템 부족 겁쟁이들에게 공포의 의미를 가르쳐줍시다!'),
(41671, 0, 0, '어서 빨리 가족이 있는 고향으로 돌아갔으면 좋겠군요. 구해주셔서 정말 감사합니다.'),
(41671, 0, 1, '여기서 꼼짝없이 죽는 줄로만 알았습니다.'),
(41671, 0, 2, '놈들이 저를 없애버릴 줄로만 알고 있었습니다!'),
(41671, 0, 3, '빛의 축복이 함께하기를. 구해주셔서 고맙습니다!'),
(41671, 0, 4, '고맙습니다!'),
(41671, 0, 5, '트로그 놈들이 나타난 뒤로 제가 본 것 중 가장 멋진 일을 해 주신 분이십니다!'),
(41738, 0, 0, '꽉 잡으십시오. 길이 매우 험할 겁니다. 틈새를 노리는 나이트 엘프들을 조심하십시오!'),
(41738, 1, 0, '신병들이 새로 수송됐습니다, 사우르보즈. 제 마차에 있는 이전 대대원들같이 시체가 되어 돌아오지 않기를 바라야겠군요.'),
(41739, 0, 0, '너같이 흉악한 오크가 얼라이언스 놈들 잡는 거 말고 신나는 일이 또 뭐가 있겠어?'),
(41739, 1, 0, '아우, 이 징그러운 자식...'),
(41739, 2, 0, '알겠습니다! 어서 움직입시다.'),
(41740, 0, 0, '얼라이언스 놈들을 없애버리는 것만큼 신나는 일도 없지.'),
(41740, 1, 0, '내가 타우렌 여자라면 껌벅 죽는 거 잘 알잖나. 내 유일한 약점이라고...'),
(41763, 0, 0, '%s|1이;가; 숨을 쉬려고 헐떡이며 추위에 몸을 떱니다.'),
(41989, 0, 0, '아우! 어딜 만져요!'),
(41989, 0, 1, '어느 길로 가라고요???'),
(41989, 0, 2, '곰마워요!'),
(41989, 0, 3, '너님 친구예요. 곰마워요!'),
(41989, 0, 4, '왜 이런 일 일어나요?'),
(42021, 0, 0, '저기 배 보이나?'),
(42021, 1, 0, '전투에서 돌아온 배는 저것뿐이네. 그나마도 수리 중이지.'),
(42021, 2, 0, '용병을 고용해서라도 출항해야지. 안 그러면 지원군을 못 보내니까.'),
(42021, 3, 0, '입대를 환영하네, 신병.'),
(42021, 4, 0, '쓸데없는 생각은 그만두게.'),
(42021, 5, 0, '십 년을 호드와 싸우면서, 이번처럼 상황이 나쁜 건 처음 보네.'),
(42021, 6, 0, '지금은 눈앞에 닥친 전투에만 집중하게. 살아야 걱정도 하는 거지.'),
(42021, 7, 0, '여기 오는 길에 공원에 들렀었지. 싹 불탔더군...'),
(42021, 8, 0, '그래, 용이 공격했을 때 나도 있었어.'),
(42021, 9, 0, '놈이 마음만 먹었더라면 도시 전체를 쓸어버렸을걸. 우린 그냥 당했을 테고.'),
(42021, 10, 0, '왜 물러갔는지 알아?'),
(42021, 11, 0, '몰라. 도저히 이해가 안 돼...'),
(42021, 12, 0, '그냥 날아와서 공원만 불태우고 가 버렸다고.'),
(42021, 13, 0, '뭐... 미친 용이었나 보지.'),
(42021, 14, 0, '여기서도 어렴풋이 보이는 것 같군... 저기 수평선 너머에 말이야.'),
(42021, 15, 0, '새로운 섬 말일세. 지진이 일어나고 나서 떠올랐지.'),
(42021, 16, 0, '우린 저것 때문에 싸우는 거야. 적어도 이 전선에서는.'),
(42021, 17, 0, '흠, 이번이 세 번째라네.'),
(42021, 18, 0, '치열한 전투가 벌어지지...'),
(42021, 19, 0, '호드가 저 섬을 차지하면 스톰윈드는 끝난 거나 마찬가지야. 호드도 이 사실을 알고 있지.'),
(42022, 0, 0, '왜 용병선을 타고 가는 거죠? 원래는 해적을 보자마자 해치우는 게 우리가 할 일 아닙니까?'),
(42022, 1, 0, '뭐, 이해는 가지만... 그래도 마음에 좀 걸립니다.'),
(42059, 0, 0, '하루걸러 한 번씩은 지진이 나고, 미친 용이 세상을 조각내고... 다음은 뭘까요?'),
(42059, 1, 0, '네.'),
(42059, 2, 0, '정확히 뭐 말씀이십니까?'),
(42059, 3, 0, '저기 가 보셨나요?'),
(42059, 4, 0, '네... 저도 알 것 같습니다.'),
(42103, 0, 0, '그만들 해라.'),
(42103, 1, 0, '정신 똑바로 차려라! 잠시 후면 오크와 싸울 테니.'),
(42103, 2, 0, '잘 들어라! 곧 우리가 탈 배가 올 것이다.'),
(42103, 3, 0, '정렬!'),
(42103, 4, 0, '좋다, 제군들! 이동!'),
(42186, 0, 0, '침입자 발견. 주 방어 회로망 작동 시작.'),
(42186, 1, 0, '방어 시스템 무효화. 동력 저하...'),
(42186, 2, 0, '전기골렘 유닛 가동.'),
(42186, 3, 0, '용암골렘 유닛 가동.'),
(42186, 4, 0, '맹독골렘 유닛 가동.'),
(42186, 5, 0, '비전골렘 유닛 가동.'),
(42186, 6, 0, '전기골렘 유닛 방어막 시스템 작동 개시.'),
(42186, 7, 0, '용암골렘 유닛 방어막 시스템 작동 개시.'),
(42186, 8, 0, '맹독골렘 유닛 방어막 시스템 작동 개시.'),
(42186, 9, 0, '비전골렘 유닛 방어막 시스템 작동 개시.'),
(42186, 10, 0, '과잉 에너지 용암골렘 유닛에게 전송 중. 화염방사기 가동.'),
(42188, 0, 0, '세계의 심장에는 아무도 들어갈 수 없다!'),
(42188, 1, 0, '생명의 순환이 완성되었다.'),
(42188, 2, 0, '내 몸에 부딪히고, 부서져라! 대지의 강력함을 느껴 보아라!'),
(42188, 3, 0, '수호자가 쓰러졌다. 세계의 심장이 위험에 노출됐다!'),
(42291, 0, 0, '광학 감지 장치에 이상 발견! 시스템을 정지합니다...'),
(42298, 0, 0, '라젤리크의 아뮬렛 안에 담긴 힘으로...'),
(42298, 1, 0, '... 그대를 라젤리크의 보금자리로 잇노라!'),
(42308, 0, 0, '그러게 말이야, 신참...'),
(42308, 1, 0, '아무래도 마차를...'),
(42308, 2, 0, '...말보다 앞세워 버렸군.'),
(42309, 0, 0, '끔찍한 살육 현장입니다, 부관님. 모두 살해당했습니다.'),
(42309, 1, 0, '시신의 체온으로 보아 죽은 지 여섯 시간은 넘지 않은 것 같습니다.'),
(42309, 2, 0, '늙은 블랑쉬까지 저렇게 만들다니... 정말 안타깝습니다.'),
(42317, 0, 0, '흥, 우리는 강력한 군대를 조직해 텔마플러그의 하수인들을 모조리 무찌르며 도시에 진입했지. 하지만 비열한 텔마플러그가 마지막으로 더러운 수작을 부렸어...'),
(42317, 1, 0, '이 영상을 잘 보게. 자네에게 놈리건 작전에 대해 알려주고 싶은 게 좀 있다네.'),
(42317, 2, 0, '하아... 우린 퇴각할 수밖에 없었지. 텔마플러그는 지금도 방사능을 방패 삼아 놈리건에 숨어 있네. 크러쉬코그를 지상에 내보내 우릴 괴롭히면서 말이야!'),
(42383, 0, 0, '이봐, $g친구:아가씨;, 난 말썽에 휘말리고 싶지 않아. 알겠어? 누가 죽였는지는 못 봤지만 소리는 똑똑히 들었어! 고함 소리가 요란했지. 인간 목소리였어... 무슨 말인지 알겠지? 널 두들겨 패고 신발을 빼앗고 싶어지기 전에 어서 꺼져.'),
(42383, 1, 0, '누가 죽였는지는 못 봤어, $g친구:아가씨;. 하지만 냄새는 맡았지. 너처럼 돈 많은 놈 냄새였어. 정말 안타까운 일이야. 펄브라우 일가는 여기서 오래 살았거든. 끼니나 잠잘 땅 한 뙈기도 기꺼이 나눠 주던 좋은 사람들이었지.'),
(42383, 2, 0, '누가 펄브라우 일가를 죽였냐고? 누군지 알려 주지. 바로 국왕 바리안 린이야! 우리도 죽이고 있잖아. 부랑자 한 명씩 말이지. 내가 확실히 말할 수 있는 건, 경비병들이 오기 몇 시간 전에 놀 몇 마리가 그곳을 떠나는 걸 봤다는 것뿐이야.'),
(42383, 3, 0, '너와 나만의 비밀인데, 멀록이 펄브라우 일가를 죽였어. 그래, 내 두 눈으로 똑똑히 봤지. 며칠, 아니 몇 달 동안 그곳을 염탐했을 거야. 저쪽의 경비 나으리와 멍청이 부대가 온다는 낌새를 채자 급히 떠나더군...'),
(42383, 4, 0, '심판의 날이 온다! 결사단은 다시 태어날 것이다!'),
(42383, 4, 1, '이제 선을 넘었군! 주먹맛 좀 봐라!'),
(42383, 4, 2, '나한테서는 아무것도 알아내지 못할 거다!'),
(42383, 4, 3, '짐승처럼 사는 것도 서러운데 네 모욕까지 들어야 하냐!'),
(42383, 4, 4, '너한테는 아무 말도 안 해!'),
(42383, 4, 5, '네 간을 팔면 돈 좀 되겠군.'),
(42383, 4, 6, '앞을 차 줄까, 뒤를 차 줄까? 네가 골라.'),
(42383, 4, 7, '그 사람들은 자연사했어...'),
(42383, 4, 8, '너희 부자 놈들은 다 똑같아!'),
(42383, 4, 9, '돈으로 날 살 수는 없어! 죽어라!'),
(42383, 5, 0, '심판의 날이 온다! 결사단은 다시 태어날 것이다!'),
(42383, 5, 1, '이제 선을 넘었군! 주먹맛 좀 봐라!'),
(42383, 5, 2, '나한테서는 아무것도 알아내지 못할 거다!'),
(42383, 5, 3, '짐승처럼 사는 것도 서러운데 네 모욕까지 들어야 하냐!'),
(42383, 5, 4, '너한테는 아무 말도 안 해!'),
(42383, 5, 5, '네 간을 팔면 돈 좀 되겠군.'),
(42383, 5, 6, '앞을 차 줄까, 뒤를 차 줄까? 네가 골라.'),
(42383, 5, 7, '그 사람들은 자연사했어...'),
(42383, 5, 8, '너희 부자 놈들은 다 똑같아!'),
(42383, 5, 9, '돈 내놓으라고 했잖아, 친구!'),
(42383, 6, 0, '오늘 저녁도 신발 가죽을 씹어야겠군.'),
(42383, 6, 1, '하하하! 재밌는 농담이야, 펭귄 씨! 정말 재밌어!'),
(42383, 6, 2, '내가 어쩌다 이렇게 됐지? 난 한때 스톰윈드의 왕이었다고!'),
(42383, 6, 3, '더는 버틸 수 없을 것 같아...'),
(42383, 6, 4, '내 땅에서 꺼져!'),
(42383, 6, 5, '데피아즈에게 털리던 때가 그립군. 적어도 그놈들은 가끔 먹을 것이라도 조금 남겨 줬는데.'),
(42383, 6, 6, '배고파 죽겠어!'),
(42383, 6, 7, '돌도 먹을 수 있으려나? 여기엔 돌이 널렸잖아. 상상해 봐! 그걸 알아내면 세상에서 제일가는 부자가 될 거야!'),
(42383, 7, 0, '횡재했다!'),
(42383, 8, 0, '맛있고 깨끗한 흙을 찾은 것 같아! 오늘 밤은 왕처럼 먹는 거야, 펭귄 씨! 물론 나눠 줄 거지! 넌 내 가장 친한 친구잖아!'),
(42383, 9, 0, '이봐! 거기 너! 내 땅에서 꺼져!'),
(42383, 10, 0, '%s|1이;가; 겁에 질려 달아나려 합니다!'),
(42384, 0, 0, '이봐, $g친구:아가씨;, 난 말썽에 휘말리고 싶지 않아. 알겠어? 누가 죽였는지는 못 봤지만 소리는 똑똑히 들었어! 고함 소리가 요란했지. 인간 목소리였어... 무슨 말인지 알겠지? 널 두들겨 패고 신발을 빼앗고 싶어지기 전에 어서 꺼져.'),
(42384, 1, 0, '누가 죽였는지는 못 봤어, $g친구:아가씨;. 하지만 냄새는 맡았지. 너처럼 돈 많은 놈 냄새였어. 정말 안타까운 일이야. 펄브라우 일가는 여기서 오래 살았거든. 끼니나 잠잘 땅 한 뙈기도 기꺼이 나눠 주던 좋은 사람들이었지.'),
(42384, 2, 0, '누가 펄브라우 일가를 죽였냐고? 누군지 알려 주지. 바로 국왕 바리안 린이야! 우리도 죽이고 있잖아. 부랑자 한 명씩 말이지. 내가 확실히 말할 수 있는 건, 경비병들이 오기 몇 시간 전에 놀 몇 마리가 그곳을 떠나는 걸 봤다는 것뿐이야.'),
(42384, 3, 0, '너와 나만의 비밀인데, 멀록이 펄브라우 일가를 죽였어. 그래, 내 두 눈으로 똑똑히 봤지. 며칠, 아니 몇 달 동안 그곳을 염탐했을 거야. 저쪽의 경비 나으리와 멍청이 부대가 온다는 낌새를 채자 급히 떠나더군...'),
(42384, 4, 0, '심판의 날이 온다! 결사단은 다시 태어날 것이다!'),
(42384, 4, 1, '이제 선을 넘었군! 주먹맛 좀 봐라!'),
(42384, 4, 2, '나한테서는 아무것도 알아내지 못할 거다!'),
(42384, 4, 3, '짐승처럼 사는 것도 서러운데 네 모욕까지 들어야 하냐!'),
(42384, 4, 4, '너한테는 아무 말도 안 해!'),
(42384, 4, 5, '네 간을 팔면 돈 좀 되겠군.'),
(42384, 4, 6, '앞을 차 줄까, 뒤를 차 줄까? 네가 골라.'),
(42384, 4, 7, '그 사람들은 자연사했어...'),
(42384, 4, 8, '너희 부자 놈들은 다 똑같아!'),
(42384, 4, 9, '돈으로 날 살 수는 없어! 죽어라!'),
(42384, 5, 0, '심판의 날이 온다! 결사단은 다시 태어날 것이다!'),
(42384, 5, 1, '이제 선을 넘었군! 주먹맛 좀 봐라!'),
(42384, 5, 2, '나한테서는 아무것도 알아내지 못할 거다!'),
(42384, 5, 3, '짐승처럼 사는 것도 서러운데 네 모욕까지 들어야 하냐!'),
(42384, 5, 4, '너한테는 아무 말도 안 해!'),
(42384, 5, 5, '네 간을 팔면 돈 좀 되겠군.'),
(42384, 5, 6, '앞을 차 줄까, 뒤를 차 줄까? 네가 골라.'),
(42384, 5, 7, '그 사람들은 자연사했어...'),
(42384, 5, 8, '너희 부자 놈들은 다 똑같아!'),
(42384, 5, 9, '돈 내놓으라고 했잖아, 친구!'),
(42384, 6, 0, '오늘 저녁도 신발 가죽을 씹어야겠군.'),
(42384, 6, 1, '하하하! 재밌는 농담이야, 펭귄 씨! 정말 재밌어!'),
(42384, 6, 2, '내가 어쩌다 이렇게 됐지? 난 한때 스톰윈드의 왕이었다고!'),
(42384, 6, 3, '더는 버틸 수 없을 것 같아...'),
(42384, 6, 4, '내 땅에서 꺼져!'),
(42384, 6, 5, '데피아즈에게 털리던 때가 그립군. 적어도 그놈들은 가끔 먹을 것이라도 조금 남겨 줬는데.'),
(42384, 6, 6, '배고파 죽겠어!'),
(42384, 6, 7, '돌도 먹을 수 있으려나? 여기엔 돌이 널렸잖아. 상상해 봐! 그걸 알아내면 세상에서 제일가는 부자가 될 거야!'),
(42384, 7, 0, '횡재했다!'),
(42384, 8, 0, '맛있고 깨끗한 흙을 찾은 것 같아! 오늘 밤은 왕처럼 먹는 거야, 펭귄 씨! 물론 나눠 줄 거지! 넌 내 가장 친한 친구잖아!'),
(42384, 9, 0, '이봐! 거기 너! 내 땅에서 꺼져!'),
(42384, 10, 0, '%s|1이;가; 겁에 질려 달아나려 합니다!'),
(42387, 0, 0, '그... 그 여자를 만났단 말이야?'),
(42387, 1, 0, '그래... 소문이 아니더군.'),
(42387, 2, 0, '펄브라우 일가에 한 일은 고맙다고 전해달라고 했어. 너희 모두와 나눠 가지라며 이 황금더미도 주었지.'),
(42387, 3, 0, '그 여자의 얼굴은 봤어? 설마 진짜로...'),
(42387, 4, 0, '오, 이게 누구신가? 보아하니 누군가 우리 대화를 엿듣고 있었던 것 같군.'),
(42387, 5, 0, '남의 이야기나 엿듣고 다니는 작자를 가르치는 방법은 한 가지밖에 없지.'),
(42387, 6, 0, '죽어라!'),
