(42413, 0, 0, '$g저 남자:저 여자; 주머니를 뒤져!'),
(42413, 0, 1, '$g저 남자:저 여자; 장화 신었어? 벗겨!'),
(42413, 0, 2, '내 거야!'),
(42419, 0, 0, '너무 조용한데. 텔마플러그의 방어 병력은 어디 있지?'),
(42419, 1, 0, '함정이다! 방사능오염기가 작동 중이다!'),
(42419, 2, 0, '10분이라고? 장치를 해제하고도 남을 시간이군.'),
(42419, 3, 0, '힝클스, 거기 청동 회전 장치와 신선한 샘물 좀 가져와라. 코그스핀, 넌 더러운 트로그 옷감과 구리 나사 한 줌을 가져와...'),
(42419, 4, 0, '이런! 여기서 나가야겠다! 랩포지, 우리를 날려보내, 어서!'),
(42423, 0, 0, '안돼! 안돼, 안돼, 안돼! 내 왕국에 들어오게 할 순 없어, 이놈들! 그렇겐 못 해!'),
(42423, 1, 0, '최고 원자력 방어 시스템을 가동해.'),
(42423, 2, 0, '...전부 분해해 버리겠어!'),
(42423, 3, 0, '10분?! 초기 설정 그대로 놔뒀다고? 조종기 이리 내, 이 멍청이!'),
(42452, 0, 0, '방사능오염기 3000 가동. 경보. 비상사태. 10분 안에 최소 안전 거리 밖으로 이동하세요.'),
(42452, 1, 0, '*삑* 경보. 비상사태. 10초 안에 최소 안전 거리 밖으로 이동하세요.'),
(42492, 0, 0, '뭐가 필요한가? 글럽톡 왜 불렀나?'),
(42492, 1, 0, '뭐가 필요한가? 글럽톡 왜 불렀나?'),
(42492, 2, 0, '다른 길?'),
(42492, 3, 0, '뭐가 필요한가? 글럽톡 왜 불렀나?'),
(42492, 4, 0, '글럽톡 부와 권력을 선택하겠다.'),
(42598, 0, 0, '정화를 시작합니다... ...'),
(42638, 0, 0, '알았소. 당신을 돕겠소. 하지만 독사의 소굴에 발을 들이는 것임은 알아 두시오. 내가 지도를 그려 주지... 잠깐, 뒤를 보시오!'),
(42638, 1, 0, '나약한 자만이 어둠 속에서 몰래 공격하는 법이다, 역겨운 놈!'),
(42638, 1, 1, '벌레가 하나 쓰러졌군.'),
(42638, 2, 0, '%s|1이;가; 다시 이야기하자는 듯 손짓합니다.'),
(42638, 3, 0, '%s|1이;가; 고향에 있는 항구를 찢어진 양피지에 자세히 그립니다.'),
(42638, 4, 0, '여기 있소, $n. 황혼의 고원으로 통하는 안전한 길을 모두 표시했소. 우리 적을 완전히 짓밟아 주시오!'),
(42645, 0, 0, '이제 자유다! 정말 자유야!'),
(42645, 0, 1, '꺼내주셔서 감사해요!'),
(42645, 0, 2, '감사합니다. 이제 저 동굴을 날려버려야겠어요!'),
(42645, 0, 3, '잘 씻지도 않는 트로그놈들의 지독한 냄새를 두 번 다시 맡고 싶지 않아요!'),
(42645, 0, 4, '당신을 만나서 제가 얼마나 반가운지 모를 거예요!'),
(42645, 0, 5, '당신이 트로그가 아니어서 정말 기뻐요!'),
(42646, 0, 0, '멍청한 $r 자식이 자기가 내 상급자인 줄 아는군.'),
(42646, 1, 0, '지난 몇 주간 벌인 싸움 중에 제일 대단했소! 이제는 우리 적과 싸우겠소.'),
(42646, 2, 0, '다시는 이러지 않겠습니다!'),
(42646, 2, 1, '시정하겠습니다!'),
(42655, 0, 0, '놀들이 실패했습니다, 주인님.'),
(42655, 1, 0, '하지만 주인님, 제독님이 아직...'),
(42655, 2, 0, '네, 주인님.'),
(42655, 3, 0, '달빛시내 마을에서 말씀이십니까, 주인님?'),
(42671, 0, 0, '검사 준비 완료됐다고!'),
(42671, 0, 1, '이게 내가 만든 녀석이야! 난 이 녀석을 "쌩쌩이"라고 부르지.'),
(42671, 0, 2, '검사 준비 완료됐다고! 살살 다뤄 줘.'),
(42671, 1, 0, '어... 이런. 윽.'),
(42671, 2, 0, '이봐, 저기, 괜찮다고! 아주 작은 문제가 하나 있을 뿐이야. 알지?'),
(42671, 3, 0, '칠만 다시 하면 괜찮을 거야!'),
(42707, 0, 0, '문을 닫아라! 놈을 찾아냈다!'),
(42709, 0, 0, '오, 제발 여기서 이러지 마! 밖에서 싸우라고, 친구!'),
(42744, 0, 0, '내게 한 가지만 알려주게, 바네사.'),
(42744, 1, 0, '펄브라우 일가는 대체 왜 죽인 거지?'),
(42748, 0, 0, '고맙군.'),
(42749, 1, 0, '희망? 판드랄 님이 품었던 희망 같은 것 말인가? 우리에게 불멸의 삶을, 영광을 되찾아 주겠다는 희망?'),
(42750, 0, 0, '예감이 좋지 않습니다, $n 님. 경계를 늦추지 마십시오!'),
(42750, 1, 0, '호프! 대체 무슨...'),
(42750, 2, 0, '$n 님, 스톰윈드로 가십시오. 그리고 국왕 바리안 린 님께 모든 것을 전하십시오. 지금 당장!'),
(42777, 0, 0, '누가 남의 사업에 감 놔라 배 놔라 하는 거야!'),
(42777, 1, 0, '고작 이음못 몇 개 뺐을 뿐이라고. 워낙 많이 박혀 있어서 말이야!'),
(42777, 2, 0, '잔잔한 바다에서 항해하는 데는 아무 문제 없다고.'),
(42777, 3, 0, '이음못을 덜 쓰는 건 환경을 보호하는 길이야!'),
(42777, 4, 0, '... 얼마면 눈감아 줄래?'),
(42777, 5, 0, '알았어, 알았다고. 그만! 그만! 충분히 알아들었어.'),
(42777, 6, 0, '작업 시간 두 배로 늘리고 내 돈 들여서 일정 맞춰 튼튼하게 만들어 줄게. 믿어 달라고!'),
(42839, 0, 0, '아니! 어떻게 경비로봇을 통과해 여기까지 온 거지?'),
(42839, 1, 0, '상관없어! 내 부하들과 함께 순식간에 처리해 주마. 공격해라, 제군들!'),
(42839, 2, 0, '놈리건의 진정한 자손이 네놈들에게 질 것 같으냐!'),
(42849, 0, 0, '기계박사 텔마플러그는 패배가 다가오고 있음을 절대로 인정하지 않는다. 놈은 라즐로 크러쉬코그를 보내, 우리가 사랑하는 놈리건의 재건을 방해하고 있다!'),
(42849, 1, 0, '하지만 여기 있는 용감한 친구가 놈을 번번이 좌절시켰고, 이제 아이언포지의 드워프 동료들도 우리와 함께한다!'),
(42849, 2, 0, '놈을 혼내 주자. 엉엉 울면서 주인에게 돌아가게 만들자!'),
(42849, 3, 0, '우리가 해냈다! 마침내 놈을 쓰러뜨렸어! 으하하하하!'),
(42849, 4, 0, '크러쉬코그의 패배를 보며 텔마플러그 놈이 기계보행전차 안에서 벌벌 떨겠군! 마땅히 그래야지! 다음은 네놈이다, 텔마플러그! 기다려라!'),
(42849, 5, 0, '멕카토크 미사일!'),
(42849, 6, 0, '멕카토크 광선!'),
(42849, 7, 0, '멕카토크 빔!'),
(42849, 8, 0, '멕카토크 포!'),
(42852, 0, 0, '알았습니다. 이 오염된 노움들을 혼쭐 내주겠습니다!'),
(42852, 1, 0, '이것이 네놈에게 놈리건과 아이언포지의 위대함에 함부로 덤빈 대가다!'),
(42937, 0, 0, '오크가 $r 죽인다!'),
(42937, 0, 1, '검은바위 부족이 이 숲을 점령할 거다!'),
(42937, 0, 2, '포도가 아주 맛있더군!'),
(42937, 0, 3, '살려달라고 빌어라!'),
(42937, 0, 4, '널 없애버리겠다!'),
(43003, 0, 0, '검이 모쉬오그 노획물 안으로 들어갔습니다. 억지로라도 여십시오!'),
(43197, 0, 0, '바위 하나도 안 무거워! 인간들 약해빠졌어!'),
(43197, 1, 0, '어디 던져? 다리에 던져?'),
(43197, 2, 0, '알았어! 물속에 던질게!'),
(43245, 0, 0, '사술사 진도가 아닌가! 그 가면은 정말 오랜만이군.'),
(43245, 1, 0, '어떤 일로 내가 관리하는 지역에 온 건가? 난 위대한 줄구룹의 방문객을 맞는 데는 익숙치 않다고.'),
(43245, 2, 0, '그것 참 안됐군... 하지만 늙은 추방자인 나, 잔질의 걱정거리는 아니야.'),
(43245, 3, 0, '친구라고? 네놈도 내게 돌을 던지던 자들 중 하나가 아니었나, 진도. 하지만 옛날 이야기는 옛날 이야기로 남겨두지.'),
(43245, 4, 0, '그래, 박쥐와 뱀에게 나, 잔질 님의 도움이 필요하다 이거지? 알겠다. 줄구룹 안에서 보지... 오랜 친구여.'),
(43246, 0, 0, '내가 왜 여기 왔는지는 잘 알 텐데, 잔질.'),
(43246, 1, 0, '구루바시 부족의 존폐가 위태로운 상황이다. 내가 부활했고 만도키르도 부활했지만... 다른 이들은 모두 사라졌지.'),
(43246, 2, 0, '그렇단 말이지, 잔질. 그렇다면 걱정하게 만들어 줘야 겠군. 내가 대여사제 제클릭과 대사제 베녹시스의 몸을 복구했다.'),
(43246, 3, 0, '나는 네 비약으로 무슨 일을 할 수 있는지 알고 있지. 옛 친구들을 도와주지 않겠나?'),
(43296, 0, 0, '%s|1이;가; 크게 콧소리를 냅니다.'),
(43296, 1, 0, '%s|1이;가; 적을 학살할 준비를 합니다!'),
(43296, 2, 0, '|C00ff0000키마이론의 대학살에 담즙로봇이 정지했습니다|r!'),
(43296, 3, 0, '|c0000FF00담즙로봇이 다시 가동됩니다|r!'),
(43324, 1, 0, '(주인님을 위한 피를!)'),
(43324, 1, 1, '그것이 너희의 운명이다.'),
(43324, 1, 2, '한심한 살덩이들!'),
(43324, 1, 3, '(처치해! 모두 처치해버려!)'),
(43324, 1, 4, '최후를 받아들여라.'),
(43324, 1, 5, '(몸과 마음. 전부 부숴버려!)'),
(43324, 1, 6, '이제 놈들은 주인님 것이다.'),
(43324, 1, 7, '(혼돈. 광란! 머리가 터질 것 같지!)'),
(43324, 2, 0, '나에게 힘을 다오!'),
(43324, 2, 1, '망치의 힘을 느껴 보아라!'),
(43324, 2, 2, '(멈춰. 망치의 시간이다!)'),
(43324, 3, 0, '그만! (그분의 의지에 모두 굴복한다. 그분의 왕국에서 혼돈이 찾아온다.) 그래, 그 말대로다.'),
(43324, 4, 0, '(무한한 고통!)'),
(43324, 4, 1, '(캬하하하하하!)'),
(43324, 4, 2, '보아라! 너희의 나약한 세상의 운명을 보라!'),
(43324, 4, 3, '(더. 더!)'),
(43324, 4, 4, '(어서 와, 형제들! 희망을 집어삼켜!)'),
(43324, 4, 5, '(더. 더 많이 보내.)'),
(43324, 5, 0, '모두 최후에는 굴복한다.'),
(43324, 6, 0, '형제여, 이럴 순 없어... (운명의 시간이 왔다!) 나의 힘... (자존심하곤! 피범벅인데도 떠드네! 들어봐!) 나의 정신... (우린 그분의 영광을 위해 산다!) 무슨 일이... 일어나는 거냐... (새벽은 가고 황혼의 그림자가 다가온다. 광란이여 오라, 파괴여 오라, 영원한 밤이여 오라!)'),
(43324, 7, 0, '(운명의 갈고리가 불신자들을 붙잡는다!)'),
(43324, 7, 1, '(주인님이 본다, 주인님이 본다!)'),
(43324, 7, 2, '(주인님의 눈은 과거와 미래를 봐! 전부 다 본다고!)'),
(43324, 7, 3, '(이제 어둠이 보이나 봐! 눈이 커지고 있네!)'),
(43324, 8, 0, '우리가 대체 무슨 짓을 저지른 거지? (아직 안 돼!)'),
(43324, 9, 0, '더는... 견딜 수가 없다... (형제여, 이제 막 시작했잖아!)'),
(43324, 10, 0, '형제여... 우린 패배했다. (하지만 주인님이... 아직 말씀을... 화나셨어... 주인님...?)'),
(43324, 11, 0, '형제여, 우린 실패했다. 놈들을 그녀의 손에 맡기자... (주인님은 놈들이 그녀 곁에 가는 거 싫어하셔... 형제여...? 주인님이 화나셨어...)'),
(43324, 12, 0, '모두 끝났다. (모두의 운명.)'),
(43376, 0, 0, '날 어떻게 찾았지!?'),
(43377, 0, 0, '전 한 푼도 없습니다! 저리 가십시오!'),
(43391, 0, 0, '감옥에 있으면서 중요한 걸 하나 배웠어. 아, 밥에서 콩 골라내는 법은 빼고 말이야. 바로 생존이지롱!!!'),
(43391, 1, 0, '따라올 테면 따라와 봐!'),
(43391, 2, 0, '아하! 때려주기 딱 좋은 자리에 섰군!'),
(43396, 0, 0, '아, 말로리악. 네가 실험실이라 부르는 그 감옥 같은 곳에서 마침내 나와 줘서 기쁘군. 이번엔 뭘 가져왔나?'),
(43396, 1, 0, '듣기 좋은 소리로군. 말해 봐라.'),
(43396, 2, 0, '보아하니 이 실험은 완전히 실패한 것 같군. 저놈은 눈이 멀어 버린 것 같다! 놈을 봐라!'),
(43396, 3, 0, '보란 말이다!'),
(43396, 4, 0, '아니, 잠깐.'),
(43396, 5, 0, '네가 화풀이 상대로 삼으려는 그 녀석이... 쓸모 있을지도 모르겠다.'),
(43396, 6, 0, '물러가 봐라, 한심한 놈. 다음엔 어떤 비참한 결과를 보여줄지 기대하마.'),
(43404, 0, 0, '심려를 끼쳐 드려 참으로 죄송합니다, 주군이시여. 하지만 이번엔 대단히 흥미를 보이실 만한 결과가 있습니다!'),
(43404, 1, 0, '물론입죠!'),
(43404, 2, 0, '다양한 용족의 피에서 갖가지 요소를 추출해 연고를 하나 만들어냈습니다. 이 연고를 바르면 아주 특별한 시각을 지니게 됩니다!'),
(43404, 3, 0, '바로 필멸의 세상 너머를 볼 수 있지요!'),
(43404, 4, 0, '아트라메데스! 네 주인님께 가거라.'),
(43404, 5, 0, '보십시오! 실험 번호 25463-D의 결과물입니다!'),
(43404, 6, 0, '어떻게 이런 일이?! 당장 녀석을 처리하겠습니다!'),
(43404, 7, 0, '예, 주인님.'),
(43505, 0, 0, '%s|1이;가; 긴 안도의 한숨을 쉽니다.'),
(43612, 0, 0, '이단자여, 썩 꺼져라! 여긴 너희가 올 곳이 아니다!'),
(43612, 1, 0, '내 앞에 무릎 꿇고 참회해라!'),
(43612, 2, 0, '죽음은... 그저 시작에 불과해!'),
(43612, 3, 0, '이제 안식이 함께하기를.'),
(43612, 3, 1, '하늘이 널 데려가리라!'),
(43614, 0, 0, '%s|1이;가; 격노합니다!'),
(43636, 0, 0, '너나 검을 뽑아라, 이 비열한 악당 자식아!'),
(43636, 0, 1, '난 절대 붉은해적단을 배신하지 않을 거다. 이 풋내기 놈아!'),
(43636, 0, 2, '이 퍼런 멀록같은 놈! 난 절대 배신하지 않을 거다!'),
(43636, 0, 3, '네 눈알을 뽑아버리겠다! 이 겁쟁이 뱀장어 같은 놈아!'),
(43636, 0, 4, '내가 손 좀 봐주지, 이 포탄 폭탄 맞은 얼굴아!'),
(43636, 0, 5, '널 넵튤론의 사물함에 던져버리겠다. 이 썩은 불가사리 같은 놈아!'),
(43636, 0, 6, '물고기 밥으로 만들어주마, 이 역겨운 트로그같은 놈아!'),
(43636, 0, 7, '반란이라고? 내가 진짜 반란이 뭔지 보여주지, 이 술 먹은 꼬막 같은 놈아!'),
(43659, 0, 0, '네, 그렇습니다! 우린 길니아스에서 너무 오랜 시간을 기다렸습니다. 이제 검에 피를 묻힐 준비가 되었습니다!'),
(43660, 0, 0, '우린 한 때 바다를 주름잡았습니다... 그 망할 그레이메인이 길니아스의 항구를 닫게 하기 전까지만 해도 말이죠! 그놈만 아니었다면, 우린 늑대인간이 되지 않았을 텐데...'),
(43686, 0, 0, '이 오만함의 대가는 목숨으로 치러라!'),
(43686, 1, 0, '흥! 내 불꽃의 연료가 되었군.'),
(43686, 2, 0, '타올라라!'),
(43686, 3, 0, '원소의 분노를 느껴 봐라!'),
(43686, 4, 0, '네놈들의 종말을 맞이해라!'),
(43687, 0, 0, '감히 정령 군주의 성소를 침범해?'),
(43687, 1, 0, '사라져라!'),
(43687, 2, 0, '그 몸속에 흐르는 피를 꽁꽁 얼려 주마!'),
(43687, 3, 0, '이제, 진정한 힘을 보여주지...'),
(43687, 4, 0, '네놈들의 종말을 맞이해라!'),
(43688, 0, 0, '이 바보 같은 놀음을 끝내 주지!'),
(43688, 1, 0, '바람 속의 속삭임처럼 약하군...'),
(43688, 2, 0, '바람이여, 내 부름에 응하라!'),
(43688, 3, 0, '꽤나 인상적이었다만...'),
(43688, 4, 0, '네놈들의 종말을 맞이해라!'),
(43689, 0, 0, '우리가 상대하겠다!'),
(43689, 1, 0, '대지가 너의 뼈를 반기는구나!'),
(43689, 2, 0, '땅이 너를 집어삼키리라!'),
(43689, 3, 0, '그것도 여기서 끝이다.'),
(43689, 4, 0, '네놈들의 종말을 맞이해라!'),
(43704, 0, 0, '%s|1이;가; 분노합니다!'),
(43735, 0, 0, '네놈들의 종말을 맞이해라!'),
(43735, 1, 0, '전멸해라...'),
(43735, 1, 1, '몰살해라...'),
(43735, 2, 0, '이럴 수가...'),
(43735, 3, 0, '힘이 무엇인지 느껴라!'),
(43778, 0, 0, '전투 절단기 5000 작동 개시. 모든 시스템, 겨우 작동.'),
(43778, 1, 0, '임계 온도 돌파. 시스템 오류. 2번 포트에 통밀 막힘 현상. 작동 종료.'),
(43778, 2, 0, '목표물 파괴.'),
(43778, 3, 0, '목표물 포착...'),
(43778, 4, 0, '목표물 포착 완료. 수확 서보 가동.'),
(43778, 5, 0, '증속 엔진 활성화.'),
(43778, 6, 0, '안전 제한 작동 정지. 대재앙 시스템 오류 임박.'),
(43845, 1, 0, '아니란다, 작은 아이야. 그런 게 전혀 아니야. 나는 오랫동안 잠들어 있었지만, 그동안 내 영혼은 에메랄드의 꿈 속에서 헤맸지. 그러면서 내 몸은 우리가 동물로 변신한 형태를 닮아 가기 시작했단다.'),
(43858, 0, 0, '시작하지...'),
(43858, 1, 0, '성공이야. 단단히 붙잡게, 지터스.'),
(43858, 2, 0, '젠장, 지터스! 단단히 잡으라고!'),
(43858, 3, 0, '아니... 이제 그를 놓아줘야 자네가 짐승이 아닌 존재라는 사실을 증명할 수 있네, 내 친구여.'),
(43859, 0, 0, '저... 저는 못해요...'),
(43875, 0, 0, '감히 신성한 영역에 발을 디디다니! 구름 사이에 필멸자의 자리는 없다!'),
(43875, 1, 0, '하, 네가 속한 대지로 돌아가라!'),
(43875, 2, 0, '알아키르여! 당신의 종이 도움을 청합니다!'),
(43875, 3, 0, '바람이 날 데려가리라!'),
(43878, 0, 0, '구역질 나는 짐승들! 하늘담에 네놈들이 있는 걸 참을 수가 없구나!'),
(43878, 1, 0, '끝났다!'),
(43919, 0, 0, '야호.'),
(43921, 0, 0, '난 자유다! 이 자유의 달콤함이여!'),
(43950, 0, 0, '지터스...'),
(43950, 1, 0, '지터스!'),
(43950, 2, 0, '네가 그늘숲에 늑대인간을 불러들였어! 네가 암흑 기수들을 내 농장에 데려왔고, 내 가족이 살해되는 동안 숨어만 있었다고!'),
(43950, 3, 0, '내 인생이 이 꼴이 된 것도 모두 빌어먹을 네놈의 잘못이야! 죽여버리겠어!'),
(43950, 4, 0, '지터스, 네가 갚아줘야 할 빚이 아주 많아. 이렇게 쉽게 끝장을 내 주지는 않겠어.'),
(44086, 0, 0, '어떻게 이럴 수 있습니까!'),
(44086, 0, 1, '아이들이 폭풍협곡에 혼자 있습니다! 아이들에게 가 봐야 한단 말입니다!'),
(44086, 0, 2, '무슨 일이 일어난 겁니까? 지붕 위에서 뭔가를 본 것 같은데 말이죠.'),
(44086, 0, 3, '어서 이곳을 벗어나야만 합니다! 울부짖는 소리가 매일 밤 더 커지고 있단 말입니다.'),
(44086, 0, 4, '경비병들이 길니아스 시는 안전하다고 말했었는데...'),
(44323, 0, 0, '죽을 준비나 해라, $r!'),
(44323, 1, 0, '네놈의 목숨을 끊어주겠다.'),
(44323, 2, 0, '이젠 진절머리가 나는군. 저주받은 자들의 교단은 안돌할이 필요치 않다. 이 쓸모없는 도시는 너희 마음대로 해라.'),
(44414, 0, 0, '헬스크림 님께서 관여하셨다고 했나, 자네?'),
(44414, 1, 0, '뭐 그렇다면 이제 한 가지 일만 남았군...'),
(44414, 2, 0, '이 모든 일이 내 생각보다 훨씬 빨리 일어났군.'),
(44414, 3, 0, '자네가 두렵네, $n. 능력이 필요 이상으로 향상되었으니 말이야...'),
(44418, 0, 0, '담즙로봇이 움직이기 시작하더니 고약한 냄새가 나는 물질을 방출합니다.'),
(44453, 0, 0, '간들링은 강력합니다. 하지만 걱정하지 마십시오. 당신이 그자와 싸우기 시작하면 바로 제가 합류하겠습니다.'),
(44453, 1, 0, '얼라이언스를 위하여!'),
(44577, 0, 0, '시아마트를 풀어줘선 안 돼! 더 늦기 전에... 부디 돌아가라!'),
(44577, 1, 0, '침입자들아, 여기서 더는 못 갈 줄 알아라!'),
(44577, 2, 0, '|TInterface\\Icons\\spell_nature_earthquake.blp:20|t%s|1이;가; |cFFFF0000|Hspell:83445|h[충격파]|h|r를 시전합니다!'),
(44577, 3, 0, '무르카쉬!'),
(44577, 4, 0, '버릇없는 쥐새끼 같으니!'),
(44577, 5, 0, '살살 밟아라.'),
(44600, 0, 0, '초갈 님께 네놈들의 머리를 바치겠다! 하나도 남김없이!'),
(44600, 1, 0, '고룡들이 오늘 배불리 먹겠군!'),
(44600, 2, 0, '지옥의 고통이 너를 기다린다!'),
(44768, 0, 0, '고맙습니다... 제련장인 찾는 걸 도와드리고 싶은 마음입니다.'),
(44768, 0, 1, '제련장인은 끔찍한 살인마입니다. 정말 제련장인을 찾아나설 생각인가요?'),
(44768, 0, 2, '아, 맞아요... 제련장인에 대해 좀 알아요! 막 이야기를 엿들었는데, 지금 이 야영지에 없다고 했어요.'),
(44768, 0, 3, '제련장인과 황혼의 망치단 수뇌부 간의 회합이 있을 겁니다. 믿어 주세요. 썩은 빵조각을 주고 얻은 정보라고요!'),
(44768, 0, 4, '전 제련장인에 대해 아는 게 없어요. 이제 당신이 왔다는 그 안전한 곳이 어딘지 말해 주세요.'),
(44768, 0, 5, '제련장인이 회합에 대한 정보를 적어 놓은 책이 야영지가 한눈에 보이는 탑 안에 있다는 얘기를 들었습니다.'),
(44819, 0, 0, '남국의 바람이여, 불어라! 와서 네 주인을 도와라!'),
(44819, 1, 0, '휘몰아치는 폭풍 앞에 몸서리쳐라!'),
(44819, 1, 1, '폭풍을 맞이해라!'),
(44819, 2, 0, '바람 속의 모래 알갱이 같은 놈.'),
(44819, 3, 0, '하늘이... 나를 부르는구나...'),
(44819, 4, 0, '내가... 드디어... 풀려났다!'),
(44866, 0, 0, '도와줄 수는 있는데, 아무에게도 이 일을 말하지 않겠다고 약속해. 비슷한 이야기만 해도 내 명성에 금이 간단 말이야!'),
(44904, 0, 0, '변신술! 달빛 섬광 발사!'),
(44904, 0, 1, '변신술! 달빛 섬광 준비!'),
(44904, 0, 2, '변신술! 공격 개시!'),
(44904, 1, 0, '변신술! 공격 준비 완료!'),
(44904, 1, 1, '변신술! 표범으로 변신해야지!'),
(44904, 1, 2, '변신술! 내 발톱 맛이나 봐라!'),
(44904, 2, 0, '변신술! 피해 흡수!'),
(44904, 2, 1, '변신술! 곰으로 변신해야지!'),
(44904, 2, 2, '변신술! 여기 있지롱!'),
(44904, 3, 0, '변신술! 아, 이런... 잠깐만 기다려주십시오...'),
(44904, 3, 1, '변신술! 아, 이런! 또...'),
(44904, 3, 2, '변신술!! 이제 헤엄쳐야지!'),
(44904, 4, 0, '제가 맡겠습니다!'),
(44904, 4, 1, '내가 때리는 거 맞나?'),
(44904, 5, 0, '덤벼, 겁쟁아!'),
(44904, 5, 1, '아니, 나를 때리라고! 여기야, 여기!'),
(44904, 6, 0, '저 좀 뒤집어주시겠습니까?'),
(44904, 6, 1, '다들 왜 거꾸로 서 있는 거지요?'),
(44904, 7, 0, '정말 죄송합니다.'),
(44904, 7, 1, '이게 아닌데...'),
(44904, 8, 0, '좋습니다, 시작하죠!'),
(44904, 8, 1, '준비 다 됐습니다!'),
(45162, 0, 0, '좋습니다. 한번 싸워보시겠습니까?'),
(45162, 0, 1, '이제는 십자군의 시대입니다!'),
(45162, 0, 2, '좋습니다... 후회하지 마십시오!'),
(45162, 0, 3, '준비하십시오! 갑니다!'),
(45162, 1, 0, '많이 배웠습니다.'),
(45162, 1, 1, '제가 수련이 더 필요한 것 같습니다.'),
(45162, 1, 2, '어머니 말씀이 맞았습니다... 이제 절대로 은빛십자군 같은 건 꿈도 꾸지 않을 겁니다.'),
(45162, 1, 3, '이번에는 당신이 이겼군요.'),
(45196, 0, 0, '에에에에이일 맥주우우우우!!! 아아아아아악!'),
(45196, 0, 1, '어이쿠! 군침 도는 술이다!'),
(45196, 0, 2, '에일 맥주에 대하여 경례!'),
(45196, 0, 3, '힘이 돌아왔다!'),
(45196, 0, 4, '나 땅콩 먹고 싶어!'),
(45238, 0, 0, '갑시다, $n. 날 바짝 따라오시오.'),
(45238, 1, 0, '조심하시오. 여기선 뭘 만나게 될지 아무도 모르니까...'),
(45238, 2, 0, '발밑을 조심하시오!'),
(45278, 0, 0, '만세.'),
(45278, 1, 0, '치유 물약을 마시겠습니다! 당분간은 다른 물약을 마실 수 없을 거예요!'),
(45278, 2, 0, '다시 만날 때까지...'),
(45278, 3, 0, '이 생명체는 고대 그림토템으로부터 힘을 얻고 있습니다! 이 괴물들을 쓰러뜨리려면 놈들부터 없어야 합니다!\n'),
(45410, 0, 0, '대모가 선택한 자로군! 아직 눈치채지 못했나 보지? 먼저 너를 없애고 나서 네 친구도 없애주겠다!'),
(45410, 1, 0, '불의 땅에서 온 정령이시여, 나를 당신의 분노로 채우소서!'),
(45410, 2, 0, '하늘담의 정령이시여... 제 부름에 응하소서!'),
(45410, 3, 0, '심원의 영지에서 온 정령이여, 당신의 힘을 주소서!'),
(45410, 4, 0, '마가타 님, 어째서 이방인을... 선택하셨습니까?'),
(45418, 0, 0, '이쪽으로 올 줄 알고 있었지. 주위에서 너와 아리카라와의 연관성에 대해 말하는 건 아무래도 상관없다. 모두 여기서 끝날 지어다!'),
(45418, 1, 0, '결국 이렇게 끝나는 건가? 이곳 먹구름 봉우리에서?'),
(45447, 0, 0, '선물 고맙군. 자신의 가치를 증명해보게, $c!'),
(45447, 1, 0, '멈춰! 내 천둥매를 죽일 셈인가!'),
(45447, 2, 0, '난 지금껏 황혼의 망치단의 포로로 잡혀 있었네.'),
(45447, 3, 0, '어디인지는 확실하지 않네. 마루둥지를 내려다보는 서편 기슭부터 수색을 시작하게.'),
(45715, 0, 0, '당신은 제 생명의 은인입니다. 우리 동족은 데스윙에게 반역한 탓에 혹독한 대가를 치렀습니다.'),
(45715, 0, 1, '당신처럼 친절한 분은 이야기 속에만 존재하는 줄 알았습니다, $r님. 당신 같은 분이 제 생명을 구해주실 줄은 꿈에도 몰랐습니다.'),
(45715, 0, 2, '고... *콜록* 고맙습니다, 이방인이여.'),
(45741, 0, 0, '난 이제 가보겠네. 여기 머물 이유가 없어. 비록 언데드이지만, 내 의지는 나의 것이지.'),
(45741, 1, 0, '다음 세상엔 푸른 초원에서 만나세, $n.'),
(45870, 0, 0, '침입자를 몰아내고 주군의 사랑을 얻는 이는 내가 되겠군. 가장 약한 바람이라도 저놈들을 상대하기엔 충분할 터!'),
(45870, 1, 0, '외부인은 입장할 수 없다, 사라져라!'),
(45870, 1, 1, '더는 우리 고향을 더럽힐 수 없으리라!'),
(45870, 2, 0, '내 힘이 모자라는구나, 형제들이여. 수치스럽지만 당분간 너희에게 기대야겠다.'),
(45870, 3, 0, '바람보다 빠를 줄 알았더냐? 크나큰 착각이로군.'),
(45870, 4, 0, '바람의 힘이 풀려난다!'),
(45870, 5, 0, '%s|1이;가; 남아 있는 바람의 군주에게서 힘을 모으기 시작합니다!'),
(45870, 6, 0, '%s|1이;가; 남아 있는 바람의 군주에게서 힘을 모으기 시작합니다!'),
(45870, 7, 0, '바람의 비밀의회의 힘이 극에 달합니다!'),
(45871, 0, 0, '형제들이여, 침입자를 처치하는 명예는 내 몫이다! 놈들의 허약한 몸뚱이는 내 차디찬 바람 속에서 딱딱하게 얼어붙을 것이다!'),
(45871, 1, 0, '잘 얼어붙었군.'),
(45871, 1, 1, '또 필멸자 하나가 마지막 숨을 쉬었군.'),
(45871, 2, 0, '형제들이여, 조심해라! 이 필멸자들은 위험하다. 나는 잠시 쉬며 힘을 모아야겠다.'),
(45871, 3, 0, '명예를 버리고 겁쟁이처럼 도망가는 것이냐? 그럼 죽어라!'),
(45871, 4, 0, '바람의 힘이 풀려난다!'),
(45871, 5, 0, '%s|1이;가; 남아 있는 바람의 군주에게서 힘을 모으기 시작합니다!'),
(45871, 6, 0, '%s|1이;가; 남아 있는 바람의 군주에게서 힘을 모으기 시작합니다!'),
(45872, 0, 0, '나는 가장 강한 바람이니, 침입자들을 조각내는 것도 바로 나이리라!'),
(45872, 1, 0, '먼지 같은 놈...'),
(45872, 1, 1, '바람에 휩쓸렸군!'),
(45872, 2, 0, '침입자들이 너무나도 완강하다, 형제들이여. 나는 저들을 쓰러뜨릴 수 없다. 잠시만 한숨 돌리며 바람을 키우게 해다오.'),
(45872, 3, 0, '어째서 도망가느냐, 필멸자여? 여기엔 도망갈 곳도, 숨을 곳도 없다!'),
(45872, 4, 0, '바람의 힘이 풀려난다!'),
(45872, 5, 0, '%s|1이;가; 남아 있는 바람의 군주에게서 힘을 모으기 시작합니다!'),
(45872, 6, 0, '%s|1이;가; 남아 있는 바람의 군주에게서 힘을 모으기 시작합니다!'),
(45878, 0, 0, '로르나, 옛 친구가 반갑지 않아?'),
(45878, 1, 0, '내 왕국이라고? 그따위 것은 이제 존재하지 않아.'),
(45878, 2, 0, '네 아버지와 그레이메인이 모두 망쳐놓았지. 아니, 살인 괴물들이 자유롭게 풀려났을 때 길니아스는 사라지고 말았어. 영원히.'),
(45878, 3, 0, '이제 무기를 내려놓고 항복해라. 널 죽이러 온 건 아니니까. 아직은.'),
(45910, 0, 0, '안전한가요?'),
(45910, 0, 1, '모두... 죽은 건가요?'),
(45910, 0, 2, '놈들이 어둠 속에 숨어 있다가 갑자기 나타났습니다. 우린 손도 쓸 수 없었고요.'),
(45910, 0, 3, '이제 끝장이라고 생각했습니다!'),
(45910, 0, 4, '사람들이 말하는 영웅이 바로 당신이로군요. 감사합니다.'),
(45992, 0, 0, '주인님 말씀 못 들었나, 테랄리온! 저놈들을 없애!'),
(45992, 1, 0, '테랄리온, 이 쓸모없는 놈. 으아아아아!'),
(45992, 2, 0, '마지막 숨을 쉬어라!'),
(45992, 3, 0, '그나마... 테랄리온 녀석도 죽어서 다행이야...'),
(45992, 4, 0, '테랄리온, 내가 전당에 불을 뿜겠다. 놈들의 퇴로를 막아라!'),
(45992, 5, 0, '황혼을 맞이해라!'),
(45993, 0, 0, '너한테 말씀하신 거다, 발리오나. 나는 바쁜 몸이라 누굴 공격할 시간이 없다.'),
(45993, 1, 0, '지금 쓸모없는 놈이라 했나? 어머니가 왜 날 제일 좋아하시는지 보여주지!'),
(45993, 2, 0, '필멸자여, 네 영혼이 드러났구나!'),
(45993, 3, 0, '으아아... 역시 끼어들지 말았어야 했어...'),
(45993, 4, 0, '나한테 명령인가, 발리오나? 난 내 맘대로 불을 뿜겠다!'),
(45993, 4, 1, '분노한 황혼의 용군단으로부터 도망갈 수 있겠나?'),
(45993, 5, 0, '고통 속에 몸부림쳐라!'),
(46041, 0, 0, '도둑이여, 네 범죄의 죗값을 치르게 될 것이다!'),
(46042, 0, 0, '도둑이여, 네 범죄의 죗값을 치르게 될 것이다!'),
(46174, 0, 0, '바로 그런 자세야!'),
(46174, 1, 0, '겨우 이 정도냐?!'),
(46174, 2, 0, '케이든의 도끼가 네놈들 목을 기다리고 있다!'),
(46174, 3, 0, '다 덤벼!'),
(46185, 0, 0, '정화 작업을 시작합니다...'),
(46185, 1, 0, '정화 작업 완료. 운반 대기 중입니다.'),
(46185, 2, 0, '경고, 시스템이 과열되었습니다. 곧 작동을 정지합니다!'),
(46191, 0, 0, '야! 그런데 왜 네가 앞에 앉아서 가는 거야?'),
(46191, 1, 0, '하! 네가 이겼다고 누가 그러는데? 아직 점수는 비교해 보지도 않았잖아.'),
(46191, 2, 0, '분명히 여섯 마리였을 거야.'),
(46191, 3, 0, '어... 어떻게 알았어?'),
(46191, 4, 0, '그러지 마, 타레나.'),
(46191, 5, 0, '너도 알고 있으면서 괜히 물어보지 마.'),
(46191, 6, 0, '<한숨>... "성스러운 성기사들"이었어.'),
(46191, 7, 0, '이제는 별로 그러고 싶지 않아. 여기 뒤쪽에서 새 친구와 함께 앉는 게 더 좋거든. 앞쪽에선 말 냄새가 나.'),
(46191, 8, 0, '마지막으로 쉬고 나서 몇 분 지나지도 않았잖아! 그냥 희망의 빛 예배당으로 바로 가자!'),
(46191, 9, 0, '그럴 일은 없어. 한 번 보라고! 처음 출발했을 때랑 똑같이 씩씩한데 뭘!'),
(46191, 10, 0, '이건 불공평해!!'),
(46191, 11, 0, '왜 내가 이렇게 지저분한 꼭대기에 앉아야 하는 건데?!'),
(46191, 12, 0, '야! 여기 가방을 네 머리 위로 떨어뜨릴 수도 있어, 타레나.'),
(46191, 13, 0, '야! 조용히 해, 이 바보야. 보아하니 네가 피오나한테 뽀뽀하고 싶은 모양이구나.'),
(46191, 14, 0, '실례가 되지 않는다면 알려주세요. 무슨 일을 하시기에 그렇게 많이 걸어 다니시죠?'),
(46191, 15, 0, '그러면 아르거스 님도 은빛십자군의 일원이신가요?'),
(46191, 16, 0, '저희를 좀 추천해 주실 수 없으세요? 저희도 십자군에 들어가려 하고 있거든요.'),
(46191, 17, 0, '안돼애애애애! 또 쉬어 간다니!'),
(46191, 18, 0, '걸어간다고요...?'),
(46193, 0, 0, '내 자리!'),
(46193, 1, 0, '내가 내기에서 이겼으니까. 그리고 내가 "내 자리"라고 먼저 말했으니까.'),
(46193, 2, 0, '좋아. 난 좀비 다섯 마리 처치했어. 아주 커다란 놈들이었고. 넌 언데드 몇 마리나 잡았는데?'),
(46193, 3, 0, '네가 네 마리밖에 못 잡았다는 데 내 전 재산을 걸겠어.'),
(46193, 4, 0, '몰랐지. 하지만 네 덕분에 이제 알았어!'),
(46193, 5, 0, '그런데 정말 언데드 사냥 어떻게 됐어? 얘기 좀 해봐.'),
(46193, 6, 0, '기드윈? 내 말 무시하냐?'),
(46193, 7, 0, '기드윈... 너 화났구나. 그렇지?'),
(46193, 8, 0, '우리 어렸을 때 기억나? 왜 하루 온종일 트롤, 멀록, 그리고 여자아이들하고 싸우는 흉내 내면서 놀았었잖아.'),
(46193, 9, 0, '우리가 붙인 이름이 있었는데... 뭐였지?'),
(46193, 10, 0, '아냐, 정말 진지하게 물어보는 거야. 완전히 잊어버렸다고.'),
(46193, 11, 0, '저기... 나는 피오나 말이 맞는 것 같아.'),
(46193, 12, 0, '조금 더 기다린다고 해서 은빛십자군에 무슨 일이라도 있겠어? 그리고... 우리 손님도 마차에서 내리셔야 할 일이 있을지 모르잖아.'),
(46193, 13, 0, '네가 키가 작아서 그런 거라고.'),
(46193, 14, 0, '피오나, 조심하는 게 좋아. 기드윈은 너한테 뽀뽀하고 싶어서 앞자리에 앉으려는 거니까.'),
(46193, 15, 0, '아니거든!'),
(46193, 16, 0, '고귀한 일이군요.'),
(46193, 17, 0, '이야... 그 분과 서로 이름을 부를 만큼 친한 사이신가요?'),
(46194, 0, 0, '어험! 아, 태워줘서 고맙소, 피오나 양. 이렇게 한 번쯤 편하게 여행하는 것도 좋구려.'),
(46194, 1, 0, '그렇소. 내가 젊었을 때는 이 길도 지나다니기 쉬웠었지. 요즘은 더 조심해야 한다오.'),
(46194, 2, 0, '난 은빛십자군의 탑 다섯 곳을 관리한다오. 대부분은 수리하고 정비하는 일이고, 마법도 약간 사용하지.'),
(46194, 3, 0, '적절히 보살펴 주지 않으면, 역병지대의 건물들은... 무너져 내리거든.'),
(46194, 4, 0, '만족스러운 일이라오. 내 손으로 직접 일하는 게 난 언제나 즐겁더군.'),
(46194, 5, 0, '말이 나왔으니 말인데, 수리할 물건이 있으면 내게 말해주시오. 도와줄 수 있으니까.'),
(46194, 6, 0, '물론이지. 나는 이제 희망의 빛 예배당에는 자주 들르지 않지만, 여러분이 거기 도착하거든 맥스 티로서스한테 내가 보냈다고 얘기하시오.'),
(46194, 7, 0, '아가씨, 날 저 앞에 있는 빛의 방패 경비탑에 내려줄 수 있겠소? 거기 잠깐 들러야 할 일이 있소.'),
(46194, 8, 0, '희망의 빛 예배당은 이제 얼마 남지 않았소, 젊은 성기사. 한번 걸어가 보는 건 어떻겠소?'),
(46230, 0, 0, '으으! 또 이곳이야, 또! 다음 구조대에서는 새로운 장소를 배정해달라고 해야지...'),
(46230, 1, 0, '안 돼, 위생로봇이... 내 자랑거리였는데!'),
(46250, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(46252, 0, 0, '%s|1이;가; 겁을 먹고 도망치려고 합니다!'),
(46254, 0, 0, '숲에선 잠깐 실수했을 뿐이다!'),
(46254, 1, 0, '들창코가 분노합니다!'),
(46254, 2, 0, '으에엑!'),
(46261, 0, 0, '%s|1이;가; 격노합니다!'),
(46264, 0, 0, '모두 불타 버려라!'),
(46264, 1, 0, '모두 불타 버려라!'),
(46268, 0, 0, '놈들이 저를 먹게 놓아두지 마세요!'),
(46268, 0, 1, '도와주세요! 혼자 힘으로 빠져나가기에는 제가 너무 약해요!'),
(46268, 0, 2, '여기서 죽고 싶지는 않아요!'),
(46268, 0, 3, '저는 정말 이곳에서 죽고 말 거예요. 안 그래요?'),
(46268, 0, 4, '난 죽기엔 너무 젊어!'),
(46268, 0, 5, '제발 도와주세요!'),
(46268, 0, 6, '좀 도와주세요! 누구라도 괜찮아요!'),
(46276, 0, 0, '안됐지만 네 친구는 당분간 깨어나지 못할 거다. 난 내 악어에게 줄 먹이는 항상 완전히 기절시켜 두거든. 모름지기 식사는 기분 좋게 해야 하니까 말이야.'),
(46276, 1, 0, '하지만 너만은 예외로 삼아 주마. 악어들을 내보내라! 식사 시간이다!'),
(46276, 2, 0, '하! 운이 좋은 녀석이군! 내 애완동물이 네놈을 고깃덩이로 만들어줄 거다!'),
(46276, 3, 0, '그만! 이제 지겹다!'),
(46277, 0, 0, '영웅들이여, 이 어두운 곳에서 그대들은 혼자가 아닙니다!'),
(46277, 1, 0, '영웅들이여, 힘이 빠져나갑니다...'),
(46277, 2, 0, '신타리아, 네 주인은 내게 큰 빚을 졌다. 오늘, 네 가죽으로 그 빚을 받겠다!'),
(46277, 3, 0, '눈앞이 흐려지는군요... 이걸 받으십시오. 마지막 힘을 다했습니다. 부디 승리하십시오. 저를 위해... 이 세상을 위해 복수해 주십시오...'),
(46277, 4, 0, '생명의 불꽃이여, 제 몸을 휘감고 원기를 북돋워 주소서!'),
(46277, 5, 0, '넌 약해지고 있다. 필연적인 결과를 받아들여라!'),
(46277, 6, 0, '이제 끝입니다... 저를 용서하십시오, 여왕님...'),
(46375, 0, 0, '어서 일어나라, 게으른 놈들아! 전투를 벌일 때다!'),
(46379, 0, 0, '어서 일어나라, 게으른 놈들아! 전투를 벌일 때다!'),
(46381, 0, 0, '싸울 때다!'),
(46381, 0, 1, '싸울 때다!'),
(46381, 0, 2, '자유를 위해!'),
(46383, 0, 0, '란돌프 몰로크가 사라집니다!'),
(46383, 1, 0, '란돌프 몰로크가 사라집니다!'),
(46383, 2, 0, '란돌프 몰로크가 사라집니다!'),
(46425, 0, 0, '잠깐! 네페르세트 경비병이 오고 있소! 내가 놈들의 머리통을 부숴놓을 테니 내 가까이에서 싸우시오!'),
(46425, 1, 0, '마침내 자유를 찾았군. 이방인이여, 정말 고맙소. 타헤트는 이미 다른 곳으로 이송되었소. 카이마스라는 잔인한 네페르세트 장군이 그를 데려갔지.'),
(46496, 0, 0, '내... *콜록* 내 생명의 은인이시군요. 이방인이여, 감사합니다.'),
(46617, 0, 0, '후바-후바!'),
(46617, 0, 1, '거 다리에 모터라도 달아 드려야겠어요!'),
(46617, 0, 2, '무장한 상어라고? 왜 나는 그 생각을 못 했지!'),
(46617, 0, 3, '신나게 가자!'),
(46617, 0, 4, '정말... 굉장해!'),
(46617, 0, 5, '200마력, 이중 연소 엔진에 개량된 유량축전기까지! 짜잔!'),
(46617, 0, 6, '음파의 진동수만큼 흔들어 주세요!'),
(46753, 0, 0, '바람의 비밀의회가 패배했군. 필멸자들이여, 너희의 명예로운 전투와 투지가 가상하여 나를 직접 상대할 기회를 주겠다. 내 너희의 공격을 기다리고 있다! 오너라!'),
(46753, 1, 0, '도전을 받아들여 주마, 필멸자여! 너희가 공기의 정령 군주, 알아키르와 마주하고 있음은 알고 있느냐? 날 쓰러뜨리겠다는 꿈도 꾸지 마라!'),
(46753, 2, 0, '바람이여! 내 명에 따라라!'),
(46753, 3, 0, '집요한 것들. 이젠 화가 나는구나!'),
(46753, 4, 0, '폭풍이여! 너를 소환하노라!'),
(46753, 5, 0, '그만! 더는 자제하지 않겠다!'),
(46753, 6, 0, '파리 같은 놈들...'),
(46753, 6, 1, '조그만 것이 날 성가시게 하더니.'),
(46753, 8, 0, '폭풍이 지나가면, 고요가 찾아오는 법...'),
(46768, 0, 0, '가동.'),
(46769, 0, 0, '작동.'),
(46813, 0, 0, '이거야 원, 투지가 불끈 솟는 말이로군요!'),
(46813, 1, 0, '좋아요. 좋습니다! 이번엔 당신이 이겼습니다.'),
(46813, 2, 0, '싸움을 시작합니다...'),
(46813, 3, 0, '셋...'),
(46813, 4, 0, '둘...'),
(46813, 5, 0, '하나...'),
(46900, 0, 0, '물러서라, 쥐새끼야! (벌레! 작고 약해!)'),
(46900, 1, 0, '보아라, 필멸자여. 너에게 파멸을 안겨줄 도구를 보아라. (망치, 지하에 계신 신의 손.) 녹아내린 피로... (주인님의 선물! 주인님의 선물!) 마지막 폭풍의 제단에서 만든...');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(46900, 2, 0, '황혼의 망치를. (황혼의 망치를!) 죽음의 위상, 그분의 뜻에 따라 만들어진, 세상을 산산조각낼 무기지. 네가 다룰 물건이 아니다. (침입자를 없애라!) 모두 없애라!'),
(46900, 3, 0, '데스윙 님께서 시작하신 일은... (아무도 못 막아!) 아무도! 비참하기 그지없는 네놈들은 물론! (놈들의 최후를 보여줘.)'),
(46935, 0, 0, '웅장한 대학살의 도가니가 자네를 기다리는군, $n. 기억하라고. 일단 전투가 시작되면 투기장에서 나가면 안 돼. 죽이 되든 밥이 되든 말이지!'),
(46935, 1, 0, '신사 숙녀 여러분, 새로운 이야기가 시작됩니다. 대학살의 도가니에서 펼쳐지는 삶과 죽음의 드라마를 지켜보십시오! 이번에 $n의 상대는... 무지 뚱뚱한 오우거? 잠깐, 이게 뭐야?! 뭐? 시간이 없어서 이렇게밖에 못 썼다고? 그러고는 무슨 월급을 받겠다는 거야?!'),
(46935, 2, 0, '하여튼, 전투를 시작합니다!'),
(46935, 3, 0, '오오! 승부가 났습니다! 승리자가 결정됐어요! 힘찬 박수로 축하해 주십시오!'),
(46935, 4, 0, '웅장한 대학살의 도가니가 자네를 기다리는군, $n. 기억하라고. 일단 전투가 시작되면 투기장에서 나가면 안 돼. 죽이 되든 밥이 되든 말이지!'),
(46935, 5, 0, '여러분, 이번엔 특별히 "조그만" 놀라움을 준비했습니다! 작은 고추가 매운 법! 잔인한 와일드해머 드워프... 설리 니캐퍼와 $n의 대결을 지켜보십시오!'),
(46935, 6, 0, '이번 경기는 정말로 짧을 겁니다! 네, 네, 쓸데없는 소리는 이만 줄이지요. 피의 향연을 즐기십시오!'),
(46935, 7, 0, '신사 숙녀 여러분, 상대를 박살 내 버린 우리의 승리자를 보십시오! 바로 지금 다음 판 베팅을 시작합니다! 흐름을 놓치지 마십시오.'),
(46935, 8, 0, '전투가 곧 시작됩니다! 잔인한 용아귀 부족, 비룡잡이 토르그와 $n의 대결입니다! 잔인한 상대 맞겠죠?! 뭐, 확실하진 않습니다만... 우리에게 자신들의 옛 싸움터를 내준 데 감사하는 뜻에서 그냥 그렇다고 쳐 주죠. 피비린내나는 한판을 기대해 봅시다!'),
(46935, 9, 0, '끔찍하지만 아름다운 경기! 이 굴그토크는 언제나 여러분이 바라는 장면을 보여 드립니다. 아제로스에서 가장 극적인 대학살! 만족하셨다면 박수로 화답해 주십시오!'),
(46935, 10, 0, '여러분, 천재 포세이큰 과학자, 칼더 그레이가 제게 연락해 엄청난 투사를 제공하겠다는 제안을 했습니다. 지난 모든 용사들의 가장 훌륭한 특징을 말 그대로 "합쳐 놓은" 투사를요! 제가 얼마나 놀랐을지 상상이 가십니까? 칼더의 창조물과 싸워볼 기회를 세상 어느 용사가 거부할 수 있겠습니까?!'),
(46935, 11, 0, '그런 말이 있습니다... 꺾지 못할 상대와는 차라리 함께하라고요! 이 자리에서 패배한 도전자는 선택의 여지도 없이 상대와 함께해야 합니다! 아아, 찬란한 대학살의 도가니여!'),
(46935, 12, 0, '오오오오오! 정말 끔찍한 광경이로군요! 놀라운 승리입니다! 멋들어지게 처리했어요!'),
(46935, 13, 0, '우왓! 저분은 완전히 곤죽이 되셨는데요.'),
(46935, 14, 0, '그리 멀지 않은 그곳, 한때 길니아스라고 불린 짓밟힌 땅에서 우리의 용사가 분연히 일어났습니다! $n|1과;와; 친구들은 단단히 준비해야 할 겁니다. 특히 이번 상대에게 보름달을 보여 주는 건 금기라는 사실을 명심하십시오!'),
(46935, 15, 0, '아, 승부가 났습니다. 도전자들이 저 멍멍이를 확실히 쓰러뜨렸습니다! 대학살의 도가니 최고의 용사가 이렇게 무너지나요!'),
(46935, 16, 0, '그러나 우리의 도전자들을 상대할 자가 아직 한 명 더 남아 있습니다. 자, 돈을 거십시오!'),
(46935, 17, 0, '언제 어디서나 여러분 주위에 범죄가 끊이지 않도록 불철주야 노력하는 황혼의 망치단, 오늘도 예외는 아닙니다! 오늘의 마지막 투사는 바로 저 황혼의 요새에서 나온 인물입니다... 뭐, 무슨 상관이겠습니까!'),
(46935, 18, 0, '여러분 모두 열과 성을 다해 이자를 미워하시겠지요. 하지만 이자 또한 자신의 증오를 여러분께 기꺼이 퍼부을 것입니다. 최후의... 경기를... 시작합니다!!!'),
(46935, 19, 0, '믿을 수가 없군요! 새로운 용사가 대학살의 도가니를 접수했습니다! 어중이떠중이로 이루어진 어설픈 무리에게 거칠고 우람하고 악랄한 우리 투사들이 패배하고 말았어요! 참으로 극적입니다!'),
(46942, 0, 0, '당신의 검을 쥐십시오, 여행자여!'),
(46942, 1, 0, '이 야수는 갈퀴발 놀 무리를 이끌며 엘윈 숲에서 놀의 침략을 종식시키는 데 실마리가 될 것이다.'),
(46942, 2, 0, '바리안 린 국왕 폐하의 이름으로 들창코를 수감하도록 한다.'),
(46942, 3, 0, '안드로매스, 우릴 지하감옥으로 이동시켜 주시오.'),
(46943, 0, 0, '마커스 조나단 장군님이시다!'),
(46943, 1, 0, '우와!'),
(46945, 0, 0, '황혼의 고원은 전부 다 용아귀 부족의 것이다! 이 구덩이도 마찬가지야!'),
(46945, 1, 0, '한심한 고기 덩어리 같으니! 용아귀 부족의 진정한 힘을 느껴 봐라!'),
(46946, 0, 0, '내 여동생도 너희보다는 낫겠다. 이게 무슨 투기장이야? 보육원이지!'),
(46947, 0, 0, '너 처치하면 네 몸뚱이 준다고 칼더 아빠가 약속했다!'),
(46947, 1, 0, '에잇! 저리 가, 이 고약한 놈아!'),
(46947, 2, 0, '응, 아빠!'),
(46947, 3, 0, '어! 너무 배불러... 안 돼...'),
(46948, 0, 0, '반갑다, 애송이들아. 이 아름다운 저녁에, 그렇게까지 놀랍지는 않은 놀라움을 하나 선사해 주지.'),
(46948, 1, 0, '단언하건대, 이런 놀음도 여기서 끝이다. 때가 되었군... 내 안의 야수가 등장할 때가!'),
(46948, 2, 0, '장난은 여기서 그만두지! 이제 손에 피를 묻힐 시간이다!'),
(46949, 0, 0, '이 땅은 황혼의 불꽃 아래 정화되리라!'),
(46949, 1, 0, '불의 땅을 흐르는 열기에 타버려라!'),
(46949, 2, 0, '하늘도 내 분노로 타오른다!'),
(46962, 0, 0, '워워! 사냥 시작이군!'),
(46962, 1, 0, '이런 천것들에게 잡히다니, 내 꼴이 우스워졌군...'),
(46962, 2, 0, '이거 너무 쉬운데...'),
(46962, 3, 0, '하! 조금 더 흥미진진하게 해볼까?'),
(46962, 4, 0, '이젠 사냥도 지겹군... 그냥 죽어 버려라!'),
(46962, 5, 0, '한심한 것.'),
(46962, 5, 1, '사냥이 너무 시시하군.'),
(46963, 0, 0, '여기서까지 멍청한 놈들에게 괴롭힘을 당해야 하는 건가!'),
(46963, 1, 0, '이제 새로운 삶이 시작되는군...'),
(46963, 2, 0, '유치한 장난도 이제 끝이다!'),
(46963, 2, 1, '이젠 날 귀찮게 할 수 없겠지!'),
(46964, 0, 0, '이바르 녀석, 자기 부하들이 참패하자 용병 무리를 보냈군. 상관없다. 너희의 여정은 고통 속에 끝날 것이다.'),
(46964, 1, 0, '너희도 망할 실바나스가 보낸 놈들이겠지? 상관없다. 너희의 여정은 고통 속에 끝날 것이다.'),
(46964, 2, 0, '깨끗이 죽여 줘서 고맙군. 나는 너희에게 그리하지 않았을 텐데...'),
(46964, 3, 0, '이 짓은 싫증도 안 난단 말이지.'),
(46964, 3, 1, '날 잡으러 온 전문 암살자라는 것들이 이 정도 실력이라니. 우습지도 않군.'),
(46965, 0, 0, '필멸자 주제에! 감히 우리 성소에 발을 들이다니! (불신자. 이단자! 모두 불타버려!)\n 너희는 돌아갈 수 없는 죽음의 문턱을 넘어섰다. (활활 타라! 이단자는 불타라.)'),
(46965, 1, 0, '할푸스! 잘 듣거라! (주인님이 부른다. 주인님이 원한다.) 비밀을 보호하라, 할푸스. 침입자들을 처단하라. (명예를 위해 처단하고 배고파서 처단한다.)'),
(46965, 2, 0, '살점과 근육, 약골들이 날뛰는군. 감히 주인님께 반항하다니... 비틀비틀 장님처럼 방황하네. 얽히고설킨 운명과 혼돈.'),
(46965, 3, 0, '혼돈의 형제들이여, 황혼이 깃들었다! (길어진 그림자, 끝없는 밤.) 데스윙 님이 세상을 가르셨으니... (한 번 열린 문은 닫히지 않아.) 진정한 주인들이 돌아오리라. (주인님이 오신다, 오신다, 오신다.)'),
(46965, 4, 0, '너희는 선택받은 존재다. (널 부르신다, 주인님은 널 알아.) 살점으로 빚어지고... (살점!) 피로 정화된... (피!) 불멸의 존재!'),
(46965, 5, 0, '그분의 부름에 응답하라! 이단자들을 즉시 처단하라!'),
(46965, 6, 0, '망치단의 형제들이여, 내게 오라! (놈들의 의지가 살아 있다.) 불신자들이 아직 살아 있다. 놈들을 처치하라! (놈들의 뼈를 부수고 의지를 꺾어라.)'),
(46965, 7, 0, '필멸의 존재들. 똥 된장도 구분 못 하는 어리석은 것들. (멍청이, 멍청이.)'),
(46965, 8, 0, '발리오나, 테랄리온, 놈들을 처치하라.'),
(46965, 9, 0, '(가까이, 더 가까이... 얼굴을 우리에게 보여줘. 모두 그분 앞에 무릎 꿇게 될 거야.)'),
(46965, 10, 0, '어서 오라, 필멸자여. (나약한 애송이들...) 이 성소에 발을 들인 자는 많지 않다. (맨손으로 불을 잡으려 드는 멍청이들!)'),
(46965, 11, 0, '여기가 바로 선택받은 자들이 운명을 실현하는 곳이다. (영원으로!) 그리고 너희도 여기서 운명을 실현할 것이다. (육신의 파멸, 육신의 파멸!)'),
(46965, 12, 0, '황혼의 형제들이여! 망치가 너희를 부르고 있다! (불, 물, 대지, 바람.) 필멸자의 껍데기를 벗어 던져라. (불, 물, 대지, 바람!) 새로운 모습으로 태어나라. 지금부터 영원히! (불타고, 물에 빠지고, 부서지고, 질식하고.) 너희가 얻은 능력으로 불신자들을 처치해라. (불타고, 물에 빠지고, 부서지고, 질식하고! 으하하하하!!)'),
(46965, 13, 0, '어리석은 필멸자들아... (나약한 침입자들!) 너희가 행한 어떤 행위도, (작은 신의 탄생!) 이봐! 내가 지금 말하고 있잖아. (말, 말, 말. 주인님은 죽음을 원하지.) 모두 혼돈에 휩싸인다. 모두 파괴될 것이다. (혼돈, 혼돈!) 너희가 오늘 벌인 일은 아무것도 바꿀 수 없다. (혼돈, 혼돈, 모두 끝이야.) 하지만 너희는 너무 많은 것을 목격했다. 너희의 마지막 순간이다!'),
(46986, 0, 0, '어떤 이들은 이 비밀을 밝히려고 수세기 동안 명상에 빠지기도 했네, 아분. 난 그대에게 같은 운명을 주고 싶지 않네.'),
(46986, 1, 0, '빛은 그 누구의 고통도 원하지 않는다네. 하지만 아무런 저지 없이 우리 세상에 군림하지도 않지.'),
(46986, 2, 0, '지금 이 순간에도, 빛과 어둠의 싸움이 점점 더 다가오고 있네. 이 싸움에는 우리 모두 휘말릴 것이며, 필멸자들의 고통은 이 분쟁 앞에선 모두 의미 없는 일이 될 것이야.'),
(46986, 3, 0, '막투르, 자네는 역경을 용감하게 잘 견뎌냈네. 빛의 품으로 돌아갈 준비가 되었는가?'),
(46986, 4, 0, '그러면 빛이 자네를 구원하고 감싸 줄 걸세.'),
(46986, 5, 0, '잊지 말게, 아분. 방황하는 자가 모두 길을 잃은 것은 아니네.'),
(47001, 0, 0, '지금까지도 전혀 반응이 없군, 어째서지? 왜 빛은 무고한 자를 저버리는 거지?'),
(47001, 1, 0, '예언자 벨렌 님!'),
(47001, 2, 0, '...고맙습니다, 예언자 님. 우리 둘에게 큰 편안함을 안겨 주셨습니다. 전 막투르에 대한 믿음과 기억을 안은 채, 연구를 계속하겠습니다.'),
(47006, 0, 0, '포세이큰에게 무릎을 꿇다니, 크롤리는 늑대인간의 수치다. 내가 이끄는 늑대인간 무리가 놈들에게 우리의 진정한 모습을, 그리고 우리가 가져오는 무한한 공포를 보여주리라!'),
(47006, 1, 0, '애처롭군.'),
(47006, 2, 0, '계속 전진해라. 내 부하들이 이 딱한 뼈다귀 자루를 처리할 것이다.'),
(47006, 3, 0, '자제해라! 고드프리를 처치하는 것이 우리의 가장 중요한 임무이다. 전리품을 즐기는 건 나중으로 미뤄라!'),
(47006, 4, 0, '놈을 끝장내려면 계속 밀고 나가야 한다. 따라와라. 내가 안마당 문을 열 테니 우리의 공격을 선두에서 지휘하라.'),
(47006, 5, 0, '이것도 자물쇠라고! 우릴 저지하고 싶다면 훨씬 더 애써야 할 텐데, 고드프리...'),
(47006, 6, 0, '월든의 악취가 느껴진다. 놈의 피냄새로 이곳을 채우자!'),
(47006, 7, 0, '드디어 너의 종말이 다가왔다, 고드프리!'),
(47006, 8, 0, '공격하라, 형제들이여! 늑대인간 무리의 분노가 어떤 것인지 보여 줘라!'),
(47006, 9, 0, '조금이라도 전리품을 원한다면 서두르는 게 좋을 것이다.'),
(47006, 10, 0, '문이 왜 닫혀 있는지 모르겠다, 영웅들이여. 내 무리가 지금쯤이면 이미 고드프리를 처리했을 텐데...'),
(47006, 11, 0, '여기서 시간만 죽일 수는 없지! 행동할 시간이다!'),
(47006, 12, 0, '아무것도 너희를 방해하지 못하게 하겠다. 가라, 영웅들이여! 고드프리를 없애라!'),
(47008, 0, 0, '내가 원한 건 조용하고 평화로운 삶뿐이었다!'),
(47162, 0, 0, '으어어... 너무... 세다아아아...'),
(47162, 1, 0, '비전 마력!!!'),
(47162, 2, 0, '글럽톡이 너희한테 비전 마력 보여준다!'),
(47162, 3, 0, '하 하 하 하!'),
(47162, 3, 1, '저거 뻗었다!'),
(47162, 4, 0, '불꽃 주먹 받아라!'),
(47162, 5, 0, '글럽톡 간다!'),
(47162, 6, 0, '얼음 주먹 받아라!'),
(47162, 7, 0, '응, 가자!'),
(47249, 0, 0, '그래, 아주 좋아. 그러면 기록을 마지막으로 한 번만 확인해 보자고.'),
(47249, 1, 0, '어... 음... 그래, 그래... 아주 간단하군...\n'),
(47249, 2, 0, '자, 고블스! 이제 시작할 준비가 됐다! 이리 와!'),
(47249, 3, 0, '잠깐만 기다려, 고블스! 모두 물러서!'),
(47249, 4, 0, '뭐지!?'),
(47249, 5, 0, '불쌍한 고블스...'),
(47249, 6, 0, '대체 뭐가 잘못된 거지? 하라는 대로 정확히 따라 했는데...'),
(47249, 7, 0, '잠깐! 이게 뭐야?!'),
(47249, 8, 0, '너 우상을 여덟 개만 가져왔잖아!'),
(47249, 9, 0, '이 의식에는 정확히 아홉 개가 필요하다니까!!'),
(47249, 10, 0, '아홉 개! 아홉! 아홉 개라고!!'),
(47249, 11, 0, '당장 내 눈앞에서 꺼져! 제길...'),
(47266, 0, 0, '어디 이 불꽃에 무엇이... 아니 이건?'),
(47269, 0, 0, '왜 그러는 거야? 왜 죽였어!!'),
(47270, 0, 0, '대체... 어떤 놈이... 당장 내 발굴지에서 꺼져!!'),
(47270, 1, 0, '%s|1이;가; 격노합니다!'),
(47271, 0, 0, '도대체 밖에서 무슨 일이 일어난 거야?'),
(47271, 1, 0, '그래, 다 네놈 때문에 일어난 일이었구나!'),
(47281, 0, 0, '이제 돌머리가 거미 탄다!'),
(47281, 0, 1, '거미 물러나라! 돌머리가 간다!'),
(47281, 0, 2, '돌머리 지금 거미 탄다!'),
(47281, 0, 3, '거미 너 가만히 있어!'),
(47281, 0, 4, '거미에 탈 시간이다!'),
(47281, 1, 0, '거미가 돌머리 배에 독 남겨놨다. 필요해?'),
(47281, 1, 1, '여기 독주머니 있다.'),
(47281, 1, 2, '돌머리 배에 독주머니 있다.'),
(47281, 2, 0, '너 누구 죽이면 돌머리 기분 안 좋다.'),
(47293, 0, 0, '우리가 사용한 이 역병은 아주 특별하다네. 고드프리의 부하들은 역병 때문에 성채를 떠날 수 없지만, 우리는 역병에 전혀 영향을 받지 않고 포세이큰의 이름으로 진군할 수 있지!'),
(47293, 1, 0, '생각했던 것보다 훨씬 훌륭한 솜씨를 보여주는군.'),
(47293, 2, 0, '그럼 좋네. 안마당 문을 열고 계속 전진하지!'),
(47293, 3, 0, '자물쇠를 여는 게 그리 어렵진 않을 걸세.'),
(47293, 4, 0, '다 됐네!'),
(47293, 5, 0, '좋았어. 자, 이제 역병을 퍼뜨리고 다음 지역으로...'),
(47293, 6, 0, '크로무쉬! 여기서 무얼 하고 있소? 이것은 비밀 작전이오!'),
(47293, 7, 0, '사과드리오, 크로무쉬. 하지만 정말 아무런 문제도 없소. 우리는 효력을 엄청나게 약화시킨 역병을 사용하고 있소.'),
(47293, 8, 0, '우리를 쫓아오려고 하는 늑대인간을 겁주는 정도밖에 효력이 없는 역병이라오. 전혀 위험하지 않소.'),
(47293, 9, 0, '물론이오. 우리는 언제나 호드에게 가장 이득이 되는 방향으로 행동하오, 장군. 이 영웅들은 우리를 위해 스프링베일을 처치하러 가려던 참이었소.'),
(47293, 10, 0, '월든 경 주변 지역을 확보하라고 내 부하들을 먼저 지붕 위로 보냈네.'),
(47293, 11, 0, '물론, 거기까지 가는 길에 있는 소규모 병력은 누군가 알아서 처리해 줘야겠지.'),
(47293, 12, 0, '때가 왔다, 병사들이여! 고드프리가 바로 앞에 있다! 자비를 보이지 마라! 우리는...'),
(47293, 13, 0, '자네들도 재미를 보고 싶다면 서두르는 게 좋을 게야.'),
(47293, 14, 0, '어째서 문이 닫혀 있지? 실바나스 님이시여... 대체 무슨 일이 생긴 거지...'),
(47293, 15, 0, '크로무쉬! 무슨 일이오?'),
(47293, 16, 0, '네놈은 대가를 치를 것이다, 고드프리!'),
(47293, 17, 0, '영웅들이여, 고드프리를 처치하게! 무엇도 자네들을 방해하지 못하게 하겠네!'),
(47294, 0, 0, '내가 잘못 기억하는 게 아니라면, 대족장님께서 전면적인 역병 사용을 완전히 금지하셨던 것 같소만. 그 어떤 상황에서라도 말이오.'),
(47294, 1, 0, '그렇다면 당신의 임무에 내가 동행을 청해도 거절하지 않으리라 믿소.'),
(47294, 2, 0, '하지만 경고하겠소, 벨몬트. 거짓말을 하고 있음이 밝혀지면...'),
(47294, 3, 0, '당신은 대족장님의 분노를 몸소 느껴야 할 거요.'),
(47294, 4, 0, '호드를 위하여!!!'),
(47294, 5, 0, '비겁한 자식이... 병사들을 죽이고... 내게... 독을...'),
(47296, 0, 0, '저울이... 기울었군...'),
(47296, 1, 0, '애걔, 10 코퍼? 처치해도 보람이 없네.'),
(47296, 2, 0, '미련한 놈들을 상대하는데 미련퉁이는 필요 없지!'),
(47296, 3, 0, '폭탄 투하!'),
(47296, 4, 0, '미련퉁이야! 던져!\n'),
(47296, 5, 0, '너희를 처치하면 여주인께서 상금을 주시겠지!'),
(47297, 0, 0, '미련퉁이가 때려줄 거야!'),
(47299, 0, 0, '돌머리 뭐 죽이는 거 다 지겹다! 돌머리 이제 그만할래!'),
(47299, 1, 0, '돌머리 진짜 모험하러 떠날 거다!'),
(47301, 0, 0, '너희 드워프들은 쓸모가 없는 놈들이로구나! 승천을 바라며 라그나로스 님을 찾아왔으면서도 아무것도 바칠 게 없다니!'),
(47301, 1, 0, '몸뚱이와 삽을 제외하고는 바칠 게 없군. 그러니 네놈들은 땅이나 파게 될 것이다.'),
(47301, 2, 0, '넓고, 또 깊게 파거라. 세상 아래에 불로 가득 찬 곳을 찾도록 말이야. 내 형제들이 자유를 절실히 바라고 있다.'),
(47301, 3, 0, '성공하면 너도 결국 승천할 것이다. 하지만 실패하면 불에 타죽겠지.'),
(47308, 0, 0, '벌입니다! 물속으로 뛰어들어 떨쳐내십시오!'),
(47309, 0, 0, '네놈은 고통받을 것이다! 황혼의 망치단의 격노를 맛볼 것이다!'),
(47310, 0, 0, '고통만이 네놈을 반길 것이다!'),
(47333, 0, 0, '자, 여기 있다. 작은 드워프한테 훔친 거야.'),
(47333, 0, 1, '저 친구 잠깐 졸릴 거야. 돌머리가 안다. 돌머리도 그랬었어.'),
(47333, 0, 2, '여기 있다. 너 드워프 물건 가져가도 된다.'),
(47333, 0, 3, '너 드워프 물건 가져가. 안 죽여도 돼.'),
(47333, 0, 4, '앉는 거 죽이는 거보다 쉬워.'),
(47333, 0, 5, '여기 있다.'),
(47339, 0, 0, '저리 꺼져, 꼬마야. 날 귀찮게 하지 마!'),
(47339, 1, 0, '얼굴 정중앙을 때리다니! 아우 아우 아퍼...'),
(47339, 2, 0, '임프시를 자루에 담으십시오!'),
(47442, 0, 0, '좋습니다. 지금은 그 임무 하나만 하겠습니다. 다만, 제가 자잘한 임무를 더 찾길 바라십시오. 못 찾으면 다시 올 겁니다. 토론장에 당신에 대한 악평을 퍼뜨릴 거고요.'),
(47443, 0, 0, '좋다, 겁쟁아. 그 뼈다귀 말 위에 앉아 오르쿠스가 호드의 영광을 드높이는 모습을 지켜보도록! 천 개의 해골을 들고 돌아오마!'),
(47444, 0, 0, '북쪽이라고! 알겠어! 고마워! 안녕! 고마워!'),
(47462, 0, 0, '라그나로스 님의 불길이 네놈을 모두 태워버릴 것이다.'),
(47462, 1, 0, '%s|1이;가; 약해졌습니다. 이제 그를 추방하십시오!'),
(47462, 2, 0, '멍청하기는! 너는 나를 이길 수 없다! 나는 계속 되살아날 테니까 말이야...'),
(47510, 0, 0, '네놈을 쏴버리면 재미있겠군!'),
(47510, 1, 0, '쓸모없는 와이번 녀석! 어차피 네놈 따윈 필요 없다!'),
(47510, 2, 0, '이게 뭐야? 저리 꺼져!'),
(47510, 3, 0, '안돼! 저리 가! 나에게서 떨어져!'),
(47510, 4, 0, '안돼애애애애!'),
(47510, 5, 0, '아아아아아아아......!'),
(47512, 0, 0, '나아가라, 아름다운 나의 천사여! 아아, 아이를 떠나보내는 마음이 어찌나 슬픈지...'),
(47512, 1, 0, '아가야, 이제 네 최고의 기술을 사용할 시간이다!'),
(47512, 2, 0, '이럴 수가... 내 창조물이! 하늘을 가릴 만큼 커지지도 않았는데! 연구 일지를 다시 살펴보는 게 좋겠군...'),
(47512, 3, 0, '자네의 몸은 참으로 훌륭하군! 내 약속하지. 이 마취제를 조금만 들이키면, 깨어날 땐 지금보다 10배는 더 강하고 100배는 더... 계획적으로 조화를 이룬 모습이 될 걸세.'),
(47512, 4, 0, '싫다고? 그래... 어쨌든 내 제안은 아직 유효하네. 마음이 바뀌면 언제든 들르게. 자네가 꿈에 그리던 모습으로 손봐 줄 테니.'),
(47556, 0, 0, '히히... 히히히... 하하하!'),
(47556, 1, 0, '날 바보라고 부르지 마, 바보야!'),
(47558, 0, 0, '쉿! 밖에서 네 소리를 들을 수도 있단 말이야, 바보야!'),
(47558, 1, 0, '아오! 이제 우리 모습이 보일 거야!'),
(47602, 0, 0, '응? 뭐라고?'),
(47619, 0, 0, '거울이라고? 어쩜 좋아라!'),
(47620, 0, 0, '공수부대?!'),
(47626, 0, 0, '그분을... 찾아봤자... 이미 때는 늦었어...'),
(47626, 1, 0, '피 맛을 보니 더 배고파지는군.'),
(47626, 2, 0, '등골이 서늘하지 않나?'),
(47626, 3, 0, '네 공포가 느껴지는군...'),
(47626, 4, 0, '네 심장을 꺼내 주마!'),
(47626, 5, 0, '아... 신선한 고기다...'),
(47836, 0, 0, '선적실로 가려면 저를 따라오십시오, $n.'),
(47872, 0, 0, '놈이 모두 죽였습니다! 모두 죽였다고요!'),
(47872, 0, 1, '이 은혜는 평생 잊지 않겠습니다, $r님.'),
(47872, 0, 2, '노... 놈은 우릴 곡물처럼 땅에 심어 버렸습니다! 스틸워터는 미쳤어요! 도망칠 수 있을 때 얼른 도망치십시오!'),
(47872, 0, 3, '어... 어쩌면 당신은 사악한 자가 아닐지도...'),
(47872, 0, 4, '만약 당신이 비료밭에 머리만 내놓고 파묻히신다면, 반드시 도와드리겠습니다.'),
(47872, 0, 5, '제 목숨을 구해주셔서 감사합니다. 큰 신세를 졌군요.'),
(47923, 0, 0, '어리석은 자여! 지금 무슨 짓을 하고 있는지 아시오?'),
(47923, 1, 0, '그만! 무기를 내려놓으시오!'),
(48001, 0, 0, '이... 이건 완벽하군요! 이 변장은 제 걸작입니다요!'),
(48022, 0, 0, '어서 오세요!'),
(48037, 0, 0, '전투 결과: 당혹스러운 실패. 새로운 방식을 전투 체계에 정립 중.'),
(48037, 1, 0, '독학 완료!'),
(48037, 2, 0, '주먹으로 때리기 맞았음. 전투 변수 조절 중...'),
(48037, 2, 1, '넘어뜨리기 당함. 다음 전투를 위한 전략 최적화 중...'),
(48037, 3, 0, '훈련 단계 충분함. 경비 임무로 돌아갑니다. 감사합니다.'),
(48119, 0, 0, '이봐, 잠깐 기다려봐...'),
(48119, 0, 1, '너 누군지 모르겠는데...'),
(48119, 0, 2, '흠... 이곳에 새로 온 자인가...?'),
(48119, 0, 3, '우리 일원 아니군, 그렇지...?'),
(48121, 0, 0, '이봐, 잠깐 기다려봐...'),
(48121, 0, 1, '너 누군지 모르겠는데...'),
(48121, 0, 2, '흠... 이곳에 새로 온 자인가...?'),
(48121, 0, 3, '우리 일원 아니군, 그렇지...?'),
(48154, 0, 0, '우리가 보이는 건가...'),
(48154, 0, 1, '앞을 보지 못하게 해주지!'),
(48154, 0, 2, '아무에게도 말하지 못하게 해주마!'),
(48154, 0, 3, '침입자다...'),
(48160, 0, 0, '네가 죽으면 이야기가 달라지겠지!'),
(48201, 0, 0, '지금 뭐하고 있는 거로 생각하는 건가, 병사?!'),
(48201, 0, 1, '두 동강 내 주겠지! 잠깐... 당신 누군가?'),
(48201, 0, 2, '멈추라고, 난 일개 병사가 아니란 말이오! 흠... 당신은?'),
(48201, 0, 3, '뒤집어쓴 게 가면인가, 병사?'),
(48331, 0, 0, '자, 심호흡하고... 심호흡하고!'),
(48331, 0, 1, '이제 괜찮아!'),
(48331, 0, 2, '어서 막자고!'),
(48331, 0, 3, '방금 그거 기분 괜찮은데!'),
(48331, 0, 4, '그만 때려! 이제 고블린처럼 행동할 시간인가!'),
(48331, 0, 5, '우와! 나 지금 어디지?!'),
(48331, 0, 6, '알았어! 알았으니 두 번 때리지 마!'),
(48397, 0, 0, '읔, 냄새가 고약해... 내 배가 큰 걸 요리했나 보군. 그렇지 않고서야 이런 냄새가 날 순 없지.'),
(48397, 1, 0, '아니, 저것들은!'),
(48397, 2, 0, '왕을 쓰러뜨린 자 오르쿠스에게 덤벼라, 드워프 놈아!'),
(48397, 3, 0, '카샤! 네 주인을 지원하라!'),
(48403, 0, 0, '이봐, 발린다. 이바르 블러드팽이란 작자는 어디서 만나기로 했지? 그건 그렇고, 이 역겨운 냄새는 대체 뭐야?'),
(48403, 1, 0, '발린다! 저쪽을 봐! 저건...'),
(48487, 0, 0, '무슨 일입니까?!'),
(48487, 1, 0, '대드루이드님... 세상에 어떻게 이런 일이...?'),
(48487, 2, 0, '다... 다른 이들에게 알려야겠습니다. 지금 당장 여사냥꾼 셀루라를 찾아가십시오.'),
(48752, 0, 0, '이단자여, 썩 꺼져라! 여긴 너희가 올 곳이 아니다!'),
(48752, 0, 1, '죽음은... 그저 시작에 불과해!'),
(48752, 0, 2, '이제 안식이 함께하기를.'),
(48752, 0, 3, '하늘이 널 데려가리라!'),
(49045, 0, 0, '멀리서 오우가 나타납니다!'),
(49045, 1, 0, '크아아! 너희 악어 어떻게 죽였지?!'),
(49045, 2, 0, '오우 똑똑하다! 너희 안 볼 때 오우가 보물 훔쳤다!'),
(49045, 3, 0, '오우가 최고다! 오예!'),
(49045, 4, 0, '오우가 너희 보물 훔쳤다. 움 움 움움!'),
(49045, 5, 0, '누가 나빠?! 오우가 나빠!! 움!'),
(49045, 6, 0, '끼야아아!!!'),
(49141, 0, 0, '반갑습니다, $n.'),
(49141, 1, 0, '암흑의 무덤은 이쪽에 있네. 나를 따라오게나, $n.'),
(49141, 2, 0, '이쪽입니다!'),
(49141, 3, 0, '자, 물건이 어디에 있을까?'),
(49141, 4, 0, '이쪽에 있지 않나?'),
(49141, 5, 0, '가... 감사합니다, 장... 의... 사님.'),
(49141, 6, 0, '아니야. 이쪽에는 없군.'),
(49141, 7, 0, '이보게, 나 좀 도와주게나, $n! 모르도가 말한 물건을 찾을 수가 없다네!'),
(49141, 8, 0, '어디 한번 보자... 물건이 어디에 있을까...'),
(49141, 9, 0, '잘했네! 자네가 물건을 찾았군. 모르도에게 되돌려 주세나.'),
(49141, 10, 0, '저기 있는 친구가 턱이 떨어졌더군. 모르도가 고쳐줄 수 있나?'),
(49226, 0, 0, '영웅들이여, 내 거처에 온 걸 환영한다! 이곳이 너희 마음에 들었으면 좋겠군. 여기서 너흰 내 실험의 실패작들을 마주하고, 결국엔 내 최고의 성공작도 보게 될 것이다!'),
(49226, 1, 0, '자기가 영웅이라고 착각하는 필멸자 무리가 파괴된 전당에 들어왔군. 흥, 이번 "공격대"는 지난번 놈들보다는 괜찮았으면 좋겠어.'),
(49226, 2, 0, '내가 실수했군. 저런 한심한 이름을 가진 기계들에게... 재미있는 구경거리를 기대하다니.'),
(49226, 3, 0, '흠... 만능골렘 방어 시스템이라. 오래전에는 이 시설이 드워프가 이룩한 엄청난 기술적 성과로 여겨졌지. 하지만 각 골렘의 공격에 대응할 방법이 너무 많은 게 문제야. 조금이라도 보는 재미가 있으려면 설계를 좀 손봐야 할 것 같군.'),
(49226, 4, 0, '그놈에게서 도망가고 싶겠지. 안 그런가? 안됐군.'),
(49226, 5, 0, '멍청한 드워프 놈들은 왜 그렇게 룬을 좋아하는지! 적을 도울 수도 있는 걸 도대체 왜 만들었는지 모르겠군.'),
(49226, 6, 0, '하하하... 번개 전도체는 인원이 많을수록 효과가 좋지.'),
(49226, 7, 0, '맹독골렘의 화학 물질로 다른 골렘에 피해를 줄 생각이었겠지? 영리한 계획이다만, 그렇게 둘 수는 없지.'),
(49226, 8, 0, '그놈은 수리비만 잡아먹는 불량품, 쓰레기였어.'),
(49226, 9, 0, '이 방 바로 아래에 흐르는 용암 속에서 그 매혹적인 생명체를 찾아냈지. 용암아귀라면 한심한 네놈들에게 적당한 도전 거리가 될 것이다.'),
(49226, 10, 0, '마침내 누군가 저 흉측한 놈을 없애 줬군. 정말 고맙다, 영웅들이여.'),
(49226, 11, 0, '너희가 이겼군. 참으로 실망스럽구나. 너희가 불구덩이 속에서 이리저리 뛰는 모습을 즐길 수도 있었는데.'),
(49226, 12, 0, '이런 곤란할 데가! 이러다간 내 용암 벌레가 정말 질 수도 있겠군! 그럼... 내가 상황을 좀 바꿔 볼까?'),
(49226, 13, 0, '아, 다시 생각해 보니 "적당한" 도전에 무슨 재미가 있겠나?'),
(49226, 14, 0, '말로리악, 필멸의 존재들에게 지지 마라. 너만큼이라도 능력이 있는 놈은 만들기 어렵지.'),
(49226, 15, 0, '혼합물이 너무 약하구나, 말로리악! 좀 더... 센 게 필요해! 으하하하하하...'),
(49226, 16, 0, '정말 축하한다! 너희가 달성한 놀라운 업적에 걸맞은 멋진 칭호를 하나 내려 주지. 지금부터 너희는 "멍청하고 무능하고 실망스러운 하수인들을 해치운 자"로 알려질 것이다.'),
(49226, 17, 0, '어차피 마음에 안 드는 놈이었어... 잘 처치했다!'),
(49226, 18, 0, '그냥 오래전에 널 없애 버렸어야 했는데.'),
(49226, 19, 0, '이 방패들은 정말 귀찮군.'),
(49226, 20, 0, '아트라메데스, 적은 바로 저기에 있다!'),
(49226, 21, 0, '아트라메데스, 눈처럼 귀도 먼 건 아니겠지? 어서 놈들을 모조리 처치해라.'),
(49226, 22, 0, '아니, 그렇게까지 할 필요는 없잖아!'),
(49226, 23, 0, '놀랍군. 내가 만든 가장 끔찍한 피조물을 파괴했구나. 아무도 그놈은 못 이길 줄 알았는데.'),
(49226, 24, 0, '흠... 저 실험체를 잃다니, 애석하군.'),
(49226, 25, 0, '아, 키마이론. 과학자로서 내 실력이 어떤지 잘 보여주는 생명체지. 오랜 시간 동안 녀석의 모습을 수없이 다시 만들고 변형했다. 보다시피 마지막 결과물은 참으로 훌륭하지.'),
(49226, 26, 0, '아, 기대했던 것과 달라서 놀랐겠지. 그렇지 않으냐? 내가 만든 일련의 "수정 사항"에 너희가 얼마나 잘 적응하는지 보자꾸나.'),
(49226, 27, 0, '이 중요한 순간에 뭐 하는 짓이냐, 키마이론!'),
(49226, 28, 0, '이거 전투가 좀 지루해졌군. 내가 분위기를 띄워 주지!'),
(49230, 0, 0, '으아아아아아아!!! 나는 괴물이야! 나를 쳐다보지 마!'),
(49230, 0, 1, '누굴 보고 괴물이라고 하는 건가? 괴물은 자네일세! 나는 단지 죽은 사람일 뿐이야.'),
(49231, 0, 0, '발드레드 모레이, 임무 보고합니다!'),
(49231, 0, 1, '알겠소. 자, 그러면 어서 일하러 가십시다, $n! 어둠의 여왕님께서 우리를 필요로 하시지 않소. 안 그렇소?'),
(49337, 0, 0, '어디 한번 보자... 물건이 어디에 있을까...'),
(49337, 1, 0, '죽음의 종소리 마을로 가는 길을 알고 있네. 나와 같이 가세나!'),
(49337, 2, 0, '좋아, 자네 아직도 살아 있군. 이제 죽음경비병 살테인은 어디 있는 거지?'),
(49337, 3, 0, '아, 저기 있군.'),
(49337, 4, 0, '아, 저기 있군.'),
(49337, 5, 0, '저 앞에 시체가 좀 보이는 것 같군. 어서 가세, $n! 자네가 수색과 전투를 하게나. 내가 시체들을 옮기겠네.'),
(49422, 0, 0, '널 죽이겠다!'),
(49422, 0, 1, '놈들이 내게 무슨 짓을 했는지 보란 말이다!'),
(49422, 0, 2, '나는 누구란 말인가?'),
(49422, 1, 0, '%s|1이;가; 격노합니다!'),
(49423, 0, 0, '널 죽이겠다!'),
(49423, 0, 1, '놈들이 내게 무슨 짓을 했는지 보란 말이다!'),
(49423, 0, 2, '나는 누구란 말인가?'),
(49424, 0, 0, '으아아아아아아!!! 나는 괴물이야! 나를 쳐다보지 마!'),
(49426, 0, 0, '반갑네, $n! 내 새 장비 어떤가?'),
(49426, 1, 0, '그들이 나를 죽음경비병으로 만들고 있다네. 믿어지나?'),
(49426, 2, 0, '난 아마 죽음의 종소리 마을에 남을 것 같아. 그래도 일이 잘 풀리면... 누가 알겠어? 어쩌면 어둠의 여왕님을 직접 만나게 될지도 모르지.'),
(49426, 3, 0, '자네는 어떤가? 사비스 님께서 자네를 칼스턴 영지로 보내겠다고 하시던데 말이네. 정말 막중한 임무를 주시는군, 안 그렇나?'),
(49426, 4, 0, '더 붙잡아 두지는 않겠네. 만나서 반가웠어. 곧 다시 마주치길 바라지.'),
(49478, 0, 0, '훈련은 당신에게 맡기겠습니다, 일사레인. 이 분야는 당신의 전문이니까요.'),
(49478, 1, 0, '열심히 배우세요, $n. 다음 보름달이 뜨기 전에 당신이 우리 곁에서 싸워야 할지도 모릅니다.'),
(49634, 0, 0, '대양의 바닥에선 빛조차도 죽으리니.'),
(49634, 0, 1, '말 없이 잠자며 노려보는 깊은 산속의 집들은 늘 꿈을 꾼다. 집들을 파괴하는 것이 오히려 자비이리라.'),
(49634, 0, 2, '실제와 가상을 딱 잘라 구분할 순 없다.'),
(49634, 0, 3, '죽음도 죽음을 피하지 못하리라.'),
(49634, 0, 4, '어둠의 숲에서 길 잃은 작은 양 한 마리 있으니.'),
(49634, 0, 5, '모든 곳, 모든 것에는 영혼이 있다. 모든 영혼은 잡아먹을 수 있다.'),
(49634, 0, 6, '무엇이 사람의 본성을 바꿀 수 있는가?'),
(49634, 0, 7, '별들은 바람을 휩쓸고, 사람들은 어둠 속에서 벌벌 떠네.'),
(49634, 0, 8, '결국 당신은 홀로 남을 것이다.'),
(49634, 0, 9, '당신은 잠자며 꿈을 꾸는 것인가? 아니면 현실의 공포로부터 벗어나는 것인가?'),
(49634, 0, 10, '둘러보라. 그들은 모두 당신을 배신할 것이다. 비명을 지르며 검은 숲으로 도망가라.'),
(49634, 0, 11, '니알로사의 땅에는 오직 잠이 있을 뿐.'),
(49634, 0, 12, '니알로사의 잠자는 도시에는 광기의 존재만이 돌아다닌다.'),
(49634, 0, 13, '니알로사는 오래되고, 끔찍하고, 셀 수 없이 많은 범죄의 도시이다.'),
(49634, 0, 14, '이크나스 크스리그 크이 므르운가 그르물라.'),
(49634, 0, 15, '공허가 당신의 영혼을 빨아들인다. 천천히, 천천히 영혼을 즐기려 한다.'),
(49634, 0, 16, '물에 잠긴 신의 심장은 검은 얼음이다.'),
(49634, 0, 17, '그것은 바로 당신 뒤에 서 있다. 움직이지 마라. 숨 쉬지 마라.'),
(49634, 0, 18, '또 그 꿈을 꾸었는가? 눈이 일곱 개 달린 검은 염소가 밖에서 쳐다보는 꿈을...'),
(49634, 0, 19, '가라앉은 도시에서, 그는 누워 꿈을 꾸고 있다.'),
(49634, 0, 20, '날 열어줘! 날 열어줘! 날 열어줘! 그래야만 당신은 평화를 알 수 있다.'),
(49634, 0, 21, '당신은 저항한다. 당신의 목숨에 의미라도 있는 양 놓질 못하고 있다. 곧 알게 되리라.'),
(49634, 0, 22, '선조의 고통스러운 영혼들이 침묵의 비명을 지르며 당신에게 매달린다. 얼핏 봐도 영혼의 수가 상당히 많다.'),
(49634, 0, 23, '그 물고기들은 비밀을 모두 알고 있다. 그들은 추위를 안다. 그들은 어둠을 안다.'),
(49634, 0, 24, '검은 까마귀가 죽은 나무 위에서 내려다보고 있다. 그 그림자 밑에서는 모든 것이 숨을 멈춘다.'),
(49869, 0, 0, '도와주세요!'),
(49869, 0, 1, '치유가 필요합니다!'),
(49869, 0, 2, '수사님, 저를 치유해 주십시오!'),
(49869, 0, 3, '팩스턴 님, 뭐 하시는 겁니까? 절 좀 치유해 주세요!'),
(49869, 1, 0, '와라, 괴물들아! 우리가 널 짓밟아 주마!'),
(49869, 1, 1, '너희 전투늑대들은 백 마리라도 더 없애주지!'),
(49869, 1, 2, '원기 왕성해 보이는군, 친구들! 사방에 오크들과 늑대들이 있네!'),
(49869, 1, 3, '더러운 네 녀석들만으로는 충분하지 않을 거다!'),
(49869, 1, 4, '너희 늑대 따위는 스톰윈드의 힘에는 상대조차 되지 않는다!'),
(49874, 0, 0, '오크가 $r 죽인다!'),
(49874, 0, 1, '검은바위 부족이 이 숲을 점령할 거다!'),
(49874, 0, 2, '포도가 아주 맛있더군!'),
(49874, 0, 3, '살려달라고 빌어라!'),
(49874, 0, 4, '널 없애버리겠다!'),
(50039, 0, 0, '우린 제값을 받기 위해 누구든 없앨 거다!'),
(50039, 0, 1, '네 친구와 만날 시간이다, 더러운 녀석!'),
(50039, 0, 2, '죽어라!!!'),
(50039, 0, 3, '우린 이곳을 완전히 태워버릴 작정이다!'),
(50047, 0, 0, '영웅이시여, 당신에게 축복이 있기를!'),
(50047, 0, 1, '살아서 다시 열심히 싸울 겁니다!'),
(50047, 0, 2, '전 악을 두려워하지 않을 겁니다!'),
(50047, 0, 3, '저... 전 괜찮아요! 괜찮다고요!'),
(50047, 0, 4, '빛이여, 감사합니다!'),
(50047, 0, 5, '당신은 $n 님이 아니십니까! 모든 이들이 얘기하던 그 영웅! 감사합니다!'),
(50332, 0, 0, '붉은색이 보인다!'),
(50333, 0, 0, '잠자는 황소를 깨웠으니 뿔 맛을 봐라!'),
(50336, 0, 0, '너! 여기서 뭐하는 거냐?'),
(50341, 0, 0, '암흑의 주먹을 맞아 봐라!'),
(50344, 0, 0, '끝이 멀지 않았다.'),
(50347, 0, 0, '암흑이 찾아온다.'),
(50363, 0, 0, '어딜! 나는 여제 폐하께 보고하러 가야 한다!'),
(50364, 0, 0, '집에서 너무 멀리 온 것 아니냐?'),
(50374, 0, 0, '무... 내게 무슨 일이? 내게 왜 이런 짓을 한 거야?'),
(50374, 1, 0, '난 죽었지만, 죽은 채 다시 돌아왔다!'),
(50374, 2, 0, '난 이렇게 되고 싶지 않았어! 날 내버려 둬!'),
(50374, 3, 0, '죽음의 손아귀에서 날 구한 이건 대체 무슨 마법이란 말인가?'),
(50374, 4, 0, '밴시 여왕님이 내게 기회를 주셨으니, 이에 마땅히 응하리라.'),
(50374, 5, 0, '이건 실바나스 여왕님이 한 건가?'),
(50374, 6, 0, '어둠의 여왕님은 날 어디에 쓰시려는 거지?'),
(50374, 7, 0, '기... 기억이 안 나... 왜 내게 이런 짓을?'),
(50374, 8, 0, '%s|1이;가; 스스로 목숨을 끊습니다.'),
(50374, 9, 0, '%s|1이;가; 격노하여 정신없는 좀비로 변한 뒤 달아납니다.'),
(50374, 10, 0, '%s|1이;가; 병영 쪽으로 걸어갑니다.'),
(50414, 0, 0, '가... 감사합니다, 장... 의... 사님.'),
(50415, 0, 0, '당신은 늑대인간에게 물렸습니다. 별일 아닐 수도 있지만, 조금 따끔거리는 것은 확실합니다.$B$B|Tinterface\\Icons\\INV_Misc_monsterfang_02.blp:32|t'),
(50750, 0, 0, '웅덩이가 울렁인다...'),
(50768, 0, 0, '감히 내 명상을 방해해? 대가를 치르게 해 주지...'),
(50780, 0, 0, '우르릉거리는 심연이 너를 부른다...'),
(50782, 0, 0, '죽어라!'),
(50783, 0, 0, '푹푹푹푹푹!'),
(50791, 0, 0, '네 피부로 모자를 만들 테다!'),
(50805, 0, 0, '안 돼! 내 금덩어리!'),
(50811, 0, 0, '내 마음 속의 어둠... 모두 너 때문이다!'),
(50816, 0, 0, '눈앞이 흐릿하다. 왜 우리에게 이런 짓을 했느냐?'),
(50820, 0, 0, '나는 분노에 굴해야 한다! 그 수밖에 없다!'),
(50822, 0, 0, '내 혼에 깃든 어둠이 내보내 달라며 소리를 지른다!'),
(50830, 0, 0, '먹을 거 내놔!'),
(50831, 0, 0, '너 우낏 때려 준다!'),
(50832, 0, 0, '넌 머리에 응가만 들었지!'),
(51078, 0, 0, '너를 뭉개서 꽃 거름으로 만들어 주마!'),
(51277, 0, 0, '%s|1이;가; 광란 상태에 빠집니다!'),
(51712, 0, 0, '%s|1이;가; 격노합니다!'),
(52053, 0, 0, '뭐야? 너도 잔질을 놀리려고 왔어? 그렇겐 안 돼! 복수하겠어!'),
(52053, 1, 0, '너희는 벌을 받을 거야! 잔질이 줄구룹에 얼... 얼마나... 필요...'),
(52053, 2, 0, '하하하하!'),
(52053, 2, 1, '깊게 들이마셔, 친구! 싹 다 들이마시라고!'),
(52053, 3, 0, '걱정 마. 잔질이 널 좋은 데 쓸 테니까...'),
(52053, 3, 1, '맛이 어떠냐?'),
(52053, 3, 2, '오, 예쁜 것... 잔질이 널 특별한 데 써 줄 거야...'),
(52053, 4, 0, '좀 더 큰 친구랑 놀고 싶지, 응?'),
(52053, 4, 1, '꼬마야, 가거라! 가서 싸워! 놈들을 없애!'),
(52053, 5, 0, '친구가 없으면 어때? 잔질처럼 이렇게 만들면 되는데!'),
(52053, 5, 1, '일어나라! 잔질이 너희에게 생명을 주마!'),
(52077, 0, 0, '%s|1이;가; 당신을 쫓습니다! 도망가세요!'),
(52077, 1, 0, '%s|1이;가; $n|1을;를; 쫓습니다!'),
(52148, 0, 0, '멋진 축제에 잘 왔어, 친구. 특별히 준비한 게 있으니, 조금만 기다리라고.'),
(52148, 1, 0, '안 돼... 안 돼!!!'),
(52148, 2, 0, '누가 진도를 막을쏘냐!'),
(52148, 2, 1, '누가 진도를 막을쏘냐!'),
(52148, 3, 0, '싱거운 놈!'),
(52148, 3, 1, '싱거운 놈!'),
(52148, 4, 0, '어이! 축하해!'),
(52148, 5, 0, '자, 이제 나 진도의 진정한 힘을 보여 주마!'),
(52148, 6, 0, '성가신 버러지들! 자, 이제 내 분노를 느껴 봐라!'),
(52150, 0, 0, '안 돼... 안 돼!!!'),
(52151, 0, 0, '칼을 버려라, 벌레들아. 내가 너희를 학카르 님께 데려간다!'),
(52151, 1, 0, '하하하! 그게 최선이냐?'),
(52151, 1, 1, '내 앞에 무릎 꿇어라. 여기 혈군주 만도키르 님 앞에!'),
(52151, 1, 2, '너의 부서진 몸은 학카르 님의 것이다.'),
(52151, 2, 0, '가서 물어, 오간! 똑같이 당하지 않는다!'),
(52151, 3, 0, '|TInterface\\Icons\\ability_heroicleap.blp:20|t %s|1이;가; |cFFFF0000|Hspell:96740|h[황폐의 격돌]|h|r을 시전합니다!'),
(52151, 4, 0, '일어나, 오간! 일어나 주인을 위해 싸워라!'),
(52151, 5, 0, '머리를 내놔라!'),
(52151, 6, 0, '머리를 내놔라!'),
(52151, 7, 0, '내 피를 학카르 님께! 내... 영혼을... 진도 님께!'),
(52155, 0, 0, '하찮은 것이 겁도 없이 구루바시의 계획을 방해했겠다? 이젠 너무 늦었다. 너무 늦었다고. 너흰 모두 끝이야!'),
(52155, 1, 0, '죽음의 똬리가 너희를 휘감으리라!'),
(52155, 2, 0, '자, 이제... 독 앞에 무릎 꿇어라...'),
(52155, 3, 0, '뱀의 소리가 나를 채우도다. 나의 몸엔 독이 흐르나니, 뱀 신의 영광을 온몸으로 맞이하거라.'),
(52155, 4, 0, '생명의 똬리가 풀리는구나...'),
(52155, 4, 1, '너희를 제물로 바쳐 그분을 기쁘게 하리라.'),
(52155, 5, 0, '내가 죽는다고... 달라지는 건... 없다...'),
(52171, 0, 0, '풀과 모래, 그리고 진흙 혼합물이 한데 섞인 곳에 희미한 발자국이 찍혀 있습니다.'),
(52171, 0, 1, '생물체가 발을 질질 끈 것 같은 흔적이 질척하게 나 있습니다.'),
(52171, 0, 2, '진흙과 함께 섞인 것은 근처 시설에서 나온 기름투성이 흔적입니다.'),
(52171, 0, 3, '흔적에 핏자국이 보입니다. 당신은 괴생물체가 최근에 잡아먹은 먹잇감의 시체가 있는 곳을 따라 근처의 덤불로 갑니다.'),
(52171, 0, 4, '이 흔적은 생긴 지 얼마 되지 않았으며, 물속으로 이어집니다...'),
(52201, 0, 0, '로켓 발사 3초 전...'),
(52201, 1, 0, '로켓 발사 2초 전...'),
(52201, 2, 0, '로켓 발사 1초 전...'),
(52201, 3, 0, '발사!'),
(52204, 0, 0, '우와, 우와, 우와! 스퍼터밸브가 이걸 몰게 해 주다니 믿을 수가 없어! 내가 날아보는 건 처음이라고 말은 했던가? 그래도 걱정하지 말라고. 내가 다 알아서 할 테니까 말이야.'),
(52204, 1, 0, '이야... 저 멋진 경치 좀 보라고! 저게 사자던가? 아이고, 운전대 놓칠 뻔했네.'),
(52204, 2, 0, '내 꿈은 언젠가 스퍼터밸브만큼 똑똑해지는 거라고. 그 친구의 바퀴 두 개 달린 세발자전거 설계도를 봤어야 하는데!'),
(52204, 3, 0, '자, 다 왔군. 십자로로 무사히 돌아왔다고.'),
(52204, 4, 0, '응? 잠깐 기다려봐. 엔진이 멈췄네...'),
(52204, 5, 0, '우왓! 뭐야?'),
(52204, 6, 0, '아니야, 아니야, 아니야... 이러면 안 돼. 이건 여행 계획에 없던 거라고!'),
(52204, 7, 0, '우우웃! 이거 예상치 못한 곳으로 돌아가는 것 같은데! 꽉 잡으라고!'),
(52204, 8, 0, '이 녹색 단추를 누르면 되나 봐. 아냐, 이 파란색 단추는 어떨까? 잠깐만 기다리라고, 이 전선 좀 다시 이어볼게. 아야!'),
(52222, 0, 0, '가거라, 벌레들아. 네놈들은 나중에 처리해 주겠다.'),
(52222, 1, 0, '너는 넘어서는 안 될 선을 넘었다, 진도. 감당하지도 못할 힘으로 장난을 치다니. 너는 내가 누군지 잊었느냐? 너는 내가 가진 힘을 잊었느냐?!'),
(52222, 2, 0, '너의 속임수는 용납할 수 없다, 진도. 감히 대놓고 신을 모욕하다니!'),
(52258, 0, 0, '날 찾았나? 한판 싸워 보자!'),
(52258, 1, 0, '그리렉의 방랑은... 끝났다...'),
(52258, 2, 0, '내가 간다, 이 꼬맹이 놈아!'),
(52258, 2, 1, '잡고 말 테다, 이 꼬맹아!'),
(52258, 3, 0, '패배자!'),
(52258, 3, 1, '약해빠진 놈!'),
(52258, 4, 0, '겁쟁이! 도망칠 수 없다!'),
(52258, 4, 1, '안 돼! 넌 구루바시의 분노를 벗어날 수 없어!'),
(52258, 5, 0, '%s|1이;가; 당신을 쫓습니다! 도망가세요!'),
(52269, 0, 0, '살을 베는 폭풍이 간다!'),
(52269, 0, 1, '폭풍칼날!'),
(52269, 1, 0, '아... 오늘 새로운 칼 한 자루를 또 수집하겠군...'),
(52269, 2, 0, '아... 천 번의 살육에도 내 영혼이 쉴 곳은 없었거늘...'),
(52269, 3, 0, '신속하게 목을 공략하면, 백이면 백 이렇게 쓰러지지.'),
(52269, 3, 1, '주제를 알라고!'),
(52269, 4, 0, '한 번 푹 찔러 주면 어깨에 긴장이 좀 풀릴 거야...'),
(52269, 4, 1, '도적은 뒤를 치지...'),
(52269, 4, 2, '처음에만 이렇게 아픈 거야. 다음번엔 저세상에 있을 테니.'),
(52271, 0, 0, '오늘, 잠에서 깨어난 걸 뼈저리게 후회하게 해 주마!'),
(52271, 1, 0, '이제 내 영혼은 꿈꾸지 않으리...'),
(52271, 2, 0, '너희의 악몽에 어떤 공포가 도사리는지 볼까?'),
(52271, 2, 1, '어떤 게 더 끔찍할까?... 영영 꿈속을 헤매는 것, 아니면 악몽 같은 현실을 사는 것?'),
(52271, 2, 2, '잠들어라... 또 다른 꿈이 너희를 기다린다...'),
(52271, 3, 0, '불쌍한 것. 이제는 꿈을 꾸지 않겠지...'),
(52271, 3, 1, '그래, 그렇게... 눈을 감는 거야...'),
(52271, 4, 0, '악몽의 환영을 공격하고 잠자는 아군을 보호하십시오!'),
(52286, 0, 0, '내 고향 땅 침범한 걸 후회하게 해 주마!'),
(52286, 1, 0, '우리 제국의 몰락은... 위대한 시작일 뿐이다...'),
(52286, 2, 0, '충격적이지? 그럴 거다.'),
(52286, 2, 1, '폭풍의 힘을 느껴라!'),
(52286, 3, 0, '찌릿찌릿함이 느껴지나? 그게 너의 마지막 느낌이야.'),
(52286, 3, 1, '너무 짜릿해 말이 안 나오지?'),
(52286, 4, 0, '번개보다 빨리 움직일 수 있을까?'),
(52286, 4, 1, '눈 깜짝하면, 넌 그냥 먼지가 되는 거야...'),
(52286, 4, 2, '폭풍이여, 힘을 주소서!'),
(52286, 5, 0, '곧 %s의 번개 공격이 시작됩니다! 피해야 합니다!'),
(52321, 1, 0, '그렇단다, 꼬마야. 그분께선 백성의 안전을 위해 고대의 티탄 의식을 수행하셨지만, 결과는 이렇게 되고 말았지.'),
(52321, 2, 0, '고맙다, 꼬마야.'),
(52325, 0, 0, '%s|1이;가; 격노합니다!'),
(52381, 0, 0, '트쿨루가 죽자 가마솥을 보호하던 힘이 사라집니다!'),
(52405, 0, 0, '%s|1이;가; 분노에 휩싸입니다!'),
(52409, 0, 0, '나오너라, 나의 부하들아! 주인을 보호해라!'),
(52409, 0, 1, '불의 하수인들아! 침입자를 불태워라!'),
(52409, 0, 2, '화염의 피조물이여, 나에게 오라!'),
(52409, 0, 3, '일어나라, 불의 하수인들아. 저들의 살을 먹어치워라!'),
(52409, 1, 0, '벌레 같은 놈들! 감히 내 영역을 침범해? 네놈들의 오만함을 살아있는 불꽃으로 녹여 주마.'),
(52409, 2, 0, '안 돼, 안 돼... 승리는 나의 것이었거늘...'),
(52409, 3, 0, '조금만!... 조금만 시간이 더 있었어도...'),
(52409, 4, 0, '으스러뜨려 주마!'),
(52409, 4, 1, '죽어라!'),
(52409, 4, 2, '심판의 시간이 왔노라!'),
(52409, 5, 0, '여기까지! 이제 끝내주마.'),
(52409, 5, 1, '무릎 꿇어라, 필멸자여! 끝낼 시간이다.'),
(52409, 5, 2, '설퍼라스로 숨통을 끊어 주마.'),
(52409, 6, 0, '이것만 끝나면, 하찮은 네놈들의 세계는 나의 복수로 불탈 것이다!'),
(52409, 7, 0, '으으으, 이방인들아, 여긴 너희 영역이 아니다!'),
(52409, 8, 0, '너무 일러...'),
(52409, 9, 0, '여긴 나의 영역이다!'),
(52409, 9, 1, '불쌍한 놈.'),
(52409, 9, 2, '죽어라, 벌레야!'),
(52409, 10, 0, '불의 세례를 받아라!'),
(52409, 11, 0, '데스윙께서 타렉고사의 정수를 상대할 방법을 가르쳐 주셨다. 네놈들의 어리석은 여정도 여기서 끝이다!'),
(52409, 12, 0, '내 영역에서 꺼져라, 벌레들아.'),
(52409, 12, 1, '한 놈도 빠짐없이 불태우겠다.'),
(52409, 12, 2, '화염의 먹이가 되어라!'),
(52409, 12, 3, '불의 세계가 네놈들을 집어삼키리라!'),
(52438, 0, 0, '올라가라.'),
(52440, 0, 0, '%s|1이;가; 분노에 휩싸입니다!'),
(52558, 0, 0, '뭐, 뭐야... 어? 작고 물렁한 살덩이들? 여기에? 성가시군, 성가셔!'),
(52558, 1, 0, '오오, 이것 봐라.'),
(52558, 1, 1, '으아아!'),
(52558, 1, 2, '으아, 이 물렁하고 조그만 놈들, 이거 어떻게 할 거냐!'),
(52558, 1, 3, '으으으 이 녀석들... 화를 돋구는구나!'),
(52558, 1, 4, '으, 이 조그만 것들이...'),
(52558, 2, 0, '부서졌어... 으으으으... 부서졌어...'),
(52558, 3, 0, '끝났다.'),
(52558, 3, 1, '너무 물러!'),
(52558, 3, 2, '찍 소리도 못 하는 것들이.'),
(52558, 4, 0, '불타라!'),
(52558, 4, 1, '살아 있는 불길에 무릎 꿇어라.'),
(52558, 4, 2, '내 안의 불길은 꺼지지 않는다.'),
(52558, 4, 3, '집어삼켜라...'),
(52558, 4, 4, '살은... 불타리라!'),
(52558, 5, 0, '밟아 버린다!'),
(52558, 5, 1, '발로 짓눌러 주마!'),
(52558, 6, 0, '긴 세월 내 잠을 방해한 이가 없었건만... 그래... 이 살덩어리들아. 네놈들을 불태워 주마!'),
(52571, 0, 0, '주인님의 힘은 여러 모습으로 발현된다...'),
(52571, 1, 0, '보아라! 불의 땅이 포효하는 모습을!'),
(52571, 2, 0, '영광의 불꽃이여!'),
(52571, 3, 0, '재가 되어 사라져라!'),
(52571, 4, 0, '내 연구들... 이제 겨우 시작이거늘...'),
(52571, 5, 0, '힘이 넘치도다!'),
(52571, 6, 0, '타올라라.'),
(52571, 6, 1, '곧 아제로스 전체가 불타리라!'),
(52571, 6, 2, '불길을 막아선 대가다!'),
(52606, 0, 0, '%s|1이;가; 격노합니다!'),
(52650, 0, 0, '가거라, 벌레들아. 네놈들은 나중에 처리해 주겠다.'),
(52924, 0, 0, '날 따라오게, $c. 문을 열려면 두 명이 있어야 하니까.'),
(52924, 1, 0, '둘이서 함께 징을 치는 것이 바로 문을 여는 의식이라네.'),
(52924, 2, 0, '잘 들어라, 음흉한 잔달라 놈들아... 네놈들이 아마니 부족을 지배하는 걸 막으러 검은창 부족이 동맹을 이끌고 왔다!'),
(52924, 3, 0, '아마니 놈들은 우리가 여기 왔음을 아네. 어서 공격을 시작하지!'),
(52924, 4, 0, '아직 준비가 안 됐나 보군. 문을 열고 싶거든 내게 다시 이야기하게.'),
(52939, 0, 0, '트롤곰은 처치하셨습니까, 친구? 저 이제 돌아가도 괜찮은 겁니까?'),
(52939, 1, 0, '거기 누구 없습니까? 하즐렉 목소리 안 들립니까?'),
(52939, 2, 0, '이봐요! 하즐렉이 여기 있단 걸 잊지 말아 주세요.'),
(52939, 3, 0, '이딴 자물쇠는 눈 감고도 열 수 있습니다. 그냥 언제 탈출하면 되는지만 좀 알려 주세요.'),
(52941, 0, 0, '절 잊지 마십시오!'),
(52941, 1, 0, '다시 자유의 몸이 되니 정말 좋군요!'),
(52941, 2, 0, '제가 발견한 게 있는데, 잠깐만 기다리십시오. 그 가방이 어디 있더라...?'),
(52941, 3, 0, '자, 당신이 가지십시오. 정찰병이 그렇게 무거운 걸 가지고 돌아다녔다간 죽기 딱 좋죠.'),
(52943, 4, 0, '물러나 있는 게 좋을 거요...'),
(52956, 0, 0, '잔달라의 고대 영혼이여, 저들에게 어둠의 길을 보여주소서.'),
(52956, 0, 1, '잔달라의 고대 영혼이여, 저에게 죽음도 조롱할 힘을 허락하소서!'),
(52958, 0, 0, '잔달라의 고대 영혼이여, 저들에게 어둠의 길을 보여주소서.'),
(52958, 0, 1, '잔달라의 고대 영혼이여, 저에게 죽음도 조롱할 힘을 허락하소서!'),
(52962, 0, 0, '잔달라의 고대 영혼이여, 저들에게 어둠의 길을 보여주소서.'),
(52962, 0, 1, '잔달라의 고대 영혼이여, 저에게 죽음도 조롱할 힘을 허락하소서!'),
(53375, 0, 0, '불의 땅의 분노를 벗어날 순 없다!'),
(53392, 0, 0, '어서 오십시오. 기다리고 있었습니다.'),
(53392, 1, 0, '당신은 불의 땅에서 눈부신 활약을 펼쳤습니다.'),
(53392, 2, 0, '허나 그냥 칭찬으론 부족합니다.'),
(53392, 3, 0, '당신 덕분에 우리 용군단의 운명을 바로잡을 수 있었습니다.'),
(53392, 4, 0, '지팡이를 주십시오. 그것에 엄청난 힘을 불어넣겠습니다.'),
(53392, 5, 0, '마침내, 당신이 소중히 품어 주신 사랑하는 우리의 누이 타렉고사가... 이 지팡이를 자신의 영원한 보금자리로 선택했습니다.'),
(53392, 6, 0, '부디 그녀가 당신에게 힘을 주는 든든한 벗이 되길.'),
(53392, 7, 0, '감사합니다, 푸른용군단의 친구여.'),
(53494, 0, 0, '너희 필멸자들은 주인님의 땅에 들어올 수 없다.'),
(53494, 1, 0, '더러운 필멸자들아... 주인님의 요새는 금지된 곳이다...'),
(53494, 2, 0, '어리석은 것들. 제 발로 무덤에 걸어 들어오다니!'),
(53494, 3, 0, '불의 군주님의 명을 받들어 네놈 역시 멸하리라!'),
(53494, 4, 0, '심판을 내렸노라.'),
(53494, 4, 1, '너의 나약함을 보아라.'),
(53494, 4, 2, '아무도 지나갈 수 없다.'),
(53494, 5, 0, '너의 몸뚱이는 불의 땅이 접수하겠다.'),
(53494, 6, 0, '이글거리는 나의 분노로 불살라 주마!'),
(53565, 0, 0, '신입치고는 대단한 실력인걸.'),
(53565, 0, 1, '수련 기구 따위, 당신 상대가 안 되던걸.'),
(53565, 0, 2, '언젠가 꼭 내게도 비결을 가르쳐 줘.'),
(53565, 0, 3, '큰 인물이 되겠군요, 수련생.'),
(53565, 0, 4, '당신처럼 될 수 있게 더 열심히 수련해야겠소.'),
(53565, 0, 5, '사부들이 봤어야 하는데!'),
(53565, 0, 6, '당신만큼 열심히 수련해야겠소.'),
(53565, 0, 7, '흠잡을 데 없는 자세야.'),
(53565, 1, 0, '난 램한테 걸래. 지난주 대련할 때 추를 꺾는 거 봤어?'),
(53565, 2, 0, '그래 봤자 램의 힘에 대면 아무것도 아니지.'),
(53565, 3, 0, '녀석은 다리가 황소 다리야! 대련할 때 걷어차인 적 있어?'),
(53565, 4, 0, '폭풍절규 황금 맥주 한 통을 걸지. 거절하면 자네 손해야.'),
(53565, 5, 0, '그건 네 착각이지. 조우는 떡갈나무처럼 튼튼하다고.'),
(53565, 6, 0, '조우는 체력이 세 사람분이야. 웬만한 적은 상대가 안 된다고.'),
(53565, 7, 0, '조우한테 4 코퍼.'),
(53566, 0, 0, '한 번에 해내다니! 자, 불꽃을 사원 꼭대기로 가져가서 그곳에 있는 두루마리를 태우게.'),
(53590, 0, 0, '야호! 실바나스를 처치하러 내가 왔다!'),
(53590, 0, 1, '오, 이것 봐라. 여긴 사람 많네. 우리 나이트 엘프가 사는 나무 도시랑은 딴판이군.'),
(53590, 0, 2, '겨울손아귀에서 자꾸 져서 매우 화가 나는군! 보복으로 네놈들의 강력한 지도자, 실바나스를 처치하... 려고 노력은 해 보겠다!'),
(53590, 0, 3, '우리에게서 톨 바라드를 빼앗은 대가를 치르게 해주마! 이 위대한 도시를 쓸어버... 리려고 노력은 해 보겠다! 벌벌 떨어라! 내가 전투 함성을 기억하려고 애쓰는 동안!'),
(53590, 0, 4, '강대하기 그지없는 호드의 용사들이여, 벌벌 떨어라! 얼라이언스가 왔다!'),
(53590, 0, 5, '여기가 어디지? 엑소다르가 추락한 것까진 기억나는데, 어쩌다가 이렇게 웅장한 도시에 오게 된 거지...'),
(53590, 0, 6, '아, 나처럼 작고 애처로운 노움에게 이 도시는 너무나도 커...'),
(53590, 0, 7, '그래, 나 좀 마셨다. 드워프가 다 그렇지, 뭐. 한참 동안 땅굴 파고 올라왔더니 여기군. 한잔하고 싶은 사람?'),
(53619, 0, 0, '뜨거운 화염 앞에 무릎 꿇어라!'),
(53691, 0, 0, '아하! 침입자들이군! 해치워라. 먹어 버려!'),
(53691, 1, 0, '아... 아파. 불의 군주님... 너무 아파...'),
(53691, 2, 0, '가서 먹이 물어와!'),
(53691, 3, 0, '저기 숨통을 노려!'),
(53691, 4, 0, '칼로베! 안 돼, 안 돼! 이 짐승만도 못한 놈들아, 세상에 어떻게?'),
(53691, 5, 0, '오, 이 악마 같은 놈들! 왜? 이렇게 고귀한 동물을 도대체 왜!'),
(53691, 6, 0, '이제 불태워 주마.'),
(53691, 6, 1, '불속에서 뒹굴어라, 침입자들아!'),
(53691, 7, 0, '아가야, 밥 먹자!'),
(53691, 7, 1, '영원히 누워 있어라.'),
(53691, 7, 2, '불의 군주님이 무척 기뻐하시겠는걸.'),
(53691, 8, 0, '그래, 나도 냄새가 나, 칼로베. 외부인이 불의 군주님의 땅에 침입했어. 흔적을 쫓아라. 놈들을 찾아서, 벌을 내리는 거야!'),
(53734, 0, 0, '불의 군주시여, 우리에게 힘을 내리소서!'),
(53772, 2, 0, '부서졌어... 으으으으... 부서졌어...'),
(53772, 3, 0, '끝났다.'),
(53772, 3, 1, '너무 물러!'),
(53772, 3, 2, '찍 소리도 못 하는 것들이.'),
(53772, 5, 0, '밟아 버린다!'),
(53772, 5, 1, '발로 짓눌러 주마!'),
(53795, 0, 0, '녹아내린 알에 금이 가며 쪼개지기 시작합니다!'),
(53872, 0, 0, '라그나로스는 사라졌으나, 그를 따랐던 원초적인 세력까지 모두 없어지진 않았다. 누군가 또 나타날 것이다.'),
(53872, 1, 0, '아니, 심판의 시간은 바로 지금이다.'),
(53872, 2, 0, '아마도...'),
(53872, 3, 0, '그러자꾸나.'),
(53875, 0, 0, '영웅들이여! 그를 속박했다. 끝을 내라!'),
(53875, 1, 0, '이제 끝났다!'),
(53875, 2, 0, '영웅들이여, 또 한 번 세상을 구했구나.'),
(53876, 0, 0, '그렇습니다, 세나리우스 님. 이 땅에서 결코 경계를 늦춰서는 안 될 것입니다. 하지만 오늘만큼은 우리의 위대한 승리를 축하했으면 합니다.'),
(53879, 0, 0, '%s|1이;가; 왼쪽 등에 플레이어들이 있음을 감지합니다.\n데스윙이 왼쪽으로 회전하려고 합니다!'),
(53879, 1, 0, '%s|1이;가; 오른쪽 등에 플레이어들이 있음을 감지합니다.\n데스윙이 오른쪽으로 회전하려고 합니다!'),
(53879, 2, 0, '%s|1이;가; 왼쪽으로 회전합니다!'),
(53879, 3, 0, '%s|1이;가; 오른쪽으로 회전합니다!'),
(53879, 4, 0, '끈기 하나는 인정해 줘야겠군. 하지만 무의미하다. 너희들을 파멸의 도가니에 처넣어주마!'),
(53879, 4, 1, '넌 먼지만도 못하다. 내 등에서 쓸어내면 그만인 것들.'),
(53879, 4, 2, '하! 멍청한 놈들, 아직 거기 붙어 있는지도 몰랐다.'),
(53879, 4, 3, '버둥거리는 꼴이 가소롭군. 내 너희를 황천으로 인도해주마.'),
(53890, 0, 0, '|TInterface\\Icons\\inv_gizmo_supersappercharge.blp:20|t%s|1이;가; |c0087CEFA|Hspell:105845|h[핵폭발]|h|r을 시전합니다!'),
(53896, 0, 0, '그분의 힘을 보아라!'),
(53896, 0, 2, '불의 군주시여, 힘을 주소서!'),
(53896, 0, 3, '화염의 장엄함을 지켜봐라!'),
(53991, 0, 0, '목소리 좀 낮춰주게, 응? 장사 좀 하자고...'),
(53991, 1, 0, '그 상자 어쩌고저쩌고하는 일을 없던 일로 해준다면, 내가 울둠에서 막 도착한 물건들을 싸게 내주지.'),
(53991, 2, 0, '알았네, 알았어. 내가 그자에게 상자 안에 든 물건에 관심을 보일법한 개인 수집가의 이름을 알려준 것 같기도 하군.'),
(54015, 0, 0, '이게 누구신가? 우리 불의 땅에 손님들이 찾아오셨군.'),
(54015, 1, 0, '알리스라를 기억할지 모르겠군. 하이잘 산에서 나를 풀어 줬지. 그녀도 다시 태어났다... 화염의 존재로!'),
(54015, 2, 0, '그녀가 너희를 잿더미로 만드는 모습을 지켜보고 싶지만, 급히 갈 곳이 있어서 말이야. 잘 있으라고!'),
(54021, 0, 0, '자꾸 질문을 피하지 마십시오, 퀸시! 상자를 훔친 그자가 여기 온 적이 있다는 사실을 다 알고 있습니다.'),
(54021, 1, 0, '그 상자 안에 든 물건은 아주 위험합니다. 무식하고 돈만 많은 수집가의 손이 아니라 튼튼한 금고 안에 보관되어야 할 물건이란 말입니다!'),
(54021, 2, 0, '경비병이 찾아오면 저기 있는 울둠 유물이나 훌륭한 그림을 어떻게 얻었는지 잘 설명할 자신이 있으신가 보군요?'),
(54021, 3, 0, '이제야 실토하시는군요. 거기 새로 오신 분, 어떻습니까? 당신도 역시 그 상자를 찾는 중이니 이곳으로 온 걸 텐데요.'),
(54067, 0, 0, '고맙습니다, $p! 저를 많이 도와주셨다고 아빠한테 말씀드릴게요!'),
(54067, 0, 1, '정말 대단해요!'),
(54067, 0, 2, '우와!'),
(54067, 0, 3, '최고예요, $p!'),
(54072, 0, 0, '대마법사 실렘 님은 깡패와는 거래하지 않으신다. 너 따위에게 돈을 줄 것 같으냐!'),
(54072, 1, 0, '뭐야, 침입자잖아? 어디, 이 상자 안에 든 유물에 어떤 힘이 있는지 볼까?'),
(54072, 2, 0, '이렇게 될 리가 없는데!'),
(54130, 0, 0, '조심해! 녀석의 친구가 오고 있어!'),
(54130, 1, 0, '도망치자!'),
(54135, 0, 0, '자네는 지나갈 자격을 얻었네. 후오는 안쪽에 있다네.'),
(54146, 0, 0, '모르는 척 해봤자 소용없다, 드란! 그 도둑은 분명히 훔친 물건을 어디로 가져가야 하는지 알고 있었단 말이야.'),
(54146, 1, 0, '도난당한 유물을 보면 그런트가 뭐라고 할지 한번 볼까?'),
(54146, 2, 0, '이제야 말이 통하는군...'),
(54146, 3, 0, '그리고, 그대는 왜 이 물건에 관심을 보이는 건가? 이야기 좀 해 보시오...'),
(54404, 0, 0, '좋다, $n.'),
(54404, 1, 0, '건방진 젖먹이! 죽고 싶어 안달이구나! 자, 보아라. 주인님께서 일어나신다!'),
(54404, 2, 0, '보라! 불의 군주 라그나로스 님을! 태초부터 존재하셨던 분이다. 경배하라! 최후를 맞기 전 그분 앞에 무릎을 꿇어라!'),
(54404, 3, 0, '주인님! 저 필멸의 이단자들이 감히 주인님의 성소에 침입해 비밀을 훔치려 했나이다!'),
(54431, 0, 0, '너희가 이곳에 어떤 사악한 기운을 풀어놓았는지는 아느냐? 조상님의 명예를 걸고 널 벌하겠다!'),
(54431, 1, 0, '여긴... 어디인가? 내가 무슨 짓을? 아버님, 저를 용서하십시오...'),
(54431, 2, 0, '너! 너희가 여기 일어난 일의 원흉인가...?'),
(54431, 3, 0, '드디어 죗값을 치렀구나!'),
(54431, 3, 1, '내 심판을 받아라!'),
(54431, 3, 2, '오만함의 대가를 치뤄라!'),
(54431, 4, 0, '도망칠 곳은 없다!'),
(54431, 4, 1, '내 분노에는 끝이 없다!'),
(54432, 0, 0, '어쩔 수 없지.'),
(54432, 1, 0, '넌 네가 무슨 짓을 저지르는지 모른다. 아만툴... 내가... 본... 것은...'),
(54432, 2, 0, '내게 모래시계의 힘은 무의미하다!'),
(54432, 3, 0, '같은 행동에 다른 결과를 바란다니 어리석군.'),
(54432, 4, 0, '한 번 더 기회가 와도 결과는 마찬가지야. 날 막진 못해.'),
(54432, 5, 0, '하! 이게 네 작전이냐, 네 계획이냐?'),
(54432, 6, 0, '모래시계의 힘이 떨어졌다. 장난은 끝이다, 필멸자여. 포기해라. 아니면 죽어라.'),
(54432, 7, 0, '"시간의 끝", 난 한때 이곳을 그렇게 불렀다. 그때는 알지 못했다. 보지 못했지. 그런데 뭐? 여기서 날 막겠다고? 내가 이리 힘들게 일궈놓은 운명을?'),
(54432, 8, 0, '장님처럼, 꿈틀대는 벌레처럼, 끝없는 광기와 절망을 향해 기어가는 너흰 알지 못한다. 난 진정한 시간의 끝을 목격했다. 이거? 이건 축복이다. 네놈들은 이해할 수 없겠지만.'),
(54432, 9, 0, '최후의 시간이다.'),
(54432, 9, 1, '모래의 흐름이 멈췄다.'),
(54432, 9, 2, '시간은 끝났다.'),
(54485, 0, 0, '자, 거기 $c님! 느릿느릿하게 움직이는 거북이 등에 고리를 던져 놓을 수 있으시겠습니까?'),
(54485, 0, 1, '단순한 분들을 위한 단순한 게임입니다. 한번 해보시겠습니까?'),
(54485, 0, 2, '고리를 던져서 상품을 얻으십시오!'),
(54485, 0, 3, '팔뚝이 참 튼실해 보이는군요. 이 게임 좀 해보시겠습니까?'),
(54543, 0, 0, '%s|1이;가; 격노합니다!'),
(54544, 2, 0, '|TInterface\\Icons\\ability_druid_lunarguidance.blp:20|t티란데가 |cFFFF0000|Hspell:102472|h[달의 인도]|h|r를 얻습니다!'),
(54544, 5, 0, '|TInterface\\Icons\\ability_druid_starfall.blp:20|t하늘에서 |cFFFF0000|Hspell:102241|h[엘룬의 눈물]|h|r이 떨어집니다!'),
(54544, 15, 0, '달빛이 비칩니다!'),
(54544, 16, 0, '서쪽에 달빛이 비칩니다!'),
(54544, 17, 0, '남쪽에 달빛이 비칩니다!'),
(54544, 18, 0, '동쪽에 달빛이 비칩니다!'),
(54544, 19, 0, '북쪽에 달빛이 비칩니다!'),
(54544, 20, 0, '근처에 어두운 달빛이 비칩니다!'),
(54544, 21, 0, '달빛이 어둠 속으로 사라집니다!'),
(54548, 0, 0, '영웅들이여, 용의 영혼을 손에 넣었네. 위상들이 고룡쉼터에서 기다리고 있어. 어서... 날 따라오게!'),
(54548, 1, 0, '발각됐군! 싸울 준비를 하게. 이 협곡을 벗어나야 해!'),
(54548, 2, 0, '이건 무슨 조화지?'),
(54548, 3, 0, '조심하게!'),
(54548, 4, 0, '잠시 쉬면서 숨 좀 돌리게. 곧 출발할 테니.'),
(54568, 0, 0, '이거나 먹어라, 원숭아!'),
(54586, 0, 0, '당신만큼 출중한 수련생은 처음 봅니다. 다른 이들에게도 이야기해야겠습니다.'),
(54586, 0, 1, '당신 실력에 미치려면 아직 멀었군. 패배를 인정하겠소.'),
(54586, 0, 2, '고맙습니다. 더욱 부지런히 수련하기로 다짐하는 계기가 됐습니다.'),
(54586, 0, 3, '좋은 싸움이었소. 고맙소.'),
(54586, 0, 4, '당신은 훌륭한 대련 상대군요.'),
(54586, 0, 5, '명예롭게 싸우는군요, 친구.'),
(54586, 0, 6, '잘 싸우셨습니다. 나중에 또 한 수 가르쳐 주십시오.'),
(54586, 0, 7, '실력이 대단하오. 졌소.'),
(54587, 0, 0, '당신만큼 출중한 수련생은 처음 봅니다. 다른 이들에게도 이야기해야겠습니다.'),
(54587, 0, 1, '당신 실력에 미치려면 아직 멀었군. 패배를 인정하겠소.'),
(54587, 0, 2, '고맙습니다. 더욱 부지런히 수련하기로 다짐하는 계기가 됐습니다.'),
(54587, 0, 3, '좋은 싸움이었소. 고맙소.'),
(54587, 0, 4, '당신은 훌륭한 대련 상대군요.'),
(54587, 0, 5, '명예롭게 싸우는군요, 친구.'),
(54587, 0, 6, '잘 싸우셨습니다. 나중에 또 한 수 가르쳐 주십시오.'),
(54587, 0, 7, '실력이 대단하오. 졌소.'),
(54590, 0, 0, '넌 하찮은 필멸자일 뿐. 필멸자답게 황천에나 떨어져라.'),
(54590, 1, 0, '넌 못 해! 못 해...'),
(54590, 2, 0, '황혼의 시간이 다가온다. 모든 것의 끝. 넌 막지 못한다. 넌 못 해. 못 해!'),
(54590, 3, 0, '하찮은 필멸자들.'),
(54590, 3, 1, '저 주술사는 너흴 보호하지 못한다.'),
(54590, 3, 2, '위상들이 엉뚱한 녀석을 믿었군.'),
(54590, 4, 0, '여기까지다, 주술사여!'),
(54590, 4, 1, '아무도 살아남지 못한다!'),
(54590, 4, 2, '주술사는 내 몫이다. 놈의 동료들을 집중 공격해!'),
(54590, 4, 3, '얼어붙어라!'),
(54590, 5, 0, '주술사여! 용의 영혼은 네 것이 아니다. 포기해라. 그러면 목숨만은 건져서 돌아갈 수 있을 거다.'),
(54590, 6, 0, '모두 처치해라. 하지만 주술사는 산 채로 데려와야 한다!'),
(54590, 7, 0, '넌 독 안에 든 쥐다, 주술사여.'),
(54590, 8, 0, '감히 대지의 위상 자리를 이어받을 생각을 하다니, 어리석구나, 주술사여!'),
(54596, 0, 0, '와! 내가 뼈를 찾았어! 이것 좀 봐!'),
(54596, 1, 0, '용의 뼈일 것 같지 않아? 아니면 거인이나!'),
(54596, 2, 0, '그걸 네가 어떻게 알아?'),
(54601, 0, 0, '망치를 휘두르면 재미가 넘칩니다! 망치 휘두르고 싶으신 분?'),
(54601, 0, 1, '때려잡을 시간입니다!'),
(54601, 0, 2, '망치를 휘둘러서 상품을 가져가십시오!'),
(54601, 1, 0, '놀 때려잡기입니다! 이리 오셔서 놀을 두들겨 패보십시오!'),
(54605, 0, 0, '자, 여러분! 통통 전차를 조종해 영광스러운 전투를 치러 보십시오!'),
(54605, 0, 1, '이리 오셔서 통통 전차를 조종해 보십시오!'),
(54605, 0, 2, '통통 전차입니다! 여기 통통 전차가 있습니다!'),
(54605, 0, 3, '지금 우리가 공격당하고 있습니다! 이리 오셔서 당신의 몫을 다 해 주십시오, $c님!'),
(54611, 0, 0, '도전자가 다가오는군요.'),
(54611, 1, 0, '놀랍습니다! 보기보다 훨씬 강하시군요.'),
(54611, 1, 1, '그 실력에 경의를 표합니다. 정정당당히 저를 이기셨습니다.'),
(54611, 1, 2, '제가 아직 수련이 부족한 것 같습니다. 가르침, 감사합니다.'),
(54611, 1, 3, '당신에게 진 것은 영광입니다.'),
(54611, 1, 4, '잘 싸우셨습니다. 샹 사부님께서 기뻐하실 겁니다.'),
(54611, 1, 5, '수련을 충실히 하셨군요.'),
(54751, 0, 0, '필멸자여! 더는 너희를 따라갈 수 없구나. 내 축복을 받고 시간의 모래시계를 사용해서 무르도즈노를 쓰러뜨려라!'),
(54751, 1, 0, '드디어 때가 왔구나. 내 최후의 순간 말이다. 이 시간의 고리는 끊겼다. 이제 미래의 나는 아무 위협도 가하지 않을 것이다.'),
(54751, 2, 0, '하지만, 시간이 지나면... 지금의 내가 광기에 휩싸이겠지. 그리고 너희 영웅들이... 날 제압하리라. 순환은 계속되고, 또 계속될 터.'),
(54751, 3, 0, '중요한 것은 아제로스가 멸망하지 않았다는 것이다. 우리가 살아남아 다시 투쟁할 수 있다는 것이다.'),
(54751, 4, 0, '중요한 것은... 지금 이 순간이다.'),
(54763, 0, 0, '당신이 누구신지는 모르겠지만, 정말 감사합니다.'),
(54763, 0, 1, '이런 일이 일어날 거라고는 생각해 본 적이 없습니다...'),
(54763, 0, 2, '이제 끝이라고 생각했습니다!'),
(54763, 0, 3, '두 번씩 말씀하실 필요는 없습니다!'),
(54786, 0, 0, '잘 왔네, 후오. 모두 자네의 온기를 그리워했다네.'),
(54786, 1, 0, '내가 자네에게 안긴 시험을 모두 훌륭히 통과했군. 후오를 찾아서 사원까지 무사히 데리고 왔어.'),
(54786, 2, 0, '지금 우리는 훨씬 큰 문제에 봉착해 있네, 제자들이여. 셴진 수가 고통받고 있네. 빨리 손쓰지 않으면 지금 우리가 서 있는 이 땅이 죽어버릴 걸세. 또한 우리 모두 함께 죽겠지.'),
(54786, 3, 0, '셴진 수와 이야기해서 치유할 방법을 알아내야 하네. 그러려면 네 정령을 한데 모아야 하지. 후오가 시작이었네.'),
(54786, 4, 0, '지, 자네는 다이로 농장으로 가서 대지의 정령 우고우를 찾게나.'),
(54786, 5, 0, '아이사, 자네는 노래하는 웅덩이로 가서 물의 정령 슈를 찾아 주게.'),
(54786, 6, 0, '그리고 자네, 자네가 우리 모두를 이끄는 손이 되게. 나와 잠깐 이야기를 나눈 후에 동쪽에 있는 노래하는 웅덩이로 아이사를 찾아가게.'),
(54786, 7, 0, '물과 대지의 정령을 데리고 왔군. 이 노사부는 자랑스러울 따름일세.'),
(54786, 8, 0, '우고우와 슈는 언제든 환영일세. 우리가 잘 돌보겠네.'),
(54786, 9, 0, '이제 남은 정령은 다펑뿐일세. 서쪽, 새벽의 교각 건너 어딘가에 숨어 있다네.'),
(54786, 10, 0, '자네를 사원 꼭대기로 보내 주겠네. 지가 기다리고 있으니 함께 가게.'),
(54856, 0, 0, '사부 리 페이의 목소리가 울려 퍼집니다. "투슈이의 가르침... 인내와 명상을 통한 깨우침... 지조 있는 삶."'),
(54856, 1, 0, '사부 리 페이의 목소리가 울려 퍼집니다. "다시 보니 반갑구먼, 아이사. 자네가 공경심을 지니고 왔으니, 자네가 구하는 답을 주겠네."'),
(54856, 2, 0, '사부 리 페이의 목소리가 울려 퍼집니다. "불의 정령 후오는 탐식이 심하기로 유명하지. 녀석은 부싯깃을 먹고 싶어하네. 바람의 손길에 깨어나고 싶어하네."'),
(54856, 3, 0, '사부 리 페이의 목소리가 울려 퍼집니다. "그것을 찾아서 우쏭 마을 너머의 후오가 있는 동굴로 가져가면, 동굴 안에서 시험에 들게 될 걸세."'),
(54856, 4, 0, '사부 리 페이의 목소리가 울려 퍼집니다. "시험을 통과하고 나면 후오 앞에 설 수 있을 걸세. 후오의 불꽃에 다시 불을 지피게. 자네의 영혼이 순수하다면 후오가 자네를 따라 나설 걸세."'),
(54856, 5, 0, '사부 리 페이의 목소리가 울려 퍼집니다. "가게, 제자들이여. 곧 다시 만나게 될 걸세."'),
(54856, 6, 0, '사부 리 페이의 모습이 흐릿해지더니 사라집니다.'),
(54867, 0, 0, '이곳엔 기괴한 어둠과 영원한 밤이 깔려 있다. 조심해라, 영웅들이여. 빛에서 멀어지지 마라.'),
(54867, 1, 0, '신성한 이곳에 남은 건 꺼지지 않는 불꽃뿐이구나. 커다란 분노가 느껴진다... 폭발 직전의 이글거리는 분노가. 부디 조심해라.'),
(54867, 2, 0, '청금석 용제단에 남은 건 이것뿐이다. 거대한 전투가 이 버림받은 곳 밖으로 나가는 시간의 길을 닫아버렸지. 땅 곳곳에 떨어진 파편을 합치고 갇힌 영혼을 쓰러뜨려야만 나갈 수 있다.'),
(54867, 3, 0, '바로 이곳이다, 영웅들이여. 그녀는 이곳에서 저항하다 쓰러졌지. 시간 속에 갇힌 여군주 실바나스 윈드러너의 환영은 루비 용제단의 썩어가는 가지 사이를 영원히 맴돌 것이다.'),
(54867, 4, 0, '무르도즈노와 맞서고 싶다면 이 땅에 안식을 가져와야 한다.'),
(54882, 0, 0, '천 개의 달빛이여, 이 영광을 저에게 허락해 주십시오.'),
(54882, 1, 0, '빛 중의 빛이시여! 제 목숨은 당신의 것입니다!'),
(54882, 2, 0, '생명의 꽃이시여, 부름을 받들겠습니다. 실망시키지 않겠습니다.'),
(54883, 0, 0, '천 개의 달빛이여, 이 영광을 저에게 허락해 주십시오.'),
(54883, 1, 0, '빛 중의 빛이시여! 제 목숨은 당신의 것입니다!'),
(54883, 2, 0, '생명의 꽃이시여, 부름을 받들겠습니다. 실망시키지 않겠습니다.'),
(54884, 0, 0, '천 개의 달빛이여, 이 영광을 저에게 허락해 주십시오.'),
(54884, 1, 0, '빛 중의 빛이시여! 제 목숨은 당신의 것입니다!'),
(54884, 2, 0, '생명의 꽃이시여, 부름을 받들겠습니다. 실망시키지 않겠습니다.'),
(54915, 0, 0, '$n, 이렇게 반가울 수가. 관리인 일은 굉장히 배고픈 작업이거든.'),
(54917, 0, 0, '저 아래에서 수련생들과 함께 사각 진형에 맞춰 서게. 그리고 교관의 지시를 따르게.'),
(54925, 0, 0, '좋습니다!'),
(54925, 1, 0, '제가 패할 줄 알았습니다. 강물이 그렇게 말하더군요.'),
(54926, 0, 0, '당신이 원한다면... 좋습니다. $R 주물럭을 만들어 먹을 시간이군요!'),
(54926, 1, 0, '이번에는... 당신이 이겼습니다. 저도 체력 훈련을 다시 시작해야겠어요.'),
(54927, 0, 0, '차원문이 닫힌다! 서둘러라!'),
(54927, 1, 0, '저기다! 어서 가라!'),
(54927, 2, 0, '허약하고 쓸모없는 생명체 같으니!'),
(54927, 3, 0, '너희 삶은 여기서 끝이다.'),
(54927, 4, 0, '연기 나는 몸뚱이만 남겨 주마.'),
(54938, 0, 0, '난 그 용의 눈을 들여다봤어... 그리고 절망했지...'),
(54938, 1, 0, '안으로 들어오시오. 어서! 내가 놈들을 막겠소!'),
(54938, 2, 0, '그럼... 주술사, 용의 영혼을 내놓으시지. 당장.'),
(54938, 3, 0, '빛이 너를 삼키리라!'),
(54938, 4, 0, '암흑 속에 잠겨라!'),
(54943, 0, 0, '쉿! 발소리 낮추시오. 아이사가 수련하고 있소.'),
(54960, 0, 0, '이방인이여, 잔잔한 호수에 돌이 떨어지는 것을 본 적이 있나? 모든 행동은 물결을 일으키지. 우정을 맺는 것도 마찬가지다. 네 제안에 대해 생각해 보겠다.'),
(54969, 0, 0, '오너라, 스톰레이지. 내 보여주마. 불타는 군단의 군주를 배신하면 어떤 일이 벌어지는지 말이다!'),
(54969, 1, 0, '안 돼... 안 돼! 승리가 눈앞에 있는데 어떻게 이런 일이! 내가 빈손으로 그분께 돌아갈 것 같으냐! 난... 이 초라한 세계를 떠날 수 없어! 안 돼... 안 돼애애애애!'),
(54969, 2, 0, '바로덴, 하찮은 놈들이 날 방해하지 못하게 해라!'),
(54969, 3, 0, '살게라스 님, 실망시키지 않겠습니다! 당신의 불타는 주먹으로 이 세상을 부숴, 모든 것이 불꽃과 암흑 속에서 다시 태어나게 하소서!'),
(54969, 4, 0, '으아아아아!'),
(54969, 5, 0, '네 피는 내것이다!'),
(54969, 6, 0, '그래... 그래! 그분의 타오르는 눈길이 느껴진다. 그분이 곧 강림하신다... 곧! 그분이 오시면 이 세계는 무너지고, 네놈들은 먼지로 돌아가리라!'),
(54969, 7, 0, '바닥을 기며 죽어가라!'),
(54969, 7, 1, '몸부림쳐라! 비명을 질러!'),
(54969, 7, 2, '쓸모없는 놈!'),
(54969, 8, 0, '[악마어] 아마나르 마이브 일 아즈갈라다 질라 아셰 아셰 질라 엔킬!'),
(54971, 0, 0, '그렇겐 못 해, 대주교여. 절대 넘기지 않을 걸세.'),
(54971, 1, 0, '자네는 빛의 최고 성직자가 아닌가, 베네딕투스. 어떻게 백성들을 배신할 수 있나.'),
(54972, 0, 0, '조심해라. 적들이 몰려온다!'),
(54972, 1, 0, '누구도 우릴 막을 순 없다!'),
(54972, 2, 0, '황혼의 망치단이 돌아왔군!'),
(54972, 3, 0, '올테면 와 봐라!'),
(54972, 4, 0, '여기서 알렉스트라자 님의 비룡들을 만나기로 했는데...'),
(54972, 5, 0, '저 위, 위를 보게!'),
(54972, 6, 0, '이 먼 길을 왔는데 너 따위가 날 막을쏘냐!'),
(54972, 7, 0, '잘 했네, 이제 이 친구를 살펴보지...'),
(54972, 8, 0, '나머지 비룡들이 곧 도착할 걸세. 먼저 갈 테니 준비되면 따라오게.'),
(55003, 0, 0, '튀어!'),
(55009, 0, 0, '여기네!'),
(55084, 0, 0, '모구 복병이 나무에서 내려옵니다. 조심하세요!'),
(55084, 1, 0, '이게 누구야! 과수원에서 온 녀석이 또 있군...'),
(55085, 0, 0, '필멸자 주제에 내 앞에 서고도 살기를 바라느냐!'),
(55085, 0, 1, '궁전으로 가고 싶은 놈은, 악의 힘을 처음으로 얻은 이 페로스안에게 덤벼라!'),
(55085, 1, 0, '안 돼! 어떻게 이런 일이...?!'),
(55085, 2, 0, '그만! 게임은 이제 끝이다!'),
(55085, 3, 0, '놈이 가까이 있다. 어둠 속에 몸을 숨겼군. 느껴진다.'),
(55085, 4, 0, '거기 지옥 군단병! 이곳을 지켜라.'),
(55085, 5, 0, '나머지는 안마당을 확실히 방어하도록.'),
(55085, 6, 0, '하, 네가 보인다...'),
(55085, 7, 0, '잘도 숨는구나, 벌레들아. 그런다고 얼마나 목숨을 부지할 것 같으냐?'),
(55085, 8, 0, '찾아내고 말겠다!'),
(55085, 8, 1, '어둠은 널 구하지 못한다.'),
(55085, 8, 2, '숨어서 벌벌 떨어라, 하하!'),
(55085, 9, 0, '누가 차원문을 닫았지? 교활한 벌레들 같으니...'),
(55085, 10, 0, '너의 정수는... 내것이다.'),
(55085, 11, 0, '이제, 어둠이 나를 섬긴다...'),
(55085, 12, 0, '%s|1이;가; 어둠 속으로 사라집니다!'),
(55085, 13, 0, '페로스안의 눈이 당신을 찾고 있습니다.'),
(55085, 14, 0, '%s|1이;가; 무력해진 사냥감을 습격합니다!'),
(55107, 0, 0, '우리에게 맞서는 모든 이에게 죽음을!'),
(55196, 0, 0, '네 친구는 꽤나 멋지게 싸웠다. 탈출에 성공할 뻔했지만, 이제 우리와 마찬가지로 포로 신세다.'),
(55201, 0, 0, '테일러 제독의 친구입니까? 그렇다면, 나중에 결투를 통해 당신의 힘을 시험해보고 싶습니다.'),
(55201, 0, 1, '물의 정령이 제 기도에 응해 줬군요. 감사합니다.'),
(55201, 0, 2, '이제 포기하려던 참이었습니다. 친구여, 감사합니다.'),
(55201, 0, 3, '헛것이 보이는 건가? 제가 정말 풀려난 건가요?'),
(55201, 0, 4, '이렇게 살아남는군요. 모두 당신 덕분입니다.'),
(55264, 0, 0, '게임 동전 팝니다! 게임 동전 사가십시오!'),
(55264, 0, 1, '자자, 거짓말하는 거 아닙니다. 이리 오셔서 게임 동전 사가십시오!'),
(55264, 0, 2, '자자, 어서 서두르십시오! 이리 오셔서 게임 동전 사가십시오!'),
(55264, 0, 3, '이리 오셔서 게임 동전을 사가십시오!'),
(55264, 0, 4, '게임 동전입니다! 게임 동전 사십시오!'),
(55264, 0, 5, '게임 동전입니다! 게임 동전! 게임 동전을 사십시오!'),
(55264, 0, 6, '게임을 하려면 동전을 내야 합니다. 이리 오셔서 게임 동전을 사가십시오!'),
(55264, 0, 7, '게임을 하려면 게임 동전이 필요합니다. 게임 동전 사가십시오!'),
(55265, 0, 0, '계란으로 바위를 치려 드는군. 내가 널 묻어주마.'),
(55265, 1, 0, '이럴 수가. 말도 안 돼. 탑을... 꼭 무너뜨려야... 하는데...'),
(55265, 2, 0, '겁쟁이들. 약해 빠진 것들. 내려와서 싸워라. 내가 직접 끌어 내리기 전에.'),
(55265, 3, 0, '이 사원에 영원히 숨을 순 없다, 주술사여.'),
(55265, 4, 0, '내가 이 탑을 돌 무더기로 만들어서, 온 벌판에 흩뿌리겠다.'),
(55265, 5, 0, '고룡쉼터는 무너질 것이다. 모두 먼지가 될 것이다.'),
(55265, 6, 0, '돌이 부른다...'),
(55265, 6, 1, '땅이 요동친다...'),
(55265, 6, 2, '바위가 떨린다...'),
(55265, 6, 3, '바닥이 전율한다...'),
(55265, 7, 0, '...대지의 검은 피가 널 삼키리라.'),
(55265, 7, 1, '...그 누구도 고대 신에게서 벗어날 순 없으리라.'),
(55265, 7, 2, '...진정한 신의 분노가 뒤따르리라.'),
(55265, 7, 3, '...주인님의 증오가 너희를 덮치리라.'),
(55265, 8, 0, '필멸자 따위가 내 임무를 막을 순 없다.'),
(55265, 9, 0, '뛰어 봤자 벼룩인 것을.'),
(55265, 9, 1, '도망쳐 봤자 죽은 목숨이다.'),
(55265, 10, 0, '날 막을 순 없다.'),
(55265, 10, 1, '당연한 결과다.'),
(55265, 10, 2, '먼지가 되어라.'),
(55265, 11, 0, '혼자 나와 싸우겠다고? 대지가 갈라져 널 삼키고 뭉개버릴 거다.'),
(55265, 12, 0, '%s|1이;가; 공명의 수정을 소환합니다!'),
(55266, 0, 0, '게임 동전 팝니다! 게임 동전 사가십시오!'),
(55266, 0, 1, '자자, 거짓말하는 거 아닙니다. 이리 오셔서 게임 동전 사가십시오!'),
(55266, 0, 2, '자자, 어서 서두르십시오! 이리 오셔서 게임 동전 사가십시오!'),
(55266, 0, 3, '이리 오셔서 게임 동전을 사가십시오!'),
(55266, 0, 4, '게임 동전입니다! 게임 동전 사십시오!'),
(55266, 0, 5, '게임 동전입니다! 게임 동전! 게임 동전을 사십시오!'),
(55266, 0, 6, '게임을 하려면 동전을 내야 합니다. 이리 오셔서 게임 동전을 사가십시오!'),
(55266, 0, 7, '게임을 하려면 게임 동전이 필요합니다. 게임 동전 사가십시오!'),
(55267, 0, 0, '비취 괴물 머리를 한 대 차 줬는데, 제 발만 아팠어요.'),
(55267, 0, 1, '구해 주셔서 고마워요!'),
(55267, 0, 2, '안이 그랬어요! 신한테 겁쟁이라고 놀리면서, 옥의 마녀네 문을 두드리라고 했어요.'),
(55294, 0, 0, '지금은 황혼의 시간이다!'),
(55294, 1, 0, '화염과 암흑 속으로, 너희 모두 다 끌고 가주마.'),
(55294, 2, 0, '하지만... 하지만.. 난... 난... 울트락시...'),
(55294, 3, 0, '나는... 종말의 시작이다. 태양을 뒤덮어버리는 그림자이자, 네 파멸을 알리는 종소리이다.'),
(55294, 4, 0, '난 이 순간만을 위해 태어났다. 네 저승사자의 모습을 봐라, 필멸자여. 그리고 절망하라.'),
(55294, 5, 0, '울트락시온 앞에 무릎 꿇어라!'),
(55294, 5, 1, '너희에게 희망은 없다!'),
(55294, 5, 2, '하하하하하!'),
(55294, 6, 0, '최후의 빛 한 줄기가 흐려진다. 네 가소로운 필멸의 목숨과 함께!'),
(55294, 7, 0, '고통과 화염 속에서 내 끝없는 증오가 타오른다.'),
(55294, 8, 0, '괴물 같은 힘이 당신을 황혼 세계로 잡아끕니다!'),
(55294, 9, 0, '|TInterface\\Icons\\spell_shadow_twilight.blp:20|t 울트락시온이 |cFF9900CC|Hspell:106371|h[황혼의 시간]|h|r을 시전합니다!'),
(55294, 10, 0, '|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t 울트락시온이 |cFF9900CC|Hspell:106373|h[더욱 불안정한 상태]|h|r가 됩니다!'),
(55308, 0, 0, '다시 한 번 이 세계의 썩어빠진 시체들 위에 느조스의 뒤틀린 살점 깃발이 꿈틀거리며 펄럭이는구나. 천 년의 세월이 지나, 우리가 돌아왔다.'),
(55308, 1, 0, '우보쉬 디즈... 크와즈...'),
(55308, 2, 0, '브와이크 액스 샤오크멕 조스 브라 즈으 쉬프 쿠오 게할라스 액스. 울그마, 아그 쿠암.'),
(55308, 3, 0, '스켁 아그스 누크 느조스 와큐즈.'),
(55308, 3, 1, '스케야그프 아가스 허크스 느조스 고나스.'),
(55308, 3, 2, '스케울 아그스 보르즈 느조스 나그와프시.'),
(55308, 4, 0, '스카맥 야위픽 하크.'),
(55308, 4, 1, '스큐야트 굴프그 하크.'),
(55308, 4, 2, '스카센 이퀴니즈 호크.'),
(55308, 5, 0, '느조스 가 지크타그 일리스.'),
(55308, 6, 0, '굴카와스 언고브 느조스.'),
(55308, 7, 0, '데스윙 님에게 승리를! 느조스의 영광을 위하여!'),
(55308, 8, 0, '이것을 위해... 너무 오랜 시간을 기다렸다...'),
(55308, 9, 0, '다시 한 번 이 세계의 썩어빠진 시체들 위에 느조스의 뒤틀린 살점 깃발이 꿈틀거리며 펄럭이는구나. 천 년의 세월이 지나, 우리가 돌아왔다.'),
(55308, 10, 0, '너의 영혼은 느조스의 끝없는 굶주림을 채워줄 것이다.'),
(55308, 10, 1, '너의 죽음은 느조스의 끝없는 영광을 찬미할 것이다.'),
(55308, 10, 2, '네놈의 해골은 고통에 몸부림치는 느조스의 왕좌를 장식할 것이다.'),
(55308, 11, 0, '너의 두려움이 나를 움직이지.'),
(55308, 11, 1, '너의 고통은 나를 강하게 만든다.'),
(55308, 11, 2, '너의 고뇌는 내게 힘이 되지.'),
(55308, 12, 0, '느조스의 의지가 너를 타락시킬 것이다.'),
(55308, 13, 0, '느조스의 심장 안을 응시하라.'),
(55312, 0, 0, '릴스 퀴요툭 샨마 예글루 셰아스야! 하인 릴스!'),
(55312, 1, 0, '이즈. 슈울와! 슥우스글 유게즈 요흐글리 일스!'),
(55312, 2, 0, '아카그티쉬 마 우니쉬. 아욱크 쉬그출 브와후운! 하이은 이긱쉬 푸쿠와티 객 우 카악스 슈울!'),
(55312, 3, 0, '스크야프 파이팔라프 피마그!'),
(55312, 3, 1, '하이은 자익스 슈울와, 프쿠타이!'),
(55312, 3, 2, '스쿨 안지그 크브삭프 케쉬가, 악 티작 아그수!'),
(55312, 4, 0, '카이스 아그시그 야아그파 일쿠아아스 온그!'),
(55312, 4, 1, '우우울 이위훅 하이윈!'),
(55312, 5, 0, '너희들은 모두 고대 신의 피에 빠져 죽을 것이다! 너희들 모두!'),
(55312, 6, 0, '아, 데스윙 님이시여! 당신의 충실한 하인이 실망을 안겨드렸습니다!'),
(55312, 7, 0, '우리의 군사는 셀 수 없을 정도로 많고, 그 힘은 상상조차 할 수 없을 만큼 강력하다! 파괴자에 맞서는 자들은 모두 천 번의 죽음을 맞으리라!'),
(55312, 8, 0, '곧 네 영혼이 끝없는 고통을 깨닫게 될 것이다!'),
(55312, 8, 1, '파괴자 데스윙 님을 찬양하라!'),
(55312, 8, 2, '이 음울한 깊은 곳으로부터, 우리는 이 세상을 되찾을 것이다!'),
(55312, 9, 0, '우리가 어떻게 이 저주받은 대지에서 쏟아져나오는지 봐라!'),
(55312, 9, 1, '어둠이 모든 것을 집어삼킬 것이다!');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(55312, 10, 0, '%s|1이;가; 슈마의 |cFF0080FF|Hspell:104900|h[푸른색 피]|h|r, |cFF424242|Hspell:104894|h[검은색 피]|h|r, |cFFFFA901|Hspell:104901|h[노란색 피]|h|r를 소환합니다!'),
(55312, 11, 0, '%s|1이;가; 슈마의 |cFF9932CD|Hspell:104896|h[보라색 피]|h|r, |cFF088A08|Hspell:104898|h[초록색 피]|h|r, |cFF0080FF|Hspell:104900|h[푸른색 피]|h|r를 소환합니다!'),
(55312, 12, 0, '%s|1이;가; 슈마의 |cFF9932CD|Hspell:104896|h[보라색 피]|h|r, |cFFFF0404|Hspell:104897|h[붉은색 피]|h|r, |cFF424242|Hspell:104894|h[검은색 피]|h|r를 소환합니다!'),
(55312, 13, 0, '%s|1이;가; 슈마의 |cFF088A08|Hspell:104898|h[초록색 피]|h|r, |cFFFFA901|Hspell:104901|h[노란색 피]|h|r, |cFFFF0404|Hspell:104897|h[붉은색 피]|h|r를 소환합니다!'),
(55312, 14, 0, '%s|1이;가; 슈마의 |cFF088A08|Hspell:104898|h[초록색 피]|h|r, |cFFFF0404|Hspell:104897|h[붉은색 피]|h|r, |cFF424242|Hspell:104894|h[검은색 피]|h|r를 소환합니다!'),
