(55312, 18, 0, '%s|1이;가; 슈마의 |cFF0080FF|Hspell:104900|h[푸른색 피]|h|r, |cFF9932CD|Hspell:104896|h[보라색 피]|h|r, |cFF088A08|Hspell:104898|h[초록색 피]|h|r, |cFFFFA901|Hspell:104901|h[노란색 피]|h|r를 소환합니다!'),
(55312, 19, 0, '%s|1이;가; 슈마의 |cFF0080FF|Hspell:104900|h[푸른색 피]|h|r, |cFF424242|Hspell:104894|h[검은색 피]|h|r, |cFF9932CD|Hspell:104896|h[보라색 피]|h|r, |cFFFFA901|Hspell:104901|h[노란색 피]|h|r를 소환합니다!'),
(55312, 20, 0, '%s|1이;가; 슈마의 |cFF088A08|Hspell:104898|h[초록색 피]|h|r, |cFFFF0404|Hspell:104897|h[붉은색 피]|h|r, |cFF0080FF|Hspell:104900|h[푸른색 피]|h|r, |cFF424242|Hspell:104894|h[검은색 피]|h|r를 소환합니다!'),
(55312, 21, 0, '%s|1이;가; 슈마의 |cFF088A08|Hspell:104898|h[초록색 피]|h|r, |cFFFFA901|Hspell:104901|h[노란색 피]|h|r, |cFF424242|Hspell:104894|h[검은색 피]|h|r, |cFFFF0404|Hspell:104897|h[붉은색 피]|h|r를 소환합니다!'),
(55339, 0, 0, '게임 동전 팝니다! 게임 동전 사가십시오!'),
(55339, 0, 1, '자자, 거짓말하는 거 아닙니다. 이리 오셔서 게임 동전 사가십시오!'),
(55339, 0, 2, '자자, 어서 서두르십시오! 이리 오셔서 게임 동전 사가십시오!'),
(55339, 0, 3, '이리 오셔서 게임 동전을 사가십시오!'),
(55339, 0, 4, '게임 동전입니다! 게임 동전 사십시오!'),
(55339, 0, 5, '게임 동전입니다! 게임 동전! 게임 동전을 사십시오!'),
(55339, 0, 6, '게임을 하려면 동전을 내야 합니다. 이리 오셔서 게임 동전을 사가십시오!'),
(55339, 0, 7, '게임을 하려면 게임 동전이 필요합니다. 게임 동전 사가십시오!'),
(55368, 0, 0, '비취 속에 영원히 보존된 우리 가족이 되는 게 어떠신가요.'),
(55402, 0, 0, '축제에 오신 분들은 모두 주목하십시오! 곧 다크문 사투를 시작합니다! 잠시 후 사투장 가운데에 상품이 든 상자가 나타날 겁니다!'),
(55402, 1, 0, '다크문 사투를 시작하겠습니다!'),
(55402, 2, 0, '다크문 사투가 끝났습니다! 승자는 바로 $n!'),
(55419, 0, 0, '당신을 위해!'),
(55419, 1, 0, '빛 중의 빛이여... 실망을 안겨드려 죄송합니다... 나의 아즈샤라...'),
(55419, 2, 0, '감히 여왕님을 거역하다니!'),
(55419, 2, 1, '죽어 마땅하다.'),
(55419, 2, 2, '아즈샤라의 이름으로!'),
(55477, 0, 0, '%s|1이;가; 한숨을 내쉽니다.'),
(55483, 0, 0, '채소 다 내놔!'),
(55483, 0, 1, '에이이이잇!'),
(55483, 0, 2, '여긴 토깽 땅이다!'),
(55483, 0, 3, '너 당근 못 가져가! 대신 순무 가져가!'),
(55490, 0, 0, '구출대 중의 한 분이신가요? 우린 이제 살 수 있나요?'),
(55490, 0, 1, '누군가 우릴 구하러 올 줄 알았습니다. 감사합니다, $c님!'),
(55490, 0, 2, '고맙습니다, $c님. 야영지까지는 제가 알아서 갈 수 있습니다.'),
(55490, 0, 3, '놈들이 제독님을 마치 동물처럼 가둬놨습니다. 제독님도 구출하십시오.'),
(55490, 0, 4, '호젠이 포로들을 고문하고 있습니다. 끔찍한 운명으로부터 절 구해주셔서 정말 감사합니다, $c님.'),
(55500, 0, 0, '다시 어둠 속으로!'),
(55500, 1, 0, '그 무엇도 날 막을 수 없어! 너도 마찬가지다, 악마야.'),
(55500, 2, 0, '악마 한 놈이 또 최후를 맞으러 왔군.'),
(55500, 3, 0, '하하하, 사냥꾼이 사냥감이 됐군.'),
(55500, 4, 0, '잘해줬다. 하지만 이젠 나 혼자 가야 해. 행운을 빈다.'),
(55500, 5, 0, '그런 것도 마법이라고. 내 실력을 똑똑히 봐라.'),
(55500, 6, 0, '어둠 속에 몸을 숨겼다. 이제 적은 우릴 볼 수 없어.'),
(55500, 7, 0, '가자. 잘 따라와라.'),
(55500, 8, 0, '내 검은 굶주렸다!'),
(55500, 9, 0, '이 정도쯤이야.'),
(55500, 10, 0, '군단에 죽음을!'),
(55500, 11, 0, '여길 지나가야겠군. 놈들을 막을 테니, 준비해.'),
(55500, 12, 0, '마법이 약해지는군. 나도 건너가겠다!'),
(55500, 13, 0, '살고 싶다면 따라와라. 내가 이 세상을 구하는 걸 보여 주지!'),
(55500, 14, 0, '악마가 너무 많군. 처리할 시간이 없어.'),
(55500, 15, 0, '서두르지 않아도 놈들은 죗값을 치를 거다...'),
(55500, 16, 0, '수호 악마 하나가 수백 명의 엘프를 학살하는 것도 봤다. 조심해라.'),
(55500, 17, 0, '궁전에서 악마가 끝없이 몰려나오는군.'),
(55500, 18, 0, '유황 냄새가 아주 코를 찌르는군. 이 차원문도 악마 놈들과 똑같이 역겨워.'),
(55500, 19, 0, '어둠을 벗어던지고 놈을 덮쳐!'),
(55500, 20, 0, '마지막 차원문을 닫고 일을 끝내자.'),
(55500, 21, 0, '곧 악마 놈들이 없어질 거다. 그러면 바로 궁전으로 갈 수 있어.'),
(55500, 22, 0, '이제 궁전에서 악마들이 나오지 않는군. 어서 가자.'),
(55500, 23, 0, '너무 쉬웠어.'),
(55500, 24, 0, '이봐! 여기 어둠 속이다.'),
(55500, 25, 0, '여기 왜 온 건가?'),
(55500, 26, 0, '공격해라. 난 기다리는 걸 싫어한다.'),
(55500, 27, 0, '첫 놈은 양보해 주지. 내가 후회하게 하지 마라.'),
(55500, 28, 0, '내게서 인내심을 바라지 마라.'),
(55500, 29, 0, '자, 공격해라...'),
(55500, 30, 0, '곧 죽을 목숨인 줄도 모르고 멍청히 서 있는 꼴이라니.'),
(55500, 31, 0, '이제 힘이 돌아오는군.'),
(55500, 32, 0, '수정을 파괴해야 다른 곳으로 갈 수 있다.'),
(55500, 33, 0, '수정을 깨뜨려라. 할 일이 많다.'),
(55500, 34, 0, '어서 수정을 파괴해라!'),
(55500, 35, 0, '우리가 힘을 합치면 일이 조금 더 쉬울 것 같은데...'),
(55500, 36, 0, '나랑 얘기 좀 하지.'),
(55500, 37, 0, '도와주러 온 게 아니었나?'),
(55500, 38, 0, '이동해야 한다. 차원문을 닫아!'),
(55500, 39, 0, '흥미로운 무기를 사용하는군... 꽤 센 것 같은데.'),
(55500, 40, 0, '넌 준비된 것 같군.'),
(55532, 0, 0, '유물이!'),
(55532, 1, 0, '형... 딱 맞춰서 왔군...'),
(55532, 2, 0, '알아. 수많은 마법에 영향을 받아 샘이 뒤틀리고 말았어. 우리가... 아니, 형이 차원문을 닫겠다고 한 짓이 과했던 거야! 불타는 군단을 저 더러운 지옥으로 돌려보낸 그 주문이 이제 샘에도 영향을 미치고 있어! 샘 자체와, 그 주변까지 몽땅 삼켜버리고 있다고! 재미있군... 안 그래?!'),
(55532, 3, 0, '형이 나가는 길을 알면 가르쳐 주지그래! 마법으로 티란데와 함께 탈출하려고 해 봤는데, 샘이 너무 요동쳐서 먹히질 않아!'),
(55532, 4, 0, '형, 차원문을 닫을 수 있겠어?'),
(55532, 5, 0, '흠... 알았어. 놈은 우리가 쓰러뜨리지.'),
(55532, 6, 0, '얼마든지 덤비라지.'),
(55532, 7, 0, '정말 많군...'),
(55532, 8, 0, '약하고 무능한 것들 같으니. 불타는 군단이라는 이름이 아깝군.'),
(55532, 9, 0, '아, 이건 상대할 맛 나겠는데...'),
(55532, 10, 0, '잠깐, 좋은 생각이 있어.'),
(55532, 11, 0, '우리 동족들은 못 하는 일.'),
(55532, 12, 0, '그래... 이거야. 영원의 샘에 담긴... 생생한 마력이 느껴지는군! 이제 이 한심한 싸움을 끝내버리겠다!'),
(55532, 13, 0, '눈에 보이는 건 허상이고, 실체는 다른 곳에 있어. 진짜를 찾아내려면 주변을 공격해!'),
(55532, 14, 0, '바로덴을 상대해라. 만노로스는 내가 맡지.'),
(55532, 15, 0, '검이 만노로스의 지옥불 갑옷을 꿰뚫었다! 지금 공격해!'),
(55532, 16, 0, '만노로스, 이 세상에서 살게라스의 힘을 가진 게 너 혼자인 줄 아느냐! 잘 봐라!'),
(55532, 17, 0, '나는... 우리 종족의 구세주가 될 것이다! 반드시, 내 운명을 실현하고야 말겠다!'),
(55532, 18, 0, '[악마어] 레보스 일 옥 모르다나스 알킴 마즈 나즈테로스. 알킴 지안테 마즈레 미슌 테 나가스!'),
(55532, 19, 0, '놈이 아직도 샘과 연결돼 있잖아! 만노로스를 집중 공격해라! 놈이 집중하지 못하게 해!'),
(55539, 0, 0, '%s|1은;는; 큰 소리로 코를 골며 계속 잠을 잡니다.'),
(55570, 0, 0, '진정하시오, 티란데. 일리단은 어디 있소?'),
(55570, 1, 0, '일리단! 샘은 지금 극도로 불안정해!'),
(55570, 2, 0, '같이 빨려들어가면 재미없을 게다! 왜 도망가지 않았지? 뭐 하느라 샘에 손을 담그고 있었던 거냐?'),
(55570, 3, 0, '이쪽입니다!'),
(55570, 4, 0, '강력한 악마가 차원문을 유지하고 있다... 만노로스 말이지.'),
(55570, 5, 0, '나 혼자선 놈을 어찌할 수 없어...'),
(55597, 0, 0, '나 레크가 $p에게 감사의 마음을 전한 뒤 젊음의 웅덩이로 돌아갑니다.'),
(55624, 0, 0, '용의 영혼을 손에 넣었군. 서둘러라! 이 세계가 무너지기 전에 시간의 차원문을 통과해라!'),
(55624, 1, 0, '드디어 왔구나. 이곳에선 내일이면 세계의 분리가 일어난다. 영원의 샘이 무너지고 대륙이 여러 개로 분리된 사건 말이지.'),
(55624, 2, 0, '여기서 용의 영혼을 손에 넣어야 한다. 이 시간의 안개 속으로 영영 사라지기 전에...'),
(55624, 3, 0, '일단 아즈샤라를 따르는 명가 놈들이 만든 보호의 수호물을 찾아서 없애라. 궁전 안에서 찾을 수 있을 터. 난 그 이후를 탐색해 보마.'),
(55624, 4, 0, '행운을 비노라!'),
(55636, 0, 0, '우리에게 맞서는 모든 이에게 죽음을!'),
(55649, 0, 0, '리우 랑의 후손들이 나를 잊지 않았다니 고통스러운 중에도 마음이 따뜻해지는구나.'),
(55649, 1, 0, '옆구리에 가시가 박혔는데, 뺄 수가 없다.'),
(55649, 2, 0, '너무 고통스러워서 참을 수가 없다. 똑바로 헤엄칠 수가 없어.'),
(55649, 3, 0, '후손들이여, 부디 이 가시를 빼 주겠나? 나 혼자서는 뺄 수가 없다.'),
(55649, 4, 0, '너희 발이 닿지 않는 숲 속에 있다. 산맥을 따라 계속 가다 보면 찾을 수 있을 것이다.'),
(55649, 5, 0, '고맙다, 후손들이여.'),
(55672, 0, 0, '다 왔네. 내가 채비를 하는 동안 몇 가지 일 좀 도와주게.'),
(55694, 0, 0, '이봐! 아침 바람 마을은 이쪽이야.'),
(55768, 0, 0, '아, 손님이군! 판다리아에 이런 날이 올 줄이야. 안개가 걷히고, 세상과 다시 만났지. 싸우러 온 건 아니면 좋겠는데?'),
(55779, 0, 0, '모습을 드러내라!'),
(55779, 1, 0, '포위되었군. 난 복병을 막을 테니 자네들은 승천자를 상대하게.'),
(55779, 2, 0, '거의 해치웠어! 오그노카 록타르. 이제 끝내버리세!'),
(55779, 3, 0, '위치를 간파당했네. 피곤하겠지. 하지만 위상들이 우릴 기다리고 있네.'),
(55779, 4, 0, '따라오게.'),
(55870, 0, 0, '한바탕 제대로 놀아볼 시간이군! 모두 대비해라. 용 사냥할 시간이다.'),
(55870, 1, 0, '저 갑옷! 놈의 갑옷이 벗겨지는군! 갑옷을 뜯어내면 놈을 쓰러뜨릴 기회가 생길 거요!'),
(55870, 2, 0, '난 걱정하지 마시오. 파괴자를 막으시오! 엔슈-팔라-나, 도리니.'),
(55870, 3, 0, '전속력으로! 모든 게 우리 속도에 달려 있다. 파괴자가 도망치게 둬선 안 돼.'),
(55870, 4, 0, '모두 전투 태세로! 저 괴물들을 내 배에서 쫓아내!'),
(55870, 5, 0, '무장한 비룡에 전 화력을 집중하라!'),
(55870, 6, 0, '적 공병이 엔진실에 침입했다!'),
(55870, 7, 0, '하늘불꽃호가 더는 버티기 힘들 텐데!'),
(55870, 8, 0, '배가 추락한다. 배를 버려라!'),
(55870, 9, 0, '하늘불꽃호에 온 걸 환영하오. 세계의 끝까지 추적할 준비는 됐소?'),
(55870, 10, 0, '우리 엔진이 고장났다! 완전 무방비 상태가 되었군!'),
(55943, 0, 0, '처음 만나는 분들입니다. 하지만 판다렌치고 나쁜 이는 없지요.'),
(55971, 0, 0, '다시 만나 반갑군, 알렉스트라자. 난 떠나 있는 동안 좀 바쁘게 지냈다.'),
(55971, 1, 0, '네 불쌍한 자식들을 내 명령만을 따르는 넋나간 졸개들로 만들었거든. 생각보다 참... 눈뜨고 보기 힘들더군.'),
(55971, 2, 0, '가련한 녀석들, 이 실험은 위대한 결말을 위한 희생이었다. 알 연구의 결과물을 직접 확인해라.'),
(55971, 3, 0, '네파리안, 오닉시아, 시네스트라... 그들은 아무것도 아니었다. 이제 내 궁극의 창조물을 상대해라.'),
(55971, 4, 0, '황혼의 시간이 임박했다. 태양이 지리라. 하찮은 네 필멸의 육신 위로.'),
(55999, 0, 0, '숨을... 숨을 잘 못 쉬겠어요. 덕분에 목숨을 건졌네요.'),
(55999, 0, 1, '덕분에 목숨을 구했습니다.'),
(55999, 0, 2, '끝인 줄만 알았어요... 죽는 줄 알았죠. 고마워요, 이방인.'),
(55999, 0, 3, '제가 살아남은 건 모두 당신 덕분이에요... 잊지 않을게요.'),
(55999, 0, 4, '내가... 살았나? 고맙습니다... 정말 고마워요!'),
(55999, 0, 5, '크... 큰 신세를 졌소.'),
(55999, 0, 6, '늦지 않게 구해 주셔서 감사합니다, 영웅님.'),
(56013, 0, 0, '자네들 모두 셴진 수를 구하는 데 큰 몫을 했네. 자네들이 정말 자랑스럽네.'),
(56013, 1, 0, '자네들의 여정은 아직 끝나지 않은 것 같네. 우리 새 동지들의 고향인 부서진 세상에 우리의 도움이 필요할 터.'),
(56013, 2, 0, '자네는 어떤가, 지? 호드와 함께 그들의 땅으로 가겠나?'),
(56013, 3, 0, '자네는 어떤가, 젊은 제자여? 어디로 갈 텐가?'),
(56099, 0, 0, '불가능한 일을 해냈구나. 전 아제로스가 실패를 염려하던 일을 너희가 해냈다.'),
(56099, 1, 0, '앞에 있는 것은 위상의 보관함이다. 원하는 대로 가져가라. 너희에겐 그만한 자격이 있다.'),
(56099, 2, 0, '이제 그대는 새로운 시대를 이끌어야 한다... 필멸자의 시대를 말이다.'),
(56099, 3, 0, '안 돼! 너무 강해! 데스윙이 최후의 대격변을 일으키면 아제로스의 모든 생명은 끝이다. 서둘러, 놈을 막아야 해!'),
(56099, 4, 0, '완전히 이성을 잃었군!'),
(56099, 5, 0, '정말 잘했다. 내 심장의 불이 더할바 없는 순수함으로 빛나는구나. 불꽃 하나 빠짐없이 전부 쏟아내주지. 용의 영혼으로!'),
(56100, 0, 0, '내가 에메랄드의 꿈으로 너희를 인도하마. 전투가 너무 치열해지면, 안전한 그곳으로 이동해라.'),
(56100, 1, 0, '데스윙이 마지막 대격변을 불러오려 한다. 에메랄드의 꿈마저 떨리는구나. 주문을 막으려면 모두 함께 놈을 공격해야 한다.'),
(56100, 2, 0, '이런 분노는 정말 처음 보는군...'),
(56100, 3, 0, '드디어 한걸음 다가섰구나. 이제 에메랄드의 꿈이 가진 미지의, 초자연적인 힘을 용의 영혼에 불어넣겠노라.'),
(56101, 0, 0, '비전 마력을 불어넣어 드리겠습니다. 적을 무찌르세요!'),
(56101, 1, 0, '파괴자가 세상을 조각낼 일격을 위해 엄청난 힘을 모으고 있습니다. 당장 공격하십시오! 마지막 대격변을 막아야 합니다!'),
(56101, 2, 0, '아니, 데스윙의 몸이 분해되는 건가?'),
(56101, 3, 0, '잘하셨습니다! 이제 마나의 흐름을 재배열하고 용의 영혼을 제 비전 마력으로 채우겠습니다.'),
(56102, 0, 0, '...하지만, 서두르는 게 좋을지도.'),
(56102, 1, 0, '내가 파괴자의 공격을 최대한 늦춰보겠다.'),
(56102, 2, 0, '서둘러라, 영웅들이여. 머지않아 데스윙이 초래한 대격변이 세상을 휩쓸어 종말을 불러올 것이다. 나와 함께 공격하자. 당장!'),
(56102, 3, 0, '계속 몰아쳐라, 영웅들이여.'),
(56102, 4, 0, '때가 왔다. 내가 가진 모든 힘을 쏟아 모든 가능성의 끈을 바로 여기, 바로 지금, 용의 영혼에 엮겠다. 앞으로 일어날 일은 절대로 되돌릴 수 없으리라.'),
(56103, 0, 0, '이제 끝났다. 마침내 파괴자가 최후를 맞았어. 드디어, 우리 세상을 치유할 수 있네.'),
(56103, 1, 0, '위상들이여! 전력으로 영웅들을 도와주십시오.'),
(56103, 1, 1, '쓰러진 전우의 복수를! 계속 밀어붙이게!'),
(56103, 1, 2, '이 용사들이 데스윙의 헛점을 노출시킬 유일한 희망입니다. 힘을 합치면, 이길 수 있습니다.'),
(56103, 1, 3, '포기말게. 자네들이라면 데스윙을 막을 수 있어.!'),
(56103, 1, 4, '오직 자네만이 이 일을 시작할 수 있네!'),
(56114, 0, 0, '네, 저도 저 차원문으로 뛰어들려고 해봤어요.'),
(56114, 0, 1, '일단 함정이 작동되면, 걸려든 이는 생명력을 다 흡수당할 때까지 빠져나오지 못해요. 모구는 사악한 놈들이에요.'),
(56114, 0, 2, '조심해요. 거기 갇히면 함정이 당신의 생명력을 흡수해서 동력원으로 사용해요.'),
(56114, 0, 3, '주먹으로 때려보고, 발로 차보고, 후려갈겨도 봤지만, 아무리 해도 이 비밀감옥을 깰 수가 없었어요.'),
(56133, 0, 0, '좋네! 이 맥주를 담그는 데 자네 도움이 필요하네.'),
(56133, 1, 0, '내가 재료 이름을 외치면, 솥에다 던져 넣게나.'),
(56133, 2, 0, '농담일세!'),
(56133, 3, 0, '나는 모든 대륙을 통틀어 최고의 양조사지! 여기서부터는 내가 맡겠네.'),
(56133, 4, 0, '좀 기다려야 할 텐데... 시간이 오래 걸릴 걸세.'),
(56159, 0, 0, '이리 오게. 자네가 수련을 마치기 전에 마지막으로 함께 가야 할 곳이 있네.'),
(56159, 1, 0, '장로의 길을 지나면 지팡이의 숲이 나온다네. 자격이 있는 자만 들어갈 수 있는 신성한 곳이지.'),
(56159, 2, 0, '자격을 증명하는 방법은 여러 가지가 있네만, 가장 단순한 방법으로 하겠네. 자네가 민족을 위해 싸울 의지가 있는지, 민족의 안전을 지킬 수 있는지 알아야겠네.'),
(56159, 3, 0, '장로의 수호자를 쓰러뜨리면 지나갈 수 있네.'),
(56159, 4, 0, '정말 강해졌군, 제자여. 좋은 일일세. 곧 그 힘이 필요할 테니.'),
(56165, 0, 0, '수정 전도체가 과부하됩니다!'),
(56167, 0, 0, '|TInterface\\Icons\\ability_warrior_bloodnova.blp:20|t %s의 상처에서 |cFFFE9A2E열기 촉수|r가 돋아납니다!'),
(56167, 10, 0, '|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s|1이;가; |cFFFF0000|Hspell:105863|h[과다출혈]|h|r을 일으킵니다!'),
(56168, 0, 0, '|TInterface\\Icons\\ability_warrior_bloodnova.blp:20|t %s의 상처에서 |cFFFE9A2E열기 촉수|r가 돋아납니다!'),
(56168, 10, 0, '|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s|1이;가; |cFFFF0000|Hspell:105863|h[과다출혈]|h|r을 일으킵니다!'),
(56173, 0, 0, '넌 아무것도 못 했다. 내가 이 세상을 조각내주마.'),
(56173, 1, 0, '나는... 데스윙. 피할 수 없고, 꺾을 수 없는 파괴자, 만물의 종결자. 내가 바로 대격변이다!'),
(56173, 2, 0, '내 분노에서 탈출할 곳은 없다.'),
(56173, 2, 1, '방어구 따윈 아무 소용없다. 믿음은 더더욱 그렇지.'),
(56173, 2, 2, '바다가 네놈들의 불에 탄 몸뚱이를 삼킬 것이다.'),
(56173, 3, 0, '%s|1이;가; 위상을 꿰뚫으려고 합니다. 막아야 합니다!'),
(56173, 4, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFFFF0000|Hspell:107018|h[알렉스트라자]|h|r를 공격합니다!'),
(56173, 5, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFFFFFF00|Hspell:107018|h[노즈도르무]|h|r를 공격합니다!'),
(56173, 6, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFF04FC32|Hspell:107018|h[이세라]|h|r를 공격합니다!'),
(56173, 7, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFF5858FA|Hspell:107018|h[칼렉고스]|h|r를 공격합니다!'),
(56173, 8, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFFFF0000|Hspell:107018|h[위상 공격]|h|r을 시전합니다!'),
(56173, 9, 0, '|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t%s|1이;가; |cFFFF0000|Hspell:105651|h[엘레멘티움 화살]|h|r을 시전합니다!'),
(56173, 10, 0, '|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s|1이;가; |cFFFF0000|Hspell:105863|h[과다출혈]|h|r을 일으킵니다!'),
(56173, 11, 0, '|TInterface\\Icons\\ability_deathwing_cataclysm.blp:20|t%s|1이;가; |cFFFF0000|Hspell:106523|h[대격변]|h|r을 시전합니다! 막아야 합니다!'),
(56173, 12, 0, '|TInterface\\Icons\\inv_stave_2h_deathwingraiddw_d_01.blp:20|t%s|1이;가; |cFF04FC32이세라|r의 돌마루에 거꾸러집니다!'),
(56173, 13, 0, '%s|1이;가; 분노에 휩싸여 광폭해집니다!'),
(56427, 0, 0, '주인님 근처에도 못 갈거다. 비룡 기수들이여, 공격!'),
(56427, 1, 0, '꽤... 하는군, 헤헷. 하지만 그분께 대적할 정도는... 아니야.'),
(56427, 2, 0, '내가 직접 나서야겠군. 좋지!'),
(56427, 3, 0, '너무 가까이 붙은 것 같군. 재미있는 싸움이었다. 하지만 이젠 끝이다!'),
(56427, 4, 0, '하! 네놈들이 여기까지 오길 바라고 있었지. 이제 진짜 싸움을 준비해라!'),
(56427, 5, 0, '황소에게 덤비다니...'),
(56427, 5, 1, '바닥에 처박아라!'),
(56427, 5, 2, '일어나! 어, 이런 약골 자식!'),
(56427, 6, 0, '고리오나! 지옥을 보여줘라!'),
(56427, 7, 0, '이건 어떠냐?'),
(56427, 7, 1, '덤벼!'),
(56427, 8, 0, '비룡이 빠르게 날아와 황혼의 폭파병을 갑판에 떨어뜨립니다!'),
(56427, 9, 0, '|Tinterface\\icons\\spell_fire_ragnaros_lavabolt.blp:0|t하늘불꽃호가 심각한 손상을 입어 |cFFFF0000|Hspell:110095|h[갑판 화재]|h|r가 일어납니다!'),
(56439, 0, 0, '죽거나 항복해라. 너희는 날 이길 수 없어.'),
(56439, 1, 0, '넌 내게서 도망칠 수 없어. 나는... 온... 세상에... 존재한다...'),
(56439, 2, 0, '네가 얼마나 무력하게 무너졌는지 봐라.'),
(56439, 2, 1, '네 안에 도사린 어둠에 굴복해라.'),
(56439, 3, 0, '모두 끝이다.'),
(56439, 4, 0, '모든 희망을 버려라.'),
(56439, 4, 1, '절망을 받아들여라.'),
(56448, 0, 0, '물이 당신의 몸에 닿자 격렬하게 반응합니다!'),
(56448, 1, 0, '감히 신성한 물을 휘젓다니! 익사시켜주마!'),
(56448, 2, 0, '깨어나라!'),
(56448, 2, 1, '물이여, 살아 움직여라!'),
(56448, 2, 2, '살아있는 물이여, 이들을 처치해라!'),
(56448, 2, 3, '도망치지 마, 결과는 똑같을 테니.'),
(56448, 2, 4, '들어와. 물이 딱 좋아!'),
(56448, 2, 5, '죽음에 휩쓸려라.'),
(56448, 3, 0, '격류의 위력을 느껴봐라!'),
(56448, 4, 0, '%s|1이;가; 주위의 물에서 힘을 끌어냅니다!'),
(56448, 5, 0, '어둠이 걷힌다...'),
(56448, 6, 0, '물을 들여다봤지만 내 모습이 비치지 않더군...'),
(56448, 7, 0, '물이여... 날 받아다오...'),
(56448, 8, 0, '헛된 희망이다.'),
(56448, 8, 1, '물의 말대로군.'),
(56485, 0, 0, '미안해요. 아직 돌아갈 순 없어요.'),
(56485, 1, 0, '그 골짜기를 찾아보겠어요. 신성한 웅덩이가 지닌 치유의 힘에 대해 알아봐야 해요.'),
(56485, 2, 0, '미안해요. 그럴 순 없어요. 이해해 주실 거라고 믿어요.'),
(56485, 3, 0, '자, 가시죠.'),
(56488, 0, 0, '안두인 왕자님, 집에 가실 시간입니다.'),
(56488, 1, 0, '어서 가시지요.'),
(56488, 2, 0, '네? 어... 음... 그렇죠, 안두인 왕자님. 마음대로 가십시오.'),
(56488, 3, 0, '어? 어떻게 된 거야?'),
(56488, 4, 0, '뭐어어? 어떻게 그러실 수가 있어!'),
(56488, 5, 0, '이렇게 교활한 분이셨나?! 전혀 몰랐네!'),
(56503, 0, 0, '샹 사부님께 잘 배웠군. 고맙소, 친구!'),
(56503, 1, 0, '나 혼자서는 물리치지 못했을 거요. 실례지만, 이제 수레를 찾으러 가야겠소.'),
(56503, 2, 0, '수레야!'),
(56503, 3, 0, '안녕, 수레야. 아직도 뒤집혀 있구나.'),
(56511, 0, 0, '%s|1이;가; 분수에서 나타납니다!'),
(56541, 0, 0, '네 이놈들! 너희가 잠들어 있던 샤를 깨운 놈들이로구나!'),
(56541, 1, 0, '너희가 진정으로 우리 땅에 불러온 재앙을 막고자 한다면 먼저 스스로의 능력을 증명해 보이거라.'),
(56541, 2, 0, '먼저, 우리 신입생들을 상대해 봐라...'),
(56541, 3, 0, '갓 들어온 신참들보다는 강하구나. 그럼 우리의 상급생 둘을 상대해 봐라.'),
(56541, 4, 0, '비설! 연향! 앞으로 나오거라!'),
(56541, 5, 0, '가장 특출난 수련생 둘을 쓰러뜨리다니. 진정 우리에게 도움이 될 수 있겠구나...'),
(56541, 6, 0, '언젠가 사부님이 말씀하셨지, ''진정 상대를 알고 싶다면 싸워봐야 한다.''고...'),
(56541, 7, 0, '따라오거라. 우릴 정식으로 소개할 터이니.'),
(56541, 8, 0, '좋다, 이방인들이여. 이제 너희의 진짜 힘을 보여다오.'),
(56541, 9, 0, '나의 패배다. 조금 있다가 함께 샤를 상대하러 가자꾸나.'),
(56541, 10, 0, '훈련이 부족하다!'),
(56541, 10, 1, '기술을 더 연마하거라.'),
(56541, 11, 0, '무기를 사용하는 기술은 무력의 물리적 표출에 지나지 않지. 내가 정신력의 진가를 보여주마!'),
(56541, 12, 0, '내가 풋내기였던 시절에는 정권 지르기 한 번도 버거웠다. 하지만 수년간 뼈를 깎는 수련을 거듭한 지금은 달라!'),
(56541, 13, 0, '한 명이 쓰러지면 다른 수련생이 그 자리를 대신할 것이다.'),
(56541, 13, 1, '샤에게서 백성들을 지키려면 아직 갈 길이 먼 것 같구나. 네 동료들이 싸울 수 있게 물러서거라!'),
(56589, 0, 0, '궁수들을 장벽에서 계속 떨어뜨려. 라이곤이 문으로 가야 한다.'),
(56589, 1, 0, '시체를 탑 밑으로 떨궈주마!'),
(56589, 2, 0, '우리 병력은... 끝이 없다! 너흰... 이길 수 없어...'),
(56589, 3, 0, '이길 수 없는 전투였어.'),
(56589, 3, 1, '제공권에서 밀려.'),
(56589, 3, 2, '예상대로군.'),
(56636, 0, 0, '살아 나갈 생각은 버려라.'),
(56636, 1, 0, '폐하... 용서하십시오.'),
(56636, 2, 0, '곧 문이 무너진다. 어서! 이 방해꾼들을 쓸어버려!'),
(56636, 3, 0, '하하하하하!'),
(56636, 3, 1, '여기가 네 무덤이다!'),
(56636, 3, 2, '감히 우리에게 맞서다니!'),
(56637, 0, 0, '누가 우끼 잔치 망쳐!?'),
(56637, 1, 0, '나 너 응가에 우끼해버린다!'),
(56637, 2, 0, '우끼 잔치를 시작하자!'),
(56637, 2, 1, '우끼해봐라!'),
(56637, 2, 2, '밤새도록 우끼우끼!'),
(56637, 4, 0, '우... 우... 우우우우끼...'),
(56660, 0, 0, '사부님은 어디 계셔?'),
(56660, 1, 0, '아... 그렇게 희망을 짓밟지 마요. 사부님이 보고 싶을 거란 말이에요.'),
(56660, 2, 0, '내가 언제는 안 공손했나요? 나 상처 받았어요, 아이사.'),
(56660, 3, 0, '가시라고? 족집게를 집에 두고 왔는데 어쩌나.'),
(56660, 4, 0, '대체 뭐길래 이런 덩치가 그렇게 아파하는 거지?'),
(56660, 5, 0, '내 눈이 이상한 건가?! 저거, 배야?!'),
(56660, 6, 0, '게다가 저 녀석들, 판다렌이 아냐. 털이 없어.'),
(56663, 0, 0, '혹시 숲을 산책하고 싶으면, 나는 아이사랑 여기 있을게. 알겠지...? 단 둘이서 말이야.'),
(56664, 0, 0, '꼭 그런 것만은 아니오. 내 생각에... 그래... 그 방법이라면.'),
(56664, 1, 0, '영원의 눈 속 집중의 눈동자를 사용하면, 용의 영혼에 담긴 마법의 힘을 하나로 집중할 수 있을 거요.'),
(56664, 2, 0, '그럼 내가 영원의 눈으로 가는 길을 열겠소. 실패해선 안 됩니다, 영웅들이여. 아제로스의 미래가 그대들에게 달렸습니다.'),
(56664, 3, 0, '잘하셨습니다! 지금 당장 의식을 시작하지요!'),
(56664, 4, 0, '비전 바람이여, 저들의 뒤를 받쳐라. 역경을 헤치는 용사들을 회복시켜라!'),
(56664, 5, 0, '|TInterface\\Icons\\inv_misc_head_dragon_blue.blp:20|t 칼렉고스가 |cFF0000FF|Hspell:105903|h[마법의 원천]|h|r을 소환합니다!'),
(56666, 0, 0, '어느 정도는 예상했다.'),
(56666, 1, 0, '시간의 순환은 모든 것의 끝을 불러오리니.'),
(56666, 2, 0, '|TInterface\\Icons\\inv_misc_head_dragon_bronze.blp:20|t 노즈도르무가 |cFFFFFF00|Hspell:105984|h[시간의 고리]|h|r로 당신을 강화합니다!'),
(56667, 0, 0, '소용없네. 용의 영혼이 가진 힘이 너무 강력해, 안전하게 다룰 수 없네. 이 안의 혼돈의 힘이 모두에게 파멸을 가져올지도 모른다네.'),
(56667, 1, 0, '그렇군요. 마침내 데스윙의 힘을 고스란히 놈에게 돌려줄 수 있겠습니다.'),
(56667, 2, 0, '선택권이 없습니다. 우리편을 믿는 수 밖에.'),
(56667, 3, 0, '영웅들이여, 또다시 큰일을 맡기게 됐군.'),
(56667, 4, 0, '우리가 영혼에 아제로스 위상의 힘을 불어넣는 동안, 자네들은 데스윙의 병력으로부터 우릴 보호해야 하네.'),
(56667, 5, 0, '수호할 준비가 되면 내게 말을 걸게.'),
(56667, 6, 0, '대지의 힘이여, 내 부름을 들어라! 아제로스의 마지막 수호자들을 어두운 시간으로부터 보호해다오!'),
(56667, 7, 0, '타레사... 케른... 아그라... 절대 실망시키지 않겠소. 절대 이 세상을 포기하지 않겠소!'),
(56667, 8, 0, '|TInterface\\Icons\\inv_misc_head_dragon_black.blp:20|t 스랄이 대지의 힘으로 방어 담당자를 강화합니다! 당신은 |cFF9900CC|Hspell:106218|h[아제로스의 마지막 수호자]|h|r입니다!'),
(56676, 0, 0, '리우 랑의 후손들이 나를 잊지 않았다니 고통스러운 중에도 마음이 따뜻해지는구나.'),
(56676, 1, 0, '옆구리에 가시가 박혔는데, 뺄 수가 없다.'),
(56676, 2, 0, '너무 고통스러워서 참을 수가 없다. 똑바로 헤엄칠 수가 없어.'),
(56676, 3, 0, '후손들이여, 부디 이 가시를 빼 주겠나? 나 혼자서는 뺄 수가 없다.'),
(56676, 4, 0, '너희 발이 닿지 않는 숲 속에 있다. 산맥을 따라 계속 가다 보면 찾을 수 있을 것이다.'),
(56676, 5, 0, '고맙다, 후손들이여.'),
(56686, 0, 0, '우리는 3천 년 동안 민족의 지혜를 계승했다네. 늙은이에게서 젊은이에게로, 또 사부에게서 제자에게로.'),
(56686, 1, 0, '늙은이는 모두 떠나야 할 날이 온다네. 그날 자기 지팡이를 조상의 지팡이 사이에 꽂지. 오늘이 내 지팡이가 이 숲에 꽂히는 날일세.'),
(56686, 2, 0, '우리 민족은 대대손손 이 거대한 거북 셴진 수 위에 살아 왔다네. 하지만 수백 년 동안 아무도 그와 이야기를 한 적이 없지.'),
(56686, 3, 0, '지금은 셴진 수가 아프고, 우리 모두가 위험하다네. 정령들의 도움을 받으면 오랜 침묵을 깰 수가 있네. 자네가 거북과 이야기를 하게.'),
(56686, 4, 0, '아이사와 지가 네 정령을 이곳으로 데리고 왔다네. 함께 가서 위대한 셴진 수와 이야기를 하고, 우리 민족을 구할 길이 있다면 그대로 따르게.'),
(56686, 5, 0, '참 먼 길을 왔네, 젊은 제자여. 자네에게서는 영웅의 싹이 보이네. 이 땅의 운명을 자네에게 맡기겠네.'),
(56719, 0, 0, '또다시 갇힐 순 없어. 음영파는 날 막을 수 없다. 그건 네 놈도 마찬가지지!'),
(56719, 1, 0, '네 가슴이 폭력에 물들어 있는 한... 난... 다시... 돌아올 것이다.'),
(56719, 2, 0, '폭력에 의한 죽음...'),
(56723, 0, 0, '여기가 어디지? 우리가... 공격하고 있었어?!'),
(56723, 0, 1, '무슨 일이지? 왜 이렇게 빨리 공격하는 거야?'),
(56742, 0, 0, '저 봉화에 불을 붙여야 하네. 지원군이 없으면 놈들이 문을 부술 거야!'),
(56743, 0, 0, '하지만 사마귀들이 이 지역을 점령했어. 갈 방법이 없네!'),
(56745, 0, 0, '걱정마세요! 제가 해볼게요!'),
(56747, 0, 0, '내 힘을 보여주마.'),
(56747, 1, 0, '와라, 용이여! 함께 이 침입자들을 처치하자.'),
(56747, 2, 0, '힘을... 합쳤는데도... 지다니...'),
(56747, 3, 0, '기력이 충만한 놈들이군!'),
(56747, 4, 0, '안 돼! 날 실망시키지 마!'),
(56747, 5, 0, '아자! 약골들... 이 손님들은 내가 맡을 테니 썩 꺼져.'),
(56747, 6, 0, '하하하. 다가와라... 죽음이 너희를 기다린다.'),
(56747, 7, 0, '용이여, 네 힘으로 날 채워라!'),
(56747, 8, 0, '약골 녀석!'),
(56747, 8, 1, '번개에게 자비란 없다!'),
(56762, 0, 0, '의심에서 벗어나렴...'),
(56782, 0, 0, '이봐요, 낯선 분! 쉿! 이리 와 보세요!'),
(56840, 0, 0, '나즈그림이 리코 좋아할 거다! 여기! 보고서 끝!'),
(56843, 0, 0, '이봐 거기! 거기 자네들! 내 신성한 도서관이 샤의 손아귀에 넘어갔네!'),
(56843, 1, 0, '놈들이 이 신성한 두루마리의 글자들에서 쏟아져 나오고 있어... 변질시키고, 더럽히고 있네!'),
(56843, 2, 0, '내 이리 비네, 이방인이여. 이곳에 넘치는 샤의 사악함을 정화해주게! 우리 이야기들을 쉬게 해줘!'),
(56843, 3, 0, '타락의 원천을 파괴해야 하네! 서두르게, 우리 소중한 역사가 지워지기 전에 막아야 해!'),
(56843, 4, 0, '오. 내 생각이 맞다면, 짜오 선시커의 전설이 우리 눈 앞에서 펼쳐지는 것 같군.'),
(56843, 5, 0, '전설에 따르면, 먼 옛날 하늘에는 밝게 타오르는 해가 다섯 개나 있었다고 하네. 바람이 불 때면 그 강렬한 화염이 불난리를 피웠다고 하지.'),
(56843, 6, 0, '작물은 시들고, 마을은 불탔으며, 사람들은 불을 피해 쉴 새 없이 떠돌아 다녀야만 했네.'),
(56843, 7, 0, '불이 도서관을 태우고 있네! 부탁일세, 영웅들이여! 사원이 잿더미가 되기 전에 이곳의 악을 몰아내주게!'),
(56843, 8, 0, '짜오도 타락해 버린 건가? 부탁이네. 부디 예를 갖춰 싸워주게...'),
(56843, 9, 0, '아, 아직 끝나지 않았네. 내가 보기엔 아직 야운골의 시험이 남았네. 내가 실마리를 주지...'),
(56843, 10, 0, '전설에 따르면, 야운골은 쿤라이 평원을 가로질러 가다, 갑자기 두 이상한 괴물의 습격을 받게 됐다네!'),
(56843, 11, 0, '야운골은 맹렬히 괴물들을 공격했지. 하지만 그가 공격을 거듭할수록 괴물은 더 무시무시하게 커졌다네!'),
(56843, 12, 0, '하지만 그가 공격을 멈추자, 괴물은 거의 무에 가까울 정도로 작아졌지.'),
(56843, 13, 0, '이처럼 불화는 분쟁을 먹고 살지. 자신의 가슴 속이 평화롭다면, 불화는 다른 대상을 찾아 배회한다네.'),
(56846, 0, 0, '|TInterface\\Icons\\ability_warrior_bloodnova.blp:20|t %s의 상처에서 |cFFFE9A2E열기 촉수|r가 돋아납니다!'),
(56846, 10, 0, '|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s|1이;가; |cFFFF0000|Hspell:105863|h[과다출혈]|h|r을 일으킵니다!'),
(56877, 0, 0, '%s의 |cFFFF0000약점|r이 노출되었습니다! 약점에 공격을 집중해 뚫리지 않는 껍질을 파괴하십시오!'),
(56877, 1, 0, '|cFFFE9A2E크리티크 무리 인도자|r 추가 병력이 전투에 합류합니다!'),
(56877, 2, 0, '위쪽에 |cFFFE9A2E크릭티크 휘몰이|r 추가 병력이 나타납니다!'),
(56877, 3, 0, '|cFFFE9A2E크릭티크 보호자|r 추가 병력이 나타납니다!'),
(56884, 0, 0, '타란 주와 음영파는 내 거다. 다가와서 내 손에 죽어라. 앞으로 내게 맞서고 최후를 맞이할 모든 이들처럼!'),
(56884, 1, 0, '증오가 모두를 잠식하고 지배하리라!'),
(56884, 2, 0, '안 돼... 안 돼!'),
(56884, 3, 0, '네 패배에 분개하라!'),
(56884, 4, 0, '증오의 샤가 내 몸에서는 물론, 수도원에서도 도망쳤네. 정말 고맙네, 이방인이여. 음영파가 자네에게 빚을 졌군. 자, 이제부터 할 일이 아주 많다네...'),
(56906, 0, 0, '문? 이 장벽을 다 가루로 만들어주마!'),
(56906, 1, 0, '폭탄은 충분하니... 선물로 줄게!'),
(56906, 2, 0, '붐 샤칼라카!'),
(56906, 2, 1, '내가 바로 폭사마...귀!'),
(56906, 2, 2, '네가 망쳤어!'),
(56906, 3, 0, '아... 망했다...'),
(56906, 4, 0, '네가 폭탄이다!'),
(56906, 4, 1, '이놈은 폭탄이 될 거다.'),
(56906, 4, 2, '널 날려버릴 테지... 펑!'),
(56906, 4, 3, '펑! 폭발! 압도적인 힘!'),
(56906, 4, 4, '폭탄 나가신다!'),
(57120, 0, 0, '아, 저는 잘 모르겠군요. 제가 나이도 들고 또 항상...'),
(57120, 1, 0, '조심하십시오! 사마귀 놈들입니다!'),
(57120, 2, 0, '다시 생각해봤습니다... 여기에 있기에는 너무 위험하군요. 목숨을 걸 정도로 땅이 소중하지는 않으니까요. 어디 그 대피 명령서 좀 보여주십시오.'),
(57121, 0, 0, '맞는 말입니다. 자, $r님, 이제 우리 것을 스스로 지켜내도록 해주십시오.'),
(57155, 0, 0, '이날이 올까 봐 두려움에 떨고 있었습니다. 어서 짐을 챙겨야겠군요.'),
(57161, 0, 0, '알겠습니다. 전쟁이 끝날 때까지 기다렸으면 좋겠지만, 사령관님께서 우리가 떠나기를 원하신다면 그렇게 하겠습니다.'),
(57161, 1, 0, '당신은 짐을 챙기시오. 후이종도... 어서 짐을 챙기거라. 안전해질 때까지 밭에서 떠나야겠다.'),
(57161, 2, 0, '잘 모르겠구나, 애야...'),
(57161, 3, 0, '그래주실 겁니까?'),
(57183, 0, 0, '%s|1이;가; 한숨을 내쉽니다.'),
(57183, 1, 0, '$c님, 저는 농부입니다. 농사 빼고는 제가 아는 게 뭐가 있겠습니까.'),
(57183, 2, 0, '우리는 가진 거라고는 땅이 전부입니다. 그런데도 사령관님께서는 우리 보고 이 땅을 사마귀 놈들에게 양보하라는 겁니까?'),
(57183, 3, 0, '저는 안 그럴 겁니다. 할아버지께서 용의 척추 가까운 곳에 처음 씨앗을 심었을 때 어떤 문제가 생길지 이미 알고 계셨거든요.'),
(57183, 4, 0, '저는 아내가 있고, 강인한 딸과 아들도 둘씩이나 있습니다. 말씀은 감사합니다만 우리 밭은 우리가 지킬 수 있습니다.'),
(57298, 0, 0, '엘라가 쓸 무를 찾으신다고요? 네, 제가 남는 게 하나 있습니다. 여기 있습니다.'),
(57319, 0, 0, '머리 속에서 계속 이상한 목소리가 들리는군. 걱정해야 할 일인가?'),
(57319, 0, 1, '왜 이렇게 열심히 노력해야 하는 거지? 결국 아무 의미도 없을 텐데...'),
(57319, 0, 2, '내 방어구가 몸에 너무 꽉 끼나?'),
(57319, 0, 3, '주위 사람들은 모두 나를 좋아하는 척할 뿐이다.'),
(57319, 0, 4, '아무것도 변하지 않을 거야.'),
(57319, 0, 5, '난 알아... 내가 걱정하는 일이 일어나고 말 거야.'),
(57319, 0, 6, '대체 사람들이 나에 대해 뭐라고 할까?'),
(57319, 0, 7, '난 왜 늘 이렇게 외로운 거지? 역시... 혼자이기 때문일까?'),
(57385, 0, 0, '그러고는 싶지만, 제가 잡초 때문에 조금 골치가 아픕니다. 그... 저 좀 조금 도와주시겠지요? 그죠?'),
(57402, 0, 0, '엘라가 맥주 양조를 처음으로 시도해본다고? 허, 그거 놀랍군! 행운을 빌어줘야겠네. 알겠지만, 맥주 양조는 초보자가 금방 따라 할 수 있는 게 아니라네. 어쨌든 여기 남는 호수멜론 하나 주겠네.'),
(57638, 0, 0, '노래하는 웅덩이에 자라는 갈대는 이 땅에서 가장 단단하지만, 내 강한 이마 앞에서는 공기나 마찬가지요.'),
(57638, 1, 0, '많은 이들이 이런 내 말을 시험하려 들었지만, 나는 항상 증명해 보였다오.'),
(57669, 0, 0, '우리 장인들이 만드는 나무판자는 최고급이라오. 아무리 심한 폭풍에도 끄떡하지 않지. 하지만 내 폭풍 같은 머리통 앞에서는 물이나 마찬가지요.'),
(57669, 1, 0, '판다렌의 손으로 만든 것은 내 힘을 당할 수가 없다오.'),
(57670, 0, 0, '이것은 셴진 수에서 가장 단단한 돌이지만, 내 무지막지한 머리통 앞에서는 아무것도 아니라오.'),
(57670, 1, 0, '아직도 내 힘을 의심하는 자는 멍청한 자요.'),
(57681, 0, 0, '이 안에 얼마나 갇혀 있었는지 모르실 겁니다.'),
(57681, 0, 1, '감사합니다!'),
(57681, 0, 2, '그놈이 다시 돌아오기 전에 여기를 벗어나는 게 좋을 겁니다!'),
(57681, 0, 3, '맥주통에 영원히 갇히는 것보다 더 고통스러운 운명이 있을까 싶군요.'),
(57681, 0, 4, '윽! 빛 때문에... 눈이 아프군요.'),
(57681, 0, 5, '드디어!'),
(57692, 0, 0, '이건 정말 놀라운걸! 대단한 장인의 솜씨요.'),
(57692, 1, 0, '답은 하나요. 부숴 버려야지! 모두가 대번에 내 무지막지한 머리통의 힘을 알게 될 거요.'),
(57692, 2, 0, '아... 내 머리... 너무 아파! 난... 이 기둥에는 엄청난 힘이 깃들어 있는 게 분명하오... 내 이마보다 더 강한 힘이...'),
(57692, 3, 0, '나... 나는 잠시 누워 있어야겠소... 이 두통이 사라질 때까지.'),
(57712, 0, 0, '안녕하시오, 친구! 필요하다면 내 수레를 써도 좋소. 수레를 타면 다이로 농장으로 갈 수 있소.'),
(57712, 1, 0, '안녕하시오, 친구! 필요하다면 내 수레를 써도 좋소. 수레를 타면 다섯 새벽 사원으로 갈 수 있소.'),
(57720, 0, 0, '네... 그게 좋을 거 같네요. 지금까지는 호드가 마음에 들고, 제 힘이 그 세상에 도움이 될 거 같거든요.'),
(57802, 0, 0, '하, 암살자라! 누가 보냈지? 불어라. 안 그러면 네 시체에서 대답을 얻어내겠다!'),
(57802, 1, 0, '이 변장도 이젠 지겹군. 그만 끝내자!'),
(57802, 2, 0, '누구의... 사주로... 이런 짓을...?'),
(58202, 0, 0, '도와주세요!'),
(58202, 0, 1, '으으으음...'),
(58202, 0, 2, '사마귀가 장벽을 넘어오고 있습니다!'),
(58206, 0, 0, '저것 봐요. 저 꼬마가 당신을 위해 정화된 물을 남겼네요.'),
(58224, 0, 0, '우리의 권능 앞에 무릎 꿇기를 거부하느냐? 그렇다면 벌레같이 죽어라.'),
(58506, 0, 0, '좋습니다. 아가씨들, 내 실력 좀 보라고!'),
(58506, 1, 0, '제법인데요! 앞으로 당신을 눈여겨봐야겠습니다.'),
(58508, 0, 0, '서로 봐주기 없습니다!'),
(58508, 1, 0, '또 지다니! 훈련을 더 해야겠습니다.'),
(58511, 0, 0, '시작합시다. 행운을 빕니다.'),
(58511, 1, 0, '저보다 크게 앞서셨군요. 잘하셨습니다.'),
(58547, 0, 0, '눈 똑바로 뜨고 바짝 붙어 오십시오.'),
(58547, 1, 0, '야영지가 바로 앞입니다. 이제부터는 우리끼리 갈 수 있습니다.'),
(58606, 0, 0, '멈춰라, 노예! 이 물은 천둥왕의 소유다. 이곳은 네놈이 올 곳이 아니다.'),
(58606, 1, 0, '수호자들이여! 침입자를 처치하라.'),
(58608, 0, 0, '영웅이여, 이 은혜를 절대 잊지 않겠습니다.'),
(58608, 0, 1, '$p 님, 너무 감사합니다!'),
(58608, 0, 2, '감사합니다! 놈들이 우리를 노예로 삼을 거라고 했습니다.'),
(58608, 0, 3, '놈들이 노예와 무기를 찾고 있다고 했습니다.'),
(58632, 0, 0, '하하! 또 내 용맹을 시험할 기회인가.'),
(58632, 1, 0, '지다니... 이딴 놈들에게...'),
(58632, 2, 0, '하하!'),
(58632, 3, 0, '칫! 이게 최선이냐?'),
(58632, 4, 0, '방어 태세를 갖춰라!'),
(58639, 0, 0, '영웅이여, 이 은혜를 절대 잊지 않겠습니다.'),
(58639, 0, 1, '$p 님, 너무 감사합니다!'),
(58639, 0, 2, '감사합니다! 놈들이 우리를 노예로 삼을 거라고 했습니다.'),
(58639, 0, 3, '놈들이 노예와 무기를 찾고 있다고 했습니다.'),
(58646, 0, 0, '우와... $n 님, 맥주 맛이 정말 좋군요. 한 두잔 더 마셔도 괜찮겠... 딸꾹!'),
(58666, 0, 0, '코르! 안 돼애애애애애!'),
(58666, 1, 0, '오늘은 피차 많은 것을 잃은 것 같다, 늙은 엘프. 시신을 수습하지.'),
(58710, 0, 0, '우와! 이거 정말 끝내주는군요! 더 마시려면 어디로 가야 합니까?'),
(58712, 0, 0, '물론입니다, $n 님! 즐기십시오!'),
(58717, 0, 0, '아무 때나 가져오십시오, 언제라도 괜찮습니다.'),
(58717, 1, 0, '흠, 정말 끝내주는 맛이군요! 훌륭합니다! 이렇게 훌륭한 맥주는 정말 오랜만에 마셔보는군요. 누가 양조한 겁니까?'),
(58718, 0, 0, '처음 드리는 씨앗 봉투는 무료입니다! 씨앗을 더 사려면 언제든지 다시 들러주십시오.'),
(58740, 5, 0, '블랜치의 원기회복의 비약 안에 서 있으면 생명력과 마나가 회복됩니다!'),
(58740, 19, 0, '폭발 맥주를 사용해 사우록 졸개에게 충격을 가하십시오!'),
(58745, 0, 0, '자, 운명의 순간이군.'),
(58745, 1, 0, '으아아아아아아악!'),
(58745, 2, 0, '아... 아프구나...'),
(58777, 0, 0, '배에 불이 붙었다! 병사들이여, 항구로!'),
(58777, 1, 0, '발드럭의 폭풍 토템을 피하거나 파괴하십시오.'),
(58787, 0, 0, '무적의 베사의 시야에서 벗어나십시오.'),
(58816, 0, 0, '아, 올 때가 됐다 싶었죠. 날 풀어줄 겁니까, 아니면... 다른 계획이라도?'),
(58816, 1, 0, '위층에 있는 경비대장 헤드릭 이븐케인에게 열쇠가 있을 겁니다. 서두르십시오. 아시다시피 시간이 없습니다!'),
(58816, 2, 0, '감사합니다! 이제 이 우울한 섬에서 나가 볼까요?'),
(58816, 3, 0, '공성 "실패"는 물론 속임수였습니다. 설마... 몰랐습니까?'),
(58816, 4, 0, '비전 장비를 실은 우리 비행선이 도착하면, 모두가 섬과 함께 박살이 날 겁니다.'),
(58816, 5, 0, '됐군요. 혹시라도 실버문을 지나면 한번 들르십시오. 알 디엘 샬라...'),
(58826, 0, 0, '이대로 놔둘 순 없어!'),
(58826, 1, 0, '뜨거운 열기에 내 감각이 무뎌진 게 틀림없어... 환영들이여! 사라져라!'),
(58840, 0, 0, '%s|1이;가; 검과 방패를 들어 올립니다.'),
(58840, 1, 0, '%s|1이;가; 방패를 내려놓고 단검을 뽑아 듭니다.'),
(58870, 0, 0, '상상도 못할 일이 일어났다. 테라모어 공성 작전이 실패했다.'),
(58870, 1, 0, '자네가 우리의 비상 대책이다. 자네 임무는 테라모어 섬에 침투하는 것이다.'),
(58870, 2, 0, '적함을 태워라. 비행 조련사를 도륙하고 전쟁 병기를 파괴해라. 그리고 우리 첩자를 구출하라!'),
(58875, 0, 0, '오 이런, 손님들이 오신 것 같군! 친구들이냐, 보스?'),
(58875, 1, 0, '이들의 죽음은 내 소환사들을 더 강하게 할 뿐이다! 잘 봐라!'),
(58875, 2, 0, '왜 그러냐, 보스? 이제 좀 지쳐?'),
(58875, 3, 0, '아름답지 않나? 이 살점과 뼈, 그리고 영혼의 향연!'),
(58875, 4, 0, '너도 아름다워, 보스. 최근에 거울을 본 적 있나?'),
(58875, 5, 0, '얘야, 너에게 내려진 이 축복을 순순히 받아들이거라.'),
(58875, 6, 0, '와라, 보스. 운명이 널 기다린다.'),
(58918, 0, 0, '당신이 찾은 건...'),
(58918, 1, 0, '당황한 암탉입니다! 닭장으로 되돌려보내십시오!'),
(58918, 2, 0, '야생 초원닭입니다! 이곳에서 쫓아내십시오!'),
(58918, 3, 0, '닭털로 변장한 마모트입니다! 속임수를 쓴 마모트임을 밝혀내십시오!'),
(58918, 4, 0, '구애하는 수탉입니다! 물에 담가 진정시키십시오.'),
(58918, 5, 0, '늙은 힐포우의 가축 대회 입상 닭, 엄마 꼬꼬댁!'),
(58918, 5, 1, '늙은 힐포우의 가축 대회 입상 닭, 밑둥반점 부인!'),
(58918, 5, 2, '늙은 힐포우의 가축 대회 입상 닭, 천둥쪼기!'),
(58918, 5, 3, '늙은 힐포우의 가축 대회 입상 닭, 맨티스배인!'),
(58918, 5, 4, '늙은 힐포우의 가축 대회 입상 닭, 부들닭털!'),
(58918, 5, 5, '늙은 힐포우의 가축 대회 입상 닭, 에가!'),
(58918, 5, 6, '늙은 힐포우의 가축 대회 입상 닭, 비실날개!'),
(58918, 5, 7, '늙은 힐포우의 가축 대회 입상 닭, 벌레잡이 베티!'),
(58930, 0, 0, '바깥쪽 정찰로 안쪽으로 겨우 들어갔을 때 적에게 사로잡혔습니다. 그래서 아무것도 알아내지 못했지요.'),
(58930, 1, 0, '적의 지도자를 봤습니다. 장벽 위쪽으로 올라가고 있었어요. 그 위치를 지도에 표시해 드리겠습니다.'),
(58930, 2, 0, '고맙습니다. 면목 없게도, 아무것도 알아내지 못하고 잡혀 버렸습니다.'),
(58930, 3, 0, '저는... 실패했습니다. 구하러 와 주셔서 감사합니다.'),
(58955, 0, 0, '우리가 사마귀들과 싸우다가 후퇴하려고 할 때, 모구가 기습해 왔습니다.'),
(58955, 0, 1, '저는 돌밭으로 가야만 합니다! 사마귀들이 곧 공격해 올 겁니다.'),
(58955, 0, 2, '감사합니다, 영웅이여.'),
(58955, 0, 3, '감사합니다, 이방인이여.'),
(58970, 0, 0, '나는 오랫동안 삶을 연장하는 법을 찾는 데 급급해, 정작 제대로 된 삶을 살지 못했다네.'),
(58970, 1, 0, '결국 그... 어리석음 때문에... 딸이 목숨을 잃었네.'),
(58970, 2, 0, '이 물로 생명을 창조할 수는 없겠지만, 내 생명을 옮길 수는 있겠지.'),
(58970, 3, 0, '사랑한다. 예쁜 내 딸 리알리아.'),
(58975, 0, 0, '이젠 어쩔 거냐, 태양길잡이?'),
(58975, 1, 0, '찬성이다.'),
(58975, 2, 0, '리알리아! 정말 미안하구나, 얘야.'),
(59074, 0, 0, '그래 그래 그래! 조금만 더! 아주 살짝만... 허이구야...'),
(59074, 1, 0, '너무 써! 벌꿀 한 방울, 사탕수수 이 정도, 그리고 옥수수? 그래, 옥수수야!'),
(59074, 2, 0, '그래, 그래, 그래... 아냐, 아냐, 아냐 아냐! 그래! 아냐! 후추!'),
(59074, 3, 0, '악! 도와줘! 이건 뭐야!? 에이, 상관없어. 지금은 아무도 날 막지 못해. 이제 거의 완성인걸! 쳐다보지만 않으면 괜찮겠지...?'),
(59074, 4, 0, '설마... 이것은???'),
(59074, 5, 0, '감미로운 맛의 조화, 강렬하고 진한 향! 이것이... 완벽한 맥주다!'),
(59074, 6, 0, '스톰스타우트의 명성이 다시 한 번 온 세상에 울려 퍼질 것이다!'),
(59074, 7, 0, '모르겠나? 내가 우리 명예를 되찾았어! 완벽한 맥주를 만들었다고!'),
(59074, 8, 0, '별일도 아닌데 집착하시긴.'),
(59074, 9, 0, '이보게, 첸 스톰스타우트. 우리 모두가 영웅이 된답시고 본분을 저버리고 공포의 황무지를 뛰어다니며 세계를 구할 순 없네. 우리 중 어떤 이들은... "예술가"야.'),
(59074, 10, 0, '그래, 그래, 그래. 그런 일도 생기지.'),
(59080, 0, 0, '수업을 시작하지!'),
(59080, 1, 0, '녀석.'),
(59080, 2, 0, '수업... 끝.'),
(59080, 3, 0, '|TInterface\\Icons\\inv_misc_book_01.blp:20|t%s|1이;가; $n에게 |cFFFF0000|Hspell:113395|h[혹독한 가르침]|h|r을 내립니다!'),
(59143, 0, 0, '신세를 졌소.'),
(59143, 0, 1, '빈안 마을을 구하기 위해 다시 싸움을 시작해야겠소.'),
(59143, 0, 2, '샤오하오 황제께서 당신을 보내신 게 분명합니다.'),
(59143, 0, 3, '야운골 놈들을 탕랑 평원으로 쫓아 보내야 합니다.'),
(59143, 0, 4, '낯선 이여, 그대는 매우 영예로운 분이시군요. 저희와 함께해 주십시오.'),
(59143, 0, 5, '감사합니다. 당신은 제 생명의 은인이십니다.'),
(59143, 0, 6, '함께 싸웁시다, $c. 당신이 있으면 힘이 될 거요.'),
(59143, 0, 7, '치유력이 대단하군요!'),
(59150, 0, 0, '모두 불태울 거야. 아무도 붉은십자군의 치욕을 알아선 안 돼!'),
(59150, 1, 0, '너도 잿더미가 되어야 한다!'),
(59150, 2, 0, '불로 속죄하라!'),
(59150, 3, 0, '|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s|1이;가; |cFFFF0000|Hspell:113364|h[책 불태우기]|h|r를 시전합니다!'),
(59150, 4, 0, '|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t%s|1이;가; |cFFFF0000|Hspell:113653|h[거대 용의 숨결]|h|r을 시전합니다!'),
(59150, 5, 0, '내 불이... 꺼졌다...'),
(59153, 0, 0, '들창엄니!'),
(59153, 1, 0, '뼈 무더기를 클릭하여 뼈 쐐기 공격을 막아내십시오!'),
(59163, 1, 0, '표적을 방패로 써야 합니다!'),
(59191, 1, 0, '계속 쏴라! 모두 처치해!'),
(59191, 2, 0, '또 처치했군. 봐주지 마라!'),
(59191, 3, 0, '병사들이여 검을 준비하라!'),
(59223, 0, 0, '내가 널 부숴주마.'),
(59223, 1, 0, '넌... 마치... 쇳덩어리 같군...'),
(59223, 2, 0, '죽으라면 죽어.'),
(59223, 3, 0, '내 주먹이 빨갛구나... 네 피 덕분에!'),
(59303, 0, 0, '아! 개들에게 줄 신선한 고기들!'),
(59303, 1, 0, '이건 피?... 하하... 하지만 난 죽지 않아!'),
(59303, 2, 0, '뭐야?! 안 돼... 안 돼! 멈춰! 주인 말을 들어!'),
(59303, 3, 0, '내가 개들을 풀어줬지!'),
(59303, 4, 0, '아! 멍청한 놈들! 이 약골들을 처치하고 나면 너희 차례다.'),
(59305, 0, 0, '보고할 준비가 됐어, $n! 뭐, 딱히 자랑할 생각은 없지만, 나즈그림 장군님께서 내 작품을 보시면 꽤나 기분이 좋으실 거야.'),
(59368, 0, 0, '피, 피, 피, 피, 피!!'),
(59368, 0, 1, '피를 줘!'),
(59368, 0, 2, '그래! 그래! 피를 더 내놔!'),
(59368, 1, 0, '이 피 냄새... 너무 달콤해!'),
(59483, 0, 0, '멍청한 것! 뭉개 버릴 테다!'),
(59483, 7, 0, '당신은 |cFFFF0404|Hspell:116784|h[야생의 불꽃]|h|r에 휩싸입니다!'),
(59483, 8, 0, '%s|1이;가; 격렬한 |cFFFF0404|Hspell:116040|h[진앙]|h|r을 시전하기 시작합니다!'),
(59483, 9, 0, '%s|1이;가; |cFFFF0404|Hspell:116711|h[불꽃 흡수]|h|r를 시전하기 시작합니다!'),
(59505, 0, 0, '이 발자국은 증거로 삼기엔 너무 진흙투성이입니다.'),
(59505, 0, 1, '이 흔적 옆에는 갉아먹은 당근이 몇 개 보입니다.'),
(59505, 0, 2, '수상한 발자국은 아주 민첩해 보입니다.'),
(59505, 0, 3, '발자국에는 건초 섞인 차가운 진흙과 야크 털이 찍혀 있습니다.'),
(59505, 0, 4, '흔적 뒤에는 물건을 잡을 수 있는 꼬리가 끌린 자국이 길게 나 있습니다'),
(59505, 0, 5, '움직인 흔적 옆에는 예리하고 끝이 뾰족한 창머리와 화려한 깃털이 있습니다.'),
(59546, 0, 0, '사람이 물고기에게 소원을 빌때는...'),
(59546, 1, 0, '진짜 속마음을 판독하기 어렵도다...'),
(59546, 2, 0, '대부분 사리사욕에 눈이 멀어...'),
(59546, 3, 0, '안방에서 연회를 열고자 한다네.'),
(59689, 0, 0, '누가 감히 내 영면을 방해하는 것이냐?'),
(59704, 0, 0, '젠이 아니라 첸 스톰스타우트입니다!'),
(59704, 1, 0, '도대체 어떻게 된 거죠?'),
(59704, 2, 0, '다른 일가족은 어디 있어요? 왜 양조장에 호젠이 득실거리죠?'),
(59704, 3, 0, '아줌마! 양조장이 왜 버려졌지요?'),
(59704, 4, 0, '그렇군요. 가오 아저씬 어디 계시죠?'),
(59704, 5, 0, '과자 먹을 시간이 어딨어요! 음... 딱 한 개만 먹을까나...?'),
(59704, 6, 0, '잠깐, 유령 과자잖아. 전혀 배가 안 불러!'),
(59751, 0, 0, '형제들이여, 이 오만한 외부인을 몰아내자!'),
(59751, 0, 1, '음영파에게 외부인의 도움은 필요없다! 이 침입자들을 쫓아내라!'),
(59789, 0, 0, '내 끝없는 고통을 너희들에게도 나눠주마!'),
(59789, 1, 0, '분노한 영혼에 안식은 없다!'),
(59789, 2, 0, '가서 네 몸뚱이를 찾아와라!'),
(59789, 3, 0, '몸을 빼앗아서 영원히 복수하는 거다!'),
(59789, 4, 0, '고통은... 이걸로, 끝인가...?'),
(59789, 5, 0, '|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t%s|1이;가; |cFF006EFD$n|r에게 |cFFFF0000|Hspell:115297|h[영혼 도려내기]|h|r를 시전합니다!'),
(59789, 6, 0, '|TInterface\\Icons\\ability_warlock_jinx.blp:20|t%s|1이;가; |cFFFF0000|Hspell:115147|h[강화된 영혼]|h|r을 시전합니다!'),
(59915, 0, 0, '|TInterface\\Icons\\inv_misc_qirajicrystal_02.blp:20|t |c00F19C88%s|r|1이;가; 모든 플레이어들을 돌로 만들기 시작합니다!'),
(59988, 0, 0, '내가 해 보지.'),
(59988, 1, 0, '문 뒤에 바위라도 괴어 둔 건가? 꼼짝도 안 해!'),
(59988, 2, 0, '잘했어, 조조!'),
(59988, 3, 0, '저 배를 제거해야 돼요, 코르가. 우리가 당신 선원을 도와주면, 우릴 도와줄래요?'),
(59988, 4, 0, '여기 이 친구가 사람 찾기 전문가죠. 맡겨 줘요.'),
(60009, 0, 0, '영혼을 내놓아라, 필멸자여! 죽은 자들의 환대를 거절하지 마라!'),
(60009, 1, 0, '오 위대한 영혼이여! 내게 대지의 힘을 부여하라!'),
(60009, 2, 0, '오 고귀한 자여! 나와 함께 발라내자! 뼈에서 살을!'),
(60009, 3, 0, '오 세기의 현자여! 내게 비전의 지혜를 불어넣어라!'),
(60009, 4, 0, '과거의 위대한 영웅들이여! 너희의 방패를 빌려다오!'),
(60009, 5, 0, '어떤 공포가 기다리는지... 그들이 알았더라면...'),
(60009, 6, 0, '손가락 까닥도 안 했는데.'),
(60009, 6, 1, '쉽게도 무너지는군.'),
(60012, 0, 0, '제 이름을 $p발로 바꿀까 봐요.'),
(60012, 0, 1, '구해 줘서 고마워요!'),
(60040, 0, 0, '내 전설은 지금부터 시작이다!'),
(60040, 1, 0, '내 검은 최고다!'),
(60042, 0, 0, '웨이, 이들은 당신 친구요?'),
(60042, 1, 0, '나는 코르가 스트롱메인이라 하오. 얼라이언스의 포로였다가, 한심하게도 맨몸으로 풀려난 타우렌이지. 반갑소, 판다렌.'),
(60042, 2, 0, '물론이오, 새로운 친구여. 그런데 우리 기술자가 아직 숲 속에 있소. 그를 구출해야 하오.'),
(60043, 0, 0, '|TInterface\\Icons\\inv_misc_qirajicrystal_03.blp:20|t |c0093F8D1%s|r|1이;가; 모든 플레이어들을 돌로 만들기 시작합니다!'),
(60047, 0, 0, '|TInterface\\Icons\\inv_misc_qirajicrystal_05.blp:20|t |c00C3B7EA%s|r|1이;가; 모든 플레이어들을 돌로 만들기 시작합니다!'),
(60051, 0, 0, '|TInterface\\Icons\\inv_misc_qirajicrystal_04.blp:20|t |c0091D0F8%s|r|1이;가; 모든 플레이어들을 돌로 만들기 시작합니다!'),
(60143, 0, 0, '죽을 시간이다!'),
(60143, 1, 0, '으흐흐! 아프겠군!'),
(60143, 1, 1, '아야! 으흐흐흐!'),
(60143, 1, 2, '영혼을 찬양하라!'),
(60143, 2, 0, '날 열받게 했겠다!'),
(60143, 2, 1, '그럼 좋다! 놀아주지, 친구들.'),
(60143, 3, 0, '|TInterface\\Icons\\ability_druid_challangingroar.blp:20|t가라잘이 |cFFFF0000|Hspell:117752|h[광기]|h|r를 시전합니다!'),
(60143, 4, 0, '|TInterface\\Icons\\spell_nature_agitatingtotem.blp:20|t가라잘이 영혼의 토템을 소환합니다. 토템을 파괴해 영혼의 세계로 |cFFFF0000|Hspell:116161|h[횡단]|h|r하십시오!'),
(60143, 5, 0, '|TInterface\\Icons\\inv_misc_idol_02.blp:20|t가라잘이 |cFFFF0000|Hspell:122151|h[부두 인형]|h|r이 될 플레이어를 임의로 선택합니다!'),
(60143, 6, 0, '|cFFFF0000|Hspell:122151|h[부두 인형]|h|r이 되었습니다! 당신이 받는 피해가 공격대의 다른 부두 인형에게 복제됩니다!'),
(60176, 0, 0, '불의 정령이 화가 났습니다. 지금 제단에 들어가면 위험합니다...'),
(60183, 0, 0, '준비는 됐소, $p? 자오민 로가 다리 건너에서 기다리고 있소.'),
(60244, 0, 0, '벌써 가는 거요? 그 무용이 부럽소. $c|1이여;여;, 당신 앞에 창창한 앞날이 펼쳐지길.'),
(60248, 0, 0, '저게... 저게 후오요?'),
(60249, 0, 0, '불의 정령 뜨거워요? 당연히 뜨겁겠죠?'),
(60249, 1, 0, '정말 센가 봐요! 마음만 먹으면 저 다리를 걷어차서 두 동강 낼 수도 있겠죠?'),
(60249, 2, 0, '안녕!'),
(60250, 0, 0, '우와! 불의 정령 데려온 사람이다!'),
(60250, 1, 0, '당연하지! 바보 같은 소리 하지 마, 덩.'),
(60250, 2, 0, '바보. 그건 몰라도 너를 저 언덕 너머로 뻥 차 버릴 수는 있을걸! 히히!'),
(60250, 3, 0, '알았어요, 안녕.'),
(60253, 0, 0, '맞네! 잘했네, $p!'),
(60293, 0, 0, '뗏목을 마음대로 써도 좋소. 뗏목을 타고 싶으면 여기로 오면 되오. 기다리고 있을 테니까.'),
(60408, 0, 0, '상어가 당신을 떨어뜨리려 합니다. 꽉 잡으십시오!$b$b|TInterface\\Icons\\inv_misc_desecrated_leatherglove.blp:32|t 꽉 잡으십시오!'),
(60410, 0, 0, '센서 가동. 모든 코어 최고 효율로 작동.'),
(60410, 1, 0, '신원 확인 결과 불일치. 미확인 개체 감지됨.'),
(60410, 2, 0, '방어 모드로 전환. 안전 장치 해제.'),
(60410, 3, 0, '존재 만료... 내 역할은 끝이다. 으으으...'),
(60410, 4, 0, '전선 비활성화.'),
(60410, 5, 0, '다가와라. 티탄의 힘을 느껴라.'),
(60410, 6, 0, '예비 전력 사용.'),
(60410, 7, 0, '에너지 소용돌이 감소.'),
(60410, 8, 0, '동력 전환.'),
(60410, 9, 0, '에너지 전선 활성화. 동력 안정.'),
(60410, 10, 0, '초토화 단계 전환 시작. 안녕히.'),
(60410, 11, 0, '에너지에 잠식당해라!'),
(60410, 12, 0, '생명의 빛, 소멸됨.'),
(60410, 12, 1, '존재, 사라짐.'),
(60410, 12, 2, '방어 조치, 성공.'),
(60491, 0, 0, '내 분노를 보여주마!'),
(60491, 1, 0, '네 분노로 날 살찌워라!'),
(60491, 2, 0, '분노를 느껴라!'),
(60491, 3, 0, '분노에 몸을 맡겨!'),
(60491, 4, 0, '소멸됐다!'),
(60491, 5, 0, '그래... 그래! 네 분노를 행동으로 보여줘! 덤벼봐!'),
(60583, 0, 0, '네깟 놈들을 위한 정원이 아니다!'),
(60583, 1, 0, '내 힘이 넘친다!'),
(60583, 2, 0, '날 저지할 순 없어!'),
(60583, 3, 0, '누구도 내 힘에 비할 바 못 돼!'),
(60583, 4, 0, '벌레 녀석!'),
(60583, 4, 1, '사라져라!'),
(60583, 5, 0, '우리... 는... 영원하다...'),
(60585, 0, 0, '폭풍이 다가온다.'),
(60585, 1, 0, '원소들에게 명한다. 이들을 파괴하라!'),
(60585, 2, 0, '폭풍을 피할 순 없다!'),
(60585, 3, 0, '공포에 휩싸여라!'),
(60585, 4, 0, '감히 여길 지나려 하다니!'),
(60585, 4, 1, '충격적이군.'),
(60585, 5, 0, '정원이... 무너져선... 안 돼...'),
(60586, 0, 0, '영원한 물이 너희를 이곳에서 씻어낼 것이다!'),
(60586, 1, 0, '파도를 막을 순 없다!'),
(60586, 2, 0, '물이 너희를 삼킨다!'),
(60586, 3, 0, '네 공포에 잠겨라!'),
(60586, 3, 1, '네 공포에 잠겨라!'),
(60586, 4, 0, '나와 맞서기엔 역부족이다.'),
(60586, 4, 1, '도망쳐라, 아가야.'),
(60586, 5, 0, '샤는... 반드시... 막아야...'),
(60648, 0, 0, '끝없는 군대가 황제의 적들을 처단하리.'),
(60648, 1, 0, '황제의 분노가 온 언덕에 울려퍼진다.'),
(60648, 2, 0, '황제의 힘이 철의 손아귀가 되어 이 땅을 옥죈다.'),
(60648, 3, 0, '황제의 용기는 영원히 불타오른다.'),
(60648, 4, 0, '황제의 숨결이 커진다.'),
(60648, 5, 0, '황제의 숨결이 잦아든다.'),
(60648, 6, 0, '황제의 의지가 바라보는 모든 것을 지배한다.'),
(60648, 7, 0, '거대한 모구 조형체 둘이 큰 벽감에 나타납니다!'),
(60648, 8, 0, '황제의 힘이 벽감에 나타납니다!'),
(60648, 9, 0, '황제의 용기가 벽감에 나타납니다!'),
(60648, 10, 0, '고대 모구 기계가 부서집니다! |cFFFF0000|Hspell:116779|h[티탄의 가스]|h|r가 방을 가득 채웁니다!'),
(60648, 11, 0, '기계가 윙윙거리며 동작하기 시작합니다! 아래층으로 가십시오!'),
(60701, 0, 0, '곧 너희도 내 백성들이 왜 어둠을 두려워하는지 알게 될 것이다!'),
(60701, 1, 0, '어둠이... 나를 감싼다!'),
(60701, 2, 0, '느껴진다... 용기. 강한 의지. 빛. 흠... 다 부질 없는 것.'),
(60701, 3, 0, '어둠에 잠겨라.'),
(60701, 3, 1, '어둠이 널 삼킨다.'),
(60701, 3, 2, '황제를 건드리면 이렇게 되는 거다!'),
(60701, 4, 0, '어둠이 너희를 추적한다. 죽음과 함께.'),
(60701, 5, 0, '|TInterface\\Icons\\ability_rogue_envelopingshadows.blp:20|t%s|1이;가; |cFFFF0000|Hspell:117506|h[불멸의 어둠]|h|r을 시전합니다!'),
(60708, 0, 0, '넌 황제를 화나게 했다! 그러므로 사형을 선고한다!'),
(60708, 1, 0, '사형을... 당하는 쪽은... 너희였는데.'),
(60708, 2, 0, '나는... 난 죽고 싶지 않아!'),
(60708, 3, 0, '누가 감히 무적의 군주들 중 가장 위엄 넘치는 황제, 멩을 소환했느냐?'),
(60708, 4, 0, '칼날에 잘려나가는 볏단처럼, 모두 내 앞에 쓰러져라!'),
(60708, 4, 1, '그 누가 감히 황제 멩에 맞서리!'),
(60708, 4, 2, '피... 피 튀기지 마! 불결해! 병 옮아!'),
(60708, 4, 3, '너... 네가 자초했어!'),
(60708, 5, 0, '서로 치고 받아 내 흥을 돋궈라!'),
(60708, 5, 1, '사방이... 적이다! 죽여! 모두 다 죽여!'),
(60708, 6, 0, '|TInterface\\Icons\\warrior_talent_icon_furyintheblood:20|t%s|1이;가; |cFFFF0000|Hspell:117708|h[광기 유발의 함성]|h|r을 시전합니다!'),
(60709, 0, 0, '네 몸과 영혼 모두 짓밟아주마.'),
(60709, 1, 0, '내가... 지다니... 이럴 수가...'),
(60709, 2, 0, '내 군대, 내 힘은 무한하다.'),
(60709, 3, 0, '내 전술은 무적이다.'),
(60709, 3, 1, '또 승리했군.'),
(60709, 3, 2, '황제는 모두를 지배한다!'),
(60709, 4, 0, '병사들이여! 측면을 공격하라!'),
(60709, 4, 1, '측면 공격! 진격하라!'),
(60709, 5, 0, '|TInterface\\Icons\\ability_warrior_stalwartprotector.blp:20|t%s|1이;가; |cFFFF0000|Hspell:117910|h[측방 부대]|h|r를 불러 냅니다!'),
(60710, 0, 0, '곧 실수였음을 알게 될 거다!'),
(60710, 1, 0, '내가... 졌다.'),
(60710, 2, 0, '도둑과 왕, 모두 원하는 것을 빼앗지!'),
(60710, 3, 0, '너무 느려!'),
(60710, 3, 1, '난 너무 빠르고, 영리해.'),
(60710, 3, 2, '발악이라도 해봐!'),
(60710, 4, 0, '네 거? 다 내 거!'),
(60710, 4, 1, '내가 못 가지는 건 없어!'),
(60710, 5, 0, '|TInterface\\Icons\\ability_rogue_dismantle.blp:20|t%s|1이;가; |cFFFF0000|Hspell:118047|h[강탈]|h|r을 시전합니다!'),
(60741, 0, 0, '아이사, 이 방법밖에 없어요. 배를 폭파해서 없애 버린 다음에 상처를 치유하면 돼요. 다른 방법이 없어요.'),
(60741, 1, 0, '그럼 뭔가 생각날 때까지 마냥 기다리자고요? 셴진 수가 죽어가고 있어요! 가만히 있다가는 모든 게 위험해져요!'),
(60741, 2, 0, '난 죽더라도 시도는 해 보고 죽어야겠어요.'),
(60900, 0, 0, '기술자라는 사람을 찾으러 가자. 가시 빼는 게 생각만큼 힘들지 않을지도 모르겠어.'),
(60999, 0, 0, '빛이 사라질 것이다. 어둠이 너를 감쌀 것이다. 그리고 너는 어둠 속을 움직이는 그림자에 공포를 느낄 것이다.'),
(60999, 1, 0, '공포가 뭔지 알려 주마!'),
(60999, 2, 0, '도망쳐라!'),
(60999, 3, 0, '공포에 질식해라.'),
(60999, 4, 0, '공포를 이기기가 그리 쉬울 줄 아느냐?'),
(60999, 5, 0, '두려움이 일어난다! 녀석은 굶주린 채 빛을 찾는다.'),
(60999, 6, 0, '공포에 질려 웅크려라!'),
(61127, 0, 0, '옙!'),
(61140, 0, 0, '흥, 너희 같은 놈들에게 지다니! 잔달라 사제로서 부끄럽기 짝이 없군!'),
(61140, 0, 1, '하지만 상관없어. 장신구를 가져가라. 필요할 테니까.'),
(61140, 0, 2, '이제 가야겠다. 내 영혼이 머물 새집으로.'),
(61140, 0, 3, '죽음은 문, 시간은 창이 되리라. 난 다시 돌아온다! 으흐흐하하하하하하!'),
(61156, 0, 0, '도망쳐라, 비겁한 촌놈들아! 이 땅은 다시 한 번 온전히 자연의 소유가 된다!'),
(61156, 1, 0, '복수심에 불타는 후이가 녹옥 마을 북쪽에 있는 석공의 집에 나타났습니다. 도전하십시오!'),
(61203, 0, 0, '정말 감사합니다... 더는 견뎌낼 수 없었습니다.'),
(61203, 1, 0, '아, 이제 더는 못하겠군요. 우리 녹옥 맥주 보급품을 전부 도난당하지 않았더라면 정말 좋았을 텐데!'),
(61203, 2, 0, '주변의 숲으로 들어가 도난당한 맥주통을 찾아서 가져오시면 강력한 힘이 집약된 맥주를 만들어 드릴 수 있는데 말입니다...'),
(61203, 3, 0, '마을을 구했을 때는 모험가였지만, 맥주를 회수해 왔을 땐 영웅이 되셨군요!'),
(61203, 3, 1, '이 정도면 저 성가신 놈들이 우리 소중한 맥주를 좀도둑질하면 어떻게 되는지 알았을 겁니다!'),
(61203, 3, 2, '아, 맥주통이 원래 있던 곳으로 돌아왔군요. 감사합니다!'),
(61203, 3, 3, '귀한 녹옥 맥주통이군요! 만세!'),
(61203, 4, 0, '아, 돌아오셨군요! 정말 고맙습니다. 이걸 받아주십시오 우리가 만든 술 중 가장 강력한 술이지요. 바로 독한 녹옥 맥주입니다.'),
(61203, 5, 0, '독한 녹옥 맥주를 획득했습니다! 이 맥주를 사용해 다수의 적들을 상대하십시오!'),
(61243, 0, 0, '거기 누구냐...'),
(61243, 1, 0, '시체를 뒤져!'),
(61243, 2, 0, '쓸어버려!'),
(61243, 3, 0, '잡아라!'),
(61243, 4, 0, '쓸모없는...'),
(61305, 0, 0, '전승지기! 네놈이 내 물건을 가지고 있구나.'),
(61315, 0, 0, '결속은 잠깐이면 끝나네만, 그동안 나는 무아지경에 빠질 걸세.'),
(61315, 1, 0, '내 뒤를 봐 주게. 방해하려는 자가 있으면 자네가 처리해 줄 걸로 믿네.'),
(61315, 2, 0, '다 됐네. 무슨 일 있었나?'),
(61342, 0, 0, '저리가, 이 악마야! 도와주십시오!'),
(61342, 1, 0, '녹옥 마을에 희망이 보이는군요! 감사합니다!'),
(61346, 0, 0, '저리가, 이 악마야! 도와주십시오!'),
(61346, 1, 0, '정말 감사합니다!'),
(61348, 0, 0, '수천 년 동안 누구도 손대지 않은 모구의 고대 금고라니... 어떤 비밀이 기다릴지 누가 알겠나?'),
(61348, 1, 0, '젊은 판다렌 전사들이 이 무덤에서 쓰러졌네. 조심해야 하네.'),
(61348, 2, 0, '커다란 기렌이 문을 지키고 있군. 깨우지 않게 조심하게.'),
(61348, 3, 0, '아주... 아슬아슬했군!'),
(61348, 4, 0, '수호자들이 죽으면서 문이 작동한 것 같아. 이 안에 무엇이 있을지 걱정이 되네.'),
(61348, 5, 0, '우리가 어떤 정령을 깨운 것 같군.'),
(61348, 6, 0, '그 이야기가 사실이었군...'),
(61348, 7, 0, '우리가 깨우지 말아야 할 것을 깨웠네. 이 감옥에서 도망치게 할 수는 없어! 자네가 없애야 하네!'),
(61348, 8, 0, '저주받은 펑은 모구의 네 황제에게 배신당하고, 매번 육신이 파괴되었지만, 늘 다시 살아났네.'),
(61348, 9, 0, '펑이 완전히 사라진 건 아닐 거야...'),
(61348, 10, 0, '잔달라 부족이라니! 모구의 고대 동맹이야! 금고 깊은 곳에 있는 전설의 무기를 찾는 것이 틀림없네!'),
(61348, 11, 0, '미리 얘기를 못해서 미안하군! 이 금고에는 믿을 수 없는 힘을 지닌 무기가 숨어 있네! 저들을 막게!'),
(61348, 12, 0, '나는 여기 남아서, 이 연단을 더 조사해 보겠네...'),
(61348, 13, 0, '아, 모구샨 황제의 고대 금고로군. 흐음... 이 단추는 뭐지...?'),
(61348, 14, 0, '이걸 보게! 영원한 어둠의 쯔안에 대한 기록이네. 왕국을 공포와 어둠으로 지배했던, 강력한 마술사였지.'),
(61348, 15, 0, '이건 무자비한 치앙에 대한 기록 같군. 여러 국가를 점령하고, 철권 통치했던 위대한 정복자였네!'),
(61348, 16, 0, '이 이야기를 들은 적이 있네. 능숙한 궁수이자 천재적인 도둑으로 유명한 날렵한 쑤베타이야. 부자의 재산을 훔쳐내서, 모두 자기가 차지했다고 하지.'),
(61348, 17, 0, '이건 누구지? 이 황제에 대해서는 들어본 적이 없네. 실성한 멩이라고? 이 글을 보면, 멩은 왕좌를 차지했던 자 중에서 가장 사악하고 미치광이 같은 지배자였군.'),
(61348, 18, 0, '영웅들이여! 살아 있군. 도와줄 이를 데려왔네.'),
(61350, 0, 0, '도와주세요! 도와주세요!'),
(61350, 1, 0, '끝장난 줄 알았습니다. 정말 감사합니다!'),
(61398, 0, 0, '이건 뭐야. 내 왕관을 훔친답시고 더 온 건가? 조그맣고 약한 놈들이.'),
(61398, 1, 0, '너희가 내게 도전한 첫 상대는 아니다. 하지만 마지막 상대도 아닐 거다.'),
(61398, 2, 0, '내 무기의 위력을 느껴라!'),
(61398, 3, 0, '%s|1이;가; |cFFFF0404|Hspell:119374|h[소용돌이치는 도끼]|h|r 함정을 활성화합니다!'),
(61398, 4, 0, '%s|1이;가; |cFFFF0404|Hspell:119311|h[칼날 빗발]|h|r 함정을 활성화합니다!'),
(61398, 5, 0, '내 힘은 무한하다!'),
(61398, 6, 0, '광대놀음은 여기까지다! 고통을 안겨주마, 겁쟁이들아!'),
(61398, 7, 0, '%s|1이;가; |cFFFF0404|Hspell:120142|h[석궁]|h|r 함정을 활성화합니다!'),
(61398, 8, 0, '고작... 이 정도냐...?'),
(61398, 9, 0, '%s|1이;가; 당신의 얼굴에 피를 뱉습니다.'),
(61398, 10, 0, '네 뼈를 부수는 일이 얼마나 쉬운지 봐라!'),
(61398, 10, 1, '무릎 꿇어라, 겁쟁아!'),
(61398, 11, 0, '나는, 패배를, 모른다!'),
(61442, 0, 0, '구르단 부족이 폐하와 권력에 굶주린 너희 애송이들에게 보여주마. 왜 우리가 폐하를 보좌해야 하는지!'),
(61442, 1, 0, '우리들은 운명을 지배할 이 정당한 권리를 결코 포기하지 않을 것이다!'),
(61442, 2, 0, '구르단에게 영광을!'),
(61442, 3, 0, '누가 우리 전당에 외부인을 들였지? 하르닥과 카게쉬 부족 놈들이나 이런 배신을 저지를 것이다!'),
(61442, 4, 0, '각본을 잘 짜왔군. 하지만 우린 속지 않아. 너희 부족은 서로 결탁한 게 분명해. 폐하의 영광을 위해, 제국의 이름으로 너희 모두를 쓰러뜨리겠다!'),
(61442, 5, 0, '저희가 최고입니다!'),
(61442, 5, 1, '다른 부족들은 필요없습니다!'),
(61444, 0, 0, '하르닥 부족이 왜 모구 최고의 부족인지 보여주마!'),
(61444, 1, 0, '우리 부족이 진짜 부족이다! 그건 영원불멸의 진리야!'),
(61444, 2, 0, '이것이 하르닥의 힘이다!'),
(61444, 3, 0, '구르단 부족의 개들이나 자신의 잘못을 남에게 돌린다! 너희 부족이 가장 절실하니 분명 너희가 범인이다!'),
(61444, 4, 0, '우리 부족은 진정한 선조들의 방식을 따릅니다. 우리야말로 왕의 호의를 받아 마땅합니다!'),
(61444, 4, 1, '이 다른 부족들은 시간 낭비일 뿐입니다. 폐하!'),
(61445, 0, 0, '왜 카게쉬 부족이 왕을 보좌할 만한 힘을 가진 유일한 부족인지 보여주겠다!'),
(61445, 1, 0, '말도 안 돼! 우리의 힘은 제국 최강이다!'),
(61445, 2, 0, '카게쉬를 위해!'),
(61445, 3, 0, '구르단 부족 말이 맞아! 불명예스런 하르닥 부족이나 목적 달성을 위해 하등 종족을 개입시키겠지. 배신자는 너희야!'),
(61445, 4, 0, '저희 부족의 힘 없이 모구는 정당한 영광을 쟁취할 수 없습니다!!'),
(61445, 4, 1, '이런 한심한 놈들이 당신을 섬깁니다, 폐하. 놈들은 우리의 위대한 역사를 우롱합니다!'),
(61461, 0, 0, '놈들이 마을을 공격했습니다! 도와주십시오!'),
(61461, 1, 0, '끝장난 줄 알았습니다. 정말 감사합니다!'),
(61462, 0, 0, '저리가, 이 악마야! 도와주십시오!'),
(61462, 1, 0, '끝장난 줄 알았습니다. 정말 감사합니다!'),
(61485, 0, 0, '니우짜오의 병력이 뒤에서 공격한다!'),
(61485, 1, 0, '사원은 무너지리라! 내 병력을 막진 못 해!'),
(61485, 2, 0, '내 군대가 너흴 박살내리라!'),
(61485, 2, 1, '막아라! 사마귀들이여, 공격!'),
(61485, 2, 2, '무기를 버리거나, 죽어라...'),
(61485, 3, 0, '폐하의 뜻이다!'),
(61485, 3, 1, '니우짜오의 병력은 약하군!'),
(61485, 4, 0, '죄송합니다, 폐하...'),
(61492, 0, 0, '감사합니다, 친구. 걱정 마십시오. 그냥 긁힌 상처입니다. 이제 다시 태어난 것처럼 기운이 나네요!'),
(61492, 0, 1, '이제 죽은 목숨이라고 생각했습니다. 당신은 제 생명의 은인이십니다.'),
(61492, 0, 2, '구출해주셔서 감사합니다. 앞선 전투는 꽤 힘에 겨웠습니다.'),
(61492, 0, 3, '저 지금... 살아 있는 겁니까? 하! 가로쉬아르 거점의 호드들에게 인사를 전하고 싶군요. 우리가 아주 혼쭐을 내줬습니다.'),
(61492, 0, 4, '감사합니다. 어서 상처를 치료하고 다시 전투를 시작해야겠습니다!'),
(61567, 0, 0, '여기까지 오다니 잘 됐군. 내 힘과 기술을 모두에게 증명할 수 있겠어!'),
(61567, 1, 0, '하하! 너희 모두 여기 온 걸 후회하게 될 거다...'),
(61567, 2, 0, '하지만... 나는... 이제 누가...?!'),
(61567, 3, 0, '감히 이길 생각을 해?!'),
(61567, 4, 0, '호박석 연금술의 힘을 보여주마...'),
(61620, 0, 0, '도와줘서 고마워. 근데 우린 아직도 사마귀 군대 사이에 발이 묶여 있어.'),
(61620, 1, 0, '저길 봐. 헤쳐나가기엔 너무 수가 많아.'),
(61620, 2, 0, '흠... 여기 써먹을 수 있는 정신나간 생각이 떠올랐는데, 너희 도움이 필요해.'),
(61620, 3, 0, '사마귀들에게 놈들의 쓴맛을 되돌려 주자!'),
(61620, 4, 0, '리, 로, 수액을 위치로 가져가!'),
(61620, 5, 0, '이제 잔치를 시작해 볼까?'),
(61620, 6, 0, '덤벼, 못생긴 것들아!'),
(61620, 7, 0, '벌레처럼 뭉개 주마!'),
(61620, 8, 0, '수액이 여기 있다! 와서 가져가 봐!'),
(61620, 9, 0, '저길 봐. 헤쳐나가기엔 너무 수가 많아.'),
(61620, 10, 0, '무리전사들이 올라온다! 수액으로 움직임을 늦춰!'),
(61620, 11, 0, '사마귀들에게 놈들의 쓴맛을 되돌려 주자!'),
(61620, 12, 0, '파괴병이 폭발물을 갖고 있어! 다가오기 전에 날려버려!'),
(61620, 13, 0, '이제 잔치를 시작해 볼까?'),
(61620, 14, 0, '전사들이 온다. 화력 집중!'),
(61620, 15, 0, '전사들이 몰려온다! 화력을 집중하라!'),
(61620, 16, 0, '덤벼, 못생긴 것들아!'),
(61620, 17, 0, '호박날개가 날아온다, 조심해!'),
(61620, 18, 0, '하하, 재미있었어, 안 그래?'),
(61620, 19, 0, '리, 로. 밑에 있는 친구들에게 가 봐.'),
(61620, 20, 0, '아, 이 문은 잠겼어. 그래도 열 방법이 없는 건 아니지.'),
(61620, 21, 0, '어디 보자... 30초짜리 도화선...'),
(61620, 22, 0, '내가 30초짜리라고 했나? 3초짜린데.'),
(61620, 23, 0, '가, 어서! 공격을 멈춰야 해!'),
(61634, 0, 0, '하! 무적의 사마귀 군단에 정면으로 맞서시겠다? 죽여주마!'),
(61634, 1, 0, '무리전사들이여, 공격! 뼈에서 살을 발라내!'),
(61634, 2, 0, '파괴병! 저기로 가! 모조리 다 태워버려!'),
(61634, 3, 0, '전사들이여! 놈들을 짓밟아라! 처치해!'),
(61634, 4, 0, '모두! 모두 내보내! 이 겁쟁이들을 처치해! 이놈들이 우릴 바보로 만들고 있어!'),
(61634, 5, 0, '어디... 어딨어? 쓸모없는 놈들... 젠장!'),
(61634, 6, 0, '하! 실패한 놈들은 죽어 마땅한 놈들이었어. 너희는 쭉정이를 걸러낸 것뿐이다!'),
(61634, 7, 0, '내가 직접 처치해 주마. 각오해라!'),
(61634, 8, 0, '융단 폭격 실시! 호박날개를 출격시켜!'),
(61634, 8, 1, '우릴 몰아내려 한다! 공중 지원 실시!'),
(61634, 8, 2, '호박날개, 가라! 저항군들을 쓸어버려!'),
(61634, 9, 0, '함정... 이었나...'),
(61634, 10, 0, '별거 아니군!'),
(61634, 10, 1, '발버둥이라도 쳐봐!'),
(61634, 10, 2, '너무 쉽게 죽는 거 아니야?!'),
(61636, 0, 0, '수련의 장에 오신 걸 환영합니다. 곧 첫 번째 시험이 시작될 겁니다. 제한 시간 내에 환영 무리를 처치하십시오.'),
(61636, 1, 0, '이 환영 학살자는 당신이 적에게 피해를 얼마나 주는지 시험할 겁니다. 공격은 안 하니 안심하십시오.'),
(61636, 2, 0, '방어의 명수인 환영 수호자는 전방의 모든 공격을 막아냅니다. 그 뒤에 서십시오!'),
(61636, 3, 0, '환영 요마들은 무리지어 다니는데, 피해를 주진 않습니다. 광역 공격 주문으로 공격해서 신속히 처치하십시오.'),
(61636, 4, 0, '성공했군요! 훌륭합니다. 다음 시험에서 만나지요.'),
(61636, 5, 0, '앞서와 같이 제한 시간 내에 환영 무리를 처치하십시오. 이번에는 좀 더 까다로운 환영과 싸우게 될 겁니다.'),
(61636, 6, 0, '환영 호박술사는 호박석 방울을 만들어 당신 쪽으로 띄워 보냅니다. 거기에 닿으면 폭발하죠. 호박석 방울을 다른 환영에게 유인하십시오!'),
(61636, 7, 0, '환영 비술사는 부상이 심한 동료를 치유합니다. 놈들의 치유 주문을 방해하십시오.'),
(61636, 8, 0, '가장 힘겨운 환영과 싸울 준비를 하십시오. 제한 시간 내에 놈들을 모두 처치하면 성공입니다.'),
(61636, 9, 0, '환영 바나나 투척자군요. 당신에게 빠른 속도로 바나나를 던질 겁니다. 움직여서 피하십시오. 가능하면 놈이 도망치지 못하게 하십시오.'),
(61636, 10, 0, '환영 밴시군요! 폭발하기 전에 어서 처치하십시오!'),
(61636, 11, 0, '오, 환영 샤군요. 놈의 보호막이 사라져서 노출될 때까지 가장 강력한 공격을 아껴두십시오!'),
(61707, 0, 0, '너도 곧 시체가 돼서 여기 묻힐 거다, 애송이 $c 놈아!'),
(61707, 1, 0, '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t%s|1이;가; |cFFFF0000|Hspell:120215|h[죽음의 힘]|h|r을 내뿜습니다! 도망치십시오!'),
(61766, 0, 0, '납골당에 침입자가 들어왔다! 살아서 나가게 하지 마라!'),
(61783, 0, 0, '누가 감히 납골당에서 행패를 부리느냐?'),
(61796, 0, 0, '거기 셋, 잠시 걷자꾸나.'),
(61796, 1, 0, '얼라이언스에 합류하고 싶다고...'),
(61796, 2, 0, '우리에겐 항상 동료가 필요했다. 전쟁이 한창인 지금 너희를 거절할 순 없겠지.'),
(61796, 3, 0, '하지만 그 전에 너희들이 알아둬야 할 것이 있다.'),
(61796, 4, 0, '첫째, 얼라이언스의 종족들은 서로를 믿고 돕는다.'),
(61796, 5, 0, '얼라이언스의 일원에게 도움이 필요하면 기꺼이 도와야 한다. 그들이 인간이든, 노움이든, 드레나이든... 혹은 너희처럼 판다렌이든...'),
(61796, 6, 0, '단순하지만 의미 있는 지침이지. 이해하겠느냐?'),
(61796, 7, 0, '좋다. 이제 두 번째 지침을 설명하겠다.'),
(61796, 8, 0, '모든 판다렌이 너희 셋과 같은 선택을 한 것은 아니다.'),
(61796, 9, 0, '어떤 이들은 호드에 합류했다.'),
(61796, 10, 0, '그들은 호드의 다른 야만족들과 마찬가지로 너희의 새로운 적이다.'),
(61796, 11, 0, '한 때 친구라 생각했던 이, 또는 사랑했던 이라고 하더라도 그들은 모두 숙명의 적이다.'),
(61796, 12, 0, '너무나도 미안하지만, 전선이 그어진 이상, 적과 노닥이는 모습은 절대로 용납할 수 없다. 이는 얼라이언스를 위험에 노출시키는 짓이기 때문이다.'),
(61796, 13, 0, '내 말을 이해하겠느냐?'),
(61796, 14, 0, '많은 이들이 모르지만, 나도 한때는 투사였다. 호드의 재미를 위해 싸우는 검투사였지. 그래서 나도 싸우는 법에 대해서는 제법 아는 편이다.'),
(61796, 15, 0, '그럼, 판다렌... 너의 실력을 보여봐라!'),
(61796, 16, 0, '도망치지 마라! 한 번 덤벼봐!'),
(61796, 17, 0, '뭐가 문제지? 이것보단 잘 싸울 줄 알았는데.'),
(61796, 18, 0, '자, 판다렌! 날 때려봐!'),
(61796, 19, 0, '하하! 이런 기분, 정말 몇 년만에 느껴보는군! 걱정 말거라, 새 친구여... 이보다 더 큰 상처를 입어도 봤으니. 이런 투지를 가진 자들은 얼마든지 환영이다!'),
(61814, 0, 0, '잘됐군요! 이 한심한 수습생들 상대하기도 지겨웠습니다!'),
(61884, 0, 0, '쓸모없는 놈들! 너희가 바친 경비병들도 이 미개한 놈들을 궁전에서 쫓아내지 못했다.'),
(61884, 1, 0, '만회, 아니, 증명해라. 침입자들을 처치해라. 놈들의 머리를 바치는 부족은 내 총애를 얻을 것이다!'),
(62081, 0, 0, '예, 대족장님.'),
(62081, 1, 0, '아... 알 것 같습니다.'),
(62081, 2, 0, '잘 싸웠어. 네가 내 뒤를 봐 주지 않았으면 목숨을 잃었을지도 몰라.'),
(62087, 0, 0, '내 호드를 선택한 것은 아주 현명한 결정이었다.'),
(62087, 1, 0, '어떤 이들은 우리를 야만인이라고... 아제로스의 "싸움꾼"이라고 하지.'),
(62087, 2, 0, '그들은 무지하며, 현실을 모른다. 네 주위를 둘러봐라, 판다렌.'),
(62087, 3, 0, '전장에서 오크보다 든든한 아군은 없다.'),
(62087, 4, 0, '타우렌은 여러모로 유용한 자들이지. 봐라, 이자는 주술사이다.'),
(62087, 5, 0, '블러드 엘프도 검을 다룰 줄은 알지.'),
(62087, 6, 0, '알겠는가? 호드의 모두가 자신의 몫은 해내야 한다는 것이다. 너와 네 친구들도 예외는 아니지.'),
(62087, 7, 0, '내 말을 이해하겠나, 판다렌?'),
(62087, 8, 0, '흠. 좋다.'),
(62087, 9, 0, '사실, 난 그 섬을 탈출한 판다렌이 너희뿐만이 아니라는 걸 알고 있다.'),
(62087, 10, 0, '어떤 놈들은 얼라이언스에 합류했지.'),
(62087, 11, 0, '그들은 이제 네 적이다.'),
(62087, 12, 0, '네 친구나 가족 중에서도 호드의 숙적, 얼라이언스를 택한 자들이 있을 것이다. 그들 역시 더는 네 친구가 아니다... 네 가족도 아니다.'),
(62087, 13, 0, '얼라이언스의 휘장을 입는 순간, 그들은 죽은 것이다. 전장에서 감정에 이끌려 우물쭈물하는 꼴은 결코 용납되지 않는다. 호드의 배신자는 배신자로서 죽을 것이다!'),
(62087, 14, 0, '내 말을 알아듣겠나?'),
(62087, 15, 0, '좋다.'),
(62087, 16, 0, '명예의 골짜기에서 만나지. 너희에게 줄... 선물이 있다.'),
(62087, 17, 0, '용맹의 투기장에 온 것을 환영한다, 판다렌. 내가 준비를 마칠 때까지 잠시 쉬고 있도록.'),
(62087, 18, 0, '하! 이제 준비가 된 것 같군. 자, 신참들아... 싸움을 준비해라.'),
(62087, 19, 0, '이게 너희에게 주는 선물이다... 선물이자 시험이지.'),
(62087, 20, 0, '전설의 판다렌과 그들의 이국적인 전투 방식에 대해선 일찍이 들어본 적 있었지. 이제 직접 확인하고 싶다.'),
(62087, 21, 0, '쉽게 오는 기회가 아니다, 판다렌. 호드의 대족장에게 네 능력을 증명해 봐라!'),
(62087, 22, 0, '록타르 오가르! 승리가 아니면 죽음을!'),
(62202, 0, 0, '내가... 돌아왔다.'),
(62205, 0, 0, '내 군대를 헤치고 먼 길을 오느라 고생 많았다. 하지만 내가... 너희를 처치한다. 그리고 다리는 내가 건설할 거야.'),
(62205, 1, 0, '파발락이 못 했던 일을 내가 해주지!'),
(62205, 2, 0, '다시 일해! 동이 트기 전까지 다리를 완성해야 한다!'),
(62205, 3, 0, '다... 다리를...'),
(62205, 4, 0, '저리 비켜.'),
(62220, 0, 0, '뭐?! 네 맘대로 만날 수 있는 분이 아니다!'),
(62220, 1, 0, '네가 뭔데 감히 음영파에게 이래라 저래라 하느냐?'),
(62227, 0, 0, '수도원 안에서 만나지요!'),
(62377, 1, 0, '그 정도면 충분해요! 이젠 거대한 당근에 물을 주세요!'),
(62377, 2, 0, '계속하세요! 제 양배추에 물을 주세요!'),
(62377, 3, 0, '멈추지 마시고요! 저 사탕무에 물을 주세요!'),
(62377, 4, 0, '밭 안쪽에 있는 커다란 멜론에 물을 주세요!'),
(62377, 5, 0, '계속하세요! 이제 붉은잎 양상추에 물을 주세요!'),
(62377, 6, 0, '사탕무에 물을 더 줘야 할 것 같아요! 다시 돌아가세요!'),
(62377, 7, 0, '멈춰!'),
(62377, 8, 0, '모든 물건은 값을 치러야 해요. 도움이 필요하다면 일을 해야 합니다.'),
(62385, 0, 0, '그건 뭉뭉에게 물어봐야 할 겁니다. 우리 식량 창고를 관리하고 있으니까요.'),
(62397, 0, 0, '여왕님에 대한 도전은 여기까지다!'),
(62397, 1, 0, '판다리아가 여왕님의 날개 밑에서 멸망하리라!'),
(62397, 2, 0, '폐하의 뜻이다!'),
(62397, 3, 0, '폐하... 이렇게... 지다니...'),
(62397, 4, 0, '내 칼날을 받아라!'),
(62397, 5, 0, '이 하늘은 여왕님 거야!'),
(62397, 6, 0, '겁쟁이처럼 싸우는군!'),
(62397, 7, 0, '여왕님을 위한 죽음은 영광이다!'),
(62397, 7, 1, '여왕님의 날개는 꺾이지 않아!');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(62397, 7, 2, '죗값을 치르게 해주지!'),
(62442, 3, 0, '안 돼... 물... 어떻게든... 저항해야... 공포에 휩싸여선... 안 돼...'),
(62442, 4, 0, '여긴 너희가 있을 곳이 아니다! 이 물은 보호해야 해... 물러서지 않겠다면 처치해주마!'),
(62442, 5, 0, '도망치거나... 죽어라!'),
(62442, 5, 1, '넘치는... 공포!'),
(62442, 6, 0, '밤에서... 낮이 되었다!'),
(62442, 6, 1, '햇살이... 비춘다...'),
(62442, 6, 2, '또다시... 새벽이구나...'),
(62442, 7, 0, '어둠이 커진다...'),
(62442, 7, 1, '밤이 온다...'),
(62442, 7, 2, '빛이 사라져...'),
(62442, 8, 0, '안 돼...!'),
(62442, 8, 1, '날 용서해줘!'),
(62442, 9, 0, '어둠에 잠겨라.'),
(62442, 9, 1, '밤이 너희를 감싼다...'),
(62442, 10, 0, '고맙다, 이방인이여. 날 자유롭게 해줘서.'),
(62442, 11, 0, '이 물을... 보호해다오...'),
(62465, 0, 0, '응가할 준비는 됐겠지!'),
(62465, 1, 0, '선장 우끼는 괴혈병이 있습니다! 녀석에게서 오렌지를 숨기십시오!'),
(62467, 0, 0, '아! 좋습니다! 와 주셨군요. 이제 "해적" 호젠 놈들에게 우리 마을을 공격하면 어떻게 되는지 알려 줘야겠군요.'),
(62467, 1, 0, '해적 호젠을 상대하는 비결은, 허를 찌르는 것이지요.'),
(62467, 2, 0, '조심하십시오!'),
(62467, 3, 0, '자... 그러니까... 해적 호젠을 상대하는 새로운 비결을 말씀드리자면, 그냥 방금처럼만 하십시오.'),
(62467, 4, 0, '새까지?! 대체 언제 새를 길들이는 법까지 배웠지?'),
(62467, 5, 0, '와, 이게 뭡니까? 처음으로 되찾은 맥주통이로군요! 이건 제가 갖겠습니다.'),
(62467, 6, 0, '이 섬 전체에 우리의 존재를 들키기 전에 빨리 움직이는 게 좋겠군요.'),
(62467, 7, 0, '호젠에 검투사가? 무기는 다 어디서 난 거지?'),
(62467, 8, 0, '오! 맥주를 만들기에 썩 괜찮은 자리군요.'),
(62468, 0, 0, '네가 오늘 저녁 밥이다!'),
(62468, 1, 0, '넌 좀 얼굴색이 안 좋구나!'),
(62468, 2, 0, '우낏은... 대가를... 치를 거다.'),
(62491, 0, 0, '이 가마솥은... 맥주를 만드는 데 딱이군요.'),
(62491, 1, 0, '어... 방금 그건 뭐였습니까?'),
(62491, 2, 0, '휴! 아슬아슬했습니다. 자, 좋은 생각이 있습니다...'),
(62491, 3, 0, '한 분은 가마솥을 좀 지켜 주십쇼. 나머지는 웅가 밀림 맥주를 찾아서 가져와 주시고요!'),
(62491, 4, 0, '섬을 수색해서 보의 가마솥에 던져 넣을 맥주를 찾으십시오. 단, 보를 호위할 사람은 남겨 두십시오.'),
(62491, 5, 0, '근처의 폭탄과 대포를 이용해 호젠을 날려 버릴 수 있습니다!'),
(62491, 6, 0, '맥주가 더 필요합니다. 남동쪽의 산봉우리에서 호젠들이 술을 퍼 마시는 걸 본 것 같습니다.'),
(62491, 7, 0, '맛있군요!'),
(62491, 8, 0, '이런... 맥주가 생각보다 좀 독하군요... 전...'),
(62491, 9, 0, '잠시 눈을 쉬어야겠습니다...'),
(62491, 10, 0, '섬을 수색해서 보의 가마솥에 던져 넣을 맥주를 찾으십시오. 단, 보를 호위할 사람은 남겨 두십시오.'),
(62491, 11, 0, '근처의 폭탄과 대포를 이용해 호젠을 날려 버릴 수 있습니다!'),
(62491, 12, 0, '호젠 도둑이 맥주를 훔치고 있습니다! 막으십시오!'),
(62491, 13, 0, '저 멀리 호젠 배가 나타납니다!'),
(62491, 14, 0, '선장 우끼는 괴혈병이 있습니다! 녀석에게서 오렌지를 숨기십시오!'),
(62491, 15, 0, '$n|1이;가; 오렌지를 손에 넣었습니다!'),
(62491, 16, 0, '$n|1이;가; 오렌지를 던졌습니다!'),
(62491, 17, 0, '맥주를 너무 많이 가지고 있습니다. 양조 가마솥이 있는 곳으로 가서 맥주를 부어 넣으십시오.'),
(62492, 0, 0, '이이야아아!'),
(62495, 0, 0, '도망쳐라!'),
(62508, 0, 0, '우낏이다!!!'),
(62511, 0, 0, '아, 내 실험체 몇 개를 봤나 보군. 이리 와라. 내 영광스러운 업적을 모두 보여주지.'),
(62511, 1, 0, '여기까지 온 걸 보니 강한가 보군. 그래, 그래... 괜찮은 실험 대상이 되겠어.'),
(62511, 2, 0, '발 조심하라고!'),
(62511, 3, 0, '복도 많군. 이런 선물을 받다니.'),
(62511, 4, 0, '죽음에서 생명이, 그리고 생명에서, 죽음이...'),
(62511, 5, 0, '자신이 강하다고 생각하겠지. 아무것도 모르는군. 이제 내 가장 위대한 창조물을 봐라!'),
(62511, 6, 0, '뭘 한 거냐? 안 돼. 내 연구는 이렇게 끝나지 않아. 그렇겐 못 해!'),
(62511, 7, 0, '좋아!'),
(62511, 8, 0, '용서하십시오, 여왕님...'),
(62540, 0, 0, '이게... 여기가 어디지?'),
(62543, 0, 0, '놈들이 온다고? 좋군. 내 무술 실력을 확인할 제자들이 있었으면 더 좋았겠지만...'),
(62543, 1, 0, '무기를 들어라. 나, 칼날군주 타야크가 상대해주마.'),
(62543, 2, 0, '난 항상 누군가를 이렇게 베어버리고, 이 소리를 듣길 원했지. 하지만 믿을 수 없군. 이 소리가 내 몸에서 나게 될 줄이야.'),
(62543, 3, 0, '완벽해.'),
(62543, 3, 1, '이것이 칼날군주의 기술이다.'),
(62543, 4, 0, '수습생이 그렇지.'),
(62543, 4, 1, '수련이 부족했던 모양이군.'),
(62543, 4, 2, '기술 하나만으로는 부족하지.'),
(62543, 4, 3, '모두 낙제로군. 너희는 어떨까?'),
(62543, 5, 0, '내 칼날을 따라올 수 있겠느냐?'),
(62543, 6, 0, '이제 가라. 내 기술을 수습생들에게 전수해라.'),
(62543, 7, 0, '칼날군주 타야크가 $n|1을;를; |cFFFF0000|Hspell:122949|h[보이지 않는 일격]|h|r의 대상으로 점찍습니다!'),
(62590, 0, 0, '맥주야, 도망쳐!'),
(62706, 0, 0, '아이고! 괴물들이 녹옥 마을을 공격하고 있습니다! 도망치십시오!'),
(62711, 0, 0, '아... 버... 지...'),
(62711, 1, 0, '호박석 괴수가 |cFFFF0000|Hspell:122398|h[호박석 폭발]|h|r을 준비합니다!'),
(62752, 0, 0, '우우욱!'),
(62752, 1, 0, '내가... 돌아왔다. 클락시의 부름에 응답하노라.'),
(62787, 5, 0, '저는 축제가 시작되기 전에 양조사 부프 님께 가야겠습니다. 구해 주셔서 감사합니다, $p님!'),
(62980, 1, 0, '신성하신 분께서 당신의 신성한 뜻을 실현하라고 우리에게 목소리를 주셨다. 우리는 도구일 뿐이다.'),
(62980, 2, 0, '우리는 어두운 공허의 절망에 지지 않으리라. 우리가 죽는 것이 그분의 뜻이라면, 그대로 따르리라.'),
(62980, 3, 0, '우리가 곧 여제 폐하의 뜻이다.'),
(62980, 4, 0, '우리는 폐하의 신성한 이름을 받든다.'),
(62980, 5, 0, '의문도 고민도 없다. 그저 행할 뿐.'),
(62980, 6, 0, '우리는 폐하께서 우리에게 뜻하신 바를 실현하기 위해 싸우고, 일하고, 섬긴다.'),
(62980, 7, 0, '그분의 기쁨이 우리의 보람이며, 그분의 슬픔은 우리의 실패다.'),
(62980, 8, 0, '우리는 여제 폐하를 위해 망설임 없이 목숨을 바칠 것이다. 폐하의 빛이 없다면 우리의 목숨은 암흑에 묻혀 사라질 것이다.'),
(62980, 9, 0, '그분의 큰 은혜에 우리는 감사할 따름이다.'),
(62980, 10, 0, '그분께서 우리를 시험하신다. 실망을 안겨 드릴 순 없다.'),
(62980, 11, 0, '우리는 이 전당을 장식하는 호박석 같이 굳세리라. 폐하의 힘을 받아, 신성한 궁전에 침입하는 자를 없애 버리리라.'),
(62980, 12, 0, '세상의 쭉정이가 공포에 휩쓸려 문간에 굴러다니는구나. 폐하께서 일으키신 폭풍이 저들을 날려 버릴 것이다.'),
(62980, 13, 0, '폐하의 신성한 품에 들 자격이 없는 자들이었다.'),
(62980, 14, 0, '저들은 태산과 같은 폐하의 뜻에 부딪히는 파도에 지나지 않는다. 일어나고 또 일어나도 허무하게 스러지고 말 것이다.'),
(62980, 15, 0, '우리는 굳건하며 동요하지 않는다.'),
(62980, 16, 0, '신성하신 분께서 침입자에게 맞서라 하신다.'),
(62980, 17, 0, '폐하께 선택받은 목소리, 우리가 나설 차례다.'),
(62980, 18, 0, '감히 신성한 이곳을 더럽히려 하다니.'),
(62980, 19, 0, '우리는 그저 섬길 뿐이고, 너는 그저 죽을 뿐이다.'),
(62980, 20, 0, '신성한 분노의 목소리를 보라.'),
(62980, 21, 0, '우리가 들이쉬는 공기를 통해 폐하께서 우리 목소리에 힘을 주신다.'),
(62980, 22, 0, '그분의 뜻은 위대하다. 그 뜻을 받들지 않으면 죽여 주겠다.'),
(62980, 23, 0, '우리의 목소리가 그분의 뜻에 형체를 부여한다.'),
(62980, 24, 0, '황실 장로 조르로크가 단상으로 날아갑니다!'),
(62980, 25, 0, '황실 장로 조르로크가 열광의 페로몬을 들이마십니다!'),
(62980, 26, 0, '|TInterface\\Icons\\spell_druid_stamedingroar.blp:20|t황실 장로 조르로크가 숨을 크게 |cFFFF0000|Hspell:122852|h[들이쉽니다]|h|r!'),
(62980, 27, 0, '|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t황실 장로 조르로크가 목소리로 공격대 대원들을 |cFFFF0000|Hspell:122740|h[개종]|h|r시켜 자기 편에서 싸우게 합니다!'),
(62980, 28, 0, '|TInterface\\Icons\\warrior_disruptingshout.blp:20|t황실 장로 조르로크가 |cFFFF0000|Hspell:122713|h[힘과 활력]|h|r을 실어 고함을 내지릅니다!'),
(62983, 1, 0, '여, 여기서 뭐하는 거예요?! 저리 가요!'),
(62983, 2, 0, '당신이 갈 때까지 숨어 있을래요!'),
(62983, 2, 1, '당신, 이제 보고 싶지 않아요!'),
(62983, 3, 0, '저리 가요!'),
(62983, 3, 1, '가까이 오지 마요!'),
(62983, 4, 0, '오, 미안해요!'),
(62983, 4, 1, '당신 잘못이에요!'),
(62983, 5, 0, '여, 여기서 뭐하는 거예요?! 저리 가요!'),
(62983, 6, 0, '아... 앗! 내가 무슨...? 혹시...? 너무... 흐릿해.'),
(62983, 7, 0, '이제 가야 해요.'),
(62983, 8, 0, '흐린 물을 맑게 해야 해요. 혹시... 도와 줄래요?'),
(62988, 0, 0, '고맙습니다!'),
(62989, 0, 0, '고맙습니다!'),
(62990, 0, 0, '고맙습니다!'),
(63013, 0, 0, '이 드워프를 내 새 의자에서 쫓아 주면 음식을 공짜로 드리지요!'),
(63179, 0, 0, '침입자 놈아! 호박석은 우리 것이다! 사마귀를 위한 게 아니야!'),
(63217, 0, 0, '이 돌은 2,500년 전 이곳에 살았던 위대한 호젠 군주에 대한 이야기를 담고 있네. 자네들의 지도자는 어떤가? 시인인가? 전사인가? 언젠가 만나보고 싶군.'),
(63217, 1, 0, '조심하게! 사우록 약탈꾼이 다가오네!'),
(63217, 2, 0, '사우록은 모구의 시대부터 이 땅을 약탈해 왔네. 협상이 불가능한 종족이지만, 우린 계속해서 노력한다네! 다른 도리가 없을 때만 이렇게 싸우지.'),
(63217, 3, 0, '도와줘서 고맙네. 이 기록은 연구에 꼭 필요하다네. 자네들도 지식의 가치를 잘 알겠지? 그럴 거라고 믿네. 그렇게 거대한 비행선을 타고 왔으니 말이야.'),
(63256, 0, 0, '이이이야아아아!'),
(63307, 0, 0, '이제 필요한 건 모두 챙겼네. 어서, 저들이 돌아오기 전에 피하세!'),
(63307, 1, 0, '판다렌의 역사는 이 정도로 끝내지. 이제 자네 얘기를 하세.'),
(63307, 2, 0, '자네 행동을 보면서 이미 많은 것을 알았네. 자네에게선 젊은이의 열정과 노병의 경험이 함께 보이더군. 일생 동안 전장에서 살았겠지?'),
(63307, 3, 0, '아, 여긴 특별한 장소라네. 우리 증조부, 증조모께서는 이 숲을 집이라고 부르셨네. 이리 오게. 잠깐이면 되네.'),
(63307, 4, 0, '우리 판다렌은 조상을 숭배하지 않네. 하지만 그분들이 우리에게 물려주신 기억과 지혜를 존중하지.'),
(63307, 5, 0, '얼마 전에 들려줬던 모구 이야기는, 바로 우리 증조부께서 내게 알려주신 거네.'),
(63315, 0, 0, '최초의 공식 전투 행사, 파멸의 투기장에 온 걸 환영해.'),
(63315, 1, 0, '자네의 무용을 백호 님 앞에서 증명해 보일 준비가 됐나?'),
(63315, 2, 0, '징을 울린 다음에, 수도사들에게 자네 실력을 보여 줘! ...방법은 상관없어.'),
(63315, 3, 0, '기술과 힘을 증명하기 위한 첫 상대로, 가장 강력한 용거북인 흉터껍질을 소개하지!'),
(63315, 4, 0, '휴, 아수라장이 됐군! 누가 수도원 주방에 연락 좀 하지그래. 오늘 저녁은 거북 수프라고!'),
(63315, 5, 0, '다음 전투를 치를 준비가 됐나? 징을 울리고 시작하게!'),
(63315, 6, 0, '이번에는 그루멀을 잡아먹는 괴수, 키가 5미터에 달하는 분노의 털북숭이, 쿤라이 봉우리를 떠도는 눈밭의 공포, 졸그럼의 차례야!'),
(63315, 7, 0, '아이쿠! 졸그럼이 자네들 같은 살상 기계를 셋이나 상대할 준비는 안 돼 있었던 모양인걸! 준비 얘기가 나와서 말인데...'),
(63315, 8, 0, '이 꼬마는 친구를 사귀러 왔지... 친해지고 나면 불태워 버리려고 말이야! 판다리아에서 가장 귀엽고 발랄한 꼬마 방화광, 리우양을 소개하겠네!'),
(63315, 9, 0, '촛불처럼 꺼져 버렸군! 과연 누가 이 삼총사와 대적할 수 있을까?!'),
(63315, 10, 0, '야크가 쳐들어왔다고?! 아니지! 탕랑 평원의 방랑 전사, 도끼의 달인 차간 파이어후프라고!'),
(63315, 11, 0, '아주 볼 만했어! 우리 대단한 싸움꾼들이 차간을 푸짐한 야운골 바비큐로 만들어버렸군...'),
(63315, 12, 0, '안개 속을 스치듯 움직이는 살인적인 주먹의 소유자, 음흉하고도 조용한 진위 암살자, 사테이 뷰를 소개하지!'),
(63315, 13, 0, '살인 생선의 전성기가 비린내 나는 최후를 맞았군.'),
(63315, 14, 0, '모두들, 파멸의 투기장의 새로운 우승자에게 환호를!'),
(63359, 0, 0, '피 추적자 스키르가 돌아왔다! 으으으윽...'),
(63359, 1, 0, '그렇습니다, 클락시바여, 의회의 명령은 무엇입니까? 피 추적자가 듣고 복종하겠습니다.'),
(63359, 2, 0, '여제 셰크지르가 우리 제국을 혼란에 빠뜨린 것 같구나. 이것은 반드시 짚고 넘어가야 한다. 하지만 그보다 먼저, 내 힘을 회복해야만 한다.'),
(63420, 0, 0, '동굴이 격렬하게 흔들립니다!'),
(63420, 1, 0, '안개 속에서 고대 야수가 꿈틀댑니다!'),
(63420, 2, 0, '|cFFF00000메가이라|r가 안개 속에서 나타납니다!'),
(63420, 3, 0, '|TInterface\\Icons\\inv_misc_volatilefire:20|t당신은 |cFFF00000|Hspell:139822|h[잿불]|h|r에 걸렸습니다!'),
(63420, 4, 0, '|TInterface\\Icons\\spell_frost_piercing chill:20|t당신은 |cFFF00000|Hspell:139866|h[얼음 격류]|h|r의 대상이 되었습니다!'),
(63420, 5, 0, '|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t메가이라가 |cFFF00000|Hspell:139458|h[광란]|h|r 상태에 빠집니다!'),
(63420, 6, 0, '메가이라의 분노가 가라앉습니다.'),
(63520, 0, 0, '|TInterface\\Icons\\creatureportrait_bubble.blp:20|t%s|1이;가; |cFFFF0000|Hspell:124653|h[물 보호막]|h|r을 시전합니다! 용오름을 사용해 터뜨리십시오!'),
(63528, 0, 0, '전쟁인도자 코비가 도끼를 떨어뜨렸습니다. 집어 드십시오!'),
(63535, 0, 0, '우릴 구하러 온 사람이 있다고? 희망이 아예 없는 건 아니로군...'),
(63542, 0, 0, '우릴 구하러 온 사람이 있다고? 희망이 아예 없는 건 아니로군...'),
(63751, 0, 0, '"호드"에 대해서 잘은 모르지만, 당신은 믿음직해 보여요. 사람을 모아둘 테니, 재건을 시작할 준비가 되면 만나요!'),
(63754, 0, 0, '"얼라이언스"에 대해서 잘은 모르지만, 당신은 믿음직해 보여요. 사람을 모아둘 테니, 재건을 시작할 준비가 되면 만나요!'),
(63811, 0, 0, '고맙습니다, $p님! 다 끝인 줄로만 알았습니다.'),
(63811, 1, 0, '사우록 놈들이 나타난 데다 배까지 난파되는 바람에 겁에 질렸습니다.'),
(63818, 1, 0, '전쟁인도자가 다가온다! 후퇴하라!'),
(63942, 0, 0, '변명은 이제 지겹다, 여제! 당장 이 멍청이들을 쓸어버리지 않으면 내가 몸소 널 죽이겠다!'),
(63942, 1, 0, '이 이방인들을 처치해야만 한다, 여제여! 그대의 신민을 정복하러 온 자들이다!'),
(63942, 2, 0, '쓸모없는 것! 내 앞에서 죽어라, 하찮은 곤충아. 너희 종족은 내게 아무런 가치가 없다!'),
(63942, 3, 0, '나머지 놈들은 자신 있으면 날 찾아 봐라. 다른 놈들처럼 비명을 지르며 죽어가겠지만.'),
(63955, 0, 0, '%s|1이;가; 따뜻한 온천의 물줄기 사이로 신나게 헤엄칩니다.'),
(63955, 1, 0, '%s|1이;가; 안개돌이호의 뱃머리를 매만지며 훌쩍입니다.'),
(63955, 2, 0, '%s|1이;가; 고래 시체에 영역을 표시하기 전에 조심스럽게 둘러봅니다.'),
(64072, 0, 0, '한 판 더 하시겠소?'),
(64072, 0, 1, '좋은 수였소.'),
(64115, 0, 0, '흥. 좋은 카드군.'),
(64115, 0, 1, '알았네, 자네가 이겼어.'),
(64115, 0, 2, '삼판이승일세!'),
(64164, 0, 0, '설령 무기가 손에서 빠져나가도 걱정하지 마시오. 맨몸으로 어떤 적이든 상대할 수 있다오.'),
(64185, 0, 0, '바타리 전투 설인이 고대의 통로 쪽에서 다가옵니다!'),
(64185, 1, 0, '바타리 전투 설인이 다리 쪽에서 다가옵니다!'),
(64185, 2, 0, '바타리 전투 설인이 서쪽에서 다가옵니다!'),
(64312, 0, 0, '흐음, 잘 모르겠습니다. $r님. 제가 알아들을 수 있는 건 계곡에 관한 부분뿐이군요. 바로 여기니까요! 네 바람의 계곡 말입니다!'),
(64315, 0, 0, '아, 조상의 계단 이야기는 들어본 적 있습니다. 여기 주민 중 누가 북쪽에 있는 산을 그렇게 부르더군요.'),
(64327, 0, 0, '메아리는 뭐고 어둠은 뭐냐고요? 간단하지 않습니까! 바로 동굴입니다!'),
(64361, 0, 0, '가오 아저씨, 아저씨가 양조장 관리를 맡았다면서요. 어떻게 된 거죠?'),
(64361, 1, 0, '그 대가는요? 양조장이 쓰레기장이 됐잖아요!'),
(64361, 2, 0, '게다가 중앙 창고는 토깽이 천지예요!'),
(64361, 3, 0, '양조장에 불이 난 것 같아요.'),
(64389, 0, 0, '으음! 맛있는 양 냄새가 나는데!'),
(64389, 1, 0, '양고기로 군것질해야지!'),
(64528, 0, 0, '아, 또 안개 너머에서 온 이방인인가.'),
(64528, 1, 0, '만 년 전, 마지막 판다렌 황제가 내 조언을 구하러 왔었지. 그 역시 갈등에 빠져 있었어. 네 말이 맞는지 보자꾸나, 타란. 이 이방인이 영혼의 혼란을 어떻게 잠재우는지 보자.'),
(64528, 2, 0, '집과 가족을 지키기 위한 것처럼 정당한 이유의 싸움은 고귀하지. 하지만 복수는? 분노는? 그런 감정들이 이 자에겐 강하게 흐르고 있다.'),
(64528, 3, 0, '잘 말했다, 즈. 안개 너머에서 온 이방인들에게 열정이 부족하진 않지. 허나 통제할 수 있을지는 봐야겠다. 분노 너머로 증오가 있다. 이는 모든 불행의 원천이지. 이건 뭐지? 네 증오에서 얼굴이 보이는군!'),
(64528, 4, 0, '이자는 분노를 통제할 수 있다. 어린 아이의 말과 이 영웅의 행동을 봤을 때, 이해가 가는구나. 안개 너머에서 온 자들은 전쟁으로 단련되었다. 전쟁은 상처를 남겼지만, 그만큼 배운 것도 많아. 난 이들을 믿는다.'),
(64536, 0, 0, '곧 저들은 이 땅을 뒤덮을 겁니다! 언제까지 지켜봐야만 한다는 겁니까?'),
(64536, 1, 0, '비취 숲에서 자네가 도움을 준답시고 거드는 걸 봤네. 이 호드니 얼라이언스니 하는 것들은... 도무지 자제심이라고는 없더군. 네놈들이 지나간 길에는 파괴와 고통뿐이지.'),
(64536, 2, 0, '폭력... 보셨습니까? 저들에겐 그것뿐입니다.'),
(64536, 3, 0, '너희들은 서로 이기려고 날뛸 뿐이야!'),
(64536, 4, 0, '보셨습니까? 이들이 서로 얼마나 증오하는지 보십시오! 전장에 그 증오를 품고 나가서 무덤까지 가져갈 겁니다!'),
(64537, 0, 0, '사실이네. 이들은 강하네. 우리가 배울 게 많아.'),
(64537, 1, 0, '분노가 없는 삶은 죽음과 같네. 오히려 우리가 이겨내야 할 숙제지. 우린 분노를 이김으로써, 큰 힘을 얻게 된다네.'),
(64537, 2, 0, '흥미롭지 않나. 이들은 우리 땅에 많은 것들을 가져왔지만, 전쟁의 그림자도 함께 몰고 왔어.'),
(64540, 0, 0, '힘을 보태고 싶습니다. 골짜기를 재건하는 걸 돕고 싶어요.'),
(64540, 1, 0, '네... 우리는 투사예요. 거친 땅에서 왔기 때문이죠. 우린 악마와, 죽음과 싸웠고, 세계의 종말과도 맞서야 했어요!'),
(64540, 2, 0, '네, 분노는 우리의 일부예요. 하지만 통제할 수 있어요. 오크는 한때 분노에 이끌리고 피에 굶주린 채 살았어요. 하지만 결국엔 이겨냈죠.'),
(64540, 3, 0, '저 모습은... 가로쉬 헬스크림이에요!'),
(64540, 4, 0, '아니, 그렇지 않아요. 우리에겐 증오가 전부가 아니라고요!'),
(64540, 5, 0, '평화가 찾아올 거예요. 맹세할게요. 낡은 증오는 사라질 거고요. 믿어 주세요.'),
(64562, 0, 0, '시작이군. 끝까지 살아남아 주길 바란다.'),
(64562, 1, 0, '우리가 널 잡으러 간다, 칠하트! 복수의 시간이다!'),
(64562, 2, 0, '조교의 영혼이 파괴되자 말하는 해골이 킬킬거리며 웃습니다.'),
(64562, 3, 0, '말하는 해골은 전당 안에 들어서기를 망설이는 듯하더니, 결국은 당신을 따라 들어옵니다.'),
(64562, 4, 0, '난... 차마 볼 수가 없군.'),
(64562, 5, 0, '말하는 해골이 입을 꾹 다물고 다음 방으로 가버립니다.'),
(64562, 6, 0, '죽어라, 간들링! 놈을 없애!'),
(64562, 7, 0, '안 돼! 돌아와라, 비겁한 놈!'),
(64562, 8, 0, '가자!'),
(64562, 9, 0, '저기 있군! 어서 놈을 없애라, $p!'),
(64562, 10, 0, '놈을 잡아! 여자는 신경 쓰지 마라!'),
(64562, 11, 0, '죽을 준비나 해라, 이 악당!'),
(64812, 0, 0, '잘됐군. 얘기 좀 하지.'),
(64812, 1, 0, '통! 마실 걸 가져와라.'),
(64812, 2, 0, '내 아버지, 데스윙은 온 아제로스를 파괴하려 했었지.'),
(64812, 3, 0, '물론 그는 제정신이 아니었다. 하지만 하나는 옳았어. 우리 세계는... 너무나도 연약해.'),
(64812, 4, 1, '우린 어둠뿐인 이 우주에서 단 하나의 빛이다. 폭풍우 속의 촛불이지.'),
(64812, 5, 0, '가끔은 그런 생각을 한다. 이 세계의 불안정함이, 아버지를 광기로 몰고 간 게 아닐까.'),
(64812, 6, 0, '아, 고맙다, 통.'),
(64812, 7, 0, '자, 본론으로 돌아가서, 지금 우리는 심판의 날을 향해 달리고 있다. 아니, 현재 벌어지는 얼라이언스와 호드의 분쟁을 얘기하는 게 아니야.'),
(64812, 8, 0, '내 말을 믿어라. 가로쉬 헬스크림이 테라모어에서 만들어낸 어둠은 아무것도 아니다. 바로 지금도 우리 연약한 고향을 향해 돌진하는, 그 공포에 비하면 말이지.'),
(64812, 9, 0, '하지만 전쟁이 매우 신경 쓰이긴 하는군. 왜인지 알겠나?'),
(64812, 10, 0, '분열된 아제로스는 절대로 그 끔찍한 어둠에 맞설 수 없다.'),
(64812, 11, 0, '이 전쟁은 끝나야 해. 그것도 빨리! 전쟁이 우리 힘을 갉아먹기 전에.'),
(64812, 12, 0, '내가 너희 호드의 충실한 친구라는 건 믿어 줬으면 좋겠군.'),
(64812, 13, 0, '이건 알아 주면 좋겠군. 나는 이 원정에서 너희 얼라이언스를 전폭적으로 지지하고 있다.'),
(64812, 14, 0, '이 분쟁을 어떻게 빠르고 확실하게 끝낼 것인가? 그 해답은 너와 같은 영웅들에게서 찾아야겠지.'),
(64812, 15, 0, '먼저 네 실력을 확인해야겠다. 그 후에 적절한 장비를 주지.'),
(64822, 0, 0, '생각이 필요할 때면 여길 찾아오지. 숨막히는 경치야. 그렇지 않나?'),
(64822, 1, 0, '판다리아는 보석 같은 땅이야. 참으로 아름답지. 지켜 주고 싶어지지 않나?'),
(64822, 2, 0, '사실 온 아제로스에 대해 난 같은 감정을 느낀다.'),
(64822, 3, 0, '참으로 훌륭한 일을 해 주었다, 친구여. 하지만 이건 우리가 함께 할 일의 시작일 뿐이야.'),
(64822, 4, 0, '똑똑히 보아라. 네가 쓰러뜨린 적들의 힘을.'),
(64822, 5, 0, '그리고 네가 능가한 그들의 지혜를.'),
(64822, 6, 0, '자, 네가 쓰러뜨린 공포의 화신이다. 이제 이것이 네 적의 가슴속에 두려움을 불러일으키길!'),
(64822, 7, 0, '마지막으로, 내 선물을 더해 주지. 착각하지 마라. 검은용군단은 아직 건재하다!'),
(64822, 8, 0, '자, 내 할일은 끝났다. 샤의 기운이 깃든 무기를 이 물건으로 강화할 수 있지.'),
(64838, 1, 0, '시체 더미를 파괴해 미라가 된 시체를 멈추십시오!'),
(64881, 0, 0, '저는 한 마디도 이해가 안 되는데요.'),
(64881, 1, 0, '우리가 커다란 거북이 등에 산다고요?!'),
(64881, 2, 0, '어쩐지 산에 지느러미발이 달려 있는 게 이상하다 했어!'),
(64881, 3, 0, '우리가 여기 사는 걸 거북이도 알아요?'),
(64881, 4, 0, '이봐!'),
(64881, 5, 0, '맞아, 너희 다 나를 닮아야 돼.'),
(64881, 6, 0, '그러면 우리 엄마, 아빠랑 할머니, 할아버지가 다 탐험가였단 말이에요?'),
(64881, 7, 0, '나도 세상을 탐험하고 싶어!'),
(64881, 8, 0, '그래? 그럼 안 할래.'),
(64881, 9, 0, '뭐지?'),
(64881, 10, 0, '그건 안가능해요!'),
(64901, 0, 0, '반갑네, $n! 혹시 잠깐 시간 있나?'),
(64901, 1, 0, '그게 마지막 재료였네! 잘했네, $p! 이제 축제를 시작할 수 있겠군!'),
(64901, 2, 0, '키우, 타르트, 부자키! 재료를 모두 던져 넣게나!'),
(64901, 3, 0, '이제부터가 어려운 부분이지. 모두 물러서게나. 완벽한 뻥뻥주를 만드는 데는 정확성이 생명이거든!'),
(64901, 4, 0, '야운골!? 지금!?'),
(64901, 5, 0, '쿤라이 뻥뻥주를 노리고 온 게로군! $p, 정찰대를 확인하고 마을 방비를 단단히 하게! 그렇게 호락호락 내 맥주를 넘겨주진 않을 걸세!'),
(64901, 6, 0, '나는 맥주가 완성될 때까지 이곳을 지키겠네. 그러고 나면 뻥뻥주를 이용해서 바타리 놈들을 상대할 수 있지! 나머지는 모두 안전한 곳으로 피하게!'),
(64901, 7, 0, '쿤라이 뻥뻥주가 완성됐네, $p! 이제 이걸로 야운골 놈들을 걷어차 줄 수 있겠군.'),
(64901, 8, 0, '잘했네, $p. 자네가 마을을 구했네. 이 은혜는 영영 잊지 않겠네.'),
(64946, 0, 0, '으으음... 흐음... 이건 정말... 끝내주는 맛이군. 자네 친구 엘라는 정말 솜씨가 뛰어난데! 엘라에게 스톰스타우트 양조장에 있는 가오 아저씨와 이야기해보라고 하게나. 곧 엘라의 새로운 집이 될 것 같으니까 말일세.'),
(65153, 0, 0, '당신의 검을 쥐십시오, 여행자여!'),
(65153, 1, 0, '이 야수는 갈퀴발 놀 무리를 이끌며 엘윈 숲에서 놀의 침략을 종식시키는 데 실마리가 될 것이다.'),
(65153, 2, 0, '바리안 린 국왕 폐하의 이름으로 들창코를 수감하도록 한다.'),
(65153, 3, 0, '안드로매스, 우릴 지하감옥으로 이동시켜 주시오.'),
(65271, 0, 0, '누구 없습니까?! 제발 도와주십시오!'),
(65271, 1, 0, '정말 감사합니다!'),
(65315, 3, 0, '구르세요!'),
(65442, 0, 0, '아무도 널 지킬 수 없다! 저 계집을 죽이고, 폭탄을 가져와라!'),
(65442, 1, 0, '말은 씩씩하구나. 네가 자비를 구걸할 때 그 얼굴에 침을 뱉어 주마.'),
(65470, 0, 0, '당신만큼 출중한 수련생은 처음 봅니다. 다른 이들에게도 이야기해야겠습니다.'),
(65470, 0, 1, '당신 실력에 미치려면 아직 멀었군. 패배를 인정하겠소.'),
(65470, 0, 2, '고맙습니다. 더욱 부지런히 수련하기로 다짐하는 계기가 됐습니다.'),
(65470, 0, 3, '좋은 싸움이었소. 고맙소.'),
(65470, 0, 4, '당신은 훌륭한 대련 상대군요.'),
(65470, 0, 5, '명예롭게 싸우는군요, 친구.'),
(65470, 0, 6, '잘 싸우셨습니다. 나중에 또 한 수 가르쳐 주십시오.'),
(65470, 0, 7, '실력이 대단하오. 졌소.'),
(65471, 0, 0, '당신만큼 출중한 수련생은 처음 봅니다. 다른 이들에게도 이야기해야겠습니다.'),
(65471, 0, 1, '당신 실력에 미치려면 아직 멀었군. 패배를 인정하겠소.'),
(65471, 0, 2, '고맙습니다. 더욱 부지런히 수련하기로 다짐하는 계기가 됐습니다.'),
(65471, 0, 3, '좋은 싸움이었소. 고맙소.'),
(65471, 0, 4, '당신은 훌륭한 대련 상대군요.'),
(65471, 0, 5, '명예롭게 싸우는군요, 친구.'),
(65471, 0, 6, '잘 싸우셨습니다. 나중에 또 한 수 가르쳐 주십시오.'),
(65471, 0, 7, '실력이 대단하오. 졌소.'),
(65475, 0, 0, '죽었나? 끝난 거지?'),
(65478, 0, 0, '공명하는 수정을 내놔라, 이 나무 껍데기나 먹는 애송이 놈아!'),
(65501, 0, 0, '하찮은 땅벌레들. 내 구역에 들어오면 너희를 이 밖으로 내던지고, 그 죽는 소리를 감상해주마!'),
(65501, 1, 0, '세트티크! 정렬! 판다리아의 바람을 누가 지배하는지 보여줘라!'),
(65501, 2, 0, '폐하의 숨결이여, 우리에게 무적의 가랄론을 내리소서!'),
(65501, 3, 0, '가랄론, 놈들의 뼈를 갈아버려라!'),
(65501, 4, 0, '이럴 수가! 너희들! 난간뜰 꼭대기로! 여왕님을 지켜야 한다!'),
(65586, 0, 0, '감사합니다. 큰 빚을 졌습니다.'),
(65586, 1, 0, '우리에 갇혀 있는 동안 들은 것이 많습니다. 런싸이 님께 말씀드리면 기뻐하실 겁니다.'),
(65586, 2, 0, '곧 또 만나지요, 친구.'),
(65590, 0, 0, '$n|1이;가; 번개 덫을 밟았습니다!'),
(65910, 0, 0, '잠깐 기다리게, 텅. 여기... 손님이 오셨군.'),
(65977, 0, 0, '들고 있는 무기에서 힘을 얻는 적이 있습니다. 그럴 때는 무기를 빼앗으면 적의 힘이 줄어들지요.'),
(65977, 1, 0, '당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.'),
(65977, 2, 0, '대단히 강하군요. 패배를 인정합니다.'),
(66073, 0, 0, '가장 좋은 방어는, 상대의 움직임을 차단하는 것입니다.'),
(66073, 1, 0, '당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.'),
(66073, 2, 0, '대단히 강하군요. 패배를 인정합니다.'),
(66138, 0, 0, '수도사인 당신에게는, 반사 신경이 아주 큰 재산입니다. 빠르게 생각하고 움직일 수 있는 능력이 목숨을 구해 주기도 하니까요.'),
(66138, 1, 0, '당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.'),
(66138, 2, 0, '사부 쳉이 당신을 산 채로 태웁니다! 이동하십시오!'),
(66138, 3, 0, '잘하셨습니다. 지금처럼 몸과 정신을 빠르게 움직이면 살아남을 수 있을 겁니다.'),
(66149, 0, 0, '주먹으로 모든 문제를 해결할 수 있는 건 아닙니다. 때로는 정신을 집중하고 멀리 있는 목표물을 향해 기운을 보내야 하지요.'),
(66149, 1, 0, '당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.'),
(66149, 2, 0, '졌습니다.'),
(66207, 0, 0, '안녕하십니까.'),
(66255, 0, 0, '함께 훈련할 일이 기대되는군요.'),
(66257, 0, 0, '평온의 봉우리에 잘 오셨습니다. 훈련에 행운이 따르기를.'),
(66258, 0, 0, '환영합니다. 시작할 준비가 되면 제게 말씀하십시오.'),
(66260, 0, 0, '내 조수가 자네를 쳉 사부에게 데려다줄 걸세. 행운을 비네!'),
(66366, 0, 0, '이제... 집에 가도 돼요?'),
(66366, 0, 1, '여기서 데려가 주세요!'),
(66366, 0, 2, '엄마 아빠가 보고 싶어요. 집에 갈래요!'),
(66366, 0, 3, '저 눈은... 날 혼자 내버려두지 않아요!'),
(66366, 0, 4, '나... 나는... 영원히 여기 갇히는 줄 알았어요.'),
(66366, 0, 5, '고마워요! 나는 호드가 정말 싫어요.'),
(66374, 0, 0, '아우, 진짜 아프잖아. 농담이지롱.'),
(66374, 0, 1, '아아, 커다랗고 나쁜 모구 님. 너무 무서워요.'),
(66374, 0, 2, '어디 한번 덤벼 봐.'),
(66374, 0, 3, '한판 붙어 볼래?'),
(66374, 0, 4, '겨우 그 정도냐?'),
(66374, 0, 5, '간지럽지도 않네.'),
(66374, 0, 6, '너 고문 잘 못하는구나.'),
(66374, 0, 7, '방금 그거 아프라고 한 거였어?'),
(66396, 0, 0, '우리 땀과 네 피로, 이 땅은 우리 것이 되리라!'),
(66564, 0, 0, '감사합니다, 친구. 걱정 마십시오. 그냥 긁힌 상처입니다. 이제 다시 태어난 것처럼 기운이 나네요!'),
(66564, 0, 1, '이제 죽은 목숨이라고 생각했습니다. 당신은 제 생명의 은인이십니다.'),
(66564, 0, 2, '구출해주셔서 감사합니다. 앞선 전투는 꽤 힘에 겨웠습니다.'),
(66564, 0, 3, '저 지금... 살아 있는 겁니까? 하! 가로쉬아르 거점의 호드들에게 인사를 전하고 싶군요. 우리가 아주 혼쭐을 내줬습니다.'),
(66564, 0, 4, '감사합니다. 어서 상처를 치료하고 다시 전투를 시작해야겠습니다!'),
(66565, 0, 0, '감사합니다, 친구. 걱정 마십시오. 그냥 긁힌 상처입니다. 이제 다시 태어난 것처럼 기운이 나네요!'),
(66565, 0, 1, '이제 죽은 목숨이라고 생각했습니다. 당신은 제 생명의 은인이십니다.'),
(66565, 0, 2, '구출해주셔서 감사합니다. 앞선 전투는 꽤 힘에 겨웠습니다.'),
(66565, 0, 3, '저 지금... 살아 있는 겁니까? 하! 가로쉬아르 거점의 호드들에게 인사를 전하고 싶군요. 우리가 아주 혼쭐을 내줬습니다.'),
(66565, 0, 4, '감사합니다. 어서 상처를 치료하고 다시 전투를 시작해야겠습니다!'),
(66567, 0, 0, '감사합니다, 친구. 걱정 마십시오. 그냥 긁힌 상처입니다. 이제 다시 태어난 것처럼 기운이 나네요!'),
(66567, 0, 1, '이제 죽은 목숨이라고 생각했습니다. 당신은 제 생명의 은인이십니다.'),
(66567, 0, 2, '구출해주셔서 감사합니다. 앞선 전투는 꽤 힘에 겨웠습니다.'),
(66567, 0, 3, '저 지금... 살아 있는 겁니까? 하! 가로쉬아르 거점의 호드들에게 인사를 전하고 싶군요. 우리가 아주 혼쭐을 내줬습니다.'),
(66567, 0, 4, '감사합니다. 어서 상처를 치료하고 다시 전투를 시작해야겠습니다!'),
(66732, 0, 0, '나를 꺾으려면, 다른 사부들에게서 배운 것을 모두 활용해야 할 걸세. 그럴 수 있다면 훈련은 끝난 것이지.'),
(66732, 1, 0, '당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.'),
(66732, 2, 0, '잘했네. 이제 훈련은 끝이 났네. 흑우의 제단으로 오면 보상을 주겠네.'),
(66791, 0, 0, '반역의 무리 클락시... 너희에 대한 폐하의 말씀이 옳았군.'),
(66791, 1, 0, '여제 폐하의 목소리, 황실 장로 조르로크다.'),
(66791, 2, 0, '클락시는 해체될 것이다. 그것이 여제 폐하의 뜻이다.'),
(66791, 3, 0, '하! 클락시 놈들... 궁지에 몰리니 화석까지 파냈군. 좋다. 이제 끝내 주마.'),
(66791, 4, 0, '흥, "다치지 않는"다더니.'),
(66791, 5, 0, '전진! 클락시는 반역자 도당이었다. 씨를 말려라. 단 한 놈도 살려 두지 마라.'),
(66797, 0, 0, '이 무리를 움직이는 자가 누구냐? 클락시의 물음에 답하라.'),
(66797, 1, 0, '이름을 말해라. 우리가 나눌 얘기는 그것뿐이다.'),
(66797, 2, 0, '너희 "폐하"는 이제 끝이야. 당장 물러서라. 아니면 죽음을 맞는 수밖에.'),
(66797, 3, 0, '감히 그런 소릴!'),
(66800, 0, 0, '깨우는 자여, 너는 그간의 행동으로 클락시의 믿음을 얻어냈다.'),
(66800, 1, 0, '이제 그 보상을 얻으리라. 잠시 걷지.'),
(66800, 2, 0, '우리 사마귀족은 고대 종족이다. 너희와 손잡은 판다렌은 아이에 불과해. 물론 그들에게도 역할이 있지.'),
(66800, 3, 0, '순환의 때마다, 우리 어린것들이 판다렌의 장벽을 덮친다. 약자는 죽고, 강자만 돌아오지.'),
(66800, 4, 0, '그렇게 세대를 거듭하며, 우리는 더욱 강해진다.'),
(66800, 5, 0, '너희 문명이 시작되기 전, 우리 제국은 광활했다. 형제 왕국인 안퀴라즈, 아졸네룹과 함께 세상을 호령했지.'),
(66800, 6, 0, '우리 신은 수가 많고 강력했어. 우린 이샤라즈의 일곱 머리를 섬겼지.'),
(66800, 7, 0, '고대 신은 위대했고, 그 분노는 끔찍했다. 이샤라즈는 희망을 삼키고 절망을 불렀다. 용기를 들이마시고 공포를 내뿜었지.'),
(66800, 8, 0, '강탈자들... 너희가 티탄이라 부르는 자들이 왔을 때, 이샤라즈는 파멸했다.'),
(66800, 9, 0, '그의 끔찍한 마지막 숨결이 이 땅을 물들였지만, 지금 남은 어둠은 과거의 영광에 비하면 그림자에 불과해.'),
(66800, 10, 0, '잘 들어라. 네가 자격이 있기에 말해주는 것이다.'),
(66800, 11, 0, '너희의 신은 우리의 신이 아니다, 이방인이여.'),
(66800, 12, 0, '고대 신들이 돌아오면, 우리 사마귀족은 다시 한 번 그 옆에 설 것이다.'),
(66800, 13, 0, '그리고 너희 중 현명한 자들도 그리하겠지.'),
(66844, 0, 0, '절 따라오십시오. 평온의 봉우리를 안내해 드리지요.'),
(66844, 1, 0, '여기 있는 동안 마음껏 즐기십시오. 평온의 봉우리에서 보는 쿤라이 봉우리는 정말 장관이랍니다.'),
(66844, 2, 0, '이곳에는 여러 가지 공예의 대가들이 있습니다. 여행 중에 쓸 보급품이 필요하다면 그들이 도와줄 수 있을 겁니다.'),
(66844, 3, 0, '이곳은 훈련장입니다. 훈련은 대부분 여기서 진행되지요. 오시지요. 당신을 가르칠 사부님들을 소개해 드리겠습니다.'),
(66844, 4, 0, '이분은 키스테인 사부님이십니다. 안개의 힘을 써서 아군을 돕는 데 능하시지요.'),
(66844, 5, 0, '이분은 우 사부님이십니다. 집요한 공격을 막아내는 데 특히 능하시지요.'),
(66844, 6, 0, '이분은 윤 사부님이십니다. 전투 중에 강력하고 집중적인 치유 주문을 사용해 체력을 관리하는 데 능하시지요.'),
(66844, 7, 0, '이분은 쳉 사부님이십니다. 움직이면서 싸우는 데 도가 트셨지요.'),
(66844, 8, 0, '이분은 창 사부님이십니다. 명상의 달인으로서, 주위에서 무슨 일이 일어나는지 감지하는 능력이 있으시지요.'),
(66844, 9, 0, '이분은 슈 사부님이십니다. 태양 아래 거의 모든 무기를 능히 다루시지요.'),
(66844, 10, 0, '마지막으로, 이분은 쳉 사부님이십니다. 빠른 반응과 움직임이 특기로, 당신이 훈련을 시작하도록 도와주실 것입니다.'),
(66844, 11, 0, '그럼, 전 이만 가야겠군요. 훈련에 행운이 따르길 빕니다.'),
(66870, 0, 0, '통을 들고 가는 걸 도와드리겠습니다. 혹시 마법처럼 당신 가방 속에 쏙 들어갈 거라고 생각했습니까?'),
(66870, 1, 0, '우리 마을은 당신의 전쟁에 참여하지 않을 겁니다. 하지만, 당신들이 나타나면서 우리의 평화로운 삶이 영원히 바뀌어버렸을지 모른다는 걱정이 드는군요.'),
(66870, 1, 1, '당신의 행동이 틀림없이 음영파의 주의를 끌 겁니다. 어쩌면 저도 음영파를 만나볼 수 있겠군요!'),
(66870, 1, 2, '한 통쯤이야! 저는 키가 당신 무릎만큼도 안 되는 어린 꼬마였을 때부터 술 한 통을 쉽게 들고 다녔습니다!'),
(66870, 2, 0, '무겁지만 더 들 수 있습니다! 계속 갑시다!'),
(66870, 2, 1, '아주 사소한 불편함일 뿐이오.'),
(66870, 2, 2, '서로의 차이점을 그냥 얘기로 풀어버릴 수 없는 이유가 뭡니까? 즐겁고 긴 대화로 풀 수 없는 문제는 제 평생 만나본 적이 없습니다!'),
(66870, 3, 0, '왜 우리 땅에서까지 전쟁을 이어가려 하는 겁니까? 당신들 고향은 어쩌고요? 그곳에는 싸울 가치가 있는 게 없습니까?'),
(66870, 3, 1, '싸움은 시간 낭비입니다. 어떻게 그렇게 내내 싸우기만 합니까? 작은 일에 기뻐하고 즐길 시간이 있기나 합니까?'),
(66870, 3, 2, '호드, 얼라이언스... 차이가 뭡니까?! 모두 좋은 술을 좋아하지 않습니까? 친구와 가족들을 똑같이 소중하게 생각하지 않습니까?'),
(66870, 4, 0, '아무래도 제 힘을 과대평가한 모양입니다...'),
(66870, 4, 1, '이제 그만, 여기까지가 제 한계입니다! 정말 힘든 일이군요!'),
(66870, 5, 0, '이 꿀술은 이 마을의 생명줄입니다. 그렇게 생각하면 싸울 만한 가치가 있겠죠!'),
(66870, 5, 1, '꿀이슬 마을은 허니듀 가문이 운영합니다만, 마을의 진짜 중심은 바로 양조장입니다! 양조장은 우리 가문, 허니포우 가문의 소유입니다. 세계 최고의 꿀술을 빚어내지요!'),
(66870, 6, 0, '도와주셔서 감사합니다. 이 꿀술은 꼭 마을까지 가져가겠습니다. 또 뭘 날려버리거나 하진 마십시오!'),
(66870, 6, 1, '도와주셔서 감사합니다. 또 뭘 날려버리거나 하진 마십시오!'),
(67260, 0, 0, '투기장에 들어서는 건... 1계급 $r $c인 $n입니다! $n|1은;는; 여기 새로 온 친구니까, 살살 해봐요!'),
(67260, 1, 0, '요새 한창 잘나가는 2계급 $c, $n|1이;가; 싸움장에 들어섭니다!'),
(67260, 2, 0, '$n에게 박수를 부탁드립니다! $n|1은;는; 3계급 $c입니다.'),
(67260, 3, 0, '도전자가 나타났습니다. 4계급 $r $c, $n|1을;를; 환영해 주십시오!'),
(67260, 4, 0, '지금 싸움장에 주먹이 매콤한 $c|1이;가; 등장했습니다. 5계급 싸움꾼, $n에게 인사하세요!'),
(67260, 5, 0, '조심하십시오... 무시무시한 6계급 $r, $n|1이;가; 등장합니다!'),
(67260, 6, 0, '지금 싸움장에 들어서는 건... 돌아온 최고의 싸움꾼, 7계급 $c $n입니다!'),
(67260, 7, 0, '드디어! 다들 아시죠? 다들 사랑하시죠? 8계급 싸움꾼, $N에게 박수를 부탁드립니다!'),
(67260, 8, 0, '싸움굴의 9계급 베테랑 싸움꾼, $n|1을;를; 소개합니다!'),
(67260, 9, 0, '이어서 어딘가에서 발견된 악어 브루스가 투기장에 등장합니다!'),
(67260, 10, 0, '이에 맞설 상대는... 천둥왕의 추종자, 일촉즉발의 비안입니다!'),
(67260, 37, 0, '승자는 $n입니다!'),
(67260, 37, 1, '이런 이런 이런... $n|1이;가; 이겼네요! 저도 돈을 좀 잃은 것 같아요.'),
(67260, 37, 2, '축하합니다, $n! 거기 투기장 밖에 피투성이 발자국은 남기지 마세요.'),
(67260, 37, 3, '끝났습니다! $n|1이;가; 가까스로 살아남았습니다. 정말 아슬아슬했네요, $n!'),
(67260, 38, 0, '아이코... 안됐네요, $n 님. 다시 도전해 보세요. 줄은 다시 서야 해요.'),
(67260, 38, 1, '우엑... 정말 처참하네요. 누가 사제나 뭐 그런 친구 하나 불러 줄래요?!'),
(67260, 38, 2, '그거 참... 안 좋게 끝났네요.'),
(67260, 38, 3, '$n, $n, 우리 $n... 다음 번에는 이렇게 자주 죽지 마세요.'),
(67263, 0, 0, '검은부화 도마뱀군주가 도움을 요청합니다!'),
(67263, 1, 0, '검은부화 도마뱀군주가 연이은 물 분출 공격을 준비합니다!'),
(67266, 0, 0, '육로로 가라. 우리는 주위를 둘러보며 다른 입구를 찾겠다.'),
(67266, 1, 0, '음... 여기가 우리가 찾던 곳이다.'),
(67266, 2, 0, '대족장님께서 모구와 이... 생물들이 관련돼 있다는 걸 알아내셨다.'),
(67266, 3, 0, '트롤! 부둔지 뭔지 좀 알지? 뭔가 알아내 보지그래?'),
(67266, 4, 0, '과연! 육신을 빚어 전사를 만들어내는 힘. 바로 대족장님께서 원하시는 것이다!'),
(67266, 5, 0, '역시 반역자였군.'),
(67266, 6, 0, '대족장님께서는 적을 멸하신다!'),
(67266, 7, 0, '힘이여!'),
(67266, 8, 0, '네 충성은 여기에 있었더냐?'),
(67266, 9, 0, '... 죽어라!'),
(67266, 10, 0, '헬스크림 님의 호드는 절대적인 복종을 요한다...'),
(67266, 11, 0, '대족장님께서 네 배신에 대해 아실 것이다!'),
(67266, 12, 0, '헬스크림 님께서... 아실 것이다...'),
(67267, 0, 0, '싸움에 참여하고 싶으면 경비병에게 말하게, $c.'),
(67267, 1, 0, '싸우고 싶다고? 초대장이 필요하다네.$b$b그래도 관람은 마음대로 할 수 있지.'),
(67268, 0, 0, '불길에 몸을 맡겨라!'),
(67268, 1, 0, '여기가... 왜 이렇게 춥지...?'),
(67268, 2, 0, '탈출할 수는 없다...'),
(67269, 0, 0, '날아갈 준비나 해라! 키로오오오오크!'),
(67269, 1, 0, '키로... 크...'),
(67269, 2, 0, '하늘을 나는 기분이 어떠냐?'),
(67414, 0, 0, '다 온 것 같군. 빨리 해치우세.'),
(67414, 1, 0, '대족장님의 명령이라면...'),
(67414, 2, 0, '자네가 있어 안심이군. 가로쉬의 깡패들은 느낌이 안 좋아.'),
(67414, 3, 0, '자, 올라타 출발하세!'),
(67414, 4, 0, '정찰대가 이 동굴 안에 고대의 마법이 있다더군. 대족장이 확인하라고 했네.'),
(67414, 5, 0, '사우록이 동굴을 지키고 있네. 처치하세.'),
(67414, 6, 0, '함정으로 데려오게!'),
(67414, 7, 0, '이걸로 상처를 치유하게!'),
(67414, 8, 0, '잠깐, 뭔가 있네.'),
(67414, 9, 0, '도마뱀 괴물이군. 함께 싸우세, 형제여!'),
(67414, 10, 0, '이놈들과 싸워 본 적 있나?'),
(67414, 11, 0, '무기는 있어도 뇌는 없는 모양이야.'),
(67414, 12, 0, '한 명이 총을 맡게. 나머지는 걸어가지.'),
(67414, 13, 0, '움직이는 건 모조리 죽이게!'),
(67414, 14, 0, '여길세! 여기 배를 세우게.'),
(67414, 15, 0, '여기는 일종의 부화실인 것 같군...'),
(67414, 16, 0, '... 저 흉측한 놈이 어미고!'),
(67414, 17, 0, '조심하게! 동굴이 무너지네!'),
(67414, 18, 0, '대재앙의 부두술 안으로 뛰어드십시오!'),
(67414, 19, 0, '이 생물들... 어딘가 부자연스러워.'),
(67414, 20, 0, '"부둔지 뭔지"라.'),
(67414, 21, 0, '조사할 동안 날 지켜 주게...'),
(67414, 22, 0, '그 "모구"라는 놈들이 여기서 사악한 흑마법을 썼네.'),
(67414, 23, 0, '사우록은 태어난 게 아니라 창조되었네. 누군가 그 육신을 빚은 거야.'),
(67414, 24, 0, '이건 마법 중에서도 가장 악한 마법이야!'),
(67414, 25, 0, '가로쉬가 신의 흉내를 내서 괴물을 만든다고? 그런 건 호드가 아니야!'),
(67414, 26, 0, '도- 도와줘-'),
(67414, 27, 0, '대족장이... 자기 패를... 보였군.'),
(67414, 28, 0, '호드가 어쩌다 이 지경에 이른 건가? 같은 호드를 죽이다니. 막아야 하네.'),
(67414, 29, 0, '자네들이 필요하네.'),
(67414, 30, 0, '대족장에게 돌아가게. 내가 죽었다 전하고 곁에서 그를 감시하게.'),
(67414, 31, 0, '자네들과 내가, 때가 되면 움직여 놈을 없애버려야 하네.'),
(67414, 32, 0, '나 같은 이들이 또 있을 테니, 찾아 주게.'),
(67414, 33, 0, '나와 피로 맹세하세.'),
(67424, 0, 0, '적대적 대상과 접촉. 안전장치 해제.'),
(67424, 1, 0, '품질 보증 기간 만료. 행복하세요.'),
(67451, 0, 0, '빨리 죽어! 점심 약속이 있단 말이야!'),
(67451, 1, 0, '재미 없다.'),
(67487, 0, 0, '난 숨을게! 네가 놈들을 날려버려!'),
(67487, 1, 0, '다 이 녀석 때문이야...'),
(67487, 2, 0, '그만 꾸물거려, 맥스. 나한테 묻어가지 말고!'),
(67488, 0, 0, 'GG 기계공학단이 네 상판대기로 바닥을 닦아주마!'),
(67488, 1, 0, '보, 네 죽음의 광선이 광고했던 것과 달라!'),
(67488, 2, 0, '이번에 살아남으면 꼭 제대로된 파트너를 찾으라고 말해줘!'),
(67513, 0, 0, '안아 줘... 온기가 필요해...'),
(67524, 1, 0, '리... 리... 리도.'),
(67525, 0, 0, '우리가 함께 있을 때는 아무도 우릴 막지 못해!'),
(67525, 1, 0, '거의 이겼었는데...'),
(67569, 0, 0, '보급품을 한 번 가져다 준다고 해서 자네 일이 끝나는 건 아니네. 최선을 다해 물자가 풍족하게 유지될 수 있게 하게.'),
(67569, 1, 0, '땅에서 솟아나온 부러질 듯한 나무를 찾게. 아주 쓸 만한 목재니까!'),
(67569, 2, 0, '지금 우리에게 가장 필요한 건 음식과 나무네. 그 외에도 우릴 더 돕고 싶다면 내게 다시 말하게.'),
(67572, 0, 0, '불어... 순순히 모두 불라고!'),
(67572, 2, 0, '낱낱이 밝혀내고야 말겠다!'),
(67572, 3, 0, '고약한 비밀이로군!'),
(67573, 0, 0, '미트볼 배고파!'),
(67573, 1, 0, '미트볼 배아파!'),
(67573, 2, 0, '미트볼 먹고 싶은 거 먹는다!'),
(67573, 3, 0, '미트볼 기분이 이상해!'),
(67573, 4, 0, '미트볼 배꼽이 꼬록꼬록!'),
(67573, 5, 0, '미트볼 이제 구리구리한 거 먹는다!'),
(67579, 0, 0, '세상은 불타 버릴 것이다.'),
(67588, 0, 0, '내 검은 항상 날카롭지. 불타는 군단의 위협은 지금도 계속되고 있으니.'),
(67588, 1, 0, '내가 졌네. 가치 있는 싸움이었어. 고맙네, 친구여.'),
(67588, 2, 0, '혼자선 할 수가 없구나...'),
(67596, 0, 0, '네가 이길 가능성은 없다. 피올에게 넌 한낱 벌레일 뿐이다.'),
(67596, 1, 0, '눈앞이 온통 보랏빛이구나...'),
(67678, 0, 0, '무얼 두려워하느냐?'),
(67678, 1, 0, '드디어 제 영혼이 해방되었군요!'),
(67678, 3, 0, '암흑소환사가 잠시 약해졌습니다. 지금이 기회입니다!'),
(67678, 4, 0, '암흑소환사의 보호 마법이 다시 활성화되었습니다.'),
(67682, 0, 0, '그러게 말이야, 힐다. 모구가 샤 에너지를 이용한다? 영 마음에 안 드는 생각이군! 이 증거를 폐하께 가져가야겠어. $n 님, 오늘 도와주셔서 감사해요. 여기서부턴 저희가 맡죠!'),
(67686, 0, 0, '모구의 힘이 몸을 따라 흐릅니다! 룬을 추가로 획득하면 모구의 힘이 더 커집니다.'),
(67688, 0, 0, '이 밀림에서 곧 얼라이언스의 악취가 사라질 것이다!'),
(67748, 0, 0, '검은부화 마술사가 배를 정지장에 가뒀습니다! 마술사를 처치하여 주문을 해제하십시오.'),
(67761, 0, 0, '참을성의 시험이로다! 늑대가 전사로 처신할 것인가... 왕으로 처신할 것인가?'),
(67761, 1, 0, '전사의 무기는 검이나, 왕의 무기는 참을성이다.'),
(67761, 2, 0, '오늘은 승리를 거두었으나, 시험은 계속될 것이다...'),
(67782, 0, 0, '잠깐! 나도 깡패는 싫다고.'),
(67782, 1, 0, '이 배를 타고 들어가면 돼. 잠시 몇 군데 손만 좀 보고...'),
(67782, 2, 0, '자... 됐다! 사우록 척살 자주포야.'),
(67782, 3, 0, '악, 어떻게 좀 해 봐!'),
(67782, 4, 0, '자, 이거 받아! 무리를 상대하는 데 도움이 될 거라고.'),
(67782, 5, 0, '저기, 나는 그냥 여기 있을게. 날 잊지 마!'),
(67801, 0, 0, '포탄을 받아라!'),
(67801, 1, 0, '테라모어를 위해!'),
(67801, 2, 0, '네놈들은... 전부... 괴물이야...'),
(67833, 0, 0, '수은 수호자가 살아납니다!'),
(67833, 1, 0, '수은 수호자의 피부가 은 갑옷을 입은 듯 단단해집니다!'),
(67834, 0, 0, '제 생각이 맞다면, $n 님, 이... 천상의 종이야말로 가로쉬 님이 찾고 계신 그런 무기가 확실합니다. 우선은 당신을 필요로 하는 다른 곳으로 돌아가십시오. 이 정보는 제가 가로쉬 님께 직접 보고하겠습니다.'),
(67862, 0, 0, '이 석상의 주인공은 고대의 모구 황제인 것 같습니다.'),
(67863, 0, 0, '이 동굴에는 강력한 모구의 마법이 담겨 있었던 것 같습니다.'),
(67879, 0, 0, '잔베스는 함락되지 않는다!'),
(67883, 0, 0, '노움 건설 현장이 공격받고 있습니다!'),
(67930, 0, 0, '짐꾼 도착.'),
(67940, 0, 0, '시간이 얼마 없습니다, $n 님. 관리자 그랜틀리가 당신을 스톰윈드까지 모셔다 드릴 겁니다. 물론, 세상에 공짜는 없습니다.'),
(67990, 0, 0, '우리 병력이 상륙할 지점을 선택했소. 방어에 유리한 동쪽의 작은 반도지.'),
(67990, 1, 0, '그런데 잔달라 트롤이 이미 그곳에 요새를 구축했소.'),
(67990, 2, 0, '영혼의 방어막이 요새를 보호하오. 함선이 상륙하려면, 우선 그걸 없애야겠소.'),
(67990, 3, 0, '영웅이여, 지상 타격대를 이끌고 내부에서 그 방어막을 제거하시오!'),
(67990, 4, 0, '탈것을 타고 정찰대장 엘시아를 찾아가시오. 지금 정예 순찰대를 조직하고 있소. 태양의 빛이 그대를 비추기를.'),
(67990, 5, 0, '신도레이의 승리요! 호드가 또 한 번 이겼소!'),
(67990, 6, 0, '롬매스, 방어선을 구축하시오. 에이타스는 감시의 수호물을 설치하고, 케시엘은 보급품을 내려 놓으시오.'),
(67990, 7, 0, '호드의 형제 자매여! 적이 사방을 포위하고 있소! 앞으로 몇 주 간, 그대들의 용기가 승패를 결정지을 것이오.'),
(68006, 0, 0, '악몽에서 구해줘서 감사합니다. 주위의 모든걸 찢어버리고 싶었어요!'),
(68006, 0, 1, '제가 왜 그랬는지 모르겠군요. 정신을 차리게 해줘서 고맙습니다.'),
(68006, 0, 2, '구해주셔서 감사합니다. 왕자님께도 빚을 졌군요.'),
(68006, 0, 3, '분노를 억누르려 했지만 오히려 제가 굴복했습니다. 고맙습니다.'),
(68036, 0, 0, '수천 년 동안이나... 새 노리개가 없었는데... 아... 이 어찌나 기쁜 일인지.'),
(68036, 1, 0, '기꺼이... 공허의 품에... 들겠노라...'),
(68036, 2, 0, '이보단 재미있을 줄 알았거늘. 참으로 실망이다.'),
(68036, 3, 0, '이보단 재미있을 줄 알았거늘. 참으로 실망이다.'),
(68036, 4, 0, '방금 무슨 일이 있었는지 보았느냐?'),
(68036, 5, 0, '오... 너한텐 버거웠나 보군. 애석하구나.'),
(68036, 6, 0, '걸음 조심해야지... 으하하하하!'),
(68036, 7, 0, '안개 속의 수많은 비밀. 어딜 찾아봐야 할지 알겠느냐...?'),
(68036, 8, 0, '음... 내가 너를 지켜본다...'),
(68036, 9, 0, '파멸을... 맞이해라.'),
(68057, 0, 0, '드워프 건설 현장이 공격받고 있습니다!'),
(68065, 0, 0, '|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t메가이라가 |cFFF00000|Hspell:139458|h[광란]|h|r 상태에 빠집니다!'),
(68065, 1, 0, '메가이라의 분노가 가라앉습니다.'),
(68078, 0, 0, '어서 공격해, 만추! 자비를 베풀지 마!'),
(68078, 1, 0, '흥, 단순무식한 놈. 큰 손실은 아니야.'),
(68078, 2, 0, '집중해라, 웨이셩. 진정한 고통을 보여줘!'),
(68078, 3, 0, '녀석은 명예롭게 싸웠다. 그게 처음이자 마지막 실수지.'),
(68078, 4, 0, '진정한 힘과 대면하라!'),
(68078, 5, 0, '이럴수가?!'),
(68078, 6, 0, '쿠엣잘! 적들에게 폭풍을 내려다오!'),
(68078, 7, 0, '댐렌! 놈들을 바짝 얼려라!'),
(68078, 8, 0, '칫! 쓸모 없는 잡종들! 내 직접 죽여주마!'),
(68078, 9, 0, '훈련이.. 부족했나...'),
(68088, 0, 0, '여기다! 배를 멈춰라.'),
(68088, 1, 0, '이 섬은 요새를 건설하기에 최적의 환경이군. 로클라! 일꾼들이 도착하면 나무를 다 베어버리고 항구를 건설해라.'),
(68088, 2, 0, '용사, 넌 한동안 여기 있었으니, 이 땅에 대해 잘 알겠지. 따라와라.'),
(68096, 0, 0, '이 사원은 잿빛혓바닥 결사단의 영토다. 떠나줘야겠어, 지금 당장.'),
(68096, 1, 0, '무엇을 보았는가, 형제여?'),
(68106, 0, 0, '$p 님, 우리는 크라사랑으로 돌아가서 이 문제를 의논해봐야 해요. 지금 일은 도와주셔서 감사해요. 원하실 때 언제라도 사자의 상륙지로 돌아갈 수 있는 차원문이 있어요.'),
(68137, 0, 0, '어리석은 흑마법사들 같으니. 네놈들이 다시 우리 사원에 침입할 줄 알고 있었다...!'),
(68137, 1, 0, '잠깐... 자네는 전에 이곳에 몰래 들어왔던 그 흑마법사들 중 하나가 아니군. 그렇다면 여긴 왜 온 건가?'),
(68137, 2, 0, '그 흑마법사 두 명이 사원에 침입한 지도 벌써 여러 달이 지났네... 하지만 아직도 그들이 무엇을 찾고 있었는지 모르겠어.'),
(68137, 3, 0, '나를 따라오게. 그들은 길 잃은 영혼의 제단과 사원 정상을 찾아갔었네.'),
(68137, 4, 0, '나는 일단 이 흑마법사를 믿기로 했다. 사원을 자유롭게 돌아다닐 수 있게 해 줘라.'),
(68137, 5, 0, '마그테리돈과 일리단, 타락한 오크가 이 신성한 장소에 저지른 만행에서 회복하려면 아직도 오랜 시간이 필요하네.'),
(68137, 6, 0, '이 안에 길 잃은 영혼의 제단이 있네. 쓰러진 내 형제 수천의 영혼이 이곳에 남아 있지.'),
(68137, 7, 0, '주의하게. 이 안에는 아직도 수많은 함정이 작동하고 있네. 앞으로 나아가기 전에, 자네가 지닌 악마의 주문 중 하나를 사용해서 이 앞을 정찰해 보는 게 좋겠어.'),
(68137, 8, 0, '$n! 내 부하들이 지하실에 갇혔네. 시간이 없어. 나와 함께 그들을 구출하세!'),
(68151, 0, 0, '이곳의 힘은 너 따위의 것이 아니다, 흑마법사!'),
(68151, 1, 0, '죽어라!'),
(68151, 2, 0, '네가 그렇게 악마를 좋아한다면... 마음껏 갖게 해 주마!'),
(68287, 0, 0, '가로쉬, 잠깐만. 다른 방법이 있을 것이오. 피를 흘릴 필요는 없소.'),
(68287, 1, 0, '무력을 쓸 게 아니라 설득을 하면 좋겠소. 여기 판다렌의 기억주가 한 통 있소. 이걸 사용하면 우리가 샨 키엔의 과거를 볼 수 있을 것이오.'),
(68305, 0, 0, '나는 부수고, 너는 죽는다. 받아들여라!'),
(68305, 1, 0, '아... 어깨가... 너무 무거워...'),
(68305, 2, 0, '내 행운의 상징을 망가뜨리다니! 널 부숴버리겠다!'),
(68305, 3, 0, '고블린은 딱히 행운을 가져오지 않더구나!'),
(68323, 0, 0, '투기장에 들어서는 건... 1계급 $r $c인 $n입니다! $n|1은;는; 여기 새로 온 친구니까, 살살 해봐요!'),
(68323, 1, 0, '요새 한창 잘나가는 2계급 $c, $n|1이;가; 싸움장에 들어섭니다!'),
(68323, 2, 0, '$n에게 박수를 부탁드립니다! $n|1은;는; 3계급 $c입니다.'),
(68323, 3, 0, '도전자가 나타났습니다. 4계급 $r $c, $n|1을;를; 환영해 주십시오!'),
(68323, 4, 0, '지금 싸움장에 주먹이 매콤한 $c|1이;가; 등장했습니다. 5계급 싸움꾼, $n에게 인사하세요!'),
(68323, 5, 0, '조심하십시오... 무시무시한 6계급 $r, $n|1이;가; 등장합니다!'),
(68323, 6, 0, '지금 싸움장에 들어서는 건... 돌아온 최고의 싸움꾼, 7계급 $c $n입니다!'),
(68323, 7, 0, '드디어! 다들 아시죠? 다들 사랑하시죠? 8계급 싸움꾼, $N에게 박수를 부탁드립니다!'),
(68323, 8, 0, '싸움굴의 9계급 베테랑 싸움꾼, $n|1을;를; 소개합니다!'),
(68323, 9, 0, '이어서 어딘가에서 발견된 악어 브루스가 투기장에 등장합니다!'),
(68323, 10, 0, '이에 맞설 상대는... 천둥왕의 추종자, 일촉즉발의 비안입니다!'),
(68323, 24, 0, '모두들 춤 출 준비를 하세요! 디켄이 나타났습니다!'),
(68323, 25, 0, '다음 상대는 밀리 와트입니다! 기계공학부에 다니던 시절에 제가 잠깐 사귀었던 아가씨죠!'),
(68323, 26, 0, '이번 상대는... 모두의 사랑을 한몸에 받는... 키가 3.5미터에 이르는 마법 시체! 피올입니다! 음... 발음이 이게 맞나요?'),
(68323, 27, 0, '아 이런... 미안합니다. 상대가 프로보스쿠스네요!'),
(68323, 28, 0, '상대는 놈리건 최고의 용사들입니다... 지금은 그다지 돋보이지 않지만요. 오염된 노움 5인조!'),
(68323, 29, 0, '아킨둔에서 이 친구가 까악까악 울면서 폭풍을 일으키는 걸 발견했습니다. 이칸 이주에게 박수를 보내주세요!'),
(68323, 30, 0, '노장 분들은 이 친구를 기억하실지도 모르겠네요. 뒤틀린 친구이긴 하지만, 오늘만은 상대를 뒤틀어 버릴 겁니다! 아카마를 소개합니다!'),
(68323, 31, 0, '썬더 블러프에서 온 끔찍한 타우렌도 환영해 주세요! 스매시 후프스톰프입니다! 저 커다란 어깨보호구 좀 보세요!'),
(68323, 32, 0, '다들 조용히 하세요... 저 친구를 화나게 하면 안 됩니다. 조용히 감상하십시오. 살인기린 운구록스입니다!'),
(68323, 33, 0, '참 잘 어울리지 않는 한 쌍입니다. 구역질이 나려고 하네요. GG 기계공학단이 나타났습니다!'),
(68323, 34, 0, '상대는... 암흑소환사입니다. 우와, 진짜 이름도 따로 없군요. 으스스합니다!'),
(68323, 35, 0, '이어서, 배틀트론이 투기장에 나타났습니다! 이 고철 덩어리가 상대를 폭발시켜 버릴 겁니다!'),
(68323, 36, 0, '그리고... 미트볼입니다.'),
(68323, 37, 0, '승자는 $n입니다!'),
(68323, 37, 1, '이런 이런 이런... $n|1이;가; 이겼네요! 저도 돈을 좀 잃은 것 같아요.'),
(68323, 37, 2, '축하합니다, $n! 거기 투기장 밖에 피투성이 발자국은 남기지 마세요.'),
(68323, 37, 3, '끝났습니다! $n|1이;가; 가까스로 살아남았습니다. 정말 아슬아슬했네요, $n!'),
(68323, 38, 0, '아이코... 안됐네요, $n 님. 다시 도전해 보세요. 줄은 다시 서야 해요.'),
(68323, 38, 1, '우엑... 정말 처참하네요. 누가 사제나 뭐 그런 친구 하나 불러 줄래요?!'),
(68323, 38, 2, '그거 참... 안 좋게 끝났네요.'),
(68323, 38, 3, '$n, $n, 우리 $n... 다음 번에는 이렇게 자주 죽지 마세요.'),
(68323, 39, 0, '이게 누구야? 브루스가 돌아왔습니다! 더 힘세고 강해져서 돌아온 브루스! 기계브루스입니다! 만세!!'),
(68323, 40, 0, '복덩이의 먼지를 터십시오. 이번엔 복이 필요할테니까요. 이번 상대는 할아범 투덜피리입니다!'),
(68323, 41, 0, '우리가 한물 간 로봇들로 뭘 하냐고요? 당연히 유혈이 난무하는 검투사 투기장으로 보내 죽을 때까지 싸우게 하죠! 여러분, 블링트론 3000입니다!'),
(68323, 42, 0, '이제 투기장에 들어서는 건, 폭탄 상자를 든 호젠입니다! 다이너마이트를 투척하는 원숭이 수도사, 사부 뻥 뻥을 소개합니다!'),
(68336, 0, 0, '코르크론 위장복을 사용한 후, 가로쉬아르 진군지 중앙에서 정보를 찾아야 합니다.'),
(68336, 1, 0, '난 참을성이 별로 없다, 샨 키엔. 천상의 종이 어디 있는지 당장 말해!'),
(68336, 2, 0, '이시, 칼을 뽑아라. 손발을 좀 잃고 나면 놈도 마음이 바뀔 것이다.'),
(68336, 3, 0, '그럼 말해 봐라!'),
(68339, 0, 0, '죽이고 싶거든 죽여라. 내겐 너희 호드를 도울 이유가 없다. 난 오로지 천둥왕에게만 복종한다.'),
(68375, 0, 0, '뭐라고?! 모구가 천상의 종을 어디에 숨겼는지 봤다고? 난 지금 당장 사자의 상륙지에 이 소식을 전하겠네. 가로쉬보다 먼저 그 종을 찾아내야 하네! 그걸 발견하면 즉시 자네에게 연락하겠네!'),
(68397, 0, 0, '너! 네놈들이 내 분노를 샀다. 너희를 본보기로 삼아, 내 힘을 겁내는 자들이 전율하며 복종하게 만들어 주마.'),
(68397, 1, 0, '나는 레이 션, 왕과 신을 살해한 자다. 너희는 지금 크게 실수하는 거다.'),
(68397, 2, 0, '복종하라!'),
(68397, 3, 0, '내 성소에서 내게 도전하려는 거냐? 어리석기 짝이 없구나!'),
(68397, 4, 0, '하! 내가 직접 널 부숴주마. 번개를 어떻게 상대하는지 보자.'),
(68397, 5, 0, '번개여, 내 적을 쫓아라!'),
(68397, 6, 0, '너희 미물들아! 나는 창공의 힘을 부린다!'),
(68397, 7, 0, '안 돼! 넌 가치 없는 존재다! 나... 나는... 천둥왕이다!'),
(68397, 8, 0, '나는 그저... 신들의 일을 마무리하려 했는...'),
(68397, 9, 0, '|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t%s|1이;가; |cFFFF0000|Hspell:135096|h[천둥충격]|h|r을 시전합니다! 떨어지십시오!'),
(68397, 10, 0, '%s|1이;가; |cFFFF0000도관 초자력 충전|r을 끝내기 직전입니다!'),
(68397, 11, 0, '|TInterface\\Icons\\ability_thunderking_lightningwhip.blp:20|t%s|1이;가; |cFFFF0000|Hspell:136850|h[번개 채찍]|h|r을 시전합니다!'),
(68397, 12, 0, '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000북서쪽|r 문이 열리면서 |cFFFF0000|Hspell:136889|h[맹렬한 강풍]|h|r이 몰아칩니다!'),
(68397, 13, 0, '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000북동쪽|r 문이 열리면서 |cFFFF0000|Hspell:136889|h[맹렬한 강풍]|h|r이 몰아칩니다!'),
(68397, 14, 0, '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000남동쪽|r 문이 열리면서 |cFFFF0000|Hspell:136889|h[맹렬한 강풍]|h|r이 몰아칩니다!'),
(68397, 15, 0, '|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000남서쪽|r 문이 열리면서 |cFFFF0000|Hspell:136889|h[맹렬한 강풍]|h|r이 몰아칩니다!'),
(68398, 0, 0, '|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135680|h[북쪽 도관]|h|r이 소진되어 |cFFFF0000|Hspell:137176|h[과부화된 회로]|h|r 효과가 발생했습니다!'),
(68403, 0, 0, '좋아, $n!'),
(68403, 0, 1, '축하하네!'),
(68403, 0, 3, '그래야 $n답지!'),
(68406, 0, 0, '좋아, $n!'),
(68406, 0, 1, '축하하네!'),
(68406, 0, 3, '그래야 $n답지!'),
(68408, 0, 0, '싸움에 참여하고 싶으면 경비병에게 말하게, $c.'),
(68408, 1, 0, '싸우고 싶다고? 더 강해지면 다시 찾아오게.$b$b그래도 관람은 언제든 할 수 있지.'),
(68417, 0, 0, '쉬잇! 이봐, 여길세. 나야. 코넬리 요원이라고! 위장한 거 들키지 않게 조심하게!'),
(68417, 1, 0, '그래, 가로쉬가 천상의 종이라는 물건을 찾고 있단 말이지? 그게 뭔진 몰라도, 좋은 물건은 아닐 테지. 본부에 이 소식을 전하겠네.'),
(68417, 2, 0, '훌륭하게 해냈군! 내 곧 다시 연락하지.'),
(68474, 0, 0, '얼라이언스 개들아! 이빨은 어딨느냐?!'),
(68474, 1, 0, '전군, 진격하라!'),
(68474, 2, 0, '대족장님을 위해!'),
(68474, 3, 0, '너희 얼라이언스는 약해 빠졌어!'),
(68474, 4, 0, '이걸로 끝이다!'),
(68474, 5, 0, '사령관 스카가쉬가 맹렬한 분노에 사로잡혔습니다! 스카가쉬의 근접 공격을 피하십시오!'),
(68474, 6, 0, '네놈들의 솜씨가 이것 뿐인가?'),
(68514, 0, 0, '우리 조사단이로군. 상륙한다.'),
(68514, 1, 0, '상황은?'),
(68514, 2, 0, '호드는?'),
(68514, 3, 0, '흠... 트로트먼이 일을 당했을지도 모른다. 갈라지지.'),
(68514, 4, 0, '린나, 여기 있으면서 야영지를 건설해라. 의무 막사와 숙소가 최우선이다. 인부들이 도착하면 부두 건설을 시작해라.'),
(68514, 5, 0, '혼스웨글, 조사단에 알려라. 함대가 오는 대로 채석과 채광을 시작하도록.'),
(68514, 6, 0, '용사여, 그대는 이 땅을 누구보다도 잘 안다. 나와 함께 가서 트로트먼을 찾자.'),
(68531, 0, 0, '그래, 내게 얼라이언스의 최전선에 다시 뛰어들라는 말이군... 어디라고? 판다리아...? 응?'),
(68531, 1, 0, '좋아, 가겠네. 하지만 호드 세력에 침투하는 건 이번이 마지막이야! 정말이라고.'),
(68531, 2, 0, '가서 보급품을 조금 확보하고 옛 친구들에게 연락을 하겠네. 판다리아에서 지원이 필요하면 자네를 찾지.'),
(68537, 0, 0, '이제 진짜 파티를 시작할 수 있겠습니다!'),
(68551, 0, 0, '빛이... 빛이 보인다... 드디어, 수백 년 동안의 침묵 끝에 누군가 왔구나.'),
(68551, 1, 0, '분부하신대로 종을 지켜냈습니다, 나의 군주시여.'),
(68551, 2, 0, '잠깐... 너희는 모구가 아니잖아! 침입자다!'),
(68551, 3, 0, '수호자들이여, 일어나라! 천둥왕의 보물을 훔치려는 자들에게 죽음을 선사하라!'),
(68586, 0, 0, '에이타스! 이쪽이오! 차원문으로!'),
(68586, 1, 0, '차원문으로 들어가십시오!'),
(68589, 0, 0, '제이나가 미쳐버렸소. 그녀는 선리버를 가두고 저항하는 자들을 공격하고 있소. 더 큰 문제는 은빛 서약단도 이 틈을 타 살육에 동참하고 있다는 거요.'),
(68590, 0, 0, '온통 혼란 속이오. 최대한 많은 이들을 구출하고 빠르게 움직여야 하오.'),
(68593, 0, 0, '내 명령을 기다리시오...'),
(68593, 1, 0, '지금이오! 서두르시오! 도시 중앙으로! 이쪽이오!'),
(68599, 1, 0, '나이트 엘프 건설 현장이 공격받고 있습니다!'),
(68631, 0, 0, '에이타스가 없군... 놈들이 옮겼나보오. 일단 그 없이 가야겠소.'),
(68634, 0, 0, '꼭 붙으시오! 터널 밖으로 나갈 거요!'),
(68634, 1, 0, '바짝 붙으시오!'),
(68692, 0, 0, '네가 간섭할 일이 아니야!'),
(68692, 0, 1, '이게 무슨 짓이냐?'),
(68692, 0, 2, '간섭하는 자는 용서치 않을 것이다!'),
(68692, 0, 3, '닥쳐라!'),
(68692, 0, 4, '멈춰라!'),
(68692, 0, 5, '네 주제를 모르는 건가?'),
(68692, 0, 6, '선리버는 쓰레기다!'),
(68695, 0, 0, '이제 실버문으로 다시 돌아갈 수 있을 것 같습니다...'),
(68695, 0, 1, '이건 말도 안 됩니다. 에이타스 님께 말씀드려야겠군요!'),
(68695, 0, 2, '알려줘서 고맙습니다. 몸조심하십시오.'),
(68695, 0, 3, '정말 키린 토가 우리를 이렇게 쫓아내려는 겁니까?'),
(68695, 0, 4, '퇴역하며 치워둔 칼을 다시 꺼낼 때가 된 것 같군요...'),
(68696, 0, 0, '|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135681|h[동쪽 도관]|h|r이 소진되어 |cFFFF0000|Hspell:137176|h[과부하된 회로]|h|r 효과가 발생했습니다!'),
(68697, 0, 0, '|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135682|h[남쪽 도관]|h|r이 소진되어 |cFFFF0000|Hspell:137176|h[과부하된 회로]|h|r 효과가 발생했습니다!'),
(68698, 0, 0, '|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135683|h[서쪽 도관]|h|r이 소진되어 |cFFFF0000|Hspell:137176|h[과부하된 회로]|h|r 효과가 발생했습니다!'),
(68714, 0, 0, '달라란이여, 안녕히...'),
(68715, 0, 0, '고맙소, $n. 실버문에서 만나세나...'),
(68716, 0, 0, '호드에 마법학자 자리가 또 있으면 좋겠군...'),
(68718, 0, 0, '좋지 않은 느낌이 들어.'),
(68718, 1, 0, '너의 대족장이 그 종 가져갔어. 그걸로 호드를 강하게 만들겠대.'),
(68718, 2, 0, '그런데 난 그 종이 너무 강력하다고 생각해... 그리고 뭔가 기분 나빠.'),
(68718, 3, 0, '아무도, 호젠이든 인간이든 오크든... 샤를 사용하면 안 돼.'),
(68718, 4, 0, '조심해.'),
(68718, 5, 0, '무사히 살아서 다시 만나, 친구.'),
(68815, 0, 0, '누가 감히 코룬을 방해하느냐? 이 오만함에 대한 대가를 치러라!'),
(68831, 0, 0, '우리가 정말 중요한 일을 맡은 거야, $p.'),
(68831, 1, 0, '섬 전체에 있는 음파 제어탑들이 잔베스 중심부를 보호하고 있어. 저걸 파괴하지 못하면 무기고로 가기 어려울거라고.'),
(68831, 2, 0, '이 보호막을 깨뜨리지 못하면 우리는 압도당할 거야.'),
(68831, 3, 0, '호박석 폭탄을 조준해. 하나만 제대로 맞춰도 큰 폭발이 일어날 거야!'),
(68831, 4, 0, '잘 쐈어, $p! 계속 폭탄들을 노리라고.'),
(68831, 5, 0, '작전 개시! 탑들을 파괴하라고!'),
(68831, 6, 0, '저 사마귀들이 탑을 지키고 있군, $p. 저들을 처리하지 못하면 탑에는 흠집도 못 낼 걸세.'),
(68831, 7, 0, '거의 다 파괴했어. 조만간 보호막이 사라질 거야!'),
(68831, 8, 0, '저 전갈들이 탑을 움직이고 있네! 처치하게!'),
(68831, 9, 0, '보호막이 사라졌군! 잘했어, $p! 내가 교두보로 데려다 주지.'),
(69017, 0, 0, '너무 추워, 너무 어두워...'),
(69017, 1, 0, '우린 잊혀지지 않을 거야, 그럼, 그럼...'),
(69017, 2, 0, '우리는 완벽해, 그래, 그래. 실패작이 아니야. 아니야, 실패작이 아니야...'),
(69017, 3, 0, '너의 육신, 그래, 그래! 너무 완벽해, 우리에게 줘...'),
(69017, 4, 0, '안 돼, 안 돼, 안 돼! 또 고통이!'),
(69017, 5, 0, '또다시... 우린 짓밟혔다... 또다시.. 차가운 어둠 속으로...'),
(69017, 6, 0, '프리모디우스가 |cFFFF0000|Hspell:136209|h[진화]|h|r하고 |cFFFF0000|Hspell:136210|h[비늘막 주머니]|h|r 능력을 습득합니다!'),
(69017, 7, 0, '프리모디우스가 |cFFFF0000|Hspell:136209|h[진화]|h|r하고 |cFFFF0000|Hspell:136215|h[가스 주머니]|h|r 능력을 습득합니다!'),
(69017, 8, 0, '프리모디우스가 |cFFFF0000|Hspell:136209|h[진화]|h|r하고 |cFFFF0000|Hspell:136218|h[산성 가시]|h|r 능력을 습득합니다!'),
(69017, 9, 0, '프리모디우스가 |cFFFF0000|Hspell:136209|h[진화]|h|r하고 |cFFFF0000|Hspell:136225|h[병원체 분비샘]|h|r 능력을 습득합니다!'),
(69017, 10, 0, '프리모디우스가 |cFFFF0000|Hspell:136209|h[진화]|h|r하고 |cFFFF0000|Hspell:136245|h[신진대사 촉진]|h|r 능력을 습득합니다!'),
(69017, 11, 0, '프리모디우스가 |cFFFF0000|Hspell:136209|h[진화]|h|r하고 |cFFFF0000|Hspell:136246|h[분출하는 고름]|h|r 능력을 습득합니다!'),
(69026, 0, 0, '너희 셋이 내 눈이고 귀다. 흩어져서 방어를 준비해라!'),
(69026, 1, 0, '가능한 한 모든 걸 활용해라! 적을 궁지에 몰아!'),
(69026, 2, 0, '참으시오, 티란데.'),
(69026, 3, 0, '준비가 거의 끝났다. 계속해라!'),
(69026, 4, 0, '방어를 준비해라. 언젠가 나올 수밖에 없을 것이다.'),
(69026, 5, 0, '이곳은 우리 땅이다. 한 치도 내주지 마라.'),
(69026, 6, 0, '참으시오, 티란데. 우리가 이기겠지만, 무방비하게 들어가선 안 되오.'),
(69026, 7, 0, '성급하게 뛰어들지 마라. 놈들이 실수하게 만들어라.'),
(69026, 8, 0, '얼라이언스의 생명을 내버릴 순 없소. 압승이 아니면 취하지 않을 거요.'),
(69026, 9, 0, '놈들이 온다. 방어선 뒤로 물러나라!'),
(69026, 10, 0, '나와라, 겁쟁이! 보여줄 테니!'),
(69026, 11, 0, '우리 군대는 여기 없다. 영웅 몇 명만 쓰러뜨리면 스톰윈드 왕을 노릴 수 있다. 두려운가?'),
(69026, 12, 0, '승리했다! 게다가 신성한 땅에 피를 흘리지도 않았다.'),
(69026, 13, 0, '예전의 나라면 그랬을 거요. 하지만 그 동안 많은 걸 배웠지. 가로쉬에게 한두 번 당한 게 아니니.'),
(69026, 14, 0, '지금부터는 우리가 이 전쟁을 주도하오.'),
(69026, 15, 0, '티란데, 나는 정치는 못할지 몰라도 싸움은 잘하오. 우린 이 전쟁에서 이길 수 있소.'),
(69026, 16, 0, '단결해야 하오. 나를 믿어 주시오. 내가 옳은 선택을 할 거라고 말이오. 우리가 하나가 되면 절대 실패하지 않소.'),
(69078, 0, 0, '모래가 모든 것을 집어삼키리라!'),
(69078, 1, 0, '전부 묻어버리겠다!'),
(69078, 2, 0, '폭풍이 다가온다!'),
(69078, 3, 0, '발 밑을 조심하라고!'),
(69078, 4, 0, '사막은 끝이 없다.'),
(69078, 4, 1, '모두가 쓰러지리라!'),
(69078, 5, 0, '나는... 다시... 모래로... 돌아간다...'),
(69099, 0, 0, '한기어린 바람이 느껴지느냐? 곧 폭풍이 몰아칠 것이다...'),
(69099, 1, 0, '나는 그저... 암흑 속... 폭풍의 전조일 뿐...'),
(69099, 2, 0, '천둥으로 태어났노라!'),
(69099, 3, 0, '하늘이 네 죽음을 애도하는구나!'),
(69099, 4, 0, '원한에 찬 요동치는 구름이여!'),
(69099, 5, 0, '분노에 찬 울부짖는 바람이여!'),
(69099, 6, 0, '폭풍의 정수가 창에서 뿜어져 나와 당신을 주시합니다!'),
(69131, 0, 0, '내가 상대해주마, 이 바보들아!'),
(69131, 1, 0, '겨울이 온다...'),
(69131, 2, 0, '한기가 느껴지나?'),
(69131, 2, 1, '얼어라!'),
(69131, 3, 0, '죽음의 차가운 품에 안겨라.'),
(69131, 3, 1, '드라카리의 힘을 봐라!'),
(69131, 4, 0, '제국은... 결코... 무너지지... 않아...'),
(69134, 0, 0, '이건 좀 아플거야!'),
(69134, 1, 0, '레이 션이여, 우리에게 힘을!'),
(69134, 2, 0, '짜릿할거야!'),
(69134, 3, 0, '받아라!'),
(69134, 3, 1, '썩 꺼져라!'),
(69134, 4, 0, '감히 잔달라에게 대적하다니!'),
(69134, 4, 1, '무릎 꿇어!'),
(69134, 5, 0, '천둥왕께서... 약속하셨는데...'),
(69135, 1, 0, '레이 션이시여. 잔달라 부족의 힘을 보여드리겠습니다. 놈들을 이 자리에서 처치하겠습니다!'),
(69135, 2, 0, '실망시키지 않겠습니다!'),
(69201, 0, 0, '내 명령을 따르는 이 함선을 모두가 두려워할 것이다! 맞지, 리피?'),
(69250, 0, 0, '절개를 하고 나면 피가 빠르게 흐를 것이다.'),
(69272, 0, 0, '이 배는 새로운 선장이 다스린다! 제대로 일을 하지 않는 놈은 영혼을 끄집어내어 골렘에게 먹이로 주겠다.'),
(69374, 0, 0, '잘 왔다, 벌레들아. 잔달라 제국이 여기서 부활한다!'),
(69374, 1, 0, '많은 부족이 결집했다. 너희는 한 부족이 아니라, 트롤 제국 전체를 상대해야 한다! 줄의 손아귀가 다시 아제로스를 뒤덮고, 너희 열등한 종족은 고통이 뭔지 알게 될 거다!'),
(69374, 2, 0, '이제, 야수훈련소의 진짜 힘을 보여주마. 다칼라 디추카 호리돈! 칼리마스테!'),
(69374, 3, 0, '하하하! 이제 내 차례다! 전쟁신의 진짜 힘을 보여 주마!'),
(69374, 4, 0, '드라카리, 얼어붙은 북부의 힘을 보여줘라!'),
(69374, 5, 0, '구루바시, 밀림의 독으로 적을 시체로 만들어 강에 띄워 보내라.'),
(69374, 6, 0, '파락키, 모래의 분노로 적의 껍질을 벗겨라!'),
(69374, 7, 0, '아마니, 줄진의 이름으로, 죽은 전쟁 군주들의 복수를 하자!'),
(69374, 8, 0, '너희 두개골은 내 엄니에 예쁘게 장식해 주마.'),
(69374, 9, 0, '다칼라 코라스테... 호리돈... 죽여라...'),
(69427, 0, 0, '주문 시전을 멈추십시오! %s|1이;가; |cFFFF0000|Hspell:138763|h[방해의 충격]|h|r을 시전합니다!'),
(69427, 1, 0, '%s|1이;가; |cFFFF0000|Hspell:138644|h[령 착취]|h|r를 시전하여 다른 골렘에게서 힘을 흡수합니다!'),
(69465, 0, 0, '천둥왕이 내게 힘을 주셨다! 봐라!'),
(69465, 1, 0, '널 부숴 주마.'),
(69465, 2, 0, '쾅!'),
(69465, 3, 0, '뼈를 부숴, 부숴!'),
(69465, 4, 0, '폭풍을 부른다!'),
(69465, 5, 0, '펑!'),
(69465, 9, 0, '약해.'),
(69465, 9, 1, '너무 쉽게 부숴지네.'),
(69465, 10, 0, '너무 쉽게 부숴지네.'),
(69465, 11, 0, '날 이기다니..'),
(69473, 0, 0, '어둠 속에서 난 수천 년을 기다렸다. 고통받는 자들의 비명만이 적막을 깨뜨리는... 깰 수 없는 악몽 속에서.'),
(69473, 1, 0, '눈에 순진한 희망이 어려 있구나. 고작 너희가 내 구원자라고? 가슴 속의 건방진 동정 따위는 버리고 내면의 소리를 들어라. 너희도 곧 내 고통을 알게 될 지니.'),
(69473, 2, 0, '이 뒤틀린 세상은 구제할 수 없다. 착각에 빠진 영웅들이 손을 쓰기엔 너무 늦었지. 타락의 해법은 파괴 뿐이니, 여기서 시작되리라... 바로 지금.'),
(69473, 3, 0, '너희를 처리하고 나면... 이 세상이 정화되기 전엔 멈추지 않겠다. 이제 소멸해라!'),
(69473, 4, 0, '창조와... 파괴의 손길.'),
(69473, 5, 0, '아직도 승리할 수 있을 것 같나? 하하하, 어리석군!'),
(69473, 6, 0, '내 힘의 맛보기일 뿐이다.'),
(69473, 7, 0, '잠깐! 난... 난 적이 아니다. 너희는 예전의 그보다도 강하구나. 어쩌면 너희가 옳을지도 모른다, 정말 희망이 있을지도.'),
(69473, 8, 0, '하지만 필멸자여, 지금 모든 것을 삼키는 어둠의 균열이 너희 발 밑에서 아귀를 벌리기 시작했다. 너희가 파멸의 순리를 거스를 순 없을 것이다.'),
(69473, 9, 0, '아, 폭풍이 날 감싸는구나...'),
(69473, 10, 0, '네 생명이 널 배신할 것이다.'),
(69475, 0, 0, '적이다! 형제여, 무기를 들어라! 놈들을 몰아내!'),
(69475, 1, 0, '잔달라의 진짜 힘은 아직이다!'),
(69475, 2, 0, '폐허를 지켜라. 적을 베어 버려!'),
(69475, 3, 0, '침입자를 박살내라. 방어막을 지켜야 한다.'),
(69475, 4, 0, '날 상대해라! 내 의지는 강철이요, 우리는 무적이다!'),
(69475, 5, 0, '잔달라가...'),
(69476, 0, 0, '%s|1이;가; 침묵의 찬가를 시전하기 시작합니다! 방벽 안으로 들어가십시오!'),
(69481, 0, 0, '엘시아가 기다리고 있소.'),
(69481, 2, 0, '놀라운 성과군. 음영파가 훌륭한 동맹이 될 줄 알았소.'),
(69481, 3, 0, '어쨌든, 우린 천둥왕에게 큰 피해를 줬소. 호드의 금속 장인들이 모구의 제작 기술을 연구할 것이오.'),
(69481, 4, 0, '때가 되면 그럴 거요, 친구. 때가 된다면.'),
(69482, 0, 0, '음- 뭐지? 밀항자다!'),
(69482, 1, 0, '아하, 간지럽군. 이제 장난은 끝이다.'),
(69482, 2, 0, '|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t %s|1이;가; 끔찍한 |cFFFF0000|Hspell:140432|h[숙취]|h|r에서 깨어납니다!'),
(69482, 3, 0, '넌... 살아서 나갈 수... 없다.'),
(69483, 0, 0, '천둥왕의 뜻을 받들어, 명을 이행하겠습니다.'),
(69483, 1, 0, '모습을 드러내라, 꼬맹이들아!'),
(69483, 2, 0, '도망갈 곳은 없다. 빠져 나가고 싶다면 나를 상대해라!'),
(69483, 3, 0, '|TInterface\\Icons\\spell_shadow_destructivesoul.blp:20|t%s|1이;가; |cFFFF0000|Hspell:140543|h[강화된 도끼]|h|r를 시전합니다! 도망치십시오!'),
(69483, 4, 0, '너흰 모두 끝장이야!'),
(69483, 5, 0, '|TInterface\\Icons\\warrior_talent_icon_bloodandthunder.blp:20|t%s|1이;가; |cFFFF0000|Hspell:140531|h[멈추기]|h|r를 시전하기 시작합니다! 풀려나려면 |cFFFF0000족쇄|r를 파괴하십시오!'),
(69483, 6, 0, '침입자들은 처형당할지어다!'),
(69483, 7, 0, '나를 해하는 것은 곧 폐하를 해하는 것이다! 그분께선 이런 모욕을 용납하지 않으리라!'),
(69483, 8, 0, '|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t레이 션이 격노해 |cFFFF0000|Hspell:140549|h[번개 폭풍]|h|r을 불러냅니다!'),
(69483, 9, 0, '아무도... 지나가지...'),
(69501, 0, 0, '네놈이야말로 내 앞에 무릎꿇고 자비를 구걸할 것이다.'),
(69501, 1, 0, '저 입상들이 초대 황제의 힘을 지니고 있네. 파괴하게!'),
(69501, 2, 0, '타오스, 문을 열게.'),
(69501, 3, 0, '용사여, 함께 가세. 전우들이 후방을 지키는 동안 앞으로 나아가야 하네.'),
(69501, 4, 0, '샨 부! 또 신을 만들려 하는구나. 언제 정신을 차리겠느냐?'),
(69501, 5, 0, '잔달라 트롤 지원군이 오고 있네.'),
(69501, 6, 0, '야리아, 치유를 부탁하네! 타오스, 후방을 맡게!'),
(69501, 7, 0, '덤벼라, 샨 부! 천둥왕의 궁정은 겁쟁이 소굴이었더냐?'),
(69501, 8, 0, '샨 부의 공격을 피하게. 우리가 더 빠르고 더 영리하네!'),
(69501, 9, 0, '으아악. 놈을 죽여. 빨리!'),
(69501, 10, 0, '알겠는가? 세상의 어떤 힘으로도 순수한 영혼을 짓밟을 수는 없다네.'),
(69501, 11, 0, '어린애들 같이.'),
(69501, 12, 0, '타오스! 내 무기를 다오!'),
(69501, 13, 0, '내 무기를! 용사여, 함께 가세. 보여줄 것이 있네.'),
(69501, 14, 0, '그만! 오늘의 싸움은 여기까지요.'),
(69501, 15, 0, '얼라이언스와 호드가 싸움을 멈추지 못하는 이유를 알겠소.'),
(69501, 16, 0, '보복은 그 자체가 공격 행위이고, 공격 행위는 즉각적인 보복을 낳기 때문이지.'),
(69501, 17, 0, '입 다무시오! 그대들이 그 순환을 깨야 하오.'),
(69501, 18, 0, '순환은 오늘, 여기서 끝날 거요. 그대, 섭정과 그대, 여군주의 손으로. 이제 돌아서서, 가시오.'),
(69501, 19, 0, '용사여, 이 휴전은 오래가지 않을지 모르나, 오늘 본 것을 기억하게.'),
(69501, 20, 0, '샨 부의 괴물이 아직 궁전 입구에 있네. 놈이 판다리아 전역을 파괴하기 전에 막아야 하네.'),
(69530, 0, 0, '타란 주! 천둥왕 폐하께 맞서려고 아무리 대군을 동원한들 소용없다. 곧 모두 그분 앞에 무릎을 꿇게 될 테니.'),
(69530, 1, 0, '신이 무슨 필요가 있나? 우리에겐 천둥왕이 계시다!'),
(69530, 2, 0, '트롤들아! 꾸물거리지 마라. 여긴 거의 다 끝냈다.'),
(69530, 3, 0, '일어나라, 나락크! 존귀하신 천둥왕 폐하를 보호하라.'),
(69530, 4, 0, '음영파 놈아, 네 머리를 천둥왕께 가져가면 정말 기뻐하실 거다.'),
(69530, 5, 0, '우리가 지배한다. 네놈들은 복종해라!'),
(69530, 6, 0, '네놈의 무례함도 이젠 진력난다! 생명을 쥐어짜 주마, 이 버릇 없는 노예 놈아!'),
(69530, 7, 0, '내가... 안 돼... 폐하... 폐하! 제가 실망을 안겨 드렸습니다!'),
(69538, 0, 0, '적이다! 형제여, 무기를 들어라! 놈들을 몰아내!'),
(69538, 1, 0, '잔달라의 진짜 힘은 아직이다!'),
(69538, 2, 0, '폐허를 지켜라. 적을 베어 버려!'),
(69538, 3, 0, '침입자를 박살내라. 방어막을 지켜야 한다.'),
(69559, 0, 0, '멍청한 것들! 내가 직접 보여 주지!'),
(69559, 1, 0, '위로 날아간다고 모를 줄 알았냐?!'),
(69559, 2, 0, '칫, 목적지까지 용케도 도착했군. 그래도 오래 살지는 못할 것이다!'),
(69559, 3, 0, '죽을 준비 해라, 침입자!'),
(69559, 4, 0, '호라키가 냉기 사격을 준비합니다!'),
(69559, 5, 0, '호라키가 하늘에 화살 빗발을 쏘아올립니다!'),
(69562, 0, 0, '천둥으로 태어났노라!'),
(69616, 13, 0, '부상병들을 수습해라. 항구로 철수한다.'),
(69617, 0, 0, '뭔가?'),
(69617, 1, 0, '아아, 키린 토의 위대한 여군주께서 싸움을 원하는 모양이지?'),
(69617, 2, 0, '순찰대! 전진!'),
(69617, 3, 0, '프라우드무어는 내가 상대하지.'),
(69617, 4, 0, '한 번에 하나씩 해결하자. 잔달라 트롤에 집중하라!'),
(69617, 5, 0, '프라우드무어! 내 백성들을 보랏빛 요새에서 풀어줘라. 아니면 내가 직접 널 베겠다!'),
(69617, 6, 0, '선리버는 가로쉬의 만행을 전혀 몰랐다!'),
(69617, 7, 0, '나는 내 백성을 보호해야 한다.'),
(69617, 8, 0, '순찰대, 무기를 내려라.'),
(69617, 9, 0, '그게 바로 내가 오늘 힘을 아끼려는 이유다.'),
(69617, 10, 0, '여군주여.'),
(69626, 0, 0, '아랫둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 1, 0, '아랫둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 2, 0, '아랫둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 3, 0, '아랫둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 4, 0, '아랫둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 5, 0, '위쪽 둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 6, 0, '위쪽 둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 7, 0, '위쪽 둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 8, 0, '위쪽 둥지에 있는 알들이 부화하기 시작합니다!'),
(69626, 9, 0, '위쪽 둥지에 있는 알들이 부화하기 시작합니다!'),
(69702, 0, 0, '막아라! 의식이 중단되어서는 안 돼!'),
(69702, 1, 0, '그 힘을... 이렇게 쓸 순 없다! 이해하지 못할 힘은 넘보지 마라!'),
(69702, 2, 0, '너희가 파멸을 초래했다. 그것이... 풀려났다...'),
(69712, 0, 0, '위쪽 둥지에 있는 알들이 부화하기 시작합니다!'),
(69712, 1, 0, '아랫둥지에 있는 알들이 부화하기 시작합니다!'),
(69712, 2, 0, '|TInterface\\Icons\\ability_hunter_pet_dragonhawk.blp:20|t지쿤이 자신의 |cFFFF0000|Hspell:134380|h[깃털]|h|r을 모든 방향으로 날립니다!'),
(69712, 3, 0, '|TInterface\\Icons\\ability_druid_galewinds.blp:20|t지쿤이 날개를 퍼덕이며 |cFFFF0000|Hspell:134370|h[하강]|h|r을 시전합니다!'),
(69712, 4, 0, '|TInterface\\Icons\\ability_hunter_animalhandler.blp:20|t지쿤이 |cFFFF0000|Hspell:138923|h[까악]|h|r거리며 적들에게 강력한 소리의 파동을 보냅니다.'),
(69743, 0, 0, '깨어나라, 후썽! 부두를 맡기겠다. 아무도 폐하의 관문을 지나지 못하게 하라.'),
(69755, 0, 0, '박살내라! 피를 보여!'),
(69755, 1, 0, '영혼이 힘을 더해 주신다!'),
(69755, 2, 0, '앞으로 나와! 천둥왕의 선물을 봐라!'),
(69755, 3, 0, '난 선택받았다. 내 피가 그분의 힘으로 불탄다!'),
(69755, 4, 0, '널 처벌하겠다! 네 인생이 얼마나 무의미한지 깨달아라!'),
(69755, 5, 0, '잔달라를 위하여!'),
(69756, 0, 0, '구슬이 폭발합니다!'),
(69837, 0, 0, '천공의 수호병이 |cFFFF2222|Hspell:140068|h[치유의 힘]|h|r의 영역을 생성합니다!'),
(69923, 0, 0, '이건 뭐지? 또 폭동인가?'),
(69923, 1, 0, '고개를 숙이지 못할까!'),
(69923, 2, 0, '너는... 벌을 받으리라...'),
(69926, 0, 0, '감히 우릴 막겠다고? 잔달라 부족을 막을 순 없다! 이번엔 안 돼!'),
(69926, 1, 0, '놈들을 처치해라, 명령이다! 잠깐, 멈춰! 멈춰!'),
(69964, 0, 0, '보아라! 난 이 세상에 존재하는 마의 에너지에 진정으로 통달했다! 내가 가진 악마의 힘은... 형언할 수 없고, 무한하며, 전능하다!'),
(69964, 1, 0, '내가 선을 넘었다고 생각하나? 내게 한계 따위는 없다. 암흑의 수확 의회는 가장 강력한 악마를 노예로 삼고, 그들의 힘을 이용해 이 세상과 아제로스에서 우리에 맞서는 자들을 처단할 것이다! 그런데 네놈 따위가 날 막겠다고? 너 따위 애송이가?'),
(69964, 2, 0, '네 실력을 보여봐라.'),
(69964, 3, 0, '하하. 약해빠진 네 공격이 귀엽군. 이제 내 새로운 소환수를 보여주지.'),
(69964, 4, 0, '아나이힐란은 매우 파괴적인 종족이지. 이들의 순수한 힘과 기운은 독보적이다.'),
(69964, 5, 0, '하하하... 날 쓰러뜨렸다고 생각했나? 아무도 날 죽일 수 없다, 하찮은 필멸자여!'),
(69964, 6, 0, '그리고 이제, 네 슬픈 이야기의 종지부를 찍어주마.'),
(69964, 7, 0, '주베카?! 지금 뭐하는...?!'),
(69964, 8, 0, '...으아아아아아아아!!!'),
(70055, 0, 0, '서로 엄호하라! 위치를 사수하라!'),
(70055, 1, 0, '아주 멋지군! 지금이다. 계속 전진해! 자비는 필요 없다!'),
(70055, 2, 0, '순찰대는 이리로! 방어선을 돌파했다!'),
(70055, 3, 0, '아니, 내가 있을 곳은 여기요.'),
(70055, 4, 0, '영웅이여! 그대는 또 한 번 호드의 승리를 이끌었소. 나도 큰 빚을 졌군.'),
(70055, 5, 0, '모두 수호물 뒤에서 집결하시오. 적이 반격하겠지만... 우린 준비를 마칠 것이오.'),
(70056, 0, 0, '이 멍청이들은 전에 날 처치했다고 생각했겠지만, 덕분에 난 더 강해졌다. 이제 잔달라 부족의 진짜 힘을 보여주자!'),
(70056, 1, 0, '내가 너희에게 선물을 주지!'),
(70056, 2, 0, '잔달라 부족을 막을 순 없다!'),
(70056, 3, 0, '천둥왕의 힘으로 잔달라 부족은 부활할 것이다.'),
(70056, 4, 0, '너흴 쓰러뜨리면 천둥왕이 상을 내리실 거야!'),
(70061, 0, 0, '천둥 가열로가 근처의 지역을 충전하기 시작했습니다. 그 안에 들어가 |cFFFF2222|Hspell:139397|h[과충전]|h|r 효과를 받으십시오!'),
(70074, 0, 0, '제련장인 불콘이 지팡이를 장비하더니 번개의 힘을 끌어모으기 시작합니다.'),
(70074, 1, 0, '제련장인 불콘이 망치를 장비하더니 엄청난 힘으로 휘두르기 시작합니다.'),
(70099, 0, 0, '음영파 방어병이 |cFFFF2222|Hspell:132744|h[치유의 보주]|h|r를 내려놓습니다!'),
(70099, 1, 0, '도움 감사합니다, 모험가님. 최선을 다해 모구를 물리치는 것을 돕겠습니다.'),
(70099, 2, 0, '이제 제련소가 안전하니 저희는 가야겠습니다. 행운을 빕니다, 모험가여.'),
(70100, 0, 0, '우선 네가 가져온 트릴리움을 정제해야 한다.'),
(70100, 1, 0, '이 가열로면 될 것이다. 거푸집 조작을 도와 다오.'),
(70100, 2, 0, '음영파가 여기 있다! 쓸모가 있을지도 모르니 도와줘야겠다.'),
(70100, 3, 0, '이 가열로면 될 것이다. 금속을 전류로 강화시킬 것이다.'),
(70100, 4, 0, '적의 주의를 끌면, 싸울 각오도 해야 한다.'),
(70100, 5, 0, '훌륭하구나! 재료는 준비됐다. 따라 오거라.'),
(70100, 6, 0, '매우 흥미롭군! 이 제련소는 고대의 티탄 기계 위에 건설되었다. 레이 션, 그대는 실로 영리한 폭군이었구나!'),
(70100, 7, 0, '내가 드워프였다면 아무 단추나 막 눌렀겠지. 하지만 우리는 목적이 있어서 온 것이다.'),
(70100, 8, 0, '이것 좀 봐라. 세상을 창조할 힘을 지녔으니, 제국을 건설하는 것쯤은 레이 션에게 일도 아니었겠지.'),
(70100, 9, 0, '모구는 자원을 조금밖에 활용하지 못했다. 천둥왕처럼 꾀가 있었던 자는 거의 없었던 모양이야.'),
(70100, 10, 0, '뭐지... "이상 물체 발견"이라. 이상 물체?'),
(70100, 11, 0, '봐라. 고대의 티탄 기술이 마치 자석같이 샤를 끌어들이는구나.'),
(70100, 12, 0, '이제 샤 처치에는 전문가겠지. 말끔히 처리해라!'),
(70100, 13, 0, '가열로를 과충전하면 샤가 불안정해지지 않을까? 한번 해보자꾸나.'),
(70100, 14, 0, '아, 내가 너무 속단했나. 샤가 강해지고 있다! 없애 버려!'),
(70100, 15, 0, '나쁜 생각을 하고 있는 건 아니겠지?'),
(70100, 16, 0, '자! 완성이다. 우리가 걸작을 벼려 냈다!'),
(70100, 17, 0, '여기서 할 일은 끝났지만, 이제 무기를 담금질해야겠다.'),
(70126, 0, 0, '아싸! 드디어! 싸움꾼 조합 초대장이다! 이제 날 막을 자는 없어!'),
(70126, 0, 1, '다들 이것 좀 봐요! 싸움꾼 조합 초대장을 받았어요! 어서 가 보고 싶네요!'),
(70126, 0, 2, '방금 싸움꾼 조합 초대장을 받았어! 분명 오늘 밤이면 8계급이 될 거야! 도착하기 전에 초대장을 잃어버리지 않아야 하는데.'),
(70126, 1, 0, '싸움꾼이 되기엔 부족했던 모양이야.'),
(70131, 1, 0, '그런데 잔달라 트롤이 이미 그곳에 요새를 구축했소.');

INSERT INTO `_koKR_stage_creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Text`) VALUES
(70228, 0, 0, '샤 융합체가 |cFFFF2222|Hspell:139382|h[정신 이상]|h|r을 시전하기 시작합니다! 모루의 힘을 방출해 막으십시오!'),
(70283, 0, 0, '|cFFFF2222[요동치는 모루]|r가 과충전되었습니다. 모루를 활성화해 에너지를 |cFFFF2222|Hspell:138834|h[방출]|h|r하십시오.'),
(70283, 1, 0, '내가 모루를 과충전했다. 샤에게는 아주 효과적일 것이나, 하나당 한 번씩만 더 사용할 수 있다!'),
(70286, 0, 0, '샤올마라 야수소환사가 자신을 도울 랩터를 소환합니다!'),
(70371, 0, 0, '에이타스, 자리를 비켜 주시오.'),
(70371, 1, 0, '그대는 지금껏 고귀하게 호드를 섬겼소. 비밀도 지킬 수 있겠지.'),
(70371, 2, 0, '대족장이 칼림도어와 판다리아에서 벌인 작전 때문에 호드가 분열하고 있소.'),
(70371, 3, 0, '우리는 천둥왕과 싸우러 왔소. 정의를 위해. 하지만 헬스크림은 지배령 거점에 사로잡혀 여기에는 신경도 쓰지 않소.'),
(70371, 4, 0, '천둥왕을 쓰러뜨리면서, 우리는 그 힘의 근원을 찾아내야 하오. 그걸 우리가 차지해야, 우리 "대족장"에게 저항할 수 있소.'),
(70371, 5, 0, '그날을 대비하려면, 미리 준비해야 하오.'),
(70371, 6, 0, '조심해!'),
(70371, 7, 0, '하! 다시 피를 보려니 기분이 좋군. 얼라이언스든 모구든, 난 가리지 않소.'),
(70371, 8, 0, '이 정도면 우리가 어떤 위기에 처했는지 알 거라 믿소. 얼라이언스와 천둥왕 사이에서, 그대와 같은 영웅의 도움이 필요하오.'),
(70371, 9, 0, '아나랄라 벨로레, 행운을 빌겠소.'),
(70437, 0, 0, '너희가 내 어전에서 쓰레기를 치웠구나. 지켜볼 만한 가치가 있겠어.'),
(70437, 1, 0, '하지만 건방진 짓거리도 여기서 끝이다. 내 요새에는 누구도 들어갈 수 없다. 네놈들의 뼈로 이 다리를 다시 짓겠다.'),
(70474, 0, 0, '$n|1이;가; |cFFFF0000|Hspell:141407|h[꽁꽁 얼어붙었습니다]|h|r. 구출하십시오!'),
(70516, 0, 0, '이 마법석에 따르면, 모구는 티탄의 피조물이었다고 한다. 돌로 만든 영혼이 없는 존재였지. 예상대로구나.'),
(70516, 1, 0, '마법석을 또 찾았구나! 어디 보자. "육신의 저주"로 모구는 필멸의 존재가 되었다. 아, 그런데 나중에 그 과정을 되돌리는 법을 알아냈다는군. 영리한 족속이야.'),
(70516, 2, 0, '모구는 티탄 수호자를 섬겼다. "라"라는 자였지. 모구 언어로 "라덴"은 "라 주인님"을 뜻한다. 흥미롭구나! 더 알아야겠다!'),
(70516, 3, 0, '모구는 주인과 함께 판다리아에 파견되었다는구나. 그들은 커다란 어둠을 찾고 있었다... 아, 조각이 불완전하구나. 더 찾아야 한다.'),
(70516, 4, 0, '이것은 고대 신, "이샤라즈"에 관한 내용이다. 머리 일곱 달린 괴물로, 어둠을 들이마셨다고 하지. 그것이 오늘날까지 판다리아를 괴롭히는 샤의 근원이었던 듯하다.'),
(70516, 5, 0, '이 마법석은 "생명의 요람"에 대해 이야기한다. 티탄이 새로운 존재를 만들어낸 곳이지. 옳지. 바로 영원꽃 골짜기다! 그곳은 숄라자르 분지의 운고로 분화구처럼, 살아 있는 실험실이었지.'),
(70516, 6, 0, '이제 큰 그림이 보이는구나. 모구는 주인인 티탄을 대신해 골짜기를 지키기 위해 창조되고 이곳에 파견되었다. 하지만 무엇으로부터? 고대 신으로부터?'),
(70516, 7, 0, '이 조각에는 "이샤라즈의 날개 달린 군단"에 대한 이야기가 나온다. 고대 신의 종이라... 혹시 사마귀 말인가?'),
(70516, 8, 0, '이 마법석은 비교적 후대의 것이다. "잠자는 수호자"에 대한 내용이지. 아마 라덴을 가리키는 것일 터. 하지만 왜 잠이 든 것일까?'),
(70516, 9, 0, '퍼즐 조각을 하나 더 찾았구나! 이것은 모구가 만든 것이다. 천 년이나 주인에게서 아무런 지시가 없고 몸이 살로 변해 버리자, 모구는 혼란에 빠졌다. 결국 내분을 일으키기 시작했지.'),
(70516, 10, 0, '흠. 모구의 만행에 대한 내용이로구나. 그들은 뿔뿔이 흩어져 각기 군주를 중심으로 족벌을 이루었다. 그중 유난히 야망이 컸던 왕이 있었지. 천둥왕 레이 션이다. 티탄 수호자가 입을 다물자, 그가 대신 입을 열기로 했지.'),
(70516, 11, 0, '아! 퍼즐의 마지막 조각이구나! 천둥왕은 라덴의 힘, 즉 티탄의 정수를 손에 넣었다. 그는 모구를 통일해 제국을 세우고 티탄의 과업을 계속하려 했다. 자기가 신이라 여긴 것이지!'),
(70544, 0, 0, '네놈들이 폭풍을 꺾었을진 몰라도, 잔달라의 의지를 꺾을 수는 없다! 너흰 여기서 죽을 거야.. 하나도 남김없이!'),
(70544, 1, 0, '모든 트롤이 너희에 맞서 손잡을 것이다!'),
(70544, 2, 0, '우리는 모래를, 바다를, 바람을 지배한다...'),
(70544, 3, 0, '우리는... 네놈들을 이 산에 묻어버릴 것이다!'),
(70544, 4, 0, '내가... 끝이 아니다! 잔달라는... 절대로 쓰러지지 않아...'),
(70602, 0, 0, '오호호호호, 내 수염에 걸고 이번엔 끝장인 줄 알았는데. 아이고 고맙습니다. 고마워요!'),
(70602, 1, 0, '아, 맞아요. 그게... 인간 왕이 당신을 보냈습니까? 그의 비밀요원은 다 죽었습니다. 우리도 거의 다 당했고요.'),
(70602, 2, 0, '볼드브루가 막 물고 차면서 남쪽 오두막으로 끌려가는 걸 봤습니다. 서두르시면 그녀를 구할 수 있을 겁니다. 저보단 아는 게 많을걸요.'),
(70602, 3, 0, '하지만 오두막이 여러 개 있는 곳은 피하십시오! 잔뜩 흥분한 얼음 트롤이 득시글거리니까요. 으... 잔달라 사제가 놈들이 아주 미쳐 돌아가게 만들었어요.'),
(70605, 0, 0, '뉴트, 저 문을 열어.'),
(70605, 1, 0, '그릿, 티커, 볼트. 너희 셋은 뉴트를 지원해줘.'),
(70605, 2, 0, '거기 신병 $p! 넌 날 따라와.'),
(70605, 3, 0, '우린 듀로타에서 최근 발생한 납치 사건의 단서를 쫓다가, 여기 성난불길의 구석진 곳까지 오게 된 거라고.'),
(70605, 4, 0, '이 사건의 배후가 누군지 알아내서 막는 게 우리 임무야.'),
(70605, 5, 0, '딱 붙어 있으라고.'),
(70605, 6, 0, '뉴트, 지금 당장 이 문을 열어야 해!'),
(70605, 7, 0, '가자고! 가자고!'),
(70605, 8, 0, '이건 뭐지...?'),
(70605, 9, 0, '고블린 분대! 각자 방어하라!'),
(70605, 10, 0, '소렌스! 우린 네 적이 아니야!'),
(70605, 11, 0, '열등하다고? 누가 진짜 열등한지 보여주지!'),
(70605, 12, 0, '좋지 않은데.'),
(70605, 13, 0, '모두 흩어져서 저장실을 수색하도록. 이 일을 가로쉬가 꾸민 거라면, 뭔가 증거가 필요해.'),
(70605, 14, 0, '이봐, $p! 빨리 이리 좀 와 봐!'),
(70605, 15, 0, '티커, 이거 열 수 있겠어?'),
(70605, 16, 0, '사마귀 폭탄이잖아?! 그게 동굴을 홀랑 무너뜨리진 않겠지?'),
(70605, 17, 0, '뭐에 쓰이는지는 상관없어! 저걸로 이 문을 열 수는 있는 거지?'),
(70605, 18, 0, '문이 꼼짝도 안 하잖아...'),
(70605, 19, 0, '그릿, 비상용 순간이동기 좀 설치해! 이 일을 볼진 님께 즉시 보고해야 한다고.'),
(70605, 20, 0, '신병들, 너희가 유일하게 싸울 수 있는 병력이라고!'),
(70605, 21, 0, '순간이동기가 준비될 때까지 우리를 지켜줘!'),
(70605, 22, 0, '놈들이 더 나타나기 전에 모두 나가자!'),
(70607, 0, 0, '원시비룡 알이잖아... 가로쉬가 용아귀 부족과 손을 잡은 건가? 원시비룡을 탄 오크라... 느낌이 안 좋아, $p. 아주 안 좋다고.'),
(70607, 1, 0, '다음번엔 조금 더 일찍 경고해 달라고!'),
(70607, 2, 0, '진정해! 그게 무슨 불이 붙은 거야!'),
(70607, 3, 0, '바로 시작하겠습니다, 분대장님!'),
(70607, 4, 0, '순간이동기가 준비됐어! 어서 여기를 뜨자고!'),
(70608, 0, 0, '분대장님, 이놈들은 가로쉬의 부하들입니다.'),
(70608, 1, 0, '정말... 정말 아름다워!'),
(70608, 2, 0, '도와주세요!'),
(70608, 3, 0, '몸에 불이 붙었어!'),
(70609, 0, 0, '알겠습니다.'),
(70609, 1, 0, '분대장님, 이 코르크론 놈들은 그리 친절해 보이진 않는데요!'),
(70609, 2, 0, '딱 맞는 게 있죠!'),
(70609, 3, 0, '특별한 경우에 쓰려고 아껴놨던 겁니다.'),
(70609, 4, 0, '개조를 좀 해야겠지만, 문은 확실히 날려버릴 수 있을 겁니다.'),
(70609, 5, 0, '신참, 저 물놀이용 조랑말이랑 대포알 세 개, 전지 두 개, 그리고 원시비룡 알 노른자 좀 가져오라고.'),
(70609, 6, 0, '이걸 손으로 잡고 옮긴 거야?! 으... 돌아가면 위생병에게 가봐야 할 거야...'),
(70609, 7, 0, '그래, 이게 바로 우리에게 필요했던 거지!'),
(70609, 8, 0, '가장 중요한 재료야!'),
(70609, 9, 0, '조심해! 이건 장난감이 아니라고!'),
(70609, 10, 0, '동력이 조금 더 필요한데......'),
(70609, 11, 0, '이거면 안정 장치를 망가뜨릴 동력으로 충분할 거야.'),
(70609, 12, 0, '내 명품 폭탄이 완성됐어!!'),
(70609, 13, 0, '내 천재성을 의심하지 말라고!'),
(70609, 14, 0, '이게 갤리윅스의 개인 금고를 열어줄 겁니다!'),
(70609, 15, 0, '기폭 장치가 터지면 말이죠... 에, 그러니까... 지금!'),
(70678, 0, 0, '복덩이 플루트!'),
(70678, 1, 0, '멍청한 그루멀짐 같으니!'),
(70683, 0, 0, '침입자다! 저 놈들을 막아라!'),
(70683, 1, 0, '약해 빠진 것!'),
(70683, 2, 0, '문을 봉쇄하고 즉시 감독관에게 알려라.'),
(70683, 3, 0, '하등한 종족들은 모두 진정한 호드의 적이다!'),
(70683, 4, 0, '|TInterface\\Icons\\ability_deathknight_remorselesswinters:20|t%s|1이;가; |cFFF00000|Hspell:142320|h[빙하 얼리기 토템]|h|r을 소환합니다!'),
(70683, 5, 0, '|TInterface\\Icons\\spell_fire_windsofwoe:20|t%s|1이;가; |cFFF00000|Hspell:142306|h[분쇄된 대지]|h|r를 시전합니다!'),
(70740, 0, 0, '선물 하나 달라고?! 난 지금 다리도 못 움직이거든?!!'),
(70740, 1, 0, '나도 반짝반짝한... 데...'),
(70740, 2, 0, '전... 기... 엄청난... 약점...'),
(70745, 0, 0, '더러운 괴물 같으니! 살려주셔서 감사합니다.'),
(70745, 1, 0, '그거 말입니다. 폭풍이요. 어떻게 만들어낸 건지 알아냈어요. 저 교활한 잔달라 놈이 얼음 트롤들을 시켜서 원소 정령한테 제물을 바치고 있습니다.'),
(70745, 2, 0, '여기 북쪽, 다리 건너에 동굴이 있어요. 그 안의 정령을 처치하면, 이 폭풍이 멎을 겁니다.'),
(70788, 0, 0, '유물 보너스 +5!'),
(70792, 0, 0, '유물 보너스 +10!'),
(70799, 0, 0, '내 요원들이 잔달라를 여기까지 추적했소.'),
(70799, 1, 0, '잔달라가 놈들과 어떤 사악한 계획을 세우고 있을지...'),
(70799, 2, 0, '확실히... 자연스러운 날씨가 아니오.'),
(70799, 3, 0, '내 용사들이 갈 것이오. 할 수 있는 일을 하고, 구출할 수 있는 이들을 구출할 거요.'),
(70799, 4, 0, '그대가 여기 있어 힘이 나는구려, 모이라. 감사하오.'),
(70799, 5, 0, '흠... 잘 가시오, 섭정 여왕.'),
(70799, 6, 0, '잘 싸웠소. 검은무쇠 부족은 여전히 용맹하군.'),
(70799, 7, 0, '하하하! 그래서 기쁘오. 브론즈비어드와 와일드해머는 여기서 승리를 나누지 못한 걸 후회할 거요.'),
(70799, 8, 0, '그리고 훌륭히 해냈지. 자, 갑시다. 아이언포지로 돌아가, 의회에 그대의 승리를 알립시다.'),
(70801, 0, 0, '제일 가까운 정찰병은 바로 저기 있네. 그를 구해주면 뭔가 알려줄지도 모르지.'),
(70801, 1, 0, '우리가 숨어서 지원하겠네. 목표물을 지정해 주면, 총을 쏘지.'),
(70824, 0, 0, '타오르는 분노가 곧 |cFFFF2222|Hspell:141456|h[폭발]|h|r합니다!'),
(70956, 0, 0, '물리학의 법칙이여 감사합니다! 어서 와!'),
(70956, 1, 0, '우리가 뭔가 찾아냈어. 아주 커다란 거야. 그런데 갑자기 바위가 우릴 공격하고, 다들 정신이 나가버렸어. 손해가 엄청나!'),
(70956, 2, 0, '제발, 어떻게 좀 해 줘!'),
(70956, 3, 0, '방금 그 괴상망측한 게 대체 뭐였지?'),
(70956, 4, 0, '허허, 걱정은 하지 마시라니까. 저런 걸 건드리고 싶은 놈이 어디 있겠어? 돈만 받으면 바로 사라져 줄게.'),
(70956, 5, 0, '어이, 어이, 이게 뭐야, 어?! 약속했던 돈의 5분의 1도 안 되잖아!'),
(70956, 6, 0, '아니, 아냐, 아냐, 계약을 했잖아. 전액 지급하기로...'),
(70956, 7, 0, '그래, 어디 때가 되면 가로쉬가 어떻게 되나 한번 보자고.'),
(70956, 8, 0, '어, 아니, 거 아무것도 아냐. 호드를 위하여! 뭐 그런 거 있잖아. 어, 그러니까... 안녕!'),
(70959, 0, 0, '하수인들아, 이 벌레들을 없애라!'),
(70959, 1, 0, '|cFFFF0000|Hspell:141387|h[울타지스의 방패]|h|r가 파괴되었습니다!'),
(71030, 0, 0, '주위에 있는 알에서 새끼 원시비룡이 부화합니다!'),
(71030, 1, 0, '용암에서 잿불핵이 나타납니다!'),
(71030, 2, 0, '네놈들은 이 동굴에서 절대 못 벗어난다!'),
(71030, 3, 0, '진정한 호드, 순수한 호드를 막을 순 없다!'),
(71030, 4, 0, '놈들을 처치하라! 호드를 위하여!'),
(71030, 5, 0, '|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 목표: 정해진 시간 안에 적들을 모두 처치하십시오!'),
(71030, 6, 0, '어리석구나! 너희 따위가 진정한 호드를 막아낼 순 없다!'),
(71095, 0, 0, '레이 스의 상이 불길하게 일렁입니다.'),
(71095, 1, 0, '레이 스의 상이 한 번 더 일렁입니다.'),
(71095, 2, 0, '%s|1이;가; 나타납니다!'),
(71107, 0, 0, '아, 젊은 검은용이 고맙게도 내 사원에 발걸음을 했군. 너와 네 용사가 한 일은 이미 판다렌의 전설이 되고 있다.'),
(71107, 1, 0, '말해 봐라, 젊은 왕자여. 힘의 본질이 무엇이냐?'),
(71107, 2, 0, '단순히 적에 대해서만 생각하고 대답하는구나.'),
(71107, 3, 0, '어떻게?'),
(71107, 4, 0, '이거야 원, 뼛속까지 검은용이로군. 좋다. 내 축복을 내려 주지. 작은 충고도 함께.'),
(71107, 5, 0, '힘이란 다른 이를 위해 사용할 때가, 자신의 적을 무찌르려고 사용할 때보다 두 배는 강한 법이다.'),
(71107, 6, 0, '자, 나의 시험을 받겠느냐? 어떤 위험이라도 당당히 마주하고, 끝까지 꿋꿋하게 싸워갈 수 있는지 보는 시험이다.'),
(71107, 7, 0, '자, 시험을 시작하자! 영웅이여, 넌 이제 근접 전투에서 검은 왕자에게 승리해야 한다.'),
(71107, 9, 0, '검은 왕자여, 물론 넌 매우 강하지. 하지만 이끌어줄 눈이 없다면 힘이 무슨 소용이겠느냐?'),
(71108, 0, 0, '이제부터 벌어질 일이 참으로 기대되는구나. 백호는 판다리아가 품은 힘의 화신이지!'),
(71108, 1, 0, '위대한 백호여! 저희의 간청을 들어주소서.'),
(71108, 2, 0, '저와 저의 용사에게 힘의 축복을 내려 주소서.'),
(71108, 3, 0, '제가 선택한 동료를 자랑스럽게 생각합니다.'),
(71108, 4, 0, '적을 무찌르는 능력입니다. 그것이 바로 힘입니다.'),
(71108, 5, 0, '물론, 힘으로 친구를 도울 수도 있지요.'),
(71108, 6, 0, '... 힘으로 친구의 적을 무찌르는 겁니다!'),
(71108, 7, 0, '잠깐, 말도 안 됩니다. 저의 용사를 제 손으로 죽이라고요?'),
(71108, 8, 0, '... 흥미롭군요. 하지만 결과는 다르지 않을 겁니다.'),
(71108, 9, 0, '좋습니다. 미안하구나, 용사여. 하지만 오늘 교훈을 얻을 사람은 내가 아니다.'),
(71108, 10, 0, '눈 먼 용이라니. 어이가 없어서!'),
(71123, 0, 0, '내 피가 굶주렸다.'),
(71123, 1, 0, '직업 재사용 대기시간이 초기화되었습니다!'),
(71123, 2, 0, '나는 잠을 잘 뿐이다.'),
(71142, 0, 0, '여기다. 위대한 흑우 니우짜오의 보금자리. 그는 판다렌의 인내를 상징하는 존재지. 유일하게 벽 너머에 머물기를 선택한 천신이고.'),
(71142, 1, 0, '강대한 흑우여! 저희의 간청을 들어주소서.'),
(71142, 2, 0, '저와 저의 용사에게 인내의 축복을 내려 주소서.'),
(71142, 3, 0, '어떤 역경도 이겨내는 힘입니다! 그것이 바로 인내입니다.'),
(71142, 4, 0, '하시고 싶은 말씀이... 육체적 강인함은 외적인 조건일 뿐, 인내는 내면에서 나온다는 겁니까?'),
(71142, 5, 0, '... 그렇죠. 알고 있었습니다.'),
(71144, 0, 0, '호오, 용과 그의 필멸의 용사가 날 찾아왔군. 내 너희를 환영하노라.'),
(71144, 1, 0, '말해 보아라, 검은 왕자여. 인내의 본질이 무엇이냐?'),
(71144, 2, 0, '너는 힘과 인내를 착각하고 있구나, 젊은 용이여. 힘이란 강인한 정신 없이는 무용지물이지!'),
(71144, 3, 0, '난 초라한 노예들이 상상도 할 수 없는 끔찍한 고문을 견뎌내고, 마침내 봉기하여 그 주인을 타도하는 것을 보았다.'),
(71144, 4, 0, '또한 가장 강력한 황제들이, 하잘것없는 적들이 가진 불굴의 인내에 꺾이는 모습도 보았지.'),
(71144, 5, 0, '바로 그거다!'),
(71144, 6, 0, '물론 알고 있었겠지. 잘 이해하고 있는지 시험해 보는 건 어떤가?'),
(71144, 7, 0, '나의 시험을 받겠느냐? 너의 용사가 끔찍한 역경을 견뎌내며 다른 이를 지키고 보호할 수 있는지 알아보는 시험이다.'),
(71152, 0, 0, '그 후엔 고대 신께서 사마귀를 위해 이 세상을 재창조하시리라!'),
(71152, 1, 0, '복수를 부탁하네, 형제들이여!'),
(71153, 0, 0, '티탄의 아이들아, 오너라. 우리 용장들이 상대해 주지.'),
(71153, 1, 0, '아... 사냥꾼이... 사냥감이 되다니...'),
(71154, 0, 0, '우리는 옛날 판다렌을 처치했듯이 쉽게 너희를 처치할 것이다.'),
(71154, 1, 0, '너무 느리구나. 그래서 먹이는 어떻게 잡지?'),
(71154, 2, 0, '으, 망할 갑각 때문에 빨리 움직일 수가 없었어!'),
(71155, 0, 0, '우리는 강탈자들과 그 자손을 이겼고, 고대 신의 실종을 견뎠다. 이제 너희 차례다.'),
(71155, 1, 0, '이 몸은 시초자다. 우월한 존재에게 굴복하라.'),
(71155, 2, 0, '날 호박석으로 돌려보내 다오...'),
(71156, 0, 0, '그런 건 상관없네. 놈들이 고대 신을 귀찮게 하는 일은 없을 테니.'),
(71156, 1, 0, '귀여운 쿤총들아, 밥 먹을 시간이다!'),
(71156, 2, 0, '코보크... 이리 오너라... 네가 필...'),
(71157, 0, 0, '우리 사마귀는 이들이 섬기는 신보다 훨씬 막대한 힘을 섬기지.'),
(71157, 1, 0, '내 새로운 물약을 맛보러 왔느냐, 깨우는 자여? 이제껏 한 번도 경험한 적이 없는 맛일 것이다.'),
(71157, 2, 0, '내 물약은 종류가 아주 많다. 어느 것으로 하겠느냐?'),
(71157, 3, 0, '아... 죽음에... 마개를 끼우는 법만큼은... 알아내지 못했다...'),
(71158, 0, 0, '여기까지 왔다고? 그러게 내가 놈들한테 미세음파 유전자 조작을 쓰자고 했지.'),
(71158, 1, 0, '좋아... 새로운 실험 대상이군!'),
(71158, 2, 0, '내 힘을... 진화시켜야... 했던 건가...'),
(71160, 0, 0, '정말 비논리적이군. 놈들은 킬루크의 경고를 듣지 못한 건가?'),
(71160, 1, 0, '혼란은 곧 질서다! 미욱한 자들은 모르지!'),
(71160, 2, 0, '두뇌 싸움을 해 볼까?'),
(71160, 3, 0, '내 계산이 틀렸다고? 또 800년을 기다려야 하나...'),
(71161, 0, 0, '보게, 형제들이여. 깨우는 자가 왔네!'),
(71161, 1, 0, '깨우는 자여, 마지막으로 너희를 파멸로 데려가 주마!'),
(71161, 2, 0, '잘 싸웠다, 깨우는 자여. 우리는 다시 만날 것이다...'),
(71166, 0, 0, '희망의 화신 주학은 역사의 여명기부터 판다리아의 주민들에게 힘을 주는 존재였지. 그와 얘기하는 게 기대되는구나.'),
(71166, 1, 0, '위대한 주학이여! 저희의 간청을 들어주소서.'),
(71166, 2, 0, '저와 저의 용사에게 희망의 축복을 내려 주소서.'),
(71166, 3, 0, '희망이란... 그건... 더 나은 내일에 대한 믿음입니다.'),
(71166, 4, 0, '위대한 학이여, 당신은 제가 본 것을 못 보셨습니다.'),
(71166, 5, 0, '... 그 옛날 하늘을 불태웠던 불길이 돌아올 겁니다. 막을 수가 없습니다. 불타는 군단이 아제로스를 찾을 겁니다.'),
(71166, 6, 0, '피가 바다를 이루고, 도시는 폐허가 되겠죠! 우리가, 이렇게 분열된 채로... 어떻게 군단에 맞서겠습니까?'),
(71166, 7, 0, '희망을 말씀하셨죠. 알아 주세요. 다가오는 이 파멸에서 우리가 어떻게든 살아남을 수 있을 거라는 그 한 조각 믿음이, 저를 지탱하는 전부입니다.'),
(71166, 8, 0, '전... 감사합니다, 위대한 학이여.'),
(71169, 0, 0, '이런, 이런, 세계파괴자의 아이로구나. 누구나 구원받을 수 있다는 증거지. 날 찾아와 주어 영광이다.'),
(71169, 1, 0, '말해 보아라, 대지의 수호자의 아들아. 희망의 본질이 무엇이냐?'),
(71169, 2, 0, '말뿐이군. 네 말에 의심이 서려 있다.'),
(71169, 3, 0, '날 과소평가하는구나.'),
(71169, 4, 0, '일어나라, 데스윙의 아들아. 내 축복을 내려 주겠다. 너는 누구보다도 그 축복이 필요한 자이니.'),
(71169, 5, 0, '희망이란 것을, 모호하고 불투명한 어떤 것으로 생각해선 안 된다.'),
(71169, 6, 0, '매일매일 가슴속에 희망을 품고 살아라. 그럼으로써, 네가 꿈꾸는 미래를 만들어갈 것이니.'),
(71169, 7, 0, '나의 시험을 받겠느냐? 무엇과도 비교할 수 없는 깊은 상처를 치유하는 시험이다.'),
(71177, 0, 0, '손대지 마라, 고블린. 대족장님께서 여기서 찾아오라고 하신 유물이다. 코르크론이 직접 보호하겠다.'),
(71177, 1, 0, '돈은 남아 있는 놈들만 받는 거다. 대족장님께서는 죽은 것들 따위는 인정하지 않으신다.'),
(71177, 2, 0, '그래, 이런 것들이 우리 호드의 본질을 흐려 놓은 거다.'),
(71177, 3, 0, '대족장님께서는 죽은 자들의 가족도 너그러이 받아 주신다. 호드를 섬기다 죽는 건 커다란 영광이거늘, 너희 족속들은 그 더러운 주머니를 채우려고만 하고 있구나!'),
(71177, 4, 0, '나는 네놈들이 역겹다. 작고, 약하고, 도둑놈들처럼 명예라고는 모르지. 대족장님이 너희를 내버려 두시는 걸 다행으로 생각해라.'),
(71177, 5, 0, '뭐라고 했나, 고블린?!'),
(71246, 0, 0, '통제 실패. 자체 방어 장치 가동.'),
(71246, 1, 0, '동력부 가동.'),
(71327, 0, 0, '호드 놈들이 우리 함선에 침입했다. 모두 쓸어버려!'),
(71327, 1, 0, '아, 결투를 원하는가? 그렇다면 들어주지!'),
(71327, 2, 0, '발사!'),
(71327, 3, 0, '레이피어가 바닥에 떨어졌습니다. 레이피어를 들고 제독 해그먼과 싸우십시오!'),
(71328, 0, 0, '이거나 먹어라!'),
(71328, 1, 0, '폭탄이다!'),
(71329, 0, 0, '이거나 먹어라!'),
(71329, 1, 0, '총알이 떨어졌어!'),
(71329, 2, 0, '%s|1이;가; 그의 |cFFFF2222|Hspell:141381|h[산탄총]|h|r을 장전하기 위해 뜁니다.'),
(71330, 0, 0, '이거나 먹어라!'),
(71330, 1, 0, '%s|1이;가; 당신에게 |cFFFF2222|Hspell:132998|h[점착 폭탄]|h|r을 붙였습니다!'),
(71330, 2, 0, '%s|1이;가; |cFFFF2222|Hspell:141327|h[휘발성 혼합물]|h|r을 마시기 시작합니다!'),
(71330, 3, 0, '이게 효과가 있는지 한 번 보자고!'),
(71352, 0, 0, '어떤 대가가 따르든 옳은 일을 하는 것, 그것이 바로 지혜입니다.'),
(71352, 1, 0, '정의를 위해 행동하지 않는 것이 어떻게 지혜입니까?'),
(71358, 0, 0, '그럼 다 괜찮아진 거야?'),
(71358, 1, 0, '시간이 없어... 이 벽을 박살내 버리자!'),
(71358, 2, 0, '거 참 굉장한 폭발인데! 가서 확인해 보자고.'),
(71358, 3, 0, '무슨 커다란 상자 같아... 아마 골드가 가득 들어 있을 거야. 그게 다 우리 거라고!'),
(71426, 0, 0, '잘 왔다, 용사여!'),
(71426, 1, 0, '천신과의 일은 정말 잘 되었군. 그들이 얼마나 수다스러운지 봤나?'),
(71426, 2, 0, '난 그냥 천신들이 조용히 축복을 내려주길 바랐는데, 참 끝도 없이 재잘거리더군.'),
(71426, 3, 0, '아, 미안하다... 어디까지 얘기했지? 아, 그래! 선물이 있다.'),
(71426, 4, 0, '이 판다리아의 천신들이 우리의 원대한 성전을 지원한다! 보아라...'),
(71426, 5, 0, '우리는 백호에게서 힘을 얻었고...'),
(71426, 6, 0, '옥룡에게서 지혜를 얻었다...'),
(71426, 7, 0, '흑우는 인내로 우리를 축복했고...'),
(71426, 8, 0, '주학은... 빛나는 희망을 우리에게 허락했지! 더 나은 세상을 위해!'),
(71426, 9, 0, '우리의 세상을 위해.'),
(71426, 10, 0, '자! 준비됐다!'),
(71436, 0, 0, '얼라이언스 돼지들이 배에 오르고 있다! 놈들을 몰아내!'),
(71436, 1, 0, '승리는 우리 거야! 대포에 올라 계속 공격해!'),
(71445, 0, 0, '도와줘! 이 얼라이언스 개들을 몰아내야 해!'),
(71445, 1, 0, '더 넘어온다! 마지막 놈들인 것 같군!'),
(71445, 2, 0, '적을 적함까지 밀어붙였군. 뱃머리를 돌리고 놈들의 폭탄을 훔쳐 적함을 산산조각 내라!'),
(71445, 3, 0, '모두 처치했군! 이제 함선의 바닥으로 가서 저 폭발물을 설치하라고!'),
(71445, 4, 0, '배가 폭발하려고 합니다. 맨 위쪽 갑판으로 올라가 뛰어내리십시오!'),
(71445, 18, 0, '이 정도면 정신 좀 차렸겠지! 이제 저 대포를 타고 놈들의 기함으로 이동해!'),
(71454, 0, 0, '나즈그림이 우릴 실망시켰다. 코르크론! 침입자들을 처치해라!'),
(71454, 1, 0, '난 대족장님을 실망시키지 않아!'),
(71454, 2, 0, '가로쉬 님의 힘이다!'),
(71454, 3, 0, '진정한 호드의 힘을 봐라!'),
(71454, 4, 0, '진정한 호드를... 막을 순... 없다!'),
(71454, 5, 0, '힘이 넘친다!'),
(71454, 6, 0, '장비를 배치하라! 방어선을 구축해!'),
(71454, 7, 0, '대족장님을 위해 죽는 건... 영광이다...'),
(71454, 8, 0, '|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s|1이;가; |cFFF00000|Hspell:142842|h[이샤라즈의 숨결]|h|r을 시전합니다!'),
(71454, 9, 0, '|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s|1이;가; |cFFF00000|Hspell:142879|h[피의 분노]|h|r에 돌입합니다!'),
(71454, 10, 0, '|TInterface\\Icons\\racial_orc_berserkerstrength.blp:20|t%s의 |cFFF00000|Hspell:142879|h[피의 분노]|h|r가 멈춥니다!'),
(71466, 0, 0, '%s|1이;가; 공성 모드로 전환합니다!'),
(71466, 1, 0, '%s|1이;가; 다시 맹공 모드로 전환합니다!'),
(71475, 0, 0, '루크... 너 누군지 알아...'),
(71475, 1, 0, '루크... 잘 모른다... 머리가... 컴컴해...'),
(71475, 2, 0, '제발... 도와줘...'),
(71475, 3, 0, '쑨... 허... 나 도와줘.'),
(71475, 4, 0, '|TInterface\\Icons\\spell_monk_ringofpeace:20|t%s|1이;가; |cFFFF0000|Hspell:143955|h[고통, 슬픔, 그리고 우울]|h|r을 시전합니다!'),
(71475, 5, 0, '루크... 도움이 필요해!'),
(71475, 6, 0, '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s|1이;가; |cFFFF0000|Hspell:143497|h[황금 연꽃의 결속력]|h|r을 시전합니다.'),
(71475, 7, 0, '루크... 위험해...'),
(71475, 8, 0, '루크랑... 싸우자.'),
(71479, 0, 0, '|TInterface\\Icons\\ability_rogue_deadliness:20|t%s|1이;가; |cFFFF0000|Hspell:143840|h[고뇌의 징표]|h|r를 만듭니다!'),
(71479, 1, 0, '%s|1이;가; 도움을 요청합니다.'),
(71479, 2, 0, '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s|1이;가; |cFFFF0000|Hspell:143497|h[황금 연꽃의 결속력]|h|r을 시전합니다.'),
(71479, 3, 0, '%s|1이;가; 위협적으로 노려봅니다.'),
(71479, 4, 0, '|TInterface\\Icons\\ability_gouge:20|t%s|1이;가; |cFFFF0000|Hspell:143330|h[후려치기]|h|r를 시도합니다. 눈을 피하십시오!'),
(71479, 5, 0, '|TInterface\\Icons\\ability_creature_poison_04:20|t%s|1이;가; 자기 단검에 |cFFFF0000|Hspell:143224|h[순간 효과 독]|h|r을 바릅니다!'),
(71479, 6, 0, '|TInterface\\Icons\\ability_rogue_deviouspoisons:20|t%s|1이;가; 자기 단검에 |cFFFF0000|Hspell:143239|h[맹독]|h|r을 바릅니다!'),
(71480, 1, 0, '|TInterface\\Icons\\ability_druid_typhoon:20|t%s|1이;가; |cFFFF0000|Hspell:143559|h[암울한 명상]|h|r에 돌입합니다!'),
(71480, 4, 0, '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s|1이;가; |cFFFF0000|Hspell:143497|h[황금 연꽃의 결속력]|h|r을 시전합니다.'),
(71504, 0, 0, '심장부 문 잠금 장치가 풀리자 강철 가는 소리가 통로에 울려 퍼집니다.'),
(71504, 1, 0, '|TInterface\\Icons\\inv_misc_sawblade_01.blp:20|t 공성기술자 블랙퓨즈가 당신을 향해 |cFFFF0000|Hspell:143266|h[톱날 발사]|h|r를 준비합니다!'),
(71515, 0, 0, '그 어떤 얼라이언스도 날 쓰러뜨리진 못했다. 너희라고 가능할 것 같나?'),
(71515, 1, 0, '나는 나즈그림, 대족장님의 오른팔이자 호드의 장군. 흐... 내 오늘 죽을 운명이라면, 명예롭게 싸우다 죽으리라. 호드를 위하여!'),
(71515, 2, 0, '|TInterface\\Icons\\ability_warrior_offensivestance.blp:20|t 장군 나즈그림이 |cFFFF0000|Hspell:143589|h[전투 태세]|h|r를 취합니다!'),
(71515, 3, 0, '전 코르크론, 내 명령을 따르라. 모두 죽여!'),
(71515, 4, 0, '|TInterface\\Icons\\ability_racial_avatar.blp:20|t 장군 나즈그림이 |cFFFF0000|Hspell:143594|h[광폭 태세]|h|r를 취합니다!'),
(71515, 5, 0, '명예롭게... 죽는구나... 록타르 오가르...'),
(71515, 6, 0, '드디어 때가 왔군. 수년간, 우린 함께 싸우며 성장해왔다. 그리고 마침내, 전장에서 이렇게 맞붙게 되었구나. 내가 봐줄 거라 생각 마라, 너 역시 날 봐줘선 안 돼. 지금부터 벌어질 우리 싸움은 그 누구도 아닌, 바로 호드를 위한 거니까.'),
(71515, 7, 0, '마침내 너와 싸우게 되어 영광이다. 록타르 오가르. 명예를 위해, 그리고 호드를 위하여!'),
(71515, 8, 0, '아... 참 많이 늘었구나... 명예로운 전투였다.'),
(71515, 9, 0, '코르크론! 날 지원하라!'),
(71515, 9, 1, '다음 분대, 앞으로!'),
(71515, 10, 0, '|TInterface\\Icons\\ability_warrior_defensivestance.blp:20|t 장군 나즈그림이 |cFFFF0000|Hspell:143593|h[방어 태세]|h|r를 취합니다!'),
(71515, 11, 0, '최후의 순간까지, 난 대족장 곁을 지켰다. 그게 내 임무였으니까. 날 쓰러뜨린 게 너라 기쁘구나. 너의 힘이... 호드를... 새 시대로 이끌길 빌겠다.'),
(71529, 0, 0, '%s|1이;가; 고통에 비틀거리며 분노 섞인 눈으로 $n|1을;를; 노려봅니다.'),
(71529, 1, 0, '%s|1이;가; 부상당한 적들이 뭉쳐 있는 걸 보곤 |cFFFF0404|Hspell:143440|h[피의 광란]|h|r에 휩싸입니다!'),
(71543, 0, 0, '|TInterface\\Icons\\ability_shawaterelemental_split.blp:20|t%s|1이;가; |cFFFF0000|Hspell:143020|h[분열]|h|r합니다!'),
(71543, 1, 0, '|TInterface\\Icons\\ability_shawaterelemental_reform.blp:20|t%s|1이;가; |cFFFF0000|Hspell:143469|h[재결합]|h|r합니다!'),
(71543, 2, 0, '|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t%s|1이;가; |cFFFF0000|Hspell:143309|h[소용돌이]|h|r를 시전합니다!'),
(71543, 3, 0, '새로운 웅덩이를 만들어 내던 타락이 마지막 물의 수호병과 함께 사라지자 조용한 울림도 멈춥니다.'),
(71658, 0, 0, '침입자 놈들! 다른 쓰레기들과 함께 감옥에 처넣어주지!'),
(71734, 0, 0, '덤벼라. 네 교만에 복종하고 "위대함"을 증명해 봐라!'),
(71734, 1, 0, '어리석긴...'),
(71734, 2, 0, '교만에 눈먼 티탄의 꼭두각시여! 너는 나를 감당할 수 없다!'),
(71734, 7, 0, '|TInterface\\Icons\\sha_spell_warlock_demonsoul.blp:20|t %s|1이;가; |cFFF00000|Hspell:144400|h[팽창하는 교만]|h|r을 시전합니다!'),
(71740, 0, 0, '|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t 활성화된 레이저 포탑이 당신을 조준합니다!'),
(71742, 0, 0, '형제들아, 멈춰라! 눈 앞에 야수가 보이지 않나?'),
(71742, 1, 0, '크로스의 빛이 보이지 않나? 이 야수는 더럽혀졌다!'),
(71742, 2, 0, '우린 크로스의 핏줄이다!'),
(71749, 0, 0, '고맙습니다. 힘 닿는 데까지 돕겠습니다.'),
(71763, 0, 0, '모두 태워라! 재로 만들어 버려!'),
(71788, 0, 0, '|TInterface\\Icons\\Ability_Siege_Engineer_Detonate.blp:20|t 거미 지뢰가 당신을 대상으로 포착합니다!'),
(71788, 1, 0, '$n|1이;가; 거미 지뢰를 터트렸습니다!'),
(71858, 1, 0, '|TInterface\\Icons\\spell_nature_diseasecleansingtotem.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144288|h[독안개 토템]|h|r을 내려놓습니다!'),
(71858, 3, 0, '|TInterface\\Icons\\spell_nature_natureresistancetotem.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144289|h[역겨운 물결 토템]|h|r을 내려놓습니다!'),
(71858, 4, 0, '|TInterface\\Icons\\spell_frost_fireresistancetotem.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144290|h[잿빛섬광 토템]|h|r을 내려놓습니다!'),
(71858, 6, 0, '진정한 호드의 피는 힘을 갈망한다!'),
(71858, 7, 0, '|TInterface\\Icons\\spell_nature_bloodlust.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144302|h[피의 욕망]|h|r효과를 얻습니다!'),
(71859, 0, 0, '폭풍!'),
(71859, 1, 0, '|TInterface\\Icons\\spell_nature_diseasecleansingtotem.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144288|h[독안개 토템]|h|r을 내려놓습니다!'),
(71859, 2, 0, '|TInterface\\Icons\\spell_nature_natureresistancetotem.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144289|h[역겨운 물결 토템]|h|r을 내려놓습니다!'),
(71859, 3, 0, '고여 있고 유독한 고통의 물!'),
(71859, 4, 0, '|TInterface\\Icons\\spell_frost_fireresistancetotem.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144290|h[잿빛섬광 토템]|h|r을 내려놓습니다!'),
(71859, 5, 0, '진정한 호드의 피는 힘을 갈망한다!'),
(71859, 6, 0, '|TInterface\\Icons\\spell_nature_bloodlust.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144302|h[피의 욕망]|h|r효과를 얻습니다!'),
(71859, 7, 0, '정령이여... 우리가 무슨 짓을...'),
(71859, 8, 0, '|TInterfaceIconsspell_shaman_totemrecall.blp:20|t 암흑주술사가 |cFFFF0000|Hspell:144291|h[녹슨 강철 토템]|h|r을 내려놓습니다!'),
(71859, 9, 0, '녹으로 오염된 조각난 대지!'),
(71865, 0, 0, '나, 그롬의 아들 가로쉬가, 헬스크림이라는 이름이 무슨 뜻인지 보여주겠다!'),
(71865, 1, 0, '|TInterface\\Icons\\ability_mage_firestarter.blp:20|t|cFFFF0000공성 기술자|r들이 측면에서 나타나 |cFFFF0000|Hspell:144616|h[강철의 별 작동]|h|r을 시전합니다!'),
(71865, 2, 0, '피바람을 불러 일으키자!'),
(71865, 2, 1, '강철과 불길로 이 세상을 정화해 주마!'),
(71865, 2, 2, '진정한 호드를 위하여!'),
(71865, 3, 0, '션견자, 우리를 치료하라!'),
(71865, 4, 0, '분노. 증오. 공포! 이게 바로 전쟁의 무기다. 대족장이 써야 할 도구다!'),
(71865, 5, 0, '그래... 그래, 이제 보인다... 이 세계의 미래가 보인다... 호드가 지배하는... 나의 호드가 지배하는 세계가...'),
(71865, 6, 0, '이 심장이 널 없앨 것이다!'),
(71865, 7, 0, '내 안에 힘이 넘쳐 흐른다! 으아아!'),
(71865, 8, 0, '|TInterface\\Icons\\ability_garrosh_whirling_corruption.blp:20|t %s|1이;가; |cFFFF0000|Hspell:144985|h[소용돌이치는 타락]|h|r을 시전합니다!'),
(71865, 9, 0, '|TInterface\\Icons\\ability_garrosh_empowered_whirling_corruption.blp:20|t %s|1이;가; |cFFFF0000|Hspell:144985|h[강화된 소용돌이치는 타락]|h|r을 시전합니다!'),
(71865, 10, 0, '이 힘으로 너의 세계와 모든 것을 부숴 주마!'),
(71865, 11, 0, '진정한 호드가 태어날 것이다. 나는 그 모습을 봤다. 그것이 내게 보여줬다. 해골의 산과 피의 강을 분명히 봤다. 이제 나는... 내 세계를... 손에 넣을 것이다!'),
(71865, 12, 0, '하! 명예가 뭔지 기억이나 하나? 전장의 영광은? 인간 따위와 협상이나 하고, 우리 발밑에서 흑마법사들이 어둠의 마법을 주물럭거리게 내버려 두는 너 따위가 그런 걸 알 리가 없지. 넌 약하다.'),
(71865, 13, 0, '우리는 오크 호드, 진정한 호드다. 전쟁터에서 피를 쏟으며 죽을 때까지 발버둥치지. 오크는 그런 존재다.'),
(71865, 14, 0, '너는 이제 오크가 아니다. 네 말을 따를 자도 없어. 넌 부질없는 동맹을 맺는다는 이유로 우리를 배신했다. 내가 기꺼이 그 동맹이란 걸 갈기갈기 찢어 주마.'),
(71865, 15, 0, '멍청하긴. 내 암흑주술사들이 주위의 모든 정령들을 뒤틀고 고문했다. 놈들은 이제 네 말을 듣지 못해. 네가 얼마나 약하고 미천한 존재인지, 다시 한 번 보여주는구나.'),
(71865, 16, 0, '그래, 진정한 오크의 대족장에게 대들겠다는 건가. 멋대로 해 봐라.'),
(71865, 17, 0, '네가 이겼다고 생각하나? 넌 눈이 멀었다! 내가 그 눈을 뜨게해 주마!'),
(71865, 18, 0, '봐라. 내 영광스러운 운명을! 으하하하하!'),
(71865, 19, 0, '|TInterface\\Icons\\ability_warlock_eradication.blp:20|t %s|1이;가; |cFFFF0000$n|r에게 |cFFFF0000|Hspell:147209|h[악의]|h|r를 시전합니다!'),
(71865, 20, 0, '내 세계는 너 따위가 있을 곳이 아니다.'),
(71865, 21, 0, '|TInterface\\Icons\\ability_garrosh_siege_engine.blp:20|t 함대장이 집결한 적을 발견해 |cFFFF0000|Hspell:147047|h[불안정한 강철의 별]|h|r을 발사합니다!'),
(71865, 22, 0, '|TInterface\\Icons\\ability_vehicle_demolisherflamecatapult.blp:20|t 호드 함대가 |cFFFF0000|Hspell:147088|h[폭격]|h|r을 시작합니다!'),
(71865, 23, 0, '네가 사랑했던 모든 것을 박살내 주마!'),
(71869, 0, 0, '적절한 거래인걸. 영혼의 세계에 온 걸 환영해. 상자들을 열어보는 게 어때? 어쩌면 내 몸뚱아리도 있을 거야!'),
(71869, 1, 0, '그녀에게 데이트 신청을 못한 걸 뼈저리게 후회하고 있지.'),
(71869, 1, 1, '귀신은 맞지만 색깔 별로 휴지를 들고 다니지는 않아!'),
(71869, 1, 2, '알고 보면 나도 부드러운 남자야.'),
(71869, 1, 3, '싸움에 잔뼈가 꽤 굵나본데?'),
(71869, 1, 4, '뼈와 살을 분리해주지! 나처럼 말이야!'),
(71869, 1, 5, '다이어트? 그게 뭐야, 먹는 거야? 아하, 안 먹는 거구나!'),
(71869, 1, 6, '방금 나보고 돌머리라고 한 녀석 누구야?! 단단하다고 다 돌은 아니야!'),
(71869, 1, 7, '골수에 맺힌 원한을 이제야 푸는구나!'),
(71869, 1, 8, '속이 텅 빈 기분이야...'),
(71869, 1, 9, '알아, 내 농담들이 재미 없다는 거. 그래도 잘 들어 놔! 내 말 속엔 뼈가 있거든!'),
(71876, 0, 0, '어이, 고깃덩어리! 5분만 나랑 얘기하지 않을래? 다들 도망가기 바쁘더라고!'),
(71889, 0, 0, 'GB-11010 "대재앙"급 방어 시스템 가동. 혹시 우리 이거 허가받았는지 아는 사람?'),
(71889, 1, 0, '"대재앙"급 방어 시스템 준비 완료. 폭파 시작!'),
(71889, 2, 0, '제1 모듈, 시스템 초기화 준비 완료.'),
(71889, 3, 0, '제2 모듈, 시스템 초기화 준비 완료.'),
(71889, 4, 0, '보안 시스템 비활성화. 공성기술자 블랙퓨즈 님 환영합니다.'),
(71889, 5, 0, '녹음되고 있는 건가? 응? 좋아. 고블린 티탄 제어 모듈 시동 중. 물러서라고.'),
(71889, 6, 0, '데이터 확인 중이니까 잠깐 기다려 줄래?'),
(71889, 7, 0, '아, 지금 입력한 코드는 완전히, 완전히 틀려 먹었어.'),
(71952, 0, 0, '자, 시작하자.'),
(71952, 1, 0, '한 번도 겪지 못한 시련을 마주했을 때, 너흰 어떤 희망을 품겠느냐? 너희가 찾는 미래는 무엇이냐?'),
(71952, 2, 0, '너희의 희망은 밝게 빛나고, 역경을 극복하려고 힘을 합치면 더욱 밝게 빛난다. 가장 어두운 곳에서도, 희망이 너희의 길을 밝혀줄 것이다.'),
(71952, 3, 0, '포기하지 마라!'),
(71952, 4, 0, '서로를 믿고, 서로에게 희망을 주어라!'),
(71952, 5, 0, '희망이 없다면 미래는 어둡기만 할 것이다!'),
(71952, 6, 0, '운명을 스스로 만들어라!'),
(71953, 0, 0, '하하! 시험을 시작하자!'),
(71953, 1, 0, '힘. 그것은 단순히 육체적 강함을 넘어서는 무엇이지. 진정한 시련을 마주했을 때, 그냥 힘과 진정한 힘의 차이를 말할 수 있겠느냐?'),
(71953, 2, 0, '너흰 강하다. 너희 생각보다 훨씬. 앞에 놓인 어둠 속으로 들어갈 때 이것을 기억하고, 방패로 삼아라.'),
(71953, 3, 0, '두 배는 강해져서 돌아와라!'),
(71953, 4, 0, '자신의 힘을 믿어라!'),
(71953, 5, 0, '너희에겐 운명을 바꿀 힘이 있다!'),
(71953, 6, 0, '어둠이 주는 힘을 진정한 힘으로 착각하지 마라!'),
(71954, 0, 0, '오늘 자네는 실력을 갈고닦아 스스로를 증명한 조련사를 여럿 상대하게 될 걸세. 자네도 그만한 실력을 보여 줄 수 있을까? 두고 보겠네! 행운을 빌지!'),
(71954, 1, 0, '비바람과 눈보라가 몸을 뒤흔드는 높은 산꼭대기에서, 나무가 말라 죽고 산이 바다로 무너져 내릴 때까지 버틸 수 있겠느냐?'),
(71954, 2, 0, '상상도 할 수 없는 강력한 적들에게 둘러싸여 있는 그런 때에도, 인내가 너희를 굳건히 지탱할 것이다. 다가오는 시간에 이 교훈을 반드시 기억해라.'),
(71954, 3, 0, '견뎌내야 한다!'),
(71954, 4, 0, '비바람이 너흴 흔들고, 눈보라가 너흴 할퀸다.'),
(71954, 5, 0, '너희는 산이다. 시간만이 너흴 흔들 수 있지.'),
(71954, 6, 0, '꿋꿋이 자리를 지켜라. 그래야만 목표를 달성할 수 있으니.'),
(71955, 0, 0, '시험을 시작하자!'),
(71955, 1, 0, '사랑하는 영웅들이여, 진정한 지혜는 너희 안에, 너희가 하는 선택 안에 있단다. 압도적인 어둠과 마주할 때, 너희는 올바른 결정을 내릴 수 있느냐?'),
(71955, 2, 0, '이 시험에서 너희의 지혜가 빛을 발했다. 그 지혜가 어두운 곳에서 항상 너희의 등불이 되길.'),
(71955, 3, 0, '실수를 되새겨 봐라!'),
(71955, 4, 0, '내면의 목소리에 귀를 기울이고, 진실을 찾아라!'),
(71955, 5, 0, '시련 때문에 판단력이 흐려져선 안 된다!'),
(71955, 6, 0, '너희 행동이 어떤 결과를 낳을지 생각해라!'),
(71965, 0, 0, '멈춰라!'),
(71965, 1, 0, '심장의 방에 타락의 존재가 들어갈 수는 없다!'),
(71965, 2, 0, '타락을 정화하고자 하는가?'),
(71965, 3, 0, '지금 이 순간, 이대로 문을 지난다면, 너희는 실패할 것이다. 너희는 모두 자신도 모르게 교만이라는 질병에 오염되고 타락했다.'),
(71965, 4, 0, '모두 많은 업적을 이루고 당당히 이 자리에 섰지만, 이제 너희 몰락이 시작될 것이다.'),
(71965, 5, 0, '타락을 이겨내고 싶다면, 먼저 너희 자신 속의 타락을 정화해야 한다.'),
(71965, 6, 0, '너희 안의 악마를 마주할 준비가 되면 내게 다시 말해라.'),
(71965, 7, 0, '그래, 좋다. 너희 타락을 가두어 둘 공간을 만들겠다.'),
(71965, 8, 0, '내게 너희 가치를 증명한다면, 너희를 보내 주겠다.'),
(71965, 9, 0, '빛이 너희를 씻어 주겠지만, 상냥하지는 않을 거다. 정화에 대비하라!'),
(71965, 10, 0, '너흰 심판을 받아들이고 스스로 가치를 증명해 보였다. 하지만 주의하라, 이 앞에 도사린 것이 너희 영혼을 극한까지 몰아붙일 테니까. 준비가 끝나면 방에 들어가도 좋다.'),
(71965, 11, 0, '타락이 증폭되고 있다. 그 힘이 너무 강해지기 전에 조각들을 모두 정화해야 한다.'),
(71965, 12, 0, '소용이 없었군. 온다. 마음을 굳게 먹고 너희 영혼을 다잡아라.'),
(71965, 13, 0, '빛은 네 더러움을 용납하지 않아!'),
(71967, 0, 0, '너흰 심판을 받아들이고 스스로 가치를 증명해 보였다. 하지만 주의하라, 이 앞에 도사린 것이 너희 영혼을 극한까지 몰아붙일 테니까. 준비가 끝나면 방에 들어가도 좋다.'),
(71967, 1, 0, '타락이 증폭되고 있다. 그 힘이 너무 강해지기 전에 조각들을 모두 정화해야 한다.'),
(71967, 2, 0, '소용이 없었군. 온다. 마음을 굳게 먹고 너희 영혼을 다잡아라.'),
(71967, 3, 0, '저것을... 억제해야... 한다...'),
(71987, 0, 0, '우우우 우우우 우우우우...'),
(71987, 0, 1, '우우 우우우 우...'),
(71987, 0, 2, '우 우우우우 우우우...'),
(71987, 0, 3, '우우 우우우...'),
(72057, 0, 0, '영원한 화로에서 내 자리를 대신해라.'),
(72057, 1, 0, '끝없는... 나의 고통...'),
(72057, 2, 0, '꺼지지 않는 불길...'),
(72057, 3, 0, '나는... 영원히 불탄다...'),
(72057, 4, 0, '영원한 불은 절대로 꺼지지 않는다.'),
(72057, 5, 0, '사라져라.'),
(72057, 6, 0, '내 고통의 일부일 뿐이다.'),
(72057, 7, 0, '녹아내려라.'),
(72057, 8, 0, '불타라!'),
(72057, 9, 0, '끝없는 고통을 느껴라.'),
(72145, 0, 0, '나는 다른 이들처럼 불타지 않을 것이다! 반역자여, 너의 공포인 악마를 맞이해라!'),
(72151, 0, 0, '이제... 조금만... 더...'),
(72151, 1, 0, '이야, 이건 예상치 못했는데!'),
(72191, 0, 0, '드디어 적들이 도착했구나! 파괴전차, 공격!'),
(72192, 0, 0, '으윽... 고맙소...'),
(72192, 1, 0, '내 비록 멍들고 다쳤지만, 속에선 아직도 증오가 끓어오르오.'),
(72192, 2, 0, '난 오크의 손에 수없이 쓰러졌소. 그리고 그만큼 다시 일어서야 했지.'),
(72192, 3, 0, '하지만 더는 아니오.'),
(72192, 4, 0, '날 공격했던 오크놈 하나 당, 천 명의 머리통을 쪼개버릴테니!'),
(72192, 5, 0, '굴욕은 이제 끝이오!'),
(72192, 6, 0, '나, 가몬이 모두를 구할 거요!'),
(72192, 7, 0, '내 도끼를 받아라!'),
(72192, 8, 0, '죗값을 치러라!'),
(72192, 9, 0, '나는 고통의 폭풍이다!'),
(72192, 10, 0, '넌 명예로운 오크다, 나즈그림. 내가 할 일을 용서해다오.'),
(72192, 11, 0, '내 약속하지. 명예로웠던 네 전투는 영영 기억될 것이다. 호드를 위하여.'),
(72218, 0, 0, '안녕하세요. 이번 시험에서 환영과 맞서는 저희를 지켜주십시오. 저, 오토가 당신을 보호하겠습니다.'),
(72218, 1, 0, '환영 둥지가수다! 음파 공격을 조심하십시오!'),
(72218, 2, 0, '철벽같이 방어해 보겠습니다! 하지만 오래는 못 버팁니다.'),
(72218, 3, 0, '새로운 도전이군요. 환영 정복자입니다! 놈들이 격노하면 저를 신속히 치유해 주십시오.'),
(72220, 0, 0, '하하! 모두 훌륭합니다! 친구, 다음 시험을 시작하려면 로툰을 만나보십시오.'),
(72220, 1, 0, '아, 환영 채굴꾼이군요. 날쌘돌이와 저는 예전에 이놈들과 싸워본 적이 있습니다. 조심하십시오. 놈들은 가끔씩 땅을 파고 들어간 뒤 적에게 튀어 올라서 확! 하하!'),
(72228, 0, 0, '너에겐 그를 꺾을 힘이 없다. 넌 너무 약해.'),
(72228, 0, 1, '동료들은 널 짐으로 생각해.'),
(72248, 6, 0, '남쪽 탑으로 통하는 문이 뚫렸습니다!'),
(72248, 7, 0, '전쟁군주 잴라가 |cFFFF0404|h코르크론 파괴전차|h|r에게 탑을 공격하라고 명령합니다!'),
(72248, 10, 0, '플레이어들이 남쪽 탑 대공포를 점령하였습니다!'),
(72248, 11, 0, '북쪽 탑으로 통하는 문이 뚫렸습니다!'),
(72248, 12, 0, '플레이어들이 북쪽 탑 대공포를 점령하였습니다!'),
(72248, 13, 0, '갈라크라스가 맞았습니다!'),
(72248, 14, 0, '%s|1이;가; 탈것에서 떨어졌습니다!'),
(72249, 0, 0, '갈라크라스가 비틀거리지만 폭발로부터 회복합니다!'),
(72249, 1, 0, '갈라크라스가 맞았습니다!'),
(72311, 0, 0, '잘했다! 상륙 부대, 정렬! 보병대, 앞으로!'),
(72311, 1, 0, '그렇소. 정찰병들이 보고하더군. "전쟁군주 잴라." 그녀의 원시비룡만 끌어내리면 나머지 용아귀 부족은 흩어질 것이오.'),
(72311, 2, 0, '탑을 점령하라! 대공포를 돌려 원시비룡에게 화력을 집중하라!'),
(72311, 3, 0, '몇 명은 이곳에서 해안을 지켜야 할 거요.'),
(72311, 4, 0, '나머지도 처치했다! 대포를 발사하라!'),
(72311, 5, 0, '하! 덩치만 큰 녀석이군...'),
(72311, 6, 0, '그가 아직 약속을 기억하는지 지켜봐야겠군.'),
(72356, 1, 0, '명예롭게... 죽는구나... 록타르 오가르...'),
(72357, 0, 0, '내 탑을 차지하겠다고? 하하...'),
(72357, 1, 0, '너희는... 이 전쟁을... 이길 수 없다...'),
(72432, 0, 0, '대족장은 내 조언을 무시했네. 결국 성난불길의 동굴 아래 주둔지를 만들고야 말았지.'),
(72432, 1, 0, '스랄과 사울팽은 먼저 내려갔네.'),
(72432, 2, 0, '조심하게. 가로쉬는 저 밑에 온갖 병기들을 모아놨어. 고블린 용병, 판다렌 유물, 그리고 내 영혼 깊은 곳까지 느껴지는 어두운 무언가까지...'),
(72455, 0, 0, '뭔가 할 말이 있나, 판다렌?'),
(72455, 1, 0, '이 촛불이 보이나? 이게 다 타기 전까지 판다렌 유물에 대해 실토해라. 안 그러면 네놈은 죽은 목숨이다.'),
(72560, 0, 0, '잘 했소. 선봉대가 성공적으로 상륙했군.'),
(72560, 1, 0, '전략을 쓰면 되오, 여군주여. 해안의 수비 시설을 이용하는 거지.'),
(72560, 2, 0, '영웅들이여, 탑으로 가시오. 원시비룡에 화력을 집중해서 놈을 끌어내리시오!'),
(72560, 3, 0, '그대들 중 몇몇은 상륙지를 지키도록.'),
(72560, 4, 0, '잴라가 탑을 공격하고 있소!'),
(72560, 5, 0, '한 놈은 잡았군!'),
(72560, 6, 0, '나도 가끔 내 실력이 놀랍소. 저기 추락하는 용을 보시오!'),
(72560, 7, 0, '끝났군! 이 먼지를 언제 다 털어내지?'),
(72560, 8, 0, '칭찬으로 받아들이지. 일단은 우리는 항구에서 병력을 모으겠소. 그대들은 볼진이 있는 오그리마 정문으로 가시오.'),
(72694, 0, 0, '일에 쾌락을 곁들일 시간이군.'),
(72694, 1, 0, '생산 설비에서 미완성 무기가 나오기 시작합니다.'),
(72694, 2, 0, '이런 젠장!'),
(72694, 3, 0, 'SD-5 자동 분쇄기 방어 장치 가동. 사랑의 산물이지.'),
(72694, 4, 0, '자동 분쇄기가 다가옵니다!'),
(72694, 5, 0, '나의 유산은... 영원할 것이다...'),
(72694, 6, 0, '고로단! 어서 나와!'),
(72694, 7, 0, '좋아, 샤나. 네 차례다.'),
(72694, 8, 0, '흠, 새 조수를 구해야 되겠군.'),
(72694, 9, 0, '거대괴수의 복수다!'),
(72694, 9, 1, '만족한 고객님 추가요.'),
(72694, 10, 0, '내 이쁜이 ST-03 충격파 미사일 포탑을 소개하지!'),
(72694, 11, 0, '그냥 폭탄은 시시하지. 폭탄 안에 폭탄이 두 개!'),
(72694, 12, 0, 'LT-403 증발 광선 맛을 봐라. 내 자랑거리지.'),
(72694, 13, 0, '너희들이 자석의 원리를 알아?'),
(72726, 0, 0, '아, 새로 온 손님들이군. 잘 왔네!'),
(72726, 1, 0, '벌써 가는가? 또 오게나!'),
(72726, 2, 0, '벌써 문을 닫을 때가 됐나? 챠오웨이가 기다리니 집에나 가야겠군.'),
(72726, 3, 0, '맛있는 국수의 비결은 튼튼하고 굵은 면발에서 시작되지!'),
(72726, 4, 0, '국물은 영혼까지 데울 수 있게 모락모락 김이 날 정도로 뜨거워야 한다네!'),
(72779, 0, 0, '<콜록 콜록> 으으으으...'),
(72779, 1, 0, '초 님... 외부인들이... 한 짓입니다... 그들을 받아들이지 말았어야...'),
(72872, 0, 0, '놀랍군! 이 방도 그 "티탄"이라는 존재들이 만든 것 같아!'),
(72872, 1, 0, '역사가 기록되기 전부터 감춰져 있었던 모양이네. 그럴 만도 하지!'),
(72872, 2, 0, '이 앞의 방에는, 우리 평화로운 대지 아래에서 잠자는, 고대 신의 심장이 있네!'),
(72872, 3, 0, '이런! 이건 뭐지? 반갑네! 난 전승지기 초라고 하네!'),
(72872, 4, 0, '타락의 존재라니? 아니, 우리는 타락을 멈추고 판다리아를 구하러 왔네!'),
(72872, 5, 0, '그래! 우릴 보내 주게!'),
(72872, 6, 0, '타란 주!'),
(72872, 7, 0, '아니, 아니, 아무 말도 하지 말게. 내가 치유사들에게 데려다 주겠네.'),
(72872, 8, 0, '내가 도움을 요청하겠네! 어떻게든 샤를 막아내 보게!'),
(72916, 0, 0, '오늘따라 입맛이 마구 당기는걸!'),
(72916, 1, 0, '저들이 린 가문 비밀 재료 국수의 비밀을 발견했다고 하더군.'),
(72964, 0, 0, '넌 이제 끝장이야!'),
(72970, 0, 0, '영겁의 시간 끝에 내가 돌아왔다.'),
(72994, 0, 0, '조심하십시오. 투기장 안으로 떨어지면 안됩니다.'),
(73037, 0, 0, '제발, 내려오세요. 피시 님이 떨어지면 제가 농사꾼 연합에 뭐라고 얘기해야겠어요?'),
(73037, 0, 1, '거기서 떨어지면 전 모르는 일입니다!'),
(73303, 0, 0, '오래전 옥룡은 내게 영혼을 깨끗이 하고 대지와 하나가 되라고 가르쳤네. 그랬더니 내가 품었던 의심이 말끔히 사라졌지.'),
(73303, 1, 0, '내 여정이 시작되었을 때, 나는 힘을 함부로 휘둘렀다네. 백호가 내게 절제를 가르쳤고, 그러자 증오와 분노, 폭력성이 말끔히 사라졌지.'),
(73303, 2, 0, '주학은 내게서 희망을 보고, 내게 내면을 들여다보라고 가르쳤네. 얼굴엔 절망이 가득했음에도 나는 희망을 찾았고, 그러자 절망이 사라졌지.'),
(73303, 3, 0, '내가 크나큰 공포를 마주했을 때 흑우가 내게 인내를 가르쳤네. 그로써 두려움과 어둠을 이겨 냈고, 그러자 공포가 사라졌지.'),
(73303, 4, 0, '자네는 지혜의 시험을 치르고 옥룡의 도를 배웠네. 내가 그랬듯이 자네도 가르침을 얻었기를 바라네.'),
(73303, 5, 0, '자네는 힘의 시험을 치르고 백호의 도를 배웠네. 늘 이 가르침을 기억하기를.'),
(73303, 6, 0, '자네는 희망의 시험을 치르고 주학의 도를 배웠네. 이 가르침이 자네의 발걸음을 이끌기를.'),
(73303, 7, 0, '자네는 인내의 시험을 치르고 흑우의 도를 배웠네. 이 가르침이 자네의 길을 축복하기를.'),
(73303, 8, 0, '자네는 이제부터 특별한 시험을 치를 걸세! 따르는 이들의 기량을 보면 지도자의 지혜를 가늠할 수 있지. 자네의 가르침이 그들에게 진정 감화를 주었는지 보세...'),
(73330, 0, 0, '아, 또 한 번 함께 모험을 하겠군. 안타까운 일이네만, 이번엔 상황이 무척이나 심각한 모양이네.'),
(73330, 1, 0, '대지는 잿빛으로 물들고, 사시사철 무성하던 초목도 시들었네. 이제 호수의 물도 모두 말라 버렸어.'),
(73330, 2, 0, '한때, 티탄은 생명을 주는 이 물로 판다리아의 모든 생명체를 만들고 다듬었어.'),
(73330, 3, 0, '이 골짜기에 꽃을 피운 건 바로 이 물이네. 물은 네 바람의 계곡으로 흘러들어, 이 세계에서 가장 풍요로운 땅을 만들었지.'),
(73330, 4, 0, '허나 지금 이 순간, 고대 신의 끔찍한 종양이 이 물 속에 번지고 있네.'),
(73330, 5, 0, '이토록 끔찍하고 또 끔찍한 존재라니. 파괴하게. 대지로 스며 들어가 판다리아 전체를 타락시키기 전에!'),
(73330, 6, 0, '아, 역시 해냈군! 골짜기의 물이 다시 깨끗해졌네.'),
(73330, 7, 0, '생명을 주는 힘이 자네를 통해 흐르는게 느껴지는가?'),
(73330, 8, 0, '골짜기가 회복되려면 오랜 시간이 필요하겠지만, 자네가 희망을 주었네!'),
(73330, 9, 0, '저건 혹시...? 아, 아니, 안 돼, 안 돼...'),
(73330, 10, 0, '황금 연꽃은... 이 땅을 지키기 위해 그 목숨을 바쳤는데...'),
(73330, 11, 0, '그래! 루크 스톤토! 날 기억하는군! 자네... 어떻게 된 건가?'),
(73330, 12, 0, '이제 알았네. 샤가 그들의 영혼을 여기 가두고, 영원히 실패를 되새기게 하는 모양이야. 저들의 절망으로 배를 채우려는 거지.'),
(73330, 13, 0, '이건 죽음보다 끔찍한 운명이로군. 영웅들이여! 부디 저들의 영혼을 풀어 주게!'),
(73330, 14, 0, '안식을 찾게, 친구들.'),
(73330, 15, 0, '자네들의 영혼이, 그 소중한 목숨을 바쳐 지켜낸 이 땅과 하나가 되길...'),
(73342, 0, 0, '나를 보호해라!'),
(73349, 0, 0, '우리 일이 아직 끝나지 않았다! 놈들을 저지해라!'),
(73435, 0, 0, '용용주 한 번 드셔보시렵니까? 용의 기운이 솟아난다고요!'),
(73435, 0, 1, '먹을 것! 마실 것!'),
(73435, 0, 2, '다른 곳에서는 찾을 수도 없는 요리들입니다. 와서 드셔보세요!'),
(73435, 0, 3, '북부와 남부 요리를 완벽하게 조합한 별미입니다!'),
(73483, 0, 0, '아직 늦지 않았다, 가로쉬. 대족장이라는 짐을 내려놓거라. 지금, 여기서 끝내자. 피를 흘릴 필요는 없다.'),
(73483, 1, 0, '그렇다면 나도 어쩔 수 없구나. 오래 전 저질렀던 실수를 이제는 바로잡아야겠다. 바람과 대지, 물의 정령이여, 내 부름에 답하라! 나를 도와다오!'),
(73483, 2, 0, '가로쉬, 나는 약하지 않고, 혼자도 아니다.'),
(73547, 0, 0, '하하하하하!'),
(73547, 1, 0, '나는 다시 살아났다!'),
(73547, 2, 0, '남쪽바다는 영원히 나의 것이다!'),
(73547, 3, 0, '와라, 바주비어스호여. 심해에서 떠올라라!'),
(73547, 4, 0, '모두 죽여라! 한 놈도 살려두지 마라!'),
(73547, 5, 0, '이럴수가! 바주비어스호는 너 따위에게 무너지지 않는다!'),
(73550, 1, 0, '손은 떨지 말고...'),
(73550, 2, 0, '녹색 줄무늬의 파란 선? 노란 줄무늬의 까만 선? 기억이 나지 않아.'),
(73605, 0, 0, '이걸 보시오! 무기를 두고 갔군.'),
(73605, 1, 0, '놈은 완전히 이성을 상실했소.'),
(73605, 2, 0, '우리도 마찬가지요. 실바나스와 나도 볼진을 돕기 위해 병력을 보냈소.'),
(73605, 3, 0, '역시 그대는 호탕하군, 프라우드무어 여군주.'),
(73618, 0, 0, '거기 자네! 이리 와서 녹옥 맥주 맛 좀 보게나!'),
(73618, 0, 1, '녹옥 맥주! 비취 숲의 정기를 그대로 받았다네!'),
(73618, 0, 2, '그 어떤 술도 녹옥 맥주의 대담한 맛을 능가할 수 없다네!'),
(73647, 0, 0, '이국적이고, 좋은 향기가 가득하다네! 자네의 몸과 영혼을 치유할 약주일세!'),
(73647, 0, 1, '둘도 없는 독특한 맥주를 마셔보게나! 활기와 만족감을 한 번에 느낄 수 있는... 호박석 맥주라네!'),
(73647, 0, 2, '용의 척추에서 공수해온 강렬한 호박석 맥주!'),
(73651, 0, 0, '스톰스타우트 가문이 영원의 섬에 왔습니다!'),
(73651, 0, 1, '아제로스가 최고의 맥주, 스톰스타우트 가문이 만듭니다!'),
(73651, 0, 2, '스톰스타우트라면 더는 설명이 필요 없겠죠?'),
(73651, 0, 3, '시간만 내세요. 맥주는 제가 준비하겠습니다! 스톰스타우트 맥주!'),
(73651, 0, 4, '스톰스타우트가 무슨 뜻이냐고요? 판다렌어로 "맥주"라는 뜻이지요.'),
(73666, 0, 0, '너의 도전에 응하겠다, 외부인이여. 오르도가 불타는 신의 이름으로 이곳을 차지하겠다!'),
(73716, 0, 0, '아, 볼진의 저항군인가. 해냈군.'),
(73716, 1, 0, '스랄은 찾았나? 내가 크게 다치는 바람에 스랄 혼자 갔다네.'),
(73716, 2, 0, '말해보게. 위에서의 전투는 어찌 되었나? 나즈그림은? 어서!'),
(73716, 3, 0, '아, 나즈그림. 위대한 지도자이자 강인한 전사. 그는 대족장에 대한 맹세를 목숨보다 소중히 여겼네.'),
(73716, 4, 0, '말해주려 했네... 헬스크림이 우릴 배신했다고. 호드를 지켜야 하는 대족장의 사명을 저버렸다고. 하지만 나즈그림은... 너무 충직했어... 긍지가 높았지.'),
(73716, 5, 0, '망할 헬스크림. 놈의 야망이 호드를 찢어놨어.'),
(73716, 6, 0, '가게. 스랄을 찾고, 가로쉬를 끝내. 난 괜찮아.'),
(73812, 0, 0, '김 나는 염소 국수! 냄새도 좋답니다!'),
(73812, 0, 1, '국수로 배를 채우러 오세요! 아주 맛있어요!'),
(73812, 0, 2, '아주 맛있는 국수예요! 한 번 드셔보실래요?'),
(73813, 0, 0, '조화로운 강 국수를 드셔보십시오. 결코 실망하지 않으실 겁니다.'),
(73813, 0, 1, '갓 낚은 싱싱한 생선입니다! ...아마 싱싱할 겁니다. 이 섬이 원체 별나긴 하지만요.'),
(73813, 0, 2, '강물 방식 국수입니다. 가장 싱싱한 생선들로 요리했습니다.'),
(73813, 0, 3, '조화로운 강 국수입니다!'),
(73814, 0, 0, '몬몬은 몇 주 동안 국수의 달인한테서 교육받았다.'),
(73814, 0, 1, '여기 좋은 국수 있다!'),
(73814, 0, 2, '국수 사라!'),
(73815, 0, 0, '매콤하고 화끈하게! 야운골 국수를 드셔보십시오!'),
(73815, 0, 1, '대담한 맛! 대담한 열기! 그 어떤 국수도 따라할 수 없습니다!'),
(73815, 0, 2, '밋밋하고 맛도 없는 국수를 왜 드십니까? 야운골 방식을 시도해보세요!'),
(73816, 0, 0, '판다리아 최고의 국수만을 취급한다네!'),
(73816, 0, 1, '내가 자신있게 선보이는 황금용 국수를 한 번 먹어보게나!'),
(73816, 0, 2, '황금용 국수라네! 정말 최고지!'),
(73817, 0, 0, '정말 맛있어요! 행운이 팡팡 터지는 국수랍니다!'),
(73817, 0, 1, '어이, 어이! 어서 오세요, 맛 좋은 국수가 준비됐어요!'),
(73817, 0, 2, '유후! 행운의 버섯 국수 어때요?'),
(73817, 0, 3, '행운이 가득해요! 국수 드시고 가세요!'),
(73859, 0, 0, '지원군을 보내라! 돌진!'),
(73909, 0, 0, '불기둥을 일으키겠소. 놈들을 유인하시오!'),
(73939, 0, 0, '허튼 수작 마라, 볼진! 남은 공성 무기가 없으니, 이 전투를 이길 순 없어!'),
(73939, 1, 0, '내 전쟁 병기를 파괴했을진 몰라도, 아직 성문은 멀쩡하다. 오그리마를 포기해!'),
(73939, 2, 0, '뭐지? 코르크론이여! 성문으로! 어서!'),
(73941, 0, 0, '우리 쪽 피해가 너무 심합니다!'),
(73941, 1, 0, '흠, 아마 새 지원군이 우릴 도와줄 겁니다.'),
(73941, 2, 0, '아직 희망의 불씨가 살아 있었군요.'),
(73941, 3, 0, '당신에게 대지모신께서 축복을 내려주시기를.'),
(73942, 0, 0, '다른 방법이 없네, 친구. 지금 가로쉬를 막지 못하면 우린 평생 도망자 신세가 될 거야.'),
(73942, 1, 0, '말 그대로 영웅들이로군.'),
(73942, 2, 0, '괴물을 쓰러뜨렸다!'),
(73942, 3, 0, '티란데...'),
(74158, 0, 0, '아무래도 말코록이 침입자들을 모두 찢어버린 것 같군.'),
(74158, 1, 0, '모르겠어. 느낌이 안 좋아. 너무 조용하단 말이지.');

UPDATE `creature_text_locale` AS `l`
INNER JOIN `_koKR_stage_creature_text_locale` AS `s` ON `l`.`CreatureID` = `s`.`CreatureID` AND `l`.`GroupID` = `s`.`GroupID` AND `l`.`ID` = `s`.`ID` AND `l`.`Locale` = 'koKR'
INNER JOIN `creature_text` AS `p` ON `p`.`CreatureID` = `s`.`CreatureID` AND `p`.`GroupID` = `s`.`GroupID` AND `p`.`ID` = `s`.`ID`
SET `l`.`Text` = IF(`s`.`Text` IS NOT NULL AND (`l`.`Text` IS NULL OR `l`.`Text` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`Text`, `l`.`Text`);

INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`)
SELECT `s`.`CreatureID`, `s`.`GroupID`, `s`.`ID`, 'koKR', `s`.`Text`
FROM `_koKR_stage_creature_text_locale` AS `s`
INNER JOIN `creature_text` AS `p` ON `p`.`CreatureID` = `s`.`CreatureID` AND `p`.`GroupID` = `s`.`GroupID` AND `p`.`ID` = `s`.`ID`
LEFT JOIN `creature_text_locale` AS `l` ON `l`.`CreatureID` = `s`.`CreatureID` AND `l`.`GroupID` = `s`.`GroupID` AND `l`.`ID` = `s`.`ID`
WHERE `l`.`CreatureID` IS NULL;

DROP TEMPORARY TABLE `_koKR_stage_creature_text_locale`;
